# --- fonts and measuring -------------------------------------------------------

"How a run of text is drawn. A chip is the box behind `code`."
struct Face
  family::String
  style::String
  size::px
  color::Colorant
  chip::Bool
  lang::String    # the language of code whose parts each get a colour, or "" for text in one colour
  highlit::Bool   # true for ==words==, which have a highlighter's colour behind them
end

Face(family, style, size, color, chip, lang="") = Face(family, style, size, color, chip, lang, false)
Face(f::Face; style=f.style, size=f.size, color=f.color, family=f.family, chip=f.chip, lang=f.lang, highlit=f.highlit) =
  Face(family, style, size, color, chip, lang, highlit)

const measured = Dict{Tuple{String,String,Float32,String},px}()

"""
How wide `s` is in `face`. It's kept, because the same words are measured every
frame. A character that the font lacks is as wide as it is in the font that
draws it (see `runs`), not as wide as the empty box that would stand for it.
"""
measure(face::Face, s::AbstractString) = begin
  isempty(s) && return 0px
  length(measured) > 200_000 && empty!(measured)
  get!(measured, (face.family, face.style, Float32(num(face.size)), String(s))) do
    hasall(face, s) ? width_in(face, s) : sum(((t, f),) -> width_in(f, t), runs(s, face))
  end
end

"How wide `s` is in the font of `face`, with no other font for the characters that it lacks"
width_in(face::Face, s::AbstractString) = px(measure_text(skia_font(face.family, face.size, face.style), s)[1])

# --- a line laid out ---------------------------------------------------------------
#
# A line of the document can wrap into several lines on screen. A Flow says
# where each run of its text goes, so the same numbers place the text, the
# caret and the selection, and turn a click back into a column.

"The node that a piece of inline code made, with the room it takes in its line"
struct Inline
  node::Any      # a Shown
  w::px
  h::px
end

"A run of a line's text before it's wrapped"
struct Piece
  text::String
  col::Int       # the column of its first character
  n::Int         # how many characters of the line it stands for
  face::Face
  atomic::Bool   # true when `text` isn't the line's own text, like a • for a -
  link::String
  node::Union{Nothing,Inline}   # what's drawn in place of the text, for inline code that made a node
  words::Bool    # true for the text that inline code made, whose words can go onto different lines
end

"A run of text placed on one line of the screen"
struct Seg
  text::String
  col::Int
  n::Int
  face::Face
  atomic::Bool
  link::String
  x::px          # from the left edge of the page's text
  w::px
  node::Union{Nothing,Inline}
end

"One line on screen"
struct VLine
  segs::Vector{Seg}
  x::px          # where its text starts
  from::Int      # the columns it covers
  to::Int
  top::px        # how far it is under the first line
  high::px       # a line with a tall node in it is taller than the others
end

struct Flow
  lines::Vector{VLine}
  lh::px         # the height of a line on screen that has only text
  size::px       # the font size, which sets the caret's height
  above::px
  below::px
  kind::Kind
  raw::Bool      # true when the markup characters are showing
end

tall(f::Flow) = f.above + sum(vl -> vl.high, f.lines, init=0px) + f.below

"How far screen line `k` of `f` is under the top of `f`"
line_top(f::Flow, k::Int) = f.above + f.lines[k].top

"The screen line of `f` that's `dy` under the top of `f`"
line_at(f::Flow, dy::px) = something(findlast(vl -> f.above + vl.top <= dy, f.lines), 1)

const INLINE_GAP = 4px   # the least room above and below a node in a line of text, in all

"Wrap `pieces` to `limit`. Lines start at `left`, and all but the first at `hang`."
wrap(pieces, limit::px; lh, size, left=0px, hang=left, above=0px, below=0px, kind=Kind.paragraph, raw=false) = begin
  lines = VLine[]
  segs = Seg[]
  # `flush!` and `add!` change these. A variable that a closure assigns to is
  # boxed, and Julia looks at its type again each time it's used: that was a
  # sixth of the time a page took to describe. A `Ref` keeps its type.
  x, start, top = Ref(left), Ref(left), Ref(0px)
  flush!() = begin
    from = isempty(segs) ? (isempty(lines) ? 0 : last(lines).to) : first(segs).col
    to = isempty(segs) ? from : last(segs).col + last(segs).n
    high = max(lh, maximum(s -> s.node === nothing ? 0px : s.node.h + INLINE_GAP, segs, init=0px))
    # The line keeps a copy, and `segs` starts the next line empty
    push!(lines, VLine(copy(segs), start[], from, to, top[], high))
    top[] += high
    empty!(segs)
    x[] = start[] = hang
  end
  # Add `text`, which is `n` characters from `col`, to the line being built
  add!(p::Piece, text, col, n) = begin
    pad = p.face.chip ? 2(CHIP_X + 1px) : 0px
    if !isempty(segs) && !p.atomic && !last(segs).atomic && last(segs).col + last(segs).n == col && last(segs).face === p.face && last(segs).link == p.link
      s = pop!(segs)
      joined = s.text * text
      push!(segs, Seg(joined, s.col, s.n + n, s.face, false, s.link, s.x, measure(s.face, joined) + pad, nothing))
      x[] = s.x + last(segs).w
    else
      w = p.node === nothing ? measure(p.face, text) + pad : p.node.w
      push!(segs, Seg(text, col, n, p.face, p.atomic, p.link, x[], w, p.node))
      x[] += w
    end
  end
  # Cut the pieces into words, each with the spaces after it. A node that inline code made is one word. The text that
  # it made is cut into words too, and its first word stands for all of the code, so that a click on it finds the code.
  words = Tuple{Piece,String,Int,Int}[]
  for p in pieces
    if p.words
      for (k, m) in enumerate(eachmatch(r"\S+\s*|\s+", p.text))
        push!(words, (p, String(m.match), k == 1 ? p.col : p.col + p.n, k == 1 ? p.n : 0))
      end
      continue
    elseif p.atomic
      push!(words, (p, p.text, p.col, p.n))
      continue
    end
    col = p.col
    for m in eachmatch(r"\S+\s*|\s+", p.text)
      n = length(m.match)
      push!(words, (p, String(m.match), col, n))
      col += n
    end
  end
  # How far a word reaches past where it starts. A `code` chip has room inside it on each side.
  # Spaces at the end of a line may hang past the edge, but the spaces in a chip are inside it.
  reach((p, text, col, n), last) =
    p.node !== nothing ? p.node.w :
    p.words ? measure(p.face, last ? rstrip(text) : text) :
    p.atomic ? measure(p.face, text) :
    p.face.chip ? measure(p.face, text) + (col == p.col ? 2(CHIP_X + 1px) : 0px) :
    measure(p.face, last ? rstrip(text) : text)
  i = 1
  while i <= length(words)
    # Words with no space between them go onto a line together, like a `code` chip and the comma after it
    j = i
    while j < length(words) && !endswith(words[j][2], r"\s") && !startswith(words[j+1][2], r"\s")
      j += 1
    end
    stop = j   # the closure below sees this, which is never assigned again, so it isn't boxed as `j` would be
    w = sum(k -> reach(words[k], k == stop), i:stop)
    if w <= limit - hang
      x[] + w > limit && x[] > start[] && flush!()
      foreach(k -> add!(words[k][1], words[k][2:4]...), i:stop)
    else
      # Words that are too wide for a whole line together break where they must
      for k in i:stop
        x[] + reach(words[k], k == stop) > limit && x[] > start[] && flush!()
        add!(words[k][1], words[k][2:4]...)
      end
    end
    i = stop + 1
  end
  flush!()
  Flow(lines, lh, size, above, below, kind, raw)
end

"""
How far into `seg` the gap after its first `k` characters is. In a `code` chip the text
is inside the chip's padding, so even the gaps at its two ends are inside the chip.
"""
inset(seg::Seg, k::Int) = begin
  seg.atomic && return k <= 0 ? 0px : seg.w
  pad = seg.face.chip ? CHIP_X + 1px : 0px
  k <= 0 && return pad
  k >= seg.n && return seg.w - pad
  pad + measure(seg.face, first(seg.text, k))
end

"""
True when `seg` is one of the words after the first of the text that inline
code made. Those take none of the line's columns: the first word stands for
all of the code. See `wrap`.
"""
later_word(seg::Seg) = seg.atomic && seg.n == 0

"Where segment `i` of `vl` ends, with the words of the same inline code that come after it"
words_end(vl::VLine, i::Int) = begin
  at = vl.segs[i].col + vl.segs[i].n
  while i < length(vl.segs) && later_word(vl.segs[i+1]) && vl.segs[i+1].col == at
    i += 1
  end
  vl.segs[i].x + vl.segs[i].w
end

"Where column `col` is on the screen line `vl`"
xcol(vl::VLine, col::Int) = begin
  for (i, seg) in enumerate(vl.segs)
    col < seg.col && return seg.x
    # The end of inline code is after the last word of its text. A line can start with the last of them.
    later_word(seg) && col == seg.col && return words_end(vl, i)
    col == seg.col && return seg.x + inset(seg, 0)
    if col <= seg.col + seg.n
      # The gap before a `code` chip is the start of its code, so the caret shows inside the chip
      i < length(vl.segs) && col == seg.col + seg.n && (next = vl.segs[i+1]).face.chip && next.col == col &&
        return next.x + inset(next, 0)
      seg.atomic && col == seg.col + seg.n && return words_end(vl, i)
      return seg.x + inset(seg, col - seg.col)
    end
  end
  isempty(vl.segs) ? vl.x : last(vl.segs).x + last(vl.segs).w
end

"The screen line that column `col` is on, and where it is on that line"
spot(f::Flow, col::Int) = begin
  for (k, vl) in enumerate(f.lines), seg in vl.segs
    col < seg.col + seg.n && return (k, xcol(vl, col))
  end
  (length(f.lines), xcol(last(f.lines), col))
end

"The column nearest to `x` on screen line `k`"
colat(f::Flow, k::Int, x::px) = begin
  vl = f.lines[k]
  isempty(vl.segs) && return vl.from
  col = vl.to
  for (i, seg) in enumerate(vl.segs)
    (x < seg.x + seg.w || i == length(vl.segs)) || continue
    if seg.atomic
      col = x < seg.x + seg.w/2 ? seg.col : seg.col + seg.n
    else
      col = seg.col + seg.n
      for c in 1:seg.n
        if x < seg.x + (inset(seg, c - 1) + inset(seg, c))/2
          col = seg.col + c - 1
          break
        end
      end
    end
    break
  end
  # The end of a wrapped line is the start of the next one, so stop a character short
  k < length(f.lines) && col >= vl.to ? max(vl.from, vl.to - 1) : col
end

# --- the document ----------------------------------------------------------------

const Pos = Tuple{Int,Int}   # a line, from 1, and a column, from 0

"An open file"
Base.@kwdef mutable struct Buffer
  path::String = ""
  lines::Vector{String} = [""]
  caret::Pos = (1, 0)
  anchor::Pos = (1, 0)                  # where the selection starts. The caret is its other end.
  # The other selections, when there are several at once: where each starts, and its caret. See `others`.
  others::Vector{Tuple{Pos,Pos}} = Tuple{Pos,Pos}[]
  others_for::Tuple{Pos,Pos,Int} = ((1, 0), (1, 0), -1)   # the anchor, the caret and the version that `others` goes with
  many::Bool = false                    # true while something is done at each selection in turn
  undo::Vector{Any} = Any[]
  redo::Vector{Any} = Any[]
  version::Int = 0                      # changes with every edit
  saved::Int = 0                        # the version that's in the file
  typed::Float64 = 0.0                  # when a character was last typed, to undo words not letters
  offset::px = 0px                      # how far it's scrolled
  across::px = 0px                      # how far it's scrolled to the right, in a file of code whose long lines don't wrap
  kinds::Vector{Line} = Line[]
  kinds_at::Int = -1
  # After Escape the caret is hidden, until a click puts the caret back
  reading::Bool = false
  # True while the page is written as plain text: the part with the caret shows its markup. The window sets it from its setting.
  plain::Bool = false
  # The part of the page that the caret is on as a whole, and the text, caret and so on that it was worked out for. See `picked`.
  picked::Union{Nothing,Tuple{Int,Int}} = nothing
  picked_for::Tuple{Int,Pos,Pos,Bool,Bool} = (-1, (0, 0), (0, 0), false, false)
  # Where the caret was when the page last looked at where it is, or nothing before the first look. See `stand!`.
  stood::Union{Nothing,Pos} = nothing
  # How the file shows. A Markdown file is a document that you change, and :code is a file of
  # code that you change, which is one block of code. Any other file is only shown: :text shows
  # its text, :hex shows its bytes in hexadecimal, :bits shows them as bits, and :file shows a viewer of its kind.
  view::Symbol = :markdown
  # The language of a file of code that has no file, like Julia for a field of code. "" takes it from the file's name.
  lang::String = ""
  # True for a page that's read, and never changed or written: an email, or a file that the Mac marks as
  # read-only. The lines of an email are the email as a page, which mail.jl makes from the file: the file
  # holds the email as the server sent it.
  fixed::Bool = false
  about::String = ""                    # what the top bar says of a file that's only shown, like how much of it shows
  disk::Vector{String} = [""]           # the file's text as it was last read or written
  # The text as an agent last knew it: what you last sent it, with every change that was made to the file from outside since
  told::Vector{String} = [""]
  sent::Vector{String} = [""]           # the text as it was when you last sent it to an agent, or when the file was opened
end

"True when the file is only shown. Ladder changes Markdown files and the files of code in `CODE_FILES`, and no others."
readonly(b::Buffer) = !(b.view in (:markdown, :code))

"""
True when Ladder shows the file at `path` as a page and never changes it: the
file is an email, or the Mac marks it as read-only. Ladder marks each email
that it keeps, and a mark that you put on a page of your own counts the same.
"""
protected(path) = Eml.isemail(path) || (isfile(path) && !iswritable(path))

"True when `path` is the address of a page on a web server, like https://example.com/notes.md, and not a file on the Mac. See \"a page from a web server\"."
isremote(path::AbstractString) = Remote.isaddress(path)

"""
True when somebody else wrote the page at `path`: it's a page from a web
server, a copy of one, or an email. Ladder runs no code of such a page. A
block that would run code, like a `ui` block or a sum in a line of text,
shows as its code. See "a copy of a page from a web server".
"""
foreign(path::AbstractString) = isremote(path) || Eml.isemail(path) || !isempty(copied_from(path))

"True when the page shows no caret and no key changes it: after Escape, and all the time in a page that's never changed"
caretless(b::Buffer) = b.reading || b.fixed

const stamp = Ref(0)

load(path) = begin
  READ[path] = mtime(path)
  Eml.isemail(path) && return load_email(path)
  code = !ismarkdown(path) && iscode(path)
  ismarkdown(path) || code || return look(path)
  lines = text(path)
  b = Buffer(path=path, lines=lines, disk=copy(lines), told=copy(lines), view=code ? :code : :markdown, fixed=protected(path))
  b.sent = b.told   # nothing has changed from outside yet
  code && return b
  # The caret starts at the text, after any front matter, so the front matter shows as a card
  t = front_matter(b.lines)
  if t > 0
    i = something(findnext(l -> !isempty(strip(l)), b.lines, t + 1), min(t + 1, length(b.lines)))
    b.caret = b.anchor = (i, 0)
  end
  b
end
text(path) = String.(split(replace(read(path, String), "\r\n" => "\n"), '\n'))

"""
The email file at `path`, as a page that's read and not changed: who it's from
and its subject at the top, then its text. A file that isn't an email after
all shows as any other file does.
"""
load_email(path) = begin
  lines = try Eml.render(path) catch; return look(path) end
  b = Buffer(path=path, lines=lines, disk=copy(lines), told=copy(lines), fixed=true)
  b.sent = b.told
  t = front_matter(b.lines)
  i = something(findnext(l -> !isempty(strip(l)), b.lines, t + 1), min(t + 1, length(b.lines)))
  b.caret = b.anchor = (i, 0)
  b
end

const READ = Dict{String,Float64}()   # when each open file was last read or written, as the disk tells it

"""
Read the file again if something else changed it on the disk, like an agent
that's working on the page with you. A document with changes that aren't saved
keeps them, and gets the file's changes too. Where both changed the same lines,
the document keeps its own. Returns the lines of the document that changed, as
`changes` gives them, or nothing.
"""
refresh!(b::Buffer) = begin
  (isempty(b.path) || !isfile(b.path)) && return
  # The Mac's mark can go on a file, or come off it, while the file is open
  if b.fixed != protected(b.path)
    b.fixed = !b.fixed
    b.picked_for = (-1, (0, 0), (0, 0), false, false)
  end
  at = mtime(b.path)
  at == get(READ, b.path, 0.0) && return
  READ[b.path] = at
  unsaved = false
  if readonly(b)
    # A file that's only shown is read again as it was shown: as bytes, or as its kind of file. A JSON file that
    # shows its text goes on showing its text.
    new = look(b.path, b.view)
    b.view, b.about = new.view, new.about
    lines = new.lines
  else
    theirs = Eml.isemail(b.path) ? (try Eml.render(b.path) catch; b.disk end) : text(b.path)
    theirs == b.disk && return
    # An agent knows the changes it made to the file, and none of yours until you send them
    b.told = combine(b.disk, b.told, theirs, keep=:theirs)
    lines = dirty(b) ? combine(b.disk, b.lines, theirs) : theirs
    b.disk = theirs
    unsaved = lines != theirs
  end
  moved = changes(b.lines, lines)
  if !isempty(moved)
    b.lines = lines
    empty!(b.undo); empty!(b.redo)
    b.version = (stamp[] += 1)
    # The caret stays on its line, wherever that line is now
    place(p) = (i = clamp(follow(moved, p[1]), 1, length(lines)); (i, clamp(p[2], 0, length(lines[i]))))
    b.caret, b.anchor = place(b.caret), place(b.anchor)
  end
  unsaved || (b.saved = b.version)
  isempty(moved) ? nothing : moved
end

"The language of the file at `path`: the end of its name, like jl, or its whole name when it has no end, like makefile"
file_lang(path) = (ext = lowercase(splitext(path)[2]); isempty(ext) ? lowercase(basename(path)) : String(lstrip(ext, '.')))

kinds(b::Buffer) = begin
  if b.kinds_at != b.version && b.view != :markdown
    # Each line of a file that isn't Markdown is a line of code, in the language that the file's name gives
    lang = b.view == :hex ? HEX : b.view == :bits ? BITS : isempty(b.lang) ? file_lang(b.path) : b.lang
    b.kinds = fill(Line(Kind.code, 0, 0, lang), length(b.lines))
    b.kinds_at = b.version
  elseif b.kinds_at != b.version
    b.kinds = classify(b.lines)
    # A page from a web server, and an email, show the code of a block that would run code or read the Mac's files
    foreign(b.path) && shown_only!(b.kinds)
    b.kinds_at = b.version
  end
  b.kinds
end

# --- strings in three quotes ---------------------------------------------------------------
#
# A string in three quotes, like a docstring, can run over several lines. The
# lines inside it are all the colour of a string, though they have words like
# for and end. Each line is coloured by itself, so the page keeps the quote of
# the string that's open at the start of each line: see `string_opens`.

"For the lines `lines` and their kinds `kinds`, of the version `version` of the file at `path` as `view` shows it: `at[i]` is the quote of a string in three quotes that's open at the start of line i, or '\\0'"
struct Opens
  path::String
  view::Symbol
  version::Int
  lines::Vector{String}
  kinds::Vector{Line}
  at::Vector{Char}
end

const OPENS = WeakKeyDict{Buffer,Opens}()

"What a string in three quotes is at the end of `text`, a line of the kind `line` that starts with `open` open: see `left_open`"
leaves_open(text::String, line::Line, open::Char) = line.kind == Kind.code ? left_open(text, shared_lang(line.lang), open) : '\0'

"""
For each line of `b`, the quote of a string in three quotes that's open at the
start of the line, like the middle of a docstring, or '\\0'. A code block of a
page starts with none open. After a change, it's worked out again from the
first line that changed, until a line after the change starts as it did before.
"""
string_opens(b::Buffer) = begin
  kept = get(OPENS, b, nothing)
  kept !== nothing && kept.version == b.version && kept.path == b.path && kept.view == b.view && return kept.at
  # What was worked out for another file, or for another view of this one, is no help
  kept !== nothing && (kept.path != b.path || kept.view != b.view) && (kept = nothing)
  lines, ks = b.lines, kinds(b)
  n = length(lines)
  at = fill('\0', n)
  was, before, wks = kept === nothing ? (Char[], String[], Line[]) : (kept.at, kept.lines, kept.kinds)
  m = length(before)
  head, tail = unchanged(lines, before)
  # A line can change its kind though its text didn't, as when a ``` above it opens a code block
  if b.view == :markdown
    k = findfirst(k -> ks[k] != wks[k], 1:head)
    k === nothing || (head = k - 1)
    tail = min(tail, something(findfirst(k -> ks[n-k+1] != wks[m-k+1], 1:tail), tail + 1) - 1)
  elseif n > 0 && m > 0 && ks[1] != wks[1]
    head = tail = 0
  end
  copyto!(at, 1, was, 1, head)
  q = head == 0 ? '\0' : leaves_open(lines[head], ks[head], at[head])
  for i in head+1:n
    j = i - n + m
    # The rest of the lines are as they were, and so are the strings in them
    if i > n - tail && q == was[j]
      copyto!(at, i, was, j, n - i + 1)
      break
    end
    at[i] = q
    q = leaves_open(lines[i], ks[i], q)
  end
  OPENS[b] = Opens(b.path, b.view, b.version, copy(lines), ks, at)
  at
end

"True when the `n` characters of `a` from `i` are the ones of `b` from `j`. It compares them as memory, which is quick for the lines of a long file."
same_chars(a::Vector{Char}, i::Int, b::Vector{Char}, j::Int, n::Int) =
  n <= 0 || GC.@preserve a b ccall(:memcmp, Cint, (Ptr{Char}, Ptr{Char}, Csize_t), pointer(a, i), pointer(b, j), n * sizeof(Char)) == 0

"The quote of a string in three quotes that's open at the start of line `i` of the page `b`, when `text` is that line, or '\\0'"
string_open(b::Buffer, i::Int, text::AbstractString) =
  1 <= i <= length(b.lines) && same_text(b.lines[i], String(text)) ? string_opens(b)[i] : '\0'

dirty(b::Buffer) = b.version != b.saved
name(b::Buffer) = isempty(b.path) ? "Untitled" : isremote(b.path) ? Remote.label(b.path) : basename(b.path)
selecting(b::Buffer) = b.caret != b.anchor
"""
The two ends of the selection, first end first. A selection that covers several
lines takes the whole of each row of a table or a sheet that it touches.
"""
selection(b::Buffer) = begin
  lo, hi = minmax(b.caret, b.anchor)
  (lo[1] == hi[1] || readonly(b)) && return (lo, hi)
  ks = kinds(b)
  (ks[lo[1]].kind == Kind.table || insheet(b, lo[1]) || inspread(b, lo[1])) && (lo = (lo[1], 0))
  (ks[hi[1]].kind == Kind.table || insheet(b, hi[1]) || inspread(b, hi[1])) && (hi = (hi[1], length(b.lines[hi[1]])))
  (lo, hi)
end

head(s, n) = String(first(s, n))
rest(s, n) = String(chop(s, head=n, tail=0))

"The text from `lo` to `hi`"
excerpt(b::Buffer, lo::Pos, hi::Pos) = begin
  lo[1] == hi[1] && return rest(head(b.lines[lo[1]], hi[2]), lo[2])
  join([rest(b.lines[lo[1]], lo[2]); b.lines[lo[1]+1:hi[1]-1]; head(b.lines[hi[1]], hi[2])], "\n")
end

"""
The other selections, when there are several at once. ⌘D on a word that's
selected adds the next place that has the word. What's typed then goes in at
each of them. They last until the caret moves, or the text changes, in a way
that isn't done at each of them: a click, ↑, undo, a change from outside.
"""
others(b::Buffer) = begin
  isempty(b.others) && return b.others
  (b.many || b.others_for == (b.anchor, b.caret, b.version)) || empty!(b.others)
  b.others
end

"Keep the other selections with the caret where it is now"
keep_others!(b::Buffer) = (b.others_for = (b.anchor, b.caret, b.version); b)

"True when two selections share some text, or start at the same place"
clash(s, t) = begin
  (a, b), (c, d) = minmax(s...), minmax(t...)
  a == c || (a < d && c < b)
end

"Where `p` is after the text from `lo` to `hi` was replaced by text that ends at `stop`"
moved(p::Pos, lo::Pos, hi::Pos, stop::Pos) =
  p <= lo ? p : p < hi ? stop : p[1] == hi[1] ? (stop[1], stop[2] + p[2] - hi[2]) : (p[1] + stop[1] - hi[1], p[2])

snapshot(b::Buffer) = (copy(b.lines), b.caret, b.anchor, b.version, copy(others(b)))

restore!(b::Buffer, (lines, caret, anchor, version, rest)) = begin
  b.lines, b.caret, b.anchor, b.version, b.others = lines, caret, anchor, version, copy(rest)
  keep_others!(b)
  b.typed = 0.0
end

"Replace the text from `lo` to `hi` with `new`, and put the caret after it"
edit!(b::Buffer, lo::Pos, hi::Pos, new::AbstractString; typing=false) = begin
  (readonly(b) || b.fixed) && return b   # nothing changes a file that's only shown, an email, or a file that's read-only
  # Letters typed one after another undo together
  if !(typing && time() - b.typed < 1 && !isempty(b.undo))
    push!(b.undo, snapshot(b))
    # Each step back keeps a list of the file's lines, so a long file keeps fewer steps: 500 for a
    # file of 16,000 lines or less, 228 for one of 35,000 lines, and never less than 20
    while length(b.undo) > clamp(8_000_000 ÷ max(length(b.lines), 1), 20, 500)
      popfirst!(b.undo)
    end
  end
  empty!(b.redo)
  b.typed = typing ? time() : 0.0
  joined = head(b.lines[lo[1]], lo[2]) * new * rest(b.lines[hi[1]], hi[2])
  splice!(b.lines, lo[1]:hi[1], String.(split(joined, '\n')))
  parts = split(new, '\n')
  stop = (lo[1] + length(parts) - 1, length(parts) == 1 ? lo[2] + length(new) : length(last(parts)))
  b.caret = b.anchor = stop
  # Each of the other selections stays with its own text
  isempty(b.others) || map!(((a, c),) -> (moved(a, lo, hi, stop), moved(c, lo, hi, stop)), b.others, b.others)
  b.version = (stamp[] += 1)
  b
end

undo!(b::Buffer) = isempty(b.undo) || (push!(b.redo, snapshot(b)); restore!(b, pop!(b.undo)))
redo!(b::Buffer) = isempty(b.redo) || (push!(b.undo, snapshot(b)); restore!(b, pop!(b.redo)))

"""
True when the lines of `b` are what its file holds, so they can be written to
it. The lines of a file that's only shown can be a part of the file, or its
bytes. The lines of an email are the email as a page, which isn't what its file holds.
"""
writes(b::Buffer) = !(isempty(b.path) || readonly(b) || b.fixed || Eml.isemail(b.path))

save!(b::Buffer) = begin
  writes(b) || return
  refresh!(b)   # a change that something else made to the file a moment ago is kept
  write(b.path, join(b.lines, "\n"))
  READ[b.path] = mtime(b.path)
  b.disk = copy(b.lines)
  b.saved = b.version
end

# --- the app -------------------------------------------------------------------------

"One block of the page: a line of the document, or a table drawn as a table"
struct Item
  first::Int     # the lines of the document it shows
  last::Int
  top::px        # from the top of the page's text
  tall::px
  content::Any   # a Flow, a Grid or a Live
end

"What a `ui` code block made when its code ran, and how tall that is on the page"
struct Live
  node::Any      # a SemanticUI or a GeometricUI
  tall::px
end

"A table laid out"
struct Grid
  rows::Vector{Int}            # the line of the document each row comes from
  widths::Vector{px}
  heights::Vector{px}
  cells::Vector{Vector{Cell}}  # where each cell's text is in its line
  flows::Vector{Vector{Flow}}  # one for each column, even where a row has no cell
  # A spreadsheet is laid out as a table is, with a row of letters over it and a column of numbers on its left
  head::px                     # how tall the row of letters is, with the line under it. A table has none.
  left::px                     # how wide the column of numbers is, with the line beside it
  values::Vector{Vector{Value}}   # what each cell of a spreadsheet comes to
end

Grid(rows, widths, heights, cells, flows) = Grid(rows, widths, heights, cells, flows, 0px, 0px, Vector{Value}[])

"True when `g` is a spreadsheet, not a table"
isspread(g::Grid) = g.head > 0px

"""
Where one caret is drawn while it moves to a new place. A place is how far the
caret's left and top are from the top left of the page's text, and its height,
so it stays the same while the page scrolls.
"""
mutable struct Glide
  from::NTuple{3,Float64}   # the place it left
  to::NTuple{3,Float64}     # the place it's going to
  left_at::Float64          # when it left
  buf::UInt                 # the page it's on
  key::Tuple{Pos,Int}       # where the caret was in the text when it left, and the version of the text
end

@def mutable struct Editor <: SemanticUI
  buf::Buffer = Buffer()
  buffers::Dict{String,Buffer} = Dict{String,Buffer}()
  back::Vector{String} = String[]       # the files that showed before this one, with the one just before it last. See `go_back!`.
  ahead::Vector{String} = String[]      # the files that going back left, with the one that was left last at the end
  folder::String = ""
  files::Vector{String} = String[]      # the Markdown files in the folder
  listed::Vector{String} = String[]     # the folders and files in the folder, as the sidebar lists them
  entries::Dict{String,FSObject} = Dict{String,FSObject}()   # the object in the file system of the folder and of each one listed, by its path
  panel::Bool = false                   # is the sidebar showing?
  slid::Float64 = 0.0                   # when the sidebar last started to slide in or out
  slid_from::Float64 = 0.0              # how far open it was then, from 0 to 1
  full_screen::Bool = false             # does the window fill a screen of its own? macOS hides its close, minimise and zoom buttons then.
  screened::Float64 = 0.0               # when the window last started or stopped filling its screen
  screened_from::Float64 = 0.0          # how far the top bar's buttons had slid into the room of the close, minimise and zoom buttons then, from 0 to 1
  side::px = PANEL_W                    # how wide the sidebar is. Drag its right edge to change it.
  hidden::Bool = false                  # the sidebar lists the hidden files and folders too: the ones whose names start with a dot
  right::Bool = true                    # a page that has a panel at the right shows it, as a repository's page has git's panel. See `page_side`.
  own::Bool = false                     # you write the message of each commit, and the agent doesn't. See "an agent writes the commit's message".
  pinned::Bool = false                  # a click on the file's name pinned the path in the top bar open. See "the path in the top bar".
  theme::Symbol = :sepia
  look::Symbol = :own                   # :site on a page of a blog, which looks as the blog's site does. See `page_look`.
  applied::Symbol = :none               # the theme the window was last told about
  font::String = SERIF                  # of the page's text
  weight::Int = 400                     # how heavy the page's text is: the Mac's number for a weight, like 300 for Light. 400 is Regular.
  zoom::Float64 = 1.0
  remember::Bool = false                # write the settings to a file when they change
  settings::Bool = false                # this window opened to show the settings page
  plain::Bool = false                   # the part of the page with the caret shows its markup: plain text, and not rich text
  spelling::Bool = true                 # put a line of dots under each word that's spelt wrong
  updates::Bool = true                  # the app looks for a newer version of itself, and gets it, without being asked
  autosave::Bool = false                # a page is written to its file when its window stops being the front window
  peeks::Bool = true                    # the card of a link to a page, while ⌘ is held, shows the start of the page. See "the start of a page in a link's card".
  ai::String = "Claude"                 # the agent that Ladder starts for a change or a question, by its name in AGENT_KINDS. See "the agents that Ladder can start".
  glide::Bool = true                    # the caret moves to a new place in a short time, and doesn't jump there
  wrap::Bool = true                     # a line of a file of code that's too long for the window goes on under itself
  numbers::Bool = true                  # a file of code shows the number of each line beside it
  shade::Bool = false                   # the line of a file of code that the caret is on is shaded
  beside::Bool = false                  # a block of changes shows the old lines at the left and the new lines at the right
  indent::Int = 2                       # how many spaces one step of indentation is, in code
  code_scale::Float64 = CODE_SCALE      # how big code is, as a part of the size of the page's text
  code_font::String = CODE_FONT         # the font of code, by the name of its family
  code_weight::Int = 300                # how heavy code is, like `weight`. A font without Light draws its nearest weight.
  guide::Int = 0                        # a faint line goes down a file of code after this many characters. 0 is no line.
  bundle::String = "Ladder"            # the bundle of key bindings: the shortcuts of every command
  rebound::Dict{Symbol,String} = Dict{Symbol,String}()   # the shortcuts of each command that has other keys than the bundle's, as the settings file writes them
  popup::Symbol = :none                # :finder while the file finder is open, and :commands while the command palette is
  picked::Int = 1                       # the file the finder will open
  scroll::Scroll = Scroll(width(grow=grow), height(grow=grow), scrollbar_inset=0px)   # the page's scrollbar is at the window's edge
  files_scroll::Scroll = Scroll(width(grow=grow), height(grow=grow))
  nodes::Dict{Any,Any} = Dict{Any,Any}()   # the parts of the window, kept between frames
  flows::Dict{Any,Any} = Dict{Any,Any}()
  layout::Vector{Item} = Item[]
  shown::UnitRange{Int} = 1:0           # the items that were built for the last frame
  width::px = PROSE_W                   # how wide the text is
  widest::px = PROSE_W                  # the widest the text gets, before zooming. The settings page sets it.
  reach::px = 0px                       # how far the longest line goes, in a file of code whose long lines don't wrap
  origin::Tuple{px,px} = (0px, 0px)     # where the page's text was last drawn in the window
  goal::Union{Nothing,px} = nothing     # where ↑ and ↓ try to keep the caret
  reveal::Bool = false                  # scroll to the caret before the next frame
  blink::Float64 = time()
  glides::Dict{Int,Glide} = Dict{Int,Glide}()   # where each caret is drawn while it moves: 1 is the main one. See `glide_to!`.
  gliding::Int = 1                      # the number of the caret that's being drawn
  by_step::Bool = false                 # a key has just taken the caret a step, so it moves to its new place in a short time
  carets::Int = 1                       # how many carets the last frame had
  clicked::Tuple{Float64,Pos,Int} = (0.0, (0, 0), 0)
  size::Tuple{px,px} = (1100px, 800px)  # the window's size, until there is a window to ask
end

@def mutable struct TopBar <: SemanticUI end
@def mutable struct Sidebar <: SemanticUI end    # the list of files down the left of the window
@def mutable struct Page <: SemanticUI end       # the scrolling area around the text
@def mutable struct Document <: SemanticUI end   # the text itself
@def mutable struct Backdrop <: SemanticUI end   # catches clicks outside a popup
@def mutable struct FinderInput <: SemanticUI end
@def mutable struct ToolButton <: SemanticUI
  icon::String = ""
  action::Symbol = :none
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)   # where it was last drawn, to put its tooltip under it
  quiet::Bool = false                         # clicked, so no tooltip until the mouse leaves it
end
"A button of the bar that shows over the table the caret is in"
@def mutable struct TableButton <: SemanticUI
  action::Symbol = :none
  label::String = ""
end
"The picture in the top bar of the level that the window shows at: a ladder at the highest level and a snake under it. While the mouse is over it, it opens into the slider of the levels."
@def mutable struct Mode <: SemanticUI
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)
  quiet::Bool = false
end
"The slider that the picture of the level opens into while the mouse is over it: a stop for each level, with the snake at its low end and the ladder at its high end"
@def mutable struct Levels <: SemanticUI
  stops::Vector{Any} = Any[]   # the Stop of each level, from the lowest
  open::Bool = false           # true from when the mouse comes over the picture until it leaves the slider
  since::Float64 = 0.0         # when it started to open or to close
  from::Float64 = 0.0          # how far open it was then, from 0 to 1
  pressed::Int = -1            # the level of the stop that the mouse went down on, 0 once a drag has left it, or -1 for none
end
"A stop of the slider of the levels. A click on it goes to its level."
@def mutable struct Stop <: SemanticUI
  level::Int = 1
  quiet::Bool = false          # clicked, so no tooltip until the mouse leaves it
end
"""
The Julia code of a `julia` code block of a page, or of a whole file of Julia
code. It's the part of the page that answers for the levels of what its code
comes to. See "what Julia code ran, down a level".
"""
@def mutable struct JuliaCode <: SemanticUI
  n::Int = 0       # its place among the `julia` code blocks of its page, or 0 for a file of Julia code
  depth::Int = 0   # how many levels down it shows what its code comes to: 0 for the value, 1 for inferred code, 2 for LLVM code, 3 for assembly
end
"The file's name in the middle of the top bar. A right-click on it shows the file's menu."
@def mutable struct Title <: SemanticUI end
"How many of the checks of a file of Julia code pass, in the top bar. A click goes to the next check that fails."
@def mutable struct CheckCount <: SemanticUI
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)
  quiet::Bool = false
end
"""
The lock in the top bar of a page that you can't change: a file that's only
shown, a page from a web server, or a file that your Mac marks as read-only.
It's no button. While the mouse is over it, its tooltip says "Read only".
"""
@def mutable struct ReadOnly <: SemanticUI
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)
  quiet::Bool = false
end
"The button in the top bar that sends the page to the agent that's waiting for it"
@def mutable struct SendButton <: SemanticUI
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)
  quiet::Bool = false
end

# The parts of the document. Each one holds the items that show its lines.
@def mutable struct Paragraph <: SemanticUI; first::Int = 0; last::Int = 0; items::Vector{Item} = Item[] end
@def mutable struct Heading <: SemanticUI; first::Int = 0; last::Int = 0; items::Vector{Item} = Item[] end
@def mutable struct List <: SemanticUI; first::Int = 0; last::Int = 0; items::Vector{Item} = Item[] end
@def mutable struct Quote <: SemanticUI; first::Int = 0; last::Int = 0; items::Vector{Item} = Item[] end
@def mutable struct CodeBlock <: SemanticUI; first::Int = 0; last::Int = 0; items::Vector{Item} = Item[] end
@def mutable struct Table <: SemanticUI; first::Int = 0; last::Int = 0; items::Vector{Item} = Item[] end
@def mutable struct Rule <: SemanticUI; first::Int = 0; last::Int = 0; items::Vector{Item} = Item[] end
"A code block in the language `ui`, showing what its code made"
@def mutable struct LiveBlock <: SemanticUI; first::Int = 0; last::Int = 0; items::Vector{Item} = Item[] end
"A code block in the language `sheet`, drawn as rows that work things out"
@def mutable struct SheetBlock <: SemanticUI; first::Int = 0; last::Int = 0; items::Vector{Item} = Item[] end
"The ! of a row of a sheet that went wrong. It says what went wrong while the mouse is over it."
@def mutable struct Trouble <: SemanticUI
  message::String = ""
  size::px = 14px
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)
end
const Block = Union{Paragraph,Heading,List,Quote,CodeBlock,Table,Rule,LiveBlock,SheetBlock}
"A row of the file finder's list, or of the project picker's: a page or a project"
@def mutable struct FileRow <: SemanticUI
  path::String = ""
  finder::Int = 0    # its place in the list
end
"The name of a file in the sidebar's tree"
@def mutable struct FileLabel <: SemanticUI
  path::String = ""
end
"A heading or a component of a file, as the sidebar lists it"
struct Entry
  line::Int       # where it starts
  level::Int      # a heading's level. A component has level 7, so it goes in the heading above it. A run of text in a line, in the top bar's path, has 8.
  title::String
  icon::String
  caret::Int      # the line the caret goes to: the heading's own, or the line after a component
end
"""
A heading or a component of a file, under that file in the sidebar's tree
"""
@def mutable struct EntryLabel <: SemanticUI
  path::String = ""
  line::Int = 0
  level::Int = 1
  title::String = ""
  icon::String = ""
  caret::Int = 0
end

editor(node) = begin
  while !(node isa Editor)
    node = node.parent
  end
  node
end

"A node that belongs to `e` and is kept for as long as `e` is"
own!(e, node) = (node.parent === nothing && setfield!(node, :parent, e); node)
node!(make, e, key) = get!(() -> own!(e, make()), e.nodes, key)

"""
A part of the page joins the children of the document, so one part can find
another by a walk of the tree: up to the document, then through its children.
`layout!` empties that list and gives the document each part of the page that
shows, so the children are the parts of this page, in the order of their lines.
The paragraphs, the headings and the other blocks that are made for the lines
on screen follow them.
"""
own!(d::Document, node) = begin
  parent = getfield(node, :parent)
  (parent === nothing || (parent === d && !listed(d, node))) && add_child!(d, node)
  node
end

"True if `node` is in the list of the children of `d`"
listed(d::Document, node) = getfield(node, :prevsibling) !== nothing || getfield(d, :firstchild) === node

"""
Take every child out of the document's list. Each one keeps the document as
its parent, so a node that an earlier frame made can still reach the editor.
"""
unlist!(d::Document) = begin
  child = getfield(d, :firstchild)
  while child !== nothing
    next = getfield(child, :nextsibling)
    setfield!(child, :prevsibling, nothing)
    setfield!(child, :nextsibling, nothing)
    child = next
  end
  setfield!(d, :firstchild, nothing)
  d
end

# A book review, as a blog's site tool reads it, is Markdown with a header that says the book's title
const MARKDOWN = (".md", ".markdown", ".mdx", ".review")
# A folder's own page, `.ladder`, is Markdown too: see "a folder's own page" below
ismarkdown(path) = lowercase(splitext(path)[2]) in MARKDOWN || basename(path) == FOLDER_PAGE

# The files of code that the page changes, as it changes a Markdown file. The whole file is one block of code.
const CODE_FILES = (".jl",)

"""
True when the file at `path` is code that the page can change: a kind of file
in `CODE_FILES`, whose text shows whole. A file of any usual length does: see
"the lines of a long file". A file that's longer than `MOST_PAGE`, or that
isn't text, is only shown.
"""
iscode(path) = begin
  (lowercase(splitext(path)[2]) in CODE_FILES && isfile(path)) || return false
  filesize(path) == 0 && return true
  found = try reading(path, tidy=false, most=MOST_PAGE) catch; nothing end
  found !== nothing && !found[2]
end

"Open the editor on a file, or on the first Markdown file in a folder"
build_editor(path) = begin
  # An address on the web is asked for once the window is on the screen: see "a page from a web server".
  # A name like `my.notes/new.md` is a file when the folder `my.notes` is there.
  Remote.typed(path) === nothing || ispath(expanduser(path)) || isdir(dirname(abspath(expanduser(path)))) ||
    return navigate!(blank_editor(), path)
  path = abspath(expanduser(path))
  e = blank_editor()
  isdir(path) ? open_on_folder!(e, path) : open!(e, path)
  e
end

"An editor that shows no file yet"
blank_editor() = begin
  e = Editor()
  load_sheet_font()
  load_omni_font()
  load_site_font()
  e.nodes[:input] = own!(e, TextInput(placeholder="Find a file", font_family=SANS, font_size=15px,
                                      look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text)))
  e
end

"""
Show the folder at `path` in a window that's opened on it: its first Markdown
file, or the folder's own page when it has no Markdown file. A folder of a
kind that shows in the page, like a desktop, shows there: see `show_opened!`.
The sidebar lists the folder, and it stays closed until you open it.
"""
open_on_folder!(e, path) = begin
  e.folder = path
  list_files!(e)
  isempty(e.files) ? show_beside!(e, path) : open!(e, e.files[1])
  e.nodes[:opened_on] = (path, e.buf.path)
  show_opened!(e)
  e
end

"""
Show the folder that the window was opened on in the page, when it's of a kind
that shows there, as a desktop is. A folder whose own page says its kind is
plain until that page has run, so the window asks again then. A window that
shows another file by then keeps that file.
"""
show_opened!(e) = begin
  on = get(e.nodes, :opened_on, nothing)
  on === nothing && return
  path, was = on
  (e.folder == path && e.buf.path == was) || return (delete!(e.nodes, :opened_on); nothing)
  d = directory(e)
  (d isa AbstractDirectory && !(d isa FS.Directory) && page_first(e, d) && page_view(e, d) !== nothing) || return
  delete!(e.nodes, :opened_on)
  open!(e, d)
  nothing
end

# The sidebar's folder, and each folder and file in it, is an object of the
# file system (FS.jl): a `File`, a `Directory`, or a kind of directory, which
# is a type under `AbstractDirectory`. Each directory makes the objects of what
# it holds, from the directory at `/` down. The sidebar asks the folder's
# object what to list and how to list it, and asks each object in the list for
# its icon, for what follows its name and for what a click on it does:
# `entries`, `folder_view`, `entry_icon`, `entry_marks` and `open!`. So code
# from the startup page gives a kind of folder its own way in the sidebar with
# a method for the folder's type, as it does for a component of a page. The
# page asks too: `page_view` gives what it shows for a file or a folder of a
# kind, `page_fills` says whether that's as wide as the window, and
# `page_covers` says whether it covers the page's whole space, as a desktop does.
#
#     @def struct NotesDirectory <: Ladder.AbstractDirectory end
#     Ladder.FS.kinds[fs"/Users/jake/Notes"] = NotesDirectory
#     Ladder.entry_icon(::NotesDirectory) = "box"
#
# A folder gets its kind from `FS.kinds`, by its path, or from a page of its
# own, the file `.ladder` in it: see "a folder's own page".

"""
Read the sidebar's folder again: what it lists, and the object of each one.
The objects are new each time, so a folder that code gave a kind since the
last time has that kind now.
"""
list_files!(e) = begin
  empty!(e.entries)
  d = isdir(e.folder) ? FS.get(FSPath(e.folder)) : nothing
  found = d isa AbstractDirectory ? entries(e, d) : FSObject[]
  d isa AbstractDirectory && (e.entries[e.folder] = d)
  e.listed = String[joinpath(e.folder, o.path.name) for o in found]
  foreach((path, o) -> e.entries[path] = o, e.listed, found)
  # The file finder lists the Markdown files
  e.files = String[path for (path, o) in zip(e.listed, found) if isfile(o) && ismarkdown(path)]
end

"""
What the sidebar lists of the directory `d`: its folders, then its files, each
in the order of their names. A name that starts with a dot is hidden, as it is
in the Finder, unless the sidebar shows those. .DS_Store is the Finder's own
file, and never shows. What's neither a folder nor a file isn't listed. The
home folder lists the Mac's Trash, whose folder is hidden, since the Finder
has it in the Dock and Ladder has no other place for it.
"""
entries(e, d::AbstractDirectory) = begin
  trash = Sys.isapple() && string(d.path) == homedir() ? basename(Mac.trash()) : ""
  shows(n) = e.hidden ? n != ".DS_Store" : !ishidden(n) || n == trash
  found = FSObject[]
  # macOS doesn't let Ladder read some folders, like the Trash without Full Disk Access. Those list nothing.
  names = try readdir(string(d.path)) catch; String[] end
  for name in sort!(names, by=lowercase)
    shows(name) || continue
    # A link that leads nowhere, a socket, and a file that left since the folder was read have no object to list
    o = try FS.child(d, name) catch; nothing end
    o === nothing || push!(found, o)
  end
  [filter(isdir, found); filter(isfile, found)]
end

"The object of the sidebar's folder, or nothing when no folder is there"
directory(e) = get(e.entries, e.folder, nothing)

"The object of the folder or the file at `path`: the one that the sidebar lists, or else a new one. Nothing when nothing is there."
object(e, path) = get(() -> ispath(path) ? FS.get(FSPath(path)) : nothing, e.entries, path)

"The name that `o` has in the sidebar: its own name, unless its kind has a better one, as the Trash has"
entry_name(o::FSObject) = basename(rstrip(string(o.path), '/'))

"The icon that `o` has in the sidebar"
entry_icon(o::AbstractDirectory) = "folder"
entry_icon(o::FSObject) = file_icon(string(o.path))

"""
What follows the name of `o` in its row of the sidebar, like how many emails of
a folder aren't read: nodes, or `()`. A kind of folder has a method with three
arguments to say it for each thing that it holds: `entry_marks(e, d, o)`,
where `d` is the directory that holds `o`.
"""
entry_marks(e, o::FSObject) = entry_marks(e, o.parent, o)
entry_marks(e, d, o) = ()

"""
How the sidebar lists the directory `d`: `(list=..., bar=...)`. `list` is a
node that shows in place of the tree of what `entries` gives, or nothing to
leave the tree. `bar` is a node for a line over the list, or nothing. `d` is
nothing when the sidebar's folder isn't there.
"""
folder_view(e, d) = (list=nothing, bar=nothing)

"""
What the page shows for `o`, a file or a folder, in place of Ladder's own
viewer: a node, or nothing to leave Ladder's viewer. A kind of folder has a
method of this to show itself in the page, as a folder of films shows their
posters, or to show a file that it holds its own way. A folder shows in the
page after `open!(e, path)` with the folder's path.
"""
page_view(e, o) = nothing

"True when what `page_view` gives for `o` is as wide as the window has room for, as a table is, and not as wide as a page's text"
page_fills(e, o) = false

"""
True when a window that's opened on the folder `d` shows what `page_view`
gives for it. It's false for a kind of folder whose first page of text is the
better start, as a folder that git keeps is: its Readme shows.
"""
page_first(e, d) = true

"""
The object of the file or the folder that the page shows in a viewer, or
nothing when it isn't there. One that the sidebar doesn't list is found again
after a second, and not in each frame.
"""
page_object(e) = begin
  path = e.buf.path
  (e.buf.view == :file && !isempty(path)) || return nothing
  haskey(e.entries, path) && return e.entries[path]
  kept = get(e.nodes, :page_object, nothing)
  kept !== nothing && kept[1] == path && time() - kept[2] < 1 && return kept[3]
  o = try object(e, path) catch; nothing end
  e.nodes[:page_object] = (path, time(), o)
  o
end

"""
True when what `page_view` gives for `o` covers the page's whole space in the
window: from the sidebar to the window's right edge, and from the top bar to
the bottom. It has no space round it, and the page doesn't scroll. A desktop
covers the page so, with its wallpaper.
"""
page_covers(e, o) = false

"""
What shows in a panel at the right of the window, beside what `page_view`
gives for `o`: a node, or nothing for no panel. The page of a repository has
git's panel there. The panel runs from the top of the window to the bottom, as
the sidebar does, and the top bar's button at its right end hides it. It's for
a page that covers the page's space (see `page_covers`), which leaves it room.
"""
page_side(e, o) = nothing

"""
Take a step back in what `page_view` gives for `o`, before the window shows the
file that showed before: true when it took one. The page of a repository goes
from a commit back to the repository's files.
"""
page_back!(e, o) = false

"""
What shows under the text of the page `o`, which the directory `d` holds: a
node, or nothing. A kind of folder has a method of this to add to each page
that it holds, as a folder of notes lists the pages that link to the page.
It's as wide as the page's text, `e.width`, and it scrolls with the text.
"""
page_foot(e, d, o) = nothing

"""
What shows in place of the card of the front matter of the page `o`, which the
directory `d` holds, while the caret isn't in it: a node, or nothing for the
card. A kind of folder has a method of this to show the front matter of the
pages that it holds its own way, as a blog shows a book review's title and
stars. `rows` are the front matter's keys, each as its line, the key and what
it's set to, as it's written.
"""
matter_view(e, d, o, rows) = nothing

"""
The object of the page of text that shows, or nothing. One that the sidebar
doesn't list is found again after a second, and not in each frame. A page
from a web server is a `WebPage`, in the web folders that it's in.
"""
text_object(e) = begin
  path = e.buf.path
  isremote(path) && return web_page(path)
  haskey(e.entries, path) && return e.entries[path]
  kept = get(e.nodes, :text_object, nothing)
  kept !== nothing && kept[1] == path && time() - kept[2] < 1 && return kept[3]
  o = try object(e, path) catch; nothing end
  e.nodes[:text_object] = (path, time(), o)
  o
end

"What shows under the text of the page, or nothing: see `page_foot(e, d, o)`. Only a page of Markdown that shows whole has it."
page_foot(e) = begin
  b = e.buf
  (b.view == :markdown && !isempty(b.path) && !filled(e) && slideshow(e) === nothing) || return nothing
  o = text_object(e)
  o === nothing ? nothing : with_theme(() -> page_foot(e, o.parent, o), component_theme(e.zoom))
end

"True when a kind of folder or of file shows the page its own way, as wide as the window has room for"
own_page(e) = (o = page_object(e); o !== nothing && page_fills(e, o))

"True when the folder or the file that shows covers the page's whole space with a view of its own"
page_covered(e) = (o = page_object(e); o !== nothing && page_covers(e, o))

"What covers the page's whole space, when the folder or the file that shows is of a kind that covers it, or nothing"
page_cover(e) = begin
  o = page_object(e)
  (o !== nothing && page_covers(e, o)) || return nothing
  # The Box is made inside the theme too. A node that `page_view` gives, like a SolidCraft design's
  # editor, is described when it's put in the Box, and it takes the theme of that moment.
  with_theme(component_theme(e.zoom)) do
    own = page_view(e, o)
    own === nothing ? nothing : Box(width(grow=grow), height(grow=grow), Alignment.Start, own)
  end
end

"How wide and how tall the page's space in the window is: beside the sidebar, and under the top bar"
page_room(e) = begin
  w, h = window_size(e)
  side = lowered(e) === nothing ? panel_w(e) * opened(e) : 0px
  (max(w - side, 1px), max(h - TOPBAR_H, 1px))
end

"""
Show the file at `path`. A file that's already open keeps its changes. The
file that leaves goes on the list that `go_back!` reads, unless `record` is false.
A folder shows too, when its kind has a method of `page_view`. The sidebar
then lists the folder that it's in, as it does for a file.
"""
open!(e, path; record=true) = begin
  # A link in a part of another page opens its page in the window, not in the part
  hosted(e) === nothing || return open!(top_editor(e), path; record)
  # A page from a web server that isn't here yet is asked for, and shows when it has come
  isremote(path) && !haskey(e.buffers, path) && return get_page!(e, path; record)
  leave_page!(e, path; record)
  e.buf = get!(e.buffers, path) do
    isfile(path) ? load(path) : isdir(path) ? Buffer(path=path, view=:file) : Buffer(path=path)
  end
  # The sidebar goes on listing the folder that it lists while a page from a web server shows
  if e.folder != dirname(path) && !isremote(path)
    e.folder = dirname(path)
    list_files!(e)
  end
  e.scroll.offset = e.buf.offset
  e.popup = :none
  e.goal = nothing
  w = window_of(e)
  w === nothing || focus(e)
  e
end

"""
Get the window ready to show the page at `path`, or no page when `path` is "".
The page that leaves keeps what its blocks hold and where it was scrolled to.
It goes on the list that `go_back!` reads, unless `record` is false.
"""
leave_page!(e, path; record=true) = begin
  # A sound that the last page was playing stops. A new window has no last page, and another window's sound plays on.
  isempty(e.buffers) || silence!()
  write_blocks!(e)   # the page that leaves keeps what its blocks hold
  e.buf.offset = e.scroll.offset
  from = e.buf.path
  from == path || forget_ticked!(e)   # an item that was ticked in a list of what's found leaves that list
  from == path || delete!(e.nodes, (:html, from))   # the page of an HTML file ends, with its scripts
  from == path || leave_design!(e, from)            # and a design with no changes gives up SolidCraft's program
  # A new file ends the list of files to go forward to, as a new address does in a web browser
  record && !isempty(from) && from != path && (push!(e.back, from); empty!(e.ahead))
  e
end

# --- closing a file ----------------------------------------------------------------------
#
# ⌘W closes the file that the window shows, and the window shows the folder
# that the file is in, as a click on that folder in the sidebar's trail does.
# ⌘W on a folder's page closes it, and the window stays open with no file in
# it. ⌘W in a window that shows no file closes the window, and Ladder quits
# when its last window closes. So three presses of ⌘W close a file's window:
# the file, its folder, then the window. The settings window closes at once
# while it shows a page of the settings. A file that closes keeps its changes,
# and ⌘⌥← shows it again.

"True when the window shows no file, because ⌘W closed the page that it showed"
nofile(e) = isempty(e.buf.path) && e.buf.fixed

"""
The folder that the window shows when ⌘W closes its file, or nothing. A
folder's own page, a page that isn't a file on the Mac, and a file in a
folder that the Finder shows as one file, like an app, have none.
"""
closes_to(e) = begin
  path = e.buf.path
  (isabspath(path) && !isdir(path)) || return nothing
  folder = dirname(path)
  isdir(folder) && !ispackage(folder) ? folder : nothing
end

"""
Close the file that the window shows, and show the folder that it's in. A
page with no such folder closes to no file. The page keeps its changes, and
goes on the list that `go_back!` reads.
"""
close_file!(e) = begin
  folder = closes_to(e)
  folder === nothing || return open_folder!(e, folder)
  leave_page!(e, "")
  e.buf = Buffer(fixed=true)   # an empty page that nothing can be typed in
  e.scroll.offset = 0px
  e.popup = :none
  e.goal = nothing
  e
end

"What ⌘W does: close the file that the window shows, or the window when it shows no file or a page of the settings"
close_file_or_window!(e, w) = (nofile(e) || issettings(e)) ? (closes!(e, w) && close(w)) : close_file!(e)

# --- the files that showed before --------------------------------------------------------
#
# Each window keeps the files that it showed, in the order that it showed them.
# ⌘⌥← goes back to the file that showed before the one that shows now, as the
# back button of a web browser does. ⌘⌥→ goes forward again, to the file that
# going back left. While the sidebar is open, two arrows at its top do the
# same. They are in the top bar, at the right of the part that's over the
# sidebar, and they aren't there while the sidebar is closed, or while
# something fills the window (see `filled`). An arrow is
# faint when it has no file to go to, and its tooltip names the file that it
# goes to. The two buttons at the side of a mouse go back and forward as well,
# if the mouse has them. Any way of showing a file adds to the list: a link, the
# list of files, the file finder, a line of a `find` block. A file shows from
# the place that it was scrolled to, because its buffer keeps that. A link to
# a heading of the page that shows adds nothing, because the file is the same.

"True when the window can show the file at `path` again: it's on the disk, or it's a new page that has no file yet, or a folder that showed in the page"
showable(e, path) = haskey(e.buffers, path) || isfile(path)

"""
The file that `go_back!` would show, or nothing when no file showed before the
one that shows now. With `e.ahead` as the `list`, it's the file that
`go_forward!` would show.
"""
last_shown(e, list=e.back) = (i = findlast(p -> p != e.buf.path && showable(e, p), list); i === nothing ? nothing : list[i])

"What the arrow that goes back (or forward, with `e.ahead` as `list`) goes to, in words: a line of the file that shows, or a file. It's nothing when there's neither."
step_words(e, list=e.back) = begin
  j = jump_list(e)
  p = place_back(e, list === e.back ? j.back : j.ahead, list)
  p !== nothing && return "line $(p.caret[1])"
  to = last_shown(e, list)
  to === nothing ? nothing : basename(to)
end

# A jump to another line of the same file, as Go To, Go To Definition, Find
# Uses and Show Steps make, is a step too. ⌘⌥← goes back to the line that the
# jump left, with the caret and the scroll as they were, before it goes back
# to another file. ⌘⌥→ goes to the jump's line again.

"""
The places of the files that showed that the window of `e` jumped from: `back`
for ⌘⌥←, and `ahead` for ⌘⌥→. Each has the file's path, where the caret and
the scroll were, and how many files the list of files to go back to (or
forward to) had then: a place comes before the files that the list got
after it.
"""
jump_list(e) = get!(() -> (back=Any[], ahead=Any[]), e.nodes, :jumps)

"Where the window of `e` is: its file, its caret, its anchor and how far it's scrolled"
place_now(e) = begin
  # While the palette showed a row of its list, the window scrolled to it. The place is where it was before that.
  was = get(e.nodes, :unpreviewed, nothing)
  (path=e.buf.path, caret=e.buf.caret, anchor=e.buf.anchor, offset=was isa typeof(e.scroll.offset) ? was : e.scroll.offset)
end

"Note where the window of `e` is, before it jumps to another line of the file, so ⌘⌥← comes back to it. A new jump ends what ⌘⌥→ would go to."
note_place!(e) = begin
  isempty(e.buf.path) && return nothing
  j = jump_list(e)
  push!(j.back, (; place_now(e)..., depth=length(e.back)))
  empty!(j.ahead)
  empty!(e.ahead)
  nothing
end

"The place of the file that shows that a step from the list of files `files` goes to first, from the places `places`, or nothing"
place_back(e, places, files) = !isempty(places) && last(places).depth == length(files) && last(places).path == e.buf.path ? last(places) : nothing

"Put the window of `e` where it was at the place `p`: its caret, its anchor and its scroll"
go_place!(e, p) = begin
  b = e.buf
  fit(c) = (n = clamp(c[1], 1, length(b.lines)); (n, clamp(c[2], 0, length(b.lines[n]))))
  b.caret, b.anchor = fit(p.caret), fit(p.anchor)
  e.scroll.offset = p.offset
  delete!(e.nodes, :hold)
  focus(e)
  redraw_in!(e, 0)
  nothing
end

"""
Show the last file of `from` that's still there, and put the file that leaves
on `to`. A file that was renamed is there under its new name. One that went to
the Trash is passed over. It's true when there was a file to show. A jump in
the file that shows comes first: see `jump_list`.
"""
step_back!(e, from, to) = begin
  j = jump_list(e)
  mine, theirs = from === e.back ? (j.back, j.ahead) : (j.ahead, j.back)
  p = place_back(e, mine, from)
  if p !== nothing
    pop!(mine)
    push!(theirs, (; place_now(e)..., depth=length(to)))
    go_place!(e, p)
    return true
  end
  while !isempty(from)
    path = pop!(from)
    (path == e.buf.path || !showable(e, path)) && continue
    isempty(e.buf.path) || push!(to, e.buf.path)
    open!(e, path, record=false)
    return true
  end
  false
end

"""
Show the file that showed before the one that shows now. It's false when no
file showed before. A folder's own page can take a step back of its own first,
as the page of a repository goes from a commit back to its files: see `page_back!`.
"""
go_back!(e) = (o = page_object(e); o !== nothing && page_back!(e, o)) || step_back!(e, e.back, e.ahead)

"Show the file that `go_back!` left. It's false when there is none, or when another file was opened since."
go_forward!(e) = step_back!(e, e.ahead, e.back)

window_size(e) = something(viewport(e), e.size)

"The folder of the document that's showing. The sidebar can show another folder."
docdir(e) = isempty(e.buf.path) ? e.folder : dirname(e.buf.path)

"True when the file or folder at `path` is a hidden one: its name starts with a dot"
ishidden(path) = startswith(basename(path), '.')

"Make the sidebar list the hidden files and folders too, or leave them out again"
hidden!(e, on::Bool) = (e.hidden = on; list_files!(e); save_settings!(e); e)

"What a click on `o` in the sidebar does: a folder shows in the sidebar, and a file shows in the page"
open!(e, d::AbstractDirectory; record=true) = go_folder!(e, string(d.path))
open!(e, o::FSObject; record=true) = open!(e, string(o.path); record)

"Show the folders and files of `folder` in the sidebar. The document that's showing stays."
go_folder!(e, folder) = begin
  e.folder = folder
  list_files!(e)
  e.files_scroll.offset = 0px
  e
end
input(e) = e.nodes[:input]::TextInput

# --- faces -----------------------------------------------------------------------------

const TEXT_SIZE = 17px   # of the page's text, before it's zoomed
# A page of a blog has the typeface of the blog's site, in its usual weight. See "the look of a blog's site".
body(e) = e.look == :site ? Face(SITE_FONT[], "", TEXT_SIZE * e.zoom, colours.ink, false) :
                            Face(e.font, nearest_weight(e.font, e.weight).style, TEXT_SIZE * e.zoom, colours.ink, false)
const HEADINGS = (2.1, 1.75, 1.4, 1.2, 1.05, 1.0)
"How much bigger than the text each level of heading is on a page of a blog, as its site has them"
const SITE_HEADINGS = (2.3, 1.4, 1.12, 1.0, 1.0, 1.0)

"The face a line's plain text is drawn in"
face(e, line::Line) = begin
  b = body(e)
  k = line.kind
  # A blog's site has its headings a little lighter than bold
  k == Kind.heading && e.look == :site && return Face(b, style=line.level == 4 ? "SemiBold Italic" : "SemiBold", size=b.size * SITE_HEADINGS[line.level])
  k == Kind.heading ? Face(emboldened(b), size=b.size * HEADINGS[line.level]) :
  # A callout's text is the page's own. Its title is bold, in the colour of its kind.
  opens_callout(line) ? Face(emboldened(b), color=callout_colour(line.lang)) :
  k == Kind.blockquote ? (isempty(line.lang) ? Face(b, style=slanted(b.style), color=colours.dim) : b) :
  # A comment on lines of its own is in the page's font, and dim
  line.lang == COMMENT ? Face(b, color=colours.dim) :
  # Code is the size that the settings page chooses. The markup of a table or a rule is code's usual size.
  k in (Kind.code, Kind.fence) ? Face(b, family=codefont(), style=codestyle(), size=code_size(e)) :
  k in (Kind.table, Kind.rule) ? Face(b, family=codefont(), style=codestyle(), size=b.size * CODE_SCALE) : b
end

"The face for one span of a line whose plain text is drawn in `base`"
face(base::Face, s::Span) = begin
  s.markup && return Face(base, color=colours.faint)
  # A comment shows only while its line's markup shows, and then it's dim
  s.comment && return Face(base, color=colours.dim)
  # The TeX of a formula, while it shows as it's written, is in the font of code
  s.math && return Face(codefont(), codestyle(), base.size * 0.86, base.color, false)
  # Inline code that runs is Julia, so its parts get the colours they have in a code block
  s.code && return Face(codefont(), codestyle(), base.size * 0.86, base.color, true, s.live ? "julia" : "")
  f = s.bold ? emboldened(base) : base
  s.italic && !isitalic(f.style) && (f = Face(f, style=slanted(f.style)))
  Face(f, color=!isempty(s.link) ? colours.accent : s.strike ? colours.faint : base.color, highlit=s.highlit)
end

"The colour behind ==words==: a highlighter's yellow, a little darker on a dark page"
highlighter() = dark_page() ? RGBA(0.85, 0.68, 0.1, 0.38) : RGBA(1.0, 0.85, 0.2, 0.45)

# --- the weights of the page's text and of code --------------------------------------
#
# The page's text and code can each be lighter or heavier than the font's usual
# weight. The settings pages list the weights that each font has, up to
# Semibold, by the names that the font gives them. Code starts in Light, so
# that it reads lighter than the page's text. Bold text and headings are
# heavier than the rest: Bold, or Extra bold when the text is Semibold. A font
# that lacks the weight you chose draws the one nearest to it, and the next
# font that has the weight draws it again.
#
# A weight is kept as the Mac's number for it, like 300 for Light. Fonts don't
# agree on names: Helvetica Neue's UltraLight is lighter than its Thin, and
# Charter calls its usual weight Roman. The Mac's numbers don't always agree
# with the names either: it says that Source Code Pro's ExtraLight weighs 300
# and its Light 342. So a font's weights are in the order of the Mac's numbers,
# with the font's own names, and each is drawn by its name.

"What the settings pages call each weight of a font whose faces the Mac hides, like SF Mono, from 100 to 900"
const WEIGHT_NAMES = ("Thin", "Extra light", "Light", "Regular", "Medium", "Semibold", "Bold", "Extra bold", "Black")
const HEAVIEST = 650   # the heaviest that the page's text and code can be: Semibold. Heavier text would hide what's bold.

weight_label(w::Integer) = WEIGHT_NAMES[clamp(round(Int, w / 100), 1, length(WEIGHT_NAMES))]

"The style of a face of the weight `w`, as Skia reads it: \"\" for Regular, or like \"Light\" and \"Bold Italic\""
text_style(w::Integer, italic::Bool=false) = begin
  name = w == 400 ? "" : weight_name(w)
  italic ? String(strip("$name Italic")) : name
end

"The style of the slanted face of `style`, like \"Light Italic\""
slanted(style::AbstractString) = isempty(style) ? "Italic" : "$style Italic"

"The weight of bold text among text of the weight `w`"
bolder(w::Integer) = max(700, w + 200)

"The face `f` made bold. A face that's bold already, like a heading's, stays as it is."
emboldened(f::Face) = begin
  w = weight_of(f.style)
  w >= 700 ? f : Face(f, style=text_style(bolder(w), isitalic(f.style)))
end

"A weight of a font: what the settings pages call it, the style that draws it, and the Mac's number for it"
const Weight = @NamedTuple{label::String, style::String, weight::Int}
const font_weights = Dict{String,Vector{Weight}}()

"""
The weights of `family` that the page's text or code can be in, lightest
first, by the names that the font gives them. A font whose faces the Mac
hides, like SF Mono, has the weights that it draws when asked for 100, 200
and so on. There are none when the Mac has no font of that family.
"""
text_weights(family::AbstractString) = get!(font_weights, String(family)) do
  faces = filter(f -> !f.italic && f.width == Int(Skia.SK_FONT_STYLE_WIDTH_NORMAL), installed_faces(family))
  found = if isempty(faces)
    Weight[(label=weight_label(w), style=text_style(w), weight=w) for w in filter(>(0), [installed_weight(family, w) for w in 100:100:900])]
  else
    # The usual face draws with no style, as it did before there were weights to choose
    usual(f) = f.weight == 400 && lowercase(f.name) in ("regular", "roman", "normal")
    Weight[(label=f.name, style=usual(f) ? "" : f.name, weight=f.weight) for f in faces]
  end
  found = sort!(unique(w -> w.weight, found), by=w -> w.weight)
  light = filter(w -> w.weight <= HEAVIEST, found)
  # A font that has only heavy weights draws its lightest
  isempty(light) ? found[1:min(1, end)] : light
end

"""
The weight of `family` nearest to `w`: the one that text of the weight `w` is
drawn in. Of two that are as near, it's the one nearer to Regular.
"""
nearest_weight(family::AbstractString, w::Integer) = begin
  has = text_weights(family)
  isempty(has) && return (label=weight_label(w), style=text_style(w), weight=Int(w))
  argmin(x -> (abs(x.weight - w), abs(x.weight - 400)), has)
end

"The Mac's number for the weight of `family` called `name`, like \"Light\""
weight_called(family::AbstractString, name::AbstractString) = begin
  has = text_weights(family)
  i = findfirst(w -> w.label == name, has)
  i === nothing && error("The weights of $(font_label(family)) are $(join([w.label for w in has], ", ", " and ")). $name isn't one of them.")
  has[i].weight
end

"`w` if text can be that heavy"
text_weight(w::Integer) = 0 < w <= HEAVIEST ? Int(w) : error("A weight of text goes from 1, the lightest, to $HEAVIEST, which is Semibold. $w isn't one of them.")

piece(text, col, face; atomic=false, n=length(text), link="", node=nothing, words=false) = Piece(text, col, n, face, atomic, link, node, words)

# --- the font of code ------------------------------------------------------------------
#
# Code is drawn in a font whose letters are all one width. The settings page
# lists each such font on the Mac, and code is drawn in the one you choose, in
# the weight you choose. Code starts in the font's light weight when the font
# has one, as SF Mono has, so that code reads lighter than the page's text.

"The weight of the face of `family` nearest to `weight`, or 0 when the Mac has no font of that family"
installed_weight(family::AbstractString, weight::Integer) = begin
  style = Skia.sk_fontstyle_new(Int32(weight), Int32(Skia.SK_FONT_STYLE_WIDTH_NORMAL), Skia.SK_FONT_STYLE_SLANT_UPRIGHT)
  typeface = Skia.sk_fontmgr_match_family_style(fontmgr[], String(family), style)
  Skia.sk_fontstyle_delete(style)
  typeface == C_NULL && return 0
  found = Skia.sk_typeface_get_fontstyle(typeface)
  w = Int(Skia.sk_fontstyle_get_weight(found))
  Skia.sk_fontstyle_delete(found)
  Skia.sk_typeface_unref(typeface)
  w
end

"Draw code in the font and weight that `e`'s settings choose, from now until another window starts to draw"
use_code_font!(e) = (code_type[] = (e.code_font, nearest_weight(e.code_font, e.code_weight).style); e)

"True when every letter of `family` is as wide as every other, as in a font for code"
isfixed(family) = begin
  f = Face(family, "", 20px, colours.ink, false)
  all(c -> has(f, c), "iMw0") && measure(f, "i") == measure(f, "M") == measure(f, "0")
end

# The Mac's own font for code has a hidden name, and the list calls it SF Mono
font_label(family) = family == ".SF NS Mono" ? "SF Mono" : family
font_family(label) = label == "SF Mono" && CODE_FONT == ".SF NS Mono" ? CODE_FONT : label

const fixed_fonts = String[]

"""
The names in `fonts` with each font once, where a font comes in copies whose
letters are the same. A Nerd Font comes as X Nerd Font, X Nerd Font Mono and X
Nerd Font Propo, whose icons differ. A variable font, X Var, is X with its
weights in one file. The plain X stays, or the one there is.
"""
once_each(fonts) = filter(f -> !(endswith(f, COPIES) && replace(f, COPIES => "") in fonts), fonts)
const COPIES = r"(?<= Nerd Font) (Mono|Propo)$| Var$"

# Fonts of pictures, not letters, though each picture is as wide as the next
const PICTURE_FONTS = ("Webdings", "Wingdings", "Wingdings 2", "Wingdings 3", "Symbol", "Zapf Dingbats", "Bodoni Ornaments")

"The families of the fonts on this Mac whose letters are all one width, in order, with the one that code is drawn in at first"
code_fonts() = begin
  if isempty(fixed_fonts)
    names = String[]
    name = Skia.sk_string_new_empty()
    for i in 0:Skia.sk_fontmgr_count_families(fontmgr[])-1
      Skia.sk_fontmgr_get_family_name(fontmgr[], Cint(i), name)
      push!(names, unsafe_string(Skia.sk_string_get_c_str(name)))
    end
    Skia.sk_string_delete(name)
    # A font whose name starts with a dot is the Mac's own, for its menus and windows
    found = filter(f -> !startswith(f, '.') && font_family(f) == f && !(f in PICTURE_FONTS) && isfixed(f), unique(names))
    append!(fixed_fonts, sort!(once_each(found), by=lowercase))
  end
  unique([CODE_FONT; fixed_fonts])
end

# The text that stands for the box of a to-do item. The box is drawn in its place, so only the text's width matters.
# Both hold the same characters, so an empty box and a ticked one are the same width.
const TODO_OPEN, TODO_DONE = "[ ] ", "] [ "
"True when `seg` is the box of a to-do item"
isbox(seg) = seg.atomic && (seg.text == TODO_OPEN || seg.text == TODO_DONE)

"True when `f` is the layout of a to-do item that shows its box, and not the - [ ] that makes the box"
shows_box(f) = f isa Flow && f.kind == Kind.todo && !f.raw && any(isbox, first(f.lines).segs)

"""
The runs of text that line `text` is drawn as. With `raw`, the markup shows.
With `open`, only the runs of the line in those columns show it: see `raw_part`.
"""
pieces(e, text::String, line::Line, raw::Bool, i::Int=0; open=nothing) = begin
  base = face(e, line)
  out = Piece[]
  k = line.kind
  if k == Kind.code && line.lang == MATTER
    # In front matter, the key is fainter than what it's set to, and a comment slants
    m = match(r"^(\s*(?:-\s+)?)([^:#\s][^:#]*:)(.*)$", text)
    if startswith(lstrip(text), '#') || m === nothing
      comment = startswith(lstrip(text), '#')
      isempty(text) || push!(out, piece(text, 0, comment ? Face(base, color=colours.comment, style=codeslant()) : base))
    else
      isempty(m[1]) || push!(out, piece(String(m[1]), 0, base))
      push!(out, piece(String(m[2]), length(m[1]), Face(base, color=colours.dim)))
      isempty(m[3]) || push!(out, piece(String(m[3]), length(m[1]) + length(m[2]), base))
    end
    return out
  elseif k == Kind.code && line.lang == TOML_MATTER
    # TOML front matter looks like YAML front matter: a key and its = are fainter, and so is a
    # [table] line that starts a group of keys. A comment slants.
    m = match(r"^(\s*)((?:\"[^\"]*\"|'[^']*'|[\w.-])+\s*=)(.*)$", text)
    if startswith(lstrip(text), '#')
      push!(out, piece(text, 0, Face(base, color=colours.comment, style=codeslant())))
    elseif startswith(lstrip(text), '[') && m === nothing
      push!(out, piece(text, 0, Face(base, color=colours.dim)))
    elseif m === nothing
      isempty(text) || push!(out, piece(text, 0, base))
    else
      isempty(m[1]) || push!(out, piece(String(m[1]), 0, base))
      push!(out, piece(String(m[2]), length(m[1]), Face(base, color=colours.dim)))
      isempty(m[3]) || push!(out, piece(String(m[3]), length(m[1]) + length(m[2]), base))
    end
    return out
  elseif line.lang == COMMENT && k in (Kind.code, Kind.fence)
    # A comment on lines of its own shows only while the caret is in it. Its words are dim, and its %% are faint.
    k == Kind.fence && !raw && return out
    a = k == Kind.fence && line.level == 0 ? length(match(r"^\s*%%", text).match) : 0
    z = k == Kind.fence && line.level == 1 ? length(text) - length(match(r"%%\s*$", text).match) : length(text)
    a > 0 && push!(out, piece(head(text, a), 0, Face(base, color=colours.faint)))
    z > a && push!(out, piece(rest(head(text, z), a), a, base))
    z < length(text) && push!(out, piece(rest(text, z), z, Face(base, color=colours.faint)))
    return out
  elseif k == Kind.code && line.lang in (HEX, BITS)
    # In a line of a file's bytes, the place in the file is faint and the bytes as characters are dim
    n = ncodeunits(text)
    chars = line.lang == HEX ? HEX_CHARS : BITS_CHARS
    for (lo, hi, colour) in ((0, HEX_BYTES, colours.faint), (HEX_BYTES, chars, base.color), (chars, n, colours.dim))
      lo < n && push!(out, piece(text[lo+1:min(hi, n)], lo, Face(base, color=colour)))
    end
    return out
  elseif k == Kind.code
    # Each part of a line of code has its own colour, and comments slant. A `check` block's lines are Julia.
    # A line inside a docstring of several lines is all the colour of a string.
    for t in tokens(text, shared_lang(line.lang), i > 0 ? string_open(e.buf, i, text) : '\0')
      colour = t.kind == :plain ? base.color : getfield(colours, t.kind)
      push!(out, piece(t.text, t.col, Face(base, color=colour, style=t.kind == :comment ? codeslant() : base.style)))
    end
    return out
  elseif k in (Kind.fence, Kind.table, Kind.rule)
    k == Kind.fence && !raw && return out
    isempty(text) || push!(out, piece(text, 0, k == Kind.table ? base : Face(base, color=colours.faint)))
    return out
  end
  # True when the columns `lo` to `hi` show their markup
  written(lo, hi) = raw || markup_shows(open, lo, hi)
  lead = head(text, line.prefix)
  bare = written(0, line.prefix)   # true when what starts the line shows as it's written
  if k in (Kind.bullet, Kind.ordered, Kind.todo)
    line.level > 0 && push!(out, piece(head(lead, line.level), 0, base))
    mark = Face(emboldened(base), color=colours.marker)
    if k == Kind.bullet && !bare
      push!(out, piece("•  ", line.level, mark, atomic=true, n=line.prefix - line.level))
    elseif k == Kind.todo && !bare
      # On another day than today, the box shows how the item stands then: see `ticked_then`
      push!(out, piece(something(ticked_then(e, i), isdone(text)) ? TODO_DONE : TODO_OPEN, line.level, base, atomic=true, n=line.prefix - line.level))
    else
      push!(out, piece(rest(lead, line.level), line.level, mark))
    end
    # A to-do item that's done reads fainter
    k == Kind.todo && something(bare ? nothing : ticked_then(e, i), isdone(text)) && (base = Face(base, color=colours.dim))
  elseif k == Kind.paragraph
    isempty(lead) || push!(out, piece(lead, 0, base))
  elseif opens_callout(line) && !bare
    # The line that names a callout's kind shows the kind's icon, and its name when the line has no title of its own
    push!(out, callout_mark(e, line, base, length(text) > line.prefix))
  elseif bare && !isempty(lead)
    push!(out, piece(lead, 0, Face(base, color=colours.faint)))
  end
  start = line.prefix
  note = k == Kind.paragraph ? match(NOTE, text) : nothing
  note === nothing || written(0, length(note.match)) && (note = nothing)
  if note !== nothing
    # The line that holds a footnote's text starts with the footnote's number
    start = length(note.match)
    push!(out, piece(note_mark(e, note[1]) * ".  ", 0, Face(base, color=colours.accent), atomic=true, n=start, link="^" * note[1]))
  end
  for s in spans(rest(text, start), start)
    shown = written(s.col, s.col + length(s.text))
    (s.markup || s.comment) && !shown && continue
    if startswith(s.link, '^') && !shown
      # [^name] shows as the footnote's number, small and raised
      push!(out, piece(note_mark(e, s.text), s.col, Face(base, size=base.size * 0.7, color=colours.accent), atomic=true, n=length(s.text), link=s.link))
      continue
    end
    # $x^2$ shows as the formula that its TeX describes
    if s.math && !shown && Maths.available()
      push!(out, equation(e, s, base))
      continue
    end
    # Line -1 isn't one of the document's lines: it's a line of a file under a path. Its inline code shows as code.
    s.live && !shown && i >= 0 && !foreign(e.buf.path) ? push!(out, inline(e, i, s, base)) : symbols!(out, s.text, s.col, face(base, s), s.link)
  end
  out
end

# --- callouts ------------------------------------------------------------------------------
#
# A callout is a quote that stands out: a note, a tip, a warning. Its first
# line names its kind, as GitHub writes it: `> [!NOTE]`. The lines of the quote
# under that one are the callout's text. The page shows the first line as the
# kind's icon and its name, like "Note", in the kind's colour. Words after the
# `]` are a title, and show in place of the name. The callout's lines have a
# line of that colour down their left, and a little of the colour behind them.
# `markdown.jl` reads the lines.

"The icon of each kind of callout"
const CALLOUT_ICONS = (note="info-circle", tip="lightbulb", important="exclamation-square", warning="exclamation-triangle", caution="exclamation-octagon")

"The colour of a kind of callout. Each is a colour that code has in this page's colours."
callout_colour(kind) =
  kind == "tip" ? colours.string : kind == "important" ? colours.keyword : kind == "warning" ? colours.number :
  kind == "caution" ? removed_colour() : colours.call

"What a callout of this kind is called when it has no title of its own, like \"Note\""
callout_name(kind) = uppercasefirst(kind)

"The colour behind the lines of a callout: a little of its kind's colour over the page"
callout_tint(kind) = (c = RGBA(callout_colour(kind)); RGBA(c.r, c.g, c.b, dark_page() ? 0.12 : 0.08))

"What shows in place of the `> [!NOTE]` that starts a callout: the kind's icon, and the kind's name when `name` isn't empty"
@def mutable struct CalloutMark <: SemanticUI
  kind::String = "note"
  name::String = ""
  face::Face = Face("", "", TEXT_SIZE, colours.ink, false)   # of the name
end

const CALLOUT_GAP = 0.45   # the room between the icon and the words after it, as a part of the size of the text

icon_size(m::CalloutMark) = px(round(num(m.face.size) * 0.95))
wide(m::CalloutMark) = icon_size(m) + m.face.size * CALLOUT_GAP + measure(m.face, m.name)

describe(m::CalloutMark) =
  Row(fixed(wide(m)), Alignment.Center, justify=Alignment.Start, child_gap=m.face.size * CALLOUT_GAP,
    Icon(getproperty(CALLOUT_ICONS, Symbol(m.kind)), size=icon_size(m), color=m.face.color),
    (isempty(m.name) ? () : (Box(Text(m.name, size=m.face.size, family=m.face.family, subfamily=m.face.style, color=m.face.color, wrap=WrapMode.none)),))...)

inputs(m::CalloutMark) = (m.kind, m.name, m.face)

"""
The piece that stands for what starts the first line of a callout, in text
drawn in `base`. `titled` is true when the line has a title of its own after
it. The piece then shows only the icon.
"""
callout_mark(e, line::Line, base::Face, titled::Bool) = begin
  m = CalloutMark(kind=line.lang, name=titled ? "" : callout_name(line.lang), face=base)
  # It's part of its line, which is laid out once and kept. It can reach the document, and it isn't one of the document's children.
  setfield!(m, :parent, node!(Document, e, :document))
  piece(callout_name(line.lang), 0, base, atomic=true, n=line.prefix, node=Inline(m, wide(m), base.size * 1.2))
end

# --- inline code -------------------------------------------------------------------------
#
# !`code` in a line of text is inline code. The page runs the code and shows
# what it makes in place of the code: a node, like a switch or a file path, or
# any other value as text. The code shows again while the caret is on its line.

const INLINE = "!`"   # what inline code starts with

"The lines of `b` that have inline code"
inline_lines(e, b::Buffer) = get!(e.flows, (:inline, b.path, b.version)) do
  [i for (i, text) in enumerate(b.lines) if occursin(INLINE, text)]
end

"""
Which one of the document's pieces of inline code with this code the span `s`
of line `i` is: 1 for the first. Two pieces with the same code each make a
node of their own.
"""
ordinal(e, i::Int, s::Span) = ordinal(e, i, s.col, s.text)

"Which one of the document's pieces of inline code `code` the one whose code starts at column `col` of line `i` is"
ordinal(e, i::Int, col::Int, code::AbstractString) = begin
  b = e.buf
  marked = INLINE * code * "`"
  1 <= i <= length(b.lines) || return 1
  before = sum(j -> count(marked, b.lines[j]), Iterators.filter(<(i), inline_lines(e, b)), init=0)
  before + count(marked, head(b.lines[i], max(0, col - length(INLINE)))) + 1
end

# How many times a sum in a line of text has run. What's worked out from what the sums show, like the
# numbers that a chart draws from a table, is worked out again when this changes.
const sums_run = Ref(0)

"""
The text of a cell of a table, with what each sum in it shows in place of its
code: "\$!`price`" is "\$12". `i` is the cell's line, and `col` the column
where `text` starts in it. A sum that hasn't run yet, that went wrong or that
made a node shows nothing. This runs no sum, as the sums run in the order of
the page, and `sums_run` says when they've run again.
"""
sums_shown(e, i::Int, col::Int, text::AbstractString) = begin
  occursin(INLINE, text) || return text
  out = IOBuffer()
  at = 1
  for m in eachmatch(r"!`([^`]+)`", text)
    print(out, text[at:prevind(text, m.offset)])
    code = String(m[1])
    made = get(e.nodes, (:inline, e.buf.path, code, ordinal(e, i, col + length(text, 1, m.offset) + 1, code)), nothing)
    made isa Tuple && !made[2] && print(out, made[1])
    at = m.offset + ncodeunits(m.match)
  end
  print(out, text[at:end])
  String(take!(out))
end

"""
What the `n`th piece of inline code `code` of the document made. It's a Shown
when the code made a node. For any other value it's the value as text, and
true if that text says what went wrong.
"""
made(e, code::String, n::Int) = begin
  foreign(e.buf.path) && return (code, false)   # a page from a web server runs no code, and nor does an email, so the code itself shows
  key = (:inline, e.buf.path, code, n)
  get!(e.nodes, key) do
    sums_run[] += 1
    out = evaluate(e, code, key=key, inline=true)
    out isa Tuple && (keep_value!(e, code, n, out[2]); return out)
    shown = Shown(value=out, inline=true)
    out isa SemanticUI && own!(shown, out)
    shown
  end
end

"Lay out what inline code made, to learn how much room it takes in its line"
fit(e, shown) = begin
  # It's part of its line. It can reach the document, and it isn't one of the document's children:
  # a line is laid out once and kept, so the document isn't given it again on each frame.
  shown.parent === nothing && setfield!(shown, :parent, node!(Document, e, :document))
  concrete = describe(Row(Alignment.Start, geometry(shown)), (e.width, 9999px))
  # A node with no width of its own, like a slider, takes all the room it's given. In a line it gets this much.
  w = concrete.width < 16px ? INLINE_W * e.zoom : concrete.width
  Inline(shown, min(w, e.width), concrete.height)
end

const INLINE_W = 180px   # of a node in a line of text that has no width of its own, before the text is zoomed

"The piece that stands for the inline code of span `s`, on line `i`, in text drawn in `base`"
inline(e, i::Int, s::Span, base::Face) = begin
  out = made(e, s.text, ordinal(e, i, s))
  n = length(s.text)
  out isa Tuple || return piece(s.text, s.col, base, atomic=true, n=n, node=fit(e, out))
  text, failed = out
  # A value between == and ==, or in the words that a comment is about, has the highlighter's colour behind it too
  piece(text, s.col, Face(base, color=failed ? colours.accent : base.color, highlit=s.highlit), atomic=true, n=n, words=true)
end

const LONGEST_VALUE = 200   # characters of a value that inline code shows as text

"""
A value as the text that inline code shows for it. A number reads the way a
sheet shows it: 28.8 and not 28.799999999999997, with or without a unit.
"""
said(value) = begin
  text = value isa AbstractString ? String(value) : value === nothing ? "nothing" : Base.invokelatest(shown, value)
  text = replace(text, r"\s*\n\s*" => " ")
  length(text) > LONGEST_VALUE ? first(text, LONGEST_VALUE) * "…" : text
end

# The page's fonts have no ⌘, ⌫ or arrows, so those characters are drawn in one that does
const SYMBOLS = r"[⌘⌥⇧⌃⏎⇥⌫⌦⎋←→↑↓]+"

"""
Add `text` to `out`, with its keyboard symbols in a font that has them. That's
Lucida Grande, and for a symbol that it hasn't got, like ⏎, a font that macOS picks.
"""
symbols!(out, text, col, face, link="") = begin
  at = 1
  add(part, f) = isempty(part) || (push!(out, piece(String(part), col, f; link)); col += length(part))
  for m in eachmatch(SYMBOLS, text)
    add(SubString(text, at, prevind(text, m.offset)), face)
    for (part, f) in runs(m.match, Face(face, family=SYMBOL_FONT, style=""))
      add(part, f)
    end
    at = m.offset + ncodeunits(m.match)
  end
  add(SubString(text, at), face)
  out
end

"The first and last line of the code block that line `i` is in, with the lines that open and close it"
codeblock(b::Buffer, i::Int) = begin
  ks = kinds(b)
  s = t = i
  while s > 1 && !(ks[s].kind == Kind.fence && ks[s].level == 0); s -= 1 end
  while t < length(ks) && !(ks[t].kind == Kind.fence && ks[t].level == 1 && t > s); t += 1 end
  (s, t)
end

"""
True when the caret is in the code block that line `i` is in, and the selection
doesn't reach out of the block. A selection that goes through a block leaves it
as it reads.
"""
incode(b::Buffer, i::Int) = begin
  caretless(b) && return false
  s, t = codeblock(b, i)
  # A block that the caret is on as a whole shows as what it makes
  s <= b.caret[1] <= t && s <= b.anchor[1] <= t && picked(b) === nothing
end

# --- rich text and plain text ----------------------------------------------------------------
#
# A page is written in one of two ways. A click on the snake or the ladder in the
# top bar changes from one to the other, and so does ⌘E. You can change the text in both.
# The two are levels of abstraction. Plain text is the low level: the page's
# symbols. Rich text is the high level: the graphics that the symbols make.
#
# As rich text, a line shows the way it reads: bold words are bold, and the
# characters that make them bold don't show. A diagram shows as a diagram. A
# line stays that way when the caret comes onto it, so the caret has rules:
#
#   - It can't stop among characters that don't show, like the ** of bold
#     text or the # of a heading. A key that moves it goes over them.
#   - It stays on the side of them that it came from. After **bold**, a caret
#     that came from the left is in the bold text, and what's typed there is
#     bold. A caret that came from the right is after the bold text.
#   - It doesn't go into a part of the page that shows as one thing: a
#     diagram, a form, a picture, a line across the page. It goes onto the
#     part as a whole, and a line goes round the part. Return then gives the
#     part the keyboard, so you can type in a field of a form. ⌫ takes the
#     part away. ↑ and ↓ go on to the line before it and the line after it.
#   - It steps over the ``` lines of a code block, which don't show.
#
# Only a part that's being typed shows its markup: the caret is on it because
# its text was typed there, and it stays as text until the caret leaves.
# Without that, a line like ```mermaid could never be typed.
#
# As plain text, the part of the page nearest the caret shows its markup. In a
# line of text, that's the run that the caret is in: bold words, a link, inline
# code, a formula. With the caret in plain words, no run shows its markup. With
# the caret in what starts the line, like the # of a heading, that shows. The
# rest of the line still reads as rich text, so a long paragraph keeps its look
# while it's changed. The same goes for the cell of a table. A line that shows
# as one thing, like a picture, shows all its markup, and so does the whole of a
# code block or a diagram. The caret goes anywhere: the run that it goes into
# shows its markup, so it never stops among characters that don't show. Every
# other part of the page still shows as rich text.

"The kinds of line whose text shows without its markup in rich text"
const TEXT_KINDS = (Kind.paragraph, Kind.heading, Kind.bullet, Kind.ordered, Kind.todo, Kind.blockquote)

"True when the page is written as rich text: it's a document, and the part with the caret doesn't show its markup"
rich(b::Buffer) = !b.plain && b.view == :markdown

"True when the caret is on line `i`, and the selection doesn't reach another line"
alone(b::Buffer, i::Int) = !caretless(b) && i == b.caret[1] == b.anchor[1]

"True when line `i` holds only a picture, a sound or a video"
pictured(b::Buffer, i::Int) = kinds(b)[i].kind == Kind.paragraph && occursin("![", b.lines[i]) && occursin(PICTURE_LINE, b.lines[i])

"""
True when all of line `i` shows its markup. It has to have the caret. As plain
text that's enough, unless it's a line of text, which shows the markup of one
run at a time: see `raw_part`. As rich text, the line also has to be one that
shows as something other than its text, which is only so while it's typed: a
``` line, a line across the page, a picture, a table's line of dashes.
"""
israw(b::Buffer, i::Int) =
  alone(b, i) && (!rich(b) ? !by_runs(b, i) : (picked(b) === nothing && (kinds(b)[i].kind in (Kind.fence, Kind.rule, Kind.table) || pictured(b, i) || maths_line(b, i) || transcludes(b, i) || only_id(b.lines[i]))))

"""
True when line `i`, as plain text, shows its markup a run at a time, and not
all at once: a line of text, but not one that shows as one thing, like a
picture or a formula on a line of its own.
"""
by_runs(b::Buffer, i::Int) =
  b.view == :markdown && kinds(b)[i].kind in TEXT_KINDS && !(pictured(b, i) || maths_line(b, i) || transcludes(b, i) || only_id(b.lines[i]))

"""
The columns of line `i` that show their markup as plain text, as a list of the
first and last column of each run, or nothing when none do. They're the run
that the caret is in, like bold words, a link or inline code, or what starts
the line when the caret is in that, like the # of a heading. The rest of the
line reads as rich text. With a selection, the run at its other end shows its
markup too, so that neither end moves. It's always nothing as rich text, and
for a line that shows all its markup: see `israw`.
"""
raw_part(b::Buffer, i::Int) = begin
  (alone(b, i) && !rich(b) && b.view == :markdown) || return nothing
  if kinds(b)[i].kind == Kind.table
    # A row of a table that's drawn as a grid shows the run that the caret is in, inside its cell
    run = table(b, i)
    (run !== nothing && i != run[1] + 1) || return nothing
  else
    by_runs(b, i) || return nothing
  end
  lead, runs = marked_runs(b, i)
  out = Tuple{Int,Int}[]
  for col in (b.anchor[2], b.caret[2])
    # What starts the line shows while the caret is in it. At its end the caret is at the start of the text, which shows anyway.
    found = col < lead ? [(0, lead)] : runs_at(runs, col)
    foreach(r -> r in out || push!(out, r), found)
  end
  isempty(out) ? nothing : out
end

"True when the columns `lo` to `hi` of a line show their markup, where `open` is what `raw_part` gave for the line"
markup_shows(open, lo::Int, hi::Int) = open !== nothing && any(r -> r[1] <= lo && hi <= r[2], open)

"""
The runs of line `i` that show their markup as one, each as the column where
its markup starts and the column where it ends: bold words, a link, inline
code, a formula, the number of a footnote, a comment, and markup that's alone,
like the \\ before a *. A run inside another comes before it. Before them, the
column where the line's text starts after what starts the line, like the # of
a heading, or 0 when nothing that starts the line is hidden in rich text.
"""
marked_runs(b::Buffer, i::Int) = begin
  start, ss = richspans(b, i)
  line = kinds(b)[i]
  lead = line.kind == Kind.paragraph && start == line.prefix ? 0 : start
  out = Tuple{Int,Int}[]
  opened = Int[]
  for (k, s) in enumerate(ss)
    s.markup || continue
    if !isempty(opened) && closes_run(ss[last(opened)].text, s.text)
      push!(out, (ss[pop!(opened)].col, s.col + length(s.text)))
    elseif s.text == "\\" || occursin(r"^\s*\^", s.text)
      # The \ before a character, and the name of a block at the end of its line, are runs by themselves
      push!(out, (s.col, s.col + length(s.text)))
    else
      push!(opened, k)
    end
  end
  # Markup that's never closed is a run by itself
  foreach(k -> push!(out, (ss[k].col, ss[k].col + length(ss[k].text))), opened)
  (lead, out)
end

"True when the markup `c` closes a run that the markup `o` opened, as `spans` reads them"
closes_run(o::AbstractString, c::AbstractString) =
  o == "[" ? startswith(c, "](") : o == "[^" ? c == "]" : o == "!`" ? c == "`" : startswith(o, "[[") ? endswith(c, "]]") :
  o == "{==" ? c == "==}" : o == "{>>" ? c == "<<}" : o == c

"""
The runs among `runs` that show their markup while the caret is at `col`: the
innermost one that it's inside, or each one that it's at an edge of. At an
edge, the run's markup shows which side of it the caret is on.
"""
runs_at(runs, col::Int) = begin
  inside = filter(r -> r[1] < col < r[2], runs)
  isempty(inside) ? filter(r -> r[1] == col || r[2] == col, runs) : [argmin(r -> r[2] - r[1], inside)]
end

"""
The spans of line `i` as rich text reads them: the text after what starts the
line, or the text of each cell of a row of a table. `start` is the column
where that text starts.
"""
richspans(b::Buffer, i::Int) = begin
  text, line = b.lines[i], kinds(b)[i]
  if line.kind in TEXT_KINDS
    note = line.kind == Kind.paragraph ? match(NOTE, text) : nothing
    start = note === nothing ? line.prefix : length(note.match)
    return (start, spans(rest(text, start), start))
  end
  out = Span[]
  line.kind == Kind.table && table(b, i) !== nothing || return (0, out)
  for c in tablecells(text)
    append!(out, spans(rest(head(text, c.hi), c.lo), c.lo))
  end
  (0, out)
end

"""
The parts of line `i` that take no room in rich text, each as the column it
starts at and the column it ends at: markup like **, and what starts a heading,
a list item or a quote. Two that touch are one. The caret can't stop inside
one. The part that starts a line starts at -1, so that column 0 is inside it.
"""
unseen(b::Buffer, i::Int) = begin
  start, ss = richspans(b, i)
  out = Tuple{Int,Int}[]
  kinds(b)[i].kind == Kind.paragraph && start == kinds(b)[i].prefix || start == 0 || push!(out, (-1, start))
  for s in ss
    # A comment, like %%note%%, takes no room either
    (s.markup || s.comment) || continue
    a, z = s.col, s.col + length(s.text)
    !isempty(out) && last(out)[2] == a ? (out[end] = (last(out)[1], z)) : push!(out, (a, z))
  end
  out
end

"The parts of line `i` that each show as one thing in rich text: the name of a footnote, inline code that runs, and a formula"
wholes(b::Buffer, i::Int) =
  Tuple{Int,Int}[(s.col, s.col + length(s.text)) for s in richspans(b, i)[2]
                 if !s.markup && (s.live || (s.math && Maths.available()) || startswith(s.link, '^')) && length(s.text) > 1]

"The first column of line `i` where the caret can stop in rich text: where the text of a heading or a list item starts"
first_stop(b::Buffer, i::Int) = begin
  rich(b) || return 0
  hidden = unseen(b, i)
  isempty(hidden) || first(hidden)[1] >= 0 ? 0 : first(hidden)[2]
end

"""
The first and last line of the part of the page that line `i` is in, when the
caret steps over that part in rich text. That's a part that shows as one
thing: a block that shows as a diagram, a plan, a chart and so on, the front
matter, a formula on lines of its own, a picture, a line across the page, a
table's line of dashes. A ``` line is such a part by itself. Nothing for a
line of text or of code.
"""
solid(b::Buffer, i::Int) = begin
  # A `columns` block that takes no room is such a part, with the empty lines after it that take none
  fold = column_fold(b, i)
  fold === nothing || return fold
  # So is a comment on lines of its own, with the empty lines after it that take no room
  fold = comment_fold(b, i)
  fold === nothing || return fold
  ks = kinds(b)
  k = ks[i]
  if k.kind in (Kind.fence, Kind.code)
    s, t = codeblock(b, i)
    lang = ks[s].lang
    closed = t > s && ks[s].kind == Kind.fence && ks[t].kind == Kind.fence && ks[t].level == 1
    whole = closed && (lang in (MATTER, TOML_MATTER, TAKEOFF, SCHEDULE, LIVE) || haskey(BLOCKS, lang) ||
                       (lang == DIAGRAM && isdiagram(join(b.lines[s+1:t-1], "\n"))) ||
                       (lang == MATH && has_maths(join(b.lines[s+1:t-1], "\n"))) || block_source(b, s) !== nothing)
    return whole ? (s, t) : k.kind == Kind.fence ? (i, i) : nothing
  end
  (k.kind == Kind.rule || pictured(b, i) || maths_line(b, i) || transcludes(b, i)) && return (i, i)
  if k.kind == Kind.table
    run = table(b, i)
    run !== nothing && i == run[1] + 1 && return (i, i)
  end
  nothing
end

"""
True when the caret can go to line `i` from line `from`. It can't go into a
part that shows as one thing, but it can move about in one that it's already
in, which shows as text because it's being typed. A ``` line only has the
caret while it's typed.
"""
free(b::Buffer, i::Int, from::Int) = begin
  run = solid(b, i)
  run === nothing && return true
  kinds(b)[i].kind == Kind.fence ? from == i : run[1] <= from <= run[2]
end

"""
The first and last line of the part of the page that line `i` is in, when the
caret can be on that part as a whole: a block that shows as a diagram, a form,
a plan and so on, the front matter, a picture, a line across the page. Nothing
for any other line. A ``` line of a code block isn't such a part, and nor is
a table's line of dashes: neither shows, so the caret steps over them.
"""
part(b::Buffer, i::Int) = begin
  run = solid(b, i)
  run === nothing && return nothing
  k = kinds(b)[i].kind
  # A `columns` block that takes no room doesn't show either, and nor does a comment on lines of its own
  k == Kind.table || (k == Kind.fence && run[1] == run[2]) || column_fold(b, i) !== nothing || comment_fold(b, i) !== nothing ? nothing : run
end

"True when `text`, a line of text, holds only a comment, like %%note%%"
comment_only(text::AbstractString) =
  occursin("%%", text) && (ss = spans(strip(text)); !isempty(ss) && all(s -> s.comment || (s.markup && s.text == "%%"), ss))

"""
The lines of a comment, when line `i` is one of them: the first and the last.
That's a comment on lines of its own, or a line that holds only a comment.
Nothing for any other line. The empty lines after it are part of it too, as
many as there are empty lines before it, so the room that's left where it
was is the room between two blocks of the page. As rich text, none of them
take room, and the caret steps over them. See `column_fold`, which does the
same for a `columns` block.
"""
comment_fold(b::Buffer, i::Int) = begin
  b.view == :markdown || return nothing
  ks = kinds(b)
  lone(k) = ks[k].kind == Kind.paragraph && comment_only(b.lines[k])
  j = i
  if ks[i].kind == Kind.blank
    # An empty line is one of them when the comment is the first thing over it
    while j > 1 && ks[j].kind == Kind.blank
      j -= 1
    end
    ((ks[j].kind == Kind.fence && ks[j].level == 1 && ks[j].lang == COMMENT) || lone(j)) || return nothing
  elseif !(ks[i].kind in (Kind.fence, Kind.code) && ks[i].lang == COMMENT) && !lone(i)
    return nothing
  end
  s, t = ks[j].kind == Kind.paragraph ? (j, j) : codeblock(b, j)
  bare(k) = 1 <= k <= length(ks) && ks[k].kind == Kind.blank
  n = 0
  while bare(s - n - 1) && bare(t + n + 1)
    n += 1
  end
  i <= t + n ? (s, t + n) : nothing
end

"""
The first and last line of the part of the page that the caret is on as a
whole, or nothing when it's in text. The caret is on a part when it's at the
very start of the part's first line, in rich text, with nothing selected. The
part then shows as what it makes, with a line round it, and not as its code.
"""
picked(b::Buffer) = begin
  key = (b.version, b.caret, b.anchor, b.plain, b.reading)
  key == b.picked_for && return b.picked
  i, col = b.caret
  run = rich(b) && col == 0 && alone(b, i) && i <= length(b.lines) ? part(b, i) : nothing
  b.picked_for = key
  b.picked = run !== nothing && run[1] == i ? run : nothing
end

"""
The first line after `i`, or with `by` of -1 before it, that the caret can go
to from line `from`: a line of text, or a line of a part that the caret can be
on as a whole. It's 0, or a line past the last, when there's none.
"""
step_over(b::Buffer, i::Int, by::Int, from::Int) = begin
  while 1 <= i <= length(b.lines) && !free(b, i, from) && part(b, i) === nothing
    s, t = solid(b, i)
    i = by > 0 ? t + 1 : s - 1
  end
  i
end

"Where the caret goes in rich text when it's sent to `p` from `from`, going in the direction `by`: the nearest place where it can stop, or the start of a part that it goes onto as a whole"
settle_rich(b::Buffer, p::Pos, by::Int, from::Pos) = begin
  i, col = p
  if !free(b, i, from[1])
    found = false
    for d in (by < 0 ? (-1, 1) : (1, -1))
      j = step_over(b, i, d, from[1])
      1 <= j <= length(b.lines) || continue
      # The caret goes onto a part like a diagram as a whole: to the start of its first line
      free(b, j, from[1]) || return (part(b, j)[1], 0)
      i, col, by, found = j, d > 0 ? 0 : length(b.lines[j]), d, true
      break
    end
    found || return p   # the page has nothing but lines that don't show
  end
  for (a, z) in Iterators.flatten((unseen(b, i), wholes(b, i)))
    a < col < z || continue
    col = a < 0 || by > 0 ? z : by < 0 ? a : col - a < z - col ? a : z
  end
  (i, col)
end

"""
Look at where the caret is, before the page is laid out. As rich text, a caret
that something put among characters that don't show goes to the nearest place
where it can stop. In a file that was just opened, and after a change from
plain text to rich text, a caret that's in a part of the page that shows as
one thing goes onto the part as a whole. At any other time it stays in such a
part, which then shows as text: a key or a click can't take it there, so
something meant to. A click with ⌥ held does, and so does the menu that
inserts a block.
"""
stand!(b::Buffer) = begin
  b.caret == b.stood && return b
  # The caret is on no line while the page is drawn for paper, so it has nowhere to stand
  b.caret[1] < 1 && return b
  if rich(b) && !selecting(b) && isempty(b.others)
    b.caret = b.anchor = b.stood === nothing ? settle(b, b.caret, 1, from=(0, 0)) :
                                               settle(b, b.caret, cmp(b.caret, b.stood), from=b.caret)
  end
  b.stood = b.caret
  b
end

"""
The pairs of markup in `ss`, the spans of a line: for each, the place in `ss` of
the span that opens it and of the one that closes it, like the two ** of bold
text. A pair that's inside another comes before it.
"""
markpairs(ss) = begin
  out = Tuple{Int,Int}[]
  open = Int[]
  for (k, s) in enumerate(ss)
    (s.markup && s.text != "\\") || continue
    o = isempty(open) ? "" : ss[last(open)].text
    closes = !isempty(o) && (o == "[" ? startswith(s.text, "](") : o == "[^" ? s.text == "]" : o == "!`" ? s.text == "`" : o == s.text)
    closes ? push!(out, (pop!(open), k)) : push!(open, k)
  end
  out
end

"""
Which characters of line `i` go when the columns `x` to `y` of it are deleted
as rich text: true for each one that goes. The text between goes. Markup
stays if it still has text to mark, so bold text that loses its last words
is still bold, and it goes with the last of its text. With `lead`, what starts
the line goes too: that's for a line that's joined to the one before it.
"""
cutmask(b::Buffer, i::Int, x::Int, y::Int; lead=false) = begin
  text, line = b.lines[i], kinds(b)[i]
  n = length(text)
  gone = falses(n)
  if !(line.kind in TEXT_KINDS || (line.kind == Kind.table && table(b, i) !== nothing))
    gone[x+1:y] .= true
    return gone
  end
  start, ss = richspans(b, i)
  mark = falses(n)
  lead && (gone[1:min(start, y)] .= true)
  # Text that no span holds, like the | between two cells, goes as it would in plain text
  held = falses(n)
  for s in ss
    held[s.col+1:s.col+length(s.text)] .= true
    s.markup ? (mark[s.col+1:s.col+length(s.text)] .= true) : (gone[max(s.col, x)+1:min(s.col + length(s.text), y)] .= true)
  end
  for c in max(x, start)+1:y
    held[c] || (gone[c] = true)
  end
  # The \ before a character goes with the character
  for s in ss
    s.markup && s.text == "\\" && s.col + 2 <= n && gone[s.col+2] && (gone[s.col+1] = true)
  end
  for (o, c) in markpairs(ss)
    from, to = ss[o].col + length(ss[o].text), ss[c].col
    all(k -> mark[k] || gone[k], from+1:to) || continue
    any(k -> gone[k], from+1:to) || continue   # nothing between them was deleted, so they stay
    gone[ss[o].col+1:from] .= true
    gone[to+1:to+length(ss[c].text)] .= true
  end
  gone
end

"""
What to change to delete the text from `lo` to `hi` as rich text: the place
where the change starts, the place where it ends, and the markup between them
that stays. The change can reach past `lo` and `hi`, to take the markup of
text that's all deleted. `typed` is true when something is typed in its place.
"""
richcut(b::Buffer, lo::Pos, hi::Pos; typed=false) = begin
  kept(i, gone, x, y) = String([c for (k, c) in enumerate(b.lines[i]) if x < k <= y && !gone[k]])
  reach(gone, x, y) = (min(x, something(findfirst(gone), x + 1) - 1), max(y, something(findlast(gone), y)))
  if lo[1] == hi[1]
    gone = cutmask(b, lo[1], lo[2], hi[2])
    x, y = reach(gone, lo[2], hi[2])
    return ((lo[1], x), (hi[1], y), kept(lo[1], gone, x, y))
  end
  # A selection that takes all the text of its first line takes what starts that line too, like the # of a
  # heading. The last line then keeps what starts it, unless its text all goes. Any other selection joins
  # what's left of the last line to the first, without what starts the last. So does one that's typed over:
  # what's typed is in the first line, with what starts it.
  whole = !typed && lo[2] <= first_stop(b, lo[1])
  top = whole ? trues(length(b.lines[lo[1]])) : cutmask(b, lo[1], lo[2], length(b.lines[lo[1]]))
  bottom = cutmask(b, hi[1], 0, hi[2], lead=!whole || hi[2] >= length(b.lines[hi[1]]))
  x = whole ? 0 : reach(top, lo[2], lo[2])[1]
  _, y = reach(bottom, hi[2], hi[2])
  ((lo[1], x), (hi[1], y), kept(lo[1], top, x, length(b.lines[lo[1]])) * kept(hi[1], bottom, 0, y))
end

"""
What Return adds in rich text to keep the look of each half of the text that
the caret is in: the markup that closes what's open at the caret, to end the
first line, and the markup that opens it again, to start the next. A caret
at the very start or end of bold text goes outside it first, so neither line
gets bold text with nothing in it.
"""
halves!(b::Buffer) = begin
  i, col = b.caret
  (rich(b) && !selecting(b) && kinds(b)[i].kind in TEXT_KINDS) || return ("", "")
  _, ss = richspans(b, i)
  found = markpairs(ss)
  inside((o, c)) = (ss[o].col + length(ss[o].text), ss[c].col)
  moved = true
  while moved
    moved = false
    for p in found
      from, to = inside(p)
      col == to && to > from && (col = to + length(ss[p[2]].text); moved = true)
      col == from && to > from && (col = ss[p[1]].col; moved = true)
    end
  end
  b.caret = b.anchor = (i, col)
  around = [p for p in found if inside(p)[1] < col < inside(p)[2]]
  (join(ss[c].text for (_, c) in around), join(ss[o].text for (o, _) in reverse(around)))
end

"Lay out line `i` of the document"
flow(e, i::Int, raw::Bool=israw(e.buf, i)) = begin
  # A line in a column of the page is laid out for the column's width. See "blocks of the page side by side".
  column = column_at(e, i)
  column === nothing || return column_flow(e, column, i, raw)
  text, line = e.buf.lines[i], kinds(e.buf)[i]
  if e.buf.view == :code
    # A line of a file of code is laid out as a line of a file that's only shown is. Inside a docstring its colours differ.
    spare_flows!(e)
    return get!(() -> file_line(e, text, line, i), e.flows, (:file, text, line, string_opens(e.buf)[i]))
  end
  # The lines that open and close a code block show while the caret is in the block. As rich text, one only shows while it's typed.
  # A comment's first and last lines have its words, so they show with the rest of it
  line.kind == Kind.fence && (raw = rich(e.buf) && line.lang != COMMENT ? israw(e.buf, i) : incode(e.buf, i))
  # As plain text, a line of text shows the markup of the run that the caret is in, and the rest of it reads as rich text
  open = raw ? nothing : raw_part(e.buf, i)
  build() = laid(e, text, line, raw, i; open)
  # What inline code made can change its size, so its line is laid out again each time
  !raw && occursin(INLINE, text) && !(line.kind in (Kind.code, Kind.fence, Kind.rule)) && return build()
  spare_flows!(e)
  # A footnote's number comes from the rest of the document, which `notes` reads once for each
  # version of it. So the line is kept for that version, and laid out again after a change.
  !raw && occursin("[^", text) && return get!(build, e.flows, (text, line, raw, open, :notes, e.buf.path, e.buf.version))
  # On another day than today, the box of a to-do item shows the tick of that day, so the line is kept with it
  then = line.kind == Kind.todo && !raw ? ticked_then(e, i) : nothing
  then === nothing || return get!(build, e.flows, (text, line, raw, open, :then, then))
  # A line of code inside a docstring has other colours than the same line outside it
  line.kind == Kind.code && return get!(build, e.flows, (text, line, raw, string_opens(e.buf)[i]))
  get!(build, e.flows, (text, line, raw, open))
end

"""
Lay out `text`, line `i` of the document, which is a line of the kind `line`,
for a page that's `wide`. `open` is what `raw_part` gives for the line.
"""
laid(e, text, line::Line, raw::Bool, i::Int, wide=e.width; open=nothing) = begin
  base = face(e, line)
  ps = spare(pieces(e, text, line, raw, i; open))
  k = line.kind
  # A hidden ``` line leaves a little room at the top or bottom of its block, and so does a line that only names the block over it
  lh = k == Kind.heading ? base.size * 1.35 : body(e).size * ((k == Kind.fence || (k == Kind.paragraph && only_id(text))) && !raw ? 0.6 : 1.65)
  # Lines of bigger code are further apart. The lines of a comment are laid out as text.
  code = k in (Kind.code, Kind.fence) && line.lang != COMMENT
  code && (lh *= e.code_scale / CODE_SCALE)
  left = code ? BLOCK_X : k == Kind.blockquote ? QUOTE_X : 0px
  # Lines that a list item wraps onto start under its text, not under its bullet
  hang = k in (Kind.bullet, Kind.ordered, Kind.todo) ? sum(p -> measure(p.face, p.text), ps[1:min(end, line.level > 0 ? 2 : 1)], init=0px) : left
  above = k == Kind.heading ? lh * 0.3 : 0px
  below = k == Kind.heading ? lh * 0.12 : 0px
  f = wrap(ps, wide; lh, size=base.size, left, hang, above, below, kind=k, raw)
  # A blog's site has its first heading in the middle of the page
  k == Kind.heading && line.level == 1 && e.look == :site ? align(f, wide, :center) : f
end

"Forget every layout, after something that changes how all the text is drawn"
restyle!(e) = (empty!(e.flows); e.reveal = true; e)

# --- tables ----------------------------------------------------------------------------
#
# A table is a line of cells, a line of dashes, then more lines of cells. It's
# drawn as a grid, and the caret moves from cell to cell. The line of dashes
# isn't drawn. If the caret gets onto it, the table shows as plain lines.

"The first and last line of the table that line `i` is part of, or nothing"
table(b::Buffer, i::Int) = begin
  ks = kinds(b)
  ks[i].kind == Kind.table || return nothing
  s = t = i
  while s > 1 && ks[s-1].kind == Kind.table; s -= 1 end
  while t < length(ks) && ks[t+1].kind == Kind.table; t += 1 end
  t > s && isdivider(b.lines[s+1]) ? (s, t) : nothing
end

"The lines of a table that are rows of cells"
tablerows((s, t)) = [s; s+2:t]

"The cells of the row that `p` is in, when that row is drawn in a grid or a sheet"
rowcells(b::Buffer, p::Pos) = begin
  insheet(b, p[1]) && return sheetcells(b.lines[p[1]])
  inspread(b, p[1]) && return spreadcells(b.lines[p[1]])
  run = table(b, p[1])
  (run === nothing || p[1] == run[1] + 1) ? Cell[] : tablecells(b.lines[p[1]])
end

within(c::Cell, col::Int) = c.lo <= col <= c.limit

"The cell that `p` is in, or nothing"
cellat(b::Buffer, p::Pos) = begin
  cs = rowcells(b, p)
  i = findfirst(c -> within(c, p[2]), cs)
  i === nothing ? nothing : cs[i]
end

"Which of `cs` column `col` is in, or is nearest to"
nearest(cs, col::Int) = argmin(i -> within(cs[i], col) ? 0 : min(abs(col - cs[i].lo), abs(col - cs[i].limit)), eachindex(cs))

"""
Where the caret goes when it's sent to `p`. In a table that's the same place
if `p` is in a cell. Otherwise it's the next cell in the direction `by`, or the
nearest cell when `by` is 0.
"""
settle(b::Buffer, p::Pos, by::Int=0; from::Pos=b.caret) = begin
  rich(b) || return settle_cells(b, p, by)
  # A caret that's on a part as a whole isn't in the part's text, so it can't move about in that text
  from == b.caret && picked(b) !== nothing && (from = (0, 0))
  # As rich text the caret also keeps off what doesn't show. A place that one rule gives can break the other, so both look again.
  for _ in 1:4
    q = settle_rich(b, settle_cells(b, p, by), by, from)
    q == p && break
    p = q
  end
  p
end

"Where the caret goes when it's sent to `p`, by the rules of a table, a sheet and a spreadsheet"
settle_cells(b::Buffer, p::Pos, by::Int=0) = begin
  run = sheet(b, p[1])
  run === nothing || return settle(b, run, p, by)
  run = spread(b, p[1])
  run === nothing || return settle(b, run, p, by, spreadcells)
  run = table(b, p[1])
  run === nothing && return p
  s, t = run
  i, col = p
  if i == s + 1
    # The line of dashes. Step over it, unless that's where a click put the caret.
    by == 0 && return p
    j = by < 0 ? s : s + 2
    return j > t ? (t < length(b.lines) ? (t + 1, 0) : p) : settle_cells(b, (j, col))
  end
  cs = tablecells(b.lines[i])
  (isempty(cs) || any(c -> within(c, col), cs)) && return p
  rows = tablerows(run)
  r = findfirst(==(i), rows)
  if by < 0
    c = findlast(c -> c.limit < col, cs)
    c === nothing || return (i, cs[c].hi)
    r > 1 && return row_edge(b, rows[r-1], 1)
    s > 1 ? line_end(b, s - 1) : (i, cs[1].lo)
  elseif by > 0
    c = findfirst(c -> c.lo > col, cs)
    c === nothing || return (i, cs[c].lo)
    r < length(rows) && return row_edge(b, rows[r+1], -1)
    t < length(b.lines) ? (t + 1, 0) : (i, cs[end].hi)
  else
    c = cs[nearest(cs, col)]
    (i, clamp(col, c.lo, c.limit))
  end
end

"The start of the first cell of row `i`, or with `by` of 1 the end of its last cell"
row_edge(b::Buffer, i::Int, by::Int) = begin
  cs = tablecells(b.lines[i])
  isempty(cs) ? (i, 0) : by < 0 ? (i, cs[1].lo) : (i, cs[end].hi)
end

"""
The runs of text in a cell that shows columns `lo` to `hi` of `text`. With
`raw`, the markup shows. With `open`, only the runs in those columns show it:
see `raw_part`.
"""
cellpieces(e, i::Int, text::String, lo::Int, hi::Int, base::Face, raw::Bool; open=nothing) = begin
  out = Piece[]
  for s in spans(rest(head(text, hi), lo), lo)
    shown = raw || markup_shows(open, s.col, s.col + length(s.text))
    (s.markup || s.comment) && !shown && continue
    s.math && !shown && Maths.available() ? push!(out, equation(e, s, base)) :
    s.live && !shown && !foreign(e.buf.path) ? push!(out, inline(e, i, s, base)) : symbols!(out, s.text, s.col, face(base, s), s.link)
  end
  out
end

"How wide a piece is before it's wrapped"
wide(p::Piece) = p.node === nothing ? measure(p.face, p.text) : p.node.w

"The text of each cell of a row of a table, without the spaces around it"
celltexts(line::AbstractString) = begin
  chars = collect(strip(line))
  !isempty(chars) && chars[1] == '|' && popfirst!(chars)
  !isempty(chars) && chars[end] == '|' && (length(chars) < 2 || chars[end-1] != '\\') && pop!(chars)
  out, cell = String[], Char[]
  for (i, c) in enumerate(chars)
    c == '|' && (i == 1 || chars[i-1] != '\\') ? (push!(out, strip(String(cell))); empty!(cell)) : push!(cell, c)
  end
  push!(out, strip(String(cell)))
end

tableline(cells) = "| " * join(cells, " | ") * " |"

"The side each column's text sits on, from the table's line of dashes: :left, :center or :right"
aligns(divider::AbstractString) =
  [startswith(c, ':') && endswith(c, ':') ? :center : endswith(c, ':') ? :right : :left for c in celltexts(divider)]

"Move each line of `f` across so its text sits on `side` of a space `room` wide"
align(f::Flow, room::px, side::Symbol) = begin
  side == :left && return f
  lines = map(f.lines) do vl
    dx = max(0px, room - sum(seg -> seg.w, vl.segs, init=0px)) * (side == :center ? 0.5 : 1)
    VLine([Seg(s.text, s.col, s.n, s.face, s.atomic, s.link, s.x + dx, s.w, s.node) for s in vl.segs], vl.x + dx, vl.from, vl.to, vl.top, vl.high)
  end
  Flow(lines, f.lh, f.size, f.above, f.below, f.kind, f.raw)
end

"""
How wide each column of a table is, when the table has `space` across it.
`natural` is how wide each column's text is on one line, and `least` is how
wide its longest word or number is. When the columns all fit, they share out
the room that's left by their natural widths. When they don't, each column
keeps the room that its longest word needs, and the columns share what's left
by how much more each one needs. So text wraps before a word or a number is cut
short, as in a spreadsheet or a browser.
"""
share_widths(natural, least, space) =
  sum(natural) <= space ? natural .* (num(space) / num(sum(natural))) :
  sum(least) >= space ? least .* (num(space) / num(sum(least))) :
  least .+ (natural .- least) .* (num(space - sum(least)) / num(sum(natural .- least)))

"Lay out the table in lines `from` to `to` of the document"
grid(e, from::Int, to::Int) = begin
  b = e.buf
  caret = from <= b.caret[1] <= to ? b.caret : nothing
  # As plain text, the run that the caret is in shows its markup, inside the caret's cell
  open = caret === nothing ? nothing : raw_part(b, caret[1])
  build() = begin
    base = Face(body(e), size=body(e).size * 0.94)
    lh = base.size * 1.5
    rows = tablerows((from, to))
    cells = [tablecells(b.lines[i]) for i in rows]
    ncols = max(1, maximum(length, cells))
    parts = map(enumerate(rows)) do (r, i)
      map(1:ncols) do c
        c <= length(cells[r]) || return Piece[]
        cell = cells[r][c]
        # The cell with the caret shows the spaces typed after its text, and as plain text the markup of the run that the caret is in
        active = caret !== nothing && caret[1] == i && within(cell, caret[2])
        cellpieces(e, i, b.lines[i], cell.lo, active ? max(cell.hi, caret[2]) : cell.hi,
                   r == 1 ? emboldened(base) : base, false; open=active ? open : nothing)
      end
    end
    # Each column gets room in proportion to its longest cell, and never less than its longest word needs
    natural = [maximum(row -> sum(wide, row[c], init=0px), parts, init=0px) + 2CELL_X for c in 1:ncols]
    natural = [clamp(w, 60px, e.width * 0.75) for w in natural]
    least = [min(natural[c], max(maximum(row -> maximum(unbroken, row[c], init=0px), parts, init=0px) + 2CELL_X, 36px)) for c in 1:ncols]
    widths = share_widths(natural, least, e.width - 1px * (ncols + 1))
    sides = aligns(b.lines[from+1])
    flows = [[align(wrap(row[c], widths[c] - 2CELL_X; lh, size=base.size, left=CELL_X), widths[c] - 2CELL_X, get(sides, c, :left))
              for c in 1:ncols] for row in parts]
    heights = [maximum(f -> tall(f), row) + 2CELL_Y for row in flows]
    Grid(rows, widths, heights, cells, flows)
  end
  # What inline code made can change its size, so a table with some in it is laid out again each time
  any(text -> occursin(INLINE, text), @view b.lines[from:to]) && return build()
  get!(build, e.flows, (:grid, from, b.lines[from:to], caret, b.plain, open))
end

const TABLE_GAP = 8px   # above and below a table
tall(g::Grid) = g.head + sum(g.heights) + 1px * (length(g.heights) + 1) + 2TABLE_GAP

"Where the text of row `r`, column `c` starts, from the top left of the table's item"
cell_origin(g::Grid, r::Int, c::Int) =
  (g.left + 1px * c + sum(g.widths[1:c-1], init=0px),
   TABLE_GAP + g.head + 1px * r + sum(g.heights[1:r-1], init=0px) + (g.heights[r] - tall(g.flows[r][c]))/2)

"The column in `cell` nearest to `x` on line `k` of its flow"
cellcol(f::Flow, k::Int, x::px, cell::Cell) =
  isempty(f.lines[k].segs) ? cell.lo : clamp(colat(f, k, x), cell.lo, cell.limit)

"The row and column of `g` that holds the caret at `p`, or nothing"
gridcell(g::Grid, p::Pos) = begin
  r = findfirst(==(p[1]), g.rows)
  (r === nothing || isempty(g.cells[r])) && return nothing
  (r, nearest(g.cells[r], p[2]))
end

# --- spreadsheets ----------------------------------------------------------------------
#
# A code block in the language `spreadsheet` is drawn as a spreadsheet. Each
# line of the block is a row, with a | between its cells, as in a table. A row
# of letters is over the cells, one for each column. A column of numbers is on
# their left, one for each row. A cell that starts with = is a formula: a Julia
# expression that can use the other cells by name, like B2 * C2 or sum(D2:D9).
# The cell shows what its formula comes to. While the caret is in the cell, it
# shows the formula.
#
# It's laid out as a `Grid`, so the caret moves as it does in a table, and the
# bar over the grid adds and removes a row or a column. Hold ⌥ and click the
# spreadsheet to see it as lines of code.

const SPREAD_Y = 5px   # above and below the text of a cell

"""
The lines that open and close the spreadsheet that line `i` is in, or nothing.
A spreadsheet needs a row, and it shows as lines of code while the caret is on
the line that opens or closes it.
"""
spread(b::Buffer, i::Int) = drawn(b, i, SPREADSHEET)

"True when line `i` is a row of a spreadsheet"
inspread(b::Buffer, i::Int) = begin
  run = spread(b, i)
  run !== nothing && run[1] < i < run[2]
end

"The lines that are the rows of the table or the spreadsheet that line `i` is in"
gridrows(b::Buffer, i::Int) = begin
  run = spread(b, i)
  run === nothing ? tablerows(table(b, i)) : collect(run[1]+1:run[2]-1)
end

"The name of every cell of a spreadsheet that has `rows` rows and `cols` columns"
cellnames(rows::Int, cols::Int) = [letters(c) * string(r) for r in 1:rows for c in 1:cols]

"How wide the longest part of `p` is that can't go onto two lines: a word, a number or what a formula comes to"
unbroken(p::Piece) =
  p.node !== nothing ? p.node.w : p.atomic && !p.words ? measure(p.face, p.text) :
  maximum(word -> measure(p.face, word), split(p.text), init=0px) + (p.face.chip ? 2(CHIP_X + 1px) : 0px)

"Lay out the spreadsheet whose code block opens on line `from` and closes on line `to`"
spreadgrid(e, from::Int, to::Int) = begin
  b = e.buf
  caret = alone(b, b.caret[1]) && from < b.caret[1] < to ? b.caret : nothing
  build() = begin
    base = Face(body(e), size=body(e).size * 0.94)
    lh = base.size * 1.5
    rows = collect(from+1:to-1)
    cells = [spreadcells(b.lines[i]) for i in rows]
    texts = [spreadtexts(b.lines[i]) for i in rows]
    # The cells are only worked out again when the text of one changes
    values = get!(() -> answers(texts), e.flows, (:answers, texts))
    ncols = maximum(length, cells)
    typing(r, c) = caret !== nothing && caret[1] == rows[r] && c <= length(cells[r]) && within(cells[r][c], caret[2])
    # What the cell in row `r`, column `c` shows. With `on`, it's the cell with the caret.
    shows(r, c, on) = begin
      c <= length(cells[r]) || return Piece[]
      i, cell, v = rows[r], cells[r][c], values[r][c]
      # The cell with the caret shows the spaces typed after its text
      upto = on ? max(cell.hi, caret[2]) : cell.hi
      isformula(texts[r][c]) || return cellpieces(e, i, b.lines[i], cell.lo, upto, base, on)
      # A formula shows what it comes to. With the caret in its cell, it shows the formula, and each cell that it names is a chip.
      on && return exprpieces(b.lines[i], cell.lo, upto, cellnames(length(rows), ncols), base)
      [piece(v.failed ? "!" : v.text, cell.lo, base, atomic=true, n=cell.hi - cell.lo)]
    end
    # The columns are as wide as they are with no caret in a cell, so a column keeps its width
    # while you edit one of its cells. A formula that's wider than its column wraps.
    resting = [[shows(r, c, false) for c in 1:ncols] for r in eachindex(rows)]
    parts = [[typing(r, c) ? shows(r, c, true) : resting[r][c] for c in 1:ncols] for r in eachindex(rows)]
    # Each column gets room in proportion to its longest cell, as in a table
    natural = [clamp(maximum(row -> sum(wide, row[c], init=0px), resting, init=0px) + 2CELL_X, 60px, e.width * 0.75) for c in 1:ncols]
    gutter = max(measure(Face(base, family=SANS, size=base.size * 0.72), string(length(rows))) + 14px, base.size * 1.9)
    space = e.width - gutter - 1px * (ncols + 2)
    least = [min(natural[c], max(maximum(row -> maximum(unbroken, row[c], init=0px), resting, init=0px) + 2CELL_X, 36px)) for c in 1:ncols]
    widths = share_widths(natural, least, space)
    flows = [[align(wrap(row[c], widths[c] - 2CELL_X; lh, size=base.size, left=CELL_X), widths[c] - 2CELL_X,
                    # A number stays on the right while you type it. A formula is on the left while its cell shows it.
                    c <= length(cells[r]) && values[r][c].number && !(typing(r, c) && isformula(texts[r][c])) ? :right : :left)
              for c in 1:ncols] for (r, row) in enumerate(parts)]
    heights = [maximum(tall, row) + 2SPREAD_Y for row in flows]
    Grid(rows, widths, heights, cells, flows, lh + 1px, gutter + 1px, values)
  end
  # What inline code made can change its size, so a spreadsheet with some in it is laid out again each time
  any(text -> occursin(INLINE, text), @view b.lines[from:to]) && return build()
  get!(build, e.flows, (:spread, from, b.lines[from:to], caret))
end

"A spreadsheet as nodes: the grid of a table, with a row of letters over it and a column of numbers on its left"
spreadsheet(e::Editor, it::Item, g::Grid) = begin
  b = e.buf
  line = border(1px, :solid, colours.line; between=true)
  size = body(e).size * 0.94
  at = alone(b, b.caret[1]) ? gridcell(g, b.caret) : nothing
  # The letter and the number of the caret's cell are darker
  name(text, on) = Box(height(grow=grow), Alignment.Center, justify=Alignment.Center,
                       label(text, size * 0.72, color=on ? colours.ink : colours.dim, weight=on ? "Semibold" : ""))
  cell(r, c) = begin
    v = c <= length(g.values[r]) ? g.values[r][c] : nothing
    # A formula that went wrong shows a !, which says what went wrong while the mouse is over it
    (v !== nothing && v.failed && at != (r, c)) || return rows(g.flows[r][c])
    [Box(padding(CELL_X, 0px), own!(node!(Document, e, :document), Trouble(message=v.text, size=size * 0.9)))]
  end
  head = Row(width(grow=grow), height(g.head - 1px), Alignment.Start, line[:between], background(colours.head),
    Box(fixed(g.left - 1px), height(grow=grow)),
    [Box(fixed(g.widths[c]), height(grow=grow), name(letters(c), at !== nothing && at[2] == c)) for c in eachindex(g.widths)]...)
  body_rows = [Row(width(grow=grow), height(g.heights[r]), Alignment.Start, line[:between], background(colours.bg),
                 Box(fixed(g.left - 1px), height(grow=grow), background(colours.head), name(string(r), at !== nothing && at[1] == r)),
                 [Column(fixed(g.widths[c]), height(grow=grow), Alignment.Start, justify=Alignment.Center, cell(r, c)...)
                  for c in eachindex(g.widths)]...)
               for r in eachindex(g.rows)]
  Box(width(grow=grow), padding(0px, TABLE_GAP),
    Column(width(grow=grow), Alignment.Start, line, name="Spreadsheet", head, body_rows...))
end

"Draw a line around the cell in row `r`, column `c` of a spreadsheet whose item has its top left corner at (x, y)"
ring(ctx, g::Grid, (r, c), x, y) =
  rectangle(ctx, x + g.left + 1px * c + sum(g.widths[1:c-1], init=0px) - 0.5px,
            y + TABLE_GAP + g.head + 1px * r + sum(g.heights[1:r-1], init=0px) - 0.5px,
            g.widths[c] + 1px, g.heights[r] + 1px, stroke=colours.accent, border=1.5px)

"""
Add or remove a row or a column of the spreadsheet the caret is in, at the
caret. Each formula still names the same cells after it: a cell that moved has
a new name, so the formula is written with that name.
"""
spreadop!(e, action::Symbol) = begin
  b = e.buf
  i = b.caret[1]
  inspread(b, i) || return
  s, t = spread(b, i)
  rows = map(spreadtexts, b.lines[s+1:t-1])
  n = maximum(length, rows)
  rows = [[row; fill("", n - length(row))] for row in rows]
  r = i - s                                           # the caret's row
  c = nearest(spreadcells(b.lines[i]), b.caret[2])    # and its column
  if action == :addrow
    r += 1
    rows = [moved.(row, 1, row=r) for row in rows]
    insert!(rows, r, fill("", n))
  elseif action == :delrow
    length(rows) == 1 && return
    deleteat!(rows, r)
    rows = [moved.(row, -1, row=r + 1) for row in rows]
    r = min(r, length(rows))
  elseif action == :addcol
    c += 1
    rows = [moved.(row, 1, col=c) for row in rows]
    foreach(row -> insert!(row, c, ""), rows)
  elseif action == :delcol
    n == 1 && return
    foreach(row -> deleteat!(row, c), rows)
    rows = [moved.(row, -1, col=c + 1) for row in rows]
    c = min(c, n - 1)
  else
    return
  end
  edit!(b, (s + 1, 0), line_end(b, t - 1), join(map(tableline, rows), "\n"))
  b.caret = b.anchor = (s + r, spreadcells(b.lines[s+r])[c].hi)
  touch!(e)
end

"Backspace in an empty row of a spreadsheet removes the row, and the last row takes the spreadsheet with it"
droprow!(e) = begin
  b = e.buf
  i = b.caret[1]
  s, t = spread(b, i)
  t - s == 2 && return (edit!(b, (s, 0), line_end(b, t), ""); touch!(e))
  spreadop!(e, :delrow)
  above = max(i - 1, s + 1)
  b.caret = b.anchor = (above, spreadcells(b.lines[above])[end].hi)
  touch!(e)
end

# --- sheets ----------------------------------------------------------------------------
#
# A code block in the language `sheet` is drawn as a sheet, like the one in
# Centient's notepad. Each line of the block is a row: a name, an = and a Julia
# expression. The expression can use the names of the rows above it the way
# they're written, and those names show as chips. What each row comes to shows
# on its right. A row without a name shows its number instead.
#
# The caret moves from cell to cell, as it does in a table. Tab and shift-Tab
# go to the next and the last cell, and Return starts a row. Hold ⌥ and click
# the sheet to see it as lines of code.

const SHEET_GAP = 8px   # above and below a sheet
const SHEET_X = 10px    # beside the text of a cell
const SHEET_Y = 4px     # above the first row and below the last
const RAISE = 0.28      # of the size of the text: how far a character from the spare font goes up, twice over
const RESULT_X = 8px    # beside the text of what a row comes to

# A sheet's text is in Source Code Pro ExtraLight, a step lighter than
# Centient's Light. A Mac without that font gets the font of the code blocks.
const SHEET_FILE = something(findfirst(isfile, joinpath.((joinpath(homedir(), "Library/Fonts"), "/Library/Fonts"),
                                                         "SourceCodePro-ExtraLight.ttf")) |>
                             i -> i === nothing ? nothing : joinpath((joinpath(homedir(), "Library/Fonts"), "/Library/Fonts")[i],
                                                                     "SourceCodePro-ExtraLight.ttf"), "")
const SHEET_FONT = isempty(SHEET_FILE) ? MONO : "Source Code Pro"
const SHEET_WEIGHT = isempty(SHEET_FILE) ? "" : "ExtraLight"

"""
Read the sheet's font from its file. A request for a weight of this font by
name can come back in another weight, so the file is read itself. This runs each time an
editor is made, because a built app forgets its fonts when it starts.
"""
load_sheet_font() = isempty(SHEET_FILE) || register_font(SHEET_FILE)

"A sheet laid out"
struct Sheet
  rows::Vector{Int}             # the line of the document each row comes from
  cells::Vector{Vector{Cell}}   # each row's name and expression, or only its expression
  names::Vector{Flow}
  exprs::Vector{Flow}
  results::Vector{Result}       # what each row comes to
  heights::Vector{px}
  name_w::px                    # how wide the column of names is
  size::px                      # of the text
end

"""
The lines that open and close the sheet that line `i` is in, or nothing. A
sheet needs a row, and it shows as lines of code while the caret is on the
line that opens or closes it.
"""
sheet(b::Buffer, i::Int) = drawn(b, i, SHEET)

"The lines that open and close the code block in the language `lang` that line `i` is in, when the block is drawn as a sheet or a spreadsheet"
drawn(b::Buffer, i::Int, lang::String) = begin
  ks = kinds(b)
  (ks[i].kind == Kind.fence || (ks[i].kind == Kind.code && ks[i].lang == lang)) || return nothing
  s, t = codeblock(b, i)
  (t > s + 1 && ks[s].kind == Kind.fence && ks[s].lang == lang && ks[t].kind == Kind.fence && ks[t].level == 1) || return nothing
  israw(b, s) || israw(b, t) ? nothing : (s, t)
end

"True when line `i` is a row of a sheet"
insheet(b::Buffer, i::Int) = begin
  run = sheet(b, i)
  run !== nothing && run[1] < i < run[2]
end

"""
The runs of text in the expression that is columns `lo` to `hi` of `text`. Each
of `names` is a chip, and a * that multiplies shows as ×.
"""
exprpieces(text::String, lo::Int, hi::Int, names, base::Face) = begin
  expr = rest(head(text, hi), lo)
  chars = collect(expr)
  faces = fill(base, length(chars))
  times = [c == '*' for c in chars]
  for t in tokens(expr, "julia")
    t.kind == :plain && continue
    span = t.col+1:t.col+length(t.text)
    faces[span] .= Ref(Face(base, color=getfield(colours, t.kind)))
    # A * in a string or a comment is only a *
    t.kind in (:string, :comment) && (times[span] .= false)
  end
  for (a, z, _) in uses(expr, names)
    faces[a+1:z] .= Ref(Face(base, chip=true))
  end
  out = Piece[]
  i = 1
  while i <= length(chars)
    if times[i]
      push!(out, piece("×", lo + i - 1, faces[i], atomic=true, n=1))
      i += 1
      continue
    end
    j = i
    while j < length(chars) && faces[j+1] === faces[i] && !times[j+1]; j += 1 end
    push!(out, piece(String(chars[i:j]), lo + i - 1, faces[i]))
    i = j + 1
  end
  out
end

"How wide the chip that shows `r` is. A row that went wrong shows a !."
chip_w(face::Face, r::Result) =
  isempty(r.text) ? 0px : r.failed ? measure(face, "!") + 2RESULT_X : sum(measure(f, t) for (t, f) in runs(r.text, face)) + 2RESULT_X

const drawable = Dict{Tuple{String,String,Char},Bool}()

"True when the font of `face` has a letter shape for `c`"
has(face::Face, c::Char) =
  get!(drawable, (face.family, face.style, c)) do
    Skia.sk_font_unichar_to_glyph(skia_font(face.family, face.size, face.style).raw, Int32(c)) != 0
  end

const stand_ins = Dict{Tuple{String,Char},String}()

"""
The name of a font on this Mac that has the character `c`, or "" when none
has. macOS picks it, as it does for the text of an app in the font `family`:
`family` when it has the character, and if not a font of symbols, of another
script or of emoji. Code asks with Menlo, which has most signs.
"""
font_with(c::Char, family::AbstractString=MONO) = get!(stand_ins, (String(family), c)) do
  style = Skia.sk_fontstyle_new(Int32(400), Int32(Skia.SK_FONT_STYLE_WIDTH_NORMAL), Skia.SK_FONT_STYLE_SLANT_UPRIGHT)
  found = Skia.sk_fontmgr_match_family_style_character(Skia.sk_fontmgr_ref_default(), family, style, C_NULL, Int32(0), Int32(c))
  Skia.sk_fontstyle_delete(style)
  found == C_NULL && return ""
  name = Skia.sk_typeface_get_family_name(found)
  family = unsafe_string(Skia.sk_string_get_c_str(name))
  Skia.sk_string_delete(name)
  # The font is asked for by its name from here on, so it has to answer to that name
  has(Face(family, "", 12px, colours.ink, false), c) ? family : ""
end

const one_wide = Dict{Tuple{String,String},Bool}()

"True when each letter of the font of `face` is as wide as the others, as in a font of code"
one_width(face::Face) = get!(one_wide, (face.family, face.style)) do
  f = skia_font(face.family, 12px, face.style)
  measure_text(f, "i")[1] == measure_text(f, "M")[1]
end

"""
The font that macOS starts from to find a font for a character that `face`
lacks. Code and the symbols of keys start from Menlo, which has most signs.
Text starts from its own font, as in TextEdit.
"""
stand_in_from(face::Face) = one_width(face) || face.family == SYMBOL_FONT ? MONO : face.family

"""
`text` in runs, each with the face to draw it in. A character that the font of
`face` doesn't have is in a font that has it (see `stand_in_from`). In code,
that's Menlo for the raised minus of m⁻¹, and a font of symbols for the ⋮ in a
big matrix. Charter has no raised minus, so the minus of yr⁻¹ in a page's text
is Lucida Grande's.
"""
runs(text::AbstractString, face::Face) = begin
  out = Tuple{String,Face}[]
  for c in text
    family = isascii(c) || has(face, c) ? face.family : font_with(c, stand_in_from(face))
    f = family == face.family || isempty(family) ? face : Face(face, family=family, style="")
    if !isempty(out) && last(out)[2] === f
      out[end] = (last(out)[1] * c, f)
    else
      push!(out, (string(c), f))
    end
  end
  out
end

"True when the font of `face` has every character of `text`"
hasall(face::Face, text::AbstractString) = all(c -> isascii(c) || has(face, c), text)

"""
The pieces `ps` of a line, with each character that the code font lacks in a
piece of its own, in a font that has it. A `code` chip stays one piece, and
draws those characters itself.
"""
spare(ps::Vector{Piece}) = begin
  whole(p) = p.face.family != codefont() || p.face.chip || p.atomic || p.node !== nothing || hasall(p.face, p.text)
  all(whole, ps) && return ps
  out = Piece[]
  for p in ps
    whole(p) && (push!(out, p); continue)
    col = p.col
    for (part, f) in runs(p.text, p.face)
      push!(out, Piece(part, col, length(part), f, false, p.link, nothing, false))
      col += length(part)
    end
  end
  out
end

"`text` in the face `f`, as the parts of a row. A character that the font lacks is in a font that has it."
spared(text::AbstractString, f::Face) =
  [Box(fixed(measure(pf, part)), Alignment.Start,
     Text(part, size=pf.size, family=pf.family, subfamily=pf.style, color=pf.color, wrap=WrapMode.none)) for (part, pf) in runs(text, f)]

"""
Where a sheet with a row over a range shows itself: at the value of that row
that the mouse is on, in a chart of the sheet or in any other part of the
page, as a number from 0 at the first value to 1 at the last. It's nothing
while the mouse is on no such value: the sheet then shows both ends.
"""
sheet_case(e, texts, given) = begin
  name = pointed(e)
  name === nothing && return nothing
  over = get!(() -> cases(texts; given, cache=e.flows), e.flows, (:cases, texts, given))
  over === nothing && return nothing
  k = findfirst(row -> plain_name(row[1]) == name, view(over.table, 2:length(over.table)))
  k === nothing ? nothing : over.places[k]
end

"Lay out the sheet whose code block opens on line `from` and closes on line `to`"
sheetgrid(e, from::Int, to::Int) = begin
  b = e.buf
  caret = from < b.caret[1] < to && b.caret[1] == b.anchor[1] ? b.caret : nothing
  # The layout holds the number of each row's line, so it's kept for these lines only
  # The names that the sheet has from the parts of the page over it, like the measures of a takeoff and the sums in its lines of text
  given = sheet_given(e, from)
  # While the mouse is on one value of a chart of a sheet with a row over a range, the sheet shows itself at that value
  at = sheet_case(e, [parts(b.lines[i]) for i in from+1:to-1], given)
  get!(e.flows, (:sheet, from, b.lines[from+1:to-1], caret, given, at)) do
    size = body(e).size * 0.86
    lh = size * 1.7
    ink = Face(SHEET_FONT, SHEET_WEIGHT, size, colours.ink, false)
    rows = collect(from+1:to-1)
    cells = [sheetcells(b.lines[i]) for i in rows]
    texts = [parts(b.lines[i]) for i in rows]
    # The rows are only worked out again when the text of one changes
    results = get!(() -> tally(texts; given, at, cache=e.flows), e.flows, (:sheetrun, texts, given, at))
    # The cell with the caret shows the spaces typed after its text
    upto(i, c) = caret !== nothing && caret[1] == i && within(c, caret[2]) ? max(c.hi, caret[2]) : c.hi
    names = map(zip(rows, cells)) do (i, cs)
      length(cs) == 2 || return Piece[]
      text = rest(head(b.lines[i], upto(i, cs[1])), cs[1].lo)
      isempty(text) ? Piece[] : [piece(text, cs[1].lo, ink)]
    end
    name_w = clamp(maximum(ps -> sum(p -> measure(p.face, p.text), ps, init=0px), names, init=0px) + 2px, 3size, e.width * 0.4)
    # An expression has the room that its row's name and result leave it
    room = e.width - 3px - 4SHEET_X - name_w
    # While the sheet shows itself at one value, a result is narrower than the range that it shows the rest of the
    # time. The expressions wrap for the wider of the two, so the sheet keeps its height. If it got shorter, a chart
    # under it would move away from the mouse, the sheet would show the range again, and the two would shake.
    ends = at === nothing ? results : get!(() -> tally(texts; given, at=nothing, cache=e.flows), e.flows, (:sheetrun, texts, given, nothing))
    exprs = map(enumerate(rows)) do (r, i)
      c = cells[r][end]
      chip = max(chip_w(ink, results[r]), chip_w(ink, ends[r]))
      wrap(exprpieces(b.lines[i], c.lo, upto(i, c), known(texts, r, given), ink), max(80px, room - chip - (chip > 0px ? SHEET_X : 0px)); lh, size)
    end
    nameflows = [wrap(ps, name_w; lh, size) for ps in names]
    heights = [max(tall(n), tall(x)) for (n, x) in zip(nameflows, exprs)]
    Sheet(rows, cells, nameflows, exprs, results, heights, name_w, size)
  end
end

tall(s::Sheet) = sum(s.heights) + 2px + 2SHEET_Y + 2SHEET_GAP

"How far the top of row `r` is from the top of the sheet's item"
row_top(s::Sheet, r::Int) = SHEET_GAP + 1px + SHEET_Y + sum(s.heights[1:r-1], init=0px)

"How far the text of an expression starts from the left of the sheet"
expr_x(s::Sheet) = 2px + 3SHEET_X + s.name_w

"The layout of cell `k` of row `r`, and how far its text starts from the left of the sheet"
cellflow(s::Sheet, r::Int, k::Int) =
  length(s.cells[r]) == 2 && k == 1 ? (s.names[r], 1px + SHEET_X) : (s.exprs[r], expr_x(s))

"Which cell of row `r` is under a point `x` from the left of the sheet"
cellunder(s::Sheet, r::Int, x::px) = length(s.cells[r]) == 2 && x < expr_x(s) - SHEET_X ? 1 : length(s.cells[r])

"The row of the sheet under a point `y` from the top of its item"
rowunder(s::Sheet, y::px) = something(findfirst(r -> y < row_top(s, r) + s.heights[r], eachindex(s.rows)), length(s.rows))

"The place in row `r` nearest to `x`, on the first line of the row's cell, or on its last when `by` is -1"
place(s::Sheet, r::Int, by::Int, x::px) = begin
  k = cellunder(s, r, x)
  f, dx = cellflow(s, r, k)
  (s.rows[r], cellcol(f, by < 0 ? length(f.lines) : 1, x - dx, s.cells[r][k]))
end

"Where the caret goes when ↑ or ↓ brings it into a sheet from the line above or below it"
enter(e, it::Item, s::Sheet, by::Int, x::px) = place(s, by > 0 ? 1 : length(s.rows), by, x)

"""
One run of text of a sheet, in a box as tall as the line with the text in the
middle of it. A name of another row is a chip with round ends.
"""
sheetseg(seg::Seg, lh::px) = begin
  f = seg.face
  t = Text(seg.text, size=f.size, family=f.family, subfamily=f.style, color=f.color, wrap=WrapMode.none)
  f.chip || return Box(fixed(seg.w), height(lh), Alignment.Center, t)
  h = f.size * 1.45
  Box(fixed(seg.w), height(lh), Alignment.Center,
    Box(fixed(seg.w), height(h), padding(CHIP_X, 0px), radius(h / 2), background(colours.chip), border(1px, :solid, colours.chip_line), t))
end

sheetlines(f::Flow) =
  [Row(width(grow=grow), height(f.lh), Alignment.Center, padding(0px, 0px, 0px, vl.x), clip=true,
       [sheetseg(seg, f.lh) for seg in vl.segs]...) for vl in f.lines]

describe(e::Editor, it::Item, s::Sheet) = begin
  b = e.buf
  lh = s.size * 1.7
  n = length(s.rows)
  bare(f) = isempty(f.lines[1].segs)
  hint(text) = Row(height(lh), Text(text, size=s.size, family=SHEET_FONT, subfamily=SHEET_WEIGHT, color=colours.faint, wrap=WrapMode.none))
  rows = map(1:n) do r
    above, below = (r == 1 ? SHEET_Y : 0px), (r == n ? SHEET_Y : 0px)
    pad = padding(above, SHEET_X, below, SHEET_X)
    # The caret is in this row's expression
    typing = b.caret[1] == b.anchor[1] == s.rows[r] && nearest(s.cells[r], b.caret[2]) == length(s.cells[r])
    res = s.results[r]
    w = chip_w(Face(SHEET_FONT, SHEET_WEIGHT, s.size, colours.ink, false), res)
    chip = isempty(res.text) ? () :
      (Column(fixed(w + SHEET_X), height(grow=grow), Alignment.Start, padding(above + 1px, SHEET_X, 0px, 0px),
         res.failed ? own!(node!(Document, e, :document), Trouble(message=res.text, size=s.size)) :
           # A value that the sheet worked out backwards, from an answer under it, has a line round it in the accent colour
           Row(fixed(w), height(lh - 2px), Alignment.Center, padding(RESULT_X, 0px), radius(6px), background(colours.chip),
               (res.solved ? (border(1px, :solid, colours.accent),) : ())...,
             # Menlo's raised signs sit lower than Source Code Pro's raised digits, so they go up a little
             [Box(padding(0px, 0px, f.family == SHEET_FONT ? 0px : s.size * RAISE, 0px),
                Text(t, size=s.size, family=f.family, subfamily=f.style, color=res.solved ? colours.accent : colours.ink, wrap=WrapMode.none))
              for (t, f) in runs(res.text, Face(SHEET_FONT, SHEET_WEIGHT, s.size, colours.ink, false))]...)),)
    Row(width(grow=grow), height(s.heights[r] + above + below), Alignment.Start,
      # A row without a name shows its number
      Column(fixed(s.name_w + 2SHEET_X + 1px), height(grow=grow), Alignment.Start, pad, border(1px, :solid, colours.line)[:right],
        (bare(s.names[r]) ? (hint(string(r)),) : sheetlines(s.names[r]))...),
      Column(width(grow=grow), height(grow=grow), Alignment.Start, pad,
        (bare(s.exprs[r]) && typing ? (hint("expression"),) : sheetlines(s.exprs[r]))...),
      chip...)
  end
  Box(width(grow=grow), padding(0px, SHEET_GAP),
    Column(width(grow=grow), Alignment.Start, radius(6px), background(colours.float), border(1px, :solid, colours.line), name="Sheet",
      rows...))
end

describe(t::Trouble) = begin
  w = measure(Face(SHEET_FONT, SHEET_WEIGHT, t.size, colours.accent, false), "!") + 2RESULT_X
  Box(fixed(w), height(t.size * 1.7 - 2px), padding(RESULT_X, 0px), radius(6px), background(colours.chip),
    Text("!", size=t.size, family=MONO, subfamily="Bold", color=colours.accent, wrap=WrapMode.none))
end

draw(ctx, size, ui::ConcreteRect, t::Trouble) = (t.rect = (ui.left, ui.top, ui.width, ui.height); nothing)

onmouse(t::Trouble, ev::MouseMove) =
  show_tooltip!(ev.window, tip_label(t.message), t.rect..., placement=:bottom, gap=6px)

"""
The boxes that cover the selected part of a sheet whose top left corner is at
(x, y). A selection that covers several lines takes each row whole.
"""
marks(e, it::Item, s::Sheet, x, y) = begin
  b = e.buf
  out = Rect[]
  selecting(b) || return out
  lo, hi = selection(b)
  if b.caret[1] != b.anchor[1]
    n = length(s.rows)
    bottom = y + it.tall - SHEET_GAP
    lo[1] <= it.first && hi[1] >= it.first && push!(out, (num(x), num(y), num(x + 7px), num(y + SHEET_GAP)))
    for (r, i) in enumerate(s.rows)
      lo[1] <= i <= hi[1] || continue
      top = r == 1 ? y + SHEET_GAP : y + row_top(s, r)
      push!(out, (num(x), num(top), num(x + item_room(e, it)[2]), num(r == n ? bottom : y + row_top(s, r + 1))))
    end
    lo[1] <= it.last && hi[1] >= it.last && push!(out, (num(x), num(bottom), num(x + 7px), num(y + it.tall)))
    return out
  end
  r = findfirst(==(b.caret[1]), s.rows)
  r === nothing && return out
  sel = selected(b, s.rows[r])
  for (k, cell) in enumerate(s.cells[r])
    (sel[1] < cell.limit && sel[2] > cell.lo) || continue
    f, dx = cellflow(s, r, k)
    append!(out, marks(f, x + dx, y + row_top(s, r), (max(sel[1], cell.lo), min(sel[2], cell.limit), false), margin=false))
  end
  out
end

"Draw the caret in the cell of a sheet that it's in. The sheet's top left corner is at (x, y)."
caret(ctx, e, s::Sheet, x, y) = begin
  p = e.buf.caret
  r = findfirst(==(p[1]), s.rows)
  r === nothing && return
  f, dx = cellflow(s, r, nearest(s.cells[r], p[2]))
  caret(ctx, e, f, x + dx, y + row_top(s, r), p[2])
end

"The place in a sheet under a point that is (dx, dy) from the top left of its item"
locate(e, it::Item, s::Sheet, dx, dy) = begin
  r = rowunder(s, dy)
  k = cellunder(s, r, dx)
  f, x = cellflow(s, r, k)
  line = clamp(floor(Int, num(dy - row_top(s, r)) / num(f.lh)) + 1, 1, length(f.lines))
  (s.rows[r], cellcol(f, line, dx - x, s.cells[r][k]))
end

"""
A click on a sheet. It returns true when it has put the caret somewhere itself.
With ⌥ held, the sheet shows as lines of code. A click where a row's name goes
gives a row that has no name a place for one.
"""
press!(e, it::Item, s::Sheet, pos) = begin
  b = e.buf
  if only_held(e, Keys.opt)
    b.caret = b.anchor = line_end(b, it.first)
    return true
  end
  r = rowunder(s, pos[2] - e.origin[2] - it.top)
  (length(s.cells[r]) == 1 && pos[1] - e.origin[1] - item_room(e, it)[1] < expr_x(s) - SHEET_X) || return false
  name_row!(e, s.rows[r])
  true
end

"Give the row on line `i`, which has no name, a place for one, and put the caret there"
name_row!(e, i::Int) = begin
  b = e.buf
  edit!(b, (i, 0), (i, 0), " = ")
  b.caret = b.anchor = (i, 0)
  e.clicked = (time(), (i, 0), 1)
  touch!(e)
end

"""
Where the caret goes when it's sent to `p` in the sheet that runs from line `s`
to line `t`. See `settle` for a table. A spreadsheet works the same way, with
`cells` to read the cells of a row.
"""
settle(b::Buffer, (s, t)::Tuple{Int,Int}, p::Pos, by::Int, cells=sheetcells) = begin
  i, col = p
  first_cell(i) = (i, cells(b.lines[i])[1].lo)
  last_cell(i) = (i, cells(b.lines[i])[end].hi)
  # The lines that open and close the sheet don't show, so the caret steps over them
  i == s && return by < 0 && s > 1 ? line_end(b, s - 1) : first_cell(s + 1)
  i == t && return by > 0 && t < length(b.lines) ? (t + 1, 0) : last_cell(t - 1)
  cs = cells(b.lines[i])
  any(c -> within(c, col), cs) && return p
  if by < 0
    c = findlast(c -> c.limit < col, cs)
    c === nothing || return (i, cs[c].hi)
    i - 1 > s ? last_cell(i - 1) : s > 1 ? line_end(b, s - 1) : first_cell(i)
  elseif by > 0
    c = findfirst(c -> c.lo > col, cs)
    c === nothing || return (i, cs[c].lo)
    i + 1 < t ? first_cell(i + 1) : t < length(b.lines) ? (t + 1, 0) : last_cell(i)
  else
    c = cs[nearest(cs, col)]
    (i, clamp(col, c.lo, c.limit))
  end
end

"The place one line up or down from the caret, which is in a sheet"
vertical(e, it::Item, s::Sheet, by::Int) = begin
  b = e.buf
  # The caret can be on the line that opens or closes the sheet, at the end of a selection
  r = something(findfirst(==(b.caret[1]), s.rows), b.caret[1] <= it.first ? 1 : length(s.rows))
  k = nearest(s.cells[r], b.caret[2])
  f, dx = cellflow(s, r, k)
  line, x = spot(f, b.caret[2])
  x = e.goal = something(e.goal, x + dx)
  1 <= line + by <= length(f.lines) && return (b.caret[1], cellcol(f, line + by, x - dx, s.cells[r][k]))
  r += by
  1 <= r <= length(s.rows) && return place(s, r, by, x)
  if by < 0
    it.first == 1 && return b.caret
    f = flow(e, it.first - 1, b.plain && !by_runs(b, it.first - 1))
    return (it.first - 1, colat(f, length(f.lines), x))
  end
  # ↓ on the last row of a sheet at the end of the document starts a line below it
  it.last == length(b.lines) && edit!(b, line_end(b, it.last), line_end(b, it.last), "\n")
  (it.last + 1, colat(flow(e, it.last + 1, b.plain && !by_runs(b, it.last + 1)), 1, x))
end

"Return in a sheet starts a row under the caret's row. In a last row that's empty, it ends the sheet instead."
next_row!(e) = begin
  b = e.buf
  i = b.caret[1]
  s, t = sheet(b, i)
  if i == t - 1 && t - s > 2 && all(isempty, parts(b.lines[i]))
    edit!(b, line_end(b, i - 1), line_end(b, t), "\n" * b.lines[t] * "\n")
    b.caret = b.anchor = (t, 0)
    return touch!(e)
  end
  edit!(b, line_end(b, i), line_end(b, i), "\n = ")
  b.caret = b.anchor = (i + 1, 0)
  touch!(e)
end

"""
Tab in a sheet goes to the next cell and selects what's in it, or with `back`
to the one before. Going on from the last cell adds a row, and going back from
an expression that has no name makes a place for one.
"""
sheet_tab!(e, back::Bool) = begin
  b = e.buf
  i, col = b.caret
  s, t = sheet(b, i)
  cs = sheetcells(b.lines[i])
  k = nearest(cs, col)
  pick(i, c) = begin
    b.anchor, b.caret = (i, c.lo), (i, c.hi)
    touch!(e)
  end
  if back
    length(cs) == 1 && return name_row!(e, i)
    k == 2 && return pick(i, cs[1])
    return i - 1 > s ? pick(i - 1, sheetcells(b.lines[i-1])[end]) : nothing
  end
  k < length(cs) && return pick(i, cs[2])
  i + 1 < t && return pick(i + 1, sheetcells(b.lines[i+1])[1])
  edit!(b, line_end(b, i), line_end(b, i), "\n = ")
  b.caret = b.anchor = (i + 1, 0)
  touch!(e)
end

"""
Backspace in a sheet, when it does more than delete a character. In a row
that's empty it takes the row away, and the last row takes the sheet with it.
At the start of an expression it goes back to the row's name. It returns true
when it did one of these.
"""
erase_row!(e, to::Pos) = begin
  b = e.buf
  i, col = b.caret
  to < b.caret || return false
  s, t = sheet(b, i)
  cs = sheetcells(b.lines[i])
  if all(isempty, parts(b.lines[i]))
    if t - s == 2
      edit!(b, (s, 0), line_end(b, t), "")
    elseif i - 1 > s
      edit!(b, line_end(b, i - 1), line_end(b, i), "")
    else
      edit!(b, (i, 0), (i + 1, 0), "")
      b.caret = b.anchor = settle(b, (i, 0), 1)
    end
    touch!(e)
    return true
  end
  (length(cs) == 2 && col == cs[2].lo && nearest(cs, col) == 2) || return false
  b.caret = b.anchor = (i, cs[1].hi)
  touch!(e)
  true
end

# --- the names a sheet offers ----------------------------------------------------------
#
# While you type a name in an expression of a sheet, a list under the caret
# shows the names of the rows above that start the same way. ↑ and ↓ choose
# one, Return or Tab types the rest of it, and esc hides the list.

isnamechar(c::Char) = isletter(c) || isdigit(c) || c == '_'

"""
The names that the text before the caret could be the start of: the line, the
column where the name starts, and the names. Nothing when the caret isn't in an
expression of a sheet, or no name fits. A name fits when it starts with what's
typed, or when one of its words does.
"""
offered(e) = begin
  b = e.buf
  i, col = b.caret
  selecting(b) && return nothing
  # A code block offers names too, and the name of a wiki link offers pages
  insheet(b, i) || return (found = code_offered(e); found === nothing ? wiki_offered(e) : found)
  cs = sheetcells(b.lines[i])
  c = cs[end]
  (c.lo <= col <= c.limit && nearest(cs, col) == length(cs)) || return nothing
  s, _ = sheet(b, i)
  rows = [parts(b.lines[j]) for j in s+1:i-1]
  names = known(rows, length(rows) + 1, page_given(e, s, sums=true))
  isempty(names) && return nothing
  chars = collect(b.lines[i])
  # In the middle of a word, nothing is offered
  col < length(chars) && isnamechar(chars[col+1]) && return nothing
  before = map(lowercase, chars[c.lo+1:col])
  # The longest run of words before the caret that starts a name wins, so "wall l" finds "Wall length"
  for from in max(1, length(before) - 40):length(before)
    (isletter(before[from]) || before[from] == '_') || continue
    from > 1 && isnamechar(before[from-1]) && continue
    typed = String(before[from:end])
    fits(n) = lowercase(n) != typed && (startswith(lowercase(n), typed) || any(w -> startswith(w, typed), split(lowercase(n))))
    found = filter(fits, names)
    isempty(found) || return (i, c.lo + from - 1, found)
    # A whole name is typed already, so its last words aren't the start of another
    any(n -> lowercase(n) == typed, names) && return nothing
  end
  nothing
end

"Which name of the list is chosen, and the list that esc hid. Each is kept with the place its list is for."
suggesting(e) = get!(() -> Ref{Any}((at=(0, 0), chosen=1, hidden=(0, 0))), e.nodes, :suggesting)

"The list of names to show now: the line, the column where the name starts, the names and which one is chosen. Or nothing."
suggestion(e) = begin
  caretless(e.buf) && return nothing
  found = offered(e)
  state = suggesting(e)[]
  # A list that esc hid stays hidden while its name is being typed, and no longer
  if state.hidden != (0, 0) && (found === nothing || state.hidden != (found[1], found[2]))
    state = suggesting(e)[] = (at=state.at, chosen=state.chosen, hidden=(0, 0))
  end
  found === nothing && return nothing
  i, start, names = found
  state.hidden == (i, start) && return nothing
  (i, start, names, state.at == (i, start) ? clamp(state.chosen, 1, length(names)) : 1)
end

"What a key does while the list of names shows. It returns true when the key was for the list."
suggest_key!(e, K) = begin
  found = suggestion(e)
  found === nothing && return false
  i, start, names, chosen = found
  state = suggesting(e)
  if K == Keys.down || K == Keys.up
    state[] = (at=(i, start), chosen=mod1(chosen + (K == Keys.down ? 1 : -1), length(names)), hidden=(0, 0))
  elseif K == Keys.enter || K == Keys.tab
    complete!(e, i, start, names[chosen])
  elseif K == Keys.escape
    state[] = (at=(0, 0), chosen=1, hidden=(i, start))
  else
    return false
  end
  touch!(e)
  true
end

"The list of names, placed in the window under the name being typed. Nothing when there's no list to show."
suggestbox(e) = begin
  found = suggestion(e)
  found === nothing && return ()
  i, start, names, chosen = found
  it = item(e, i)
  s = it.content
  # Where the name starts, from the left of the page's text and from the top of the item, and the font of the list
  if s isa Sheet
    r = findfirst(==(i), s.rows)
    r === nothing && return ()
    f, dx = cellflow(s, r, length(s.cells[r]))
    k, x = spot(f, start)
    face = Face(SHEET_FONT, SHEET_WEIGHT, s.size, colours.ink, false)
    across, down = item_room(e, it)[1] + dx + x, row_top(s, r) + f.lh * k
  elseif s isa Flow
    # In a code block, the list is under the line of the screen that the name is on. In a wiki link too.
    k, x = spot(s, start)
    prose = kinds(e.buf)[i].kind != Kind.code
    face = prose ? body(e) : Face(codefont(), codestyle(), s.size, colours.ink, false)
    across, down = x, line_top(s, k) + s.lines[k].high
  else
    return ()
  end
  # In Julia code, each name has what it is at the right of its row, in a paler colour. A page has its folder there.
  notes = !(s isa Flow) ? fill("", length(names)) :
          prose ? [get(get(e.nodes, :wiki_notes, Dict{String,String}()), n, "") for n in names] : name_notes(e, i, names)
  pale = Face(face, color=colours.dim)
  span(note) = sum(((part, f),) -> measure(f, part), runs(note, pale), init=0px)
  needs(n, note) = measure(face, n) + (isempty(note) ? 0px : NOTE_GAP + span(note))
  wide = max(150px, maximum(map(needs, names, notes)) + 26px)
  list = Column(fixed(wide), Alignment.Start, padding(4px), radius(7px), background(colours.float), border(1px, :solid, colours.line), lifted,
    name="Names",
    [Row(width(grow=grow), height(face.size * 1.8), Alignment.Center, padding(8px, 0px), radius(4px),
         background(j == chosen ? colours.active : clear),
       (isempty(note) ? (Text(n, size=face.size, family=face.family, subfamily=face.style, color=colours.ink, wrap=WrapMode.none),) :
        (Box(Text(n, size=face.size, family=face.family, subfamily=face.style, color=colours.ink, wrap=WrapMode.none)),
         Box(width(grow=grow), height(1px)), spared(note, pale)...))...)
     for (j, (n, note)) in enumerate(zip(names, notes))]...)
  # A list that's too wide for the room at its right stays in the window
  left = clamp(text_left(e) + across - 9px, 8px, max(8px, window_size(e)[1] - 8px - wide))
  top = TOPBAR_H + PAGE_TOP + it.top - e.scroll.offset + down + 3px
  top >= TOPBAR_H || return ()
  (Row(width(grow=grow), height(grow=grow), Alignment.Start, padding(top, 0px, 0px, left), list),)
end

# --- the page's layout ---------------------------------------------------------------

# --- live blocks ---------------------------------------------------------------------
#
# A code block in the language `ui` holds Julia code. The page runs it once and
# shows its value where the block is: a UI node from any module, or any other
# value as text. The node is kept, so a node with state keeps it between frames.
# The code runs in the page's module, as the page's `julia` blocks do, so the
# two kinds of block share their names: see `page_module`.
#
# The code can use the names that pages use most with no line that loads them:
# UI.jl's components, like Slider and STLViewer, the parts of a layout, like
# Column and px, a file path as fs"notes.md" and a colour as colorant"tomato".

const LIVE = "ui"
const LIVE_GAP = 8px   # above and below what a live block shows

"The modules whose names a live block can use with no line that loads them"
const USUAL = ("github.com/jkroso/UI.jl/Interface/Semantic", "github.com/jkroso/UI.jl/Interface/Geometric")

"Give the module `m` each name that the module at `path` exports"
share!(m, path) = begin
  from = include_string(m, "@use $(repr(path))")
  # The module can be new, so its names are asked for as they are now
  for name in Base.invokelatest(names, from)
    # A menu and a tree each have an Item, so a block loads the one it means
    (name == nameof(from) || name == :Item) && continue
    Core.eval(m, :(const $name = $(Base.invokelatest(getglobal, from, name))))
  end
end

"""
The names that the window gives the code of its pages, with no line that
loads them, in a module of the window. No code runs in this module. Each
page's module has its names (see `usual_module`), and a name that acts on a
window, like `page_theme!`, acts on this window when it calls this module's.
"""
sandbox(e) = get!(e.nodes, :sandbox) do
  m = Module(Symbol("⭒window"))
  # Kip by the module that's loaded here, not by name. A built app can't find a package by name.
  Core.eval(m, :(const Kip = $Kip))
  Core.eval(m, :(using .Kip))
  foreach(path -> share!(m, path), USUAL)
  include_string(m, "@use \"github.com/jkroso/URI.jl/FSPath\" FSPath @fs_str")
  Core.eval(m, :(const $(Symbol("@colorant_str")) = $(var"@colorant_str")))
  # A live block can read and set the page's colours: `page_theme()` gives "Sepia", "Paper" or "Night"
  Core.eval(m, :(const page_theme = $(() -> (reads!(e, :theme); titlecase(string(e.theme))))))
  Core.eval(m, :(const page_theme! = $(name -> theme!(e, Symbol(lowercase(string(name)))))))
  # ... and the size of the page's text, in pixels
  Core.eval(m, :(const page_text_size = $(() -> (reads!(e, :zoom); TEXT_SIZE.value * e.zoom))))
  Core.eval(m, :(const page_text_size! = $(size -> text_size!(e, size))))
  # ... and the font of the page's text, by name
  Core.eval(m, :(const page_font = $(() -> (reads!(e, :font); e.font))))
  Core.eval(m, :(const page_font! = $(name -> font!(e, String(name)))))
  # ... and its weight, by name: `page_weights()` gives the weights that the font has, like "Light" and "Regular",
  # and `page_weight()` the one that the text is drawn in
  Core.eval(m, :(const page_weights = $(() -> (reads!(e, :font); [w.label for w in text_weights(e.font)]))))
  Core.eval(m, :(const page_weight = $(() -> (reads!(e, :font); reads!(e, :weight); nearest_weight(e.font, e.weight).label))))
  Core.eval(m, :(const page_weight! = $(name -> weight!(e, String(name)))))
  # ... and the width of the page, in pixels
  Core.eval(m, :(const page_width = $(() -> e.widest.value)))
  Core.eval(m, :(const page_width! = $(width -> page_width!(e, width))))
  # ... and whether the page checks its spelling
  Core.eval(m, :(const page_spelling = $(() -> (reads!(e, :spelling); e.spelling))))
  Core.eval(m, :(const page_spelling! = $(on -> spelling!(e, Bool(on)))))
  # ... and whether a page is written to its file when its window stops being the front window
  Core.eval(m, :(const page_autosave = $(() -> (reads!(e, :autosave); e.autosave))))
  Core.eval(m, :(const page_autosave! = $(on -> autosave!(e, Bool(on)))))
  # ... and whether the caret moves to a new place in a short time, and doesn't jump there
  Core.eval(m, :(const page_glide = $(() -> (reads!(e, :glide); e.glide))))
  Core.eval(m, :(const page_glide! = $(on -> glide!(e, Bool(on)))))
  # ... and whether the card of a link to a page shows the start of the page, while ⌘ is held
  Core.eval(m, :(const page_peeks = $(() -> (reads!(e, :peeks); e.peeks))))
  Core.eval(m, :(const page_peeks! = $(on -> peeks!(e, Bool(on)))))
  # ... and the agent that Ladder starts for a change or a question, by its name, and the names that it can be
  Core.eval(m, :(const page_agent = $(() -> (reads!(e, :ai); e.ai))))
  Core.eval(m, :(const page_agent! = $(name -> preferred_agent!(e, String(name)))))
  Core.eval(m, :(const agent_names = $(() -> [k.name for k in AGENT_KINDS])))
  # ... and whether a line of a file of code that's too long for the window goes on under itself
  Core.eval(m, :(const code_wrap = $(() -> (reads!(e, :wrap); e.wrap))))
  Core.eval(m, :(const code_wrap! = $(on -> wrap!(e, Bool(on)))))
  # ... and whether it shows the number of each line, and shades the line that the caret is on
  Core.eval(m, :(const code_numbers = $(() -> (reads!(e, :numbers); e.numbers))))
  Core.eval(m, :(const code_numbers! = $(on -> numbers!(e, Bool(on)))))
  Core.eval(m, :(const code_shade = $(() -> (reads!(e, :shade); e.shade))))
  Core.eval(m, :(const code_shade! = $(on -> shade!(e, Bool(on)))))
  # ... and how many spaces one step of indentation is in code: 2 or 4
  Core.eval(m, :(const code_indent = $(() -> (reads!(e, :indent); e.indent))))
  Core.eval(m, :(const code_indent! = $(n -> indent_width!(e, Int(n)))))
  # ... and how big code is, in pixels. It grows and shrinks with the page's text.
  Core.eval(m, :(const code_text_size = $(() -> (reads!(e, :code_scale); reads!(e, :zoom); code_size(e).value))))
  Core.eval(m, :(const code_text_size! = $(size -> code_size!(e, size))))
  # ... and the font of code, by the name in the list of `code_fonts()`. `code_family(name)` gives the font's own name, to draw the name in.
  Core.eval(m, :(const code_fonts = $(() -> font_label.(unique([code_fonts(); e.code_font])))))
  Core.eval(m, :(const code_family = $(name -> font_family(String(name)))))
  Core.eval(m, :(const code_font = $(() -> (reads!(e, :code_font); font_label(e.code_font)))))
  Core.eval(m, :(const code_font! = $(name -> code_font!(e, font_family(String(name))))))
  # ... and its weight, by name: `code_weights()` gives the weights that the font has, and `code_weight()` the one that code is drawn in
  Core.eval(m, :(const code_weights = $(() -> (reads!(e, :code_font); [w.label for w in text_weights(e.code_font)]))))
  Core.eval(m, :(const code_weight = $(() -> (reads!(e, :code_font); reads!(e, :code_weight); nearest_weight(e.code_font, e.code_weight).label))))
  Core.eval(m, :(const code_weight! = $(name -> code_weight!(e, String(name)))))
  # ... and after how many characters a faint line goes down a file of code. 0 is no line.
  Core.eval(m, :(const code_guide = $(() -> (reads!(e, :guide); e.guide))))
  Core.eval(m, :(const code_guide! = $(n -> guide!(e, Int(n)))))
  # ... and the key bindings. `key_bundles()` gives the names of the bundles, and `key_bundle()` the one that's chosen.
  # `key_list()` shows each command with its keys, and a click on one changes them. `keys_changed()` is true when a
  # command has other keys than the bundle's, and `key_reset!()` gives every command the bundle's keys again.
  Core.eval(m, :(const key_bundles = $(() -> String[first(b) for b in BUNDLES])))
  Core.eval(m, :(const key_bundle = $(() -> (reads!(e, :bundle); e.bundle))))
  Core.eval(m, :(const key_bundle! = $(name -> bundle!(e, String(name)))))
  Core.eval(m, :(const key_list = $(() -> own!(e, KeyList()))))
  Core.eval(m, :(const keys_changed = $(() -> (reads!(e, :bundle); reads!(e, :rebound); !isempty(e.rebound)))))
  Core.eval(m, :(const key_reset! = $(() -> bundle!(e, e.bundle))))
  # ... and the app that opens Markdown files: `markdown_app()` gives its name, like "Ladder", or "" when macOS can't say.
  # `default_app!()` asks macOS to make that app Ladder. It gives false when the Ladder app isn't installed.
  # `app_installed()` is true when the Ladder app is on this Mac.
  Core.eval(m, :(const markdown_app = $(() -> (reads!(e, :app); app_name(markdown_app())))))
  Core.eval(m, :(const app_installed = $(() -> (reads!(e, :app); !isempty(app_path())))))
  Core.eval(m, :(const default_app! = $(() -> default_app!(e))))
  # ... and the app's own updates. `app_updates()` is true when the app gets a newer version without being asked.
  # `update_news()` says how far an update has got. `update_offer()` is what a button can do about it now, like
  # "Check now", or "" for nothing. `update!()` does that.
  Core.eval(m, :(const app_updates = $(() -> (reads!(e, :updates); e.updates))))
  Core.eval(m, :(const app_updates! = $(on -> updates!(e, Bool(on)))))
  Core.eval(m, :(const update_news = $(() -> update_news(e))))
  Core.eval(m, :(const update_offer = $(() -> (reads!(e, :updates); reads!(e, :update); Update.label(Update.own())))))
  Core.eval(m, :(const update! = $(() -> update_act!(e))))
  # ... and the names that code from the startup page adds
  foreach(f -> f(m, e), values(PAGE_NAMES))
  # The units that a sheet has, from Units.jl, so that code can work with lengths, times and so on: 12m * 2.4m.
  # They come in with `using`, so a name that a block makes or loads for itself wins over a unit with that name.
  Core.eval(m, :(const SheetUnits = $(units())))
  Core.eval(m, :(using .SheetUnits))
  m
end

"""
Note that the live block that's running now asked for a setting of the page:
`:theme`, `:zoom` or `:font`. Such a block is run again when the setting changes, so
what it shows stays true.
"""
reads!(e, setting::Symbol) = begin
  key = get(e.nodes, :running, nothing)
  key === nothing || push!(get!(() -> Set{Any}(), e.nodes, (:readers, setting)), key)
  nothing
end

"""
Ask macOS to make Ladder the app that opens Markdown files, for the button on
the settings page. macOS asks you to confirm, so the window then looks for
your answer. It's false when the Ladder app isn't installed.
"""
default_app!(e) = begin
  before = markdown_app()
  make_default!() || return false
  e.nodes[:asked] = (time(), before, time())
  true
end

"Run again the live blocks that asked for `setting`"
rerun!(e, setting::Symbol) = foreach(pop!(e.nodes, (:readers, setting), ())) do key
  # What the block made before is kept until it runs again, so that what it makes then can
  # carry on from it, like a chooser whose choice was clicked sliding to it
  old = pop!(e.nodes, key, nothing)
  old === nothing || (e.nodes[(:replaced, key)] = old)
end

"""
Wrap the page's text again, for a live block that changed a setting. The block
under the mouse stays where it is in the window, so a slider that's being
dragged doesn't move up or down, away from the mouse.
"""
rewrap!(e) = begin
  save_settings!(e)
  empty!(e.flows)
  win = window_of(e)
  if win !== nothing && !isempty(e.layout)
    y = win.mouse[2] - TOPBAR_H - PAGE_TOP + e.scroll.offset
    i = findfirst(it -> it.top <= y < it.top + it.tall, e.layout)
    i === nothing || (e.nodes[:hold] = (e.layout[i].first, e.layout[i].top - e.scroll.offset))
  end
  e
end

"Make the page's text `size` pixels tall, for a live block or the command palette. Sizes are from 11 to 42."
text_size!(e, size::Real) = (e.zoom = zoom_for(size); rewrap!(e))

const NARROWEST, WIDEST = 400, 1200   # the page widths that the settings page offers

"""
Make the page `width` pixels wide, to the nearest ten, for a live block. That's
its width while the text is its usual size: bigger text gets a wider page, so
a line holds as many words as before. A window that's too narrow for the page
shows it as wide as it can.
"""
page_width!(e, width) = (e.widest = px(clamp(10round(Int, width / 10), NARROWEST, WIDEST)); rewrap!(e))

"Draw the page's text in the font called `name`"
font!(e, name::String) = (e.font = name; save_settings!(e); rerun!(e, :font); restyle!(e))

"Draw the page's text in the weight called `w`, like \"Light\", or in the weight `w`, like 300"
weight!(e, w::Union{Integer,AbstractString}) = begin
  e.weight = w isa Integer ? text_weight(w) : weight_called(e.font, w)
  save_settings!(e)
  rerun!(e, :weight)
  restyle!(e)
end

"Use the colours called `name` for the page"
theme!(e, name::Symbol) = begin
  name in THEME_ORDER || error("The page's colours are Sepia, Paper and Night. $name isn't one of them.")
  e.theme = name
  save_settings!(e)
  rerun!(e, :theme)
  restyle!(e)
end

# The errors of the live blocks that failed. The app's self-test reads it, to check its own pages.
const problems = String[]

"""
Run the code of a live block and return a UI node that shows its value, or its
error. `key` is where the editor keeps what the code made. With `inline`, the
code is in a line of text: a value that isn't a node comes back as its text,
with true if the text says what went wrong.
"""
evaluate(e, code::String; key=(:live, e.buf.path, code), inline=false) = begin
  path = e.buf.path
  # The code can load the drawing methods of a node, and the frame that runs it
  # can't call them yet. So the window draws one more frame soon after.
  e.nodes[:ran] = true
  e.nodes[:running] = key
  try
    # Kip finds a path like "./widgets.jl" from the folder of the document, and so does a relative FSPath
    cd(isdir(docdir(e)) ? docdir(e) : pwd()) do
      # The code runs in the page's module, with the page's other code
      value = running_code(m -> (inline ? run_sum : run_in)(m, code, isempty(path) ? joinpath(e.folder, "untitled.md") : path), e)
      node = inline ? present_inline(value) : present(value)
      # Keep the amount, with its unit, so a chart can read that and not the words around it
      inline && node === nothing && (e.nodes[(:amount, key[2], key[3], key[4])] = value)
      node !== nothing ? node : inline ? (said(value), false) : note(repr("text/plain", value), colours.ink)
    end
  catch err
    err = err isa LoadError ? err.error : err
    inline && length(key) == 4 && delete!(e.nodes, (:amount, key[2], key[3], key[4]))
    push!(problems, sprint(showerror, err))
    # A line of text has room for the first line of what went wrong
    inline ? (said(first(split(sprint(showerror, err), '\n'))), true) : note(sprint(showerror, err), colours.accent)
  finally
    delete!(e.nodes, :running)
    CODE_RUNS[] += 1   # the page's `check` blocks run again
  end
end

"""
The node that shows `value` in a live block, or nothing to show it as text. Add
a method to show a type of your own as a node.
"""
present(value) = nothing
present(node::Union{SemanticUI,GeometricUI}) = node
# Text on its own goes in a box as wide as the page, so that it wraps and takes the page's colours
present(text::Text) = Box(width(grow=grow), Alignment.Start, text)
present(p::FSPath) = begin
  path = abspath(string(p))
  path = ispath(path) ? realpath(path) : path
  Breadcrumb(at=length(path) > 1 ? String(rstrip(path, '/')) : path)
end

"""
The node that shows `value` in a line of text, for inline code, or nothing to
show it as text. It's what a live block shows, unless a type has a method here.
"""
present_inline(value) = present(value)
present_inline(text::Text) = Box(Alignment.Start, text)
# A file path in a line of text is as wide as its names. Its list floats under it.
present_inline(p::FSPath) = (l = present(p); l.inline = true; l)

note(text, colour) = Box(width(grow=grow), padding(BLOCK_X, 10px), background(colours.block),
  Text(String(text), size=13px, family=codefont(), subfamily=codestyle(), color=colour))

"""
What a live block shows: the node that its code made. The code can make a
layout with nodes in it, like `Column(Checkbox(), Checkbox())`. Making the
Column describes each Checkbox once, so each frame describes them again, and
a click on a checkbox shows.
"""
@def mutable struct Shown <: SemanticUI
  value::Any = nothing   # a SemanticUI or a GeometricUI
  was::Theme = light     # the theme that the text in a GeometricUI value has now
  inline::Bool = false   # made by inline code, so it's in a line of text and only as wide as what it shows
end

cursor(::Shown) = :arrow

# A drag that starts in a live block is the block's. The page's text doesn't select as the mouse moves.
onmouse(s::Shown, ::MouseMove) = held(s, Keys.mouse_left) ? handled : nothing

# The components in the block get the page's colours
describe(s::Shown) = begin
  e = editor(s)
  t = component_theme(e.zoom)
  was, s.was = s.was, t
  with_theme(t) do
    # A diagram, a model and a video have a button that makes them fill the window. One that fills it leaves its room here empty.
    what = s.inline ? nothing : fill_what(s.value)
    what !== nothing && what[1] == :node && zoomed_node(e, s.value) && return Column(width(grow=grow), Alignment.Start, held_room(e))
    inner = s.value isa SemanticUI ? Base.invokelatest(convert, GeometricUI, s.value) : redescribe!(detach!(s.value), t, was)
    what === nothing || (inner = fillable(s, what, inner, wide=fill_wide(s.value)))
    s.inline ? Row(width(grow=grow), Alignment.Center, inner) : Column(width(grow=grow), Alignment.Start, inner)
  end
end

# What inline code made can float a list over the page, as a file path does. A
# click in that list is the list's, so it stops here, before the page's text sees it.
onkey(s::Shown, ev::KeyPress{Keys.mouse_left}) = begin
  s.inline || return nothing
  r = rect(s)
  x, y = ev.window.mouse
  r !== nothing && r.left <= x < r.left + r.width && r.top <= y < r.top + r.height ? nothing : handled
end

"""
Describe again each semantic node in `geo`, and put the new geometry where the
old geometry was. Text that has the colours of the theme `was` gets the colours of `t`.
"""
redescribe!(geo, t, was) = begin
  child = geo.firstchild
  while child !== nothing
    next = child.nextsibling
    if child isa GeometricUI && child.from isa SemanticUI
      new = Base.invokelatest(convert, GeometricUI, child.from)
      new === child || swap!(child, new)
    elseif child isa GeometricUI
      redescribe!(child, t, was)
    elseif child isa Text
      adopt_theme!(child, t, was)
    end
    child = next
  end
  geo
end

"Put `new` in the place of `old` among its siblings"
swap!(old, new) = begin
  parent, prev, next = old.parent, old.prevsibling, old.nextsibling
  detach!(new)
  setfield!(new, :parent, parent)
  setfield!(new, :prevsibling, prev)
  setfield!(new, :nextsibling, next)
  prev === nothing ? setfield!(parent, :firstchild, new) : setfield!(prev, :nextsibling, new)
  next === nothing || setfield!(next, :prevsibling, new)
  setfield!(old, :parent, nothing)
  setfield!(old, :prevsibling, nothing)
  setfield!(old, :nextsibling, nothing)
  new
end

# --- files in a live block ---------------------------------------------------------------
#
# An FSPath shows as a breadcrumb: the name of each folder on the way to it,
# in a row. Click the last name to list what's in that folder under the
# breadcrumb, and click an earlier name to go to that folder. A click on a
# line of the list makes that file or folder the path, so its name joins the
# breadcrumb. The Open button, a square at the right end of the names, shows the file in
# the window, or the folder in the sidebar, as a link to it does. A click with ⌘
# held on a name or on a line of the list does the same for that file or folder.
# A breadcrumb in a line of text has no Open button, but a click with ⌘ held works.
# Under a path to a file is a preview of the file:
#
#   - a picture, of any kind that Skia or macOS reads
#   - the model in an STL or 3MF file
#   - a player for a sound or a video file
#   - the pages of a PDF file, one at a time
#   - a CSV file as a table, and the list of the files in a zip
#   - a Markdown file as it reads
#   - the text of any other text file, which the wheel scrolls through. The lines
#     of a file of code have the colours that a code block gives them.
#   - the picture that the Finder shows, for a file like a Word file or a font
#
# A sound or a video plays on while you scroll the page and type in it. It stops
# when the path goes to another file, when the preview closes and when the window
# shows another page.

"One line of the list under a Breadcrumb: a file or a folder"
@def mutable struct FileEntry <: SemanticUI
  path::String = ""
end

"One name in a Breadcrumb"
@def mutable struct Crumb <: SemanticUI
  path::String = ""
  name::String = ""
end

"The path `at`, as the names of the folders on the way to it"
@def mutable struct Breadcrumb <: SemanticUI
  at::String = ""
  open::Bool = false     # is the list of what's in the folder showing?
  # Kept so each name and each line knows when the mouse is over it
  crumbs::Dict{String,Crumb} = Dict{String,Crumb}()
  entries::Dict{String,FileEntry} = Dict{String,FileEntry}()
  # The STLViewer of the model at `at`, the player of the sound or the video there, or the Pages
  # of the PDF file there. It's kept so that the model stays as it was turned, the file plays on
  # from one frame to the next, and the page stays the one you turned to.
  viewer::Any = nothing
  text::Any = nothing    # what `kept!` keeps of the file at `at`, like its text, or false if it has none
  read::Any = nothing    # what `text` is: its kind, the path of its file and when the file last changed
  inline::Bool = false   # in a line of text, so its list floats under it and takes no room on the page
  folders::Bool = false  # only a folder can be the path, as when you choose where something is kept. The folder needn't be made yet.
  room::Union{Nothing,px} = nothing   # how wide it can be, when it has less room than the page is wide
  button::Any = nothing  # its OpenButton, once it has shown
  files::Any = nothing   # a function of a file's name that's true for the files the list shows, when it picks a file of some kinds. Folders always show.
end

"The button at the right end of a breadcrumb's names that shows its file or its folder in the window. It shows while the mouse is over the breadcrumb."
@def mutable struct OpenButton <: SemanticUI
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)   # where it was last drawn, to put its tooltip under it
  quiet::Bool = false                         # clicked, so no tooltip until the mouse leaves it
end

"The list or the preview under a breadcrumb that's in a line of text. It floats over the page."
@def mutable struct Listing <: SemanticUI
  of::Any = nothing   # the Breadcrumb
end

const LISTING_W = 340px

describe(f::Listing) =
  Column(width(grow=grow), Alignment.Start, padding(6px), radius(8px), background(colours.block), border(1px, :solid, colours.line),
         lifted, child_gap=1px, contents(f.of)...)

"Show the list of a breadcrumb that's in a line of text when it's open, and take the list away when it isn't"
list!(l::Breadcrumb, w) = begin
  w === nothing && return
  l.open || return close_popup!(w, :listing)
  e = editor(l)
  popup!(w, Listing(of=l), anchor=l, gap=4px, width=min(LISTING_W, e.width), key=:listing, onclose=() -> (l.open = false),
         theme=component_theme(e.zoom))
end

const MOST_FILES = 100

entry(l::Breadcrumb, path) = get!(() -> own!(l, FileEntry(path=path)), l.entries, path)

"The name and the path of each step on the way to `path`. The home folder `home` is one step, named ~."
steps(path, home=homedir()) = begin
  inside = path == home || startswith(path, home * "/")
  at = inside ? home : "/"
  out = [(inside ? "~" : "/", at)]
  for name in splitpath(relpath(path, at))
    name == "." && continue
    at = joinpath(at, name)
    push!(out, (name, at))
  end
  out
end

"The files and folders in `dir` that aren't hidden, folders first"
listing(dir) = begin
  names = try filter(n -> !startswith(n, "."), readdir(dir)) catch; String[] end
  sort!(names, by=n -> (!isdir(joinpath(dir, n)), lowercase(n)))
end

describe(l::Breadcrumb) = begin
  l.open || hush!(l)
  names = [get!(() -> own!(l, Crumb(path=path, name=name)), l.crumbs, path) for (name, path) in steps(l.at)]
  arrow() = Icon("chevron-right", size=9px, color=colours.faint)
  # The first name and as many of the last names as fit. An … stands for the names left out.
  # An open breadcrumb that isn't in a line of text is in a panel with what's under it, so it has less room
  panel = l.open && !l.inline
  # A path to a file or a folder has a button at the right end of its names that shows it in the window.
  # The button shows only while the mouse is over the breadcrumb. Its room is kept, so the names don't move.
  # A breadcrumb in a line of text has no room for it: a click with ⌘ held does the same.
  opens = !l.inline && !l.folders && l.files === nothing && ispath(l.at)
  opens && l.button === nothing && (l.button = own!(l, OpenButton()))
  n = fitting(map(wide, names), something(l.room, editor(l).width) - (panel ? 2PANEL_PAD : 0px) - (opens ? FILL_SIDE + 2CRUMB_GAP : 0px))
  kept = n < length(names) - 1 ? Any[names[1], Box(width(DOTS_W), label("…", color=colours.dim)), names[end-n+1:end]...] : names
  parts = Iterators.flatten(i == 1 ? (c,) : (arrow(), c) for (i, c) in enumerate(kept))
  l.inline && return Row(height(24px), child_gap=CRUMB_GAP, clip=true, parts...)
  trail = Row(width(grow=grow), height(30px), child_gap=CRUMB_GAP, clip=true, parts...,
              (opens ? (Box(width(grow=grow)), ishovered(l) ? l.button : Box(width(FILL_SIDE), height(FILL_SIDE))) : ())...)
  panel || return Column(width(grow=grow), Alignment.Start, trail)
  # One background goes round the names and what's under them, to show that they're one thing
  Column(width(grow=grow), Alignment.Start, padding(PANEL_PAD), radius(8px), background(colours.block), child_gap=1px,
    trail, contents(l)...)
end

const PANEL_PAD = 6px

"What shows under an open breadcrumb: the lines of a folder, or the preview of a file"
contents(l::Breadcrumb) = begin
  l.folders && !isdir(l.at) &&
    return (Row(width(grow=grow), height(26px), padding(10px, 0px), label("This folder isn't made yet", 12px, color=colours.dim)),)
  isdir(l.at) || return (preview(l, l.at),)
  hush!(l)
  l.viewer = l.text = nothing
  names = listing(l.at)
  l.folders && filter!(n -> isdir(joinpath(l.at, n)), names)
  l.files === nothing || filter!(n -> isdir(joinpath(l.at, n)) || l.files(n), names)
  shown = first(names, MOST_FILES)
  isempty(names) && return (Row(width(grow=grow), height(26px), padding(10px, 0px),
                                label(l.files === nothing ? "This folder is empty" : "This folder has no file of the kind to choose", 12px, color=colours.dim)),)
  ((entry(l, joinpath(l.at, n)) for n in shown)...,
   (length(names) > length(shown) ? (Row(width(grow=grow), height(26px), padding(10px, 0px),
      label("and $(length(names) - length(shown)) more", 12px, color=colours.dim)),) : ())...)
end

const CRUMB_GAP = 2px
const ARROW_W = 9px
const DOTS_W = 18px
const LONGEST_NAME = 28   # characters. A longer name loses its middle.

"A name with its middle left out if it's long, like 8ebf6aee-d8a…e60dbee0e511"
short(name) = length(name) <= LONGEST_NAME ? name :
  first(name, LONGEST_NAME ÷ 2 - 1) * "…" * last(name, LONGEST_NAME ÷ 2)

"How wide a name of a breadcrumb is. The last name is bold and has an icon."
wide(c::Crumb) = begin
  last = c.path == (c.parent::Breadcrumb).at
  measure(Face(SANS, last ? "Semibold" : "", 13px, colours.ink, false), short(c.name)) + 12px + (last ? 19px : 0px)
end

"How many of the last names fit in `room` after the first name, when an … stands for the rest"
fitting(widths, room) = begin
  step = ARROW_W + 2CRUMB_GAP
  sum(widths) + step * (length(widths) - 1) <= room && return length(widths) - 1
  used = widths[1] + step + DOTS_W
  n = 0
  for w in Iterators.reverse(widths[2:end])
    used += step + w
    used > room && n > 0 && break
    n += 1
  end
  min(n, length(widths) - 2)
end

describe(c::Crumb) = begin
  l = c.parent::Breadcrumb
  last = c.path == l.at
  Row(height(24px), padding(6px, 0px), radius(5px), child_gap=6px,
      background(last && l.open ? colours.active : ishovered(c) ? colours.hover : clear),
    (last ? (Icon(l.folders || isdir(c.path) ? "folder" : file_icon(c.path), size=13px, color=colours.dim),) : ())...,
    Box(label(short(c.name), color=last ? colours.ink : colours.dim, weight=last ? "Semibold" : "")))
end

cursor(::Crumb) = :hand

# The last name shows and hides the list. An earlier name goes to its folder.
onkey(c::Crumb, ev::KeyPress{Keys.mouse_left}) = begin
  l = c.parent::Breadcrumb
  # In a line of text, a click with ⌥ held shows the code and leaves the path as it is
  l.inline && only_held(c, Keys.opt) && return nothing
  only_held(c, Keys.cmd) && !l.folders && return show_crumb!(l, c.path, ev.window)
  c.path == l.at ? (l.open = !l.open) : (l.at = c.path; l.open = true)
  l.inline && list!(l, ev.window)
  nothing
end

# It looks like the button that makes a picture fill the window, as it also shows one thing in the whole window
describe(b::OpenButton) = begin
  ishovered(b) || (b.quiet = false)
  square_button("arrows-fullscreen", ishovered(b))
end

cursor(::OpenButton) = :hand
draw(ctx, size, ui::ConcreteRect, b::OpenButton) = (b.rect = (ui.left, ui.top, ui.width, ui.height); nothing)

onmouse(b::OpenButton, ev::MouseMove) = begin
  b.quiet && return handled
  tip = isdir((b.parent::Breadcrumb).at) ? "Show this folder in the window" : "Show this file in the window"
  show_tooltip!(ev.window, tip_label(tip), b.rect..., placement=:bottom, gap=6px)
  handled
end

onkey(b::OpenButton, ev::KeyPress{Keys.mouse_left}) = begin
  b.quiet = true
  hide_tooltip!(ev.window)
  l = b.parent::Breadcrumb
  show_crumb!(l, l.at, ev.window)
end

"""
Show the file or the folder at `path` in the window, as the path in the top
bar does. The breadcrumb `l` holds the path. When it's in a line of text, its
list closes first. A breadcrumb in a part of another page shows it in the window too.
"""
show_crumb!(l::Breadcrumb, path, window) = begin
  l.inline && l.open && (l.open = false; list!(l, window))
  open_folder!(top_editor(editor(l)), path)
  handled
end

describe(r::FileEntry) = begin
  folder = isdir(r.path)
  Row(width(grow=grow), height(26px), padding(10px, 0px), radius(5px), child_gap=8px, clip=true,
      background(ishovered(r) ? colours.hover : clear),
    Icon(folder ? "folder" : file_icon(r.path), size=13px, color=colours.dim),
    Box(width(grow=grow), Alignment.Start, label(basename(r.path))),
    (folder ? () : (Box(label(bytes(filesize(r.path)), 12px, color=colours.dim)),))...)
end

"A file's size in words, like 6.5 KB"
bytes(n) = begin
  n < 1000 && return "$n bytes"
  for unit in ("KB", "MB", "GB")
    n /= 1000
    (n < 1000 || unit == "GB") && return "$(n < 10 ? round(n, digits=1) : round(Int, n)) $unit"
  end
end

const PICTURES = (".png", ".jpg", ".jpeg", ".gif", ".webp", ".bmp")
const PREVIEW_LINES = 12
const MODELS = (".stl", ".3mf", ".glb", ".gltf")   # the files of 3D models that the viewer reads
const MODEL_HEIGHT = 260px
# The sound and the video files that macOS plays
const SOUNDS = (".mp3", ".m4a", ".wav", ".aif", ".aiff", ".aac", ".flac", ".caf")
const VIDEOS = (".mp4", ".mov", ".m4v")

"The viewer of the model in the STL, 3MF or glTF file at `path`, or nothing if the file can't be read as a model"
model(l::Breadcrumb, path) = begin
  v = l.viewer
  (v isa STLViewer && v.path == path) || (hush!(l); v = l.viewer = own!(l, STLViewer(path=path, height=MODEL_HEIGHT)))
  load!(v) isa Mesh ? v : nothing
end

"The player of the sound or the video file at `path`. `Player` is AudioPlayer or VideoPlayer."
player(l::Breadcrumb, path, Player) = begin
  v = l.viewer
  (v isa Player && v.path == path) && return v
  hush!(l)
  l.viewer = own!(l, Player === VideoPlayer ? VideoPlayer(path=path, height=MODEL_HEIGHT) : AudioPlayer(path=path))
end

"Stop the sound or the video that the breadcrumb's player is playing, and end the program of a SolidCraft design that it shows"
hush!(l::Breadcrumb) = (l.viewer isa Union{AudioPlayer,VideoPlayer} && pause!(l.viewer); l.viewer isa Designs.DesignView && Designs.close!(l.viewer); l)

"""
What shows the SolidCraft design at `path` under a path and in a `view` block:
the design alone, which you turn and nothing changes. The file's own page is
the editor: see "a SolidCraft design".
"""
design(l::Breadcrumb, path) = begin
  v = l.viewer
  (v isa Designs.DesignView && v.path == path) && return v
  hush!(l)
  l.viewer = own!(l, Designs.DesignView(path=path, readonly=true, fill=false, height=MODEL_HEIGHT))
end

const LINE_H = 18px          # the height of a line of a file's text
const TEXT_PAD = 8px         # above the first line and under the last
const MOST_TEXT = 400_000    # bytes. The preview of a longer file stops there.
const MOST_PAGE = 20_000_000 # bytes. A file that shows as a page shows this much of its text: see "the lines of a long file".

"""
The text of the file that a breadcrumb previews. It's kept so that the file
is read once, and so that the text stays where you scrolled it to.
"""
mutable struct FileText
  lines::Vector{String}
  more::Bool        # the file is longer than what was read
  scroll::Scroll
end

FileText(lines, more) = FileText(lines, more, Scroll(width(grow=grow), height(LINE_H * min(length(lines), PREVIEW_LINES) + 2TEXT_PAD)))

"""
The lines of the file at `path` and whether it has more, or nothing if it isn't
text. With `tidy`, a tab is two spaces and a long line stops at 200 characters,
which is how the lines of a file of code are shown. No more than `most` bytes
of the file are read.
"""
reading(path; tidy=true, most=MOST_TEXT) = begin
  # Julia makes room for as many bytes as it's asked to read, so it's asked for no more than the file has
  bytes = open(io -> read(io, min(most, filesize(path)) + 1), path)
  more = length(bytes) > most
  more && resize!(bytes, most)
  (isempty(bytes) || 0x00 in view(bytes, 1:min(length(bytes), 4000))) && return nothing
  s = String(bytes)
  # A file that was cut short can stop part way through a character
  for _ in 1:3
    (isvalid(s) || !more) && break
    s = String(codeunits(s)[1:end-1])
  end
  isvalid(s) || return nothing
  lines = [tidy ? String(first(replace(rstrip(line, '\r'), '\t' => "  "), 200)) : String(rstrip(line, '\r')) for line in split(s, '\n')]
  # The last line of a file that was cut short isn't all there, and a file that ends with a new line has no line after it
  (more || isempty(lines[end])) && length(lines) > 1 && pop!(lines)
  lines, more
end

"""
What the breadcrumb `l` keeps of the file at `path`: what `make(path)` gave, or
nothing if `make` found nothing to show. It's made again when the file changes.
`kind` names what's kept, so that two kinds of preview don't take each other's.
"""
kept!(make, l::Breadcrumb, path, kind) = begin
  key = (kind, path, mtime(path))
  l.read == key || (l.read = key; l.text = something(make(path), false))
  l.text === false ? nothing : l.text
end

"The text of the file at `path` for the breadcrumb `l`, or nothing if the file isn't text"
text!(l::Breadcrumb, path) = kept!(l, path, :text) do path
  found = reading(path)
  found === nothing ? nothing : FileText(found...)
end

"""
`n` rows that are each `high` tall, `PREVIEW_LINES` of them at a time. The
wheel scrolls through the rest. `row(i)` makes row `i`. Only the rows in view
are made, so a long file costs no more than a short one.
"""
scrolled(row, scroll::Scroll, n, high=LINE_H) = begin
  lo = clamp(floor(Int, (scroll.offset - TEXT_PAD) / high), 0, max(0, n - PREVIEW_LINES))
  hi = min(n, lo + PREVIEW_LINES + 2)
  Box(width(grow=grow), padding(10px, 0px), radius(5px), background(colours.bg), clip=true,
    reuse!(scroll, Column(width(grow=grow), Alignment.Start,
      spacer(TEXT_PAD + high * lo),
      [row(i) for i in lo+1:hi]...,
      spacer(TEXT_PAD + high * (n - hi)))))
end

"For each line of a file's text, the quote of a docstring that's open at its start, or '\\0', worked out once for each FileText"
const TEXT_OPENS = WeakKeyDict{FileText,Vector{Char}}()

"The text of a file. `lang` is the end of the file's name, like jl."
textview(t::FileText, lang) = begin
  at = get!(() -> (q = '\0'; [(o = q; q = left_open(l, lang, q); o) for l in t.lines]), TEXT_OPENS, t)
  scrolled(i -> codeline(t.lines[i], lang, at[i]), t.scroll, length(t.lines))
end

"""
One line of a file's text. A file of code has the colours that a code block
has: `lang` is the end of the file's name, like jl, and a file that isn't code
is all one colour. `open` is the quote of a docstring that's open at the start
of the line, or '\\0'.
"""
codeline(line, lang, open='\0') = Row(height(LINE_H),
  [part for t in tokens(line, lang, open)
        for part in spared(t.text, Face(codefont(), t.kind == :comment ? codeslant() : codestyle(), 12px,
                                        t.kind == :plain ? colours.ink : getfield(colours, t.kind), false))]...)

# --- the files in a zip -------------------------------------------------------------------

const ZIPS = (".zip", ".jar")
const MOST_ZIP = 300_000_000   # bytes. A bigger zip isn't read.

"The files in the zip at `path`, as lines of text: the name of each and how big it is once it's unpacked"
zipped(path) = begin
  filesize(path) > MOST_ZIP && return nothing
  found = try ThreeMF.entries(read(path)) catch; return nothing end
  names = sort!([name for name in keys(found) if !endswith(name, '/')])
  isempty(names) && return nothing
  wide = min(64, maximum(length, names))
  FileText([rpad(length(name) > 64 ? "…" * last(name, 63) : name, wide) * "   " * bytes(found[name].full) for name in names], false)
end

# --- a CSV file as a table --------------------------------------------------------------------

const TABLES = (".csv", ".tsv")
const ROW_H = 24px
const MOST_COLUMNS = 40

"The rows of a CSV file that a breadcrumb previews, and how wide each column is"
mutable struct FileTable
  rows::Vector{Vector{String}}
  widths::Vector{px}
  more::Bool
  scroll::Scroll
end

"The cells of one line of a CSV file, as csv.jl reads them. `mark` is the character between two cells."
const csv_cells = Csvs.cells

"The rows of the CSV file at `path`. The mark between its cells is the one its first line has most of: a comma, a tab or a semicolon."
tabled(path) = begin
  found = reading(path, tidy=false)
  found === nothing && return nothing
  lines, more = found
  lines = filter(!isempty, lines)
  isempty(lines) && return nothing
  mark = argmax(c -> count(==(c), lines[1]), (',', '\t', ';'))
  rows = [first(csv_cells(line, mark), MOST_COLUMNS) for line in lines]
  columns = maximum(length, rows)
  face(r) = Face(SANS, r == 1 ? "Semibold" : "", 12px, colours.ink, false)
  # A column is as wide as the widest of its first hundred cells, and no wider than 240px
  widths = [clamp(maximum(r -> c <= length(rows[r]) ? measure(face(r), rows[r][c]) : 0px, 1:min(100, length(rows))), 24px, 240px) + 20px
            for c in 1:columns]
  FileTable(rows, widths, more, Scroll(width(grow=grow), height(ROW_H * min(length(rows), PREVIEW_LINES) + 2TEXT_PAD)))
end

"The rows of a CSV file as a table. Its first row is its headings."
tableview(t::FileTable) = scrolled(r -> tablerow(t, r), t.scroll, length(t.rows), ROW_H)

"""
Row `r` of a CSV file's table. It's as wide as the box that the table is in,
so its stripe reaches both sides. Each column takes a share of that width as
big as its share of the widths that its text needs, and never less than those,
as the table of a CSV file that fills the window does. The text of a cell is
in the middle of the row's height.
"""
tablerow(t::FileTable, r) = begin
  total = num(sum(t.widths))
  Row(width(grow=grow), height(ROW_H), radius(3px), background(r == 1 ? colours.head : iseven(r) ? clear : colours.stripe),
    [Row(width(percent=num(w) / total, min=w), height(ROW_H), padding(10px, 0px), Alignment.Center, clip=true,
         label(c <= length(t.rows[r]) ? t.rows[r][c] : "", 12px, weight=r == 1 ? "Semibold" : ""))
     for (c, w) in enumerate(t.widths)]...)
end

# --- a Markdown file as it reads ---------------------------------------------------------------

const PAGE_ZOOM = 0.8        # the text of a page under a path is this much smaller than the text of the page itself
const PAGE_HEIGHT = 320px    # the most of the page that shows. The wheel scrolls through the rest.

"The lines of a Markdown file that a breadcrumb previews, laid out as the page lays out its own lines"
mutable struct FilePage
  flows::Vector{Flow}
  tops::Vector{px}   # how far each line is under the first
  tall::px
  more::Bool
  scroll::Scroll
end

"How wide what's under the breadcrumb `l` is"
room(l::Breadcrumb) = (e = editor(l); (l.inline ? min(LISTING_W, e.width) : e.width - 2PANEL_PAD) - 12px)

"The Markdown file at `path`, laid out for the breadcrumb `l`. It's laid out again when the page's text changes its size, font, weight or colours."
filepage(l::Breadcrumb, path) = begin
  e = editor(l)
  wide = room(l) - 28px   # the page has 14px of room on each side
  kept!(l, path, (:page, wide, e.zoom, look_key(e), e.font, e.weight)) do path
    found = reading(path, tidy=false)
    found === nothing && return nothing
    lines, more = found
    kinds = classify(lines)
    zoom = e.zoom
    e.zoom = zoom * PAGE_ZOOM
    # -1 says that the line isn't one of the document's, so its inline code isn't run
    flows = try
      [laid(e, lines[i], kinds[i], false, -1, wide) for i in eachindex(lines)]
    finally
      e.zoom = zoom
    end
    tops = accumulate(+, map(tall, flows)) .- map(tall, flows)
    total = sum(tall, flows, init=0px)
    FilePage(flows, tops, total, more, Scroll(width(grow=grow), height(min(total + 2TEXT_PAD, PAGE_HEIGHT))))
  end
end

"A Markdown file as it reads. Only the lines in view are made."
pageview(e, p::FilePage) = begin
  from = p.scroll.offset - TEXT_PAD
  lo = something(findlast(<=(from), p.tops), 1)
  hi = something(findfirst(>(from + PAGE_HEIGHT), p.tops), length(p.tops) + 1) - 1
  under = p.tall - (p.tops[hi] + tall(p.flows[hi]))
  Box(width(grow=grow), padding(14px, 0px), radius(5px), background(colours.bg), clip=true,
    reuse!(p.scroll, Column(width(grow=grow), Alignment.Start,
      spacer(TEXT_PAD + p.tops[lo]),
      [describe(e, Item(0, 0, 0px, tall(f), f), f) for f in p.flows[lo:hi]]...,
      spacer(TEXT_PAD + under))))
end

# --- the pages of a PDF file --------------------------------------------------------------------

const PAGE_W = 420px   # how wide a page of a PDF file shows

"The pages of a PDF file, one at a time. A click on the left half goes back a page, and one on the right half goes on."
@def mutable struct Pages <: SemanticUI
  path::String = ""
  page::Int = 1
  count::Int = 0
  wide::px = PAGE_W   # how wide a page shows
end

describe(p::Pages) = begin
  # Twice as many pixels as px, so that the page is sharp on a screen with 2 pixels to the px
  key = pdf_page(p.path, p.page, round(Int, 2num(p.wide)))
  key === nothing && return label("This page can't be shown", 12px, color=colours.dim)
  shape = image_aspect(key)
  arrow(name, on) = Icon(name, size=11px, color=on ? colours.dim : colours.faint)
  Column(Alignment.Start, child_gap=6px,
    fillable(p, (:pdf, p.path, p.page), Image(key, fixed(p.wide), height(p.wide / shape), radius(3px), border(1px, :solid, colours.line))),
    (p.count > 1 ? (Row(fixed(p.wide), height(22px), justify=Alignment.Center, child_gap=10px,
       arrow("chevron-left", p.page > 1), label("Page $(p.page) of $(p.count)", 12px, color=colours.dim),
       arrow("chevron-right", p.page < p.count)),) : ())...)
end

cursor(p::Pages) = p.count > 1 ? :hand : :arrow

"Go on by `by` pages, as far as the first page or the last"
turn!(p::Pages, by) = (p.page = clamp(p.page + by, 1, max(1, p.count)); handled)

onkey(p::Pages, ev::KeyPress{Keys.mouse_left}) = begin
  focus(p)
  r = rect(p)
  r === nothing ? handled : turn!(p, ev.window.mouse[1] < r.left + p.wide / 2 ? -1 : 1)
end
# The arrow keys turn the pages too, once a click has given them the keyboard
onkey(p::Pages, ev::KeyPress{Keys.left}) = unmodified(ev) ? turn!(p, -1) : nothing
onkey(p::Pages, ev::KeyPress{Keys.right}) = unmodified(ev) ? turn!(p, 1) : nothing

"The pages of the PDF file at `path`, or nothing if it isn't a PDF file that macOS can read"
pager(l::Breadcrumb, path) = begin
  v = l.viewer
  v isa Pages && v.path == path && return v
  hush!(l)
  n = pdf_pages(path)
  n == 0 ? nothing : (l.viewer = own!(l, Pages(path=path, count=n)))
end

# --- what shows for each kind of file --------------------------------------------------------------

# The pictures that macOS reads and Skia doesn't
const MAC_PICTURES = (".heic", ".heif", ".tif", ".tiff", ".svg", ".ico", ".icns", ".psd")
# The files whose first page the Finder can show
const DOCUMENTS = (".rtf", ".rtfd", ".doc", ".docx", ".pages", ".key", ".numbers", ".xls", ".xlsx", ".ppt", ".pptx", ".odt", ".epub")
const FONTS = (".ttf", ".otf", ".ttc", ".woff", ".woff2")
const CODE = (".jl", ".js", ".mjs", ".cjs", ".ts", ".tsx", ".jsx", ".py", ".rb", ".rs", ".go", ".c", ".h", ".cc", ".cpp", ".hpp", ".swift",
              ".kt", ".java", ".sh", ".zsh", ".css", ".less", ".scss", ".mk", ".html", ".json", ".jsonl", ".toml", ".yml", ".yaml", ".xml", ".sql", ".lua")

"The icon for the file at `path`. It says what kind of file it is, from the end of the file's name."
file_icon(path) = begin
  ext = lowercase(splitext(path)[2])
  ext in MARKDOWN || ext == ".txt" ? "file-earmark-text" :
  ext in PICTURES || ext in MAC_PICTURES ? "file-earmark-image" :
  ext in SOUNDS ? "file-earmark-music" :
  ext in VIDEOS ? "file-earmark-play" :
  ext in MODELS || ext in DESIGNS ? "box" :
  ext == ".pdf" ? "file-earmark-pdf" :
  ext in ZIPS ? "file-earmark-zip" :
  ext in TABLES ? "file-earmark-spreadsheet" :
  ext in FONTS ? "file-earmark-font" :
  ext in DOCUMENTS ? "file-earmark-richtext" :
  ext in CODE ? "file-earmark-code" : "file-earmark"
end

"Every icon that `file_icon` can give, and those of a file that's only shown: of a binary file, and of the button that opens the file in its own app. The built app reads them all when it's made."
const FILE_ICONS = ("file-earmark", "file-earmark-text", "file-earmark-image", "file-earmark-music", "file-earmark-play", "box",
                    "file-earmark-pdf", "file-earmark-zip", "file-earmark-spreadsheet", "file-earmark-font", "file-earmark-richtext",
                    "file-earmark-code", "file-earmark-binary", "box-arrow-up-right", "chevron-left", "chevron-right")

"The picture kept under `key`, no taller than `most` and no wider than 420px. A picture of a page has a line round it."
framed(key, most=260px; page=false) = begin
  shape = image_aspect(key)
  w = min(420px, most * shape)
  page ? Image(key, fixed(w), height(w / shape), radius(3px), border(1px, :solid, colours.line)) :
         Image(key, fixed(w), height(w / shape), radius(4px))
end

"""
What shows for the file at `path`, or nothing if the file has no preview. `ext`
is the end of the file's name. `note(words)` adds words to the line under the
preview.
"""
peek(l::Breadcrumb, path, ext, note) = begin
  mac = Sys.isapple()
  # A picture, a model and a video have a button that makes them fill the window
  pic(key, more...; kw...) = fillable(l, (:picture, key), framed(key, more...; kw...))
  if ext in PICTURES
    return pic(path)
  elseif ext in MAC_PICTURES
    key = picture(path)
    key === nothing || return pic(key)
  elseif ext in MODELS
    viewer = model(l, path)
    viewer === nothing || return fillable(l, (:node, viewer), viewer, wide=:grow)
  elseif ext in DESIGNS
    viewer = design(l, path)
    return fillable(l, (:node, viewer), viewer, wide=:grow)
  elseif mac && ext in SOUNDS
    return player(l, path, AudioPlayer)
  elseif mac && ext in VIDEOS
    p = player(l, path, VideoPlayer)
    return fillable(l, (:node, p), p, wide=video_wide(p))
  elseif mac && ext == ".pdf"
    found = pager(l, path)
    found === nothing || return found
  elseif ext in ZIPS
    list = kept!(zipped, l, path, :zip)
    list === nothing && return nothing
    note("$(length(list.lines)) file$(length(list.lines) == 1 ? "" : "s")")
    return textview(list, "")
  elseif ext in TABLES
    table = kept!(tabled, l, path, :table)
    table === nothing && return nothing
    note(table.more ? "the first $(length(table.rows) - 1) rows" : "$(length(table.rows) - 1) row$(length(table.rows) == 2 ? "" : "s")")
    return tableview(table)
  elseif ismarkdown(path)
    page = filepage(l, path)
    page === nothing && return nothing
    page.more && note("the first $(bytes(MOST_TEXT)) of $(bytes(filesize(path)))")
    return pageview(editor(l), page)
  elseif ext in DOCUMENTS || ext in FONTS
    key = thumbnail(path)
    return key === nothing ? nothing : pic(key, 400px, page=ext in DOCUMENTS)
  end
  text = text!(l, path)
  if text !== nothing
    text.more && note("the first $(bytes(MOST_TEXT)) of $(bytes(filesize(path)))")
    return textview(text, file_lang(path))
  end
  # The Finder has a picture for many kinds of file that have none here
  key = thumbnail(path)
  key === nothing ? nothing : pic(key)
end

"What shows under the path of a file: its picture, its model, its player, its pages or its text, and when it last changed"
preview(l::Breadcrumb, path) = begin
  isfile(path) || return Box(height(0px))
  ext = lowercase(splitext(path)[2])
  # A player that was made for another file stops when the path leaves that file
  l.viewer !== nothing && l.viewer.path != path && (hush!(l); l.viewer = nothing)
  about = "Changed " * Libc.strftime("%-d %b %Y, %H:%M", mtime(path))
  content = try
    peek(l, path, ext, words -> (about *= "  ·  " * words))
  catch
    nothing
  end
  content === nothing && (content = label("This file has no preview", 12px, color=colours.dim))
  Column(width(grow=grow), Alignment.Start, padding(6px), child_gap=8px,
    content, label(about, 12px, color=colours.dim))
end

cursor(::FileEntry) = :hand

onkey(r::FileEntry, ev::KeyPress{Keys.mouse_left}) = begin
  l = r.parent::Breadcrumb
  # A click with ⌘ held shows the file in the window, as a click on a link with ⌘ held does. In a `view` block any
  # click does, since the block shows the folder that its line names.
  (only_held(r, Keys.cmd) || l.parent isa ViewBlock) && !l.folders && return show_crumb!(l, r.path, ev.window)
  l.at = r.path
end

# --- a file that isn't Markdown, in the page -------------------------------------------------
#
# A click on a file in the sidebar shows the file in the page, whatever kind of
# file it is. Ladder changes Markdown files and Julia files, so any other file
# is only shown, and the top bar has a lock (see `ReadOnly`). The button beside
# the lock opens the file in the app that the Mac uses for it.
#
# A Julia file is one block of code, with no lines that open and close it. You
# type in it as in a `julia` code block of a page: ⌘Return runs the expression
# that the caret is in, a list offers names, a bracket comes with the bracket
# that closes it, and ⌘S writes the file. What its code comes to has three
# levels under the value, as it has in a `julia` code block: with the slider in
# the top bar, the box after a piece of code shows the code as Julia infers it,
# its LLVM code or its assembly.
# "what Julia code ran, down a level" says more.
#
#   - A file of text shows its text. A file of code has the colours that a code
#     block has. You can select the text, copy it and find words in it.
#   - A picture, a model, a sound, a video, a PDF file, a CSV file, a Word file
#     and a font show as they do under a file path, as big as the page has room for.
#   - A CSV file shows as a table as wide as the window, which you can sort and
#     filter by its headings. "a CSV file in the page" says more.
#   - A JSON file shows as a tree of its values. "a JSON file as a tree"
#     says more.
#   - A file of text, a CSV file and a JSON file have levels under what they
#     show: the file's text, its bytes in hexadecimal, and its bits. The
#     slider in the top bar goes to each. "the slider of the levels" says more.
#   - A zip shows the list of the files in it.
#   - Any other file is a binary file. The page says so, and a button there
#     shows the file's bytes in hexadecimal.

const MOST_LINE = 2000     # characters. A longer line of a file's text stops there.
const HEX = "hex"          # the language of the lines that show a file's bytes
const HEX_BYTES = 10       # the column of such a line where the bytes start, after their place in the file
const HEX_CHARS = 60       # the column where the same bytes start as characters
const MOST_HEX = 160_000   # bytes. The lines of a longer file stop there.
const BITS = "bits"        # the language of the lines that show a file's bytes as bits
const BITS_ROW = 6         # how many bytes such a line has, so that it's no longer than a line of hexadecimal
const BITS_CHARS = HEX_BYTES + 9BITS_ROW + 1   # the column of such a line where its bytes start as characters
const MOST_BITS = 80_000   # bytes. The lines of bits of a longer file stop there.

"True when a file whose name ends with `ext` has a viewer of its own, so it doesn't show as text"
viewed(ext) = ext in PICTURES || ext in MAC_PICTURES || ext in MODELS || ext in SOUNDS || ext in VIDEOS || ext == ".pdf" ||
              ext in TABLES || ext in DOCUMENTS || ext in FONTS

"A line of a file's text as the page shows it: a tab is two spaces, and a very long line stops with an …"
shown_line(line) = begin
  s = replace(line, '\t' => "  ")
  length(s) > MOST_LINE ? first(s, MOST_LINE) * "…" : String(s)
end

"The buffer that shows the file at `path`, which isn't Markdown. A JSON file shows as a tree and an HTML file as its page, or with `tree` false as their text."
look(path; tree=true) = begin
  ext = lowercase(splitext(path)[2])
  if ext in ZIPS
    return Buffer(path=path, view=:file)   # the list of what it holds: see "a zip file"
  elseif tree && ext in JSONS && json_of(path) !== nothing
    return Buffer(path=path, view=:file)
  elseif tree && ext in HTMLS && text_file(path)
    return Buffer(path=path, view=:file)   # the page that its HTML makes: see "an HTML file as its page"
  elseif !viewed(ext)
    shown = text_look(path)
    shown === nothing || return shown
  end
  Buffer(path=path, view=:file)
end

"The buffer that shows the text of the file at `path`, or nothing if the file isn't text"
text_look(path) = begin
  found = try reading(path, tidy=false, most=MOST_PAGE) catch; nothing end
  found === nothing && return nothing
  lines, more = found
  Buffer(path=path, view=:text, lines=map(shown_line, lines),
         about=more ? "First $(bytes(MOST_PAGE)) of $(bytes(filesize(path)))" : "")
end

"Whether each file that was asked about is text, with when the file was last read then. Only the last few are kept."
const TEXT_READ = Dict{String,Tuple{Float64,Bool}}()

"""
True when the file at `path` is text, so it can show as its text. A file is
read once to find out, and again after the page reads it again. A zip isn't
text: what shows for it is the list of its files.
"""
text_file(path) = begin
  lowercase(splitext(path)[2]) in ZIPS && return false
  at = get(READ, path, 0.0)
  kept = get(TEXT_READ, path, nothing)
  kept !== nothing && kept[1] == at && return kept[2]
  found = isfile(path) && (try reading(path, tidy=false) !== nothing catch; false end)
  length(TEXT_READ) >= 16 && empty!(TEXT_READ)
  TEXT_READ[path] = (at, found)
  found
end

"""
The ways that the file of `b` can show, from its lowest level to its highest,
or () for a page and for a file with one way to show. A file of text shows as
its bits, its bytes in hexadecimal and its text. A JSON file and a CSV file
have a level over their text: :file, which is the tree of the one and the
table of the other. So has an HTML file: the page that its HTML makes.
"""
file_views(b::Buffer) = begin
  (b.view in FILE_VIEWS && !isdir(b.path)) || return ()   # a folder that shows in the page has one way to show
  served_html(b) && return SERVED_VIEWS   # a page of HTML from a web server has no file of bits and bytes
  (json_page(b) || html_page(b)) && return FILE_VIEWS
  ext = lowercase(splitext(b.path)[2])
  ext in TABLES ? (text_file(b.path) ? FILE_VIEWS : ()) :
  viewed(ext) || !text_file(b.path) ? () : FILE_VIEWS[1:3]
end

"""
The bytes of the file at `path` as lines of text. Each line has the place of
its first byte in the file, then 16 bytes in hexadecimal, then the same bytes
as characters. A byte that isn't a character of plain text shows as a dot.
"""
hexlines(path) = begin
  data = open(io -> read(io, MOST_HEX), path)
  hex(row) = join((string(x, base=16, pad=2) for x in row), ' ')
  map(0:16:max(0, length(data) - 1)) do at
    row = data[at+1:min(at + 16, end)]
    rpad(string(at, base=16, pad=8), HEX_BYTES) * rpad(hex(row[1:min(8, end)]) * "  " * hex(row[9:end]), HEX_CHARS - HEX_BYTES) *
      String([0x20 <= x < 0x7f ? Char(x) : '.' for x in row])
  end
end

"What the top bar says of the bytes of the file at `path`: how many of them show, when not all do"
hex_about(path) = filesize(path) > MOST_HEX ? "First $(bytes(MOST_HEX)) of $(bytes(filesize(path)))" : ""

"""
The bytes of the file at `path` as lines of bits. Each line has the place of
its first byte in the file, then `BITS_ROW` bytes as the 8 bits of each, then
the same bytes as characters. A byte that isn't a character of plain text
shows as a dot.
"""
bitlines(path) = begin
  data = open(io -> read(io, MOST_BITS), path)
  map(0:BITS_ROW:max(0, length(data) - 1)) do at
    row = data[at+1:min(at + BITS_ROW, end)]
    rpad(string(at, base=16, pad=8), HEX_BYTES) * rpad(join((string(x, base=2, pad=8) for x in row), ' '), BITS_CHARS - HEX_BYTES) *
      String([0x20 <= x < 0x7f ? Char(x) : '.' for x in row])
  end
end

"True when the page shows a file's bytes, in hexadecimal or as bits. Each line keeps its columns, so the lines never wrap."
bytes_page(b::Buffer) = b.view in (:hex, :bits)

"What the top bar says of the bits of the file at `path`: how many of its bytes show, when not all do"
bits_about(path) = filesize(path) > MOST_BITS ? "First $(bytes(MOST_BITS)) of $(bytes(filesize(path)))" : ""

"""
The buffer that shows the file at `path` at the level `view`: :bits for its
bytes as bits, :hex for its bytes in hexadecimal, :text for its text, and
:file for what `look` shows, like the tree of a JSON file or the table of a
CSV file. A file that has no text shows as `look` shows it.
"""
look(path, view::Symbol) = begin
  view == :bits && return Buffer(path=path, view=:bits, lines=bitlines(path), about=bits_about(path))
  view == :hex && return Buffer(path=path, view=:hex, lines=hexlines(path), about=hex_about(path))
  (view == :text && text_file(path)) || return look(path)
  something(text_look(path), look(path))
end

"Show the bytes of the file that the page shows, in hexadecimal"
hex!(e) = begin
  b = e.buf
  (readonly(b) && isfile(b.path)) || return e
  b.lines, b.about, b.view = hexlines(b.path), hex_about(b.path), :hex
  b.caret = b.anchor = (1, 0)
  b.saved = b.version += 1
  e.scroll.offset = 0px
  focus(e)
  e
end

# --- a JSON file as a tree ---------------------------------------------------------------------
#
# A JSON file shows as a tree of its values, as the inspector of a `ui` block
# shows a Julia value. The first row is the file's whole value, so you can see
# whether the file holds an object or a list. Each key of an object, and each
# item of a list, is a row, a step in from the row of what holds it. The row
# of an object or a list has an arrow, and a click on the row opens it or
# closes it. ⌥-click opens or closes everything in it too. A closed one shows
# on its row what it holds, as much as the row has room for. An open one says
# how many keys or items it has, in its brackets: {3 keys} or [22 items]. At
# first the tree is open as far as about a window of rows goes. The place of
# an item in its list counts from 0, as JSON's own tools count it.
#
# A click also chooses the row and gives the tree the keyboard. Then ↑ and ↓
# go from row to row, → opens a row or goes into it, ← closes it or goes to
# the row that holds it, and Return opens or closes it. ⌘C copies the value of
# the row: a string as its text, and an object or a list as JSON. Esc gives
# the keyboard back to the page.
#
# The tree is the file at its highest level, as the graphics are of a page. ⌘E
# goes down a level to the file's text, which you can select and search, and
# ⌘E again goes back up to the tree, open as it was. The file has two more
# levels under its text: its bytes in hexadecimal, and under those its bits.
# The ladder in the top bar opens into a slider with a stop for each of the
# four levels. See "the slider of the levels". From its bits to its bytes to
# its text, the window stays at the same place in the file. A file that isn't
# JSON after all, and one bigger than MOST_JSON, only shows as text.
#
# Only the rows that are in the window are made, so a long tree costs no more
# to draw than a short one.

const JSONS = (".json", ".geojson")
const MOST_JSON = 32_000_000   # bytes. A bigger JSON file only shows as text.
const JSON_STEP = 18px         # how far in each level of the tree is
const JSON_ARROW = 16px        # the room for the arrow of an object or a list
const JSON_PAD = 6px           # between the ends of a row's highlight and its text
const MOST_STRING = 2000       # characters. A longer string stops there on its row.

"An object of a JSON file: its keys and their values, in the order that the file has them"
struct JSONObject
  keys::Vector{String}
  values::Vector{Any}
end

"A number of a JSON file, as the file writes it. So 3 shows as 3, 1.50 as 1.50, and a long number loses no digits."
struct JSONNumber
  text::String
end

"""
What the JSON in `data` holds: a JSONObject, a list, a string, a JSONNumber,
true, false or nothing. It's an error if `data` isn't JSON.
"""
json_value(data::AbstractVector{UInt8}) = begin
  # Some programs start a file with a mark that says it's UTF-8. It isn't part of the JSON.
  i = length(data) >= 3 && data[1] == 0xef && data[2] == 0xbb && data[3] == 0xbf ? 4 : 1
  value, i = json_read(data, json_blank(data, i))
  json_blank(data, i) > length(data) || error("There's more after the JSON")
  value
end

"The place of the first byte at or after `i` that isn't a space or a line break"
json_blank(d, i) = begin
  while i <= length(d) && (d[i] == 0x20 || d[i] == 0x0a || d[i] == 0x0d || d[i] == 0x09)
    i += 1
  end
  i
end

"Byte `i` of `d`. It's an error if the JSON stops before it."
json_byte(d, i) = i <= length(d) ? d[i] : error("The JSON stops early")

const JSON_NUMBER = r"^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$"

"The value that starts at byte `i` of `d`, and the place of the byte after it"
json_read(d, i) = begin
  c = json_byte(d, i)
  if c == UInt8('{')
    keys, values = String[], Any[]
    i = json_blank(d, i + 1)
    json_byte(d, i) == UInt8('}') && return JSONObject(keys, values), i + 1
    while true
      key, i = json_string(d, i)
      i = json_blank(d, i)
      json_byte(d, i) == UInt8(':') || error("A key of the JSON has no value")
      value, i = json_read(d, json_blank(d, i + 1))
      push!(keys, key)
      push!(values, value)
      i = json_blank(d, i)
      c = json_byte(d, i)
      c == UInt8('}') && return JSONObject(keys, values), i + 1
      c == UInt8(',') || error("The JSON has an object that doesn't end")
      i = json_blank(d, i + 1)
    end
  elseif c == UInt8('[')
    list = Any[]
    i = json_blank(d, i + 1)
    json_byte(d, i) == UInt8(']') && return list, i + 1
    while true
      value, i = json_read(d, i)
      push!(list, value)
      i = json_blank(d, i)
      c = json_byte(d, i)
      c == UInt8(']') && return list, i + 1
      c == UInt8(',') || error("The JSON has a list that doesn't end")
      i = json_blank(d, i + 1)
    end
  elseif c == UInt8('"')
    json_string(d, i)
  else
    j = i
    while j <= length(d) && !(d[j] in (UInt8(','), UInt8('}'), UInt8(']'), 0x20, 0x0a, 0x0d, 0x09))
      j += 1
    end
    word = String(d[i:j-1])
    word == "true" ? (true, j) : word == "false" ? (false, j) : word == "null" ? (nothing, j) :
      occursin(JSON_NUMBER, word) ? (JSONNumber(word), j) : error("The JSON has $(repr(first(word, 20))) where a value should be")
  end
end

"The string that starts at byte `i` of `d`, and the place of the byte after it"
json_string(d, i) = begin
  json_byte(d, i) == UInt8('"') || error("The JSON has no string where one should be")
  i += 1
  j = i
  # Most strings have no \ in them, and are copied as they are
  while (c = json_byte(d, j)) != UInt8('"') && c != UInt8('\\')
    j += 1
  end
  d[j] == UInt8('"') && return String(d[i:j-1]), j + 1
  out = IOBuffer()
  write(out, view(d, i:j-1))
  while (c = json_byte(d, j)) != UInt8('"')
    if c == UInt8('\\')
      x = json_byte(d, j + 1)
      j += 2
      if x == UInt8('u')
        n, j = json_hex(d, j)
        # A character past U+FFFF is written as two halves
        if 0xd800 <= n < 0xdc00 && j + 1 <= length(d) && d[j] == UInt8('\\') && d[j+1] == UInt8('u')
          low, k = json_hex(d, j + 2)
          0xdc00 <= low < 0xe000 && ((n, j) = (0x10000 + ((n - 0xd800) << 10) + (low - 0xdc00), k))
        end
        # Half of one on its own is no character
        print(out, 0xd800 <= n < 0xe000 ? '�' : Char(n))
      else
        write(out, x == UInt8('n') ? UInt8('\n') : x == UInt8('t') ? UInt8('\t') : x == UInt8('r') ? UInt8('\r') :
                   x == UInt8('b') ? UInt8('\b') : x == UInt8('f') ? UInt8('\f') : x)
      end
    else
      write(out, c)
      j += 1
    end
  end
  String(take!(out)), j + 1
end

"The number that the four hexadecimal digits at byte `i` of `d` write, and the place of the byte after them"
json_hex(d, i) = begin
  i + 3 <= length(d) || error("The JSON stops early")
  parse(UInt32, String(d[i:i+3]), base=16), i + 4
end

"What each JSON file that was read holds, with when the file had last changed then. Only the last few are kept."
const JSON_READ = Dict{String,Tuple{Float64,Any}}()

"""
What the JSON file at `path` holds, or nothing if it isn't JSON or is bigger
than MOST_JSON. A file is read once, and again when it changes.
"""
json_of(path) = begin
  at = mtime(path)
  kept = get(JSON_READ, path, nothing)
  kept !== nothing && kept[1] == at && return kept[2]
  value = 0 < filesize(path) <= MOST_JSON ? (try json_value(read(path)) catch; nothing end) : nothing
  length(JSON_READ) >= 4 && empty!(JSON_READ)
  JSON_READ[path] = (at, value)
  value
end

"True when the page shows a JSON file that can show as a tree: as the tree, or at a level under it, as the file's text, its bytes in hexadecimal or its bits"
json_page(b::Buffer) = b.view in FILE_VIEWS && lowercase(splitext(b.path)[2]) in JSONS && isfile(b.path) && json_of(b.path) !== nothing

json_items(o::JSONObject) = zip(o.keys, o.values)
json_items(l::Vector{Any}) = zip(0:length(l)-1, l)
"How many keys or items `v` has. A value that's neither an object nor a list has none."
json_length(o::JSONObject) = length(o.keys)
json_length(l::Vector{Any}) = length(l)
json_length(_) = 0
json_holder(v) = v isa JSONObject || v isa Vector{Any}

"How many keys or items `v` has, in words"
json_count(o::JSONObject) = (n = length(o.keys); "$(commas(n)) key$(n == 1 ? "" : "s")")
json_count(l::Vector{Any}) = (n = length(l); "$(commas(n)) item$(n == 1 ? "" : "s")")

"Write `v` as JSON. An object and a list have each key or item on a line of its own, `depth` steps of two spaces in."
json_write(io::IO, s::AbstractString) = begin
  print(io, '"')
  for c in s
    c == '"' ? print(io, "\\\"") : c == '\\' ? print(io, "\\\\") : c == '\n' ? print(io, "\\n") :
    c == '\r' ? print(io, "\\r") : c == '\t' ? print(io, "\\t") :
    isvalid(c) && c < ' ' ? print(io, "\\u", string(UInt32(c), base=16, pad=4)) : print(io, c)
  end
  print(io, '"')
end
json_write(io::IO, n::JSONNumber) = print(io, n.text)
json_write(io::IO, b::Bool) = print(io, b)
json_write(io::IO, ::Nothing) = print(io, "null")
json_write(io::IO, v::Union{JSONObject,Vector{Any}}, depth=0) = begin
  object = v isa JSONObject
  json_length(v) == 0 && return print(io, object ? "{}" : "[]")
  print(io, object ? '{' : '[')
  for (k, (key, x)) in enumerate(json_items(v))
    print(io, k > 1 ? ",\n" : "\n", "  "^(depth + 1))
    object && (json_write(io, key); print(io, ": "))
    json_write(io, x, depth + 1)
  end
  print(io, '\n', "  "^depth, object ? '}' : ']')
end
json_write(io::IO, x, depth) = json_write(io, x)

"What ⌘C copies of `v`: a string as its text, and any other value as JSON"
json_copy(v::AbstractString) = String(v)
json_copy(v) = sprint(json_write, v)

"A row of a JSON file's tree: how many steps in it is, the key of its value or its place in its list, and its value"
struct JSONRow
  depth::Int
  key::Union{Nothing,String,Int}
  value::Any
end

"The tree of the JSON file at `path`"
@def mutable struct JSONTree <: SemanticUI
  path::String = ""
  root::Any = nothing
  open::IdDict{Any,Bool} = IdDict{Any,Bool}()   # the objects and the lists that are open
  rows::Vector{JSONRow} = JSONRow[]             # the rows that show, worked out again when one opens or closes
  chosen::Int = 0                               # the row that the arrow keys are on, or 0 for none
end

"""
Show the tree of `root`, open as far as about `most` rows go. The top object
or list is always open. Then each level opens as a whole while there's room
for all of it.
"""
plant!(t::JSONTree, root, most=60) = begin
  t.root, t.chosen = root, 0
  empty!(t.open)
  level = json_holder(root) ? Any[root] : Any[]
  count = 0
  while !isempty(level)
    n = sum(json_length, level)
    count > 0 && count + n > most && break
    foreach(v -> t.open[v] = true, level)
    count += n
    level = Any[x for v in level for (_, x) in json_items(v) if json_length(x) > 0]
  end
  t.rows = json_rows(t)
  t
end

"""
The rows that show. The first is the file's whole value, so a file that holds
a list shows that it's a list, and with that row closed the tree is that one
row. Under each object or list that's open are the rows of its keys or items.
"""
json_rows(t::JSONTree) = json_rows!(JSONRow[], t.open, 0, nothing, t.root)
json_rows!(rows, open, depth, key, value) = begin
  push!(rows, JSONRow(depth, key, value))
  if json_holder(value) && get(open, value, false)
    for (k, x) in json_items(value)
      json_rows!(rows, open, depth + 1, k, x)
    end
  end
  rows
end

"True when row `i` is an object or a list that's open"
json_opened(t::JSONTree, i) = (v = t.rows[i].value; json_holder(v) && get(t.open, v, false))

"Open row `i` if it's closed, or close it. With `all`, everything in it opens or closes with it."
json_toggle!(t::JSONTree, i; all=false) = begin
  v = t.rows[i].value
  json_length(v) > 0 || return t
  shut = json_opened(t, i)
  set!(x) = shut ? delete!(t.open, x) : (t.open[x] = true)
  all ? json_each(set!, v) : set!(v)
  t.rows = json_rows(t)
  t
end

"Call `f` on `v` and on each object and list in it that has something in it"
json_each(f, v) = begin
  json_length(v) > 0 || return
  f(v)
  for (_, x) in json_items(v)
    json_each(f, x)
  end
end

"How far apart the rows of the tree are: as far as the lines of the file's text"
json_row_h(e) = code_size(e) * 1.5 / CODE_SCALE

"The face of the tree's text: the font of code, in `colour`"
json_face(e, colour=colours.ink) = Face(codefont(), codestyle(), code_size(e), colour, false)

"Words of the tree, in `colour`. Each is in a box, so it's as wide as it is and no wider."
json_words(e, s, colour) = Box(height(grow=grow), Alignment.Center,
  Text(s, size=code_size(e), family=codefont(), subfamily=codestyle(), color=colour, wrap=WrapMode.none))

"`s` as a string of JSON, in its quotes, no longer than `room` characters. A longer one stops with an …"
json_quoted(s, room) = begin
  q = sprint(json_write, length(s) > MOST_STRING ? first(s, MOST_STRING) : s)
  length(q) <= room && length(s) <= MOST_STRING ? q : first(q, max(2, room - 2)) * "…\""
end

"What `x` shows as in a closed object or list: an object or a list in short, and a string no longer than 40 characters"
json_brief(x) = json_holder(x) ? (x isa JSONObject ? (json_length(x) == 0 ? "{}" : "{…}") : (json_length(x) == 0 ? "[]" : "[…]")) :
                x isa AbstractString ? json_quoted(x, 40) : sprint(json_write, x)

"""
What a closed object or list holds, on one line of no more than `room`
characters, as far as there's room. The end says how many more there are.
"""
json_peek(v, room) = begin
  object = v isa JSONObject
  n = json_length(v)
  parts = String[]
  used = 2
  for (key, x) in json_items(v)
    part = (object ? key * ": " : "") * json_brief(x)
    left = n - length(parts) - 1   # how many come after this one
    more = left > 0 ? length(", … $(commas(left)) more") : 0
    !isempty(parts) && used + 2 + length(part) + more > room && break
    used += (isempty(parts) ? 0 : 2) + length(part)
    push!(parts, part)
  end
  left = n - length(parts)
  inside = join(parts, ", ") * (left > 0 ? ", … $(commas(left)) more" : "")
  object ? "{" * inside * "}" : "[" * inside * "]"
end

"The text of the value of a row, and its colour, no longer than `room` characters"
json_shown(t::JSONTree, i, room) = begin
  v = t.rows[i].value
  v isa AbstractString ? (json_quoted(v, room), colours.string) :
  v isa JSONNumber ? (v.text, colours.number) :
  v isa Bool || v === nothing ? (sprint(json_write, v), colours.keyword) :
  json_length(v) == 0 ? (json_brief(v), colours.dim) :
  json_opened(t, i) ? (v isa JSONObject ? "{" * json_count(v) * "}" : "[" * json_count(v) * "]", colours.dim) :
                      (json_peek(v, room), colours.dim)
end

"The row of the tree that the mouse is over, or 0"
json_under(t::JSONTree) = begin
  ishovered(t) || return 0
  r, w = rect(t), window_of(t)
  (r === nothing || w === nothing) && return 0
  i = floor(Int, (w.mouse[2] - r.top) / json_row_h(editor(t))) + 1
  1 <= i <= length(t.rows) ? i : 0
end

"Row `i` of the tree. `over` is true while the mouse is over it, and `keys` while the tree has the keyboard."
json_row(t::JSONTree, e, i, over, keys) = begin
  row = t.rows[i]
  h = json_row_h(e)
  tint = i == t.chosen ? (keys ? colours.select : colours.active) : over ? colours.hover : clear
  key = row.key === nothing ? () :
        row.key isa Int ? (json_words(e, string(row.key), colours.faint), json_words(e, ": ", colours.faint)) :
                          (json_words(e, row.key, colours.call), json_words(e, ": ", colours.dim))
  # The code font is monospaced, so the room for the value is a number of characters
  wide = measure(json_face(e), "0")
  keyed = row.key === nothing ? 0 : length(string(row.key)) + 2
  room = max(12, floor(Int, (e.width - 2JSON_PAD - JSON_STEP * row.depth - JSON_ARROW) / wide) - keyed)
  text, colour = json_shown(t, i, room)
  arrow = json_length(row.value) > 0 ? Icon(json_opened(t, i) ? "chevron-down" : "chevron-right", size=10px, color=colours.dim) : Box()
  Row(width(grow=grow), height(h), Alignment.Center, padding(JSON_PAD, 0px), radius(4px), background(tint), clip=true,
    Box(width(JSON_STEP * row.depth)), Box(width(JSON_ARROW), height(grow=grow), Alignment.Center, arrow),
    key..., json_words(e, text, colour))
end

describe(t::JSONTree) = begin
  e = editor(t)
  h = json_row_h(e)
  n = length(t.rows)
  _, high = window_size(e)
  # Only the rows that are in the window are made, and a few more above and below
  lo = clamp(floor(Int, (e.scroll.offset - page_top(e) - LIVE_GAP) / h) - 6, 0, n)
  hi = min(n, lo + ceil(Int, high / h) + 12)
  over = json_under(t)
  w = window_of(t)
  keys = w !== nothing && w.focus === t
  Column(width(grow=grow), Alignment.Start,
    spacer(h * lo), [json_row(t, e, i, i == over, keys) for i in lo+1:hi]..., spacer(h * (n - hi)))
end

cursor(t::JSONTree) = (i = json_under(t); i > 0 && json_length(t.rows[i].value) > 0 ? :hand : :arrow)

# A click chooses a row and gives the tree the keyboard. On an object or a list it opens it or closes it,
# and with ⌥ it opens or closes everything in it too.
onkey(t::JSONTree, ev::KeyPress{Keys.mouse_left}) = begin
  i = json_under(t)
  focus(t)
  i == 0 && return handled
  t.chosen = i
  json_toggle!(t, i, all=only_held(ev, Keys.opt))
  handled
end

"Choose row `i`, and scroll the page so that it's in the window"
json_choose!(t::JSONTree, i) = begin
  isempty(t.rows) && return handled
  t.chosen = clamp(i, 1, length(t.rows))
  e = editor(t)
  r = rect(t)
  r === nothing && return handled
  h = json_row_h(e)
  top = r.top + h * (t.chosen - 1)   # where the row is in the window
  _, high = window_size(e)
  top < TOPBAR_H + h ? scroll_page!(e, top - TOPBAR_H - h) : top + 2h > high ? scroll_page!(e, top + 2h - high) : nothing
  handled
end

onkey(t::JSONTree, ev::KeyPress{Keys.down}) = unmodified(ev) ? json_choose!(t, t.chosen + 1) : nothing
onkey(t::JSONTree, ev::KeyPress{Keys.up}) = unmodified(ev) ? json_choose!(t, max(1, t.chosen - 1)) : nothing
# → opens a closed row, and goes into one that's open
onkey(t::JSONTree, ev::KeyPress{Keys.right}) = begin
  unmodified(ev) || return nothing
  i = t.chosen
  i == 0 && return json_choose!(t, 1)
  json_length(t.rows[i].value) == 0 && return handled
  json_opened(t, i) ? json_choose!(t, i + 1) : (json_toggle!(t, i); handled)
end
# ← closes an open row, and goes out of one that's closed, to the row that holds it
onkey(t::JSONTree, ev::KeyPress{Keys.left}) = begin
  unmodified(ev) || return nothing
  i = t.chosen
  i == 0 && return json_choose!(t, 1)
  json_opened(t, i) && return (json_toggle!(t, i); handled)
  d = t.rows[i].depth
  d == 0 ? handled : json_choose!(t, findprev(r -> r.depth < d, t.rows, i))
end
onkey(t::JSONTree, ev::KeyPress{Keys.enter}) = unmodified(ev) ? (t.chosen > 0 && json_toggle!(t, t.chosen); handled) : nothing
onkey(t::JSONTree, ev::KeyPress{Keys.c}) = begin
  only_held(ev, Keys.cmd) || return nothing
  t.chosen > 0 && clipboard(json_copy(t.rows[t.chosen].value))
  handled
end

"Show the file of the page at the level `view`: :bits, :hex, :text, or :file for the tree of a JSON file and the table of a CSV file"
file_level!(e, view::Symbol) = begin
  b = e.buf
  # A page of HTML from a web server has its HTML already, at each of its levels
  served_html(b) && return (b.view = view; b.caret = b.anchor = (1, 0); b.saved = b.version += 1; e.scroll.offset = 0px; focus(e); e)
  at = place_in_file(e)
  shown = look(b.path, view)
  b.lines, b.about, b.view = shown.lines, shown.about, shown.view
  b.caret = b.anchor = (1, 0)
  b.saved = b.version += 1
  e.scroll.offset = 0px
  # The window stays at the same place in the file, between its bits, its bytes and its text
  line = line_of_byte(b, at)
  line > 1 && (e.nodes[:hold] = (line, 0px))
  focus(e)
  e
end

"""
How far into its file the line at the top of the window starts, in bytes, while
the page shows a file's bits, its bytes in hexadecimal or its text. It's 0 for
anything else. A line of text counts as its characters and its line break, so
in a file with tabs or with very long lines it's only near the place.
"""
place_in_file(e) = begin
  b = e.buf
  (b.view in (:bits, :hex, :text) && !isempty(e.layout) && e.scroll.offset > 0px) || return 0
  k = something(findfirst(it -> it.top + it.tall > e.scroll.offset, e.layout), 1)
  line = e.layout[k].first
  b.view == :bits ? BITS_ROW * (line - 1) : b.view == :hex ? 16(line - 1) : sum(l -> ncodeunits(l) + 1, @view(b.lines[1:line-1]), init=0)
end

"The line of the page that has byte `at` of its file, counted from 0, for a page that shows a file's bits, its bytes in hexadecimal or its text. It's 1 for any other page."
line_of_byte(b::Buffer, at::Int) = begin
  n = length(b.lines)
  b.view == :bits && return clamp(at ÷ BITS_ROW + 1, 1, n)
  b.view == :hex && return clamp(at ÷ 16 + 1, 1, n)
  b.view == :text || return 1
  upto = 0
  for (i, l) in enumerate(b.lines)
    upto += ncodeunits(l) + 1
    upto > at && return i
  end
  n
end

# --- what Julia code ran, down a level -----------------------------------------------------------
#
# Julia code has four levels, and they're levels of what the code comes to
# when it runs. At the highest, the box after a piece of code shows the value
# that the code came to. "code that runs where it is" says how. A level
# down, the box shows the code as Julia infers it: each step, with the type
# that Julia worked out for it. Under that it shows the LLVM code that Julia
# makes of those steps, and under that the assembly that LLVM compiles them
# to, with the machine code of each instruction beside it.
#
# The levels belong to a block of code, not to the window. Each `julia` code
# block of a page has a level of its own, and a file of Julia code, which is
# one block, has one. While the caret is in a block, the slider in the top bar
# is that block's: the top bar asks the part of the page that the caret is in
# for its levels, and the block answers. See "the slider of the levels". The
# slider goes to each level, and ⌘E goes between the value and the inferred
# code. With the caret in the page's text, the slider is the page's again.
#
# The code shows as it's written at every level, and you type in it as
# always. The boxes of the block change with its level, so you can take one
# piece of code from its value down to its machine code. Code that runs while
# its block is down a level has its box open.
#
# What a box shows is the code of what ran. For the definition of a function,
# that's the function's code for the types that it has been called with since,
# or for the types that it's written for when it hasn't been called. When the
# function has more than one method or set of types, a line at the top of the
# open box says so, and a click on it shows the next. For any other code, it's
# that code itself, compiled as a function that takes nothing. Code that can't
# be in a function has no lower level, like `using` or the definition of a
# struct. Neither has code that failed. Their boxes show what they show at the
# highest level.
#
# A closed box shows a little: the type that the code gives at the level of
# inferred code, and how many bytes of machine code there are at the level of
# assembly. Only the lines of an open box that are in sight are made.

const CODE_LEVELS = ("the assembly of what you run", "the LLVM code of what you run", "the inferred code of what you run", "the value of what you run")
const MOST_LOWERED = 4000    # lines. The inferred code, the LLVM code or the assembly of longer code stops there.
const MOST_FORMS = 12        # the most methods and sets of types that a function offers

"True when the page shows a file of Julia code that you change. The whole file is one block of Julia code."
julia_file(b::Buffer) = b.view == :code && lowercase(splitext(b.path)[2]) == ".jl"

"The place of the `julia` code block that opens on line `s` among the `julia` code blocks of `b`"
julia_place(b::Buffer, s::Int) = (ks = kinds(b); count(i -> ks[i].kind == Kind.fence && ks[i].level == 0 && lowercase(ks[i].lang) in JULIA, 1:s))

"""
The Julia code that line `i` is in, as the part of the page that has levels: a
`julia` code block of a page, or the whole of a file of Julia code. It's
nothing when the line isn't in Julia code. With `make` false, it's also
nothing for code that was never asked for, which is at its highest level.
"""
julia_part(e, i::Int; make=true) = begin
  b = e.buf
  n = 0   # a file of Julia code is one block
  if !julia_file(b)
    (b.view == :markdown && 1 <= i <= length(b.lines)) || return nothing
    found = julia_code(b, i)
    found === nothing && return nothing
    n = julia_place(b, found[1] - 1)
  end
  key = (:julia, b.path, n)
  make || return get(e.nodes, key, nothing)
  get!(e.nodes, key) do
    c = JuliaCode(n=n)
    # It's a part of the document, so the document answers what it doesn't
    setfield!(c, :parent, node!(Document, e, :document))
    c
  end
end

"How many levels down the Julia code that line `i` is in shows what it comes to: 0 for the value, 1 for inferred code, 2 for LLVM code and 3 for assembly"
code_depth(e, i::Int) = (c = julia_part(e, i, make=false); c === nothing ? 0 : c.depth)

levels(::JuliaCode) = CODE_LEVELS
level(c::JuliaCode) = length(CODE_LEVELS) - c.depth
level!(c::JuliaCode, i::Int) = (c.depth = clamp(length(CODE_LEVELS) - i, 0, length(CODE_LEVELS) - 1); c)

"True when the code `lhs` is what a function's definition starts with, like `f(x)` or `f(x::T) where T`"
calls(lhs) = Meta.isexpr(lhs, :call) || (Meta.isexpr(lhs, (:where, :(::))) && !isempty(lhs.args) && calls(lhs.args[1]))

"True when the expression `ex` defines a function. Its documentation can be above it, and a macro like `@inline` can be before it."
is_definition(ex) = Meta.isexpr(ex, :function, 2) || (Meta.isexpr(ex, :(=), 2) && calls(ex.args[1])) ||
                    (Meta.isexpr(ex, :macrocall) && length(ex.args) > 2 && is_definition(last(ex.args)))

"The definition of a function that ran: the function, and the types that each method it got then is written for"
struct Defined
  value::Any
  sigs::Vector{Any}
end

"Code that ran and defined no function. The levels under its value show it compiled as a function that takes nothing."
mutable struct Thunk
  code::String
  made::Any   # that function, false when the code can't be in a function, or nothing until a lower level asks for it
end

"A line of code that a box shows a level down: its pieces, each with the name of its colour"
const CodeRow = Vector{Tuple{String,Symbol}}

"What a box shows while its code is down a level: its top line, the lines under it, how wide the widest is, and how many methods and sets of types its function offers"
struct Lowered
  key::Any
  title::String
  rows::Vector{CodeRow}
  cols::Int
  forms::Int
end

"The code without the comments and the empty lines above it"
bare_code(code::AbstractString) = begin
  lines = split(code, '\n')
  k = something(findfirst(l -> !isempty(strip(l)) && !startswith(lstrip(l), '#'), lines), 1)
  String(rstrip(join(lines[k:end], "\n")))
end

"""
What the levels under the value show the code of, for `code` that ran and
came to `value`. A definition gives its function, with the methods that the
function got after `world`. Other code gives itself.
"""
source_of(code::AbstractString, value, world) = begin
  ex = try Meta.parse(bare_code(code), raise=false) catch; nothing end
  (is_definition(ex) && value isa Union{Function,Type}) || return Thunk(String(code), nothing)
  Defined(value, Any[x.sig for x in Base.invokelatest(methods, value) if x.primary_world > world])
end

"The function that the code of `t` makes when it's the body of a function that takes nothing, in the module `m`, or false when it can't be one"
thunk!(t::Thunk, m::Module) = begin
  t.made === nothing || return t.made
  t.made = try
    Core.eval(m, Expr(:->, Expr(:tuple), Expr(:block, Meta.parseall(t.code).args...)))
  catch
    false
  end
end

"""
The types that the function of `d` shows its code for: for each of its
methods, each set of types that it has been called with, or the types that it's
written for when it hasn't been called. The method with the most arguments is first.
"""
forms(d::Defined) = begin
  out = Any[]
  now = try collect(Base.invokelatest(methods, d.value)) catch; return out end
  for sig in sort(d.sigs, by=sig -> -length(Base.unwrap_unionall(sig).parameters))
    k = findfirst(x -> x.sig == sig, now)
    called = k === nothing ? Any[] : Any[mi.specTypes for mi in Base.specializations(now[k]) if Base.isdispatchtuple(mi.specTypes)]
    isempty(called) ? push!(out, sig) : append!(out, called)
  end
  length(out) > MOST_FORMS ? out[1:MOST_FORMS] : out
end
forms(t::Thunk, m::Module) = (f = thunk!(t, m); f === false ? Any[] : Any[Tuple{typeof(f)}])
forms(d::Defined, ::Module) = forms(d)

"A type as Julia writes it, with no module's name in front of a type of the module `m`"
type_name(m::Module, T) = replace(sprint(show, T, context=:module => m), string(m) * "." => "")

"The call that the types `tt` are of, like `area(w::Int64, h::Int64)`, with the names that the method of `d` gives its arguments. Code that defined no function has none."
call_words(::Thunk, m::Module, tt) = ""
call_words(d::Defined, m::Module, tt) = begin
  types = Base.unwrap_unionall(tt).parameters[2:end]
  now = try collect(Base.invokelatest(methods, d.value)) catch; Method[] end
  k = findfirst(x -> tt <: x.sig, now)
  names = k === nothing ? String[] : String[string(n) for n in Base.method_argnames(now[k])[2:end]]
  args = [(length(names) == length(types) ? names[i] : "") * "::" * type_name(m, T) for (i, T) in enumerate(types)]
  string(d.value isa Function ? nameof(d.value) : type_name(m, d.value)) * "(" * join(args, ", ") * ")"
end

"`text` as the pieces of a line of Julia code, each with the name of its colour. Pieces of one colour that touch are one piece."
tinted(text::AbstractString) = begin
  out = Tuple{String,Symbol}[]
  for t in tokens(text, "julia")
    # Julia writes the place that a step jumps to as #4, which isn't a comment
    kind = t.kind in (:plain, :comment) ? :ink : t.kind
    !isempty(out) && last(out)[2] == kind ? (out[end] = (last(out)[1] * t.text, kind)) : push!(out, (String(t.text), kind))
  end
  out
end

"""
The code of the types `tt` as Julia infers it, with the type that it gives. The
local variables come first, each with its type, then each step.
"""
inferred(m::Module, tt) = begin
  found = Base.code_typed_by_type(tt; optimize=false, debuginfo=:none)
  isempty(found) && error("Julia has no method for these types.")
  ci, gives = first(found)
  inside = string(m) * "."
  body = split(replace(sprint(show, ci, context=:module => m), inside => ""), '\n')
  # Julia writes the steps between a line that says CodeInfo( and a line with a )
  length(body) > 2 && startswith(first(body), "CodeInfo(") && (body = body[2:end-1])
  n = length(Base.unwrap_unionall(tt).parameters)
  locals = ci.slottypes isa Vector ?
    ["  " * string(name) * "::" * type_name(m, T) for (name, T) in zip(ci.slotnames[n+1:end], ci.slottypes[n+1:end])
     if !startswith(string(name), '#') && !isempty(string(name))] : String[]
  rows = CodeRow[tinted(l) for l in body]
  # The two headings are words of Ladder's, so they're dim
  isempty(locals) || (rows = [[[("Locals", :dim)]]; [tinted(l) for l in locals]; [[("Body", :dim)]]; rows])
  (rows, gives)
end

"The function that the types `tt` call, and the types of its arguments, as `code_llvm` and `code_native` take them"
callee(tt) = begin
  inner = Base.unwrap_unionall(tt)
  F = inner.parameters[1]
  f = isdefined(F, :instance) ? F.instance : F isa DataType && F.name === Type.body.name ? F.parameters[1] :
      error("Ladder can't compile a thing that's called like a function. It has no name to compile.")
  (f, Base.rewrap_unionall(Tuple{inner.parameters[2:end]...}, tt))
end

const LLVM_WORDS = r"%[\w.\"#-]+|@\"[^\"]*\"|@[\w.]+|\b(?:define|declare|ret|br|call|load|store|alloca|getelementptr|icmp|fcmp|phi|select|switch|unreachable|invoke|bitcast|trunc|zext|sext|add|sub|mul|sdiv|udiv|srem|urem|fadd|fsub|fmul|fdiv|and|or|xor|shl|lshr|ashr)\b|(?<![\w.])-?\d+(?:\.\d+)?(?![\w.])"

"A line of LLVM code as pieces, each with the name of its colour: the names of values, the names of functions, the instructions and the numbers"
llvm_row(line::AbstractString) = begin
  startswith(lstrip(line), ';') && return [(String(line), :comment)]
  out = Tuple{String,Symbol}[]
  at = 1
  for found in eachmatch(LLVM_WORDS, line)
    found.offset > at && push!(out, (String(line[at:prevind(line, found.offset)]), :ink))
    word = found.match
    push!(out, (String(word), startswith(word, '%') ? :call : startswith(word, '@') ? :type : isletter(first(word)) ? :keyword : :number))
    at = found.offset + ncodeunits(word)
  end
  at <= ncodeunits(line) && push!(out, (String(line[at:end]), :ink))
  out
end

"The LLVM code that Julia makes for the types `tt`"
llvm(tt) = begin
  f, types = callee(tt)
  text = sprint(io -> Base.invokelatest(code_llvm, io, f, types; debuginfo=:none, dump_module=false, raw=false))
  CodeRow[llvm_row(l) for l in split(rstrip(text), '\n')]
end

"""
The assembly that Julia compiles the types `tt` to, and how many bytes of
machine code it is. Each instruction has its place in that machine code, then
its machine code in hexadecimal, then the instruction as assembly.
"""
assembly(tt) = begin
  f, types = callee(tt)
  text = sprint(io -> Base.invokelatest(code_native, io, f, types; debuginfo=:none, dump_module=false, binary=true))
  rows = CodeRow[]
  code = nothing   # the place and the machine code of the instruction on the next line
  bytes = 0
  wide = maximum(l -> (found = match(r"^; [0-9a-f]+: ([0-9a-f ]+)$", l); found === nothing ? 0 : length(found[1])), split(text, '\n'), init=8)
  for line in split(text, '\n')
    found = match(r"^; ([0-9a-f]+): ([0-9a-f ]+)$", line)
    if found !== nothing
      code = (String(found[1]), String(found[2]))
    elseif startswith(line, "; code origin")
      size = match(r"code size: (\d+)", line)
      size === nothing || (bytes = parse(Int, size[1]))
    elseif startswith(line, ';')
      push!(rows, [(String(strip(line[2:end])), :comment)])
    elseif startswith(line, '\t')
      parts = split(strip(line), '\t', limit=2)
      place, hex = something(code, ("", ""))
      push!(rows, [(rpad(place, 6), :faint), (rpad(hex, wide + 2), :dim), (rpad(parts[1], 8), :keyword),
                   (length(parts) > 1 ? replace(String(parts[2]), '\t' => ' ') : "", :ink)])
      code = nothing
    elseif !isempty(strip(line))
      push!(rows, [(String(line), :dim)])   # the name of a place that an instruction jumps to
    end
  end
  (rows, bytes)
end

"""
What the box of `o` shows while the Julia code that it's in is down a level:
the code of what ran, at the level of that block or file. It's nothing at the
level of the value, and for code that has no lower level. The lines of a level
are worked out once for each set of types.
"""
code_view(e, o) = begin
  (o.failed || o.source === nothing) && return nothing
  depth = code_depth(e, o.first)
  depth > 0 || return nothing
  m = workspace(e)
  found = forms(o.source, m)
  isempty(found) && return nothing
  o.form = clamp(o.form, 1, length(found))
  tt = found[o.form]
  key = (depth, tt)
  title, rows = get!(o.views, key) do
    name = call_words(o.source, m, tt)
    try
      if depth == 1
        rows, gives = inferred(m, tt)
        (name * "::" * type_name(m, gives), rows)
      elseif depth == 2
        (isempty(name) ? "LLVM code" : name, llvm(tt))
      else
        rows, bytes = assembly(tt)
        ((isempty(name) ? "" : name * "  ") * "$(commas(bytes)) bytes", rows)
      end
    catch err
      what = ("infer", "make LLVM code of", "compile")[depth]
      (isempty(name) ? "No code" : name, CodeRow[[("Julia couldn't $what this: " * Base.invokelatest(sprint, showerror, err), :dim)]])
    end
  end
  more = length(rows) - MOST_LOWERED
  more > 0 && (rows = [rows[1:MOST_LOWERED]; [[("… and $(commas(more)) more lines", :dim)]]])
  Lowered(key, title, rows, maximum(row -> sum(piece -> length(piece[1]), row, init=0), rows, init=0), length(found))
end

"The line at the top of the open box of a function that has more than one method or set of types. A click on it shows the next."
@def mutable struct FormPick <: SemanticUI
  of::Any = nothing   # the OutcomeBody
end

describe(p::FormPick) = begin
  o = p.of.of
  low = o.low
  words = low === nothing ? "" : "$(o.form) of $(low.forms)  ·  click for the next types"
  Row(width(grow=grow), height(o.size * 1.7), Alignment.Center, radius(4px), background(ishovered(p) ? colours.hover : clear), name="Form pick",
    Box(label(words, o.size * 0.92, color=colours.dim)), Box(width(grow=grow)))
end

cursor(::FormPick) = :hand
onmouse(::FormPick, ::MouseMove) = handled
onkey(p::FormPick, ::KeyPress{Keys.mouse_left}) = (o = p.of.of; o.low === nothing || (o.form = mod1(o.form + 1, o.low.forms)); handled)

"""
The lines of code that the open box `d` shows while its code is down a level.
A list that's taller than the room under the box shows that much of itself,
and the wheel moves through the rest. Only the lines in sight are made.
"""
lowered_view(d) = begin
  o = d.of
  low = o.low::Lowered
  face = outcome_face(o.size)
  h = o.size * 1.45
  n = length(low.rows)
  # Other lines start at their top
  d.showed == low.key || (d.showed = low.key; d.scroll.offset = 0px)
  pick = low.forms > 1 ? (d.pick === nothing ? (d.pick = own!(d, FormPick(of=d))) : d.pick,) : ()
  tall = min(h * n, d.tall)
  lo = clamp(floor(Int, d.scroll.offset / h) - 2, 0, n)
  hi = min(n, lo + ceil(Int, tall / h) + 4)
  row(i) = Row(height(h), Alignment.Center,
    [Box(Text(text, size=o.size, family=face.family, subfamily=face.style, color=getfield(colours, kind), wrap=WrapMode.none)) for (text, kind) in low.rows[i]]...)
  inside = Column(width(grow=grow), Alignment.Start, spacer(h * lo), [row(i) for i in lo+1:hi]..., spacer(h * (n - hi)))
  Column(width(grow=grow), Alignment.Start, pick..., Box(width(grow=grow), height(tall), Alignment.Start, clip=true, reuse!(d.scroll, inside)))
end

# A whole file of code or of text starts at the left of the page, not in the
# middle of it as a page's text is, and has the number of each line beside it.
# The number of the line that the caret is in is a little darker. The list of
# the files in a zip has no numbers.

const NUMBER_GAP = 14px   # between the numbers of the lines and the text

"True when the page shows a whole file of code or of text, which can have the number of each line beside it"
numbered(b::Buffer) = b.view == :code || (b.view == :text && !(lowercase(splitext(b.path)[2]) in ZIPS))

"The font of the numbers of the lines: a little smaller and fainter than the code"
number_face(e) = (code = face(e, Line(Kind.code, 0, 0, "")); Face(code, size=code.size * 0.9, color=colours.faint))

"True when the page shows the number of each line beside it: a file of code or of text, unless the settings page hid them"
numbers(e) = numbered(e.buf) && e.numbers

"How much room the numbers of the page's lines take beside the text, with the gap between them. A page with no numbers takes none."
gutter(e) = numbers(e) ? measure(number_face(e), "0") * max(2, ndigits(length(e.buf.lines))) + NUMBER_GAP : 0px

const capitals = Dict{Tuple{String,String,Float32},px}()

"How tall a capital letter of `face` is"
capital(face::Face) = get!(capitals, (face.family, face.style, Float32(num(face.size)))) do
  metrics = Ref{Skia.sk_font_metrics_t}()
  Skia.sk_font_get_metrics(skia_font(face.family, face.size, face.style).raw, metrics)
  px(metrics[].capHeight)
end

"Write the number of each line on screen beside the line. The page's text starts at `left`, and its first line is at `top`."
draw_numbers(ctx, e, left, top) = begin
  b = e.buf
  numbers(e) || return
  f = number_face(e)
  # A number stands on the line that its line of code stands on
  rise = capital(face(e, Line(Kind.code, 0, 0, "")))
  for it in e.layout[e.shown]
    flow = it.content
    flow isa Flow || continue
    words = string(it.first)
    here = !caretless(b) && !readonly(b) && it.first == b.caret[1]
    x = left - NUMBER_GAP - measure(f, words)
    y = top + it.top + line_top(flow, 1) + (flow.lines[1].high + rise) / 2
    write_ink(ctx, words, num(x), num(y), here ? Face(f, color=colours.dim) : f)
  end
end

# A line of a file of code or of text that's too long for the window goes on
# under itself, at the window's right edge. The part under it starts one step of
# indentation further in than the line does, so it doesn't look like a line of
# its own. The settings page can turn that off. Then a long line goes on past
# the edge of the window, and the page scrolls sideways to show the rest of it,
# under the numbers of the lines. The caret stays in sight as it moves.
#
# The settings page has more for code. A file of code can show the numbers of
# its lines or not, shade the line that the caret is on, and have a faint line
# down it after a number of characters, to show where a line gets too long. In
# all code, in a file or in a page, it sets how big the code is and how many
# spaces one step of indentation is.

const INDENTS = (2, 4)                  # the steps of indentation that the settings page offers
const GUIDES = (0, 80, 92, 100, 120)    # the places for the line down a file of code. 0 is no line.
const CODE_SCALES = (0.4, 2.5)          # the least and most that code can be, beside the page's text
const SIDE_ROOM = 40px   # how near the caret gets to the left or right of the window before the page scrolls sideways

"True when the long lines of the page go on under themselves. Only a file of code or of text can have them go on past the window, and the lines of a file's bytes always do."
wraps(e) = !bytes_page(e.buf) && (e.wrap || !numbered(e.buf))

"How far the page is scrolled to the right"
sideways(e) = wraps(e) ? 0px : e.buf.across

"How far the page can scroll to the right: as far as the longest line goes past the right of the window"
sideways_room(e) = max(0px, e.reach + SIDE_ROOM - e.width)

"Scroll the page `by` to the right, as far as it goes"
scroll_sideways!(e, by) = (e.buf.across = clamp(e.buf.across + by, 0px, sideways_room(e)); e)

"""
Two fingers that move sideways on the trackpad, or the wheel with ⇧ held,
scroll the page sideways. Their move up or down still scrolls the page up or down.
"""
swipe!(e, ev::MouseScroll) = begin
  (wraps(e) || ev.delta[1] == 0px) && return nothing
  scroll_sideways!(e, -30ev.delta[1])
  ev.delta[2] == 0px ? handled : nothing
end
onscroll(d::Document, ev::MouseScroll) = swipe!(editor(d), ev)
onscroll(p::Page, ev::MouseScroll) = swipe!(editor(p), ev)

"How far the lines of `f` go, from the left of the text"
extent(f::Flow) = maximum(vl -> isempty(vl.segs) ? vl.x : last(vl.segs).x + last(vl.segs).w, f.lines)

"Turn on or off the wrapping of a line of a file of code that's too long for the window"
wrap!(e, on::Bool) = (e.wrap = on; save_settings!(e); rerun!(e, :wrap); restyle!(e))

"Show or hide the numbers of the lines of a file of code"
numbers!(e, on::Bool) = (e.numbers = on; save_settings!(e); rerun!(e, :numbers); restyle!(e))

"Shade the line of a file of code that the caret is on, or don't"
shade!(e, on::Bool) = (e.shade = on; save_settings!(e); rerun!(e, :shade); e)

"Make one step of indentation in code `n` spaces: 2 or 4"
indent_width!(e, n::Int) = begin
  n in INDENTS || error("A step of indentation is 2 or 4 spaces. $n isn't one of them.")
  e.indent = n
  save_settings!(e)
  rerun!(e, :indent)
  restyle!(e)
end

"Put the faint line down a file of code after `n` characters. 0 takes the line away."
guide!(e, n::Int) = begin
  n in GUIDES || error("The line goes after 80, 92, 100 or 120 characters, or 0 for none. $n isn't one of them.")
  e.guide = n
  save_settings!(e)
  rerun!(e, :guide)
  e
end

"Draw code in the font called `family`, in the weight that the settings choose or the nearest one it has"
code_font!(e, family::String) = begin
  installed_weight(family, 400) > 0 || error("This Mac has no font called $family.")
  e.code_font = family
  use_code_font!(e)
  save_settings!(e)
  rerun!(e, :code_font)
  restyle!(e)
end

"Draw code in the weight called `w`, like \"Light\", or in the weight `w`, like 300"
code_weight!(e, w::Union{Integer,AbstractString}) = begin
  e.code_weight = w isa Integer ? text_weight(w) : weight_called(e.code_font, w)
  use_code_font!(e)
  save_settings!(e)
  rerun!(e, :code_weight)
  restyle!(e)
end

"How big code is: a part of the size of the page's text, so it grows and shrinks with it"
code_size(e) = body(e).size * e.code_scale

"Make code `size` pixels tall, for a live block. The text of the page stays the size it is."
code_size!(e, size) = (e.code_scale = clamp(size / num(body(e).size), CODE_SCALES...); rewrap!(e))

"The spaces of one step of indentation, in a block of the kind `block`. In code the settings page chooses how many."
indentation(e, block) = block === CodeBlock ? " "^e.indent : STEP

"Lay out `text`, line `i` of a file that shows as text. It has no background of its own and starts at the edge of the page."
file_line(e, text, line::Line, i::Int) = begin
  ps = spare(pieces(e, text, line, false, i))
  # Lines of bigger code are further apart
  lh, size = code_size(e) * 1.5 / CODE_SCALE, face(e, line).size
  wraps(e) || return wrap(ps, px(Inf); lh, size)
  # The spaces at the start of the line, and one step more, though half the page is always left for the text
  indent = match(r"^[ \t]*", text).match
  hang = min(measure(face(e, line), indent * " "^e.indent), e.width / 2)
  wrap(ps, e.width; lh, size, hang)
end

# --- the lines of a long file ---------------------------------------------------------
#
# A file of code can be tens of thousands of lines long. To lay out a line takes
# time: its code is cut into parts, each part is measured, and the parts are
# wrapped. So the lines of a file are laid out in a way that costs less, and the
# layout is kept from one frame to the next.
#
#   - A line is laid out as runs of text in one colour, and nothing is
#     measured. In a font whose characters are all one width, a run is as wide
#     as its characters are many, so where a long line breaks can be counted.
#     The line gets its colours when it's drawn, and only the lines on screen
#     are drawn: see `in_colour`.
#   - A line with a character that may be of another width is laid out in full,
#     and so is a line with a word that's too long for the window.
#   - After a change, only the lines that changed are laid out again.

"The layout of a file's lines, kept from one frame to the next, with the lines that it's of"
mutable struct Laid
  version::Int
  lines::Vector{String}
  items::Vector{Item}
end

const pitches = Dict{Tuple{String,String,Float32},Union{Nothing,px}}()

"""
How wide one character of `face` is, when each character that a keyboard types
is that wide, in the face and in the slanted one that comments are in. Code's
own fonts are like that. Nothing for a font whose characters differ.
"""
pitch(face::Face) = get!(pitches, (face.family, face.style, Float32(num(face.size)))) do
  wide = measure(face, "M")
  near(w, n=1) = abs(num(w) - n * num(wide)) < 0.01
  slant = Face(face, style=codeslant())
  # Two characters side by side can be nearer than they are apart, in a font that isn't code's
  even = all(c -> near(measure(face, string(c))) && near(measure(slant, string(c))), ' ':'~') &&
         near(measure(face, "AVAVfifiWoTo"), 12) && near(measure(face, "    ->==!="), 10)
  even && num(wide) > 0 ? wide : nothing
end

"True when each character of `text` is one that a keyboard types: a letter, a digit, a mark or a space"
typeable(text::String) = all(c -> 0x20 <= c <= 0x7e, codeunits(text))

"""
Where the line `text` breaks into lines on screen, as `wrap` breaks the line
that `file_line` gives it: the first and the last column of each. Each
character is `wide` across, the lines are `limit` across, and each after the
first starts at `hang`. Nothing when that can't be told without measuring:
a word that's too long for a line breaks between two parts of its code, and
a word that ends within half a pixel of the edge could go either way.
"""
quick_rows(text::String, wide::Float64, limit::Float64, hang::Float64) = begin
  chars = codeunits(text)
  n = length(chars)
  rows = Tuple{Int,Int}[]
  x = start = 0.0
  from = at = 0
  # The spaces that start the line go on its first line, however many they are
  while at < n && chars[at+1] == 0x20; at += 1 end
  x += at * wide
  while at < n
    word = at
    while word < n && chars[word+1] != 0x20; word += 1 end
    next = word
    while next < n && chars[next+1] == 0x20; next += 1 end
    w = (word - at) * wide
    w <= limit - hang - 0.5 || return nothing
    over = x + w - limit
    abs(over) < 0.5 && return nothing
    if over > 0 && x > start
      push!(rows, (from, at))
      from, x, start = at, hang, hang
    end
    # The spaces after a word may hang past the edge
    x += (next - at) * wide
    at = next
  end
  push!(rows, (from, n))
end

"""
Line `i` of a file, laid out for the layout of the whole file. It's what
`file_line` gives, but for the colours of its code, and nothing is measured:
`wide` is how wide one character of `face` is, so a run of text is as wide as
its characters are many. A line with a character that a keyboard doesn't type,
or in a font whose characters differ, when `wide` is nothing, is laid out by
`file_line`. So is a line that `quick_rows` can't break.
"""
quick_line(e, text::String, line::Line, i::Int, face::Face, lh::px, wide) = begin
  n = ncodeunits(text)
  (wide !== nothing && typeable(text)) || return file_line(e, text, line, i)
  run(from, to, x) = Seg[Seg(from == 0 && to == n ? text : text[from+1:to], from, to - from, face, false, "", x, (to - from) * wide, nothing)]
  flow(lines) = Flow(lines, lh, face.size, 0px, 0px, Kind.paragraph, false)
  # A line that's sure to fit, or that goes on past the edge of the window, is one line on screen
  (!wraps(e) || n * wide <= e.width - 1px) && return flow([VLine(n == 0 ? Seg[] : run(0, n, 0px), 0px, 0, n, 0px, lh)])
  # A line that goes on under itself starts there one step of indentation further in, as `file_line` has it
  lead = something(findfirst(!=(0x20), codeunits(text)), n + 1) - 1
  hang = min((lead + e.indent) * wide, e.width / 2)
  rows = quick_rows(text, num(wide), num(e.width), num(hang))
  rows === nothing && return file_line(e, text, line, i)
  flow([VLine(run(from, to, k == 1 ? 0px : hang), k == 1 ? 0px : hang, from, to, lh * (k - 1), lh) for (k, (from, to)) in enumerate(rows)])
end

"True when `a` and `b` are the same text. Two lines of a file that didn't change are one string, which is quick to see."
same_text(a::String, b::String) = pointer(a) == pointer(b) || a == b

"How many lines at the start of `new` are as they are in `old`, and how many at the end of the lines that are left"
unchanged(new::Vector{String}, old::Vector{String}) = begin
  n, m = length(new), length(old)
  head = 0
  while head < min(n, m) && same_text(new[head+1], old[head+1])
    head += 1
  end
  tail = 0
  while tail < min(n, m) - head && same_text(new[n-tail], old[m-tail])
    tail += 1
  end
  (head, tail)
end

"""
The lines of the file that `b` shows, laid out. Each is a line of code. The
whole page is code, so the lines have no background of their own and start at
the edge of the page. See "the lines of a long file".
"""
file_lines(e, b::Buffer) = begin
  key = (:lines, b.path, b.view)
  kept = get(e.flows, key, nothing)
  kept isa Laid && kept.version == b.version && return kept.items
  # What was laid out before, and the lines that it was of. Julia knows the types of these two, so the loops below are quick.
  was, before = kept isa Laid ? (kept.items, kept.lines) : (Item[], String[])
  ks, lines = kinds(b), b.lines
  n = length(lines)
  items = Vector{Item}(undef, n)
  n == 0 && return items
  # Every line of a file is a line of code in the file's language, so one face and one height do for all
  f = face(e, ks[1])
  lh = code_size(e) * 1.5 / CODE_SCALE
  wide = pitch(f)
  # The lines before the first that changed, and the lines after the last, keep their layout
  m = length(before)
  head, tail = unchanged(lines, before)
  # Except a line that `file_line` laid out in its colours, when a docstring above it opened or closed. Its text is the same, so it's as tall.
  at = string_opens(b)::Vector{Char}
  laid = get(e.flows, (:opens, key), nothing)
  laid_at::Vector{Char} = kept isa Laid && laid isa Opens ? laid.at : Char[]
  recoloured(it, i) = all(vl -> length(vl.segs) == 1, it.content.lines) ? it : Item(i, i, it.top, it.tall, quick_line(e, lines[i], ks[i], i, f, lh, wide))
  top = 0px
  copyto!(items, 1, was, 1, head)
  h = min(head, length(laid_at))
  if !same_chars(at, 1, laid_at, 1, h)
    for i in 1:h
      @inbounds laid_at[i] == at[i] || (items[i] = recoloured(items[i], i))
    end
  end
  head > 0 && (top = items[head].top + items[head].tall)
  for i in head+1:n-tail
    flow = quick_line(e, lines[i], ks[i], i, f, lh, wide)
    high = tall(flow)
    items[i] = Item(i, i, top, high, flow)
    top += high
  end
  # A long file has many lines after the change, and most often a docstring opened or closed above none of them
  kept_same = m == length(laid_at) && same_chars(at, n - tail + 1, laid_at, m - tail + 1, tail)
  for i in n-tail+1:n
    j = i - n + m
    it = was[j]
    kept_same || j > length(laid_at) || laid_at[j] == at[i] || (it = recoloured(it, i))
    items[i] = Item(i, i, top, it.tall, it.content)
    top += it.tall
  end
  e.flows[key] = Laid(b.version, copy(lines), items)
  e.flows[(:opens, key)] = Opens(b.path, b.view, b.version, String[], Line[], at)
  items
end

"""
The Flow `f` of the item `it`, with the colours of its code, to draw. A line of
a file whose lines on screen are each one run of text is in one colour: see
`quick_line`. The line as `file_line` lays it out has its colours, and is kept
by its text. It's drawn only if it breaks where `f` does, so the page's lines
stay where the layout put them.
"""
in_colour(e, it::Item, f::Flow) = begin
  b = e.buf
  (b.view != :markdown && it.first == it.last && 1 <= it.first <= length(b.lines)) || return f
  all(vl -> length(vl.segs) == 1, f.lines) || return f
  text = b.lines[it.first]
  (last(f.lines).to == length(text) && startswith(text, f.lines[1].segs[1].text)) || return f
  line = kinds(b)[it.first]
  spare_flows!(e)
  full = get!(() -> file_line(e, text, line, it.first), e.flows, (:file, text, line, string_opens(b)[it.first]))::Flow
  length(full.lines) == length(f.lines) && all(k -> full.lines[k].from == f.lines[k].from, eachindex(f.lines)) ? full : f
end

"""
Forget the lines that are laid out, when many are kept: more than a page of
4,000 lines has, or more than three for each line of a longer page, so that a
long page's lines stay laid out from one frame to the next. The layout of a
whole file's lines stays: it's made again only after a change.
"""
spare_flows!(e) = begin
  length(e.flows) > max(4000, 3length(e.buf.lines)) || return e
  kept = [p for p in e.flows if p.second isa Laid || p.second isa Opens || p.second isa Vector{Union{Nothing,PlainLine}}]
  empty!(e.flows)
  foreach(p -> e.flows[p.first] = p.second, kept)
  e
end

"What the page shows for a file that doesn't show as text: a viewer of its kind, or words that say it's a binary file"
@def mutable struct FileView <: SemanticUI
  path::String = ""
  viewer::Any = nothing   # the STLViewer, the player or the Pages of the file, kept from one frame to the next
  table::Any = nothing    # the FileSheet of a CSV file: its table, and what's chosen for it
  button::Any = nothing   # the HexButton of a binary file
end

"The button under the words that say a file is binary. A click shows the file's bytes."
@def mutable struct HexButton <: SemanticUI end

describe(b::HexButton) = Box(height(30px), padding(14px, 0px), radius(6px), background(ishovered(b) ? colours.active : colours.hover),
                             label("View as hexadecimal", 13px))
cursor(::HexButton) = :hand
onkey(b::HexButton, ::KeyPress{Keys.mouse_left}) = (hex!(editor(b)); handled)

cursor(::FileView) = :arrow

"The one item of the page of a file that shows in a viewer"
file_item(e, b::Buffer) = begin
  v = node!(() -> FileView(path=b.path), e, (:fileview, b.path))
  # What covers the page's whole space isn't one of the page's items, so it has no height to learn
  b === e.buf && (page_covered(e) || html_shown(e) || file_covers(e)) && return Item(1, 1, 0px, 1px, Live(v, 1px))
  # Lay it out once to learn how tall it is
  concrete = describe(Column(fixed(e.width), Alignment.Start, geometry(v)), (e.width, 9999px))
  high = concrete.height + 2LIVE_GAP
  Item(1, 1, 0px, high, Live(v, high))
end

# A file that you open is all that its page shows. So a model, a picture, a PDF file and a video cover the
# page's whole space in the window, under the top bar, as the page of an HTML file does. One in another
# page, like a model in a gallery, has the room that the page gives it, and so does a part of another page.

"The viewer that covers the page's space with the model in the file that shows, or nothing if the page shows no file that can be read as a model"
model_part(e) = begin
  b = e.buf
  (b.view == :file && hosted(e) === nothing && lowercase(splitext(b.path)[2]) in MODELS && isfile(b.path)) || return nothing
  m = node!(() -> STLViewer(path=b.path, fill=true), e, (:model_page, b.path))
  load!(m) isa Mesh || return nothing
  # The top bar says how big the file is and when it changed, as it does for a table
  b.about = file_about(b.path)
  m
end

"True when the page shows a model's file as the model, which covers the page's whole space"
model_shown(e) = model_part(e) !== nothing

"What the top bar says of a file that's only shown: how big it is and when it changed"
file_about(path) = bytes(filesize(path)) * "  ·  Changed " * Libc.strftime("%-d %b %Y, %H:%M", mtime(path))

"What of the file at `path` fills its own page as a picture does: a picture, or the first page of a PDF file. Nothing for any other file."
file_fill(path) = begin
  ext = lowercase(splitext(path)[2])
  if ext in PICTURES || ext in MAC_PICTURES
    key = picture_key(path)
    key === nothing ? nothing : (:picture, key)
  elseif Sys.isapple() && ext == ".pdf"
    pdf_pages(path) > 0 ? (:pdf, path, 1) : nothing
  end
end

"""
The view that covers the page's space with the picture or the PDF file that
shows, or nothing if the page shows no such file. It's what fills the window
for a picture in a document, without the room round it and the button that
closes it: the picture fits the page's space, a pinch or a scroll with ⌘ makes
it bigger, a drag moves it, and a PDF file turns its pages. Its bar of buttons
shows while the mouse is over the foot of the page.
"""
file_zoom(e) = begin
  b = e.buf
  (b.view == :file && hosted(e) === nothing && isfile(b.path)) || return nothing
  v = get(e.nodes, (:file_zoom, b.path), nothing)
  # The file is looked at again only when it changes, since this is asked several times in each frame
  read = mtime(b.path)
  if v === nothing || v.read != read
    what = file_fill(b.path)
    what === nothing && return nothing
    v = node!(() -> ZoomView(bare=true), e, (:file_zoom, b.path))
    v.read = read
    if !same_what(v.what, what)
      v.what, v.path, v.zoom, v.fits, v.grab = what, b.path, 0.0, true, nothing
      what[1] == :pdf && ((v.page, v.pages) = (1, max(1, pdf_pages(b.path))))
    end
  end
  about = v.what[1] == :pdf ? "$(v.pages) page$(v.pages == 1 ? "" : "s")" : (s = subject_size(v); s === nothing ? "" : "$(round(Int, s[1])) × $(round(Int, s[2]))")
  b.about = (isempty(about) ? "" : about * "  ·  ") * file_about(b.path)
  v
end

"The player that covers the page's space with the video in the file that shows, or nothing if the page shows no video"
video_part(e) = begin
  b = e.buf
  (b.view == :file && hosted(e) === nothing && Sys.isapple() && lowercase(splitext(b.path)[2]) in VIDEOS && isfile(b.path)) || return nothing
  p = node!(() -> VideoPlayer(path=b.path), e, (:video_page, b.path))
  b.about = file_about(b.path)
  p
end

"True when the file that shows covers the page's whole space: a model, a picture, a PDF file or a video"
file_covers(e) = model_shown(e) || file_zoom(e) !== nothing || video_part(e) !== nothing

"""
Do what the key `K` does to the picture, the PDF file or the video that covers
a file's own page. It's `handled`, or nothing for a key that the page takes as
it always does. The keys that change the size of a page's text change the size
of a picture, and the arrows turn the pages of a PDF file.
"""
file_key!(e, K, w, command) = begin
  v = file_zoom(e)
  if v !== nothing
    command == :bigger && return zoom_by!(v, ZOOM_STEP, view_middle(v)...)
    command == :smaller && return zoom_by!(v, 1 / ZOOM_STEP, view_middle(v)...)
    command == :usual_size && return fit_now!(v)
    unmodified(w) && v.what[1] == :pdf && K in (Keys.left, Keys.right, Keys.up, Keys.down) && return turn!(v, K in (Keys.left, Keys.up) ? -1 : 1)
    return nothing
  end
  p = video_part(e)
  (p === nothing || !unmodified(w)) && return nothing
  # F makes the video fill the screen. Space plays and stops it, and ← and → go back and on in it.
  K == Keys.f && return screen_video!(e, p)
  K in (Keys.space, Keys.left, Keys.right) ? onkey(p, KeyPress{K}(0, w)) : nothing
end

"The picture kept under `key`, `wide` across, and no wider than the page's text"
fitted(e, key, wide; line=false) = begin
  source = image_source(key)
  w = min(e.width, px(wide))
  h = w * source.height / source.width
  line ? Image(key, fixed(w), height(h), radius(3px), border(1px, :solid, colours.line)) : Image(key, fixed(w), height(h), radius(4px))
end

"""
What shows the file of `v`, or nothing if Ladder has nothing that shows it.
`note(words)` adds words to the line that says how big the file is.
"""
viewer(v::FileView, e, note) = begin
  path = v.path
  ext = lowercase(splitext(path)[2])
  mac = Sys.isapple()
  _, h = window_size(e)
  room = clamp(h - TOPBAR_H - PAGE_TOP - 150px, 240px, 800px)   # how tall a model or a video shows
  # What's made for the file is kept, so the model stays as it was turned and the file plays on
  made(make, T) = v.viewer isa T ? v.viewer : (v.viewer = own!(v, make()))
  if ext in PICTURES || ext in MAC_PICTURES
    key = picture_key(path)
    key === nothing && return nothing
    source = image_source(key)
    # A picture of pixels is a pixel to the px. One that macOS read, like an SVG, is the size that macOS says it is.
    size = something(natural(key), (source.width, source.height))
    note("$(round(Int, size[1])) × $(round(Int, size[2]))")
    return fillable(v, (:picture, key), fitted(e, key, size[1]))
  elseif ext in MODELS
    m = made(() -> STLViewer(path=path), STLViewer)
    zoomed_node(e, m) || (m.height = room)   # one that fills the window is as tall as the window
    return load!(m) isa Mesh ? fillable(v, (:node, m), m, wide=:grow) : nothing
  elseif mac && ext in SOUNDS
    return made(() -> AudioPlayer(path=path), AudioPlayer)
  elseif mac && ext in VIDEOS
    p = made(() -> VideoPlayer(path=path), VideoPlayer)
    zoomed_node(e, p) || (p.height = room)
    return fillable(v, (:node, p), p, wide=video_wide(p))
  elseif mac && ext == ".pdf"
    p = made(() -> Pages(path=path, count=pdf_pages(path)), Pages)
    p.count == 0 && return nothing
    p.wide = e.width
    return p
  elseif ext in JSONS
    root = json_of(path)
    root === nothing && return nothing
    t = made(() -> JSONTree(path=path), JSONTree)
    t.root === root || plant!(t, root)   # a file that changed shows afresh
    json_holder(root) && note(json_count(root))
    return t
  elseif ext in TABLES
    return sheet_view(v, e, note)
  end
  # The picture that the Finder shows: the first page of a Word file, the letters of a font,
  # and what it has for many kinds of file that have no viewer here
  key = thumbnail(path)
  key === nothing && return nothing
  fillable(v, (:picture, key), fitted(e, key, image_source(key).width / 2, line=ext in DOCUMENTS))   # the picture has two pixels to the px
end

describe(v::FileView) = begin
  e = editor(v)
  # A Text on its own would take the whole width and start at the left, so each is in a box that the column centres
  words(parts) = Column(width(grow=grow), padding(90px, 0px, 30px, 0px), child_gap=10px, [p isa Text ? Box(p) : p for p in parts]...)
  # A kind of folder can show a file that it holds, or itself, its own way
  o = e.buf.path == v.path ? page_object(e) : object(e, v.path)
  own = o === nothing ? nothing : with_theme(() -> page_view(e, o), component_theme(e.zoom))
  own === nothing || return Box(width(grow=grow), Alignment.Start, own)
  # A folder with no page of its own shows its folders and files as the sidebar does
  isdir(v.path) && return Box(width(grow=grow), Alignment.Start, node!(() -> FolderPage(path=v.path), e, (:folder_page, v.path)))
  isfile(v.path) || return words((label("$(basename(v.path)) isn't there any more", 15px),))
  about = bytes(filesize(v.path)) * "  ·  Changed " * Libc.strftime("%-d %b %Y, %H:%M", mtime(v.path))
  filesize(v.path) == 0 && return words((label("$(basename(v.path)) is empty", 15px), label(about, 12px, color=colours.dim)))
  # A model and a player are components, so they get the colours and the text size that a live block gives them
  with_theme(component_theme(e.zoom)) do
    content = try
      viewer(v, e, more -> (about *= "  ·  " * more))
    catch
      nothing
    end
    line = label(about, 12px, color=colours.dim)
    if content === nothing
      # Nothing shows this file, so the page says what it is, and its bytes are a click away
      v.button === nothing && (v.button = own!(v, HexButton()))
      return words((Icon("file-earmark-binary", size=34px, color=colours.faint), label("$(basename(v.path)) is a binary file", 15px),
                    line, Box(height(4px)), v.button))
    end
    # A table and the tree of a JSON file can be long, so what's said about them is in the top bar, where it
    # stays in sight while they scroll. Anything else has the line about it under it.
    if lowercase(splitext(v.path)[2]) in (TABLES..., JSONS...)
      e.buf.path == v.path && (e.buf.about = about)
      return Box(width(grow=grow), Alignment.Start, content)
    end
    Column(width(grow=grow), child_gap=10px, content, Box(line))
  end
end

# --- a CSV file in the page -------------------------------------------------------------------
#
# A CSV file that the sidebar opens shows as a table as wide as the window has
# room for. Each column is as wide as its first rows need, up to `WIDEST_CELL`,
# and a table that's narrower than the window shares the rest of the room
# among its columns. A table that's wider than the window scrolls sideways: two
# fingers that move sideways on the trackpad, or the wheel with ⇧ held. Text
# that's too long for its column stops with an …. The row of headings stays at
# the top of the window while the rows scroll under it. A thin line with round
# corners goes round the table.
#
# A click on a heading opens a menu. Its first part puts the rows in the order
# of that column, A to Z or Z to A, and a click on the order that the rows have
# now puts them back in the file's order. A column of numbers goes in the order
# of its numbers. Empty cells go last in both orders.
#
# The menu's second part shows fewer rows. A column with no more than
# `FEW_VALUES` different values lists them, each with how many rows have it. A
# click on a value ticks it, and only the rows with a ticked value show. Any
# other column has a field, and only the rows with its words in that column
# show. Return keeps what the field holds, and esc puts back what it held
# before. The heading of a column that shows fewer rows is in the accent
# colour, with a funnel beside it. The top bar says how big the file is, when
# it last changed, and how many rows show. It's there and not over the table,
# so the words stay in sight while the table scrolls. The table starts nearer
# the top bar than the text of a page does, so the window shows more rows.
#
# Ladder reads `FILE_ROWS` rows of the file at most. When the file changes on
# the disk and its headings stay the same, the table keeps its order and what
# it shows.
#
# The table is the file at its highest level. ⌘E, or the slider in the top
# bar, goes down to the file's text, and the slider goes on down to its bytes
# in hexadecimal and its bits. Back at the table, the rows are in the order
# and show what they did. See "the slider of the levels".

const FILE_ROWS = 100_000       # the most rows of a CSV file that the page reads
const FILE_BYTES = 40_000_000   # and the most of the file that it reads
const HEAD_H = 30px             # how tall the row of headings is
const CELL_PAD = 10px           # on each side of a cell's text
const SHEET_LINE = 1px          # the line round the table
const SHEET_ROUND = 6px         # how round the corners of that line are
const SHEET_ABOVE = 4px         # the room over the table. With LIVE_GAP, the table is 12px under the top bar.
const WIDEST_CELL = 360px       # the widest a column is before the columns share the room that's left
const FEW_VALUES = 20           # a column with no more different values than this lists them in its menu
const SHEET_MENU_W = 240px
const SHEET_KEY = :sheet_column

"The table of a CSV file that the page shows, and what's chosen for it"
mutable struct FileSheet
  table::Csvs.Table
  at::Float64                      # when the file last changed, when it was read
  natural::Vector{px}              # how wide each column needs to be, up to WIDEST_CELL
  widths::Vector{px}               # how wide each column is in the page
  wide::px                         # how wide the page was when the widths were worked out
  sort::Any                        # the column that the rows are in the order of and :asc or :desc, or nothing for the file's order
  filters::Dict{Int,String}        # the words that a column's cells must have, for each column that has some
  picks::Dict{Int,Set{String}}     # the values that show, for each column whose menu lists its values and has some ticked
  sought::Any                      # what the rows were last found for: the order, and what each column keeps
  found::Vector{Int}               # the rows that show, in the order that they show in. Row 1 is the headings.
  values::Dict{Int,Any}            # each column's values with how many rows have each, or nothing when it has more than FEW_VALUES
  asking::Int                      # the column whose menu is open, or 0
  was::Any                         # what that column kept when its menu opened, which esc puts back
  field::Any                       # the text field of the menu
  parts::Dict{Any,Any}             # the headings and the lines of the menu, kept between frames
  across::px                       # how far the table is scrolled to the right
  cut::Dict{Tuple{Int,Int},Tuple{px,String}}   # the text of a cell as it shows, with the width that it was cut short for
end

"The font of a cell, or of a heading with `bold`"
cell_face(bold=false) = Face(SANS, bold ? "Semibold" : "", 12px, colours.ink, false)

"""
The table in the CSV file at `path`, read for the page. When `old` is the
table that the file had before and the headings are the same, the new one
keeps its order, what it shows, and how far it's scrolled.
"""
file_sheet(path, old) = begin
  t = Csvs.load(path, most=FILE_ROWS, upto=FILE_BYTES)
  rows = t.rows
  head, plain = cell_face(true), cell_face()
  # A heading has room for the arrow of its order beside it
  need(r, c) = measure(r == 1 ? head : plain, first(celltext(rows[r][c]), 300)) + (r == 1 ? 14px : 0px)
  natural = [clamp(maximum(r -> need(r, c), 1:min(length(rows), 200)), 24px, WIDEST_CELL) + 2CELL_PAD for c in eachindex(t.numbers)]
  s = FileSheet(t, mtime(path), natural, copy(natural), 0px, nothing, Dict{Int,String}(), Dict{Int,Set{String}}(), nothing, Int[],
                Dict{Int,Any}(), 0, nothing, nothing, Dict{Any,Any}(), 0px, Dict{Tuple{Int,Int},Tuple{px,String}}())
  if old isa FileSheet && !isempty(rows) && !isempty(old.table.rows) && old.table.rows[1] == rows[1]
    s.sort, s.filters, s.picks, s.across = old.sort, old.filters, old.picks, old.across
    s.asking, s.was, s.field, s.parts = old.asking, old.was, old.field, old.parts
  end
  s
end

"Share the page's width `wide` among the columns of `s`. A table that's narrower than the page grows, each column by its share."
spread!(s::FileSheet, wide) = begin
  s.wide == wide && return s
  total = sum(s.natural, init=0px)
  s.widths = total < wide ? s.natural .* (num(wide) / num(total)) : copy(s.natural)
  s.wide = wide
  empty!(s.cut)
  s
end

"True when column `c` of `s` shows only some rows"
narrowed(s::FileSheet, c::Int) = haskey(s.filters, c) || haskey(s.picks, c)
"True when some column of `s` shows only some rows"
narrowed(s::FileSheet) = !isempty(s.filters) || !isempty(s.picks)

"Keep only the rows that have `words` in column `column`. No words takes that away."
keep!(s::FileSheet, column::Int, words) = begin
  words = String(strip(words))
  isempty(words) ? delete!(s.filters, column) : (s.filters[column] = words)
  s
end

"""
The values of column `c` of `s`, each with how many rows have it, in the order
that the column puts them in. It's nothing when the column has more than
`FEW_VALUES` different values.
"""
values_of(s::FileSheet, c::Int) = get!(s.values, c) do
  counts = Dict{String,Int}()
  for r in 2:length(s.table.rows)
    value = s.table.rows[r][c]
    counts[value] = get(counts, value, 0) + 1
    length(counts) > FEW_VALUES && return nothing
  end
  [(value, counts[value]) for value in in_order(s.table, collect(keys(counts)), c, :asc, value -> value)]
end

"""
`items` in the order of column `c` of `t`, A to Z with `way` :asc and Z to A
with :desc. `cell(item)` is the text of the item's cell. In a column of
numbers, the cells that are numbers go in the order of their numbers, and come
before the rest. Empty cells go last whichever way.
"""
in_order(t::Csvs.Table, items, c, way, cell) = begin
  rev = way == :desc
  blank = [x for x in items if isempty(cell(x))]
  full = [(x, lowercase(cell(x))) for x in items if !isempty(cell(x))]
  if t.numbers[c]
    found = [(x, Charts.number(cell(x))) for (x, _) in full]
    numbers = sort!([(x, n[1]) for (x, n) in found if n !== nothing], by=last, rev=rev)
    words = sort!([(x, lowercase(cell(x))) for (x, n) in found if n === nothing], by=last, rev=rev)
    return [first.(numbers); first.(words); blank]
  end
  [first.(sort!(full, by=last, rev=rev)); blank]
end

"""
The rows of `s` that show, in the order that they show in: the rows that have
each column's words in that column and one of its ticked values, in the order
of the column that's chosen. When they change, a page that was scrolled down
the table goes back to the top of the table.
"""
sheet_rows!(e, s::FileSheet) = begin
  key = (s.sort, copy(s.filters), Dict(c => copy(p) for (c, p) in s.picks))
  key == s.sought && return s.found
  rows = s.table.rows
  words = [(c, lowercase(w)) for (c, w) in s.filters]
  keep = [r for r in 2:length(rows) if all(((c, w),) -> occursin(w, lowercase(rows[r][c])), words) &&
                                       all(((c, p),) -> rows[r][c] in p, s.picks)]
  s.sort === nothing || (keep = in_order(s.table, keep, s.sort[1], s.sort[2], r -> rows[r][s.sort[1]]))
  s.sought === nothing || (e.scroll.offset = min(e.scroll.offset, sheet_top()))
  s.sought, s.found = key, keep
  keep
end

"How far the top of the table of a CSV file is under the top of the page"
sheet_top() = SHEET_ABOVE + LIVE_GAP + SHEET_LINE

"The text of row `r`, column `c` of `s`, as it shows in a column that's `room` wide: on one line, and cut short with an … when it's too long"
shown_cell(s::FileSheet, r, c, room, face=cell_face(r == 1)) = begin
  kept = get(s.cut, (r, c), nothing)
  kept !== nothing && kept[1] == room && return kept[2]
  length(s.cut) > 50_000 && empty!(s.cut)
  text = first(celltext(s.table.rows[r][c]), 300)
  while measure(face, text) > room && length(text) > 1
    text = first(text, max(1, floor(Int, (length(text) - 1) * num(room) / num(measure(face, text))) - 1)) * "…"
  end
  s.cut[(r, c)] = (room, text)
  text
end

"A node of the headings or of the menu of the table of `v`, kept between frames"
sheet_part!(make, v, key) = get!(() -> own!(v, make()), (v.table::FileSheet).parts, key)

"""
The table of the CSV file that `v` shows, or nothing when the file has no
table. It's as wide as the page and as tall as all the rows that show, but only
the rows in the window are made. The headings stay at the top of the window
while the page is scrolled down the table. `note(words)` adds to what the top
bar says of the file.
"""
sheet_view(v, e, note) = begin
  at = mtime(v.path)
  (v.table isa FileSheet && v.table.at == at) || (v.table = file_sheet(v.path, v.table))
  s = v.table::FileSheet
  isempty(s.table.problem) || return nothing
  # What the field of a heading's menu holds is what its column keeps, as it's typed
  s.asking > 0 && s.field !== nothing && values_of(s, s.asking) === nothing && keep!(s, s.asking, s.field.text)
  found = sheet_rows!(e, s)
  n, total = length(found), length(s.table.rows) - 1
  held = s.table.more ? "the first $(commas(total)) rows" : "$(commas(total)) row$(total == 1 ? "" : "s")"
  note(n < total || narrowed(s) ? "$(commas(n)) of $held" : held)
  wide = e.width - 2SHEET_LINE   # the room inside the line round the table
  spread!(s, wide)
  room = sum(s.widths, init=0px)
  s.across = clamp(s.across, 0px, max(0px, room - wide))
  _, h = window_size(e)
  into = e.scroll.offset - sheet_top()   # how far the top of the window is past the top of the table
  lo = clamp(floor(Int, (into - HEAD_H) / ROW_H) - 4, 0, n)
  hi = min(n, lo + ceil(Int, h / ROW_H) + 8)
  plain = cell_face()
  row(k) = (r = found[k];
    Row(fixed(room), height(ROW_H), Alignment.Start, background(iseven(k) ? colours.stripe : clear),
      [Row(fixed(w), height(ROW_H), padding(CELL_PAD, 0px), Alignment.Center, clip=true, label(shown_cell(s, r, c, w - 2CELL_PAD, plain), 12px))
       for (c, w) in enumerate(s.widths)]...))
  none = n == 0 ? (Box(fixed(min(room, wide)), height(2ROW_H), label("No row has what the headings keep.", 12px, color=colours.dim)),) : ()
  rows = Column(fixed(room), Alignment.Start, spacer(HEAD_H + ROW_H * lo), [row(k) for k in lo+1:hi]..., spacer(ROW_H * (n - hi)), none...)
  heads = Row(fixed(room), height(HEAD_H), Alignment.Start, background(colours.head),
    [sheet_part!(() -> SheetHead(of=v, column=c), v, (:head, c)) for c in eachindex(s.widths)]...)
  # The headings are over the rows, and move down with the window until the rows end
  stick = clamp(into, 0px, ROW_H * max(n - 1, 0))
  table = Stack(fixed(room), Alignment.Start, rows, Box(Alignment.Start, offset_y=stick, heads))
  frame = sheet_part!(() -> SheetFrame(of=v), v, :frame)
  frame.wide, frame.inside = e.width, Box(Alignment.Start, offset_x=-s.across, table)
  frame
end

"The line round a CSV file's table, which has round corners. The table scrolls sideways inside it."
@def mutable struct SheetFrame <: SemanticUI
  of::Any = nothing       # the FileView
  wide::px = 0px          # how wide it is, with its line
  inside::Any = nothing   # what's in it in this frame: the table, as far to the left as it's scrolled
end

describe(f::SheetFrame) = Row(fixed(f.wide), Alignment.Start, padding(SHEET_LINE), clip_x=true, name="Table frame", detach!(f.inside))
cursor(::SheetFrame) = :arrow

# The rows of the table have square ends, so the page's colour goes over what of them is outside the
# round corners. The line goes round on top of that.
draw(ctx, size, ui::ConcreteRect, f::SheetFrame) = begin
  x, y, w, h, r = num(ui.left), num(ui.top), num(ui.width), num(ui.height), num(SHEET_ROUND)
  shape = Skia.sk_path_new()
  rect = Ref(Skia.sk_rect_t(Float32(x), Float32(y), Float32(x + w), Float32(y + h)))
  Skia.sk_path_add_rounded_rect(shape, rect, Float32(r), Float32(r), Skia.SK_PATH_DIRECTION_CW)
  Skia.sk_canvas_save(ctx)
  Skia.sk_canvas_clip_path_with_operation(ctx, shape, Skia.SK_CLIP_OP_DIFFERENCE, true)
  foreach(((cx, cy),) -> round_box(ctx, cx, cy, r, r, 0; fill=colours.bg), ((x, y), (x + w - r, y), (x, y + h - r), (x + w - r, y + h - r)))
  Skia.sk_canvas_restore(ctx)
  Skia.sk_path_delete(shape)
  line = num(SHEET_LINE)
  round_box(ctx, x + line / 2, y + line / 2, w - line, h - line, r - line / 2; line=colours.line, wide=line)
  nothing
end

# Two fingers that move sideways, or the wheel with ⇧ held, scroll a wide table sideways. Their move up or down scrolls the page.
onscroll(v::FileView, ev::MouseScroll) = begin
  s = v.table
  (s isa FileSheet && ev.delta[1] != 0px) || return nothing
  s.across = clamp(s.across - 30ev.delta[1], 0px, max(0px, sum(s.widths, init=0px) - s.wide))
  ev.delta[2] == 0px ? handled : nothing
end

"The heading of a column of a CSV file's table. A click on it opens the column's menu."
@def mutable struct SheetHead <: SemanticUI
  of::Any = nothing   # the FileView
  column::Int = 1
end
"The menu of a column of a CSV file's table: its two orders, and what shows fewer rows"
@def mutable struct SheetMenu <: SemanticUI
  of::Any = nothing
  column::Int = 1
end
"One of the two orders in the menu of a column of a CSV file's table"
@def mutable struct SheetOrder <: SemanticUI
  of::Any = nothing
  way::Symbol = :asc
end
"A value in the menu of a column of a CSV file's table. A click ticks it, or takes the tick away."
@def mutable struct SheetValue <: SemanticUI
  of::Any = nothing
  value::String = ""
  count::Int = 0
end

describe(h::SheetHead) = begin
  s = h.of.table::FileSheet
  c = h.column
  w = s.widths[c]
  way = s.sort !== nothing && s.sort[1] == c ? s.sort[2] : nothing
  lit = ishovered(h) || s.asking == c
  fewer = narrowed(s, c)
  colour = fewer ? colours.accent : colours.ink
  # The funnel of a column that shows fewer rows, and the arrow of its order. With neither, the mouse over the heading shows that it opens.
  marks = ((fewer ? (Icon("funnel-fill", size=9px, color=colours.accent),) : ())...,
           (way !== nothing ? (Icon(way == :asc ? "chevron-up" : "chevron-down", size=9px, color=colours.ink),) :
            lit && !fewer ? (Icon("chevron-down", size=9px, color=colours.faint),) : ())...)
  room = w - 2CELL_PAD - 13px * length(marks)
  Row(fixed(w), height(HEAD_H), padding(CELL_PAD, 0px), child_gap=4px, Alignment.Center, clip=true,
      background(lit ? colours.hover : clear),
    Box(label(shown_cell(s, 1, c, max(room, 12px)), 12px, color=colour, weight="Semibold")), marks...)
end

cursor(::SheetHead) = :hand
onmouse(::SheetHead, ::MouseMove) = handled

onkey(h::SheetHead, ev::KeyPress{Keys.mouse_left}) = begin
  v = h.of
  s = v.table::FileSheet
  c = h.column
  listed = values_of(s, c) !== nothing
  s.asking = c
  s.was = listed ? (haskey(s.picks, c) ? copy(s.picks[c]) : nothing) : get(s.filters, c, "")
  # The menu's field starts with what the column keeps, which esc puts back
  if !listed
    s.field === nothing && (s.field = own!(v, TextInput(placeholder="Contains…", font_family=SANS, font_size=13px,
                                                        look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))))
    s.field.text = s.was
    s.field.cursor = s.field.anchor = length(s.was)
  end
  menu = sheet_part!(() -> SheetMenu(of=v), v, :menu)
  menu.column = c
  e = editor(v)
  # A click outside the menu closes it and keeps what's chosen
  popup!(ev.window, menu, anchor=h, placement=:below, gap=4px, width=SHEET_MENU_W, key=SHEET_KEY,
         onclose=() -> (v.table isa FileSheet && (v.table.asking = 0); focus(e)), theme=component_theme(e.zoom))
  listed || focus(s.field)
  handled
end

"Close the menu of the table of `v`, and give the keyboard back to the page"
close_sheet_menu!(v) = begin
  v.table isa FileSheet && (v.table.asking = 0)
  w = window_of(v)
  w === nothing || close_popup!(w, SHEET_KEY)
  focus(editor(v))
  handled
end

describe(m::SheetMenu) = begin
  v, c = m.of, found_colours()
  s = v.table::FileSheet
  section(words) = Row(width(grow=grow), height(22px), padding(8px, 0px), Alignment.Center, label(words, 10px, color=c.dim, weight="Semibold"))
  order(way) = sheet_part!(() -> SheetOrder(of=v, way=way), v, (:sort, way))
  values = values_of(s, m.column)
  value(text, count) = (r = sheet_part!(() -> SheetValue(of=v, value=text), v, (:value, m.column, text)); r.count = count; r)
  fewer = values === nothing ?
    (section("FILTER FOR"),
     Box(width(grow=grow), padding(4px, 2px),
       Box(width(grow=grow), height(28px), padding(8px, 0px), radius(6px), border(1px, :solid, c.line), background(c.frame), s.field))) :
    (section("SHOW"), [value(text, count) for (text, count) in values]...)
  Box(width(grow=grow), padding(6px), radius(8px), background(c.frame), border(1px, :solid, c.line),
      shadow(0, 6, 16, RGBA(60 / 255, 45 / 255, 20 / 255, 0.2)), name="Column menu",
    Column(width(grow=grow), Alignment.Start,
      section("SORT"), order(:asc), order(:desc),
      Box(width(grow=grow), height(13px), Alignment.Center, Box(width(grow=grow), height(1px), background(c.rule))),
      fewer...))
end

# The menu sees a key before its text field does. Return keeps what's chosen, and esc puts back what the column kept before.
onkey(m::SheetMenu, ev::KeyPress{Keys.enter}) = unmodified(ev) ? close_sheet_menu!(m.of) : nothing
onkey(m::SheetMenu, ev::KeyPress{Keys.escape}) = begin
  unmodified(ev) || return nothing
  s = m.of.table::FileSheet
  if values_of(s, m.column) === nothing
    keep!(s, m.column, s.was)
  else
    s.was === nothing ? delete!(s.picks, m.column) : (s.picks[m.column] = s.was)
  end
  close_sheet_menu!(m.of)
end

describe(r::SheetOrder) = begin
  s, c = r.of.table::FileSheet, found_colours()
  on = s.sort == (s.asking, r.way)
  numbers = s.asking > 0 && s.table.numbers[s.asking]
  words = numbers ? (r.way == :asc ? "Smallest first" : "Largest first") : (r.way == :asc ? "A–Z" : "Z–A")
  Row(width(grow=grow), height(28px), padding(8px, 0px), radius(6px), child_gap=8px, Alignment.Center,
      background(on || ishovered(r) ? c.pick : c.frame),
    Icon(r.way == :asc ? "chevron-up" : "chevron-down", size=10px, color=on ? c.ink : c.dim),
    label(words, 13px, color=on ? c.ink : c.dim, weight=on ? "Semibold" : ""))
end

cursor(::SheetOrder) = :hand
onmouse(::SheetOrder, ::MouseMove) = handled
# A click on the order that the rows have puts them back in the file's order
onkey(r::SheetOrder, ::KeyPress{Keys.mouse_left}) = (s = r.of.table::FileSheet; s.sort = s.sort == (s.asking, r.way) ? nothing : (s.asking, r.way); handled)

describe(r::SheetValue) = begin
  s, c = r.of.table::FileSheet, found_colours()
  ticked = get(s.picks, s.asking, nothing)
  on = ticked !== nothing && r.value in ticked
  Row(width(grow=grow), height(26px), padding(8px, 0px), radius(6px), child_gap=8px, Alignment.Center,
      background(ishovered(r) ? c.pick : c.frame),
    Box(fixed(10px), (on ? (Icon("check", size=10px, color=c.ink),) : ())...),
    Box(width(grow=grow), Alignment.Start, clip_x=true,
      label(isempty(r.value) ? "Empty" : r.value, 13px, color=isempty(r.value) || !(on || ticked === nothing) ? c.dim : c.ink, weight=on ? "Semibold" : "")),
    Box(label(commas(r.count), 11px, color=c.dim)))
end

cursor(::SheetValue) = :hand
onmouse(::SheetValue, ::MouseMove) = handled
# A click ticks the value, or takes the tick away. With every value ticked, or none, every row shows.
onkey(r::SheetValue, ::KeyPress{Keys.mouse_left}) = begin
  s = r.of.table::FileSheet
  c = s.asking
  ticked = get!(Set{String}, s.picks, c)
  r.value in ticked ? delete!(ticked, r.value) : push!(ticked, r.value)
  (isempty(ticked) || length(ticked) == length(values_of(s, c))) && delete!(s.picks, c)
  handled
end

"What the live block with this code shows"
live(e, code::String) = begin
  key = (:live, e.buf.path, code)
  node = get!(e.nodes, key) do
    shown = Shown(value=evaluate(e, code))
    shown.value isa SemanticUI && own!(shown, shown.value)
    old = pop!(e.nodes, (:replaced, key), nothing)
    old isa Shown && carry!(shown.value, old.value)
    shown
  end
  own!(node!(Document, e, :document), node)
  # Lay it out once to learn how tall it is
  concrete = describe(Column(fixed(e.width), Alignment.Start, geometry(node)), (e.width, 9999px))
  Live(node, concrete.height + 2LIVE_GAP)
end

# --- diagrams -----------------------------------------------------------------------
#
# A code block in the language `mermaid` shows the diagram that its code
# describes: a flowchart, a sequence diagram, a state diagram, a class diagram,
# a pie chart, a mind map, an entity relationship diagram, a Gantt chart or a
# timeline. UI.jl's Mermaid component reads the code and draws it. Click
# it with ⌥ held to see its code, or as plain text put the caret in the block.
# A diagram of the first five kinds can be changed while it fills the window:
# see "a picture, a diagram or a page that fills the window". The last four
# fill the window too, and are changed in their code.

const DIAGRAM = "mermaid"

"True when `code` is the code of a diagram that can be drawn"
isdiagram(code::AbstractString) = problem(code) === nothing

"What the `mermaid` block with this code shows: its diagram, or nothing if the code can't be drawn as one"
diagram(e, code::String) = begin
  isdiagram(code) || return nothing
  # A Shown gives the diagram the page's colours and font, as it does for what a live block makes
  node = get!(e.nodes, (:diagram, code)) do
    shown = Shown(value=Mermaid(code))
    own!(shown, shown.value)
    shown
  end
  own!(node!(Document, e, :document), node)
  # Lay it out once to learn how tall it is
  concrete = describe(Column(fixed(e.width), Alignment.Start, geometry(node)), (e.width, 9999px))
  Live(node, concrete.height + 2LIVE_GAP)
end

# --- formulas ---------------------------------------------------------------------------
#
# A formula is written in TeX between dollar signs. $x^2$ is a formula in a
# line of text. A formula on lines of its own goes between a line of $$ and
# another, or between $$ and $$ on one line, or in a code block in the language
# `math`. It's in the middle of the page, and its fractions and sum signs are
# bigger. math.jl reads the TeX and says where each character goes.
#
# In a line of text the formula is one thing: the caret goes over it in one
# step, and ⌘E shows its TeX. On lines of its own it's a part of the page, as
# a diagram is: the caret goes onto it as a whole, and Return shows its TeX.

"A formula as it's set: in a line of text, or with `display` on lines of its own in the middle of the page"
@def mutable struct Equation <: SemanticUI
  tex::String = ""
  size::px = TEXT_SIZE         # of the text that it's in
  display::Bool = false
  colour::Any = nothing        # of the text that it's in, or nothing for the page's ink
  mid::px = 0px                # in a line of text: how far the middle of the line's capital letters is over the line they stand on
end

"The formula of `m`, with where each of its characters goes"
typeset(m::Equation) = Maths.formula(m.tex, num(m.size), m.display)

"How far a formula in a line of text goes over and under the middle of the line. A row of the page puts the middle of each thing in it at the same height."
half_height(m::Equation) = (f = typeset(m); px(max(Maths.height(f) - num(m.mid), Maths.depth(f) + num(m.mid))))

describe(m::Equation) = begin
  f = typeset(m)
  m.display ? Box(width(grow=grow), height(px(Maths.height(f) + Maths.depth(f)))) : Box(fixed(px(Maths.wide(f))), height(2half_height(m)))
end

draw(ctx, size, ui::ConcreteRect, m::Equation) = begin
  f = typeset(m)
  # On lines of its own it's in the middle of the page. In a line of text it stands on the line that the letters stand on.
  x = m.display ? ui.left + max(0px, ui.width - px(Maths.wide(f))) / 2 : ui.left
  y = m.display ? ui.top + px(Maths.height(f)) : ui.top + half_height(m) + m.mid
  Maths.paint(ctx, f, num(x), num(y), something(m.colour, colours.ink), colours.accent)
  nothing
end

# The mouse over a formula that has a command that Ladder doesn't know says which. Two lines with the
# same text show the same formula, so the words go under the mouse, not under where the formula was drawn.
onmouse(m::Equation, ev::MouseMove) = begin
  words = tip(m)
  isempty(words) && return nothing
  x, y = ev.position
  show_tooltip!(ev.window, tip_label(words), x - 1px, y - 10px, 2px, 20px, placement=:bottom, gap=6px)
  nothing
end

"What the mouse over a formula says: the commands of its TeX that Ladder doesn't know, or nothing when it knows them all"
tip(m::Equation) = (unknown = unique(typeset(m).problems); isempty(unknown) ? "" : "Ladder doesn't know " * join(unknown, ", ", " or "))

"The piece that stands for the formula of span `s`, in text drawn in `base`"
equation(e, s::Span, base::Face) = begin
  m = Equation(tex=s.text, size=base.size, colour=base.color, mid=capital(base) / 2)
  # It's part of its line, which is laid out once and kept. It can reach the document, and it isn't one of the document's children.
  setfield!(m, :parent, node!(Document, e, :document))
  piece(s.text, s.col, base, atomic=true, n=length(s.text), node=Inline(m, px(Maths.wide(typeset(m))), 2half_height(m)))
end

const MATHS_LINE = r"^\s*\$\$(.*\S.*)\$\$\s*$"

"The TeX of a line that holds only a formula between \$\$ and \$\$, or nothing for any other line"
maths_text(text::AbstractString) = begin
  m = match(MATHS_LINE, text)
  m === nothing || occursin("\$\$", m[1]) ? nothing : String(strip(m[1]))
end

"True when line `i` holds only a formula between \$\$ and \$\$, which shows on a line of its own"
maths_line(b::Buffer, i::Int) =
  kinds(b)[i].kind == Kind.paragraph && occursin("\$\$", b.lines[i]) && maths_text(b.lines[i]) !== nothing && Maths.available()

"True when `tex` is a formula that can be set: it has something in it, and the Mac has the font for maths"
has_maths(tex::AbstractString) = !isempty(strip(tex)) && Maths.available()

const MATHS_SMALLEST = 0.5   # how small a formula that's wider than the page gets, as a part of the size of the text

"What a formula on lines of its own shows, or nothing if `tex` can't be set"
equation_item(e, tex) = begin
  (tex === nothing || !has_maths(tex)) && return nothing
  m = get!(() -> Equation(tex=String(tex), display=true), e.nodes, (:equation, String(tex)))
  own!(node!(Document, e, :document), m)
  m.size = body(e).size
  # A formula that's wider than the page is smaller, so that all of it shows
  wide = px(Maths.wide(typeset(m)))
  wide > e.width && (m.size *= max(MATHS_SMALLEST, e.width / wide))
  f = typeset(m)
  Live(m, px(Maths.height(f) + Maths.depth(f)) + 2LIVE_GAP)
end

# --- takeoffs ---------------------------------------------------------------------------
#
# A code block in the language `takeoff` shows a plan that you measure from: a
# page of a PDF file, or a picture. takeoff.jl says how the block is written.
# Click it with ⌥ held to see its lines, or as plain text put the caret in the block.
#
#   - Drop a PDF file or a picture on the block, or click it, to choose the plan.
#   - Set the scale: type it, like 1:100, or choose the ruler, click the two ends
#     of a length that you know and type how long it is.
#   - Two buttons under the table start a measure. Add a measure asks what it
#     measures: type a few words that describe it, like "Double power point".
#     Its item is defined later: the measure is matched to one in Centient.
#     Add from catalogue asks for an item of Centient's catalogue, and shows
#     only on a Mac that has Centient. The item gives the measure its name, and
#     its unit says what the measure is and chooses the tool: a length for an
#     item sold by the metre, an area for one sold by the square metre, and a
#     count for the rest.
#   - A measure with no item and nothing drawn yet is what the tool you choose
#     makes it. A click on a measure in the list chooses its tool too.
#   - The table has no column for a measure's name. A measure with no item
#     shows its words, and a click on them, when it's the measure that's
#     chosen, changes them. A measure with an item shows the item's name, then
#     the catalogue that it's from, and the same click chooses another item.
#   - The table has columns for the price of one and for the cost while a
#     measure has an item. With none, there's no price to show.
#   - What a search of Centient finds shows in a list that floats beside the
#     text field. The search for an item looks in one catalogue at a time: the
#     business's own items, or a supplier's that ⌥ lets you choose. The headings of the table of measures sort and search it.
#   - A click on the unit after a measure's amount lists the units that it can
#     be in, as Centient's unit picker does. Type to search them. The amount
#     shows in the unit that you choose, and the quote's line is in it too. A
#     measure with nothing drawn and no item can take a unit of another kind,
#     and that changes what it measures.
#   - A count takes a mark for each click. A length and an area take a corner for
#     each click. To end one, click the Done button beside its last corner,
#     click twice, or press Return. An area also ends with a click on its
#     first corner.
#   - A corner snaps to the lines of a PDF plan: to the end of a line, to the
#     place where two lines cross, or to the nearest point of a line. A small
#     mark shows where it will go. It snaps to the corners of what's already
#     measured too. The magnet turns snapping off, and so does ⌘ while it's held.
#   - The tool after the area tool cuts a shape out of an area, like a window
#     out of a wall. Draw its outline over the area. What the area comes to is
#     then without the part of the cut-out that's in it. A cut-out is selected,
#     moved and taken away like any outline, and it goes when its area does.
#   - With the arrow, click a mark or a line to select it, drag a corner to move
#     it, and press Delete to take it away. Drag the plan to move it.
#   - A mouse wheel makes the plan bigger and smaller round the mouse, and so
#     does a pinch. Two fingers on the trackpad move the plan. With ⌘ held, they
#     make it bigger and smaller. In the page, the wheel and two fingers move
#     the page until you click the plan. A plan that shows whole stays put.
#   - The button with four arrows makes the block fill the window, with the list
#     of measures beside the plan or under it. Esc puts it back in the page.
#   - V, C, L, A, X and S choose the tools. Esc drops what's half drawn. ⌘Z takes
#     the last change back.
#   - Choose the customer, then Make quote in Centient. Centient makes a quote
#     with a line for each measure. A measure with an item is priced from the
#     catalogue. One with none is a line of its words, to price in Centient.
#
# Every change is written into the block's lines, so the file holds the whole
# takeoff. The catalogue, the contacts and the quote come from Centient through
# its MCP server, which centient.jl starts. Centient's app needn't be open.

const TAKEOFF = Plans.TAKEOFF
const PLAN_LEAST = 220px      # how tall the plan's view is at the least
const REACH = 7.0             # px. A corner or a line that's this near the mouse is under it.
const SNAP = 8.0              # px. A corner that's put this near a line of the plan goes on the line.
const NEAR = 24.0             # the most px to a point of the page: as big as the plan gets
const SETTLED = 0.15          # seconds after the plan last moved until a plan that's slow to draw is drawn sharp
const QUICK = 0.012           # seconds. A plan that's drawn in less is drawn sharp while it moves.
const MOST_FOUND = 8          # the lines of the list under a search
const SIDE_W = 380px          # how wide the list of measures is beside a plan that fills the window
const HUES = (colorant"rgb(222,72,58)", colorant"rgb(38,120,214)", colorant"rgb(30,150,90)", colorant"rgb(232,140,24)",
              colorant"rgb(140,84,208)", colorant"rgb(18,160,170)", colorant"rgb(214,70,150)", colorant"rgb(128,104,72)")
"The tools of a takeoff, in the order of their buttons: the icon of each, what it says of itself, and the letter that chooses it"
const PLAN_TOOLS = (:select => ("cursor", "Select and move  V", 'v'), :count => ("plus-circle", "Count  C", 'c'),
                    :length => ("vector-pen", "Measure a length  L", 'l'), :area => ("pentagon", "Measure an area  A", 'a'),
                    :cut => ("subtract", "Cut a shape out of an area  X", 'x'),
                    :scale => ("rulers", "Set the scale from a length that you know  S", 's'))
"Every icon that a takeoff can show. The built app reads them all when it's made."
const PLAN_ICONS = ["cursor", "plus-circle", "vector-pen", "pentagon", "rulers", "chevron-left", "chevron-right", "zoom-out", "zoom-in",
                    "aspect-ratio", "file-earmark-pdf", "x-lg", "plus-lg", "map", "person", "receipt", "arrows-fullscreen", "fullscreen-exit",
                    "chevron-up", "chevron-down", "check", "subtract", "magnet", "box-seam"]

"True when the page's theme is a dark one"
dark_page() = RGBA(colours.bg).r < 0.5
"""
What's behind the plan's paper, round the table of measures and at the foot of
a takeoff: the theme's colour for things that float over the page, which is a
little lighter than the page. In a dark page it's the page's own colour.
"""
takeoff_back() = dark_page() ? colours.bg : colours.float

"The colour of the measure at place `i` in the list"
hue(i) = HUES[mod1(i, length(HUES))]

"The part of a page of a PDF plan that a takeoff shows, as a picture that Skia draws. It's kept until the view moves."
mutable struct Sharp
  of::Any                         # what it's a picture of
  image::Ptr{Skia.sk_image_t}
  cost::Float64                   # seconds that the last one took to draw
end

"What a `takeoff` block shows: the plan, the tools and the list of measures"
@def mutable struct TakeoffView <: SemanticUI
  n::Int = 0                              # its place among the page's takeoffs
  first::Int = 0                          # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Plans.Takeoff = Plans.Takeoff()
  lines::Vector{String} = String[]        # the lines that `data` was read from
  tool::Symbol = :select
  current::Int = 0                        # the measure that the tools draw for: its place in the list, or 0
  picked::Any = nothing                   # what's selected on the plan: the place of its measure and its shape, and of its point if it's one corner
  draft::Vector{Plans.Point} = Plans.Point[]   # the corners so far of what's being drawn
  zoom::Float64 = 0.0                     # px to a point of the page. 0 fits the page in the view.
  at::Plans.Point = (0.0, 0.0)            # the point of the page at the view's top left
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the view was last drawn in the window: its left, top, width and height
  fitted::Any = nothing                   # the file and the page that the zoom is for
  mouse::Any = nothing                    # the point of the page under the mouse, or the one near it that a corner snaps to
  aim::Any = nothing                      # what `mouse` snapped to: :corner, :crossing or :line, or nothing when it's where the mouse is
  snap::Bool = true                       # corners snap to the lines of the plan
  grab::Any = nothing                     # a drag: of the plan, or of a corner
  clicked::NTuple{3,Float64} = (0.0, 0.0, 0.0)   # when and where the plan was last clicked
  moved::Float64 = 0.0                    # when the view last moved
  asking::Any = nothing                   # what the text field is for: (:name, i), (:item, i), (:extra, i), (:scale,), (:length, a, b) or (:customer,)
  query::String = ""                      # the words that were last searched for
  typed::Float64 = 0.0                    # when the words in the text field last changed
  search::Any = nothing                   # the search that Centient hasn't answered yet
  rows::Vector{Any} = Any[]               # what the last search found
  pick::Int = 1                           # the row of them that Return takes
  known::Dict{String,Any} = Dict{String,Any}()   # what Centient says of each item: its name, its unit, its price
  lookup::Any = nothing                   # the request for those that Centient hasn't answered yet
  quoting::Any = nothing                  # the request for a quote that Centient hasn't answered yet
  said::String = ""                       # what the foot of the block says
  wrong::Bool = false                     # it says what went wrong
  parts::Dict{Any,Any} = Dict{Any,Any}()  # its buttons, rows and text field, kept between frames
  sharp::Sharp = Sharp(nothing, C_NULL, 1.0)
  full::Bool = false                      # it fills the window, over the page
  beside::Bool = false                    # it fills the window with its list of measures beside the plan, not under it
  tall::px = 0px                          # how tall it was in the page when it was last laid out there
  pinned::px = 0px                        # how far the page was scrolled when it filled the window
  sort::Any = nothing                     # the column that the table of measures is sorted by, and which way: (:cost, :desc)
  filters::Dict{Symbol,String} = Dict{Symbol,String}()   # the words that a column's text must have for the table to show a measure
  order::Vector{Int} = Int[]              # the measures that the table shows, in the order that it shows them
  reads::UInt = UInt(0)                   # what its parts read, as one number. See `shown_state`.
  measured::Int = -1                      # the `version` of its geometry when `tall` was measured
end

"The part of a takeoff that shows the plan"
@def mutable struct PlanArea <: SemanticUI
  of::Any = nothing
end
"A button of a takeoff: a tool, a page arrow, the button that makes the quote"
@def mutable struct PlanButton <: SemanticUI
  of::Any = nothing
  action::Any = :none
  icon::String = ""
  words::String = ""
  tip::String = ""
  off::Bool = false                           # it does nothing now, and shows that
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)   # where it was last drawn, to put its tooltip under it
  quiet::Bool = false                         # clicked, so no tooltip until the mouse leaves it
end
"A measure in a takeoff's list"
@def mutable struct MeasureRow <: SemanticUI
  of::Any = nothing
  i::Int = 0
end
"The amount of a measure in its row: the number, then the unit that it's in"
@def mutable struct AmountCell <: SemanticUI
  of::Any = nothing
  i::Int = 0
  unit::Any = nothing   # its UnitWord
end
"The unit after a measure's amount. A click on it shows the list of units that the measure can be in."
@def mutable struct UnitWord <: SemanticUI
  of::Any = nothing     # the AmountCell
end
"The list of units that floats under a measure's amount, with a field that searches it"
@def mutable struct UnitMenu <: SemanticUI
  of::Any = nothing
  i::Int = 0
  side::Symbol = :bottom   # the side of the amount that it's on
  pick::Int = 0            # the row that was picked when it was last drawn. A row that the keys pick is brought in sight.
end
"A unit in the list of units"
@def mutable struct UnitRow <: SemanticUI
  of::Any = nothing
  k::Int = 0
end
"A part of a measure's row that a click changes: its item, or what it adds for waste"
@def mutable struct MeasureCell <: SemanticUI
  of::Any = nothing
  i::Int = 0
  what::Symbol = :item
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)   # where it was last drawn: its width cuts its words short, and its tooltip goes under it
  full::String = ""                           # its words when they're cut short with …, to show in its tooltip, or "" when they fit
end
"""
The heading of a column of the table of measures. It fills the column's cell, so
the mouse can be anywhere over the column to use it. A click sorts by the
column, or opens a menu that sorts and searches it.
"""
@def mutable struct ColumnHead <: SemanticUI
  of::Any = nothing
  key::Symbol = :item
  side::Symbol = :start   # the side of the cell that its words go on: :start, or :end over numbers that line up on the right
  words::Any = nothing    # its HeadWords
end
"The words of a column's heading, and the arrow of its order. The heading's menu and tooltip point at them."
@def mutable struct HeadWords <: SemanticUI
  of::Any = nothing   # the heading
end
"The menu of a column of text: its two orders and a field to search it. It floats under the heading, as it does in Centient's lists."
@def mutable struct ColumnMenu <: SemanticUI
  of::Any = nothing
  key::Symbol = :item
  side::Symbol = :bottom   # the side of the heading that it's on
end
"One of the two orders in the menu of a column"
@def mutable struct SortRow <: SemanticUI
  of::Any = nothing
  key::Symbol = :item
  dir::Symbol = :asc
end
"A line of the list that a search shows: an item of Centient's catalogue, or a contact"
@def mutable struct FoundRow <: SemanticUI
  of::Any = nothing
  k::Int = 0
end
"The foot of the list of items: the catalogue that the list shows. A click on it shows another."
@def mutable struct CatalogueFoot <: SemanticUI
  of::Any = nothing
end
"""
The list of what a search found. It floats beside the text field with an arrow
that points at the field, the way the lists in Centient's own forms do.
"""
@def mutable struct FoundList <: SemanticUI
  of::Any = nothing
  side::Symbol = :bottom   # the side of the text field that it's on
  rows::Any = nothing      # what it showed last. A new list starts at its top.
  pick::Int = 0            # the row that was picked when it was last drawn. A row that the keys pick is brought in sight.
  popup::Any = nothing     # what UI.jl floats it in
  settled::Bool = false    # its side of the text field is chosen, and it keeps that side while it's open
end

"A part of `v` that's kept between frames"
part!(make, v::TakeoffView, key) = begin
  node = get!(make, v.parts, key)
  node.parent === nothing && setfield!(node, :parent, v)
  node
end

"The text field of a takeoff. One field does for the name of a measure, a search, the scale and the rest."
plan_input(v::TakeoffView) = part!(v, :input) do
  TextInput(placeholder="", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

# --- the plan's file ---------------------------------------------------------------------

"The file of the plan, or \"\" when the block names none that's there"
plan_path(v::TakeoffView) = begin
  isempty(v.data.plan) && return ""
  path = abspath(docdir(editor(v)), expanduser(unescaped(v.data.plan)))
  isfile(path) ? path : ""
end

ispdf(path) = lowercase(splitext(path)[2]) == ".pdf"

"How many pages the plan has"
plan_pages(v::TakeoffView) = (path = plan_path(v); isempty(path) ? 0 : ispdf(path) ? pdf_pages(path) : 1)

"""
How wide and how tall the page that shows is, in points, or nothing when there's
no plan to show. A picture has a point for each of its pixels.
"""
plan_size(v::TakeoffView) = begin
  path = plan_path(v)
  isempty(path) && return nothing
  ispdf(path) && return pdf_size(path, v.data.page)
  key = picture_key(path)
  key === nothing && return nothing
  source = image_source(key)
  (Float64(source.width), Float64(source.height))
end

"How tall the plan's view is in a block that's `w` wide: tall enough for the whole page, and no taller than leaves room for the list"
plan_h(v::TakeoffView, w::px) = begin
  s = plan_size(v)
  s === nothing && return 180px
  _, tall = window_size(editor(v))
  clamp((w - 2px(PAPER_EDGE)) * s[2] / s[1] + 2px(PAPER_EDGE), PLAN_LEAST, max(PLAN_LEAST, tall - 280px))
end

"Make the file at `path` the plan"
plan!(v::TakeoffView, path) = begin
  v.data.plan = named(editor(v), path)
  v.data.page = 1
  v.zoom = 0.0
  empty!(v.draft)
  commit!(v)
end

"Ask which file holds the plan, with macOS's own panel"
choose_plan!(v::TakeoffView, w) = begin
  # A window that isn't on the screen, like one a test makes, has no panel to ask with
  (Sys.isapple() && !isempty(w.glfw)) || return handled
  path = with_pool() do
    panel = msg(cls("NSOpenPanel"), "openPanel")
    msg(panel, "setDirectoryURL:", msg(cls("NSURL"), "fileURLWithPath:", nsstring(docdir(editor(v)))))
    # 1 is the panel's Open button
    ccall((:objc_msgSend, libobjc), Int, (Ptr{Cvoid}, Ptr{Cvoid}), panel, sel("runModal")) == 1 || return nothing
    jstring(msg(msg(panel, "URL"), "path"))
  end
  # The panel took the mouse, so the window never heard its button come up
  Keys.mouse_left in w.keys && (w.keys ⊻= Keys.mouse_left)
  path === nothing || plan!(v, path)
  handled
end

"The takeoff under the mouse, or nothing"
takeoff_at(e, w) = begin
  x, y = w.mouse
  for node in values(e.nodes)
    node isa TakeoffView || continue
    r = rect(node)
    r !== nothing && r.left <= x < r.left + r.width && r.top <= y < r.top + r.height && return node
  end
  nothing
end

# --- the block's lines -------------------------------------------------------------------

"The first and the last line of the `n`th takeoff block of `b`, or nothing"
takeoff_lines(b::Buffer, n::Int) = block_lines(b, TAKEOFF, n)

"The first and the last line of the `n`th code block of `b` in the language `lang`, or nothing"
block_lines(b::Buffer, lang::String, n::Int) = begin
  ks = kinds(b)
  seen = 0
  for i in eachindex(ks)
    (ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang == lang) || continue
    (seen += 1) == n || continue
    t = codeblock(b, i)[2]
    return t > i && ks[t].kind == Kind.fence && ks[t].level == 1 ? (i, t) : nothing
  end
  nothing
end

"Read the takeoff again from the lines of its block, if they've changed"
reread!(v::TakeoffView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Plans.takeoff(lines)
  v.current = min(v.current, length(v.data.measures))
  v.picked = nothing
  v
end

"""
Write the takeoff into its block. The caret stays where it was in the text, and
⌘Z takes the change back. If the block's lines aren't the ones that the takeoff
was read from, something else changed them, and the takeoff is read again.
"""
commit!(v::TakeoffView) = begin
  b = editor(v).buf
  readonly(b) && return v
  span = takeoff_lines(b, v.n)
  span === nothing && return v
  i, t = span
  v.first, v.last = i, t
  b.lines[i+1:t-1] == v.lines || return reread!(v, b.lines[i+1:t-1])
  new = Plans.written(v.data)
  new == v.lines && return v
  caret, anchor = b.caret, b.anchor
  edit!(b, line_end(b, i), line_end(b, t - 1), isempty(new) ? "" : "\n" * join(new, "\n"))
  by = length(new) - length(v.lines)
  moved(p) = p[1] >= t ? (p[1] + by, p[2]) : p[1] > i ? (i, 0) : p
  b.caret, b.anchor = moved(caret), moved(anchor)
  v.last += by
  v.lines = new
  v
end

"What the `takeoff` block from line `i` to line `t` shows. `n` is its place among the page's takeoffs."
takeoff_item(e, i, t, n) = begin
  v = get!(() -> TakeoffView(n=n), e.nodes, (:takeoff, e.buf.path, n))
  own!(node!(Document, e, :document), v)
  v.first, v.last = i, t
  reread!(v, e.buf.lines[i+1:t-1])
  # A takeoff that fills the window is drawn over the page, and its room in the page stays empty
  v.full && return Live(Box(width(grow=grow), height(v.tall)), v.tall + 2LIVE_GAP)
  # Lay it out once to learn how tall it is. While nothing that it shows changes, its geometry
  # is kept (see `shown_state`), and so is its height. Laid out again here at another height
  # than the page gives it, the page's layout of it couldn't be used again either.
  g = geometry(v)
  if version(v) == 0 || version(v) != v.measured
    v.tall = describe(Column(fixed(e.width), Alignment.Start, g), (e.width, 9999px)).height
    v.measured = version(v)
  end
  Live(v, v.tall + 2LIVE_GAP)
end

# --- Centient ----------------------------------------------------------------------------

"What Centient says of the item that `ref` names, or nothing if it hasn't said yet"
known(v::TakeoffView, ref) = isempty(ref) ? nothing : get(v.known, ref, nothing)

"Ask Centient for the items of the takeoff that it hasn't told of yet. The plan's view asks when it's drawn, so a takeoff that's out of sight asks nothing."
lookup!(v::TakeoffView) = begin
  v.lookup === nothing || return
  refs = unique!([m.item for m in v.data.measures if !isempty(m.item) && !haskey(v.known, m.item)])
  (isempty(refs) || !Centient.available()) && return
  # An item that Centient doesn't have is asked for once
  foreach(ref -> v.known[ref] = nothing, refs)
  v.lookup = Centient.ask("lookup_items", Dict("refs" => refs))
  nothing
end

"A sentence at the foot of the block. `wrong` shows it as something that went wrong."
say!(v::TakeoffView, words, wrong=false) = (v.said = String(words); v.wrong = wrong; handled)

"An amount of money: \$1,234.50"
dollars(x::Real) = begin
  cents = round(Int, 100x)
  (cents < 0 ? "-" : "") * "\$" * commas(abs(cents) ÷ 100) * "." * lpad(abs(cents) % 100, 2, '0')
end

"""
The price of one of measure `m`'s unit, from the catalogue's `row`. Centient's
price is for one of the item's unit, so an item sold at \$2 a foot is \$6.56 a
metre to a measure in metres. It's nothing when the item is sold by a unit
that `m` can't be in, like a price a metre for a count.
"""
unit_price(m, row) = begin
  u = string(something(get(row, "unit", nothing), ""))
  Plans.kind_for(u) == m.kind || return nothing
  # A unit that Centient doesn't name, like "lineal metre" or "each", is its kind's own
  row["price"] * get(Plans.UNIT_SIZES, Plans.unit(m), 1.0) / get(Plans.UNIT_SIZES, u, 1.0)
end

"What `amount` of its kind's own unit of measure `m` costs at the price of the catalogue's `row`"
cost_of(m, amount::Real, row) = begin
  p = unit_price(m, row)
  p === nothing ? amount * row["price"] : Plans.in_unit(amount, Plans.unit(m)) * p
end

"""
The line of a quote for measure `m`, which comes to `amount` of its kind's own
unit. The line is in the measure's unit, and Centient prices it from the item
in that unit. A measure with no item names none, and its line is its words,
to match to an item in Centient.
"""
quote_line(m, amount::Real) = begin
  unit = Plans.unit(m)
  line = Dict{String,Any}("quantity" => round(Plans.in_unit(amount, unit), sigdigits=6), "unit" => unit, "note" => m.name)
  isempty(m.item) || (line["ref"] = m.item)
  line
end

"Ask Centient for a quote with a line for each measure"
make_quote!(v::TakeoffView) = begin
  v.quoting === nothing || return handled
  t = v.data
  Centient.available() || return say!(v, "Centient isn't on this Mac, so Ladder can't make the quote", true)
  isempty(t.customer) && return say!(v, "Choose the customer first", true)
  lines = Any[]
  for m in t.measures
    amount = Plans.amount(t, m)
    amount === nothing && return say!(v, "Set the scale first, so that $(isempty(m.name) ? "each length" : m.name) has a size", true)
    amount > 0 || continue
    push!(lines, quote_line(m, amount))
  end
  isempty(lines) && return say!(v, "Nothing is measured yet", true)
  plan = isempty(t.plan) ? "" : " of " * basename(t.plan)
  v.quoting = Centient.ask("create_quote", Dict{String,Any}("customer" => t.customer, "notes" => "From a takeoff$plan in Ladder", "lines" => lines))
  say!(v, "Making the quote in Centient…")
end

"""
What happens to a takeoff in each frame, before the page is laid out: a drag
that ended is written down, the text field that lost the keyboard closes, and
Centient's answers are taken.
"""
tick!(v::TakeoffView) = begin
  w = window_of(v)
  v.grab !== nothing && !held(v, Keys.mouse_left) && drop!(v)
  # A click somewhere else took the keyboard from the text field
  v.asking !== nothing && w !== nothing && w.focus !== plan_input(v) && settle_asking!(v)
  waiting = false
  # A column shows what its search finds while you type
  v.asking !== nothing && v.asking[1] == :filter && search_column!(v, v.asking[2], plan_input(v).text)
  # The list of units shows the ones that match what's typed. New words pick the unit that they name, or the first.
  if v.asking !== nothing && v.asking[1] == :unit
    words = String(strip(plan_input(v).text))
    v.rows = Any[u for u in units_for(v, v.asking[2]) if unit_matches(u, words)]
    words == v.query || (v.query = words; v.pick = something(findfirst(u -> names_unit(u, words), v.rows), 1))
    v.pick = clamp(v.pick, 1, max(1, length(v.rows)))
  end
  if v.asking !== nothing && v.asking[1] in (:item, :customer)
    words = String(strip(plan_input(v).text))
    words == v.query || (v.query = words; v.typed = time(); v.pick = 1)
    # The search waits until the typing stops for a moment
    if v.typed > 0 && time() - v.typed > 0.2
      v.typed = 0.0
      from = ITEM_FROM[]
      v.search = v.asking[1] == :customer ? Centient.ask("find_contacts", Dict("query" => words)) :
                 from[1] == :suppliers    ? Centient.ask("list_catalogues", Dict("query" => words)) :
                 Centient.ask("search_catalogue", Dict("query" => words, "catalogue" => from[1] == :own ? "own" : from[2]))
    end
    waiting = v.typed > 0
  end
  Centient.check!()
  r = v.search
  if r !== nothing && Centient.finished(r)
    v.search = nothing
    if Centient.failed(r)
      v.rows = Any[]
      say!(v, r.problem, true)
    else
      v.rows = collect(Any, get(r.value, r.tool == "find_contacts" ? "contacts" : r.tool == "list_catalogues" ? "catalogues" : "items", Any[]))
      v.pick = clamp(v.pick, 1, max(1, length(v.rows)))
    end
  end
  r = v.lookup
  if r !== nothing && Centient.finished(r)
    v.lookup = nothing
    Centient.failed(r) || foreach(row -> v.known[row["ref"]] = row, get(r.value, "items", Any[]))
  end
  r = v.quoting
  if r !== nothing && Centient.finished(r)
    v.quoting = nothing
    if Centient.failed(r)
      say!(v, r.problem, true)
    else
      v.data.made = string(get(r.value, "number", ""))
      company = Centient.server.company
      say!(v, "Centient has quote $(v.data.made) for $(dollars(get(r.value, "total", 0.0))) with GST" * (isempty(company) ? "" : ", in $company"))
      commit!(v)
    end
  end
  # While Centient works, the window looks again soon
  (waiting || v.search !== nothing || v.lookup !== nothing || v.quoting !== nothing) && redraw_in!(v, 0.1)
  v
end

"Do what each takeoff of the page that shows needs in this frame"
takeoff_tick!(e) = for (key, node) in collect(e.nodes)
  (node isa TakeoffView && key[2] == e.buf.path) || continue
  tick!(node)
  node.full || continue
  # A takeoff whose block has gone goes back to the page. Under one that fills the window, the page stays where it was.
  takeoff_lines(e.buf, node.n) === nothing ? (node.full = false) : (e.scroll.offset = node.pinned)
end

# --- the text field ----------------------------------------------------------------------

"Close the text field, if it shows. What's typed in it is kept, but nothing is chosen from a list."
settle_asking!(v::TakeoffView) = v.asking === nothing ? handled : v.asking[1] in (:item, :customer, :unit) ? stop_asking!(v) : answer!(v)

"Show the text field for `what`, with `text` in it and selected"
ask!(v::TakeoffView, what, text="", placeholder="") = begin
  settle_asking!(v)
  i = plan_input(v)
  i.color = colours.ink
  i.text, i.placeholder = String(text), String(placeholder)
  i.anchor, i.cursor = 0, length(i.text)
  v.asking = what
  v.rows, v.pick, v.search = Any[], 1, nothing
  v.query, v.typed = "\0", 0.0   # no words yet, so the first look at the field starts a search
  v.said, v.wrong = "", false
  focus(i)
  if what[1] == :item
    # The list starts on the catalogue that an item was last chosen from, and not on the list of suppliers
    ITEM_FROM[][1] == :suppliers && (ITEM_FROM[] = (:own,))
    i.placeholder = "⌥ to toggle catalogue"
  end
  what[1] in (:item, :customer) && Centient.available() && show_found!(v)
  handled
end

"Take the text field away. The keyboard goes back to the plan."
stop_asking!(v::TakeoffView) = begin
  v.asking = nothing
  v.rows, v.search = Any[], nothing
  w = window_of(v)
  w === nothing || (close_popup!(w, FOUND_KEY); close_popup!(w, HEAD_KEY); close_popup!(w, UNIT_KEY))
  w !== nothing && w.focus === plan_input(v) && focus(part!(() -> PlanArea(of=v), v, :area))
  handled
end

"The number of metres that `text` says: 3.6, 3.6m or 3600mm. It's nothing when it says none."
metres_typed(text) = begin
  m = match(r"^\s*(\d+(?:\.\d+)?)\s*(mm|cm|m)?\s*$", lowercase(text))
  m === nothing && return nothing
  n = parse(Float64, m[1]) * (m[2] == "mm" ? 0.001 : m[2] == "cm" ? 0.01 : 1.0)
  n > 0 ? n : nothing
end

"Give page `page` the scale `n`. A plan's first scale is for all its pages. After that, a page gets a scale of its own."
scale!(v::TakeoffView, n) = begin
  t = v.data
  page = t.page
  key = isempty(t.scales) || plan_pages(v) <= 1 || (length(t.scales) == 1 && haskey(t.scales, 0) && page == 1) ? 0 : page
  t.scales[key] = round(n, digits=1)
  commit!(v)
end

"Take row `k` of what a search found"
choose_row!(v::TakeoffView, k::Int) = begin
  a = v.asking
  (a === nothing || !(1 <= k <= length(v.rows))) && return stop_asking!(v)
  row = v.rows[k]
  # A supplier in the list of suppliers opens its catalogue. The search goes on there.
  a[1] == :item && haskey(row, "slug") && return browse!(v, (:catalogue, string(row["slug"]), string(row["name"])))
  if a[1] == :customer
    v.data.customer = string(row["name"])
  elseif a[2] <= length(v.data.measures)
    m = v.data.measures[a[2]]
    was = known(v, m.item)
    # A measure that still has the name it was made with, or its old item's name, takes the new item's name
    (isempty(m.name) || occursin(FIRST_NAME, m.name) || (was !== nothing && m.name == was["name"])) &&
      (m.name = replace(string(row["name"]), '|' => '/'))
    m.item = string(row["ref"])
    v.known[m.item] = row
    # The item's unit says what the measure is, and the tool for it is ready to draw
    kind = Plans.kind_for(get(row, "unit", nothing))
    isempty(m.shapes) && m.kind != kind && (m.kind = kind; m.unit = "")
    # The amount shows in the unit that the item is sold by, when the measure can be in it
    sold = string(something(get(row, "unit", nothing), ""))
    Plans.unit_kind(sold) == m.kind && Plans.unit!(m, sold)
    stop_asking!(v)
    commit!(v)
    v.current = a[2]
    tool!(v, m.kind)
    m.kind == kind || say!(v, "Centient's price for $(row["name"]) is for $(sold_by(row)), and this measure is $(KIND_WORDS[m.kind])", true)
    return handled
  end
  stop_asking!(v)
  commit!(v)
  handled
end

"Do what the text field was for with what's typed in it"
answer!(v::TakeoffView) = begin
  a = v.asking
  a === nothing && return handled
  text = String(strip(plan_input(v).text))
  t = v.data
  # A column's search changes what the table shows, and nothing in the block
  a[1] == :filter && return (search_column!(v, a[2], text); stop_asking!(v))
  a[1] == :unit && return isempty(v.rows) ? stop_asking!(v) : unit!(v, a[2], v.rows[clamp(v.pick, 1, length(v.rows))])
  if a[1] in (:item, :customer)
    isempty(v.rows) || return choose_row!(v, v.pick)
    # Nothing to choose from. An empty field takes the item away, and a customer is kept as it's typed.
    a[1] == :item && isempty(text) && a[2] <= length(t.measures) && (t.measures[a[2]].item = "")
    a[1] == :customer && !isempty(text) && (t.customer = text)
  elseif a[1] == :name
    a[2] <= length(t.measures) && !isempty(text) && (t.measures[a[2]].name = replace(text, '|' => '/'))
  elseif a[1] == :extra
    n = tryparse(Float64, strip(replace(text, '%' => "", '+' => "")))
    a[2] <= length(t.measures) && (t.measures[a[2]].extra = n === nothing ? 0.0 : clamp(n, 0, 1000) / 100)
  elseif a[1] == :scale
    n = Plans.scale(text)
    n === nothing ? say!(v, "A scale is written like 1:100", true) : scale!(v, n)
  elseif a[1] == :length
    real = metres_typed(text)
    n = real === nothing ? nothing : Plans.scale(a[2], a[3], real)
    n === nothing ? say!(v, "Type the length in metres, like 3.6", true) : scale!(v, n)
    empty!(v.draft)
    v.tool = :select
  end
  stop_asking!(v)
  commit!(v)
  handled
end

# The keys of the text field that the field has no use for come here
onkey(v::TakeoffView, ev::KeyPress{Keys.enter}) = unmodified(ev) ? (v.asking === nothing ? nothing : answer!(v)) : nothing
onkey(v::TakeoffView, ev::KeyPress{Keys.escape}) = begin
  unmodified(ev) || return nothing
  v.asking === nothing && return nothing
  v.asking[1] == :length && (empty!(v.draft); v.tool = :select)
  stop_asking!(v)
end
# ⌥ in an empty search for an item changes the catalogue that the list shows
onkey(v::TakeoffView, ev::KeyPress{Keys.opt}) = begin
  setdiff(held_keys(ev.window), Keys.opt) == Keys(0) || return nothing   # ⌥ by itself
  a = v.asking
  (a !== nothing && a[1] == :item && Centient.available() && isempty(strip(plan_input(v).text))) || return nothing
  toggle_catalogue!(v)
end
onkey(v::TakeoffView, ev::KeyPress{Keys.down}) = unmodified(ev) ? (v.asking === nothing ? nothing : (v.pick = min(v.pick + 1, max(1, length(v.rows))); handled)) : nothing
onkey(v::TakeoffView, ev::KeyPress{Keys.up}) = unmodified(ev) ? (v.asking === nothing ? nothing : (v.pick = max(v.pick - 1, 1); handled)) : nothing

# --- the view of the plan ----------------------------------------------------------------

"The point of the page that's at a place in the window"
page_point(v::TakeoffView, x, y) = (v.at[1] + (x - v.box[1]) / v.zoom, v.at[2] + (y - v.box[2]) / v.zoom)

"The place in the window of a point of the page"
window_point(v::TakeoffView, p) = (v.box[1] + (p[1] - v.at[1]) * v.zoom, v.box[2] + (p[2] - v.at[2]) * v.zoom)

# The lines of the pages of PDF plans that were last shown, each with a grid that finds the ones near the mouse.
# Each is kept under its file, when the file last changed, and its page.
const plan_lines = Dict{Any,Plans.Lines}()

"The lines of the page that shows, for corners to snap to. A picture has none, and nor has a PDF file that's a scan of paper."
lines_of(v::TakeoffView) = begin
  path = plan_path(v)
  (isempty(path) || !ispdf(path)) && return Plans.Lines()
  key = (path, mtime(path), v.data.page)
  kept = get(plan_lines, key, nothing)
  kept === nothing || return kept
  length(plan_lines) >= 4 && empty!(plan_lines)
  s = pdf_size(path, v.data.page)
  found = pdf_lines(path, v.data.page)
  plan_lines[key] = s === nothing || found === nothing ? Plans.Lines() : Plans.Lines(found[1], s[1], s[2], found[2])
end

"""
The point of the page where a corner goes when the mouse is at a place in the
window, and what it snapped to there: :corner, :crossing or :line. With the
magnet off or ⌘ held, and where nothing is near, it's the point under the
mouse, and nothing. `skip` is a corner that it doesn't snap to: the one that's
being dragged.
"""
aim(v::TakeoffView, w, x, y; skip=nothing) = begin
  p = page_point(v, x, y)
  (v.snap && !only_held(w, Keys.cmd)) || return (p, nothing)
  something(Plans.snap(v.data, lines_of(v), v.data.page, p, SNAP / v.zoom, skip=skip), (p, nothing))
end

"The px of white that the view keeps round the paper, so that the paper's edge and its shadow show"
const PAPER_EDGE = 14.0

"How many px to a point fits the whole page in the view, with white round it"
fit_zoom(v::TakeoffView, s) = max(min((v.box[3] - 2PAPER_EDGE) / s[1], (v.box[4] - 2PAPER_EDGE) / s[2]), 1e-3)

"Show the whole page, in the middle of the view"
fit!(v::TakeoffView, s) = begin
  v.zoom = fit_zoom(v, s)
  v.at = ((s[1] - v.box[3] / v.zoom) / 2, (s[2] - v.box[4] / v.zoom) / 2)
  v
end

"""
Keep the page in the view. Where the page is narrower than the view, it stays
in the middle, and so it does where it's shorter. So the plan only moves once
it's bigger than the view, and then no further than its edges, with the
white that the view keeps round the paper. `s` is the page's size in points.
"""
hold!(v::TakeoffView, s) = begin
  w, h = v.box[3] / v.zoom, v.box[4] / v.zoom
  e = PAPER_EDGE / v.zoom
  v.at = (s[1] <= w ? (s[1] - w) / 2 : clamp(v.at[1], -e, s[1] - w + e),
          s[2] <= h ? (s[2] - h) / 2 : clamp(v.at[2], -e, s[2] - h + e))
  v
end

"Note that the view moved just now, and keep the page in it"
moved!(v::TakeoffView) = begin
  v.moved = time()
  s = plan_size(v)
  s === nothing ? v : hold!(v, s)
end

"Make the plan `by` times as big. The point of the page at the place `(x, y)` in the window stays there."
zoom_plan!(v::TakeoffView, by, x, y) = begin
  s = plan_size(v)
  (s === nothing || v.zoom <= 0) && return handled
  p = page_point(v, x, y)
  v.zoom = clamp(v.zoom * by, fit_zoom(v, s), NEAR)   # never smaller than the whole page
  v.at = (p[1] - (x - v.box[1]) / v.zoom, p[2] - (y - v.box[2]) / v.zoom)
  moved!(v)
  handled
end

"Go on by `by` pages"
page!(v::TakeoffView, by) = begin
  page = clamp(v.data.page + by, 1, max(1, plan_pages(v)))
  page == v.data.page && return handled
  v.data.page = page
  v.zoom = 0.0
  v.picked = nothing
  empty!(v.draft)
  commit!(v)
  handled
end

# --- drawing -----------------------------------------------------------------------------

"How many of the screen's pixels a px is wide on the canvas `ctx`"
density(ctx) = begin
  m = Ref(Skia.sk_matrix_t(1f0, 0f0, 0f0, 0f0, 1f0, 0f0, 0f0, 0f0, 1f0))
  Skia.sk_canvas_get_total_matrix(ctx, m)
  sqrt(abs(m[].scaleX * m[].scaleY - m[].skewX * m[].skewY))
end

const plan_sampling = Skia.sk_sampling_options_t(0, false, Skia.sk_cubic_resampler_t(0f0, 0f0),
                                                 Skia.SK_FILTER_MODE_LINEAR, Skia.SK_MIPMAP_MODE_NONE)

"Draw the part `from` of a picture of Skia's into the part `to` of the window. Each is a left, a top, a width and a height."
paint_picture(ctx, image, from, to) = begin
  paint = Skia.sk_paint_new()
  Skia.sk_paint_set_antialias(paint, true)
  paint_picture(ctx, image, from, to, paint)
  Skia.sk_paint_delete(paint)
end
"The same, drawn with `paint`, which the caller deletes"
paint_picture(ctx, image, from, to, paint) = begin
  a = Ref(Skia.sk_rect_t(Float32(from[1]), Float32(from[2]), Float32(from[1] + from[3]), Float32(from[2] + from[4])))
  b = Ref(Skia.sk_rect_t(Float32(to[1]), Float32(to[2]), Float32(to[1] + to[3]), Float32(to[2] + to[4])))
  Skia.sk_canvas_draw_image_rect(ctx, image, a, b, Ref(plan_sampling), paint, Skia.SRC_RECT_CONSTRAINT_FAST)
end

"The part of a page of a PDF plan that the view shows, drawn at the screen's own pixels and kept until the view moves"
sharpen!(v::TakeoffView, path, of, k, x, y, w, h) = sharpen!(v.sharp, path, v.data.page, of, k, x, y, w, h)

"""
The part of page `page` of the PDF file at `path` that's `w` by `h` pixels and
starts `x` and `y` pixels into the page drawn `k` pixels to the point. It's kept
in `p` while `of`, what it's a picture of, stays the same.
"""
sharpen!(p::Sharp, path, page, of, k, x, y, w, h) = begin
  p.of == of && return p.image
  started = time()
  pixels = pdf_part(path, page, k, x, y, w, h)
  p.image == C_NULL || Skia.sk_image_unref(p.image)
  p.image, p.of = C_NULL, of
  pixels === nothing && return C_NULL
  info = Ref(Skia.sk_image_info_t(C_NULL, Skia.SK_COLOR_TYPE_BGRA_8888, Skia.SK_ALPHA_TYPE_PREMUL, w, h))
  GC.@preserve info pixels begin
    data = Skia.sk_data_new_with_copy(pointer(pixels), UInt64(4w * h))
    p.image = Skia.sk_image_new_raster_data(info, data, Csize_t(4w))
    Skia.sk_data_unref(data)
  end
  p.cost = time() - started
  p.image
end

"How round the corners of the plan's paper are, in px"
const PAPER_ROUND = 3.0

"""
Draw the plan's paper, with what shows where it ends on the white behind it:
a soft shadow under it and a thin line round it. Its corners are a little round.
"""
paper!(ctx, (x, y, w, h)) = begin
  shape(grow, down) = begin
    path = Skia.sk_path_new()
    rect = Ref(Skia.sk_rect_t(Float32(x - grow), Float32(y - grow + down), Float32(x + w + grow), Float32(y + h + grow + down)))
    Skia.sk_path_add_rounded_rect(path, rect, Float32(PAPER_ROUND + grow), Float32(PAPER_ROUND + grow), Skia.SK_PATH_DIRECTION_CW)
    path
  end
  fill(path, paint) = (Skia.sk_canvas_draw_path(ctx, path, paint); Skia.sk_paint_delete(paint); Skia.sk_path_delete(path))
  shadow = ink(RGBA(0, 0, 0, 0.2))
  blur = Skia.sk_maskfilter_new_blur_with_flags(Skia.SK_BLUR_STYLE_NORMAL, 6f0, true)
  Skia.sk_paint_set_maskfilter(shadow, blur)
  fill(shape(0, 2), shadow)
  Skia.sk_maskfilter_unref(blur)
  # The line is outside the paper, so the plan doesn't cover it
  fill(shape(0.5, 0), ink(RGBA(0, 0, 0, 0.16), 1))
  fill(shape(0, 0), ink(colorant"white"))
end

"Draw the page of the plan that shows. `s` is its size in points."
draw_plan(ctx, v::TakeoffView, s) = begin
  left, top, wide, tall = v.box
  path = plan_path(v)
  # Where the paper is in the window
  x, y = window_point(v, (0.0, 0.0))
  paper = (x, y, s[1] * v.zoom, s[2] * v.zoom)
  paper!(ctx, paper)
  # What's on the paper is cut off at the paper's round corners
  with_round_clip(() -> plan_ink(ctx, v, s, path, paper), ctx, px(paper[1]), px(paper[2]), px(paper[3]), px(paper[4]), px(PAPER_ROUND))
end

"Draw what's on the paper: the picture, or the part of the PDF page that's in the view"
plan_ink(ctx, v::TakeoffView, s, path, paper) = begin
  left, top, wide, tall = v.box
  if !ispdf(path)
    key = picture_key(path)
    key === nothing || paint_picture(ctx, image_source(key).raw, (0, 0, s[1], s[2]), paper)
    return
  end
  # Never fewer than 2 pixels to the px, so that the plan is sharp on paper too
  d = clamp(density(ctx), 2, 3)
  w, h = round(Int, wide * d), round(Int, tall * d)
  (w < 1 || h < 1) && return
  k = v.zoom * d   # the screen's pixels to a point of the page
  of = (path, mtime(path), v.data.page, k, v.at, w, h)
  p = v.sharp
  # A plan that takes long to draw shows a rougher picture of the whole page while it moves
  if p.of != of && p.cost > QUICK && time() - v.moved < SETTLED
    rough = pdf_page(path, v.data.page, 2000)
    rough === nothing || paint_picture(ctx, image_source(rough).raw, (0, 0, image_source(rough).width, image_source(rough).height), paper)
    redraw_in!(v, SETTLED)
    return
  end
  image = sharpen!(v, path, of, k, v.at[1] * k, v.at[2] * k, w, h)
  image == C_NULL && return
  # The picture is of the whole view, with white where the paper ends. The paper's edge cuts it off.
  paint_picture(ctx, image, (0, 0, w, h), (left, top, wide, tall))
end

"A paint for lines `wide` px wide, or for filling when `wide` is 0"
ink(colour, wide=0.0) = begin
  paint = Skia.sk_paint_new()
  Skia.sk_paint_set_antialias(paint, true)
  Skia.sk_paint_set_color(paint, sk_color(colour))
  Skia.sk_paint_set_style(paint, wide > 0 ? Skia.SK_PAINT_STYLE_STROKE : Skia.SK_PAINT_STYLE_FILL)
  if wide > 0
    Skia.sk_paint_set_stroke_width(paint, Float32(wide))
    Skia.sk_paint_set_stroke_join(paint, Skia.SK_STROKE_JOIN_ROUND)
    Skia.sk_paint_set_stroke_cap(paint, Skia.SK_STROKE_CAP_ROUND)
  end
  paint
end

"Skia's path through the places `ps`. `closed` joins its end to its start."
path_through(ps, closed) = begin
  shape = Skia.sk_path_new()
  for (i, (x, y)) in enumerate(ps)
    i == 1 ? Skia.sk_path_move_to(shape, Float32(x), Float32(y)) : Skia.sk_path_line_to(shape, Float32(x), Float32(y))
  end
  closed && Skia.sk_path_close(shape)
  shape
end

"""
Draw a line through the places `ps`. `fill` colours what's inside it, but not
what's inside one of the outlines `holes`. `closed` joins its end to its start.
`dashed` draws it in dashes.
"""
trace(ctx, ps, colour, wide; fill=nothing, closed=false, holes=(), dashed=false) = begin
  length(ps) < 2 && return
  shape = path_through(ps, closed)
  if fill !== nothing
    paint = ink(fill)
    Skia.sk_canvas_save(ctx)
    for hole in holes
      length(hole) < 3 && continue
      cut = path_through(hole, true)
      Skia.sk_canvas_clip_path_with_operation(ctx, cut, Skia.SK_CLIP_OP_DIFFERENCE, true)
      Skia.sk_path_delete(cut)
    end
    Skia.sk_canvas_draw_path(ctx, shape, paint)
    Skia.sk_canvas_restore(ctx)
    Skia.sk_paint_delete(paint)
  end
  paint = ink(colour, wide)
  if dashed
    dashes = Float32[6, 5]
    effect = Skia.sk_path_effect_create_dash(dashes, Cint(2), 0f0)
    Skia.sk_paint_set_path_effect(paint, effect)
    Skia.sk_path_effect_unref(effect)
  end
  Skia.sk_canvas_draw_path(ctx, shape, paint)
  Skia.sk_paint_delete(paint)
  Skia.sk_path_delete(shape)
end

"""
Show where the next corner snaps to: a square on a corner of the plan, a cross
where two of its lines cross, and a ring on a line.
"""
snap_mark(ctx, (x, y), kind) = begin
  r = 5.0
  # White under the colour, so that it shows on a dark part of the plan
  for (colour, wide) in ((colorant"white", 3.5), (colours.accent, 1.5))
    if kind == :corner
      trace(ctx, [(x - r, y - r), (x + r, y - r), (x + r, y + r), (x - r, y + r)], colour, wide, closed=true)
    elseif kind == :crossing
      trace(ctx, [(x - r, y - r), (x + r, y + r)], colour, wide)
      trace(ctx, [(x - r, y + r), (x + r, y - r)], colour, wide)
    else
      paint = ink(colour, wide)
      Skia.sk_canvas_draw_circle(ctx, Float32(x), Float32(y), Float32(r), paint)
      Skia.sk_paint_delete(paint)
    end
  end
end

"Draw a dot of radius `r` at the place `(x, y)`, with a white edge"
dot(ctx, (x, y), r, colour) = begin
  for (radius, c) in ((r + 1.5, colorant"white"), (r, colour))
    paint = ink(c)
    Skia.sk_canvas_draw_circle(ctx, Float32(x), Float32(y), Float32(radius), paint)
    Skia.sk_paint_delete(paint)
  end
end

"Write `words` in a small dark box beside the place `(x, y)`"
tag(ctx, (x, y), words) = begin
  isempty(words) && return
  face = Face(SANS, "Semibold", 11px, colorant"white", false)
  wide = num(measure(face, words))
  rounded_rectangle(ctx, px(x + 10), px(y - 22), px(wide + 12), 18px, 4px, background=RGBA(0.12, 0.12, 0.12, 0.85))
  paint = ink(colorant"white")
  blob = Skia.sk_textblob_make_from_string(words, skia_font(face.family, face.size, face.style).raw, Skia.SK_TEXT_ENCODING_UTF8)
  Skia.sk_canvas_draw_text_blob(ctx, blob, Float32(x + 16), Float32(y - 9), paint)
  Skia.sk_textblob_unref(blob)
  Skia.sk_paint_delete(paint)
end

"What a shape of this kind comes to in the unit `unit`, as the plan shows it beside the shape, or \"\" when its page has no scale"
size_text(v::TakeoffView, kind, shape, unit=Plans.own_unit(kind)) = begin
  a = Plans.amount(v.data, kind, shape)
  a === nothing ? "" : Plans.shown(kind, a, unit)
end

"""
What shape `j` of measure `m` comes to in the measure's unit, as the plan shows
it beside the shape: an outline without its cut-outs, and a cut-out as what it
takes away, with a minus. It's "" when its page has no scale.
"""
size_text(v::TakeoffView, m::Plans.Measure, j::Int) = begin
  a = Plans.amount(v.data, m, j)
  a === nothing ? "" : (m.shapes[j].cut ? "−" : "") * Plans.shown(m.kind, a, Plans.unit(m))
end

"""
What a cut-out with the corners `points` takes from the outline at the place
`from`, as the plan shows it while the cut-out is drawn. Over no outline, it
says so.
"""
cut_text(v::TakeoffView, from, points) = begin
  length(points) < 3 && return ""
  from === nothing && return "Not over an area"
  n = Plans.scale(v.data, v.data.page)
  n === nothing && return ""
  m = v.data.measures[from[1]]
  "−" * Plans.shown(:area, Plans.takes(m, from[2], points) * Plans.metres(n)^2, Plans.unit(m))
end

"Draw what's measured on the page that shows, and what's being drawn"
draw_shapes(ctx, v::TakeoffView) = begin
  t = v.data
  for (i, m) in enumerate(t.measures), (j, s) in enumerate(m.shapes)
    s.page == t.page || continue
    colour = hue(i)
    on = v.picked !== nothing && v.picked[1] == i && v.picked[2] == j
    ps = [window_point(v, p) for p in s.points]
    if m.kind == :count
      for (k, p) in enumerate(ps)
        dot(ctx, p, on && length(v.picked) == 3 && v.picked[3] == k ? 7.5 : 5, colour)
      end
      continue
    end
    area = m.kind == :area
    if s.cut
      # A cut-out is an outline of dashes. Its area's colour stops at it.
      trace(ctx, ps, colour, on ? 3 : 1.5, closed=true, dashed=true)
    else
      holes = area ? [[window_point(v, p) for p in m.shapes[k].points] for k in Plans.cuts(m, j)] : ()
      trace(ctx, ps, colour, on ? 4 : 2.5, fill=area ? RGBA(colour, 0.22) : nothing, closed=area, holes=holes)
    end
    # The corners show on the measure that the tools draw for, so that you can take hold of one
    (on || v.current == i) && foreach(p -> dot(ctx, p, on ? 4 : 3, colour), ps)
    on && tag(ctx, ps[end], size_text(v, m, j))
  end
  # Where the next corner goes, when it snaps to something
  marked = v.aim !== nothing && v.mouse !== nothing && v.asking === nothing && ishovered(part!(() -> PlanArea(of=v), v, :area))
  if isempty(v.draft)
    marked && snap_mark(ctx, window_point(v, v.mouse), v.aim)
    return
  end
  # What's being drawn runs on to the mouse
  cut = v.tool == :cut
  kind = cut ? :area : v.tool
  # With the mouse over the Done button, it shows what a click there leaves
  done = over_done(v)
  points = v.mouse === nothing || v.asking !== nothing || done ? copy(v.draft) : [v.draft; [v.mouse]]
  # A cut-out has the colour of the area that it's cut from
  from = cut ? Plans.cut_from(t, t.page, points, v.current) : nothing
  colour = kind == :scale ? colours.accent : cut ? (from === nothing ? colours.dim : hue(from[1])) :
           hue(v.current > 0 && t.measures[v.current].kind == kind ? v.current : length(t.measures) + 1)
  ps = [window_point(v, p) for p in points]
  closed = kind == :area && length(ps) > 2
  trace(ctx, ps, colour, 2, fill=closed && !cut ? RGBA(colour, 0.15) : nothing, closed=closed, dashed=cut)
  foreach(p -> dot(ctx, p, 3, colour), ps[1:length(v.draft)])
  # In the unit of the measure that it's for
  unit = v.current > 0 && t.measures[v.current].kind == kind ? Plans.unit(t.measures[v.current]) : Plans.own_unit(kind)
  kind == :scale || tag(ctx, ps[end], cut ? cut_text(v, from, points) : size_text(v, kind, Plans.Shape(t.page, points), unit))
  marked && !done && snap_mark(ctx, window_point(v, v.mouse), v.aim)
  draw_done(ctx, v, done)
end

# --- the button that ends a line or an outline -------------------------------------------
#
# While a length or an area is being drawn, a Done button shows beside its last
# corner, as soon as it has corners enough to end. A click on the button ends
# the line or the outline, as Return does, and puts no corner down. The button
# is behind the last corner and to one side of the line that led to it. The
# next corner is seldom put there, so the button is seldom in its way.

const DONE_W, DONE_H = 64.0, 24.0   # px. How wide and how tall the Done button is.
const DONE_GAP = 10.0               # px between the button and the line that led to the last corner

"""
Where the Done button is in the window: its left, its top, its width and its
height. It's nothing while there's no line or outline with corners enough to end.
"""
done_box(v::TakeoffView) = begin
  (v.tool in (:length, :area, :cut) && v.zoom > 0) || return nothing
  n = length(v.draft)
  n >= (v.tool == :length ? 2 : 3) || return nothing
  (x, y), (x0, y0) = window_point(v, v.draft[n]), window_point(v, v.draft[n-1])
  far = hypot(x - x0, y - y0)
  # The way the line went to its last corner
  ux, uy = far > 0 ? ((x - x0) / far, (y - y0) / far) : (1.0, 0.0)
  # The button's place on one side of the line. Its front is level with the corner, and its near edge is DONE_GAP from the line.
  place(nx, ny) = begin
    back = (abs(ux) * DONE_W + abs(uy) * DONE_H) / 2
    off = (abs(nx) * DONE_W + abs(ny) * DONE_H) / 2 + DONE_GAP
    (x - ux * back + nx * off - DONE_W / 2, y - uy * back + ny * off - DONE_H / 2)
  end
  left, top, wide, tall = v.box
  fits((bx, by)) = bx >= left && by >= top && bx + DONE_W <= left + wide && by + DONE_H <= top + tall
  # The side that's lower in the window, or the right one of two that are level. The other side if only that one is in the view.
  nx, ny = ux > 0 || (ux == 0 && uy < 0) ? (-uy, ux) : (uy, -ux)
  at = place(nx, ny)
  other = place(-nx, -ny)
  fits(at) || !fits(other) || (at = other)
  # A corner that's out of sight still has its button in sight
  (clamp(at[1], left, max(left, left + wide - DONE_W)), clamp(at[2], top, max(top, top + tall - DONE_H)), DONE_W, DONE_H)
end

"True when the place `(x, y)` of the window is on the Done button"
on_done(v::TakeoffView, x, y) = begin
  b = done_box(v)
  b !== nothing && b[1] <= x <= b[1] + b[3] && b[2] <= y <= b[2] + b[4]
end

"True when the mouse is over the Done button"
over_done(v::TakeoffView) = (w = window_of(v); w !== nothing && on_done(v, num(w.mouse[1]), num(w.mouse[2])))

"What the Done button's tooltip says"
done_tip(v::TakeoffView) = (v.tool == :length ? "End the line" : "End the outline") * "  Return"

"Draw the Done button. It's lighter while the mouse is over it."
draw_done(ctx, v::TakeoffView, over::Bool) = begin
  b = done_box(v)
  b === nothing && return
  size = (px(b[3]), px(b[4]))
  white = colorant"white"
  button = Box(fixed(size[1]), height(size[2]), radius(size[2] / 2), Alignment.Center, border(1.5px, :solid, white),
               background(over ? RGBA(0.3, 0.3, 0.3, 0.95) : RGBA(0.12, 0.12, 0.12, 0.9)),
               Row(Alignment.Center, child_gap=4px, Icon("check", size=12px, color=white), label("Done", 12px, color=white, weight="Semibold")))
  Skia.sk_canvas_save(ctx)
  Skia.sk_canvas_translate(ctx, Float32(b[1]), Float32(b[2]))
  draw(ctx, size, describe(button, size))
  Skia.sk_canvas_restore(ctx)
end

describe(a::PlanArea) = begin
  v = a.of
  # In the window, the plan takes all the room that the tools leave
  h = v.full ? height(grow=grow) : height(plan_h(v, editor(v).width - 2px))
  plan_size(v) === nothing || return Box(width(grow=grow), h, background(takeoff_back()))
  words = isempty(v.data.plan) ? "Drop a plan here, or click to choose one: a PDF file or a picture" :
                                 "$(v.data.plan) isn't a plan that Ladder can show. Click to choose another."
  Column(width(grow=grow), h, justify=Alignment.Center, child_gap=10px, background(colours.stripe),
    Icon("map", size=26px, color=colours.faint), Box(label(words, 13px, color=colours.dim)))
end

draw(ctx, size, ui::ConcreteRect, a::PlanArea) = begin
  v = a.of
  was = v.box
  v.box = (num(ui.left), num(ui.top), num(ui.width), num(ui.height))
  s = plan_size(v)
  s === nothing && return
  # A new file or a new page is shown whole
  shown = (plan_path(v), v.data.page)
  if v.zoom <= 0 || v.fitted != shown
    fit!(v, s)
    v.fitted = shown
  elseif was[3] > 0 && (was[3] != v.box[3] || was[4] != v.box[4])
    # The view changed its size, as it does when the window does, when it fills the window and on paper.
    # A view that showed the whole page still does. A view that was bigger shows the same part of the plan.
    if v.zoom <= 1.0001min(was[3] / s[1], was[4] / s[2])
      fit!(v, s)
    else
      middle = (v.at[1] + was[3] / 2v.zoom, v.at[2] + was[4] / 2v.zoom)
      v.zoom = max(v.zoom * v.box[3] / was[3], fit_zoom(v, s))
      v.at = (middle[1] - v.box[3] / 2v.zoom, middle[2] - v.box[4] / 2v.zoom)
      hold!(v, s)
    end
  end
  lookup!(v)
  with_clip(ctx, ui.left, ui.top, ui.width, ui.height) do
    draw_plan(ctx, v, s)
    draw_shapes(ctx, v)
  end
end

"""
True when the mouse is over something on the plan that a click selects: a
mark, a line, an outline or the inside of one. The window asks for the cursor
before the plan sees the mouse move, so this reads where the window's mouse is.
"""
over_shape(v::TakeoffView) = begin
  w = window_of(v)
  (w === nothing || v.zoom <= 0) && return false
  p = page_point(v, num(w.mouse[1]), num(w.mouse[2]))
  Plans.shape(v.data, v.data.page, p, REACH / v.zoom) !== nothing
end

# With the select tool, a hand over something that a click selects, and an arrow over the paper
cursor(a::PlanArea) = begin
  v = a.of
  plan_size(v) === nothing || over_done(v) ? :hand : v.tool == :select ? (v.grab !== nothing || over_shape(v) ? :hand : :arrow) : :crosshair
end

# --- the mouse and the keys on the plan --------------------------------------------------

"The name that a new measure of this kind starts with: Count 1, Length 2"
first_name(v::TakeoffView, kind) = "$(uppercasefirst(string(kind))) $(count(m -> m.kind == kind, v.data.measures) + 1)"
const FIRST_NAME = r"^(Count|Length|Area) \d+$"
const KIND_WORDS = Dict(:count => "a count", :length => "a length", :area => "an area")

"What an item's price is for, in words: each one, each m, each m²"
sold_by(row) = begin
  unit = string(something(get(row, "unit", nothing), ""))
  unit in ("", "Piece", "each") ? "each one" : "each " * unit
end

"Make a measure that has nothing drawn yet one of `kind`. A name that it was made with follows its kind."
kind!(v::TakeoffView, m, kind::Symbol) = begin
  (m.kind == kind || !isempty(m.shapes)) && return m
  occursin(FIRST_NAME, m.name) && (m.name = first_name(v, kind))
  m.kind = kind
  m.unit = ""
  m
end

"The measure of this kind that the tools draw for. If the current measure is of another kind, a new one starts."
measure!(v::TakeoffView, kind::Symbol) = begin
  ms = v.data.measures
  1 <= v.current <= length(ms) && ms[v.current].kind == kind && return ms[v.current]
  push!(ms, Plans.Measure(kind, first_name(v, kind)))
  v.current = length(ms)
  last(ms)
end

"What the foot of the block says when a cut-out is drawn where there's no area to cut it from"
const CUT_NOWHERE = "A cut-out goes over an area that's measured. Measure the area first, then cut the shape out of it."

"""
End the line or the outline that's being drawn. One with too few corners is
dropped. A cut-out goes to the area that it's over, and one that's over none is
dropped too.
"""
finish_shape!(v::TakeoffView) = begin
  kind = v.tool
  if kind == :cut && length(v.draft) >= 3
    made = Plans.cut!(v.data, v.data.page, copy(v.draft), v.current)
    empty!(v.draft)
    if made === nothing
      say!(v, CUT_NOWHERE, true)
    else
      v.current = made[1]
      v.said == CUT_NOWHERE && say!(v, "")
      commit!(v)
    end
  elseif kind in (:length, :area) && length(v.draft) >= (kind == :length ? 2 : 3)
    push!(measure!(v, kind).shapes, Plans.Shape(v.data.page, copy(v.draft)))
    empty!(v.draft)
    commit!(v)
  end
  empty!(v.draft)
  handled
end

"""
Choose a tool. A tool that measures draws for the measure that's chosen in the
list. If that measure is of another kind, it becomes the tool's kind when
nothing is drawn for it yet and it has no item. If not, the tool draws for the
last measure of its kind.
"""
tool!(v::TakeoffView, tool::Symbol) = begin
  v.tool = tool
  empty!(v.draft)
  v.picked = nothing
  ms = v.data.measures
  if tool in Plans.KINDS && !(1 <= v.current <= length(ms) && ms[v.current].kind == tool)
    m = 1 <= v.current <= length(ms) ? ms[v.current] : nothing
    if m !== nothing && isempty(m.shapes) && isempty(m.item)
      kind!(v, m, tool)
      commit!(v)
    else
      v.current = something(findlast(m -> m.kind == tool, ms), 0)
    end
  end
  handled
end

"A drag ended. A corner that moved is written down."
drop!(v::TakeoffView) = begin
  g = v.grab
  v.grab = nothing
  g !== nothing && g[1] == :corner && g[3] && commit!(v)
  v
end

"Take away what's selected on the plan: a mark, a corner, or a whole line or outline"
remove_picked!(v::TakeoffView) = begin
  p = v.picked
  p === nothing && return handled
  m = v.data.measures[p[1]]
  # An outline takes its cut-outs with it
  length(p) == 3 ? Plans.remove!(m, p[2], p[3]) : Plans.remove!(m, p[2])
  v.picked = nothing
  commit!(v)
  handled
end

onkey(a::PlanArea, ev::KeyPress{Keys.mouse_left}) = begin
  v, w = a.of, ev.window
  focus(a)
  plan_size(v) === nothing && return choose_plan!(v, w)
  v.zoom > 0 || return handled
  x, y = num(w.mouse[1]), num(w.mouse[2])
  # A click on the Done button ends what's being drawn, and puts no corner down
  on_done(v, x, y) && return (hide_tooltip!(w); finish_shape!(v))
  p = page_point(v, x, y)
  at, cx, cy = v.clicked
  twice = time() - at < 0.35 && hypot(x - cx, y - cy) < 4
  v.clicked = (time(), x, y)
  reach = REACH / v.zoom
  page = v.data.page
  if v.tool == :count
    Plans.mark!(measure!(v, :count), page, p)
    commit!(v)
  elseif v.tool in (:length, :area, :cut)
    closes = v.tool != :length && length(v.draft) >= 3 && hypot(v.draft[1][1] - p[1], v.draft[1][2] - p[2]) <= reach
    # The first click of two put the last corner down. A corner snaps to the plan's lines.
    (twice && !isempty(v.draft)) || closes ? finish_shape!(v) : push!(v.draft, aim(v, w, x, y)[1])
  elseif v.tool == :scale
    length(v.draft) >= 2 && empty!(v.draft)
    push!(v.draft, aim(v, w, x, y)[1])
    length(v.draft) == 2 && ask!(v, (:length, v.draft[1], v.draft[2]), "", "metres")
  else
    corner = Plans.corner(v.data, page, p, reach)
    if corner !== nothing
      v.picked, v.current = corner, corner[1]
      v.grab = (:corner, corner, false)
    else
      v.picked = Plans.shape(v.data, page, p, reach)
      v.picked === nothing || (v.current = v.picked[1])
      v.grab = (:pan, (x, y), v.at)
    end
  end
  handled
end

# A right-click ends what's being drawn
onkey(a::PlanArea, ::KeyPress{Keys.mouse_right}) = isempty(a.of.draft) ? nothing : finish_shape!(a.of)

onmouse(a::PlanArea, ev::MouseMove) = begin
  v = a.of
  v.zoom > 0 || return nothing
  x, y = num(ev.position[1]), num(ev.position[2])
  g = v.grab
  # A corner that a tool is about to put down snaps to the plan's lines, and so does one that's dragged. A mark of a count doesn't.
  drawing = g === nothing && v.tool in (:length, :area, :cut, :scale) && !on_done(v, x, y)
  dragged = g !== nothing && g[1] == :corner && v.data.measures[g[2][1]].kind != :count
  v.mouse, v.aim = drawing ? aim(v, ev.window, x, y) : dragged ? aim(v, ev.window, x, y, skip=g[2]) : (page_point(v, x, y), nothing)
  # The Done button says what it does, and the key that does the same
  on_done(v, x, y) && show_tooltip!(ev.window, tip_label(done_tip(v)), px.(done_box(v))..., placement=:bottom, gap=6px)
  g === nothing && return handled
  Keys.mouse_left in ev.window.keys || (drop!(v); return handled)
  if g[1] == :pan
    (x0, y0), at = g[2], g[3]
    v.at = (at[1] - (x - x0) / v.zoom, at[2] - (y - y0) / v.zoom)
    moved!(v)
  else
    i, j, k = g[2]
    v.data.measures[i].shapes[j].points[k] = v.mouse
    v.grab = (:corner, g[2], true)
  end
  handled   # the drag is the plan's, so the page's text doesn't select
end

# A mouse wheel makes the plan bigger or smaller, round the mouse, like a map. Two fingers on the trackpad move
# the plan, and a pinch makes it bigger or smaller. With ⌘ held, both make it bigger or smaller.
# A plan in the page takes them once a click has given it the keyboard, or while ⌘ is held. Before that, they
# move the page that the plan is on, so that the page can scroll past it. A plan that fills the window has no page.
onscroll(a::PlanArea, ev::MouseScroll) = begin
  v, w = a.of, ev.window
  v.zoom > 0 || return nothing
  cmd = only_held(w, Keys.cmd)
  (cmd || w.focus === a || v.full) || return nothing
  (cmd || ev.wheel) && return zoom_plan!(v, exp(num(ev.delta[2]) / 10), num(w.mouse[1]), num(w.mouse[2]))
  v.at = (v.at[1] - 30num(ev.delta[1]) / v.zoom, v.at[2] - 30num(ev.delta[2]) / v.zoom)
  moved!(v)
  handled
end

# Two fingers that move apart or together on the trackpad make the plan bigger or smaller, round the mouse
onpinch(a::PlanArea, ev::Pinch) = begin
  v, w = a.of, ev.window
  v.zoom > 0 || return nothing
  zoom_plan!(v, ev.scale, num(w.mouse[1]), num(w.mouse[2]))
end

onkey(a::PlanArea, ev::KeyPress{Keys.enter}) = unmodified(ev) ? finish_shape!(a.of) : nothing
onkey(a::PlanArea, ev::KeyPress{Keys.escape}) = begin
  unmodified(ev) || return nothing
  v = a.of
  # Esc drops what's half drawn, then puts the arrow back, then puts a takeoff that fills the window
  # back in the page, then gives the keyboard back to the text
  isempty(v.draft) || return (empty!(v.draft); handled)
  v.tool == :select ? (v.full ? full!(v, false) : nothing) : tool!(v, :select)
end
onkey(a::PlanArea, ::KeyPress{K}) where K = begin
  v = a.of
  if K in (Keys.backspace, Keys.delete) && unmodified(window_of(a))
    # While something is being drawn, Delete takes its last corner back
    return isempty(v.draft) ? remove_picked!(v) : (pop!(v.draft); handled)
  elseif (command = command_of(editor(v), window_of(a), K)) in (:undo, :redo)
    b = editor(v).buf
    command == :redo ? redo!(b) : undo!(b)
    return handled
  end
  nothing
end

ontype(a::PlanArea, ev::Typed) = begin
  # A letter picks a tool by itself, or with ⇧
  (unmodified(ev) || only_held(ev, Keys.shft)) || return nothing
  i = findfirst(((_, (_, _, letter)),) -> letter == lowercase(ev.char), PLAN_TOOLS)
  i === nothing ? nothing : tool!(a.of, PLAN_TOOLS[i][1])
end

# --- the buttons -------------------------------------------------------------------------

"The button of `v` that's kept under `key`, with what it does and shows now"
button!(v::TakeoffView, key, action; icon="", words="", tip="", off=false) = begin
  b = part!(() -> PlanButton(of=v), v, (:button, key))
  b.action, b.icon, b.words, b.tip, b.off = action, icon, words, tip, off
  b
end

describe(b::PlanButton) = begin
  v = b.of
  ishovered(b) || (b.quiet = false)
  # The tool in use is lit, and so is the magnet while corners snap
  on = (b.action isa Tuple && b.action[1] == :tool && v.tool == b.action[2]) || (b.action == :snap && v.snap)
  colour = b.off ? colours.faint : on ? colours.accent : colours.dim
  Box(height(26px), padding(7px, 0px), radius(6px), Alignment.Center, name="Button",
      background(on ? colours.active : ishovered(b) && !b.off ? colours.hover : clear),
    Row(Alignment.Center, child_gap=5px,
      (isempty(b.icon) ? () : (Icon(b.icon, size=14px, color=colour),))...,
      (isempty(b.words) ? () : (label(b.words, 12px, color=b.off ? colours.faint : colours.ink),))...))
end

cursor(b::PlanButton) = b.off ? :arrow : :hand

draw(ctx, size, ui::ConcreteRect, b::PlanButton) = (b.rect = (ui.left, ui.top, ui.width, ui.height); nothing)

onmouse(b::PlanButton, ev::MouseMove) = begin
  (b.quiet || isempty(b.tip)) && return
  show_tooltip!(ev.window, tip_label(b.tip), b.rect..., placement=:bottom, gap=6px)
end

onkey(b::PlanButton, ev::KeyPress{Keys.mouse_left}) = begin
  b.quiet = true
  hide_tooltip!(ev.window)
  b.off ? handled : act!(b.of, b.action, ev.window)
end

"Make the takeoff fill the window, or put it back in the page"
full!(v::TakeoffView, on::Bool) = begin
  e = editor(v)
  on && unfill!(e)   # one block at a time fills the window
  v.full = on
  v.pinned = e.scroll.offset
  focus(part!(() -> PlanArea(of=v), v, :area))
  handled
end

"The takeoff of the page that fills the window, or nothing"
full_takeoff(e) = begin
  for (key, node) in e.nodes
    node isa TakeoffView && node.full && key[2] == e.buf.path && return node
  end
  nothing
end

"""
True for a kind of view that can fill the window, over the page: a takeoff, a
schedule and a sketch. Such a view has the fields `full`, `tall`, which is how
tall it was in the page, and `pinned`, which is how far the page was scrolled.
"""
can_fill(v) = hasfield(typeof(v), :full) && hasfield(typeof(v), :pinned)
"True for a view that fills the window now"
filling(v) = can_fill(v) && v.full

"Put the block that fills the window back in the page"
unfill!(e) = foreach(node -> filling(node) && (node.full = false), values(e.nodes))

"The takeoff, the schedule or the sketch of the page that fills the window, or nothing"
full_block(e) = begin
  for (key, node) in e.nodes
    filling(node) || continue
    # A view is kept under its page: the second part of the key of a takeoff and a schedule, and the third of another block
    (key[1] == :block ? key[3] : key[2]) == e.buf.path && return node
  end
  nothing
end

"The takeoff, the schedule or the sketch that fills the window, over the page and the sidebar and under the top bar"
takeoff_over(e) = begin
  v = full_block(e)
  v === nothing ? () : (Box(width(grow=grow), height(grow=grow), padding(TOPBAR_H, 0px, 0px, 0px), background(colours.bg), geometry(v)),)
end

"Do what a button of a takeoff does"
act!(v::TakeoffView, action, w) = begin
  settle_asking!(v)
  a = action isa Tuple ? action[1] : action
  t = v.data
  if a == :tool
    tool!(v, action[2])
  elseif a == :page
    page!(v, action[2])
  elseif a == :zoom
    zoom_plan!(v, action[2], v.box[1] + v.box[3] / 2, v.box[2] + v.box[4] / 2)
  elseif a == :fit
    v.zoom = 0.0
  elseif a == :snap
    v.snap = !v.snap
    v.aim = nothing
  elseif a == :full
    full!(v, !v.full)
  elseif a == :scale
    s = Plans.scale(t, t.page)
    ask!(v, (:scale,), s === nothing ? "1:100" : Plans.scale_text(s))
  elseif a == :choose
    choose_plan!(v, w)
  elseif a in (:add, :add_item)
    # It starts as what the tool in use measures, or as a count. Its item's unit, or the next tool, can change that.
    kind = v.tool in Plans.KINDS ? v.tool : :count
    empty!(v.filters)   # a search of the table could hide the new measure
    push!(t.measures, Plans.Measure(kind, first_name(v, kind)))
    v.current = length(t.measures)
    tool!(v, kind)
    commit!(v)
    # A measure from the catalogue asks for its item: it takes the item's name, and the item's unit says what it is.
    # Another asks for the words that describe it. Typing takes the place of the name that it was made with.
    a == :add_item ? ask!(v, (:item, v.current)) : ask!(v, (:name, v.current), last(t.measures).name, "What it measures")
  elseif a == :delete && action[2] <= length(t.measures)
    deleteat!(t.measures, action[2])
    v.current = v.current == action[2] ? 0 : v.current > action[2] ? v.current - 1 : v.current
    v.picked = nothing
    commit!(v)
  elseif a == :customer
    Centient.available() ? ask!(v, (:customer,), "", "Search Centient's contacts") :
                           ask!(v, (:customer,), t.customer, "The customer's name")
  elseif a == :quote
    make_quote!(v)
  end
  handled
end

# --- the list of measures ----------------------------------------------------------------

"The text field in a box, where the thing that it changes was"
field(v::TakeoffView, wide=width(grow=grow)) =
  Box(wide, height(24px), padding(6px, 0px), radius(5px), border(1px, :solid, colours.accent), background(colours.bg), plan_input(v))

"The mark beside a measure's name, in its colour: a dot for a count, a line for a length, a square for an area"
swatch(kind::Symbol, colour) =
  Box(width(14px), height(14px), Alignment.Center,
    kind == :count ? Box(width(10px), height(10px), radius(5px), background(colour)) :
    kind == :length ? Box(width(14px), height(3px), radius(1.5px), background(colour)) :
                      Box(width(11px), height(11px), radius(2px), background(RGBA(colour, 0.3)), border(1.5px, :solid, colour)))

"A price as a row of the list shows it: \$22.00 / m, or \$5.97 each"
price_text(row) = begin
  unit = string(something(get(row, "unit", nothing), ""))
  dollars(row["price"]) * (unit in ("", "Piece", "each") ? " each" : " / " * unit)
end

"""
`s` cut short with … so that it's no wider than `wide` at `size`. It's all of
`s` when it fits, and when there's no width to fit it to yet.
"""
elide(s::AbstractString, size, wide) = begin
  face = Face(SANS, "", size, colours.ink, false)
  (wide <= 0px || measure(face, s) <= wide) && return String(s)
  # The most letters that fit with the … after them
  cs = collect(s)
  lo, hi = 0, length(cs)
  while lo < hi
    mid = (lo + hi + 1) ÷ 2
    measure(face, rstrip(String(cs[1:mid])) * "…") <= wide ? (lo = mid) : (hi = mid - 1)
  end
  rstrip(String(cs[1:lo])) * "…"
end

"""
What the table calls measure `m`. With an item that Centient has told of, it's
the item's name. With no item, it's the words that describe the measure, which
are its name in the block.
"""
item_name(v::TakeoffView, m) = begin
  row = known(v, m.item)
  row === nothing ? (isempty(m.name) ? m.item : m.name) : string(row["name"])
end

"The words `shown`, which start the words of `parts` and may end with …, as a text for each part in its colour"
runs(shown::AbstractString, parts) = begin
  cs, at, out = collect(shown), 0, Any[]
  for (s, colour) in parts
    n = min(length(s), length(cs) - at)
    n > 0 || break
    push!(out, label(String(cs[at+1:at+n]), 13px, color=colour))
    at += n
  end
  out
end

describe(c::MeasureCell) = begin
  v, i = c.of, c.i
  i <= length(v.data.measures) || return Box(width(0px))
  m = v.data.measures[i]
  wide = c.what == :extra ? fixed(52px) : width(grow=grow)
  c.full = ""
  # The item's cell holds the field for the item, and the field for the words of a measure with none
  a = v.asking
  a !== nothing && a[1] in (c.what == :item ? (:item, :name) : (:extra,)) && a[2] == i && return field(v, wide)
  # The words are in a row with no width of its own, so long words take no room from the cells beside them.
  # They're cut short with … to fit the width the cell had when it was last drawn. Each of `parts` is words and their colour.
  words(parts...) = begin
    s = join(first.(parts))
    shown = elide(s, 13px, c.rect[3])
    shown == s || (c.full = s)
    Row(wide, height(grow=grow), Alignment.Center, clip=true, Row(fixed(0px), runs(shown, parts)...))
  end
  c.what == :extra && return words((m.extra > 0 ? "+" * Plans.number(100m.extra) * "%" : "+0%", m.extra > 0 ? colours.ink : colours.faint))
  name, row = item_name(v, m), known(v, m.item)
  # An item that Centient knows shows where it's from after its name
  row === nothing ? words((name, colours.ink)) : words((name, colours.ink), ("  ·  " * string(row["source"]), colours.dim))
end

cursor(::MeasureCell) = :hand

draw(ctx, size, ui::ConcreteRect, c::MeasureCell) = begin
  # A new width cuts the words short in another place, so the cell is described again
  ui.width == c.rect[3] || redraw_in!(c.of, 0)
  c.rect = (ui.left, ui.top, ui.width, ui.height)
  nothing
end

# Words that are cut short show whole under the cell
onmouse(c::MeasureCell, ev::MouseMove) = isempty(c.full) ? nothing :
  show_tooltip!(ev.window, tip_label(c.full), c.rect..., placement=:bottom, gap=6px)

onkey(c::MeasureCell, ::KeyPress{Keys.mouse_left}) = begin
  v, i = c.of, c.i
  i <= length(v.data.measures) || return handled
  m = v.data.measures[i]
  # The first click on a row chooses it. A click on the row that's chosen changes the part that's clicked.
  chosen = v.current == i
  chosen || choose_measure!(v, i)
  chosen || return handled
  c.what == :extra && return ask!(v, (:extra, i), m.extra > 0 ? Plans.number(100m.extra) : "", "%")
  # A measure from the catalogue chooses another item. One with no item changes the words that describe it.
  isempty(m.item) || !Centient.available() ? ask!(v, (:name, i), m.name, "What it measures") : ask!(v, (:item, i))
end

describe(r::MeasureRow) = begin
  v, i = r.of, r.i
  i <= length(v.data.measures) || return Box(height(0px))
  m = v.data.measures[i]
  cell(what) = part!(() -> MeasureCell(of=v, i=i, what=what), v, (:cell, i, what))
  amount = Plans.amount(v.data, m)
  row = known(v, m.item)
  # A Text on its own would take all of the row, so each is in a box that the row puts at its right
  # It's as tall as the row, so that what cuts a long text off at the side doesn't cut the tail of a comma or a g
  right(wide, s, colour) = Row(fixed(wide), height(grow=grow), Alignment.Center, justify=Alignment.End, clip=true, Box(label(s, 13px, color=colour)))
  back = background(v.current == i ? colours.active : ishovered(r) ? colours.hover : clear)
  # The first row has a line that doesn't show, so that its words are where the other rows' are
  line = (border(1px, :solid, !isempty(v.order) && v.order[1] == i ? clear : colours.line)[:top],)
  size = part!(() -> AmountCell(of=v, i=i), v, (:amount, i))
  cost = right(88px, row === nothing || amount === nothing ? "" : dollars(cost_of(m, amount, row)), colours.ink)
  remove = button!(v, (:delete, i), (:delete, i), icon="x-lg", tip="Remove this measure")
  # The panel beside a plan that fills the window is narrow, so a measure has two lines there
  # The cost and the price have columns only while a measure has an item to price it
  costs = has_items(v) ? (cost,) : ()
  v.beside && return Column(width(grow=grow), Alignment.Start, padding(10px, 4px), name="Measure", back, line...,
    Row(width(grow=grow), height(26px), child_gap=8px, Alignment.Center, swatch(m.kind, hue(i)), cell(:item), size),
    Row(width(grow=grow), height(26px), child_gap=8px, Alignment.Center, Box(width(14px)), cell(:extra), Box(width(grow=grow)), costs..., remove))
  Row(width(grow=grow), height(32px), padding(10px, 0px), child_gap=10px, Alignment.Center, name="Measure", back, line...,
    swatch(m.kind, hue(i)), cell(:item), cell(:extra), size,
    # A narrow block has no room for the price of one, so it shows what the measure comes to and no more
    # The price is for one of the measure's unit, so it needs no unit after it. One that the measure can't be in says its own.
    (has_price(v) ? (right(96px, row === nothing ? "" : (p = unit_price(m, row); p === nothing ? price_text(row) : dollars(p)), colours.dim),) : ())...,
    costs..., remove)
end

cursor(::MeasureRow) = :hand

"Make measure `i` the one that the tools draw for, and choose the tool of its kind"
choose_measure!(v::TakeoffView, i::Int) = begin
  i <= length(v.data.measures) || return handled
  v.current = i
  tool!(v, v.data.measures[i].kind)
end

onkey(r::MeasureRow, ::KeyPress{Keys.mouse_left}) = choose_measure!(r.of, r.i)

# --- the units of a measure --------------------------------------------------------------
#
# A click on the unit after a measure's amount shows the list of units that it
# can be in, as Centient's unit picker does: each unit's name, and the short
# form that goes after an amount at the right. A field at the top of the list
# searches it. The up and down arrows pick a unit, and so does the mouse. Return or a
# click takes it. Esc, or a click somewhere else, closes the list and changes
# nothing.

const UNIT_KEY = :takeoff_units
const AMOUNT_W = 96px    # how wide the column of amounts is
const MOST_UNITS = 8     # the units that the list shows before it scrolls

"""
The units that measure `i` can be in. One with nothing drawn and no item can be
a count, a length or an area, so it can take a unit of each kind. Any other
keeps its kind.
"""
units_for(v::TakeoffView, i::Int) = begin
  i <= length(v.data.measures) || return String[]
  m = v.data.measures[i]
  isempty(m.shapes) && isempty(m.item) ? reduce(vcat, collect(Plans.KIND_UNITS)) : copy(getfield(Plans.KIND_UNITS, m.kind))
end

"Write a unit as a keyboard can: m^2 or m2 for m². What's typed is folded the other way, so that each finds the other."
fold_unit(s::AbstractString) = begin
  s = replace(lowercase(s), "^2" => "²", "^3" => "³")
  replace(s, r"([a-z]+)([23])(?!\d)" => m -> m[1:end-1] * (m[end] == '2' ? "²" : "³"))
end

"Other words that a unit is typed as"
const UNIT_EXTRAS = Dict("hectare" => ["ha", "hectares"], "ft" => ["feet"], "inch" => ["in", "inches"],
                         "ft²" => ["sq ft", "square feet"], "m" => ["meter"], "m²" => ["sqm", "square meter"], "Piece" => ["each"])

"True when `words` find `unit`: they're in its name, its short form, or the name that Centient gives it"
unit_matches(unit::AbstractString, words::AbstractString) = begin
  isempty(words) && return true
  q = fold_unit(words)
  any(h -> occursin(q, fold_unit(h)), [Plans.UNIT_WORDS[unit], Plans.unit_short(unit), unit, get(UNIT_EXTRAS, unit, String[])...])
end

"True when `words` are a name of `unit` and not only part of one: metre for m, and not for mm"
names_unit(unit::AbstractString, words::AbstractString) =
  (q = fold_unit(words); any(h -> fold_unit(h) == q, [Plans.UNIT_WORDS[unit], Plans.unit_short(unit), unit, get(UNIT_EXTRAS, unit, String[])...]))

"The unit word of the amount `c`. It belongs to the amount, so the mouse over it is over the amount too."
unit_word(c::AmountCell) = begin
  c.unit === nothing && (c.unit = UnitWord(of=c); setfield!(c.unit, :parent, c))
  c.unit
end

describe(c::AmountCell) = begin
  v, i = c.of, c.i
  i <= length(v.data.measures) || return Box(width(0px))
  m = v.data.measures[i]
  amount = Plans.amount(v.data, m)
  # It's as tall as the row, so that what cuts a long amount off at the side doesn't cut the tail of a comma or a g
  cell(parts...) = Row(fixed(AMOUNT_W), height(grow=grow), Alignment.Center, justify=Alignment.End, clip=true, name="Amount", parts...)
  amount === nothing && return cell(Box(label("No scale", 13px, color=colours.accent)))
  unit = Plans.unit(m)
  number = Box(label(Plans.amount_number(Plans.in_unit(amount, unit)), 13px, color=colours.ink))
  # The unit is there to click when the measure can be in another. A count that can only be in pieces is a number.
  length(units_for(v, i)) > 1 ? cell(number, unit_word(c)) : cell(Box(label(Plans.shown(m, amount), 13px, color=colours.ink)))
end

cursor(::AmountCell) = :hand
# A click on the number chooses the measure, as a click on the rest of its row does
onkey(c::AmountCell, ::KeyPress{Keys.mouse_left}) = choose_measure!(c.of, c.i)

describe(w::UnitWord) = begin
  c = w.of
  v = c.of
  c.i <= length(v.data.measures) || return Box(width(0px))
  unit = Plans.unit(v.data.measures[c.i])
  lit = ishovered(w) || v.asking == (:unit, c.i)
  # A foot and an inch are marks right after the number. Another unit has a space before it, and the space is the unit's to click.
  Row(height(grow=grow), padding(0px, 0px, 0px, unit in ("inch", "ft") ? 1px : 4px), Alignment.Center,
    label(Plans.unit_short(unit), 13px, color=lit ? colours.accent : colours.ink))
end

cursor(::UnitWord) = :hand
onkey(w::UnitWord, ev::KeyPress{Keys.mouse_left}) = open_units!(w.of, ev.window)

"Show the list of the units that the measure of the amount `c` can be in, under its unit"
open_units!(c::AmountCell, window) = begin
  v, i = c.of, c.i
  i <= length(v.data.measures) || return handled
  ask!(v, (:unit, i), "", "Filter…")
  v.query = ""   # so that the first frame keeps the unit that's picked
  v.rows = Any[units_for(v, i)...]
  v.pick = something(findfirst(==(Plans.unit(v.data.measures[i])), v.rows), 1)
  menu = UnitMenu(of=v, i=i)
  v.parts[:unit_menu] = menu
  popup!(window, menu, anchor=unit_word(c), placement=:bottom, gap=9px, width=230px, key=UNIT_KEY,
         onclose=() -> settle_asking!(v), theme=component_theme(editor(v).zoom))
  handled
end

"""
Put measure `i` in `unit`. A unit of another kind makes a measure with nothing
drawn and no item that kind. The tool for it is ready to draw.
"""
unit!(v::TakeoffView, i::Int, unit::AbstractString) = begin
  stop_asking!(v)
  i <= length(v.data.measures) || return handled
  m = v.data.measures[i]
  kind = Plans.unit_kind(unit)
  kind === nothing && return handled
  if kind != m.kind
    (isempty(m.shapes) && isempty(m.item)) || return handled
    kind!(v, m, kind)
  end
  Plans.unit!(m, unit)
  commit!(v)
  v.current = i
  tool!(v, m.kind)
end

# The list of units and the lists at the top of a `find` block are one kind of
# list. These three draw it: the box with the field at its top, a row of it, and
# the words that take the place of its rows when nothing matches.

const FLOAT_ROW = 28px   # how tall a row of such a list is

"""
A list that floats beside what it's for, with a field at its top that searches
it. `input` is the field, or nothing for a list with no field, and `body` is
the rows under it.
"""
float_list(input, body; name="List") = begin
  c = found_colours()
  field = input === nothing ? () :
    (Box(width(grow=grow), padding(2px, 2px),
       Box(width(grow=grow), height(28px), padding(8px, 0px), radius(6px), border(1px, :solid, c.line), background(c.frame), input)),)
  Box(width(grow=grow), padding(6px), radius(8px), background(c.frame), border(1px, :solid, c.line),
      shadow(0, 6, 16, RGBA(60 / 255, 45 / 255, 20 / 255, 0.2)), name=name,
    Column(width(grow=grow), Alignment.Start, child_gap=4px, field..., body))
end

"""
A row of such a list. `picked` is the row that Return takes, and `on` is the
one that's chosen now, which is in bold. `short` is a word at its right.
"""
float_row(name, short=""; picked=false, on=false) = begin
  c = found_colours()
  Row(width(grow=grow), height(FLOAT_ROW), padding(8px, 0px), radius(6px), child_gap=8px, Alignment.Center,
      background(picked ? c.pick : c.frame),
    Row(width(grow=grow), height(grow=grow), Alignment.Center, clip=true, label(name, 13px, color=c.ink, weight=on ? "Semibold" : "")),
    (isempty(short) ? () : (Box(label(short, 12px, color=c.dim)),))...)
end

"What such a list says in place of its rows when nothing in it matches"
float_none(words) = Row(width(grow=grow), height(FLOAT_ROW), padding(8px, 0px), Alignment.Center, label(words, 12px, color=found_colours().dim))

describe(r::UnitRow) = begin
  v = r.of
  r.k <= length(v.rows) || return Box(height(0px))
  unit = v.rows[r.k]
  a = v.asking
  on = a !== nothing && a[1] == :unit && a[2] <= length(v.data.measures) && Plans.unit(v.data.measures[a[2]]) == unit
  short = Plans.unit_short(unit)
  name = Plans.UNIT_WORDS[unit]
  # The short form shows when it isn't the name again
  float_row(name, lowercase(short) == lowercase(name) ? "" : short, picked=v.pick == r.k, on=on)
end

cursor(::UnitRow) = :hand
onkey(r::UnitRow, ::KeyPress{Keys.mouse_left}) = begin
  v, a = r.of, r.of.asking
  a !== nothing && a[1] == :unit && r.k <= length(v.rows) ? unit!(v, a[2], v.rows[r.k]) : handled
end
# The mouse picks the unit that it's over, as the arrow keys do
onmouse(r::UnitRow, ::MouseMove) = begin
  v = r.of
  v.pick = r.k
  menu = get(v.parts, :unit_menu, nothing)
  menu === nothing || (menu.pick = r.k)   # it's in sight already, so the list doesn't scroll to it
  handled
end

describe(m::UnitMenu) = begin
  v = m.of
  n, high = length(v.rows), FLOAT_ROW
  scroll = get!(() -> Scroll(width(grow=grow)), v.parts, :unit_scroll)
  body = if n == 0
    float_none("No unit has that name")
  else
    # Half a row at the bottom says that the list goes on
    scroll.height = height(n <= MOST_UNITS ? n * high : MOST_UNITS * high - high / 2)
    m.pick == v.pick || (m.pick = v.pick; scroll_into_view!(scroll, high * (v.pick - 1), high * v.pick))
    reuse!(scroll, Column(width(grow=grow), Alignment.Start, [part!(() -> UnitRow(of=v, k=k), v, (:unit_row, k)) for k in 1:n]...))
  end
  float_list(plan_input(v), body, name="Units")
end

placed!(m::UnitMenu, side) = (m.side = side; nothing)
draw(ctx, size, ui::ConcreteRect, m::UnitMenu) = caret(ctx, ui, m.side, rect(unit_word(part!(() -> AmountCell(of=m.of, i=m.i), m.of, (:amount, m.i)))))

# The list sees a key before its field does. The arrows pick a unit, Return takes it, and Esc closes the list.
onkey(m::UnitMenu, ev::KeyPress{Keys.enter}) = unmodified(ev) ? answer!(m.of) : nothing
onkey(m::UnitMenu, ev::KeyPress{Keys.escape}) = unmodified(ev) ? stop_asking!(m.of) : nothing
onkey(m::UnitMenu, ev::KeyPress{Keys.down}) = unmodified(ev) ? (v = m.of; v.pick = min(v.pick + 1, max(1, length(v.rows))); handled) : nothing
onkey(m::UnitMenu, ev::KeyPress{Keys.up}) = unmodified(ev) ? (v = m.of; v.pick = max(v.pick - 1, 1); handled) : nothing

# --- the list that a search shows --------------------------------------------------------
#
# What a search finds shows in a list that floats beside the text field. It
# looks like the lists in Centient's own forms: a cream box with an arrow that
# points at the field, and in it a card with a line for each thing found. The
# up and down arrows pick a line, and so does the mouse. Return or a click
# takes it. Esc closes the list, and so does a click somewhere else.

const FOUND_KEY = :takeoff_found
"The colours of the list: Centient's cream in a light page, and the page's own in a dark one"
found_colours() = dark_page() ?
  (frame=colours.float, pick=colours.active, ink=colours.ink, dim=colours.dim, line=colorant"rgb(86,86,94)", rule=colours.line) :
  (frame=colorant"rgb(233,224,202)", pick=colorant"rgb(224,212,185)", ink=colorant"rgb(27,23,16)", dim=colorant"rgb(110,104,88)",
   line=colorant"rgb(176,164,136)", rule=colorant"rgb(221,212,192)")

# The search for an item looks in one catalogue at a time, as Centient's own
# item field does. It starts in the business's own items. ⌥ in an empty field,
# or a click on the foot of the list, shows the suppliers whose catalogues
# Centient holds. A supplier chosen there opens its catalogue, and the search
# goes on in that. ⌥ again goes back to the suppliers, and from the suppliers
# to the business's own items. The next search starts where an item was last
# chosen from.

"""
The catalogue that the search for an item looks in: `(:own,)` for the
business's own items, `(:suppliers,)` for the list of suppliers to choose a
catalogue from, or `(:catalogue, slug, name)` for one supplier's.
"""
const ITEM_FROM = Ref{Any}((:own,))

"Look in another catalogue. The words that were typed go, and a search of the new one starts now."
browse!(v::TakeoffView, from) = begin
  ITEM_FROM[] = from
  i = plan_input(v)
  i.text = ""
  i.anchor, i.cursor = 0, 0
  v.rows, v.search, v.pick = Any[], nothing, 1
  v.query, v.typed = "", time() - 1
  handled
end

"Go from the business's own items to the list of suppliers, and from the list or a supplier's catalogue back"
toggle_catalogue!(v::TakeoffView) = browse!(v, ITEM_FROM[][1] == :catalogue ? (:suppliers,) : ITEM_FROM[][1] == :suppliers ? (:own,) : (:suppliers,))

"What the foot of the list says of the catalogue that it shows"
catalogue_words() = (from = ITEM_FROM[]; from[1] == :own ? "Our catalogue" : from[1] == :suppliers ? "Pick a catalogue" : from[3])

"True when the list shows suppliers to choose from, and false when it shows items"
lists_suppliers(v::TakeoffView) = v.asking !== nothing && v.asking[1] == :item && ITEM_FROM[][1] == :suppliers

"How tall a line of the list is. An item has a second line under its name. A contact or a supplier has its name and no more."
found_h(v::TakeoffView) = v.asking == (:customer,) || lists_suppliers(v) ? 34px : 50px

"Show the list of what the search finds, beside the text field"
show_found!(v::TakeoffView) = begin
  w = window_of(v)
  w === nothing && return
  e = editor(v)
  wide = min(v.asking == (:customer,) ? 340px : 460px, window_size(e)[1] - 16px)
  list = FoundList(of=v)
  v.parts[:found_list] = list
  # The keys stay with the text field, and a click outside the list is the app's, as it is with no list
  list.popup = popup!(w, list, anchor=plan_input(v), placement=:bottom, gap=FOUND_GAP, width=wide, key=FOUND_KEY, modal=false,
                      onclose=() -> stop_asking!(v), theme=component_theme(e.zoom))
end

const FOUND_GAP = 9px   # between the text field and the list, with the list's arrow in it

"""
Choose the side of the text field that the list is on, once for each time it
opens. The list goes under the field when the longest list fits there, and
if not, on the side with more room. A short list, like the one line that shows
while Centient searches, is then on the side that the long list will be on, so
the list doesn't jump from one side to the other.
"""
settle_side!(l::FoundList) = begin
  (l.settled || l.popup === nothing) && return
  v = l.of
  r = rect(plan_input(v))
  r === nothing && return
  item = v.asking !== nothing && v.asking[1] == :item
  # The longest list: its rows, the edges round them, and the foot that names the catalogue
  longest = MOST_FOUND * (item ? 50px : 34px) + 14px + (item ? 28px : 0px)
  over, under = r.top - FOUND_GAP, window_size(editor(v))[2] - r.top - r.height - FOUND_GAP
  l.popup.placement = under >= longest || under >= over ? :bottom : :top
  l.settled = true
end

placed!(l::FoundList, side) = (l.side = side; nothing)

describe(r::FoundRow) = begin
  v = r.of
  r.k <= length(v.rows) || return Box(height(0px))
  row = v.rows[r.k]
  c = found_colours()
  picked = v.pick == r.k
  ref = string(get(row, "ref", ""))
  # Under an item of the business is what it says of it. Under a supplier's product is the supplier's code for it.
  under = isempty(ref) ? "" : startswith(ref, "item ") ? string(something(get(row, "description", nothing), "")) : String(last(split(ref, ' ', limit=2)))
  # At the right is an item's price, and how many products a supplier's catalogue has
  right = !isempty(ref) ? price_text(row) : haskey(row, "slug") ? commas(round(Int, get(row, "products", 0))) * " products" : ""
  # A thin line parts two rows, but not the picked row from the ones beside it. A row with no line has one in its
  # own colour, so that its words don't move by the line's height when the pick comes to it or leaves it.
  back = picked ? c.pick : c.frame
  Row(width(grow=grow), height(found_h(v)), padding(12px, 0px), child_gap=10px, Alignment.Center, background(back),
      border(1px, :solid, r.k == 1 || picked || v.pick == r.k - 1 ? back : c.rule)[:top],
    # As tall as the row, so that what cuts a long name off at the side doesn't cut the tails of its g, p and y
    Column(width(grow=grow), height(grow=grow), Alignment.Start, justify=Alignment.Center, child_gap=6px, clip=true,
      label(string(row["name"]), 13px, color=c.ink),
      (isempty(under) ? () : (label(under, 11px, color=c.dim),))...),
    (isempty(right) ? () : (Box(label(right, 12px, color=c.dim)),))...)
end

cursor(::FoundRow) = :hand
onkey(r::FoundRow, ::KeyPress{Keys.mouse_left}) = choose_row!(r.of, r.k)
# The mouse picks the row that it's over, as the arrow keys do
onmouse(r::FoundRow, ::MouseMove) = begin
  v = r.of
  v.pick = r.k
  list = get(v.parts, :found_list, nothing)
  list === nothing || (list.pick = r.k)   # it's in sight already, so the list doesn't scroll to it
  handled
end

describe(l::FoundList) = begin
  v = l.of
  settle_side!(l)
  c = found_colours()
  high, n = found_h(v), length(v.rows)
  scroll = get!(() -> Scroll(width(grow=grow)), v.parts, :found_scroll)
  l.rows === v.rows || (l.rows = v.rows; l.pick = 0; scroll.offset = 0px)
  item = v.asking !== nothing && v.asking[1] == :item
  body = if n == 0
    words = v.search !== nothing || v.typed > 0 ? "Searching Centient…" :
            !isempty(v.query) && v.query != "\0" ? "Centient has nothing that matches" :
            lists_suppliers(v) ? "Centient holds no supplier's catalogue" : item ? "Nothing here yet" : "Type to search"
    Row(width(grow=grow), height(34px), padding(12px, 0px), Alignment.Center, background(c.frame), label(words, 12px, color=c.dim))
  else
    # Half a row at the bottom says that the list goes on
    scroll.height = height(min(n * high, MOST_FOUND * high - high / 2))
    l.pick == v.pick || (l.pick = v.pick; scroll_into_view!(scroll, high * (v.pick - 1), high * v.pick))
    reuse!(scroll, Column(width(grow=grow), Alignment.Start, [part!(() -> FoundRow(of=v, k=k), v, (:found, k)) for k in 1:n]...))
  end
  Box(width(grow=grow), padding(6px), radius(8px), background(c.frame), border(1px, :solid, c.line),
      shadow(0, 6, 16, RGBA(60 / 255, 45 / 255, 20 / 255, 0.2)), name="Found",
    Column(width(grow=grow), Alignment.Start, child_gap=4px,
      Column(width(grow=grow), Alignment.Start, radius(5px), border(1px, :solid, c.line), background(c.frame), clip=true, body),
      (item ? (part!(() -> CatalogueFoot(of=v), v, :catalogue_foot),) : ())...))
end

# The foot of the list of items says which catalogue it shows. A click on it does what ⌥ does.
describe(f::CatalogueFoot) = begin
  c = found_colours()
  Row(width(grow=grow), height(24px), padding(8px, 0px), radius(5px), child_gap=8px, Alignment.Center, background(ishovered(f) ? c.pick : c.frame),
    Row(width(grow=grow), height(grow=grow), Alignment.Center, clip=true, label(catalogue_words(), 12px, color=c.ink, weight="Semibold")),
    Box(label("⌥ to toggle catalogue", 11px, color=c.dim)))
end
cursor(::CatalogueFoot) = :hand
onmouse(::CatalogueFoot, ::MouseMove) = handled
onkey(f::CatalogueFoot, ::KeyPress{Keys.mouse_left}) = toggle_catalogue!(f.of)

"""
Draw the arrow of a floating box `ui`, on its edge that faces what it's for.
`side` is the side of that thing that the box is on, and `aim` is the thing's
rectangle. The arrow covers the box's border where it joins.
"""
caret(ctx, ui::ConcreteRect, side, aim) = begin
  aim === nothing && return
  c = found_colours()
  left, top, wide, high = num(ui.left), num(ui.top), num(ui.width), num(ui.height)
  x = clamp(num(aim.left + aim.width / 2), left + 16, max(left + 16, left + wide - 16))
  # The box's border is a line 1px wide along the middle of the first px of its edge. The arrow's sides start on
  # that line, so they join it with nothing past it.
  edge, way = side == :top ? (top + high - 0.5, 1) : (top + 0.5, -1)
  half, tall = 7.0, 6.5
  tip = edge + way * tall
  # Its inside goes 1px past that line into the box, on the same slant, so that no border shows across the arrow
  inner, spread = edge - way, half * (1 + 1 / tall)
  shape = path_through([(x - spread, inner), (x, tip), (x + spread, inner)], true)
  paint = ink(c.frame)
  Skia.sk_canvas_draw_path(ctx, shape, paint)
  Skia.sk_paint_delete(paint)
  Skia.sk_path_delete(shape)
  trace(ctx, [(x - half, edge), (x, tip), (x + half, edge)], c.line, 1)
end

draw(ctx, size, ui::ConcreteRect, l::FoundList) = caret(ctx, ui, l.side, rect(plan_input(l.of)))

# --- the columns of the table ------------------------------------------------------------
#
# The headings of the table of measures work as the headings of Centient's
# lists do. A click on a heading of numbers sorts by it: low to high, then high
# to low, then the order that the block is written in. A click on a heading of
# text opens a menu with its two orders and a field that searches the column.
# Return keeps the search, and Esc puts back the one before. A heading whose
# column is searched is in the accent colour. Sorting and searching change what
# the table shows, and nothing in the block or in the quote.

const HEAD_KEY = :takeoff_column
"The columns of the table that sort: the heading of each, and whether it holds text"
const COLUMNS = (item=("Item", true), extra=("Waste", false), amount=("Amount", false), price=("Price", false), cost=("Cost", false))
"What the two orders of a column are called"
order_words(text::Bool) = text ? ("A–Z", "Z–A") : ("Low → High", "High → Low")

"The item of a measure in words, as its column sorts and searches it: what the table calls it, and the catalogue that it's from"
item_words(v::TakeoffView, m) = (row = known(v, m.item); item_name(v, m) * (row === nothing ? "" : "  ·  " * string(row["source"])))

"What measure `i` has in the column `key`, as the thing that the column sorts by"
column_value(v::TakeoffView, i, key) = begin
  m = v.data.measures[i]
  key == :item && return lowercase(item_words(v, m))
  key == :extra && return m.extra
  amount, row = Plans.amount(v.data, m), known(v, m.item)
  key == :amount ? something(amount, -1.0) :
  key == :price  ? (row === nothing ? -1.0 : Float64(something(unit_price(m, row), row["price"]))) :
                   (row === nothing || amount === nothing ? -1.0 : cost_of(m, amount, row))
end

"Search the column `key` for `words`. No words takes its search away."
search_column!(v::TakeoffView, key::Symbol, words) = begin
  words = String(strip(words))
  isempty(words) ? delete!(v.filters, key) : (v.filters[key] = words)
  v
end

"The measures that the table shows, in the order that it shows them: those that the searches keep, sorted by the column that's chosen"
shown_measures(v::TakeoffView) = begin
  ms = v.data.measures
  # The item's column is the one that holds text, so a search is of it
  keep = [i for i in eachindex(ms) if all(words -> occursin(lowercase(words), lowercase(item_words(v, ms[i]))), values(v.filters))]
  v.sort === nothing ? keep : sort!(keep, by=i -> column_value(v, i, v.sort[1]), rev=v.sort[2] == :desc)
end

"The heading of the column `key`. `side` is the side of its cell that its words go on, and nothing keeps the side that it has."
head(v::TakeoffView, key::Symbol, side=nothing) = begin
  h = part!(() -> ColumnHead(of=v, key=key), v, (:head, key))
  side === nothing || (h.side = side)
  h
end

"""
The words of the heading of the column `key`. They belong to the heading, so a
click on them goes to it, and the mouse over them is over it.
"""
head_words(v::TakeoffView, key::Symbol) = begin
  h = head(v, key)
  h.words === nothing && (h.words = HeadWords(of=h); setfield!(h.words, :parent, h))
  h.words
end

"The order that a click on a heading of numbers gives next. It's nothing for the order that the block is written in."
next_order(v::TakeoffView, key) = v.sort === nothing || v.sort[1] != key ? :asc : v.sort[2] == :asc ? :desc : nothing

describe(h::ColumnHead) =
  Row(width(grow=grow), height(grow=grow), Alignment.Center, justify=h.side == :end ? Alignment.End : Alignment.Start, name="Heading",
    head_words(h.of, h.key))

describe(w::HeadWords) = begin
  h = w.of
  v = h.of
  words, text = COLUMNS[h.key]
  dir = v.sort !== nothing && v.sort[1] == h.key ? v.sort[2] : nothing
  open = v.asking !== nothing && v.asking[1] == :filter && v.asking[2] == h.key
  lit = ishovered(h) || open
  colour = haskey(v.filters, h.key) ? colours.accent : lit || dir !== nothing ? colours.ink : colours.dim
  # The arrow of the order that it has. With none, the mouse over it shows what a click gives.
  will = text ? :desc : next_order(v, h.key)
  mark = dir !== nothing ? (Icon(dir == :asc ? "chevron-up" : "chevron-down", size=9px, color=colours.ink),) :
         lit && will !== nothing ? (Icon(will == :asc ? "chevron-up" : "chevron-down", size=9px, color=colours.faint),) : ()
  parts = (label(words, 11px, color=colour), mark...)
  # The arrow goes on the side away from the cell's edge, so that it doesn't push the words when it shows
  Row(height(20px), child_gap=4px, Alignment.Center, (h.side == :start ? parts : reverse(parts))...)
end

cursor(::ColumnHead) = :hand

# A heading of numbers says what a click on it does
onmouse(h::ColumnHead, ev::MouseMove) = begin
  COLUMNS[h.key][2] && return
  will = next_order(h.of, h.key)
  low, high = order_words(false)
  words = will == :asc ? low : will == :desc ? high : "The order they're written in"
  # The tooltip follows the words: the mouse over them shows their arrow, which makes them wider on the next frame
  show_tooltip!(ev.window, tip_label(words), head_words(h.of, h.key), placement=:bottom, gap=6px)
end

onkey(h::ColumnHead, ev::KeyPress{Keys.mouse_left}) = begin
  v = h.of
  hide_tooltip!(ev.window)
  settle_asking!(v)
  COLUMNS[h.key][2] || return (will = next_order(v, h.key); v.sort = will === nothing ? nothing : (h.key, will); handled)
  # The menu's field starts with the column's search, which Esc puts back
  was = get(v.filters, h.key, "")
  ask!(v, (:filter, h.key, was), was, "Contains…")
  menu = ColumnMenu(of=v, key=h.key)
  v.parts[:column_menu] = menu
  # A click outside the menu closes it and keeps what's typed
  popup!(ev.window, menu, anchor=head_words(v, h.key), placement=:bottom, gap=9px, width=210px, key=HEAD_KEY,
         onclose=() -> settle_asking!(v), theme=component_theme(editor(v).zoom))
  handled
end

placed!(m::ColumnMenu, side) = (m.side = side; nothing)

describe(r::SortRow) = begin
  v, c = r.of, found_colours()
  on = v.sort == (r.key, r.dir)
  words = order_words(COLUMNS[r.key][2])[r.dir == :asc ? 1 : 2]
  Row(width(grow=grow), height(28px), padding(8px, 0px), radius(6px), child_gap=8px, Alignment.Center,
      background(on || ishovered(r) ? c.pick : c.frame),
    Icon(r.dir == :asc ? "chevron-up" : "chevron-down", size=10px, color=on ? c.ink : c.dim),
    label(words, 13px, color=on ? c.ink : c.dim, weight=on ? "Semibold" : ""))
end

cursor(::SortRow) = :hand
onmouse(::SortRow, ::MouseMove) = handled
# A click on the order that the table has takes it away
onkey(r::SortRow, ::KeyPress{Keys.mouse_left}) = (v = r.of; v.sort = v.sort == (r.key, r.dir) ? nothing : (r.key, r.dir); handled)

describe(m::ColumnMenu) = begin
  v, c = m.of, found_colours()
  section(words) = Row(width(grow=grow), height(22px), padding(8px, 0px), Alignment.Center, label(words, 10px, color=c.dim, weight="Semibold"))
  order(dir) = part!(() -> SortRow(of=v, key=m.key, dir=dir), v, (:sort, m.key, dir))
  Box(width(grow=grow), padding(6px), radius(8px), background(c.frame), border(1px, :solid, c.line),
      shadow(0, 6, 16, RGBA(60 / 255, 45 / 255, 20 / 255, 0.2)), name="Column menu",
    Column(width(grow=grow), Alignment.Start,
      section("SORT"), order(:asc), order(:desc),
      Box(width(grow=grow), height(13px), Alignment.Center, Box(width(grow=grow), height(1px), background(c.rule))),
      section("FILTER FOR"),
      Box(width(grow=grow), padding(4px, 2px),
        Box(width(grow=grow), height(28px), padding(8px, 0px), radius(6px), border(1px, :solid, c.line), background(c.frame), plan_input(v)))))
end

draw(ctx, size, ui::ConcreteRect, m::ColumnMenu) = caret(ctx, ui, m.side, rect(head_words(m.of, m.key)))

# The menu sees a key before its text field does. Return keeps the search, and Esc puts back the one before.
onkey(m::ColumnMenu, ev::KeyPress{Keys.enter}) = unmodified(ev) ? answer!(m.of) : nothing
onkey(m::ColumnMenu, ev::KeyPress{Keys.escape}) = begin
  unmodified(ev) || return nothing
  v = m.of
  a = v.asking
  a !== nothing && a[1] == :filter && search_column!(v, a[2], a[3])
  stop_asking!(v)
end

# --- the whole block ---------------------------------------------------------------------

"A thin line between two groups of buttons"
rule() = Box(width(9px), height(16px), Alignment.Center, Box(width(1px), height(16px), background(colours.line)))

toolbar(v::TakeoffView) = begin
  t = v.data
  n = plan_pages(v)
  s = Plans.scale(t, t.page)
  file = isempty(t.plan) ? "Choose a plan" : basename(t.plan)
  Row(width(grow=grow), height(38px), padding(6px, 0px), child_gap=2px, Alignment.Center, background(colours.block),
    [button!(v, (:tool, tool), (:tool, tool), icon=icon, tip=tip) for (tool, (icon, tip, _)) in PLAN_TOOLS]...,
    rule(),
    button!(v, :snap, :snap, icon="magnet", tip=v.snap ? "Corners snap to the lines of the plan. Click to stop that, or hold ⌘." : "Snap corners to the lines of the plan"),
    rule(),
    button!(v, :scale, :scale, words=s === nothing ? "Set the scale" : Plans.scale_text(s), tip="Type the scale of this page, like 1:100"),
    (n > 1 ? (rule(), button!(v, :back, (:page, -1), icon="chevron-left", tip="The page before", off=t.page <= 1),
              label("Page $(t.page) of $n", 12px, color=colours.dim),
              button!(v, :next, (:page, 1), icon="chevron-right", tip="The next page", off=t.page >= n)) : ())...,
    Box(width(grow=grow)),
    button!(v, :smaller, (:zoom, 1 / 1.4), icon="zoom-out", tip="Smaller"),
    button!(v, :bigger, (:zoom, 1.4), icon="zoom-in", tip=v.full ? "Bigger  pinch, or the mouse wheel" : "Bigger  pinch, or ⌘ and scroll"),
    button!(v, :fit, :fit, icon="aspect-ratio", tip="Show the whole page"),
    button!(v, :full, :full, icon=v.full ? "fullscreen-exit" : "arrows-fullscreen", tip=v.full ? "Back to the page  esc" : "Fill the window"),
    rule(),
    button!(v, :plan, :choose, icon="file-earmark-pdf", words=length(file) > 28 ? first(file, 27) * "…" : file, tip="Choose the plan's file"))
end

"The line under the tools that asks for the scale, or for the length of the line that was drawn"
prompt(v::TakeoffView) = begin
  a = v.asking
  (a !== nothing && a[1] in (:scale, :length)) || return ()
  words, hint = a[1] == :scale ? ("The scale of this page", "like 1:100, then Return") :
                                 ("How long is the line that you drew?", "in metres, like 3.6, or 3600mm, then Return")
  (Row(width(grow=grow), height(36px), padding(12px, 0px), child_gap=10px, Alignment.Center, background(colours.float),
     label(words, 12px), field(v, fixed(110px)), label(hint, 12px, color=colours.dim)),)
end

"""
True when a measure has an item of Centient's catalogue. Only then is there a
price to show, so only then has the table its columns for the price and the cost.
"""
has_items(v::TakeoffView) = any(m -> !isempty(m.item), v.data.measures)

"True when the table of measures shows the price of one of each item: when a measure has an item, and there's room"
has_price(v::TakeoffView) = has_items(v) && editor(v).width >= 720px

"""
The headings of the table of measures. Each is as wide as the cells under it.
The panel beside a plan has two lines for each measure, so it has two
headings and no more: the item and its cost. The cost and the price have
headings only while a measure has an item.
"""
table_head(v::TakeoffView) = begin
  # Each heading fills its cell, so the mouse can use it anywhere over its column
  left(key) = Row(width(grow=grow), height(grow=grow), Alignment.Center, clip=true, head(v, key, :start))
  right(wide, key) = Row(wide, height(grow=grow), Alignment.Center, clip=true, (key === nothing ? () : (head(v, key, :end),))...)
  # With no Centient on the Mac there are no prices, so the columns for them have no headings
  ours(key) = Centient.available() ? key : nothing
  cost = has_items(v) ? (right(fixed(88px), ours(:cost)),) : ()
  look = (width(grow=grow), height(26px), Alignment.Center, background(colours.head), border(1px, :solid, colours.line)[:bottom])
  v.beside && return Row(look..., padding(10px, 0px), child_gap=8px, name="Headings",
    Box(width(14px)), left(:item), cost..., Box(width(28px)))
  Row(look..., padding(10px, 0px), child_gap=10px, name="Headings",
    Box(width(14px)), left(:item), Row(fixed(52px), height(grow=grow), Alignment.Center, clip=true, head(v, :extra, :start)),
    right(fixed(AMOUNT_W), :amount), (has_price(v) ? (right(fixed(96px), ours(:price)),) : ())..., cost...,
    Box(width(28px)))   # over the buttons that remove a measure
end

"""
The table of measures, in a box of its own with round corners: the headings,
then `rows`, then the button that adds a measure. `tall` makes it fill the
height that it's given.
"""
table(v::TakeoffView, rows; tall=false) =
  Box(width(grow=grow), (tall ? (height(grow=grow),) : ())..., padding(10px, 8px),
    Column(width(grow=grow), (tall ? (height(grow=grow),) : ())..., Alignment.Start, radius(8px), border(1px, :solid, colours.line),
           background(colours.bg), clip=true, name="Measures",
      table_head(v), rows, adders(v)))

"""
The buttons at the foot of the table that start a new measure. One starts a
measure that you describe in words. The other starts one for an item of
Centient's catalogue, and shows only on a Mac that has Centient.
"""
adders(v::TakeoffView) =
  Row(width(grow=grow), height(36px), padding(6px, 0px), child_gap=2px, Alignment.Center, border(1px, :solid, colours.line)[:top],
    button!(v, :add, :add, icon="plus-lg", words="Add a measure",
            tip="Say what it measures. Then choose a tool: count, length or area."),
    (Centient.available() ? (button!(v, :add_item, :add_item, icon="box-seam", words="Add from catalogue",
                                     tip="Choose an item of Centient's catalogue. Its unit chooses the tool."),) : ())...)

"The rows of the table of measures: those that the columns' searches keep, in the order of the column that's sorted"
measure_rows(v::TakeoffView) = begin
  v.order = shown_measures(v)
  isempty(v.order) && !isempty(v.data.measures) &&
    return Any[Row(width(grow=grow), height(32px), padding(34px, 0px), Alignment.Center, label("No measure has that", 12px, color=colours.dim))]
  Any[part!(() -> MeasureRow(of=v, i=i), v, (:row, i)) for i in v.order]
end

"The line at the foot of the block: the customer, what the measures come to, and the button that makes the quote"
foot(v::TakeoffView) = begin
  t = v.data
  total, priced, all_priced = 0.0, false, true
  for m in t.measures
    amount, row = Plans.amount(t, m), known(v, m.item)
    (amount === nothing || row === nothing) && (all_priced = false; continue)
    total += cost_of(m, amount, row)
    priced = true
  end
  # The total is of the measures that have an item. While a measure has none, the words say that the total leaves it out.
  total_words = all_priced ? "At catalogue prices" : "Catalogue items only"
  asking = v.asking == (:customer,)
  busy = v.quoting !== nothing
  said = isempty(v.said) ? (isempty(t.made) ? "" : "Quote $(t.made)") : v.said
  colour = v.wrong ? colours.accent : colours.dim
  customer = asking ? field(v, v.beside ? width(grow=grow) : fixed(220px)) :
             button!(v, :customer, :customer, words=isempty(t.customer) ? "Choose the customer" : t.customer, tip="Who the quote is for")
  maker = button!(v, :quote, :quote, icon="receipt", words=busy ? "Making the quote…" : isempty(t.made) ? "Make quote in Centient" : "Make another quote",
                  tip=Centient.available() ? "Centient makes a quote with a line for each measure" : "Centient isn't on this Mac",
                  off=busy || isempty(t.measures) || !Centient.available())
  line = border(1px, :solid, colours.line)[:top]
  # In the panel beside a plan that fills the window, each part of the foot has a line of its own
  v.beside && return Column(width(grow=grow), Alignment.Start, padding(10px, 8px), child_gap=6px, line,
    Row(width(grow=grow), height(28px), child_gap=8px, Alignment.Center, Icon("person", size=14px, color=colours.dim), customer),
    (priced ? (Row(width(grow=grow), height(22px), Alignment.Center, Box(label(total_words, 12px, color=colours.dim)),
                   Box(width(grow=grow)), Box(label(dollars(total), 13px, weight="Semibold"))),) : ())...,
    (isempty(said) ? () : (Box(width(grow=grow), Alignment.Start, Text(said, size=12px, family=SANS, color=colour, wrap=WrapMode.words)),))...,
    Row(width(grow=grow), justify=Alignment.End, maker))
  Row(width(grow=grow), height(42px), padding(10px, 0px), child_gap=8px, Alignment.Center, line,
    Icon("person", size=14px, color=colours.dim), customer,
    Row(width(grow=grow), clip=true, justify=Alignment.End, Box(label(said, 12px, color=colour))),
    # The catalogue's prices, before the GST and the margins that Centient adds to a quote
    (priced ? (label(total_words, 12px, color=colours.dim), label(dollars(total), 13px, weight="Semibold")) : ())...,
    maker)
end

"How tall the list of measures is, with what a search found under one of them"
list_h(v::TakeoffView) = 32px * max(1, length(v.order))

"The most of the window's height that the list of measures takes under a plan that fills the window"
const LIST_SHARE = 0.4

"""
True when the list of measures goes beside a plan that fills the window, and
false when it goes under it. It goes where it leaves the page bigger: beside a
wide window's plan, and under a tall window's.
"""
goes_beside(v::TakeoffView) = begin
  w, h = num.(window_size(editor(v)))
  h -= num(TOPBAR_H) + 38   # the top bar and the tools
  s = plan_size(v)
  s === nothing && return w > h
  side = min(num(SIDE_W), 0.45w)
  # Under the plan are the table, with its headings, its rows and the button that adds a measure, and the foot
  under = min(32.0 * length(v.data.measures), LIST_SHARE * h) + 26 + 36 + 18 + 42
  min((w - side) / s[1], h / s[2]) >= min(w / s[1], (h - under) / s[2])
end

describe(v::TakeoffView) = begin
  e = editor(v)
  plan_input(v).color = colours.ink
  area = part!(() -> PlanArea(of=v), v, :area)
  v.beside = v.full && goes_beside(v)
  with_theme(component_theme(e.zoom)) do
    # Only the tools have a colour of their own behind them. The rest is on white, and the plan's paper has a shadow.
    v.full || return Column(width(grow=grow), Alignment.Start, radius(8px), border(1px, :solid, colours.line), background(takeoff_back()),
                            clip=true, name="Takeoff",
      toolbar(v), prompt(v)..., area,
      table(v, Column(width(grow=grow), Alignment.Start, measure_rows(v)...)),
      foot(v))
    # In the window, the plan is as big as it can be. The wheel scrolls through a list of measures that's longer than its room.
    list = get!(() -> Scroll(width(grow=grow), height(grow=grow)), v.parts, :list)
    rows = Column(width(grow=grow), Alignment.Start, measure_rows(v)...)
    if v.beside
      list.height = height(grow=grow)
      return Row(width(grow=grow), height(grow=grow), Alignment.Start, background(takeoff_back()), name="Takeoff",
        Column(width(grow=grow), height(grow=grow), Alignment.Start, toolbar(v), prompt(v)..., area),
        Column(fixed(min(SIDE_W, window_size(e)[1] * 0.45)), height(grow=grow), Alignment.Start, border(1px, :solid, colours.line)[:left],
          table(v, reuse!(list, rows), tall=true), foot(v)))
    end
    list.height = height(min(list_h(v), (window_size(e)[2] - TOPBAR_H - 38px) * LIST_SHARE))
    Column(width(grow=grow), height(grow=grow), Alignment.Start, background(takeoff_back()), name="Takeoff",
      toolbar(v), prompt(v)..., area, table(v, reuse!(list, rows)), foot(v))
  end
end

cursor(::TakeoffView) = :arrow

# --- what a takeoff's parts read -----------------------------------------------------------
#
# UI.jl describes a node again only when its `inputs` have changed, and otherwise
# uses its last geometry and layout. A takeoff's parts read its measures, its
# state and the page around it. So each part gives one number for all of that,
# which the takeoff works out once a frame, and the fields of its own that it
# reads. On a frame where nothing changed, nothing in the takeoff is described
# or laid out again: that was half the time a page with a takeoff took to
# describe. The lists that float over the page, of a search, of units and of a
# column's menu, have no `inputs`, so they're described on each frame while
# they're open. So is the takeoff while its text field shows, which has none.

"""
Everything that the parts of takeoff `v` read as they're described, as values.
A part that shows something that isn't here has to add it, or it won't change
when that does.
"""
shown_state(v::TakeoffView) = begin
  e = editor(v)
  (Plans.written(v.data), v.asking, v.current, v.filters, v.full, v.known, v.quoting === nothing, v.said, v.sort,
   v.tool, v.snap, v.wrong, e.width, e.zoom, window_size(e), plan_path(v), plan_size(v), plan_pages(v), Centient.available(),
   ntuple(k -> getfield(colours, k), nfields(colours)))
end

# UI.jl asks for the takeoff's inputs before those of its parts on each frame
inputs(v::TakeoffView) = (v.reads = hash(shown_state(v)); (v.reads,))
inputs(a::PlanArea) = (a.of.reads,)
# A schedule's buttons are PlanButtons too. They're described on each frame, as the schedule is.
inputs(b::PlanButton) = b.of isa TakeoffView ? (b.action, b.icon, b.words, b.tip, b.off, b.quiet, b.of.reads) : nothing
inputs(r::MeasureRow) = (r.i, r.of.reads)
inputs(c::AmountCell) = (c.i, c.of.reads)
inputs(u::UnitWord) = (u.of.i, u.of.of.reads)
inputs(c::MeasureCell) = (c.i, c.what, c.rect[3], c.of.reads)   # its width cuts its words short. Where it is doesn't matter.
inputs(h::ColumnHead) = (h.key, h.side, h.of.reads)
inputs(w::HeadWords) = (w.of.key, w.of.side, ishovered(w.of), w.of.of.reads)   # it's lit while the mouse is over its heading
# A click beside a button is the block's, and takes the keyboard from the text field
onkey(v::TakeoffView, ::KeyPress{Keys.mouse_left}) = (focus(part!(() -> PlanArea(of=v), v, :area)); handled)
onmouse(v::TakeoffView, ::MouseMove) = held(v, Keys.mouse_left) ? handled : nothing

# --- a schedule of the page's tasks -------------------------------------------------------
#
# A code block in the language `schedule` shows each to-do item of the page as
# a bar on a line of days. schedule.jl says how the block is written.
#
#   - Drag a bar to say the first day that its task can start.
#   - Drag the right end of a bar to say how many working days the task takes.
#   - Drag from the circle after a bar to another task. That task then waits
#     for this one, and starts when this one is finished. An arrow shows it.
#   - Click an arrow and press Delete to take it away.
#   - Click a task twice to go to its line of the page.
#   - Drag the days, or scroll sideways, to see other days. Pinch, or scroll
#     with ⌘ held, to show more days or fewer.
#   - The button at the top right makes the schedule fill the window. Esc puts
#     it back in the page.
#
# Every change is written into the block's lines, so the file holds the whole
# schedule. While the page has a schedule, the mouse over a to-do item shows
# the task's days beside the item, with buttons that make the task a day
# longer or shorter.

const SCHEDULE = Schedules.SCHEDULE
const TASK_H = 30.0        # px: how tall the row of a task is
const TASK_BAR = 20.0         # and how tall its bar is
const DATES_H = 46.0       # how tall the months and the days over the rows are
const DAY_MOST = 60.0      # the most px to a day
const DAY_LEAST = 2.5      # and the least
const DAY_USUAL = 34.0     # the most px to a day when a schedule shows all its tasks
const BAR_EDGE = 7.0       # px at the right end of a bar, where a drag makes the task longer or shorter
const KNOB = 4.5           # the radius of the circle after a bar, which a link is dragged from
const KNOB_GAP = 11.0      # from the end of a bar to the middle of that circle
const NAMES_W = 250px      # how wide the names of the tasks are at the most
const NAMES_FULL = 360px   # and at the most in a schedule that fills the window
const DETAILS_H = 24px     # how tall the days of a to-do item are beside the item
const DAY_ZERO = Date(2000, 1, 1)   # day number 0
"Every icon that a schedule can show. The built app reads them all when it's made."
const SCHEDULE_ICONS = ["bar-chart-steps", "calendar-event", "zoom-out", "zoom-in", "aspect-ratio", "dash", "plus", "check",
                        "arrows-fullscreen", "fullscreen-exit"]

"What a `schedule` block shows: the page's tasks, each as a bar on a line of days"
@def mutable struct ScheduleView <: SemanticUI
  n::Int = 0                              # its place among the page's schedules
  first::Int = 0                          # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Schedules.Schedule = Schedules.Schedule()
  lines::Vector{String} = String[]        # the lines that `data` was read from
  tasks::Vector{Schedules.Planned} = Schedules.Planned[]   # the page's tasks, with the days of each
  planned::Any = nothing                  # the version of the page, and the day, that `tasks` was worked out for
  renamed::Bool = false                   # a task has a new name that the block's lines don't have yet
  zoom::Float64 = 0.0                     # px to a day. 0 shows every task.
  at::Float64 = 0.0                       # the number of the day at the left edge of the bars
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the days and the bars were last drawn in the window
  picked::Any = nothing                   # what's selected: (:task, key), or (:link, key, key) for the link from one task to the next
  grab::Any = nothing                     # a drag: of a bar, of a bar's end, of a link or of the days
  clicked::NTuple{3,Float64} = (0.0, 0.0, 0.0)   # when and where it was last clicked
  asking::Bool = false                    # the text field for the day that the work starts shows
  said::String = ""                       # what the top of the block says when something can't be done
  parts::Dict{Any,Any} = Dict{Any,Any}()  # its buttons, names and text field, kept between frames
  full::Bool = false                      # it fills the window, over the page
  tall::px = 0px                          # how tall it was in the page when it was last laid out there
  pinned::px = 0px                        # how far the page was scrolled when it filled the window
end

"The part of a schedule that shows the days and the bars"
@def mutable struct ChartArea <: SemanticUI
  of::Any = nothing
end
"The name of a task, beside its bar"
@def mutable struct TaskName <: SemanticUI
  of::Any = nothing
  key::String = ""
end
"""
The days of the to-do item under the mouse. They show beside the item while
the page has a schedule: the task's first and last day, how many days it
takes, and what it waits for.
"""
@def mutable struct TaskDetails <: SemanticUI
  of::Any = nothing                # the schedule
  key::String = ""                 # the task
  floats::Bool = false             # it's under the item's first line, because that line has no room for it
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where it was last put in the window
  less::Any = nothing              # its two buttons
  more::Any = nothing
end
"A button beside a to-do item that makes its task a day longer or a day shorter"
@def mutable struct DayButton <: SemanticUI
  by::Int = 1
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)
end

"A part of `v` that's kept between frames"
part!(make, v::ScheduleView, key) = begin
  node = get!(make, v.parts, key)
  node.parent === nothing && setfield!(node, :parent, v)
  node
end

"The button of `v` that's kept under `key`, with what it does and shows now"
button!(v::ScheduleView, key, action; icon="", words="", tip="", off=false) = begin
  b = part!(() -> PlanButton(of=v), v, (:button, key))
  b.action, b.icon, b.words, b.tip, b.off = action, icon, words, tip, off
  b
end

"The text field of a schedule, for the day that the work starts"
schedule_input(v::ScheduleView) = part!(v, :input) do
  TextInput(placeholder="", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

field(v::ScheduleView, wide=width(grow=grow)) =
  Box(wide, height(24px), padding(6px, 0px), radius(5px), border(1px, :solid, colours.accent), background(colours.bg), schedule_input(v))

chart(v::ScheduleView) = part!(() -> ChartArea(of=v), v, :area)

# --- the block's lines and the page's tasks -------------------------------------------------

"The to-do items of the page that shows"
page_todos(e) = (b = e.buf; get!(() -> Schedules.todos(b.lines, kinds(b)), e.flows, (:todos, b.path, b.version)))

"The view of the `n`th schedule of the page that shows"
schedule_view(e, n) = begin
  v = get!(() -> ScheduleView(n=n), e.nodes, (:schedule, e.buf.path, n))
  own!(node!(Document, e, :document), v)
  v
end

"Read the schedule again from the lines of its block, if they've changed"
reread!(v::ScheduleView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  start = v.data.start
  v.data = Schedules.schedule(lines)
  v.planned = nothing
  v.renamed = false
  # When the work starts on another day, as it does after ⌘Z takes a new day back, every task shows again
  v.data.start == start || (v.zoom = 0.0)
  v
end

"Work out the days of the page's tasks again. A task that was renamed in the page keeps its line of the schedule."
replan!(v::ScheduleView) = begin
  e = editor(v)
  names = [entry.name for entry in v.data.entries]
  v.tasks = Schedules.plan!(v.data, page_todos(e))
  names == [entry.name for entry in v.data.entries] || (v.renamed = true)
  v.planned = (e.buf.version, Dates.today())
  v
end

"The page's tasks with the days of each. They're worked out again when the page has changed, and on a new day."
tasks!(v::ScheduleView) = (v.planned == (editor(v).buf.version, Dates.today()) || replan!(v); v.tasks)

"The place of the task called `key` in the list of tasks, or nothing"
task_place(v::ScheduleView, key) = findfirst(t -> t.todo.key == key, v.tasks)

"""
Write the schedule into its block. The caret stays where it was in the text,
and ⌘Z takes the change back. If the block's lines aren't the ones that the
schedule was read from, something else changed them, and the schedule is read
again. The lines of tasks that the page no longer has go.
"""
commit!(v::ScheduleView) = begin
  e = editor(v)
  b = e.buf
  readonly(b) && return v
  span = block_lines(b, SCHEDULE, v.n)
  span === nothing && return v
  i, t = span
  v.first, v.last = i, t
  b.lines[i+1:t-1] == v.lines || return reread!(v, b.lines[i+1:t-1])
  # The day that the work starts is written down, so that it's the same day tomorrow
  v.data.start === nothing && (v.data.start = Schedules.workday(Dates.today(), v.data.weekends))
  Schedules.prune!(v.data, page_todos(e))
  new = Schedules.written(v.data)
  v.planned = nothing
  v.renamed = false
  new == v.lines && return v
  caret, anchor = b.caret, b.anchor
  edit!(b, line_end(b, i), line_end(b, t - 1), isempty(new) ? "" : "\n" * join(new, "\n"))
  by = length(new) - length(v.lines)
  moved(p) = p[1] >= t ? (p[1] + by, p[2]) : p[1] > i ? (i, 0) : p
  b.caret, b.anchor = moved(caret), moved(anchor)
  v.last += by
  v.lines = new
  v
end

"What the `schedule` block from line `i` to line `t` shows. `n` is its place among the page's schedules."
schedule_item(e, i, t, n) = begin
  v = schedule_view(e, n)
  v.first, v.last = i, t
  reread!(v, e.buf.lines[i+1:t-1])
  tasks!(v)
  # A schedule that fills the window is drawn over the page, and its room in the page stays empty
  v.full && return Live(Box(width(grow=grow), height(v.tall)), v.tall + 2LIVE_GAP)
  # Lay it out once to learn how tall it is
  concrete = describe(Column(fixed(e.width), Alignment.Start, geometry(v)), (e.width, 9999px))
  v.tall = concrete.height
  Live(v, v.tall + 2LIVE_GAP)
end

"Make the schedule fill the window, or put it back in the page. Either way it shows every task again."
full!(v::ScheduleView, on::Bool) = begin
  e = editor(v)
  on && unfill!(e)   # one block at a time fills the window
  v.full = on
  v.pinned = e.scroll.offset
  v.zoom = 0.0
  focus(chart(v))
  handled
end

"How tall the names and the bars are in a schedule that fills the window, when its tasks need less: the window, under the top bar and the schedule's buttons"
full_room(v::ScheduleView) = num(window_size(editor(v))[2] - TOPBAR_H - 38px)

"How tall the names and the bars of a schedule are"
chart_h(v::ScheduleView) = (rows = DATES_H + TASK_H * length(v.tasks); px(v.full ? max(rows, full_room(v)) : rows))

"""
Write the page to its file. A task that was renamed in the page since its
schedule was last written gets its new name in the schedule first, so that the
file's schedule names the tasks as the file's to-do items do. A page from a web
server has no file: it's saved as a copy that you can change, with `save_copy!`.
"""
save_page!(e) = begin
  isremote(e.buf.path) && return save_copy!(e)   # a page from a web server is saved as a copy that you can change
  write_blocks!(e)   # what a block that a file defines holds now goes into its lines
  for (key, node) in collect(e.nodes)
    (node isa ScheduleView && key[2] == e.buf.path) || continue
    span = block_lines(e.buf, SCHEDULE, node.n)
    span === nothing && continue
    reread!(node, e.buf.lines[span[1]+1:span[2]-1])
    tasks!(node)
    node.renamed && commit!(node)
  end
  save!(e.buf)
  # A page that a part of this one shows, and that was changed there, is saved with it
  foreach(b -> dirty(b) && save!(b), shown_buffers(e))
end

# --- where things are ------------------------------------------------------------------------

"The number of the day `d`: one more for each day that passes"
daynum(d::Date) = Float64(Dates.value(d - DAY_ZERO))
"The day with the number `n`"
numday(n::Real) = DAY_ZERO + Day(floor(Int, n))

"How far across the window day number `n` starts"
day_x(v::ScheduleView, n::Real) = v.box[1] + (n - v.at) * v.zoom
"The number of the day at `x` across the window, with the part of the day that's passed"
x_day(v::ScheduleView, x::Real) = v.at + (x - v.box[1]) / v.zoom

"Where the bar of the task at place `i` is in the window for its run from `start` to `finish`: its left, top, width and height"
bar_box(v::ScheduleView, i::Int, start::Date, finish::Date) = begin
  left, right = day_x(v, daynum(start)) + 1, day_x(v, daynum(finish) + 1) - 1
  (left, v.box[2] + DATES_H + (i - 1) * TASK_H + (TASK_H - TASK_BAR) / 2, max(right - left, 3.0), TASK_BAR)
end

"Where the bar of the first run of the task at place `i` is in the window: its left, top, width and height"
task_bar(v::ScheduleView, i::Int) = (t = v.tasks[i]; bar_box(v, i, t.start, t.finish))

"The first and the last day of each run after the first of the task at place `i`, when its item says how often it repeats, up to the last day in sight"
task_runs(v::ScheduleView, i::Int) =
  v.zoom > 0 ? Schedules.runs(v.tasks[i], numday(v.at + v.box[3] / v.zoom), v.data.weekends) : Tuple{Date,Date}[]

"Where the bar of the time `k` of the task at place `i` is in the window: its first bar when `k` is 1. Nothing when it has no such time."
time_bar(v::ScheduleView, i::Int, k::Int) = begin
  k == 1 && return task_bar(v, i)
  d = Schedules.time_days(v.tasks[i], k, v.data.weekends)
  d === nothing ? nothing : bar_box(v, i, d...)
end

"The bars of the task at place `i` that are in sight, or before them: its first, then each time after it up to the last day in sight"
row_bars(v::ScheduleView, i::Int) = [task_bar(v, i); [bar_box(v, i, a, z) for (a, z) in task_runs(v, i)]]

"""
The middle of the circle that a link is dragged from, for the bar `b`, when the
next bar of its task is `n`, or nothing: after the bar, or on its top right
corner when `n` leaves no room after it. And true when it's on the corner.
"""
knob_place(b, n) = n === nothing || n[1] - (b[1] + b[3]) >= KNOB_GAP + KNOB + 3 ?
  ((b[1] + b[3] + KNOB_GAP, b[2] + b[4] / 2), false) : ((b[1] + b[3] - KNOB - 2, b[2]), true)

"The middle of the circle that a link is dragged from, for the time `k` of the task at place `i`"
knob(v::ScheduleView, i::Int, k::Int=1) = knob_place(time_bar(v, i, k), time_bar(v, i, k + 1))[1]

"Which time of the task at place `i` has its bar at `x` across the window: its number, or 1 when no later time has"
time_at(v::ScheduleView, i::Int, x::Real) = begin
  for (k, (a, z)) in enumerate(task_runs(v, i))
    rx, _, rw, _ = bar_box(v, i, a, z)
    rx <= x < rx + rw && return k + 1
  end
  1
end

"The task at place `i` in words, with the day of its time `k` when it repeats: “Water the slab” on Wed 9 Dec"
time_words(v::ScheduleView, i::Int, k::Int) = begin
  t = v.tasks[i]
  words = "“$(t.todo.name)”"
  Schedules.repeats(t.todo) === nothing && return words
  d = Schedules.time_days(t, k, v.data.weekends)
  d === nothing ? words : words * " on " * Schedules.short(d[1])
end

"The place of the task whose row is `y` down the window, or nothing"
row_at(v::ScheduleView, y::Real) = begin
  i = floor(Int, (y - v.box[2] - DATES_H) / TASK_H) + 1
  1 <= i <= length(v.tasks) ? i : nothing
end

"""
The corners of the arrow from the end of the bar of time `ka` of task `a` to
the start of the bar of time `kb` of task `b`, or nothing when one has no such
time. Where the bars leave no room to turn between them, it goes round,
between two rows.
"""
link_points(v::ScheduleView, a::Int, b::Int) = link_points(v, a, 1, b, 1)
link_points(v::ScheduleView, a::Int, ka::Int, b::Int, kb::Int) = begin
  from, to = time_bar(v, a, ka), time_bar(v, b, kb)
  (from === nothing || to === nothing) && return nothing
  sx, sy = from[1] + from[3], from[2] + from[4] / 2
  tx, ty = to[1], to[2] + to[4] / 2
  out = sx + 8
  tx - out >= 8 && return [(sx, sy), (out, sy), (out, ty), (tx, ty)]
  between = sy + sign(ty - sy) * TASK_H / 2
  back = tx - 9
  [(sx, sy), (out, sy), (out, between), (back, between), (back, ty), (tx, ty)]
end

"How far the place `(x, y)` is from the line through the places `ps`"
away(ps, x, y) = minimum(1:length(ps)-1) do k
  (ax, ay), (bx, by) = ps[k], ps[k+1]
  long = (bx - ax)^2 + (by - ay)^2
  along = long == 0 ? 0.0 : clamp(((x - ax) * (bx - ax) + (y - ay) * (by - ay)) / long, 0, 1)
  hypot(x - ax - along * (bx - ax), y - ay - along * (by - ay))
end

"""
What's at the place `(x, y)` of a schedule's bars: `(:knob, i, k)` for the
circle of the time `k` of the task at place `i` (1 for its first bar),
`(:edge, i)` for the right end of its first bar, `(:bar, i)` for the rest of
the bar, `(:run, i, start, finish)` for the bar of a later time of a task that
repeats, `(:link, a, b, r, k)` for the arrow from task `a` to the time `k` of
task `b`, where `r` is the time of `a` as `Schedules.links` gives it,
`(:row, i)` for the rest of the task's row, or nothing.
"""
under(v::ScheduleView, x::Real, y::Real) = begin
  left, top, wide, tall = v.box
  (v.zoom > 0 && left <= x < left + wide && top + DATES_H <= y < top + tall) || return nothing
  i = row_at(v, y)
  i === nothing && return nothing
  bx, by, bw, bh = task_bar(v, i)
  # The circle of each bar of the task. One on a bar's corner reaches less far, so the bar's end can still be dragged.
  bars = row_bars(v, i)
  for k in eachindex(bars)
    (kx, ky), corner = knob_place(bars[k], get(bars, k + 1, nothing))
    hypot(x - kx, y - ky) <= (corner ? KNOB + 1.5 : KNOB + 3) && return (:knob, i, k)
  end
  if by - 2 <= y < by + bh + 2
    bx <= x < bx + bw + 3 && return x >= bx + bw - min(BAR_EDGE, bw / 2) ? (:edge, i) : (:bar, i)
    for (a, z) in task_runs(v, i)
      rx, _, rw, _ = bar_box(v, i, a, z)
      rx <= x < rx + rw && return (:run, i, a, z)
    end
  end
  for (a, r, b, k) in Schedules.links(v.tasks)
    ps = link_points(v, a, Schedules.bar_of(v.tasks[a], r), b, k)
    ps === nothing || away(ps, x, y) > 4 || return (:link, a, b, r, k)
  end
  (:row, i)
end

"The place of the task whose row the mouse is over, in its name or in its bar's row, or 0"
hot_row(v::ScheduleView) = begin
  w = window_of(v)
  (w === nothing || !ishovered(v) || v.zoom <= 0) && return 0
  something(row_at(v, num(w.mouse[2])), 0)
end

"The days of a task in words: Mon 16 Nov – Wed 18 Nov"
task_days(t) = t.start == t.finish ? Schedules.short(t.start) : Schedules.short(t.start) * " – " * Schedules.short(t.finish)
"The days of a task and how many they are: Mon 16 Nov – Wed 18 Nov  ·  3 days"
task_words(t) = task_days(t) * "  ·  " * Schedules.days_text(t.days)

"""
Show every task: the days from the day before the first task starts to the
day after the last one finishes. A task that repeats with a limit, like `every
day for 3 days`, finishes with its last run. One that repeats for ever finishes
with its first. A short schedule's days are no wider than `DAY_USUAL` in the
page, and no wider than `DAY_MOST` when it fills the window.
"""
fit!(v::ScheduleView) = begin
  ts = v.tasks
  today = Dates.today()
  ends(t) = something(Schedules.last_day(t, v.data.weekends), t.finish)
  lo, hi = isempty(ts) ? (today, today + Day(13)) : (minimum(t -> t.start, ts), maximum(ends, ts))
  days = daynum(hi) - daynum(lo) + 3.5
  v.zoom = clamp(max(v.box[3], 1.0) / days, DAY_LEAST, v.full ? DAY_MOST : DAY_USUAL)
  v.at = daynum(lo) - 1
  v
end

"Make each day `by` times as wide. The day at `x` across the window stays there."
zoom_days!(v::ScheduleView, by, x) = begin
  v.zoom > 0 || return handled
  day = x_day(v, x)
  v.zoom = clamp(v.zoom * by, DAY_LEAST, DAY_MOST)
  v.at = day - (x - v.box[1]) / v.zoom
  handled
end

# --- drawing -------------------------------------------------------------------------------

"Write `words` on the canvas, with their left end at `x` and the line that they stand on at `y`"
write_ink(ctx, words, x, y, face::Face) = begin
  paint = ink(face.color)
  blob = Skia.sk_textblob_make_from_string(words, skia_font(face.family, face.size, face.style).raw, Skia.SK_TEXT_ENCODING_UTF8)
  Skia.sk_canvas_draw_text_blob(ctx, blob, Float32(x), Float32(y), paint)
  Skia.sk_textblob_unref(blob)
  Skia.sk_paint_delete(paint)
end

"Draw a box whose corners have the radius `r`. `fill` colours it in, and `line` draws its edge, `wide` px wide."
round_box(ctx, x, y, w, h, r; fill=nothing, line=nothing, wide=1.0) = begin
  shape = Skia.sk_path_new()
  rect = Ref(Skia.sk_rect_t(Float32(x), Float32(y), Float32(x + w), Float32(y + h)))
  Skia.sk_path_add_rounded_rect(shape, rect, Float32(r), Float32(r), Skia.SK_PATH_DIRECTION_CW)
  for paint in ((fill === nothing ? () : (ink(fill),))..., (line === nothing ? () : (ink(line, wide),))...)
    Skia.sk_canvas_draw_path(ctx, shape, paint)
    Skia.sk_paint_delete(paint)
  end
  Skia.sk_path_delete(shape)
end

"Draw a line through the corners `ps`, each corner a little round, with the head of an arrow at its end"
arrow(ctx, ps, colour, wide) = begin
  shape = Skia.sk_path_new()
  Skia.sk_path_move_to(shape, Float32(ps[1][1]), Float32(ps[1][2]))
  for k in 2:length(ps)-1
    before, corner, after = ps[k-1], ps[k], ps[k+1]
    d1, d2 = hypot((corner .- before)...), hypot((after .- corner)...)
    r = min(4.0, d1 / 2, d2 / 2)
    a = corner .+ (before .- corner) .* (r / max(d1, 1e-6))
    b = corner .+ (after .- corner) .* (r / max(d2, 1e-6))
    Skia.sk_path_line_to(shape, Float32(a[1]), Float32(a[2]))
    # A conic with this weight is a quarter of a circle
    Skia.sk_path_conic_to(shape, Float32(corner[1]), Float32(corner[2]), Float32(b[1]), Float32(b[2]), Float32(sqrt(0.5)))
  end
  # The line stops where the head starts
  tip, from = ps[end], ps[end-1]
  along = (tip .- from) ./ max(hypot((tip .- from)...), 1e-6)
  base = tip .- along .* 5.5
  Skia.sk_path_line_to(shape, Float32(base[1]), Float32(base[2]))
  paint = ink(colour, wide)
  Skia.sk_canvas_draw_path(ctx, shape, paint)
  Skia.sk_paint_delete(paint)
  Skia.sk_path_delete(shape)
  across = (-along[2], along[1]) .* 3.4
  trace(ctx, [tip, base .+ across, base .- across], colour, 0.6; fill=colour, closed=true)
end

"Draw the months and the days over the rows, the lines between them, the days when no work is done, and today"
draw_days(ctx, v::ScheduleView) = begin
  left, top, wide, tall = v.box
  z = v.zoom
  rows = top + DATES_H
  small = Face(SANS, "", 11px, colours.dim, false)
  each_day, each_week = z >= 20, 7z >= 46
  for n in floor(Int, v.at):ceil(Int, v.at + wide / z)
    d = numday(n)
    x = day_x(v, n)
    off = !Schedules.works(d, v.data.weekends)
    off && round_box(ctx, x, rows, z, tall - DATES_H, 0; fill=RGBA(colours.ink, 0.05))
    month, monday = Dates.day(d) == 1, Dates.dayofweek(d) == 1
    if month
      trace(ctx, [(x, top + 4), (x, top + tall)], RGBA(colours.ink, 0.16), 1.0)
    elseif each_day || (monday && each_week)
      trace(ctx, [(x, rows), (x, top + tall)], RGBA(colours.ink, monday ? 0.1 : 0.05), 1.0)
    end
    if each_day
      words = string(Dates.day(d))
      face = off ? Face(small, color=colours.faint) : small
      write_ink(ctx, words, x + (z - num(measure(face, words))) / 2, top + 37, face)
    elseif monday && each_week
      write_ink(ctx, "$(Dates.day(d)) $(Dates.monthabbr(d))", x + 5, top + 37, small)
    end
  end
  # Today's name goes over the middle of today, when today is in sight. A page that shows another day has that day's name there.
  e = editor(v)
  other = another_day(e)
  at = other ? page_day(e) : Dates.today()
  pill_text = other ? "$(Dates.day(at)) $(Dates.monthabbr(at))" : "Today"
  now = day_x(v, daynum(at)) + z / 2
  today = Face(SANS, "Semibold", 10.5px, colours.bg, false)
  pill = num(measure(today, pill_text)) + 12
  shows = left <= now <= left + wide
  # Each month's name is at the month's first day, or at the left edge when that day is out of sight.
  # A name that today's name would cover goes after it.
  bold = Face(SANS, "Medium", 12px, colours.ink, false)
  month = Dates.firstdayofmonth(numday(v.at))
  while day_x(v, daynum(month)) < left + wide
    next = month + Dates.Month(1)
    words = "$(Dates.monthname(month)) $(Dates.year(month))"
    long = num(measure(bold, words))
    x = max(left + 8, day_x(v, daynum(month)) + 6)
    shows && x < now + pill / 2 + 6 && x + long > now - pill / 2 - 6 && (x = now + pill / 2 + 8)
    write_ink(ctx, words, min(x, day_x(v, daynum(next)) - long - 8), top + 18, bold)
    month = next
  end
  trace(ctx, [(left, rows), (left + wide, rows)], colours.line, 1.0)
  for i in 1:length(v.tasks)
    y = rows + i * TASK_H
    trace(ctx, [(left, y), (left + wide, y)], RGBA(colours.line, 0.6), 1.0)
  end
  # Today has a line down the rows, under its name
  if shows
    trace(ctx, [(now, rows), (now, top + tall)], RGBA(colours.ink, 0.6), 1.0)
    round_box(ctx, now - pill / 2, top + 6, pill, 16, 4; fill=colours.ink)
    write_ink(ctx, pill_text, now - pill / 2 + 6, top + 17.5, today)
  end
end

"The colour of a task's bar: one for a task that's done, and one for a task that isn't"
task_hue(done::Bool) = done ? colours.string : colours.accent

"""
True when the bar of a task's run from `start` to `finish` shows as done.
`done` is true when the task's item is ticked. On another day than today, the
plan says: a run that's finished by then is done.
"""
run_done(e, start::Date, finish::Date, done::Bool) = another_day(e) ? Days.stands(start, finish, done, page_day(e), calendar_today()) == :done : done

"""
Draw a bar of a task, `days` long, at `(x, y)`, `w` wide and `h` tall. A bar
that's `done` has a tick, a `strong` one is darker, and a bar with room says
how many days it is. It gives the bar's colour.
"""
draw_bar(ctx, x, y, w, h, days::Int, done::Bool, strong::Bool) = begin
  hue = task_hue(done)
  round_box(ctx, x, y, w, h, 5; fill=RGBA(hue, strong ? 0.32 : 0.17), line=RGBA(hue, 0.9), wide=strong ? 1.8 : 1.0)
  inset = 6.0
  if done && w >= 18
    trace(ctx, [(x + 5.5, y + h / 2 + 0.5), (x + 8.5, y + h / 2 + 3.5), (x + 13.5, y + h / 2 - 3.5)], hue, 1.6)
    inset = 18.0
  end
  face = Face(SANS, "Medium", 10.5px, hue, false)
  words = "$(days)d"
  num(measure(face, words)) + inset + 5 <= w && write_ink(ctx, words, x + inset, y + h / 2 + 3.8, face)
  hue
end

"""
Which time of the task at place `i` shows the circle that a link is dragged
from: the one under the mouse, or else the task as a whole, which is its last
time when its item says how many, and its first otherwise.
"""
hot_time(v::ScheduleView, i::Int) = begin
  t = v.tasks[i]
  whole = Schedules.bar_of(t, 0)
  w = window_of(v)
  w === nothing && return whole
  hit = under(v, num(w.mouse[1]), num(w.mouse[2]))
  (hit === nothing || hit[2] != i) && return whole
  hit[1] == :knob ? hit[3] : hit[1] in (:bar, :edge) ? 1 : hit[1] == :run ? time_at(v, i, num(w.mouse[1])) : whole
end

"""
Draw the bar of each task. A task whose item says how often it repeats has a
bar for each time, to the right edge of the days, or to its last time. The
task under the mouse, and the one that's selected, have the circle that a link
is dragged from: after the bar of the time under the mouse, or of the task as
a whole.
"""
draw_bars(ctx, v::ScheduleView) = begin
  left, _, wide, _ = v.box
  hot = hot_row(v)
  g = v.grab
  e = editor(v)
  for (i, t) in enumerate(v.tasks)
    on = v.picked == (:task, t.todo.key)
    # A bar is marked while the mouse is on its task in another part of the page
    lit = i != hot && marked(v, t.todo.key)
    for (a, z) in task_runs(v, i)
      x, y, w, h = bar_box(v, i, a, z)
      x + w < left || draw_bar(ctx, x, y, w, h, t.days, run_done(e, a, z, false), on || lit)
    end
    x, y, w, h = task_bar(v, i)
    (x + w + 2KNOB_GAP < left || x > left + wide) && continue
    # On another day than today, the plan says which runs are done
    hue = draw_bar(ctx, x, y, w, h, t.days, run_done(e, t.start, t.finish, t.todo.done), on || lit)
    linking = g !== nothing && g[1] == :link && g[2] == t.todo.key
    if (g === nothing && (i == hot || on)) || linking
      k = linking ? g[3] : hot_time(v, i)
      b = time_bar(v, i, k)
      b === nothing && continue
      (kx, ky), corner = knob_place(b, time_bar(v, i, k + 1))
      corner || trace(ctx, [(b[1] + b[3], ky), (kx - KNOB, ky)], RGBA(hue, 0.7), 1.2)
      for (r, colour) in ((KNOB, hue), (KNOB - 1.5, takeoff_back()))
        paint = ink(colour)
        Skia.sk_canvas_draw_circle(ctx, Float32(kx), Float32(ky), Float32(r), paint)
        Skia.sk_paint_delete(paint)
      end
    end
  end
end

"""
Draw an arrow from each task to each task that waits for it, from and to the
bars of the times that they say. Each time of a task that repeats waits for
the time before it, so a short arrow joins them where there's room between
their bars.
"""
draw_links(ctx, v::ScheduleView) = begin
  for (a, r, b, k) in Schedules.links(v.tasks)
    ps = link_points(v, a, Schedules.bar_of(v.tasks[a], r), b, k)
    ps === nothing && continue
    on = v.picked == (:link, v.tasks[a].todo.key, v.tasks[b].todo.key, r, k)
    arrow(ctx, ps, on ? colours.accent : RGBA(colours.dim, 0.9), on ? 2.0 : 1.2)
  end
  left, _, wide, _ = v.box
  for (i, t) in enumerate(v.tasks)
    Schedules.repeats(t.todo) === nothing && continue
    bars = row_bars(v, i)
    for k in 1:length(bars)-1
      x, y, w, h = bars[k]
      nx = bars[k+1][1]
      (nx < left || x > left + wide) && continue
      mid = y + h / 2
      if nx - (x + w) >= 10
        arrow(ctx, [(x + w + 1, mid), (nx - 1, mid)], RGBA(colours.dim, 0.9), 1.2)
      elseif nx - (x + w) >= 4
        trace(ctx, [(x + w, mid), (nx, mid)], RGBA(colours.dim, 0.9), 1.2)
      end
    end
  end
end

"Draw what a drag is doing: the link that's being made, or the days of the bar that's being moved"
draw_drag(ctx, v::ScheduleView) = begin
  g = v.grab
  (g === nothing || g[1] == :pan) && return
  i = task_place(v, g[2])
  i === nothing && return
  x, y, w, h = task_bar(v, i)
  if g[1] == :link
    win = window_of(v)
    win === nothing && return
    mx, my = num(win.mouse[1]), num(win.mouse[2])
    trace(ctx, [knob(v, i, g[3]), (mx, my)], colours.accent, 1.5)
    # The task that the link would go to has a line round its bar: the bar of the time under the mouse, or its first
    j = row_at(v, my)
    if j !== nothing && j != i
      tx, ty, tw, th = time_bar(v, j, time_at(v, j, mx))
      round_box(ctx, tx - 2, ty - 2, tw + 4, th + 4, 7; line=colours.accent, wide=1.5)
    end
  else
    tag(ctx, (x + w - 4, y + 2), task_words(v.tasks[i]))
  end
end

describe(a::ChartArea) = Box(width(grow=grow), height(chart_h(a.of)))

draw(ctx, size, ui::ConcreteRect, a::ChartArea) = begin
  v = a.of
  v.box = (num(ui.left), num(ui.top), num(ui.width), num(ui.height))
  v.box[3] > 0 || return
  v.zoom > 0 || fit!(v)
  with_clip(ctx, ui.left, ui.top, ui.width, ui.height) do
    draw_days(ctx, v)
    draw_links(ctx, v)
    draw_bars(ctx, v)
    draw_drag(ctx, v)
  end
end

cursor(a::ChartArea) = begin
  v = a.of
  g = v.grab
  g === nothing || return g[1] == :size ? :resize_x : g[1] == :pan ? :arrow : :hand
  w = window_of(v)
  w === nothing && return :arrow
  hit = under(v, num(w.mouse[1]), num(w.mouse[2]))
  hit === nothing || hit[1] == :row ? :arrow : hit[1] == :edge ? :resize_x : :hand
end

# --- the mouse and the keys on the bars -----------------------------------------------------

"Put the caret at the end of line `i` of the page, and bring the line in sight"
show_line!(e, i::Int) = begin
  b = e.buf
  1 <= i <= length(b.lines) || return handled
  b.caret = b.anchor = line_end(b, i)
  focus(e)
  touch!(e)
  handled
end

"Note a click at `(x, y)`. True when it's the second of two clicks in one place."
click_twice!(v::ScheduleView, x, y) = begin
  at, cx, cy = v.clicked
  v.clicked = (time(), x, y)
  time() - at < 0.35 && hypot(x - cx, y - cy) < 4
end

onkey(a::ChartArea, ev::KeyPress{Keys.mouse_left}) = begin
  v, w = a.of, ev.window
  focus(a)
  v.said = ""
  v.zoom > 0 || return handled
  x, y = num(w.mouse[1]), num(w.mouse[2])
  twice = click_twice!(v, x, y)
  hit = under(v, x, y)
  if hit === nothing || hit[1] == :row
    # A drag of anything but a bar moves the days
    v.picked = nothing
    v.grab = (:pan, x, v.at)
  elseif hit[1] == :link
    v.picked = (:link, v.tasks[hit[2]].todo.key, v.tasks[hit[3]].todo.key, hit[4], hit[5])
  else
    t = v.tasks[hit[2]]
    key = t.todo.key
    v.picked = (:task, key)
    if hit[1] == :knob
      # The link goes from the time whose circle it is
      v.grab = (:link, key, hit[3])
    elseif hit[1] == :edge
      v.grab = (:size, key, false)
    elseif twice
      return show_line!(editor(v), t.todo.line)
    else
      # The bar keeps the place where the mouse took hold of it
      v.grab = (:move, key, x - day_x(v, daynum(t.start)), false)
    end
  end
  handled
end

"A drag ended. A link is made, or the bar that moved is written down."
drop!(v::ScheduleView) = begin
  g = v.grab
  v.grab = nothing
  g === nothing && return v
  if g[1] == :link
    w = window_of(v)
    a = task_place(v, g[2])
    b = w === nothing ? nothing : row_at(v, num(w.mouse[2]))
    (a === nothing || b === nothing) && return v
    # It goes to the time whose bar is under the mouse, or to the task's first time
    to = time_at(v, b, num(w.mouse[1]))
    did = Schedules.link!(v.data, v.tasks, a, b; from=Schedules.whole(v.tasks[a], g[3]), to)
    did == :ok && return commit!(v)
    did == :loop && (v.said = "$(time_words(v, a, g[3])) waits for $(time_words(v, b, to)), so it can't go before it")
  elseif g[1] in (:move, :size) && g[end]
    commit!(v)
  end
  v
end

onmouse(a::ChartArea, ev::MouseMove) = begin
  v = a.of
  v.zoom > 0 || return nothing
  x, y = num(ev.position[1]), num(ev.position[2])
  g = v.grab
  if g === nothing
    # A bar says its days, and the other parts say what they're for
    hit = under(v, x, y)
    if hit !== nothing && hit[1] in (:bar, :edge)
      show_tooltip!(ev.window, tip_label(task_words(v.tasks[hit[2]])), px.(task_bar(v, hit[2]))..., placement=:top, gap=6px)
    elseif hit !== nothing && hit[1] == :run
      # A later run of a task that repeats says its own days, and how often the task repeats
      t = v.tasks[hit[2]]
      words = task_words((start=hit[3], finish=hit[4], days=t.days)) * "  ·  " * Repeats.how_often(t.todo.name).match
      show_tooltip!(ev.window, tip_label(words), px.(bar_box(v, hit[2], hit[3], hit[4]))..., placement=:top, gap=6px)
    elseif hit !== nothing && hit[1] == :knob
      kx, ky = knob(v, hit[2], hit[3])
      show_tooltip!(ev.window, tip_label("Drag to the task that waits for this one"), px(kx - KNOB), px(ky - KNOB), px(2KNOB), px(2KNOB), placement=:top, gap=6px)
    elseif hit !== nothing && hit[1] == :link
      a, b, r, k = hit[2:5]
      words = "$(time_words(v, b, k)) waits for $(time_words(v, a, Schedules.bar_of(v.tasks[a], r))).  Click, then Delete takes the link away"
      show_tooltip!(ev.window, tip_label(words), px(x - 4), px(y - 4), 8px, 8px, placement=:top, gap=6px)
    end
    return handled
  end
  Keys.mouse_left in ev.window.keys || (drop!(v); return handled)
  # A press that became a drag isn't the first click of two
  hypot(x - v.clicked[2], y - v.clicked[3]) > 4 && (v.clicked = (0.0, 0.0, 0.0))
  if g[1] == :pan
    v.at = g[3] - (x - g[2]) / v.zoom
    return handled
  end
  i = task_place(v, g[2])
  i === nothing && return handled
  t = v.tasks[i]
  if g[1] == :move
    d = Schedules.workday(numday(round(x_day(v, x - g[3]))), v.data.weekends)
    d == t.start && return handled
    Schedules.move!(v.data, v.tasks, t, d)
    replan!(v)
    v.grab = (:move, g[2], g[3], true)
  elseif g[1] == :size
    # The bar ends at the line between two days that's nearest the mouse
    days = max(1, Schedules.span(t.start, numday(round(x_day(v, x))) - Day(1), v.data.weekends))
    days == t.days && return handled
    Schedules.days!(v.data, t, days)
    replan!(v)
    v.grab = (:size, g[2], true)
  end
  handled   # the drag is the schedule's, so the page's text doesn't select
end

"The place across the window that the days grow or shrink round: the mouse, or the nearest end of the days when the mouse is beside them"
zoom_x(v::ScheduleView, w) = clamp(num(w.mouse[1]), v.box[1], v.box[1] + v.box[3])

# Scrolling sideways moves the days, and scrolling with ⌘ held shows more days or fewer, round the mouse.
# They do that anywhere on the schedule: over the bars, the days, the names of the tasks or the buttons.
# Scrolling up and down scrolls the page that the schedule is on.
onscroll(v::ScheduleView, ev::MouseScroll) = begin
  w = ev.window
  v.zoom > 0 || return nothing
  dx, dy = num(ev.delta[1]), num(ev.delta[2])
  only_held(w, Keys.cmd) && return zoom_days!(v, exp(dy / 10), zoom_x(v, w))
  abs(dx) > abs(dy) || return nothing
  v.at -= 30dx / v.zoom
  handled
end
onscroll(a::ChartArea, ev::MouseScroll) = onscroll(a.of, ev)

onpinch(v::ScheduleView, ev::Pinch) = zoom_days!(v, ev.scale, zoom_x(v, ev.window))
onpinch(a::ChartArea, ev::Pinch) = onpinch(a.of, ev)

# Esc takes the selection away, then puts a schedule that fills the window back in the page, then gives the keyboard back to the text
onkey(a::ChartArea, ev::KeyPress{Keys.escape}) = begin
  unmodified(ev) || return nothing
  v = a.of
  v.picked === nothing || return (v.picked = nothing; handled)
  v.full ? full!(v, false) : nothing
end
onkey(a::ChartArea, ::KeyPress{K}) where K = begin
  v = a.of
  if K in (Keys.backspace, Keys.delete) && unmodified(window_of(a))
    # Delete takes away the link that's selected
    p = v.picked
    (p !== nothing && p[1] == :link) || return handled
    from, to = task_place(v, p[2]), task_place(v, p[3])
    v.picked = nothing
    (from === nothing || to === nothing) && return handled
    Schedules.unlink!(v.data, v.tasks, from, to; from=p[4], to=p[5])
    commit!(v)
    return handled
  elseif (command = command_of(editor(v), window_of(a), K)) in (:undo, :redo)
    b = editor(v).buf
    command == :redo ? redo!(b) : undo!(b)
    return handled
  end
  nothing
end

# --- the names, the buttons and the whole block -----------------------------------------------

"How wide the names of the tasks are, beside the bars"
names_w(v::ScheduleView) = v.full ? min(NAMES_FULL, window_size(editor(v))[1] * 0.3) : min(NAMES_W, editor(v).width * 0.36)

describe(n::TaskName) = begin
  v = n.of
  i = task_place(v, n.key)
  i === nothing && return Box(width(grow=grow), height(px(TASK_H)))
  t = v.tasks[i]
  on = v.picked == (:task, n.key)
  done = finished(editor(v), t)
  # A task under another, further in, is further in here too
  indent = 12px + 14px * min(t.todo.level ÷ 2, 4)
  # The hours that the page's time logs have for the task show at the end of its name
  minutes = worked(editor(v), t.todo.name)
  hours = minutes > 0 ? (minutes % 60 == 0 ? "$(minutes ÷ 60) h" : "$(round(minutes / 60, digits=1)) h") : ""
  room = names_w(v) - indent - 12px - (done ? 20px : 0px) - (isempty(hours) ? 0px : measure(Face(SANS, "", 11px, colours.dim, false), hours) + 8px)
  Row(width(grow=grow), height(px(TASK_H)), padding(0px, 12px, 0px, indent), child_gap=6px, Alignment.Center, clip=true,
      background(on ? colours.active : hot_row(v) == i ? colours.hover : marked(v, n.key) ? tint(colours.accent, MARK_FILL) : clear),
    (done ? (Icon("check", size=14px, color=colours.string),) : ())...,
    Box(label(elide(t.todo.name, 13px, room), 13px, color=done ? colours.dim : colours.ink)),
    (isempty(hours) ? () : (Box(width(grow=grow)), Box(label(hours, 11px, color=colours.dim))))...)
end

cursor(::TaskName) = :hand

onkey(n::TaskName, ev::KeyPress{Keys.mouse_left}) = begin
  v, w = n.of, ev.window
  focus(chart(v))
  twice = click_twice!(v, num(w.mouse[1]), num(w.mouse[2]))
  v.picked = (:task, n.key)
  i = task_place(v, n.key)
  twice && i !== nothing ? show_line!(editor(v), v.tasks[i].todo.line) : handled
end

toolbar(v::ScheduleView) = begin
  s = v.data
  start = v.asking ?
    (Box(width(6px)), label("Starts on", 12px), Box(width(6px)), field(v, fixed(120px)), Box(width(8px)),
     label("like 16 Nov, then Return", 12px, color=colours.dim)) :
    (button!(v, :start, :start, icon="calendar-event", words="Starts " * Schedules.long(Schedules.origin(s)),
             tip="Change the day that the work starts"),)
  Row(width(grow=grow), height(38px), padding(6px, 0px), child_gap=2px, Alignment.Center, background(colours.block),
    start..., rule(),
    button!(v, :weekends, :weekends, words=s.weekends ? "Every day" : "Weekdays",
            tip=s.weekends ? "Work is done every day. Click to leave out Saturday and Sunday." :
                             "Work is done from Monday to Friday. Click to count Saturday and Sunday too."),
    Row(width(grow=grow), padding(8px, 0px), clip=true, justify=Alignment.End, Box(label(v.said, 12px, color=colours.accent))),
    button!(v, :smaller, (:zoom, 1 / 1.4), icon="zoom-out", tip="Show more days"),
    button!(v, :bigger, (:zoom, 1.4), icon="zoom-in", tip="Show fewer days  pinch, or ⌘ and scroll"),
    button!(v, :fit, :fit, icon="aspect-ratio", tip="Show every task"),
    button!(v, :full, :full, icon=v.full ? "fullscreen-exit" : "arrows-fullscreen", tip=v.full ? "Back to the page  esc" : "Fill the window"))
end

"Do what a button of a schedule does"
act!(v::ScheduleView, action, w) = begin
  a = action isa Tuple ? action[1] : action
  v.said = ""
  if a == :start
    i = schedule_input(v)
    i.color = colours.ink
    i.text = Schedules.long(Schedules.origin(v.data))
    i.anchor, i.cursor = 0, length(i.text)
    v.asking = true
    focus(i)
  elseif a == :weekends
    v.data.weekends = !v.data.weekends
    commit!(v)
  elseif a == :zoom
    zoom_days!(v, action[2], v.box[1] + v.box[3] / 2)
  elseif a == :fit
    fit!(v)
  elseif a == :full
    full!(v, !v.full)
  end
  handled
end

"Take the day that was typed as the day that the work starts, and show every task again"
answer!(v::ScheduleView) = begin
  v.asking || return handled
  d = Schedules.date(schedule_input(v).text)
  d === nothing && return (v.said = "Ladder can't read that day. Type it like 16 Nov 2026."; handled)
  v.data.start = d
  stop_asking!(v)
  commit!(v)
  v.zoom = 0.0
  handled
end

"Take the text field away. The keyboard goes back to the bars."
stop_asking!(v::ScheduleView) = begin
  v.asking = false
  w = window_of(v)
  w !== nothing && w.focus === schedule_input(v) && focus(chart(v))
  handled
end

onkey(v::ScheduleView, ev::KeyPress{Keys.enter}) = unmodified(ev) ? (v.asking ? answer!(v) : nothing) : nothing
onkey(v::ScheduleView, ev::KeyPress{Keys.escape}) = unmodified(ev) ? (v.asking ? stop_asking!(v) : nothing) : nothing

"What happens to a schedule in each frame, before the page is laid out: a drag that ended is written down, and the text field that lost the keyboard closes"
tick!(v::ScheduleView) = begin
  w = window_of(v)
  v.grab !== nothing && !held(v, Keys.mouse_left) && drop!(v)
  # A click somewhere else took the keyboard from the text field. A day that reads is kept.
  if v.asking && w !== nothing && w.focus !== schedule_input(v)
    Schedules.date(schedule_input(v).text) === nothing ? stop_asking!(v) : answer!(v)
  end
  v
end

"Do what each schedule of the page that shows needs in this frame"
schedule_tick!(e) = for (key, node) in collect(e.nodes)
  (node isa ScheduleView && key[2] == e.buf.path) || continue
  tick!(node)
  node.full || continue
  # A schedule whose block has gone goes back to the page. Under one that fills the window, the page stays where it was.
  block_lines(e.buf, SCHEDULE, node.n) === nothing ? (node.full = false) : (e.scroll.offset = node.pinned)
end

describe(v::ScheduleView) = begin
  e = editor(v)
  schedule_input(v).color = colours.ink
  ts = tasks!(v)
  # The names of tasks that the page had once are forgotten
  length(v.parts) > 2length(ts) + 40 && filter!(p -> !(p[1] isa Tuple && p[1][1] == :name) || task_place(v, p[1][2]) !== nothing, v.parts)
  with_theme(component_theme(e.zoom)) do
    # In the page it's a box with round corners. In the window it takes all the room under the top bar.
    look = v.full ? (width(grow=grow), height(grow=grow), Alignment.Start, background(takeoff_back())) :
                    (width(grow=grow), Alignment.Start, radius(8px), border(1px, :solid, colours.line), background(takeoff_back()))
    isempty(ts) && return Column(look..., clip=true, name="Schedule", toolbar(v),
      Row(width(grow=grow), height(64px), padding(16px, 0px), Alignment.Center, clip=true,
          Box(label("This page has no to-do items yet. Start a line with - [ ] to make a task.", 13px, color=colours.dim))))
    names = Column(fixed(names_w(v)), height(chart_h(v)), Alignment.Start, border(1px, :solid, colours.line)[:right],
      Row(width(grow=grow), height(px(DATES_H)), padding(12px, 0px, 9px, 12px), Alignment.End, border(1px, :solid, colours.line)[:bottom],
          Box(label("Task", 11px, color=colours.dim))),
      [part!(() -> TaskName(of=v, key=t.todo.key), v, (:name, t.todo.key)) for t in ts]...)
    rows = Row(width(grow=grow), Alignment.Start, names, chart(v))
    v.full || return Column(look..., clip=true, name="Schedule", toolbar(v), rows)
    # The wheel scrolls through more tasks than the window has room for
    list = get!(() -> Scroll(width(grow=grow), height(grow=grow)), v.parts, :list)
    Column(look..., name="Schedule", toolbar(v), reuse!(list, rows))
  end
end

cursor(::ScheduleView) = :arrow
# A click beside a button is the block's, and takes the keyboard from the text field
onkey(v::ScheduleView, ::KeyPress{Keys.mouse_left}) = (focus(chart(v)); handled)
onmouse(v::ScheduleView, ::MouseMove) = held(v, Keys.mouse_left) ? handled : nothing

# --- a to-do item of a page that has a schedule ------------------------------------------------
#
# A to-do item reads as it always does: a box and its text. While the page has
# a schedule, the item is a task, and the mouse over it shows the task's days
# at the right end of its line: its first and last day, how many working days
# it takes, with a button each side that makes it a day shorter or longer, and
# what it waits for. An item whose lines have no room for them shows them under
# the item.

"The schedule that the page's to-do items are in: the page's first, or nothing when it has none"
page_schedule(e) = begin
  b = e.buf
  readonly(b) && return nothing
  span = block_lines(b, SCHEDULE, 1)
  span === nothing && return nothing
  v = schedule_view(e, 1)
  reread!(v, b.lines[span[1]+1:span[2]-1])
  v
end

"The line of the to-do item whose row of the page is at the place `(x, y)` in the window, or nothing. An item that shows its markup isn't one."
todo_line(e, x, y) = begin
  dx, dy = px(x) - e.origin[1], px(y) - e.origin[2]
  (-30px <= dx < e.width && y >= num(TOPBAR_H)) || return nothing
  dy >= 0px || return nothing
  it = e.layout[item_under(e, dx, dy)]
  f = it.content
  dy < it.top + it.tall && shows_box(f) ? it.first : nothing
end

"""
The days of the to-do item under the mouse, beside the item. They stay while
the mouse is on them, so that their buttons can be clicked.
"""
task_over(e) = begin
  (zooming(e) === nothing && full_block(e) === nothing && e.popup == :none) || return ()
  win = window_of(e)
  (win === nothing || isempty(e.layout) || readonly(e.buf)) && return ()
  d = node!(TaskDetails, e, :task_details)
  x, y = num(win.mouse[1]), num(win.mouse[2])
  on_details = d.of !== nothing && d.box[1] <= x < d.box[1] + d.box[3] && d.box[2] <= y < d.box[2] + d.box[4]
  hide() = (d.of = nothing; ())
  line = on_details ? nothing : ishovered(node!(Document, e, :document)) && !held(e, Keys.mouse_left) ? todo_line(e, x, y) : nothing
  (on_details || line !== nothing) || return hide()
  # A page with a schedule shows the task's days. A page with a time log shows the item's clock.
  v, log = page_schedule(e), page_log(e)
  (v === nothing && log === nothing) && return hide()
  v === nothing || tasks!(v)
  items = page_todos(e)
  i = on_details ? findfirst(t -> t.key == d.key, items) : findfirst(t -> t.line == line, items)
  i === nothing && return hide()
  it = item(e, items[i].line)
  f = it.content
  shows_box(f) || return hide()
  d.of, d.key = something(v, log), items[i].key
  wide = describe(Row(Alignment.Start, geometry(d)), (9999px, 9999px)).width
  # They go at the right end of the first of the item's lines that has room for them, or under the item when none has
  edge = sum(item_room(e, it))   # the right edge of the item's column, or of the page
  k = findfirst(vl -> maximum(seg -> seg.x + seg.w, vl.segs, init=0px) + 24px + wide <= edge, f.lines)
  d.floats = k === nothing
  vl = f.lines[something(k, length(f.lines))]
  left = e.origin[1] + edge - wide
  top = e.origin[2] + it.top + f.above + vl.top
  top = d.floats ? top + vl.high - 2px : top + (vl.high - DETAILS_H) / 2
  top >= TOPBAR_H || return hide()
  d.box = (num(left), num(top), num(wide), num(DETAILS_H))
  (Row(width(grow=grow), height(grow=grow), Alignment.Start, padding(top, 0px, 0px, left), d),)
end

describe(d::TaskDetails) = begin
  e = editor(d)
  v = d.of isa ScheduleView ? d.of : nothing
  i = v === nothing ? nothing : task_place(v, d.key)
  # On a page with a time log, the item has a button that starts and stops the log's clock on it
  clock = page_log(e) === nothing || todo_called(e, d.key) === nothing ? () :
    ((c = node!(ItemClock, e, :item_clock); c.key = d.key; c.parent === d || setfield!(c, :parent, d); c),)
  (i === nothing && isempty(clock)) && return Box(width(0px), height(DETAILS_H))
  dot() = Box(label("·", 12px, color=colours.faint))
  # Under the line, they float over the text of the next line
  look = d.floats ? (background(colours.float), border(1px, :solid, colours.line), lifted) : (background(colours.bg),)
  i === nothing && return Row(height(DETAILS_H), padding(8px, 0px), child_gap=6px, Alignment.Center, radius(6px), look..., name="Task", clock...)
  t = v.tasks[i]
  d.less === nothing && (d.less = own!(d, DayButton(by=-1)); d.more = own!(d, DayButton(by=1)))
  first_name = isempty(t.after) ? "" : v.tasks[t.after[1]].todo.name
  waits = isempty(t.after) ? "" : length(t.after) > 1 ? "after $(length(t.after)) tasks" :
          "after " * (length(first_name) > 30 ? first(first_name, 29) * "…" : first_name)
  Row(height(DETAILS_H), padding(8px, 0px), child_gap=6px, Alignment.Center, radius(6px), look..., name="Task",
    Icon("calendar-event", size=12px, color=colours.dim), Box(label(task_days(t), 12px, color=colours.dim)), dot(),
    d.less, Box(label(Schedules.days_text(t.days), 12px)), d.more,
    (isempty(waits) ? () : (dot(), Box(label(waits, 12px, color=colours.dim))))...,
    (isempty(clock) ? () : (dot(), clock...))...)
end

cursor(::TaskDetails) = :arrow
# A click beside a button does nothing, and doesn't move the caret
onkey(::TaskDetails, ::KeyPress{Keys.mouse_left}) = handled
onmouse(::TaskDetails, ::MouseMove) = handled

"The task that the details `d` show, or nothing when the page has it no more"
task_of(d::TaskDetails) = (i = d.of isa ScheduleView ? task_place(d.of, d.key) : nothing; i === nothing ? nothing : d.of.tasks[i])

describe(b::DayButton) = begin
  t = task_of(b.parent)
  off = b.by < 0 && (t === nothing || t.days <= 1)
  Box(width(18px), height(18px), radius(4px), Alignment.Center, justify=Alignment.Center, name="Button",
      background(ishovered(b) && !off ? colours.hover : clear),
    Icon(b.by < 0 ? "dash" : "plus", size=13px, color=off ? colours.faint : colours.dim))
end

cursor(::DayButton) = :hand
draw(ctx, size, ui::ConcreteRect, b::DayButton) = (b.rect = (ui.left, ui.top, ui.width, ui.height); nothing)

onmouse(b::DayButton, ev::MouseMove) = begin
  show_tooltip!(ev.window, tip_label(b.by < 0 ? "A day shorter" : "A day longer"), b.rect..., placement=:top, gap=6px)
  handled
end

onkey(b::DayButton, ev::KeyPress{Keys.mouse_left}) = begin
  d = b.parent
  t = task_of(d)
  hide_tooltip!(ev.window)
  (t === nothing || t.days + b.by < 1) && return handled
  Schedules.days!(d.of.data, t, t.days + b.by)
  commit!(d.of)
  handled
end

# --- a picture, a diagram or a page that fills the window ---------------------------------
#
# While the mouse is over a picture, a diagram, a page of a PDF file, a model or
# a video, a button shows beside its top right corner, so it covers none of it.
# The button makes it fill the window, over the page and under the top bar.
# Esc, or the button with a cross, puts the page back where it was.
#
#   - A picture, a diagram and a page of a PDF file fit the window at first.
#     Pinch, or scroll with ⌘ held, to make one bigger or smaller round the
#     mouse. ⌘+, ⌘- and the buttons under it do the same, and ⌘0 fits it to
#     the window again. Drag it, or scroll, to move it.
#   - A pinch outwards on a picture, a diagram or a page in the page makes it
#     fill the window too.
#   - ← and → go to the page before and the next page of a PDF file. The page
#     that shows in the document goes on from the page you looked at.
#   - A model and a video only fill the window. A model turns and zooms there
#     as it does in the page, and a video plays on.
#   - A diagram of a `mermaid` block can be changed while it fills the window.
#     A click selects a box, a line or another part of it, and two clicks let
#     you type its words where they are. A drag moves the diagram, as before.
#     The first buttons under it are the tools for the part that's selected,
#     or for the whole diagram: add a box, draw a line to the box that's
#     clicked next, change a shape, take the part away. ⌫ takes it away too.
#     Each change is written in the lines of the block, and ⌘Z takes it back.
#     With a part selected, Esc selects nothing, and the next Esc puts the
#     page back.
#
# A diagram is drawn again at each size, so it's sharp however big it is, and so
# is a page of a PDF file once it stops moving. A picture is as sharp as its pixels.

const ZOOM_EDGE = 24.0   # px of room round a picture that fits the window
const BAR_ROOM = 64px    # the bottom of the window, where the bar of buttons is
const MODEL_FOOT = 34px  # how tall the line under a model is, which says what the model is
const MOST_ZOOM = 8.0    # the biggest a picture gets: this many times its own size, or the size that fits the window if that's bigger
const ZOOM_STEP = 1.25   # how much bigger the + button, and ⌘+, make a picture
"The commands that do what they always do while a picture fills the window. The rest would change the page under it."
const PAGE_COMMANDS = (:save, :open, :open_project, :print, :close, :settings, :sidebar, :sidebar_keys)

"What fills the window, over the page"
@def mutable struct ZoomView <: SemanticUI
  what::Any = nothing                       # (:picture, key), (:diagram, code), (:pdf, path, page) or (:node, node). Nothing while the page shows.
  path::String = ""                         # the document it was opened from. It closes when another document shows.
  from::Any = nothing                       # the node of the page that it was opened from
  page::Int = 1                             # of a PDF file
  pages::Int = 1
  zoom::Float64 = 0.0                       # px of the window to a px of the picture at its own size. 0 fits it to the window.
  at::Tuple{Float64,Float64} = (0.0, 0.0)   # the point of the picture at the view's top left
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the view is in the window: its left, top, width and height
  fits::Bool = true                         # it shows the whole picture, so it fits the window again when the window changes size
  grab::Any = nothing                       # where a drag started, and the point of the picture that was at the view's top left then
  moved::Float64 = 0.0                      # when the view last moved
  sharp::Sharp = Sharp(nothing, C_NULL, 1.0)
  drawn::Any = nothing                      # a diagram laid out at its own size, with what it was laid out for
  home::Any = nothing                       # how tall a model or a video was in the page
  held::px = 0px                            # the room that a model or a video took in the page, which the page keeps for it
  pinned::px = 0px                          # how far the page was scrolled
  block::Int = 0                            # which `mermaid` block of the page its diagram is, so that it can be changed. 0 for a diagram that can't.
  tool::Any = nothing                       # the tool of its diagram that waits for a click, whose button is lit
  parts::Dict{Any,Any} = Dict{Any,Any}()    # its buttons and its area, kept between frames
  screen::Bool = false                      # its video fills the screen: the window is full screen, and the video is all that it shows
  was_full::Bool = false                    # the window filled its screen before the video did, so it stays so after
  screen_at::Float64 = 0.0                  # when the video began to fill the screen
  bare::Bool = false                        # it's the page of a file itself: it has no room round it and nothing closes it. See `file_zoom`.
  read::Float64 = -1.0                      # when the file of such a page had last changed, the last time it was looked at
end

"The part of a ZoomView that shows the picture. It takes the mouse and the keys."
@def mutable struct ZoomArea <: SemanticUI
  of::Any = nothing
end

"""
A picture, a diagram, a page, a model or a video in the page that can fill the
window. It's a node of its own so that the window knows where it is, to put
its button beside it.
"""
@def mutable struct Fillable <: SemanticUI
  what::Any = nothing      # what fills the window. See ZoomView.
  content::Any = nothing   # what shows in the page
  sizing::Any = ()         # how wide it is
  button::Any = nothing       # its FillButton, once it has shown
  transcript::Any = nothing   # a video's TranscriptButton, once it has shown
  also::Any = nothing         # what fills the window too, for a `view` block: its first button fills the window with this, and its second goes to its file
  expand::Any = nothing       # the FillButton for `also`, once it has shown
end

"The button beside the top right corner of a Fillable that makes it fill the window"
@def mutable struct FillButton <: SemanticUI
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)   # where it was last drawn, to put its tooltip under it
  quiet::Bool = false                         # clicked, so no tooltip until the mouse leaves it
  also::Bool = false                          # it's for its Fillable's `also`, not for its `what`
end

"What the button `b` does: what it makes fill the window, or `(:go, path)` for the file that it goes to"
button_what(b::FillButton) = b.also ? b.parent.also : b.parent.what

const FILL_SIDE = 24px   # how wide and how tall the button is that makes a picture fill the window
const FILL_GAP = 4px     # between that button and the picture, and between it and the window's edge

"""
A small square button with a line round it and the icon `icon`, like the one
that makes a picture fill the window. `lit` while the mouse is over it, or
while what it opens is open.
"""
square_button(icon, lit) =
  Box(width(FILL_SIDE), height(FILL_SIDE), radius(6px), Alignment.Center, justify=Alignment.Center, name="Button",
      background(lit ? colours.hover : colours.float), border(1px, :solid, colours.line),
    Icon(icon, size=12px, color=colours.dim))

"A part of `v` that's kept between frames"
part!(make, v::ZoomView, key) = begin
  node = get!(make, v.parts, key)
  node.parent === nothing && setfield!(node, :parent, v)
  node
end

"The ZoomView of `e` while it fills the window, or nothing"
zooming(e) = (v = get(e.nodes, :zoom, nothing); v === nothing || v.what === nothing ? nothing : v)

"True when `a` and `b` say the same thing fills the window. A node is the same node, not one like it."
same_what(a, b) = a !== nothing && b !== nothing && a[1] == b[1] && (a[1] == :node ? a[2] === b[2] : a == b)

"True when `node`, a model or a video, fills the window now"
zoomed_node(e, node) = (v = zooming(e); v !== nothing && v.what[1] == :node && v.what[2] === node)

"The empty room that the page keeps for the model or the video that fills the window"
held_room(e) = Box(width(grow=grow), height(zooming(e).held))

"What fills the window when you click the button over `x`, a node that a live block made, or nothing if it has no button"
fill_what(x) = x isa Mermaid ? (isdiagram(x.code) ? (:diagram, x.code) : nothing) : x isa Union{STLViewer,VideoPlayer} ? (:node, x) : nothing

"How wide `x` is at most in the page, for the button over its top right corner: a width, or :grow when it's as wide as the page"
fill_wide(x) = x isa VideoPlayer ? video_wide(x) : x isa Mermaid && x.made !== nothing && hasproperty(x.made[2], :w) ? px(x.made[2].w) : :grow

"How wide the picture of a video is at most: as wide as a picture of its height is, as VideoPlayer works it out"
video_wide(p::VideoPlayer) = begin
  s = p.media === nothing ? (0.0, 0.0) : picture_size(p.media)
  s[1] > 0 && s[2] > 0 ? max(240px, p.height * s[1] / s[2]) : :grow
end

"The Fillable of each node of the page that shows one, by the node"
fills(e) = get!(Dict{UInt,Fillable}, e.nodes, :fills)

"""
`content`, which `owner` shows, as a Fillable: while the mouse is over it, a
button beside it makes `what` fill the window. `wide` is how wide the content
is at most: a width, :grow for content that's as wide as the room it's given,
or nothing for content of a fixed size. A model or a video that fills the
window now leaves its room empty.
"""
fillable(owner, what, content; wide=nothing) = begin
  e = editor(owner)
  what[1] == :node && zoomed_node(e, what[2]) && return held_room(e)
  f = get!(() -> own!(owner, Fillable()), fills(e), objectid(owner))
  f.what, f.content, f.also = what, content, nothing
  f.sizing = wide === nothing ? () : wide === :grow ? (width(grow=grow),) : (width(grow=grow, max=wide),)
  f
end

describe(f::Fillable) = Box(f.sizing..., Alignment.Start, f.content isa GeometricUI ? detach!(f.content) : f.content)

"""
Where the button of a picture that's at `r` in the window goes: beside its top
right corner, so it covers none of the picture. Where the window has no room
there, it's beside the top left corner, and where there's room on neither
side, it's in the top right corner. It stays under the top bar.
"""
fill_spot(e, r) = begin
  w, _ = window_size(e)
  top = min(max(r.top, TOPBAR_H + FILL_GAP), r.top + r.height - FILL_SIDE)
  right = r.left + r.width + FILL_GAP
  right + FILL_SIDE <= w - FILL_GAP && return (right, top)
  left = r.left - FILL_GAP - FILL_SIDE
  left >= panel_w(e) * opened(e) + FILL_GAP && return (left, top)
  (right - 2FILL_GAP - FILL_SIDE, top + FILL_GAP)
end

"The video player that `f` shows, or nothing when it shows something else"
video_of(f::Fillable) = f.what !== nothing && f.what[1] == :node && f.what[2] isa VideoPlayer ? f.what[2] : nothing

"How tall the buttons beside `f` are: a video has the button that shows what was said in it under the first"
buttons_tall(f::Fillable) = video_of(f) === nothing && f.also === nothing ? FILL_SIDE : 2FILL_SIDE + FILL_GAP

# The buttons beside a picture are put in place before the frame's layout, so
# `rect` gives where the last frame put the picture. A scroll of the page since
# then moves the picture as far, so the buttons move with it in the same frame.
# Anything else that moved the picture, like a block above it that grew, puts
# the buttons right on the next frame, which comes at once.

"The scroll of the page that the last layout used, which the draw of the page keeps"
draw(ctx, size, ui::ConcreteRect, p::Page) = begin
  e = editor(p)
  e.nodes[:laid_scroll] = e.scroll.offset
  nothing
end

"True when `node` is a part of the page of `e`, so it moves when the page scrolls"
scrolls_with_page(e, node) = begin
  doc = get(e.nodes, :document, nothing)
  while node isa SemanticUI && !(node isa Editor)
    node === doc && return true
    node = getfield(node, :parent)
  end
  false
end

"Where `f` is in the window in this frame: where the last layout put it, moved as far as the page has scrolled since"
fill_rect(e, f::Fillable) = begin
  r = rect(f)
  r === nothing && return nothing
  moved = get(e.nodes, :laid_scroll, e.scroll.offset) - e.scroll.offset
  (moved == 0px || !scrolls_with_page(e, f)) && return r
  (left=r.left, top=r.top + moved, width=r.width, height=r.height)
end

"The picture that has the buttons beside it draws again at once when it isn't where they were put for it"
draw(ctx, size, ui::ConcreteRect, f::Fillable) = begin
  at = get(editor(f).nodes, :fill_at, nothing)
  (at === nothing || at[1] !== f) && return
  r = at[2]
  abs(num(ui.left - r.left)) + abs(num(ui.top - r.top)) + abs(num(ui.width - r.width)) + abs(num(ui.height - r.height)) > 0.5 &&
    redraw_in!(f, 0)
  nothing
end

"""
The button that makes the picture under the mouse fill the window, beside it.
A video has a button under that one, which shows what was said in the video.
They show while the mouse is over the picture or the buttons, or between them,
and while the drop-down of what was said is open.
"""
fill_over(e) = begin
  e.nodes[:fill_at] = nothing
  (zooming(e) === nothing && full_block(e) === nothing && e.popup == :none) || return ()
  win = window_of(e)
  win === nothing && return ()
  x, y = num(win.mouse[1]), num(win.mouse[2])
  # A picture under a path is in a live block that can fill the window too, so the smallest one under the mouse has the button
  best, spot, least, at = nothing, nothing, Inf, nothing
  for f in values(fills(e))
    r = fill_rect(e, f)
    (r === nothing || button_above(f)) && continue
    s = fill_spot(e, r)
    if f.transcript !== nothing && f.transcript.open
      best, spot, at = f, s, r
      break
    end
    num(min(r.left, s[1])) <= x < num(max(r.left + r.width, s[1] + FILL_SIDE)) || continue
    num(min(r.top, s[2])) <= y < num(max(r.top + r.height, s[2] + buttons_tall(f))) || continue
    area = num(r.width) * num(r.height)
    area < least && ((best, spot, least, at) = (f, s, area, r))
  end
  e.nodes[:fill_at] = best === nothing ? nothing : (best, at)
  best === nothing && return ()
  b = best.button === nothing ? (best.button = own!(best, FillButton())) : best.button
  buttons = Any[b]
  # A `view` block has two: the first makes what it shows fill the window, and the second goes to its file
  if best.also !== nothing
    best.expand === nothing && (best.expand = own!(best, FillButton(also=true)))
    pushfirst!(buttons, best.expand)
  end
  if video_of(best) !== nothing
    best.transcript === nothing && (best.transcript = own!(best, TranscriptButton()))
    push!(buttons, best.transcript)
  end
  (Row(width(grow=grow), height(grow=grow), Alignment.Start, padding(spot[2], 0px, 0px, spot[1]),
     Column(Alignment.Start, child_gap=FILL_GAP, buttons...)),)
end

"""
True when a part that holds the Fillable `f`, like a `view` block, has a
button of its own beside it that stands for all that's in it. Then `f` shows
no button.
"""
button_above(f::Fillable) = begin
  n = f.parent === nothing ? nothing : f.parent.parent
  while n !== nothing
    own_button(n) && return true
    n = hasproperty(n, :parent) ? n.parent : nothing
  end
  false
end

"True when the node `n` has a button beside it that stands for all that's in it. A `view` block's goes to its file."
own_button(n) = false

# A `view` block has a button that goes to its file, `(:go, path)`. The rest make what they show fill the window.
describe(b::FillButton) = begin
  ishovered(b) || (b.quiet = false)
  square_button(button_what(b)[1] == :go ? "arrow-up-right" : "arrows-fullscreen", ishovered(b))
end

cursor(::FillButton) = :hand
draw(ctx, size, ui::ConcreteRect, b::FillButton) = (b.rect = (ui.left, ui.top, ui.width, ui.height); nothing)

onmouse(b::FillButton, ev::MouseMove) = begin
  b.quiet && return handled
  what = button_what(b)
  tip = what[1] == :go ? "Go to " * view_name(what[2]) : what[1] == :node ? "Fill the window" : "Fill the window  pinch"
  # The tooltip of one of two buttons goes beside it, so that it doesn't cover the other button
  show_tooltip!(ev.window, tip_label(tip), b.rect...,
                placement=video_of(b.parent) === nothing && b.parent.also === nothing ? :bottom : :right, gap=6px)
  handled
end

onkey(b::FillButton, ev::KeyPress{Keys.mouse_left}) = begin
  b.quiet = true
  hide_tooltip!(ev.window)
  f = b.parent
  fill_window!(editor(b), button_what(b), f.parent)
end

"""
Make `what`, which a Fillable of the node `from` shows, fill the window. A
block like a sketch, `(:block, view)`, fills it by itself. The rest fill the
ZoomView. A `view` block's `(:go, path)` goes to its file instead.
"""
fill_window!(e, what, from) = what[1] == :block ? full!(what[2], true) : what[1] == :go ? go_view!(from) : zoom_in!(e, what, from)

"A pinch outwards on a picture, a diagram, a page or a sketch in the page makes it fill the window"
pinch_open(owner, ev::Pinch) = begin
  ev.scale > 1 || return nothing
  e = editor(owner)
  f = get(fills(e), objectid(owner), nothing)
  (f === nothing || f.what === nothing || f.what[1] in (:node, :go)) && return nothing
  # Only when the fingers are on the picture, not beside it
  r = rect(f)
  x, y = num(ev.window.mouse[1]), num(ev.window.mouse[2])
  (r !== nothing && num(r.left) <= x < num(r.left + r.width) && num(r.top) <= y < num(r.top + r.height)) || return nothing
  fill_window!(e, f.what, owner)
end

onpinch(s::Shown, ev::Pinch) = pinch_open(s, ev)
onpinch(p::Pages, ev::Pinch) = pinch_open(p, ev)
onpinch(v::FileView, ev::Pinch) = pinch_open(v, ev)
onpinch(l::Breadcrumb, ev::Pinch) = pinch_open(l, ev)

"Make `what` fill the window. `from` is the node of the page that shows it."
zoom_in!(e, what, from=nothing) = begin
  v = node!(ZoomView, e, :zoom)
  # A pinch goes on to the page until the next frame is drawn, so it would open it again
  same_what(v.what, what) && return handled
  zoom_out!(v, false)
  v.what, v.path, v.from, v.pinned = what, e.buf.path, from, e.scroll.offset
  v.zoom, v.fits, v.grab, v.drawn = 0.0, true, nothing, nothing
  v.block, v.tool = 0, nothing
  delete!(v.parts, :diagram)
  if what[1] == :diagram
    # The diagram of a `mermaid` block can be changed here. One that the code of a live block made has no lines of its own.
    from !== nothing && get(e.nodes, (:diagram, what[2]), nothing) === from && !readonly(e.buf) && (v.block = diagram_block(e.buf, what[2]))
  elseif what[1] == :pdf
    v.page, v.pages = what[3], max(1, pdf_pages(what[2]))
  elseif what[1] == :node
    r = rect(what[2])
    # A model fills the window with no frame, so it has that to get back too. A page of the web is sized by its block.
    v.home = what[2] isa Union{STLViewer,Designs.DesignView} ? (what[2].height, what[2].fill) : what[2] isa Browsers.Browser ? nothing : what[2].height
    v.held = r !== nothing ? r.height : what[2] isa Browsers.Browser ? what[2].high : what[2].height
  end
  # A page of the web has the keyboard, for its fields and its keys. Esc comes back from it when the page doesn't take it.
  what[1] == :node && what[2] isa Browsers.Browser ? focus(what[2]) : focus(part!(() -> ZoomArea(of=v), v, :area))
  handled
end

"True while a video fills the screen"
screening(e) = (v = zooming(e); v !== nothing && v.screen)

"""
Make the video that fills the window fill the screen, or with `on` false put
it back to filling the window. The window fills a screen of its own, as the
green button of its title bar makes it, and the video is all that it shows:
black is round the picture, and the top bar is gone. The video's controls lie
over the foot of the picture while the mouse moves. A window that filled its
screen before stays so after.
"""
screen!(v::ZoomView, on::Bool) = begin
  what = v.what
  (what !== nothing && what[1] == :node && what[2] isa VideoPlayer) || return handled
  v.screen == on && return handled
  v.screen = what[2].screen = on
  w = window_of(editor(v))
  if w !== nothing
    if on
      v.was_full = fills_screen(w)
      v.screen_at = time()
      fill_screen!(w, true)
    else
      v.was_full || fill_screen!(w, false)
    end
  end
  on && (what[2].stirred = time())   # its controls show at first
  handled
end

"Make the video `p`, which the node `from` shows in the page, fill the screen"
screen_video!(e, p::VideoPlayer, from=nothing) = (zoom_in!(e, (:node, p), from); screen!(node!(ZoomView, e, :zoom), true))

"Put the page back, with a model or a video back in it. `refocus` gives the keyboard back to the text."
zoom_out!(v::ZoomView, refocus=true) = begin
  what = v.what
  what === nothing && return handled
  v.screen && screen!(v, false)   # a video that filled the screen leaves it
  # Words that were being typed into a diagram are taken
  m = changing(v)
  m === nothing || Diagrams.settle!(m)
  v.what = nothing
  what[1] == :node && v.home !== nothing && (v.home isa Tuple ? ((what[2].height, what[2].fill) = v.home) : (what[2].height = v.home))
  # A video of a gallery shows only while it fills the window, so it stops when it leaves
  what[1] == :node && what[2] isa VideoPlayer && v.from isa GalleryView && pause!(what[2])
  v.from isa Pages && (v.from.page = v.page)   # the page in the document goes on from the page you looked at
  v.from = nothing
  e = editor(v)
  e.scroll.offset = v.pinned
  refocus && focus(e)
  handled
end

"In each frame: the page comes back when another document shows, and until then it stays where it was"
zoom_tick!(e) = begin
  v = zooming(e)
  v === nothing && return
  v.path == e.buf.path || return zoom_out!(v, false)
  e.scroll.offset = v.pinned
  # The mouse button that started a drag has come up
  w = window_of(e)
  v.grab === nothing || w === nothing || Keys.mouse_left in w.keys || let_go!(v, w)
  # A window that left its screen another way, as the green button does, has its video fill the window again.
  # macOS takes a moment to make a window fill a screen, so the first seconds don't count.
  v.screen && w !== nothing && !isempty(w.glfw) && time() - v.screen_at > 2 && !fills_screen(w) && screen!(v, false)
  m = changing(v)
  if m !== nothing && w !== nothing
    m.joining === nothing || Keys.mouse_left in w.keys || Diagrams.let_go_at!(m, picture_spot(v, w.mouse)...)
    # A box shows its point only while the mouse is over the diagram, and not over the buttons under it
    m.hovered === nothing || ishovered(part!(() -> ZoomArea(of=v), v, :area)) || Diagrams.unhover!(m)
  end
  v.what === nothing && return
  if v.what[1] == :diagram && v.block > 0
    # The diagram is what the lines of its block say now. They change under it when ⌘Z takes a change back.
    code = diagram_code(e.buf, v.block)
    (code === nothing || !isdiagram(code)) && return zoom_out!(v, false)
    code == v.what[2] || (v.what = (:diagram, code); refit!(v))
  end
  nothing
end

"The code of the `n`th `mermaid` block of `b`, or nothing when it has no such block"
diagram_code(b::Buffer, n::Int) = begin
  span = block_lines(b, DIAGRAM, n)
  span === nothing ? nothing : join(b.lines[span[1]+1:span[2]-1], "\n")
end

"Which `mermaid` block of `b` has the code `code`: the first one that does, or 0"
diagram_block(b::Buffer, code) = begin
  n = 1
  while (found = diagram_code(b, n)) !== nothing
    found == code && return n
    n += 1
  end
  0
end

"The diagram of `v` as the component that changes it, or nothing when `v` shows something else or a diagram that can't be changed"
changing(v::ZoomView) = begin
  (v.what !== nothing && v.what[1] == :diagram && v.block > 0) || return nothing
  m = get(v.parts, :diagram, nothing)
  m !== nothing && m.editing ? m : nothing
end

"A diagram that fitted the window fits it again after a change, which gives it another size"
refit!(v::ZoomView) = (v.fits && (v.zoom = 0.0); v)

"""
Write the code of the diagram that fills the window as the lines of its block.
The caret stays where it was in the text, and ⌘Z takes the change back.
"""
write_diagram!(v::ZoomView, code::String) = begin
  e = editor(v)
  b = e.buf
  span = block_lines(b, DIAGRAM, v.block)
  (span === nothing || readonly(b)) && return v
  i, t = span
  new, old = String.(split(code, '\n')), b.lines[i+1:t-1]
  if new != old
    caret, anchor = b.caret, b.anchor
    edit!(b, line_end(b, i), line_end(b, t - 1), "\n" * join(new, "\n"))
    by = length(new) - length(old)
    moved(p) = p[1] >= t ? (p[1] + by, p[2]) : p[1] > i ? (i, 0) : p
    b.caret, b.anchor = moved(caret), moved(anchor)
  end
  v.what = (:diagram, code)
  refit!(v)
end

"What fills the window, over the page and the sidebar and under the top bar"
zoom_over(e) = zooming(e) === nothing ? () :
  # A video that fills the screen has the top bar's room too, and black round it
  screening(e) ? (Box(width(grow=grow), height(grow=grow), background(RGBA(0, 0, 0, 1)), geometry(e.nodes[:zoom])),) :
  (Box(width(grow=grow), height(grow=grow), padding(TOPBAR_H, 0px, 0px, 0px), background(colours.bg), geometry(e.nodes[:zoom])),)

"The button of `v` that's kept under `key`, with what it does and shows now"
button!(v::ZoomView, key, action; icon="", tip="", off=false) = begin
  b = part!(() -> PlanButton(of=v), v, (:button, key))
  b.action, b.icon, b.tip, b.off = action, icon, tip, off
  b
end

"Do what a button of a ZoomView does"
act!(v::ZoomView, action, w) = begin
  a = action isa Tuple ? action[1] : action
  a == :tool && return use_tool!(v, action[2], w)
  a == :zoom && return zoom_by!(v, action[2], view_middle(v)...)
  a == :fit && return fit_now!(v)
  a == :page && return turn!(v, action[2])
  a == :close && return zoom_out!(v)
  a == :screen && return screen!(v, !v.screen)
  handled
end

describe(v::ZoomView) = begin
  e = editor(v)
  what = v.what
  bar(buttons...; up=0px) = Column(width(grow=grow), height(grow=grow), Alignment.Center, justify=Alignment.End, padding(0px, 0px, 16px + up, 0px),
    Row(height(36px), padding(4px), child_gap=2px, radius(8px), Alignment.Center, background(colours.float),
        border(1px, :solid, colours.line), lifted, buttons...))
  close = v.bare ? nothing : button!(v, :close, :close, icon="x-lg", tip="Back to the page  esc")
  if what[1] == :node && what[2] isa Browsers.Browser
    # A page of the web has all of the window under the top bar, as it has a browser's window. Nothing lies over it:
    # Esc puts the document back.
    b = what[2]
    w, h = window_size(e)
    b.zoom = round(Float64(e.zoom), digits=2)
    b.wide, b.high = w, max(40px, h - TOPBAR_H)
    return Stack(width(grow=grow), height(grow=grow), Alignment.Start, b)
  elseif what[1] == :node && what[2] isa Designs.DesignView
    # A SolidCraft design that's only shown has all of the window under the top bar, as a model has. Esc puts the document back.
    node = what[2]
    node.fill = true
    shows = with_theme(() -> geometry(node), component_theme(e.zoom))
    return Stack(width(grow=grow), height(grow=grow), Alignment.Start, Box(width(grow=grow), height(grow=grow), shows))
  elseif what[1] == :node && what[2] isa STLViewer
    # A model has all of the window under the top bar too, with no frame, and nothing lies over it: Esc puts the document
    # back. Only a model of a gallery has a bar, to go to the file before it and the next one. It's above the line that
    # says what the model is, if the model has that line.
    node = what[2]
    node.fill = true
    shows = with_theme(() -> geometry(node), component_theme(e.zoom))
    steps = gallery_buttons(v, rest=100)
    return Stack(width(grow=grow), height(grow=grow), Alignment.Start, Box(width(grow=grow), height(grow=grow), shows),
      gallery_edges(v)..., (isempty(steps) ? () : (bar(steps..., close, up=node.foot ? MODEL_FOOT : 0px),))...)
  elseif what[1] == :node
    # A model or a video is as tall as the window has room for. Its own bar is under its picture.
    node = what[2]
    _, h = window_size(e)
    if v.screen
      # A video that fills the screen is as tall as the window. Its two buttons are in the top right corner, while it shows its own controls.
      node.height = h
      shows = with_theme(() -> geometry(node), component_theme(e.zoom))
      corner = controls_show(node) ?
        (Column(width(grow=grow), height(grow=grow), Alignment.End, padding(16px),
           Row(height(36px), padding(4px), child_gap=2px, radius(8px), Alignment.Center, background(colours.float), border(1px, :solid, colours.line),
               button!(v, :screen, :screen, icon="fullscreen-exit", tip="Back to the window  F"), close)),) : ()
      return Stack(width(grow=grow), height(grow=grow), Alignment.Start,
        Box(width(grow=grow), height(grow=grow), background(RGBA(0, 0, 0, 1)), shows), corner...)
    end
    node.height = max(160px, h - TOPBAR_H - BAR_ROOM - px(2ZOOM_EDGE) - 44px)
    shows = with_theme(() -> geometry(node), component_theme(e.zoom))
    # A video has a button that makes it fill the screen
    buttons = node isa VideoPlayer ? (button!(v, :screen, :screen, icon="arrows-fullscreen", tip="Fill the screen  F"), close) : (close,)
    # A video or a model of a gallery says where it is in the gallery, with a button to each side
    return Stack(width(grow=grow), height(grow=grow), Alignment.Start,
      Column(width(grow=grow), height(grow=grow), Alignment.Center, padding(px(ZOOM_EDGE)), shows),
      gallery_edges(v)..., bar(gallery_buttons(v, rest=60 + 40length(buttons))..., buttons...))
  end
  what[1] == :diagram && lay_diagram!(v)
  # The view is the whole window under the top bar, so it's fitted here, and the bar says how big the picture is in this frame.
  # The page of a file itself is beside the sidebar, where it was drawn last.
  w, h = window_size(e)
  place = v.bare ? rect(part!(() -> ZoomArea(of=v), v, :area)) : nothing
  v.bare || reframe!(v, (0.0, num(TOPBAR_H), num(w), num(h) - num(TOPBAR_H)))
  place === nothing || reframe!(v, (num(place.left), num(place.top), num(place.width), num(place.height)))
  buttons = Any[diagram_buttons(v)..., button!(v, :smaller, (:zoom, 1 / ZOOM_STEP), icon="zoom-out", tip="Smaller  pinch, or ⌘ and scroll"),
                Box(width(46px), Alignment.Center, justify=Alignment.Center,
                    label(v.zoom > 0 ? "$(round(Int, 100v.zoom))%" : "", 12px, color=colours.dim)),
                button!(v, :bigger, (:zoom, ZOOM_STEP), icon="zoom-in", tip="Bigger  pinch, or ⌘ and scroll"),
                button!(v, :fit, :fit, icon="aspect-ratio", tip="Fit the window  ⌘0")]
  pages = what[1] == :pdf && v.pages > 1
  # A file of a gallery says where it is in the gallery, with a button to each side
  prepend!(buttons, gallery_buttons(v, rest=pages ? 450 : 281))
  if pages
    # In a gallery, ← and → go to the file before and the next one, so ↑ and ↓ turn the pages
    before, next = v.from isa GalleryView ? ("↑", "↓") : ("←", "→")
    push!(buttons, button!(v, :back, (:page, -1), icon="chevron-left", tip="The page before  $before", off=v.page <= 1),
          Box(Alignment.Center, padding(4px, 0px), label("Page $(v.page) of $(v.pages)", 12px, color=colours.dim)),
          button!(v, :on, (:page, 1), icon="chevron-right", tip="The next page  $next", off=v.page >= v.pages))
  end
  v.bare || push!(buttons, close)
  # On the page of a file itself the bar lies over the foot of the picture, so it shows only while the mouse is near it
  Stack(width(grow=grow), height(grow=grow), Alignment.Start, part!(() -> ZoomArea(of=v), v, :area), gallery_edges(v)...,
        (!v.bare || bar_near(v) ? (bar(buttons...),) : ())...)
end

const BAR_NEAR = 110.0   # px from the bottom of a file's own page within which the mouse brings its bar of buttons

"True while the mouse is over the foot of the view, where the bar of buttons is"
bar_near(v::ZoomView) = begin
  w = window_of(editor(v))
  w === nothing && return false
  x, y = num(w.mouse[1]), num(w.mouse[2])
  left, top, wide, tall = v.box
  left <= x < left + wide && top + tall - BAR_NEAR <= y < top + tall
end

describe(::ZoomArea) = Box(width(grow=grow), height(grow=grow))
# While a tool of the diagram waits for a click on a part, the mouse is a cross
# While a tool of the diagram waits for a click on a part, or a line is dragged from a box's point, the mouse is a cross
cursor(a::ZoomArea) = begin
  m = changing(a.of)
  a.of.tool !== nothing || (m !== nothing && (m.joining !== nothing || m.on_point)) ? :crosshair : :arrow
end

"""
The buttons of the tools of the diagram that fills the window, with a line
after them: the tools for the part that's selected, or for the whole diagram
while nothing is. A diagram that can't be changed has none.
"""
diagram_buttons(v::ZoomView) = begin
  m = changing(v)
  m === nothing && return ()
  # The caret in the words that are typed into the diagram blinks
  m.typing === nothing || redraw_in!(v, 0.5)
  v.tool = m.waiting
  tools = Diagrams.tools(m)
  isempty(tools) && return ()
  (Any[button!(v, (:tool, t.name), (:tool, t.name), icon=t.icon, tip=t.tip) for t in tools]...,
   Box(width(9px), height(18px), Alignment.Center, justify=Alignment.Center, Box(width(1px), height(18px), background(colours.line))))
end

"Use the tool `name` of the diagram that fills the window. A tool with choices shows them in a menu over its button first."
use_tool!(v::ZoomView, name, w) = begin
  m = changing(v)
  m === nothing && return handled
  i = findfirst(t -> t.name == name, Diagrams.tools(m))
  i === nothing && return handled
  tool = Diagrams.tools(m)[i]
  isempty(tool.choices) && return (Diagrams.use!(m, name); handled)
  b = get(v.parts, (:button, (:tool, name)), nothing)
  left, top = b === nothing ? (w.mouse[1], w.mouse[2]) : (b.rect[1], b.rect[2])
  tall = 28px * length(tool.choices) + 10px
  show_menu!(w, [first(c) for c in tool.choices], left, top - tall - 6px, 200px, theme=menu_theme(), item_height=28px, lift=3.0,
             onselect=k -> k in eachindex(tool.choices) && Diagrams.use!(m, name, last(tool.choices[k])))
  handled
end

"""
Lay the diagram of `v` out at its own size, in the page's font and colours, to
draw at any size. It's laid out again when the font or the colours change.
"""
lay_diagram!(v::ZoomView) = begin
  e = editor(v)
  code = v.what[2]
  # One component shows the diagram for as long as it fills the window, so it keeps what's selected in it
  m = part!(() -> Mermaid(code, bar=false), v, :diagram)
  m.code = code
  m.editing = v.block > 0 && !readonly(e.buf)
  m.keys = part!(() -> ZoomArea(of=v), v, :area)
  m.onchange = m -> write_diagram!(v, m.code)
  key = (code, look_key(e), e.font, e.zoom)
  v.drawn !== nothing && v.drawn[1] == key && return v.drawn[2]
  root = with_theme(component_theme(e.zoom)) do
    inner = geometry(m)
    made = m.made === nothing ? nothing : m.made[2]
    (made === nothing || !hasproperty(made, :w) || made.w <= 0) && return nothing
    describe(Column(fixed(px(made.w)), Alignment.Start, inner), (px(made.w), 99999px))
  end
  v.drawn = (key, root)
  root
end

"How wide and how tall what `v` shows is at its own size, in px, or nothing when it can't be shown"
subject_size(v::ZoomView) = begin
  what = v.what
  what === nothing && return nothing
  if what[1] == :picture
    has_image(what[2]) || return nothing
    s = image_source(what[2])
    n = natural(what[2])
    n === nothing ? (Float64(s.width), Float64(s.height)) : (Float64(n[1]), Float64(n[2]))
  elseif what[1] == :diagram
    root = v.drawn === nothing ? nothing : v.drawn[2]
    root === nothing ? nothing : (num(root.width), num(root.height))
  elseif what[1] == :pdf
    s = pdf_size(what[2], v.page)
    s === nothing ? nothing : (Float64(s[1]), Float64(s[2]))
  end
end

"How many px of room are round a picture that fits the view. The page of a file itself has none."
zoom_edge(v::ZoomView) = v.bare ? 0.0 : ZOOM_EDGE
"How many px at the bottom of the view are kept for the bar of buttons. On the page of a file itself the bar lies over the picture."
bar_room(v::ZoomView) = v.bare ? 0.0 : num(BAR_ROOM)

"The middle of the part of the view that's above the bar of buttons"
view_middle(v::ZoomView) = (v.box[1] + v.box[3] / 2, v.box[2] + (v.box[4] - bar_room(v)) / 2)

"How many px to a px of the picture fits the whole of something `s` big in the view, above the bar and with room round it"
fit_zoom(v::ZoomView, s) = max(min((v.box[3] - 2zoom_edge(v)) / s[1], (v.box[4] - bar_room(v) - 2zoom_edge(v)) / s[2]), 1e-3)

"Show the whole picture, in the middle of the view"
fit!(v::ZoomView, s) = (v.zoom = fit_zoom(v, s); v.fits = true; hold!(v, s))

"""
Keep the picture in the view. Where it's narrower than the view, it stays in
the middle, and so it does where it's shorter. Otherwise it moves no further
than its edges, with room round them.
"""
hold!(v::ZoomView, s) = begin
  w, h = v.box[3] / v.zoom, (v.box[4] - bar_room(v)) / v.zoom
  edge = zoom_edge(v) / v.zoom
  v.at = (s[1] + 2edge <= w ? (s[1] - w) / 2 : clamp(v.at[1], -edge, s[1] - w + edge),
          s[2] + 2edge <= h ? (s[2] - h) / 2 : clamp(v.at[2], -edge, s[2] - h + edge))
  v
end

"Note that the view is now `box`. A picture that fitted the old view fits the new one."
reframe!(v::ZoomView, box) = begin
  s = subject_size(v)
  changed, v.box = box != v.box, box
  s === nothing && return v
  v.zoom <= 0 || (v.fits && changed) ? fit!(v, s) : hold!(v, s)
end

"Note that the view moved just now, and keep the picture in it"
moved!(v::ZoomView, s) = begin
  v.moved = time()
  hold!(v, s)
  v.fits = v.zoom <= fit_zoom(v, s) * 1.0001
  handled
end

"Fit the picture to the window again"
fit_now!(v::ZoomView) = (s = subject_size(v); s === nothing || fit!(v, s); handled)

"Make the picture `by` times as big. The point of it at the place `(x, y)` in the window stays there."
zoom_by!(v::ZoomView, by, x, y) = begin
  s = subject_size(v)
  (s === nothing || v.zoom <= 0) && return handled
  p = (v.at[1] + (x - v.box[1]) / v.zoom, v.at[2] + (y - v.box[2]) / v.zoom)
  f = fit_zoom(v, s)
  v.zoom = clamp(v.zoom * by, min(f, 1.0), max(f, 1.0) * MOST_ZOOM)
  v.at = (p[1] - (x - v.box[1]) / v.zoom, p[2] - (y - v.box[2]) / v.zoom)
  moved!(v, s)
end

"Go on by `by` pages of a PDF file, as far as the first page or the last"
turn!(v::ZoomView, by) = begin
  page = clamp(v.page + by, 1, v.pages)
  page == v.page && return handled
  v.page, v.zoom, v.fits = page, 0.0, true
  handled
end

draw(ctx, size, ui::ConcreteRect, a::ZoomArea) = begin
  v = a.of
  v.what === nothing && return
  reframe!(v, (num(ui.left), num(ui.top), num(ui.width), num(ui.height)))
  s = subject_size(v)
  (s === nothing || v.zoom <= 0) && return
  with_clip(() -> zoom_ink(ctx, v, s), ctx, ui.left, ui.top, ui.width, ui.height)
end

"Draw what `v` shows, which is `s` big at its own size"
zoom_ink(ctx, v::ZoomView, s) = begin
  x, y = v.box[1] - v.at[1] * v.zoom, v.box[2] - v.at[2] * v.zoom
  w, h = s[1] * v.zoom, s[2] * v.zoom
  kind = v.what[1]
  if kind == :picture
    image = image_source(v.what[2])
    paint_picture(ctx, image.raw, (0, 0, image.width, image.height), (x, y, w, h))
  elseif kind == :diagram
    # The diagram is drawn at its own size onto a canvas that's made bigger, so its lines and its words stay sharp
    root = v.drawn[2]
    Skia.sk_canvas_save(ctx)
    Skia.sk_canvas_translate(ctx, Float32(x), Float32(y))
    Skia.sk_canvas_scale(ctx, Float32(v.zoom), Float32(v.zoom))
    Skia.sk_canvas_translate(ctx, -Float32(num(root.left)), -Float32(num(root.top)))
    try
      draw(ctx, root.size, root)
    finally
      Skia.sk_canvas_restore(ctx)
    end
  else
    paper = (x, y, w, h)
    paper!(ctx, paper)
    with_round_clip(() -> pdf_ink(ctx, v, paper), ctx, px(x), px(y), px(w), px(h), px(PAPER_ROUND))
  end
end

"Draw the part of a PDF page that's in the view, at the screen's own pixels. While it moves, a rougher picture of the whole page shows."
pdf_ink(ctx, v::ZoomView, paper) = begin
  left, top, wide, tall = v.box
  path = v.what[2]
  d = clamp(density(ctx), 2, 3)
  w, h = round(Int, wide * d), round(Int, tall * d)
  (w < 1 || h < 1) && return
  k = v.zoom * d   # the screen's pixels to a point of the page
  of = (path, mtime(path), v.page, k, v.at, w, h)
  p = v.sharp
  if p.of != of && p.cost > QUICK && time() - v.moved < SETTLED
    rough = pdf_page(path, v.page, 2000)
    if rough !== nothing
      r = image_source(rough)
      paint_picture(ctx, r.raw, (0, 0, r.width, r.height), paper)
    end
    redraw_in!(v, SETTLED)
    return
  end
  image = sharpen!(p, path, v.page, of, k, v.at[1] * k, v.at[2] * k, w, h)
  image == C_NULL || paint_picture(ctx, image, (0, 0, w, h), (left, top, wide, tall))
end

"The place in the picture of the diagram that's at the place `at` in the window"
picture_spot(v::ZoomView, at) = (v.at[1] + (num(at[1]) - v.box[1]) / v.zoom, v.at[2] + (num(at[2]) - v.box[2]) / v.zoom)

# A click starts a drag that moves the picture. On the point of a box of a diagram, the drag draws a line from the box.
onkey(a::ZoomArea, ev::KeyPress{Keys.mouse_left}) = begin
  w, v = ev.window, a.of
  focus(a)
  m = changing(v)
  # The point is under the mouse when it's within 8px of it on the screen, however small the diagram is drawn
  m !== nothing && v.zoom > 0 && Diagrams.press_at!(m, picture_spot(v, w.mouse)..., near=8 / v.zoom) && return handled
  v.grab = ((num(w.mouse[1]), num(w.mouse[2])), v.at)
  handled
end

# A line that's dragged from a box's point is drawn when the button comes up over another box
onkey(a::ZoomArea, ev::KeyRelease{Keys.mouse_left}) = begin
  m = changing(a.of)
  m === nothing || a.of.zoom <= 0 || Diagrams.let_go_at!(m, picture_spot(a.of, ev.window.mouse)...)
  nothing
end

"""
The mouse button came up. On a diagram that can be changed, a click that
didn't drag the diagram selects the part that it was on, or nothing. A drag
only moves the diagram, so the part that's selected stays selected.
"""
let_go!(v::ZoomView, w) = begin
  g, v.grab = v.grab, nothing
  m = changing(v)
  (g === nothing || m === nothing || v.zoom <= 0) && return v
  x, y = g[1]
  hypot(num(w.mouse[1]) - x, num(w.mouse[2]) - y) < 4 || return v
  # A line is clicked when the mouse is within 5px of it on the screen, however small the diagram is drawn
  Diagrams.pick_at!(m, v.at[1] + (x - v.box[1]) / v.zoom, v.at[2] + (y - v.box[2]) / v.zoom, near=5 / v.zoom)
  v
end

onmouse(a::ZoomArea, ev::MouseMove) = begin
  v = a.of
  m = changing(v)
  if m !== nothing && v.zoom > 0
    at = picture_spot(v, ev.position)
    if m.joining !== nothing
      Keys.mouse_left in ev.window.keys ? Diagrams.drag_to!(m, at...) : Diagrams.let_go_at!(m, at...)
      return handled
    end
    # The box under the mouse shows its point
    v.grab === nothing && Diagrams.hover_at!(m, at..., near=8 / v.zoom)
  end
  g = v.grab
  g === nothing && return handled
  Keys.mouse_left in ev.window.keys || (let_go!(v, ev.window); return handled)
  s = subject_size(v)
  (s === nothing || v.zoom <= 0) && return handled
  (x0, y0), at = g
  x, y = num(ev.position[1]), num(ev.position[2])
  v.at = (at[1] - (x - x0) / v.zoom, at[2] - (y - y0) / v.zoom)
  moved!(v, s)
end

# Scrolling with ⌘ held makes the picture bigger or smaller, round the mouse. Scrolling without ⌘ moves it.
onscroll(a::ZoomArea, ev::MouseScroll) = begin
  v, w = a.of, ev.window
  only_held(w, Keys.cmd) && return zoom_by!(v, exp(num(ev.delta[2]) / 10), num(w.mouse[1]), num(w.mouse[2]))
  s = subject_size(v)
  (s === nothing || v.zoom <= 0) && return handled
  v.at = (v.at[1] - 30num(ev.delta[1]) / v.zoom, v.at[2] - 30num(ev.delta[2]) / v.zoom)
  moved!(v, s)
end

# Two fingers that move apart or together on the trackpad make the picture bigger or smaller, round the mouse
onpinch(a::ZoomArea, ev::Pinch) = zoom_by!(a.of, ev.scale, num(ev.window.mouse[1]), num(ev.window.mouse[2]))

# The keys are the view's, so none of them change the page under it: the editor gives each key to `zoom_key!`
# when the key comes up to it. A right-click has no menu here.
onkey(a::ZoomArea, ::KeyPress{Keys.mouse_right}) = handled
ontype(::ZoomArea, ::Typed) = handled

"""
Do what the key `K` does while `v` fills the window. `command` is the command
that the key bindings give the key, or nothing. It's `handled`, or nothing for
the key of a command that the page still takes, like the one that saves. The
keys that change the size of the page's text change the size of the picture.
"""
zoom_key!(v::ZoomView, K, w, command) = begin
  m = changing(v)
  if m !== nothing
    # ⌘Z takes back the last change to the diagram, which is a change to the lines of its block
    if command in (:undo, :redo)
      Diagrams.cancel!(m)
      command == :redo ? redo!(editor(v).buf) : undo!(editor(v).buf)
      return handled
    end
    # Return types the words of the part that's selected, ⌫ takes it away and Esc selects nothing
    !unmodified(w) || !Diagrams.key!(m, K) || return handled
  end
  K == Keys.escape && unmodified(w) && return zoom_out!(v)
  command in PAGE_COMMANDS && return nothing
  # A file of a gallery: ← and → go to the file before it and the next one. A video that fills the screen keeps them.
  unmodified(w) && v.from isa GalleryView && !v.screen && K in (Keys.left, Keys.right) && return step!(v.from, K == Keys.left ? -1 : 1)
  if v.what[1] == :node && v.what[2] isa VideoPlayer && unmodified(w)
    # F makes a video fill the screen, and puts it back. The keys of the video are its own here too.
    K == Keys.f && return screen!(v, !v.screen)
    K in (Keys.space, Keys.left, Keys.right) && return onkey(v.what[2], KeyPress{K}(0, w))
  end
  v.what[1] == :node && return handled
  command == :bigger && return zoom_by!(v, ZOOM_STEP, view_middle(v)...)
  command == :smaller && return zoom_by!(v, 1 / ZOOM_STEP, view_middle(v)...)
  command == :usual_size && return fit_now!(v)
  # ← and →, or ↑ and ↓, turn the pages of a PDF file. In a gallery only ↑ and ↓ do.
  unmodified(w) && v.what[1] == :pdf && K in (Keys.left, Keys.right, Keys.up, Keys.down) && return turn!(v, K in (Keys.left, Keys.up) ? -1 : 1)
  handled
end

# --- blocks that show as a component ---------------------------------------------------------
#
# A code block in one of the languages of `BLOCKS` shows as a component of its
# own, as a takeoff and a schedule do: a chart, a question, a set of changes,
# a board, a calendar, a list of what was found, a sketch or a list of emails. Each one
# keeps all that it knows in the lines of its block, so the file holds the
# whole of it, and ⌘Z takes back what you do to it. Move the caret into the
# block, or click the block with ⌥ held, to see those lines.
#
# The view of a block is a node with these fields: `n`, its place among the
# page's blocks in its language, `first` and `last`, the lines of its block,
# `lines`, the lines that it was last read from, and `parts`, its buttons and
# the rest that's kept between frames. `reread!(view, lines)` reads it again.

"What a block in one language shows as"
struct BlockKind
  name::String   # what the sidebar calls it
  icon::String   # and the icon beside that name
  view::Any      # the type of its view
  html::Any      # `html(e, view)` is the block as HTML, or nothing to show its lines
end

"The languages whose blocks show as a component, with what each shows as"
const BLOCKS = Dict{String,BlockKind}()

"The view of the `n`th block of the page that shows in the language `lang`"
block_view(e, lang, n) = begin
  v = get!(() -> BLOCKS[lang].view(n=n), e.nodes, (:block, lang, e.buf.path, n))
  own!(node!(Document, e, :document), v)
  v
end

"What the block in the language `lang` from line `i` to line `t` shows. `n` is its place among the page's blocks in that language."
block_item(e, lang, i, t, n) = begin
  v = block_view(e, lang, n)
  v.first, v.last = i, t
  reread!(v, e.buf.lines[i+1:t-1])
  # A block that fills the window is drawn over the page, and its room in the page stays empty
  filling(v) && return Live(Box(width(grow=grow), height(v.tall)), v.tall + 2LIVE_GAP)
  # Lay it out once to learn how tall it is
  concrete = describe(Column(fixed(e.width), Alignment.Start, geometry(v)), (e.width, 9999px))
  can_fill(v) && (v.tall = concrete.height)
  Live(v, concrete.height + 2LIVE_GAP)
end

"The place of the block that opens on line `s` among the blocks of `b` in the language `lang`"
block_place(b::Buffer, lang, s) = count(i -> (k = kinds(b)[i]; k.kind == Kind.fence && k.level == 0 && k.lang == lang), 1:s)

"The block in the language `lang` that opens on line `s`, as HTML, or nothing to show its lines"
block_html(e, lang, s, t) = begin
  ks = kinds(e.buf)
  t > s && ks[t].kind == Kind.fence && ks[t].level == 1 || return nothing
  v = block_view(e, lang, block_place(e.buf, lang, s))
  v.first, v.last = s, t
  reread!(v, e.buf.lines[s+1:t-1])
  BLOCKS[lang].html(e, v)
end

"""
Write `new` as the lines of the block of `v`, a view in the language `lang`.
The caret stays where it was in the text, and ⌘Z takes the change back. With
`typing`, changes that come one soon after another are taken back together.
"""
write_block!(v, lang, new::Vector{String}; typing=false) = begin
  e = editor(v)
  b = e.buf
  readonly(b) && return v
  span = block_lines(b, lang, v.n)
  span === nothing && return v
  i, t = span
  v.first, v.last = i, t
  old = b.lines[i+1:t-1]
  new == old && return reread!(v, new)
  caret, anchor = b.caret, b.anchor
  edit!(b, line_end(b, i), line_end(b, t - 1), isempty(new) ? "" : "\n" * join(new, "\n"); typing)
  by = length(new) - length(old)
  moved(p) = p[1] >= t ? (p[1] + by, p[2]) : p[1] > i ? (i, 0) : p
  b.caret, b.anchor = moved(caret), moved(anchor)
  v.last += by
  reread!(v, new)
end

"What happens to a block's view in each frame, before the page is laid out. Most kinds of block need nothing."
block_tick!(v) = v

"Do what each block of the page that shows needs in this frame"
blocks_tick!(e) = for (key, node) in collect(e.nodes)
  (key isa Tuple && length(key) == 4 && key[1] == :block && key[3] == e.buf.path) || continue
  block_tick!(node)
  filling(node) || continue
  # A block whose lines have gone goes back to the page. Under one that fills the window, the page stays where it was.
  block_lines(e.buf, key[2], node.n) === nothing ? (node.full = false) : (e.scroll.offset = node.pinned)
end

"A part of the block view `v` that's kept between frames"
block_part!(make, v, key) = begin
  node = get!(make, v.parts, key)
  node.parent === nothing && setfield!(node, :parent, v)
  node
end

"A button of a block. A click does `act!(view, action, window)`."
@def mutable struct BlockButton <: SemanticUI
  of::Any = nothing
  action::Any = :none
  icon::String = ""
  words::String = ""
  tip::String = ""
  on::Bool = false                            # it's lit, like the kind of chart that shows now
  off::Bool = false                           # it does nothing now, and shows that
  bold::Bool = false                          # it's filled with colour, like the one button that a question waits for
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)   # where it was last drawn, to put its tooltip under it
  quiet::Bool = false                         # clicked, so no tooltip until the mouse leaves it
end

"The button of the block view `v` that's kept under `key`, with what it does and shows now"
block_button!(v, key, action; icon="", words="", tip="", on=false, off=false, bold=false) = begin
  b = block_part!(() -> BlockButton(of=v), v, (:button, key))
  b.action, b.icon, b.words, b.tip, b.on, b.off, b.bold = action, icon, words, tip, on, off, bold
  b
end

describe(b::BlockButton) = begin
  ishovered(b) || (b.quiet = false)
  filled = b.bold && !b.off
  colour = b.off ? colours.faint : filled ? colours.bg : b.on ? colours.accent : colours.dim
  back = filled ? (ishovered(b) ? RGBA(colours.accent, 0.85) : colours.accent) :
         b.on ? colours.active : ishovered(b) && !b.off ? colours.hover : clear
  Box(height(26px), padding(filled ? 10px : 7px, 0px), radius(6px), Alignment.Center, name="Button", background(back),
    Row(Alignment.Center, child_gap=5px,
      (isempty(b.icon) ? () : (Icon(b.icon, size=14px, color=colour),))...,
      (isempty(b.words) ? () : (label(b.words, 12px, color=b.off ? colours.faint : filled ? colours.bg : colours.ink, weight=filled ? "Semibold" : ""),))...))
end

cursor(b::BlockButton) = b.off ? :arrow : :hand
draw(ctx, size, ui::ConcreteRect, b::BlockButton) = (b.rect = (ui.left, ui.top, ui.width, ui.height); nothing)

onmouse(b::BlockButton, ev::MouseMove) = begin
  (b.quiet || isempty(b.tip)) && return
  show_tooltip!(ev.window, tip_label(b.tip), b.rect..., placement=:bottom, gap=6px)
end

onkey(b::BlockButton, ev::KeyPress{Keys.mouse_left}) = begin
  b.quiet = true
  hide_tooltip!(ev.window)
  b.off ? handled : act!(b.of, b.action, ev.window)
end

"What a block's box looks like in the page: round corners and a thin line, as a schedule has"
block_look() = (width(grow=grow), Alignment.Start, radius(8px), border(1px, :solid, colours.line), background(takeoff_back()))

"The row of buttons at the top of a block"
block_bar(parts...) = Row(width(grow=grow), height(38px), padding(6px, 0px), child_gap=2px, Alignment.Center, background(colours.block), parts...)

"A line of quiet words in a block that has nothing to show yet"
block_note(words) = Row(width(grow=grow), padding(16px, 20px), Alignment.Center, clip=true,
                        Box(width(grow=grow), Text(words, size=13px, family=SANS, color=colours.dim, wrap=WrapMode.words)))

"A colour as CSS writes it, like #2a78d6"
css_colour(c) = (c = RGBA(c); "#" * join(string(round(Int, 255x), base=16, pad=2) for x in (c.r, c.g, c.b)))

# --- a chart of a table's numbers ------------------------------------------------------------
#
# A code block in the language `chart` draws the numbers of a table of the
# page as bars, as lines or as a pie. chart.jl says how the block is written,
# and works out where each bar goes. The three buttons at the top of the chart
# choose its kind. The mouse over a bar, a dot or a slice says its number.

const CHART = Charts.CHART
const PLOT_H = 260px   # how tall bars and lines are
const PIE_H = 220px    # and a pie
"Every icon that a block can show. The built app reads them all when it's made."
const BLOCK_ICONS = String["bar-chart", "graph-up", "pie-chart"]

# The colours of the columns of numbers, in the order that a chart uses them. Each one can be told from
# the one before it by a reader who doesn't see every colour. The first eight are for a light page.
const SERIES_LIGHT = [colorant"#2a78d6", colorant"#eb6834", colorant"#1baf7a", colorant"#eda100",
                      colorant"#e87ba4", colorant"#008300", colorant"#6250d6", colorant"#e34948"]
const SERIES_DARK = [colorant"#3987e5", colorant"#d95926", colorant"#199e70", colorant"#c98500",
                     colorant"#d55181", colorant"#0ca30c", colorant"#9085e9", colorant"#e66767"]
series_colours() = dark_page() ? SERIES_DARK : SERIES_LIGHT

"What a `chart` block shows: the numbers of a table, drawn"
@def mutable struct ChartView <: SemanticUI
  n::Int = 0                               # its place among the page's charts
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  spec::Charts.Chart = Charts.Chart()
  lines::Vector{String} = String[]         # the lines that `spec` was read from
  shown::Any = nothing                     # the version of the page, and what the chart shows of that page
  marks::Vector{Charts.Mark} = Charts.Mark[]   # the parts of the chart, where they were last drawn
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the chart was last drawn in the window
  sourcing::Bool = false                   # the list of files to draw is open, after Choose a file…
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its buttons, kept between frames
end

"The part of a chart that shows the bars, the lines or the pie"
@def mutable struct PlotArea <: SemanticUI
  of::Any = nothing
end

reread!(v::ChartView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.spec = Charts.chart(lines)
  v.shown = nothing
  v
end

"The text of a cell without the marks that make it bold or code"
plain_cell(text) = String(strip(replace(text, r"\*\*|__|`" => "")))

"""
Every table of the page that shows: each table, each spreadsheet and each
sheet. Each one has its first and last line, the heading that it's under, and
the text of each cell of each row. A formula's cell holds what the formula
comes to, and a cell with a sum in it holds what the sum shows. `headed` is true when the first row has the names of the columns.
"""
page_tables(e) = begin
  b = e.buf
  key = (:tables, b.path, b.version, table_reads[], sums_run[], page_day(e))
  haskey(e.flows, key) && return e.flows[key]
  ks = kinds(b)
  out = @NamedTuple{first::Int, last::Int, under::String, rows::Vector{Vector{String}}, headed::Bool, ranged::Bool}[]
  under = ""
  i = 1
  while i <= length(ks)
    k = ks[i]
    stop = i
    if k.kind == Kind.heading
      under = plain_cell(rest(b.lines[i], k.prefix))
    elseif k.kind == Kind.table
      run = table(b, i)
      if run !== nothing && run[1] == i
        # A chart draws what a sum in a cell shows, and not its code
        rows = [String[plain_cell(sums_shown(e, r, c.lo, rest(head(b.lines[r], c.hi), c.lo))) for c in tablecells(b.lines[r])] for r in tablerows(run)]
        push!(out, (first=i, last=run[2], under=under, rows=rows, headed=true, ranged=false))
        stop = run[2]
      end
    elseif k.kind == Kind.fence && k.level == 0 && k.lang in (SPREADSHEET, SHEET)
      t = codeblock(b, i)[2]
      if t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        if k.lang == SPREADSHEET
          texts = [spreadtexts(b.lines[r]) for r in i+1:t-1]
          values = get!(() -> answers(texts), e.flows, (:answers, texts))
          rows = [String[isformula(text) ? (values[r][c].failed ? "" : values[r][c].text) : String(strip(text)) for (c, text) in enumerate(row)]
                  for (r, row) in enumerate(texts)]
        else
          texts = [parts(b.lines[r]) for r in i+1:t-1]
          given = sheet_given(e, i)
          # A sheet with a row over a range is a table with a row for each value of that row
          over = get!(() -> cases(texts; given, cache=e.flows), e.flows, (:cases, texts, given))
          if over !== nothing
            push!(out, (first=i, last=t, under=under, rows=over.table, headed=true, ranged=true))
            i = t + 1
            continue
          end
          results = get!(() -> tally(texts; given, cache=e.flows), e.flows, (:sheetrun, texts, given, nothing))
          rows = [String[strip(name), results[r].failed ? "" : results[r].text] for (r, (name, _)) in enumerate(texts)]
        end
        push!(out, (first=i, last=t, under=under, rows=rows, headed=false, ranged=false))
        stop = t
      end
    elseif k.kind == Kind.fence && k.level == 0 && k.lang == TIMELOG
      # A log of hours is a table of its tasks, with the hours of each
      t = codeblock(b, i)[2]
      if t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        rows = Timelogs.table(log_to_day(e, Timelogs.timelog(b.lines[i+1:t-1])), Timelogs.now())
        length(rows) > 1 && push!(out, (first=i, last=t, under=under, rows=rows, headed=true, ranged=false))
        stop = t
      end
    elseif k.kind == Kind.fence && k.level == 0 && k.lang in (FILTER, LOAD)
      # A filter is a table of the rows that it shows. It reads a table above it. A load block is a filter too.
      t = codeblock(b, i)[2]
      if t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        rows = filter_page_table(e, b.lines[i+1:t-1], out, i; load=k.lang == LOAD)
        rows === nothing || push!(out, (first=i, last=t, under=under, rows=rows, headed=true, ranged=false))
        stop = t
      end
    elseif k.kind == Kind.fence && k.level == 0
      stop = max(i, codeblock(b, i)[2])   # a table in a block of code isn't one
    elseif k.kind == Kind.paragraph && (rows = table_rows(e, i)) !== nothing
      push!(out, (first=i, last=i, under=under, rows=rows, headed=true, ranged=false))   # a line that shows a CSV file as a table
    end
    i = stop + 1
  end
  e.flows[key] = out
end

"""
The rows that a chart draws: its own, or those of a table of the page. With
`from`, that's the first table under the heading that `from` names, or the
tables that it names with commas between them. Without it, it's the table
that's nearest above the chart, or the first one under it.
"""
chart_data(e, v::ChartView) = begin
  c = v.spec
  isempty(c.rows) || return Charts.data(c, c.rows)
  drawn = chart_file(e, c)   # `from` can name a CSV file
  drawn === nothing || return drawn
  tables = page_tables(e)
  k = isempty(c.from) ? something(findlast(t -> t.last < v.first, tables), findfirst(t -> t.first > v.last, tables), 0) :
                        something(named_table(e, tables, c.from), 0)
  k == 0 || return Charts.data(c, tables[k].rows, headed=tables[k].headed, by_first=tables[k].ranged, values=table_amounts(e, tables[k]))
  names = chart_sources(c)
  length(names) > 1 && return Charts.joined(c, [chart_part(e, c, tables, name) for name in names], names)
  Charts.nothing_to_draw(isempty(c.from) ?
    "This page has no table yet. Put a table, a spreadsheet or a sheet over this chart, and the chart draws its numbers." :
    "This page has no table called “$(c.from)”. A table is called by the heading over it, with a number after it for the second table under that heading.")
end

"The tables that the `from` of the chart `c` names, with commas between them. It's one name, or none, for a chart that draws one table."
chart_sources(c::Charts.Chart) = Charts.listed(c.from)

"What the chart `c` draws of `name`, one of the several tables that it draws: the table under a heading of the page, or a CSV file"
chart_part(e, c::Charts.Chart, tables, name) = begin
  if istable(name)
    t = file_table(abspath(docdir(e), expanduser(name)))
    return isempty(t.problem) ? Charts.data(c, t.rows, headed=true, part=true) : Charts.nothing_to_draw(t.problem)
  end
  k = named_table(e, tables, name)
  k === nothing && return Charts.nothing_to_draw("This page has no table called “$(name)”. A table is called by the heading over it.")
  Charts.data(c, tables[k].rows, headed=tables[k].headed, by_first=tables[k].ranged, part=true, values=table_amounts(e, tables[k]))
end

"The amount of each cell of a Markdown table, where the cell is one sum and the amount has a unit. Any other cell is nothing, and so is a table that isn't rows of the page."
table_amounts(e, t) = begin
  b = e.buf
  run = table(b, t.first)
  (run === nothing || run[1] != t.first) && return nothing
  rows = Vector{Any}[]
  for r in tablerows(run)
    push!(rows, Any[cell_amount(e, r, c.lo, rest(head(b.lines[r], c.hi), c.lo)) for c in tablecells(b.lines[r])])
  end
  rows
end

"The amount a cell holds, when the cell is one sum and that amount has a unit. The % in an amount goes into its number, as the cell shows it."
cell_amount(e, i::Int, col::Int, text::AbstractString) = begin
  m = match(r"!`([^`]+)`", text)
  m === nothing && return nothing
  strip(text) == INLINE * m[1] * "`" || return nothing
  code = String(m[1])
  n = ordinal(e, i, col + length(text, 1, m.offset) + 1, code)
  made(e, code, n)
  value = get(e.nodes, (:amount, e.buf.path, code, n), nothing)
  value isa Units.Unit || return nothing
  y = folded(value)
  y isa Units.Unit ? y : nothing
end

"What the chart shows. It's worked out again when the page has changed."
shown!(v::ChartView) = begin
  e = editor(v)
  key = (e.buf.version, v.first, v.lines, table_reads[], sums_run[], page_day(e))
  (v.shown !== nothing && v.shown[1] == key) || (v.shown = (key, chart_data(e, v)))
  v.shown[2]
end

"How wide `text` is in the font of a chart's words, at the size `size`"
chart_measure(text, size) = num(measure(Face(SANS, "", px(size), colours.ink, false), text))

"The three kinds of chart: the icon of each one's button, and what the button's tooltip says"
const CHART_KINDS = ((:bars, "bar-chart", "Bars"), (:lines, "graph-up", "Lines"), (:pie, "pie-chart", "A pie"))

describe(v::ChartView) = begin
  e = editor(v)
  d = shown!(v)
  with_theme(component_theme(e.zoom)) do
    bar = block_bar(
      [block_button!(v, k, (:kind, k), icon=icon, tip=tip, on=v.spec.kind == k) for (k, icon, tip) in CHART_KINDS]...,
      rule(), source_button(v),
      # The title's row is as tall as the bar, so what it clips is only a title too long for it. A row as tall as the text
      # would clip the tails of letters like p and y, which hang under the text's box.
      (isempty(v.spec.title) ? () : (rule(), Row(width(grow=grow), height(grow=grow), padding(6px, 0px), Alignment.Center, clip=true,
                                                 Box(label(v.spec.title, 13px, weight="Semibold")))))...)
    Column(block_look()..., clip=true, name="Chart", bar, (v.sourcing ? from_picker_section(v) : ())...,
           isempty(d.problem) ? block_part!(() -> PlotArea(of=v), v, :area) : block_note(d.problem))
  end
end

cursor(::Union{ChartView,PlotArea}) = :arrow

act!(v::ChartView, action, w) = begin
  action == :close_picker && return (v.sourcing = false; handled)
  action isa Tuple && action[1] == :kind || return handled
  v.spec.kind = action[2]
  write_block!(v, CHART, Charts.written(v.spec))
  handled
end

describe(a::PlotArea) = Box(width(grow=grow), height(a.of.spec.kind == :pie ? PIE_H : PLOT_H))

"The mark of the chart that the mouse is over, or nothing"
chart_hit(v::ChartView) = begin
  w = window_of(v)
  w === nothing ? nothing : Charts.hit(v.marks, num(w.mouse[1]) - v.box[1], num(w.mouse[2]) - v.box[2])
end

"Draw a filled circle"
disc(ctx, x, y, r, colour) = begin
  paint = ink(colour)
  Skia.sk_canvas_draw_circle(ctx, Float32(x), Float32(y), Float32(r), paint)
  Skia.sk_paint_delete(paint)
end

"Draw the marks of a chart, with the top left corner of the chart at `(x0, y0)`. The mark `hot` is the one under the mouse."
draw_marks(ctx, marks, x0, y0, hot=nothing; lit=0) = begin
  cs, surface = series_colours(), takeoff_back()
  for m in marks
    # While the mouse is over a bar or a slice, the others are pale. So are the bars of the other rows,
    # while the mouse is on a row of the chart's table: the row at place `lit`.
    pale = m.kind in (:bar, :slice) && (hot !== nothing ? (m.label, m.series) != (hot.label, hot.series) : lit > 0 && m.label != lit)
    colour = m.colour == 0 ? colours.dim : pale ? RGBA(cs[m.colour], 0.4) : cs[m.colour]
    x, y = x0 + m.at[1], y0 + m.at[2]
    if m.kind == :rule
      trace(ctx, [(x, y), (x0 + m.at[3], y0 + m.at[4])], RGBA(colours.ink, m.style == :strong ? 0.3 : 0.08), 1.0)
    elseif m.kind == :bar
      w, h = m.at[3], m.at[4]
      # Only the end that's away from the line of 0 has round corners, so the box is drawn longer and cut off at that line
      with_clip(ctx, px(x), px(y), px(w), px(h)) do
        round_box(ctx, x, m.style == :down ? y - 4 : y, w, h + 4, min(4.0, w / 2); fill=colour)
      end
    elseif m.kind == :line
      trace(ctx, [(x0 + a, y0 + b) for (a, b) in m.points], colour, 2.0)
    elseif m.kind == :dot
      on = hot === m || (hot === nothing && lit > 0 && m.label == lit)
      r = on ? 5.5 : m.at[3]
      r > 0 || continue
      disc(ctx, x, y, r + 2, surface)   # a ring in the colour of the page keeps it apart from the line that it's on
      disc(ctx, x, y, r, colour)
    elseif m.kind == :slice
      trace(ctx, [(x0 + a, y0 + b) for (a, b) in m.points], surface, 2.0; fill=colour, closed=true)
    elseif m.kind == :swatch
      round_box(ctx, x, y, m.at[3], m.at[4], 2.5; fill=colour)
    elseif m.kind == :words
      face = Face(SANS, "", px(m.size), m.tone == :ink ? colours.ink : colours.dim, false)
      wide = num(measure(face, m.text))
      write_ink(ctx, m.text, m.style == :end ? x - wide : m.style == :middle ? x - wide / 2 : x, y, face)
    end
  end
end

draw(ctx, size, ui::ConcreteRect, a::PlotArea) = begin
  v = a.of
  v.box = (num(ui.left), num(ui.top), num(ui.width), num(ui.height))
  v.box[3] > 0 || return
  v.marks = Charts.plot(shown!(v), v.spec.kind, v.box[3], v.box[4], chart_measure)
  with_clip(ctx, ui.left, ui.top, ui.width, ui.height) do
    hot = ishovered(a) ? chart_hit(v) : nothing
    # The row of the table that the mouse is on, in another part of the page, has its bars marked
    lit = hot === nothing ? something(findfirst(name -> marked(v, name), shown!(v).labels), 0) : 0
    draw_marks(ctx, v.marks, v.box[1], v.box[2], hot; lit)
  end
end

# The mouse over a bar, a dot or a slice says its number
onmouse(a::PlotArea, ev::MouseMove) = begin
  v = a.of
  m = Charts.hit(v.marks, num(ev.position[1]) - v.box[1], num(ev.position[2]) - v.box[2])
  m === nothing && return nothing
  x, y = v.box[1] + m.at[1], v.box[2] + m.at[2]
  spot = m.kind == :bar ? (x, y, m.at[3], m.at[4]) : m.kind == :dot ? (x - 6, y - 6, 12.0, 12.0) :
         (mid = (m.at[3] + m.at[4]) / 2; (x + 0.6m.size * cos(mid) - 4, y + 0.6m.size * sin(mid) - 4, 8.0, 8.0))
  show_tooltip!(ev.window, tip_label(Charts.said(shown!(v), m)), px.(spot)..., placement=:top, gap=6px)
  handled
end

"The chart as HTML: its title, and a picture of it"
chart_html(e, v::ChartView) = begin
  d = shown!(v)
  isempty(d.problem) || return nothing
  wide, tall = 720.0, num(v.spec.kind == :pie ? PIE_H : PLOT_H)
  picture = Charts.svg(Charts.plot(d, v.spec.kind, wide, tall, chart_measure), wide, tall, colours=css_colour.(SERIES_LIGHT),
                       ink="#2b2622", dim="#6b6259", line="#e6e0d0", surface="#fdfcf9", family="-apple-system, Helvetica, sans-serif")
  title = isempty(v.spec.title) ? "" : "<p><strong>$(escape(v.spec.title))</strong></p>\n"
  "<div class=\"diagram\">\n$title$picture\n</div>"
end

BLOCKS[CHART] = BlockKind("Chart", "bar-chart", ChartView, chart_html)

# --- a filter of a table's rows ----------------------------------------------------------------
#
# A code block in the language `filter` shows only the rows of a table that
# meet its conditions: the rows of a CSV file, of a JSON file or of a table of
# the page. filter.jl says how the block is written. The top of the block
# names where the rows come from and says how many show. Its Save button
# writes the rows that show into a new file.
#
# Under the top, each condition is a chip with an × that takes it away. The
# field after them adds one: type `Total > 100` and press Return. A chip whose
# condition the filter can't use is in the accent colour, and the line under
# the chips says why. When the block hides some columns, a chip says how many,
# and its × shows them again.
#
# The rows show as a table. A click on a heading opens a menu, as it does in a
# CSV file's table. It puts the rows in the order of that column, ticks the
# values to show, or keeps only the rows that have some words in that column.
# It can also hide the column. Each choice goes into the block's lines, so the
# file holds the whole filter, and ⌘Z takes it back. Esc in the menu puts back
# the lines that the block had when the menu opened.
#
# The table shows its first FILTER_ROWS rows. A line under them says how many
# more there are, and a click on it shows them all. Only the rows in the window
# are made, so a long table costs no more to draw than a short one. A table
# that's wider than the page scrolls sideways: two fingers that move sideways,
# or the wheel with ⇧ held.
#
# A filter reads a table of the page that's above it. A chart can draw the rows
# that a filter shows: they're a table of the page, under the heading that the
# block is under. Save writes the rows that show to a file that you choose: a
# CSV file, or a JSON file that has each thing as the file had it, when the
# rows came from a JSON file. Ladder reads a file once, and again when it
# changes on the disk.

const FILTER = Filters.FILTER
const FILTER_ROWS = 30              # the rows that a filter shows until you ask for the rest
const FILTER_COLUMNS = 60           # the most columns that the things of a JSON file make
const FILTER_KEY = :filter_column   # the key of the menu of a filter's column
const CHIP_H = 24px                 # how tall a condition is, at the top of a filter
const ADD_W = 230px                 # how wide the field is that adds a condition
push!(BLOCK_ICONS, "funnel", "x", "download", "eye-slash", "plus")

"The rows that a filter reads, and where they came from"
struct FilterRows
  rows::Vector{Vector{String}}   # the first row has the names of the columns
  numbers::Vector{Bool}          # true for each column that holds numbers
  things::Vector{Any}            # for a JSON file, the thing that each row came from: row k + 1 came from thing k
  name::String                   # what the top of the block calls where they came from
  path::String                   # the file, or "" for a table of the page
  more::Bool                     # the file has rows after these
  problem::String                # why there are no rows, or ""
end

"No rows, and why"
no_rows(problem; name="", path="") = FilterRows(Vector{String}[], Bool[], Any[], name, path, false, problem)

# What's known of each file that a filter reads: when it last changed, how big it was then, and its rows, for each `at`
const filter_files = Dict{Tuple{String,String},Tuple{Float64,Int,FilterRows}}()

"True when the file at `path` is one that a filter reads: a CSV file, a TSV file or a JSON file"
isfilterable(path) = (x = lowercase(splitext(path)[2]); x in TABLES || x in JSONS)

"""
The rows of the file at `path`, for a filter. `at` says where the list is in
a JSON file, and `name` is what the block calls the file. The file is read
once, and again when it changes on the disk.
"""
filter_file(path, at; name=basename(path)) = begin
  isfile(path) || return no_rows("Ladder can't find the file $name.", name=name, path=path)
  s = stat(path)
  when, size = Float64(s.mtime), Int(s.size)
  json = lowercase(splitext(path)[2]) in JSONS
  key = (path, json ? String(strip(at)) : "")
  kept = get(filter_files, key, nothing)
  kept !== nothing && kept[1] == when && kept[2] == size && return kept[3]
  table_reads[] += 1   # what's worked out from the file is worked out again
  rows = json ? json_filter_rows(path, at; name) : begin
    t = Csvs.load(path, most=FILE_ROWS, upto=FILE_BYTES)
    isempty(t.problem) ? FilterRows(t.rows, t.numbers, Any[], name, path, t.more, "") : no_rows(t.problem, name=name, path=path)
  end
  filter_files[key] = (when, size, rows)
  rows
end

"The rows of the JSON file at `path`: a row for each thing in the list that `at` names"
json_filter_rows(path, at; name=basename(path)) = begin
  filesize(path) <= MOST_JSON || return no_rows("The file $name is too big for Ladder to read.", name=name, path=path)
  root = try
    json_value(read(path))
  catch
    return no_rows("Ladder can't read $name as JSON.", name=name, path=path)
  end
  things, problem = json_things(root, at)
  isempty(problem) || return no_rows(problem, name=name, path=path)
  isempty(things) && return no_rows("The list in $name has nothing in it.", name=name, path=path)
  rows = json_table(things)
  FilterRows(rows, Csvs.numbers(rows), things, name, path, false, "")
end

"""
The first list in `root` whose items are mostly objects, looking at the top
level first and then a level further in each time. Without one, it's the first
list, or `root` itself when it holds no list.
"""
json_first_list(root) = begin
  root isa Vector{Any} && return root
  level, first = Any[root], nothing
  while !isempty(level)
    for v in level
      v isa Vector{Any} || continue
      first === nothing && (first = v)
      !isempty(v) && 2count(x -> x isa JSONObject, v) > length(v) && return v
    end
    level = Any[x for v in level if json_holder(v) for (_, x) in json_items(v) if json_holder(x)]
  end
  something(first, root)
end

"""
The things that a filter of a JSON file has a row for, and why there are none
or "". They're the items of the list that `at` names, as keys with dots
between them, like data.orders. A number in `at` is the place of an item in its
list, counting from 0. Without `at`, they're the items of `json_first_list`.
An object whose values are all objects has a row for each of them, with a
column called key for its key. Any other object is one row.
"""
json_things(root, at) = begin
  at = String(strip(at))
  value = isempty(at) ? json_first_list(root) : root
  for step in (isempty(at) ? String[] : strip.(split(at, '.')))
    if value isa JSONObject && (k = findfirst(==(step), value.keys)) !== nothing
      value = value.values[k]
    elseif value isa Vector{Any} && (n = tryparse(Int, step)) !== nothing && 0 <= n < length(value)
      value = value[n+1]
    else
      return Any[], "The file has nothing at “$(at)”."
    end
  end
  value isa Vector{Any} && return value, ""
  if value isa JSONObject && !isempty(value.values) && all(x -> x isa JSONObject, value.values)
    return Any[JSONObject(["key"; o.keys], Any[k; o.values]) for (k, o) in zip(value.keys, value.values)], ""
  end
  Any[value], ""
end

"""
The rows of a table of `things`: the names of the columns, then a row for each
thing. Each key of a thing is a column, and so is each key of an object in it,
with a dot between the keys: customer.name. A thing that isn't an object has a
column called value.
"""
json_table(things) = begin
  names, place = String[], Dict{String,Int}()
  cells = [json_cells!(Dict{Int,String}(), names, place, "", x, 0) for x in things]
  rows = Vector{String}[names]
  append!(rows, [[get(row, c, "") for c in eachindex(names)] for row in cells])
end

"Put the cells of `x` into `row`, with the name of each one's column after `prefix`"
json_cells!(row, names, place, prefix, x, depth) = begin
  if x isa JSONObject && !isempty(x.keys) && depth < 4
    for (k, v) in zip(x.keys, x.values)
      json_cells!(row, names, place, isempty(prefix) ? k : prefix * "." * k, v, depth + 1)
    end
    return row
  end
  name = isempty(prefix) ? "value" : prefix
  c = get(place, name, 0)
  if c == 0
    length(names) >= FILTER_COLUMNS && return row
    push!(names, name)
    c = place[name] = length(names)
  end
  row[c] = json_cell(x)
  row
end

"What a JSON value shows as in a cell: a string as its text, null as nothing, a list of words with commas between them, and anything else as JSON on one line"
json_cell(x::AbstractString) = String(x)
json_cell(x::JSONNumber) = x.text
json_cell(x::Bool) = string(x)
json_cell(::Nothing) = ""
json_cell(x) = x isa Vector{Any} && !any(json_holder, x) ? join((json_cell(y) for y in x), ", ") : json_line(x)

"`x` as JSON on one line"
json_line(x) = replace(sprint(json_write, x), r",\n\s*" => ", ", r"\n\s*" => "")

"""
The rows of the table of the page that a filter reads: the one under the
heading that `from` names, or the nearest one above line `line`. `tables` are
the page's tables that are above the filter.
"""
page_filter_rows(e, spec::Filters.Filter, tables, line) = begin
  from = String(strip(spec.from))
  k = isempty(from) ? something(findlast(t -> t.last < line, tables), 0) : something(named_table(e, tables, from), 0)
  k == 0 && return no_rows(isempty(from) ?
    "Name a CSV or JSON file with a line like “from: orders.csv”, or put a table over this block." :
    "There's no file called $from beside this page, and no table called “$(from)” above this block.")
  t = tables[k]
  rows = t.headed ? t.rows : [[["Name", "Value"]]; t.rows]   # a sheet's rows have no names
  wide = maximum(length, rows)
  rows = [[r; fill("", wide - length(r))] for r in rows]
  FilterRows(rows, Csvs.numbers(rows), Any[], isempty(t.under) ? "The table above" : t.under, "", false, "")
end

"What a filter shows of `d`, its rows: the names of the columns that show, then each row that shows"
filter_table(d::FilterRows, s) = [[Filters.cell_of(d.rows[r], c) for c in s.columns] for r in [1; s.rows]]

"What a filter shows: the rows that it reads, and what it shows of them"
mutable struct FilterFound
  data::FilterRows
  subset::Any   # what Filters.subset gives, or nothing when there are no rows
  table::Any    # the rows that show, as a table of the page. It's made when a chart first asks for it.
end

# A FilterFound comes apart into its rows and what it shows of them: `d, s = filter_shown!(v)`
Base.iterate(x::FilterFound, i=1) = i == 1 ? (x.data, 2) : i == 2 ? (x.subset, 3) : nothing

# What each filter of a file showed last: the rows of the file then, and what showed. By the file and the block's lines.
const filter_found = Dict{Tuple{String,Vector{String}},Tuple{FilterRows,FilterFound}}()

"""
What the filter in `lines`, on line `line`, shows. `tables` are the page's
tables. A filter of a file is worked out again only when its lines or the file
change, so typing in another part of the page costs it nothing. A file of
100,000 rows takes about a tenth of a second. With `load`, it's a load block,
whose `from` can be a web address. Its rows are then the copy of what that
address last gave.
"""
filter_subset(e, lines, tables, line; load=false) = begin
  spec = Filters.query(lines)
  from = String(strip(spec.from))
  found(data) = FilterFound(data, isempty(data.problem) ? Filters.subset(spec, data.rows, data.numbers) : nothing, nothing)
  if Saves.isurl(from)
    load || return found(no_rows("A filter reads a file or a table of the page. To get rows from a server, write load in place of filter at the top of the block."))
    path, name = load_copy(from), Saves.host(from)
    isempty(path) && return found(no_rows("Ladder hasn't loaded the rows from $name yet.", name=name))
  elseif load && isempty(from)
    return found(no_rows("Name a file or a web address with a line like “from: orders.json” or “from: https://example.com/orders”."))
  else
    isfilterable(from) || return found(page_filter_rows(e, spec, [t for t in tables if t.last < line], line))
    path = abspath(docdir(e), expanduser(from))
    name = basename(path)
  end
  key = (path, String.(lines))
  data = filter_file(path, spec.at; name)
  kept = get(filter_found, key, nothing)
  kept !== nothing && kept[1] === data && return kept[2]
  length(filter_found) > 200 && empty!(filter_found)
  (filter_found[key] = (data, found(data)))[2]
end

"The rows that the filter in `lines`, on line `line`, shows as a table of the page, or nothing when it has none"
filter_page_table(e, lines, tables, line; load=false) = begin
  x = filter_subset(e, lines, tables, line; load)
  x.subset === nothing && return nothing
  x.table === nothing && (x.table = filter_table(x.data, x.subset))
  x.table
end

"What a `filter` block shows: the rows of a table that meet its conditions"
@def mutable struct FilterView <: SemanticUI
  n::Int = 0                               # its place among the page's filters
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  spec::Filters.Filter = Filters.Filter()
  lines::Vector{String} = String[]         # the lines that `spec` was read from
  shown::Any = nothing                     # what the rows were last worked out for, and what they are
  whole::Bool = false                      # every row shows, and not only the first FILTER_ROWS
  widths::Any = nothing                    # what the widths of the columns were worked out for, and the widths
  values::Dict{Int,Any} = Dict{Int,Any}()  # each column's values, for its menu, or nothing for a column with too many
  cut::Dict{Any,String} = Dict{Any,String}()   # the text of a cell as it shows, cut short for its column
  across::px = 0px                         # how far the table is scrolled to the right
  top::px = 0px                            # where the top of the table was last drawn in the window
  asking::Int = 0                          # the column whose menu is open, or 0
  was::Vector{String} = String[]           # the block's lines when that menu opened, which esc puts back
  saved::String = ""                       # what Save last did, in words
  lang::String = FILTER                    # filter, or load for a block that loads its rows from a server or a file
  job::Any = nothing                       # a load from a server that hasn't ended: a function that gives nothing until it has, then how it went
  asked::Any = nothing                     # the address and the key that the block last asked its server with
  changed::Float64 = 0.0                   # when the block's lines last changed
  said::String = ""                        # what came of the last load, in words
  failed::Bool = false                     # true when that went wrong
  nokey::Bool = false                      # the Keychain had no key with the name that `key` gives
  choosing::Bool = false                   # the file picker of a load block is open, after a click on Choose
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its chips, headings and buttons, kept between frames
end

"A condition at the top of a filter. Its × takes it away. With `k` 0, it's the chip that says how many columns are hidden."
@def mutable struct FilterChip <: SemanticUI
  of::Any = nothing
  k::Int = 0
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)   # where it was last drawn, to put its tooltip under it
end
"The × of a chip"
@def mutable struct ChipCross <: SemanticUI
  of::Any = nothing   # the chip
end
"The table of a filter. It scrolls sideways when it's wider than the page."
@def mutable struct FilterGrid <: SemanticUI
  of::Any = nothing
  inside::Any = nothing   # what's in it in this frame: the table, as far to the left as it's scrolled
end
"The heading of a column of a filter's table. A click on it opens the column's menu."
@def mutable struct FilterHead <: SemanticUI
  of::Any = nothing
  column::Int = 1    # the column of the rows that the filter reads
  wide::px = 0px
end
"The menu of a column of a filter's table"
@def mutable struct FilterMenu <: SemanticUI
  of::Any = nothing
end
"A line of that menu: one of the two orders, a value to tick, or the line that hides the column"
@def mutable struct FilterPick <: SemanticUI
  of::Any = nothing
  what::Symbol = :asc   # :asc, :desc, :value or :hide
  value::String = ""
  count::Int = 0
end
"The line under a filter's table that says how many rows don't show. A click shows them, or hides them again."
@def mutable struct FilterMore <: SemanticUI
  of::Any = nothing
end

reread!(v::FilterView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.spec = Filters.query(lines)
  v.changed = time()
  v
end

"""
What the filter `v` shows: a FilterFound, with `data`, the rows that it reads,
and `subset`, what it shows of them, or nothing when there are no rows. It's
worked out again when the block, the page or the file changes.
"""
filter_shown!(v::FilterView) = begin
  e = editor(v)
  key = (v.lines, e.buf.version, v.first, table_reads[], sums_run[], page_day(e))
  v.shown !== nothing && v.shown[1] == key && return v.shown[2]
  found = filter_subset(e, v.lines, page_tables(e), v.first; load=v.lang == LOAD)
  # What's kept of the rows is kept while they're the same
  v.shown !== nothing && v.shown[2] === found || (empty!(v.values); empty!(v.cut))
  v.shown = (key, found)
  found
end

"Write `f` as the lines of the filter `v`. ⌘Z takes it back."
filter_write!(v::FilterView, f::Filters.Filter; typing=false) = write_block!(v, v.lang, Filters.written(f); typing)

"The text field that adds a condition"
filter_adder(v::FilterView) = block_part!(v, :add) do
  TextInput(placeholder="Add a condition", font_family=SANS, font_size=12px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"The text field of a column's menu, for the words that the column's cells must have"
filter_field(v::FilterView) = block_part!(v, :field) do
  TextInput(placeholder="Contains…", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"""
The values of column `c` of what `v` reads, each with how many rows have it,
in the order of the column. Capitals don't count, so Sydney and sydney are
one value. It's nothing when the column has more than FEW_VALUES values.
"""
filter_values(v::FilterView, c::Int) = get!(v.values, c) do
  d = filter_shown!(v).data
  counts, shown = Dict{String,Int}(), Dict{String,String}()
  for r in 2:length(d.rows)
    cell = strip(Filters.cell_of(d.rows[r], c))
    key = lowercase(cell)
    haskey(counts, key) || (shown[key] = cell)
    counts[key] = get(counts, key, 0) + 1
    length(counts) > FEW_VALUES && return nothing
  end
  [(shown[k], counts[k]) for k in Filters.ordered(collect(keys(counts)), k -> shown[k], d.numbers[c], false)]
end

"""
What happens to a filter in each frame, before the page is laid out. It looks
at its file, so it shows the new rows when the file changes. While a column's
menu is open, the words in its field go into the block's lines as they're typed.
A load block looks for the rows that it asked its server for.
"""
block_tick!(v::FilterView) = begin
  v.lang == LOAD && load_tick!(v)
  pick_tick!(v)
  sources_tick!(v)
  from = String(strip(v.spec.from))
  isfilterable(from) && filter_file(abspath(docdir(editor(v)), expanduser(from)), v.spec.at)
  v.asking > 0 || return v
  d = filter_shown!(v).data
  (isempty(d.problem) && v.asking <= length(d.rows[1]) && filter_values(v, v.asking) === nothing) || return v
  words = String(strip(filter_field(v).text))
  names = d.rows[1]
  had = Filters.looked_for(v.spec, names, v.asking, :has)
  words == (isempty(had) ? "" : had[1]) && return v
  f = Filters.query(v.lines)
  filter_write!(v, Filters.look_for!(f, names, v.asking, :has, [words]), typing=true)
  v
end

"The width of each column of the table that `v` shows: as wide as its first rows need, and wider when they share room that's left"
filter_widths!(v::FilterView, d, s, wide) = begin
  key = (objectid(v.shown[2]), wide, s.columns)
  v.widths !== nothing && v.widths[1] == key && return v.widths[2]
  head, plain = cell_face(true), cell_face()
  sample = first(s.rows, 200)
  need(c) = max(measure(head, celltext(d.rows[1][c])) + 14px,
                maximum(r -> measure(plain, first(celltext(Filters.cell_of(d.rows[r], c)), 300)), sample, init=0px))
  natural = [clamp(need(c), 24px, WIDEST_CELL) + 2CELL_PAD for c in s.columns]
  total = sum(natural, init=0px)
  widths = total < wide ? natural .* (num(wide) / num(total)) : natural
  v.widths = (key, widths)
  widths
end

"The text of `text` as a cell `room` wide shows it: on one line, and cut short with an … when it's too long"
filter_cell(v::FilterView, text, room, face) = get!(v.cut, (text, room, face.style)) do
  length(v.cut) > 20_000 && empty!(v.cut)
  shown = first(celltext(text), 300)
  while measure(face, shown) > room && length(shown) > 1
    shown = first(shown, max(1, floor(Int, (length(shown) - 1) * num(room) / num(measure(face, shown))) - 1)) * "…"
  end
  shown
end

"How many rows the table of `v` shows, of the `n` that meet its conditions"
rows_to_show(v::FilterView, n) = v.whole ? n : min(n, FILTER_ROWS)

describe(v::FilterView) = begin
  e = editor(v)
  d, s = filter_shown!(v)
  load, url = v.lang == LOAD, load_url(v)
  v.job === nothing || redraw_in!(v, 0.2)   # so that a frame comes soon to see if the rows have come
  with_theme(component_theme(e.zoom)) do
    count = s === nothing ? "" : Filters.summary(length(s.rows), length(d.rows) - 1, more=d.more)
    icon = !load ? "funnel" : isempty(url) ? "file-earmark-arrow-down" : "cloud-arrow-down"
    refresh = isempty(url) ? () : (block_button!(v, :refresh, :refresh, icon="arrow-clockwise", words=v.job === nothing ? "Refresh" : "Loading…",
                                                 tip="Ask $(Saves.host(url)) for the rows again", off=v.job !== nothing || !isempty(load_problem(v))),)
    bar = block_bar(Box(width(6px)), Icon(icon, size=14px, color=colours.dim), Box(width(4px)),
      source_button(v),
      (isempty(count) ? () : (rule(), Box(label(count, 12px, color=colours.dim))))...,
      Box(width(grow=grow)),
      (isempty(v.saved) ? () : (Box(label(v.saved, 12px, color=colours.dim)), Box(width(6px))))...,
      refresh...,
      block_button!(v, :save, :save, icon="download", words="Save", tip="Save the rows that show as a new file", off=s === nothing || isempty(s.rows)))
    picker = picks_file(v) ? picker_section(v) : ()
    # With no `from`, the picker says what to do, so there's nothing else to say
    load && isempty(strip(v.spec.from)) && return Column(block_look()..., clip=true, name="Filter", bar, picker...)
    said = load ? load_line(v) : ()
    # A load block shows no field for conditions until it has one
    chips = load && isempty(v.spec.conditions) && isempty(v.spec.show) ? () : filter_chips(v, d, s)
    # While the first rows from a server are on their way, or when it can't be asked, the line under the top says why
    s === nothing && return Column(block_look()..., clip=true, name="Filter", bar, picker..., said..., chips...,
                                   (v.job !== nothing && isempty(load_copy(url)) || !isempty(url) && !isempty(load_problem(v)) ? () :
                                    (block_note(d.problem),))...)
    problems = isempty(s.problems) ? () : (Row(width(grow=grow), padding(0px, 12px, 8px, 12px), Alignment.Start,
      Box(width(grow=grow), Text(join(s.problems, " "), size=12px, family=SANS, color=colours.accent, wrap=WrapMode.words))),)
    Column(block_look()..., clip=true, name="Filter", bar, picker..., said..., chips..., problems..., filter_grid(v, d, s)...)
  end
end

"""
The rows of chips at the top of a filter, with the field that adds one at the
end. The chips go onto as many rows as they need.
"""
filter_chips(v::FilterView, d, s) = begin
  e = editor(v)
  chips = Any[block_part!(() -> FilterChip(of=v, k=k), v, (:chip, k)) for k in eachindex(v.spec.conditions)]
  s !== nothing && !isempty(v.spec.show) && length(s.columns) < length(d.rows[1]) && push!(chips, block_part!(() -> FilterChip(of=v, k=0), v, (:chip, 0)))
  adder = filter_adder(v)
  adder.color = colours.ink
  # The field suggests a condition on the last column of numbers. The first is often an id.
  names = isempty(d.rows) ? String[] : d.rows[1]
  c = findlast(identity, d.numbers)
  adder.placeholder = c === nothing ? (isempty(names) ? "Add a condition" : "Add a condition, like $(names[1]) is …") :
                                      "Add a condition, like $(names[c]) > 100"
  w = window_of(v)
  typing = w !== nothing && w.focus === adder
  field = Row(fixed(ADD_W), height(CHIP_H), padding(8px, 0px), child_gap=6px, radius(6px), Alignment.Center,
              background(colours.bg), border(1px, :solid, typing ? colours.accent : colours.line),
              Icon("plus", size=12px, color=colours.dim), Box(width(grow=grow), height(grow=grow), adder))
  # Each row of chips takes chips while they fit
  room = e.width - 24px
  lines, used = Vector{Any}[Any[]], 0px
  # Without rows, there's nothing to add a condition to, so only the chips show
  s === nothing && isempty(chips) && return Any[]
  for (chip, wide) in [[(chip, chip_width(chip)) for chip in chips]; s === nothing ? Tuple{Any,px}[] : [(field, ADD_W)]]
    !isempty(lines[end]) && used + wide > room && (push!(lines, Any[]); used = 0px)
    push!(lines[end], chip)
    used += wide + 6px
  end
  [Row(width(grow=grow), padding(k == 1 ? 10px : 0px, 12px, k == length(lines) ? 10px : 6px, 12px), child_gap=6px, Alignment.Center, line...)
   for (k, line) in enumerate(lines)]
end

"What a chip says: its condition, or how many columns are hidden"
chip_words(c::FilterChip) = begin
  v = c.of
  c.k == 0 || return get(v.spec.conditions, c.k, "")
  d, s = filter_shown!(v)
  n = s === nothing ? 0 : length(d.rows[1]) - length(s.columns)
  n == 1 ? "1 column hidden" : "$n columns hidden"
end

"Why the filter can't use the condition of chip `c`, or \"\""
chip_problem(c::FilterChip) = begin
  d, s = filter_shown!(c.of)
  s === nothing || c.k == 0 || c.k > length(s.conditions) ? "" : s.conditions[c.k].problem
end

chip_width(c::FilterChip) = measure(cell_face(), chip_words(c)) + 10px + 8px + 16px

describe(c::FilterChip) = begin
  bad = !isempty(chip_problem(c))
  cross = block_part!(() -> ChipCross(of=c), c.of, (:cross, c.k))
  Row(height(CHIP_H), padding(0px, 4px, 0px, 10px), child_gap=4px, radius(CHIP_H / 2), Alignment.Center, name="Condition",
      background(c.k == 0 ? colours.bg : colours.chip), border(1px, :solid, bad ? colours.accent : colours.chip_line),
    Box(label(chip_words(c), 12px, color=bad ? colours.accent : c.k == 0 ? colours.dim : colours.ink)), cross)
end

cursor(::FilterChip) = :arrow
draw(ctx, size, ui::ConcreteRect, c::FilterChip) = (c.rect = (ui.left, ui.top, ui.width, ui.height); nothing)
# The mouse over a chip whose condition can't be used says why
onmouse(c::FilterChip, ev::MouseMove) = begin
  why = chip_problem(c)
  isempty(why) && return nothing
  show_tooltip!(ev.window, tip_label(why), c.rect..., placement=:bottom, gap=6px)
  handled
end

describe(x::ChipCross) = Box(fixed(16px), radius(8px), Alignment.Center, background(ishovered(x) ? colours.hover : clear),
  Icon("x", size=12px, color=ishovered(x) ? colours.ink : colours.dim))
cursor(::ChipCross) = :hand
onmouse(::ChipCross, ::MouseMove) = handled

# A click on the × takes the condition away, or shows every column again
onkey(x::ChipCross, ev::KeyPress{Keys.mouse_left}) = begin
  c = x.of
  v = c.of
  hide_tooltip!(ev.window)
  f = Filters.query(v.lines)
  c.k == 0 ? empty!(f.show) : c.k <= length(f.conditions) && deleteat!(f.conditions, c.k)
  filter_write!(v, f)
  handled
end

# Return in the field adds what it holds as a condition. Esc empties it, and gives the keyboard back to the page.
onkey(v::FilterView, ev::KeyPress{Keys.enter}) = begin
  unmodified(ev) || return nothing
  adder = filter_adder(v)
  ev.window.focus === adder || return (focus(editor(v)); handled)
  words = String(strip(adder.text))
  isempty(words) && return handled
  f = Filters.query(v.lines)
  push!(f.conditions, words)
  adder.text, adder.cursor, adder.anchor = "", 0, 0
  filter_write!(v, f)
  handled
end
onkey(v::FilterView, ev::KeyPress{Keys.escape}) = begin
  unmodified(ev) || return nothing
  adder = filter_adder(v)
  adder.text, adder.cursor, adder.anchor = "", 0, 0
  focus(editor(v))
  handled
end

"""
The table of the filter `v`, and the line under it that says how many more
rows there are. Only the rows that are in the window are made.
"""
filter_grid(v::FilterView, d, s) = begin
  e = editor(v)
  wide = e.width - 2px   # the room inside the line round the block
  widths = filter_widths!(v, d, s, wide)
  room = sum(widths, init=0px)
  v.across = clamp(v.across, 0px, max(0px, room - wide))
  n = rows_to_show(v, length(s.rows))
  _, h = window_size(e)
  # The rows that the window shows, with a few each side. The table's top is where it was drawn last.
  lo = clamp(floor(Int, -num(v.top + HEAD_H) / num(ROW_H)) - 8, 0, n)
  hi = clamp(lo + ceil(Int, num(h) / num(ROW_H)) + 16, lo, n)
  plain = cell_face()
  row(k) = (r = s.rows[k];
    Row(fixed(room), height(ROW_H), Alignment.Start, background(iseven(k) ? colours.stripe : clear),
      [Row(fixed(w), height(ROW_H), padding(CELL_PAD, 0px), Alignment.Center, clip=true,
           label(filter_cell(v, Filters.cell_of(d.rows[r], c), w - 2CELL_PAD, plain), 12px))
       for (c, w) in zip(s.columns, widths)]...))
  heads = [block_part!(() -> FilterHead(of=v, column=c), v, (:head, c)) for c in s.columns]
  foreach(((h, w),) -> h.wide = w, zip(heads, widths))
  none = isempty(s.rows) ? (Box(fixed(min(room, wide)), height(2ROW_H), label("No row meets the conditions.", 12px, color=colours.dim)),) : ()
  table = Column(fixed(room), Alignment.Start,
    Row(fixed(room), height(HEAD_H), Alignment.Start, background(colours.head), heads...),
    spacer(ROW_H * lo), [row(k) for k in lo+1:hi]..., spacer(ROW_H * (n - hi)), none...)
  grid = block_part!(() -> FilterGrid(of=v), v, :grid)
  grid.inside = Box(Alignment.Start, offset_x=-v.across, table)
  more = length(s.rows) > FILTER_ROWS ? (block_part!(() -> FilterMore(of=v), v, :more),) : ()
  (Box(width(grow=grow), height(1px), background(colours.line)), grid, more...)
end

describe(g::FilterGrid) = Row(width(grow=grow), Alignment.Start, clip_x=true, name="Rows", detach!(g.inside))
cursor(::FilterGrid) = :arrow
draw(ctx, size, ui::ConcreteRect, g::FilterGrid) = (g.of.top = ui.top; nothing)

# Two fingers that move sideways, or the wheel with ⇧ held, scroll a wide table sideways. They do that anywhere on the
# block, as on a schedule. Their move up or down scrolls the page.
onscroll(v::FilterView, ev::MouseScroll) = begin
  ev.delta[1] == 0px && return nothing
  v.across = max(0px, v.across - 30ev.delta[1])
  ev.delta[2] == 0px ? handled : nothing
end

describe(h::FilterHead) = begin
  v = h.of
  d, s = filter_shown!(v)
  c = h.column
  way = s !== nothing && s.sorted == c ? (Filters.down(v.spec) ? :desc : :asc) : nothing
  lit = ishovered(h) || v.asking == c
  names = d.rows[1]
  fewer = s !== nothing && any(x -> x.column == c && isempty(x.problem), s.conditions)
  colour = fewer ? colours.accent : colours.ink
  marks = ((fewer ? (Icon("funnel-fill", size=9px, color=colours.accent),) : ())...,
           (way !== nothing ? (Icon(way == :asc ? "chevron-up" : "chevron-down", size=9px, color=colours.ink),) :
            lit && !fewer ? (Icon("chevron-down", size=9px, color=colours.faint),) : ())...)
  room = h.wide - 2CELL_PAD - 13px * length(marks)
  Row(fixed(h.wide), height(HEAD_H), padding(CELL_PAD, 0px), child_gap=4px, Alignment.Center, clip=true,
      background(lit ? colours.hover : clear),
    Box(label(filter_cell(v, names[c], max(room, 12px), cell_face(true)), 12px, color=colour, weight="Semibold")), marks...)
end

cursor(::FilterHead) = :hand
onmouse(::FilterHead, ::MouseMove) = handled

onkey(h::FilterHead, ev::KeyPress{Keys.mouse_left}) = begin
  v, c = h.of, h.column
  e = editor(v)
  v.asking = c
  v.was = copy(v.lines)
  names = filter_shown!(v).data.rows[1]
  listed = filter_values(v, c) !== nothing
  # The menu's field starts with the words that the column's cells must have now
  if !listed
    field = filter_field(v)
    had = Filters.looked_for(v.spec, names, c, :has)
    field.text = isempty(had) ? "" : had[1]
    field.cursor = field.anchor = length(field.text)
  end
  menu = block_part!(() -> FilterMenu(of=v), v, :menu)
  # A click outside the menu closes it and keeps what's chosen
  popup!(ev.window, menu, anchor=h, placement=:below, gap=4px, width=SHEET_MENU_W, key=FILTER_KEY,
         onclose=() -> (v.asking = 0; focus(e)), theme=component_theme(e.zoom))
  listed || focus(filter_field(v))
  handled
end

"Close the menu of the filter `v`, and give the keyboard back to the page"
close_filter_menu!(v::FilterView) = begin
  v.asking = 0
  w = window_of(v)
  w === nothing || close_popup!(w, FILTER_KEY)
  focus(editor(v))
  handled
end

describe(m::FilterMenu) = begin
  v, c = m.of, found_colours()
  d, s = filter_shown!(v)
  section(words) = Row(width(grow=grow), height(22px), padding(8px, 0px), Alignment.Center, label(words, 10px, color=c.dim, weight="Semibold"))
  pick(what; value="", count=0) = (p = block_part!(() -> FilterPick(of=v, what=what, value=value), v, (:pick, what, value)); p.count = count; p)
  between() = Box(width(grow=grow), height(13px), Alignment.Center, Box(width(grow=grow), height(1px), background(c.rule)))
  values = v.asking > 0 ? filter_values(v, v.asking) : nothing
  fewer = values === nothing ?
    (section("FILTER FOR"),
     Box(width(grow=grow), padding(4px, 2px),
       Box(width(grow=grow), height(28px), padding(8px, 0px), radius(6px), border(1px, :solid, c.line), background(c.frame), filter_field(v)))) :
    (section("SHOW"), [pick(:value, value=text, count=n) for (text, n) in values]...)
  hide = s !== nothing && length(s.columns) > 1 ? (between(), pick(:hide)) : ()
  Box(width(grow=grow), padding(6px), radius(8px), background(c.frame), border(1px, :solid, c.line),
      shadow(0, 6, 16, RGBA(60 / 255, 45 / 255, 20 / 255, 0.2)), name="Column menu",
    Column(width(grow=grow), Alignment.Start, section("SORT"), pick(:asc), pick(:desc), between(), fewer..., hide...))
end

# The menu sees a key before its text field does. Return keeps what's chosen, and esc puts back the lines that the block had.
onkey(m::FilterMenu, ev::KeyPress{Keys.enter}) = unmodified(ev) ? close_filter_menu!(m.of) : nothing
onkey(m::FilterMenu, ev::KeyPress{Keys.escape}) = begin
  unmodified(ev) || return nothing
  v = m.of
  was = v.was
  close_filter_menu!(v)
  write_block!(v, v.lang, was)
  handled
end

"True when the line `p` of a menu is on: the order that the rows have, or a value that's ticked"
picked(p::FilterPick) = begin
  v = p.of
  p.what == :value || return p.what in (:asc, :desc) && (s = filter_shown!(v).subset; s !== nothing && s.sorted == v.asking) &&
                             Filters.down(v.spec) == (p.what == :desc)
  ticked = Filters.looked_for(v.spec, filter_shown!(v).data.rows[1], v.asking, :is)
  any(t -> Filters.alike(p.value, t), ticked)
end

describe(p::FilterPick) = begin
  v, c = p.of, found_colours()
  d = filter_shown!(v).data
  on = picked(p)
  back = background(ishovered(p) ? c.pick : c.frame)
  if p.what == :value
    ticked = !isempty(Filters.looked_for(v.spec, d.rows[1], v.asking, :is))
    return Row(width(grow=grow), height(26px), padding(8px, 0px), radius(6px), child_gap=8px, Alignment.Center, back,
      Box(fixed(10px), (on ? (Icon("check", size=10px, color=c.ink),) : ())...),
      Box(width(grow=grow), Alignment.Start, clip_x=true,
        label(isempty(p.value) ? "Empty" : p.value, 13px, color=isempty(p.value) || !(on || !ticked) ? c.dim : c.ink, weight=on ? "Semibold" : "")),
      Box(label(commas(p.count), 11px, color=c.dim)))
  end
  numbers = v.asking > 0 && get(d.numbers, v.asking, false)
  icon, words = p.what == :hide ? ("eye-slash", "Hide this column") :
                p.what == :asc ? ("chevron-up", numbers ? "Smallest first" : "A–Z") : ("chevron-down", numbers ? "Largest first" : "Z–A")
  Row(width(grow=grow), height(28px), padding(8px, 0px), radius(6px), child_gap=8px, Alignment.Center,
      on ? background(c.pick) : back,
    Icon(icon, size=10px, color=on ? c.ink : c.dim), label(words, 13px, color=on ? c.ink : c.dim, weight=on ? "Semibold" : ""))
end

cursor(::FilterPick) = :hand
onmouse(::FilterPick, ::MouseMove) = handled

"""
A click on an order puts the rows in that order, or back in the table's order
when they're in it already. A click on a value ticks it, or takes the tick
away, and only the rows with a ticked value show. With every value ticked, or
none, every row shows. A click on the last line hides the column.
"""
onkey(p::FilterPick, ::KeyPress{Keys.mouse_left}) = begin
  v = p.of
  c = v.asking
  d, s = filter_shown!(v)
  (c > 0 && s !== nothing) || return handled
  names = d.rows[1]
  f = Filters.query(v.lines)
  if p.what == :hide
    close_filter_menu!(v)
    return (filter_write!(v, Filters.hide!(f, names, c, s.columns)); handled)
  elseif p.what == :value
    ticked = Filters.looked_for(f, names, c, :is)
    k = findfirst(t -> Filters.alike(p.value, t), ticked)
    k === nothing ? push!(ticked, p.value) : deleteat!(ticked, k)
    length(ticked) == length(filter_values(v, c)) && empty!(ticked)
    Filters.look_for!(f, names, c, :is, ticked)
  else
    Filters.sort_by!(f, names, picked(p) ? 0 : c, p.what == :desc, d.numbers[c])
  end
  filter_write!(v, f)
  handled
end

"What the line under the table says"
more_words(v::FilterView) = begin
  s = filter_shown!(v).subset
  rest = length(s.rows) - FILTER_ROWS
  v.whole ? "Show the first $FILTER_ROWS rows only" : "and $(commas(rest)) more row$(rest == 1 ? "" : "s")"
end

describe(m::FilterMore) = Row(width(grow=grow), height(30px), padding(12px, 0px), Alignment.Center, clip=true,
  Box(label(more_words(m.of), 12px, color=ishovered(m) ? colours.accent : colours.dim)), Box(width(grow=grow)))
cursor(::FilterMore) = :hand
onmouse(::FilterMore, ::MouseMove) = handled

# A click on the line under the table shows every row, or only the first ones again. When rows go, the line stays under the mouse.
onkey(m::FilterMore, ::KeyPress{Keys.mouse_left}) = begin
  v = m.of
  e = editor(v)
  s = filter_shown!(v).subset
  hidden = ROW_H * (length(s.rows) - FILTER_ROWS)
  v.whole = !v.whole
  v.whole || (e.scroll.offset = max(0px, e.scroll.offset - hidden))
  handled
end

"""
Write the rows that the filter `v` shows into the file at `path`. A JSON file
gets the things that the rows came from, as the file that the filter reads
had them, when it's a JSON file. Any other file gets the rows as CSV, with the
columns that show.
"""
save_rows(v::FilterView, path) = begin
  d, s = filter_shown!(v)
  s === nothing && return 0
  if lowercase(splitext(path)[2]) in JSONS && !isempty(d.things)
    write(path, sprint(json_write, Any[d.things[r-1] for r in s.rows]) * "\n")
  else
    mark = lowercase(splitext(path)[2]) == ".tsv" ? '\t' : ','
    quoted(cell) = occursin(mark, cell) || occursin('"', cell) || occursin('\n', cell) ? "\"" * replace(cell, "\"" => "\"\"") * "\"" : cell
    write(path, join((join(quoted.(row), mark) for row in filter_table(d, s)), "\n") * "\n")
  end
  length(s.rows)
end

"The name that the Save panel starts with: the name of the file that the rows came from, with (filtered) after it"
save_name(v::FilterView) = begin
  d = filter_shown!(v).data
  isempty(d.path) && return "$(isempty(d.name) ? "Rows" : d.name).csv"
  # A copy of what a server sent has a name that means nothing, so the server's name takes its place
  isload_copy(d.path) && return d.name * splitext(d.path)[2]
  stem, ext = splitext(basename(d.path))
  "$stem (filtered)$ext"
end

act!(v::FilterView, action, w) = begin
  action == :refresh && return (load_rows!(v); handled)
  action == :choose && return (toggle_picker!(v); handled)
  action == :close_picker && return (v.choosing = false; handled)
  action == :key && return (ask_load_key!(v, w); handled)
  action == :save || return handled
  # A window that isn't on the screen, like one a test makes, has no panel to ask with
  (Sys.isapple() && !isempty(w.glfw)) || return handled
  path = save_panel(editor(v), save_name(v))
  # The panel took the keyboard, so the window never heard the keys that opened it come up
  w.keys = Keys(0)
  path === nothing && return handled
  v.saved = try
    n = save_rows(v, path)
    "Saved $(commas(n)) row$(n == 1 ? "" : "s") to $(basename(path))"
  catch
    "Ladder couldn't save $(basename(path))"
  end
  handled
end

"The filter as HTML: where its rows come from, its conditions, and the rows that show"
filter_html(e, v::FilterView) = begin
  d, s = filter_shown!(v)
  s === nothing && return "<p><em>$(escape(d.problem))</em></p>"
  table = filter_table(d, s)
  numbers = [get(d.numbers, c, false) for c in s.columns]
  side(c) = numbers[c] ? " style=\"text-align: right\"" : ""
  row(tag, cells) = "<tr>" * join("<$tag$(side(c))>$(replace(escape(cell), "\n" => "<br>"))</$tag>" for (c, cell) in enumerate(cells)) * "</tr>"
  good = [x.text for x in s.conditions if isempty(x.problem)]
  caption = escape(d.name) * ": " * Filters.summary(length(s.rows), length(d.rows) - 1, more=d.more) *
            (isempty(good) ? "" : ", where " * join(escape.(good), " and "))
  "<table>\n<caption>$caption</caption>\n<thead>" * row("th", table[1]) * "</thead>\n<tbody>\n" *
    join((row("td", cells) for cells in table[2:end]), "\n") * "\n</tbody>\n</table>"
end

BLOCKS[FILTER] = BlockKind("Filter", "funnel", FilterView, filter_html)

# --- checks of the page's code ------------------------------------------------------------------
#
# A code block in the language `check` holds a line of Julia for each thing
# that must be true, like `area(room) == 12` or `length(walls) > 3`. A blank
# line and a comment are no check.
#
# The block has three levels. At the highest, it's a row of dots: a green dot
# for each check that passes, and a red one for each that doesn't. The mouse
# over a dot shows its line, and what it found. A click on the dots opens the
# block, to the level under that: each line with a tick or a cross. A line that
# compares two values and fails says what each of them was, and a line that
# stops says why. A click on the top of the open block shows the dots again. At
# the lowest level, the block shows as its lines of Julia, with the caret in
# them, as ⌥-click shows it. With the caret on the block as a whole or in its
# lines, the ladder in the top bar goes up and down these levels, and ⌘E too.
#
# Each check of the open block can be changed where it is: a click on its line
# puts a field there, which shows the line as Julia code. Return or a click
# somewhere else writes it into the block, and the check runs again. A line
# that's left empty takes the check away, and Esc leaves it as it was. The
# last line of the list adds a check, and stays open for another one. The
# lines of the block are Julia too, with the colours and the names that a
# `julia` block has.
#
# The lines run in the module of the page's code, with the names that the
# page's `julia` blocks made. They run again when a line of the block changes,
# and each time the page's code runs, as it does with ⌘Return. A click that
# opens the block, and the button at the top of the open block, run them again
# too.

const CHECK = "check"
push!(BLOCK_ICONS, "check2-square", "check-circle-fill", "x-circle-fill", "exclamation-triangle-fill", "arrow-clockwise")
const CHECK_GOOD = colorant"rgb(52,150,86)"
const CHECK_BAD = colorant"rgb(200,60,50)"

"How many times the code of a page has run in this Ladder. A `check` block runs its lines again when it's more than it was."
const CODE_RUNS = Ref(0)

"One line of a `check` block as it came out: its code, how it went, which is :pass, :fail or :stop, and what there is to say of one that didn't pass"
struct Checked
  code::String
  went::Symbol
  said::String
end

"The functions that compare two values. A check that calls one and fails says what the two values were."
const COMPARES = (:(==), :(!=), :≠, :≈, :≉, :(<), :(<=), :≤, :(>), :(>=), :≥, :(===), :(!==), :isa, :in, :∈, :∉, :⊆, :isequal, :isapprox)

"`value` in a few characters, as Julia writes it"
value_brief(value) = (s = try Base.invokelatest(repr, value) catch; "a value" end; length(s) > 40 ? first(s, 39) * "…" : s)

"Run `code`, one line of a `check` block, in the module of the page's code, and give how it went"
check_line(e, code::AbstractString) = begin
  path = isempty(e.buf.path) ? joinpath(e.folder, "untitled.md") : e.buf.path
  # The first line of what went wrong, without the long name that Julia has for the page's module
  why(err) = replace(String(first(split(trouble(err), '\n'))), r" in `Main\.[^`]*`" => "")
  ex = try Meta.parse(code) catch err; return Checked(code, :stop, why(err)) end
  Meta.isexpr(ex, (:incomplete, :error)) && return Checked(code, :stop, "Julia can't read this line.")
  two = Meta.isexpr(ex, :call, 3) && ex.args[1] in COMPARES
  # A line that compares two values gives both, with what the comparison came to
  ran = two ? "let var\"#left\" = ($(ex.args[2])), var\"#right\" = ($(ex.args[3])); (var\"#left\", var\"#right\", $(ex.args[1])(var\"#left\", var\"#right\")) end" : String(code)
  value = try
    cd(() -> running_code(m -> run_in(m, ran, path), e), isdir(docdir(e)) ? docdir(e) : pwd())
  catch err
    return Checked(code, :stop, why(err))
  end
  came = two ? value[3] : value
  came === true && return Checked(code, :pass, "")
  came === false || return Checked(code, :fail, "It came to $(value_brief(came)), which is neither true nor false.")
  Checked(code, :fail, two ? "$(value_brief(value[1])) $(ex.args[1]) $(value_brief(value[2]))" : "")
end

"What a `check` block shows: how each of its lines went"
@def mutable struct CheckView <: SemanticUI
  n::Int = 0                            # its place among the page's check blocks
  first::Int = 0                        # the lines of its block, when the page was last laid out
  last::Int = 0
  lines::Vector{String} = String[]      # the block's lines
  results::Vector{Checked} = Checked[]
  ran::Any = nothing                    # the checks, the count of runs of the page's code and the page that `results` are of
  open::Bool = false                    # it shows each check with what it found, and not a row of dots
  editing::Int = 0                      # the check whose line is being changed, or one more than there are for a new check. 0 is none.
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its dots, its top, its button, its lines and its field, kept between frames
end

reread!(v::CheckView, lines) = (lines == v.lines || (v.lines = lines); v)

"True when a line of a block is a check: it isn't blank and isn't a comment"
ischeck(line) = !isempty(strip(line)) && !startswith(strip(line), '#')

"The lines of a `check` block that are checks: each line that isn't blank and isn't a comment"
checks(lines) = [String(strip(l)) for l in lines if ischeck(l)]

"Where each check is in the lines of a `check` block"
check_places(lines) = findall(ischeck, lines)

"Run the checks of `v`, unless they ran since they last changed and since the page's code last ran"
checked!(v::CheckView) = begin
  e = editor(v)
  key = (checks(v.lines), CODE_RUNS[], e.buf.path)
  v.ran == key && return v
  v.results = Checked[check_line(e, code) for code in key[1]]
  v.ran = key
  v
end

"What the top of a `check` block says: how many of its checks pass"
check_words(results) = begin
  n, passed = length(results), count(r -> r.went == :pass, results)
  n == 0 ? "No checks yet. Write one on each line, like total == 12." :
  passed < n ? "$passed of $n check$(n == 1 ? "" : "s") pass$(passed == 1 ? "es" : "")" :
  n == 1 ? "The check passes" : "All $n checks pass"
end

"The colour of the dot of a check that went as `r` did"
check_colour(r::Checked) = r.went == :pass ? CHECK_GOOD : CHECK_BAD

"A dot of a `check` block at its highest level. The mouse over it shows the check's line, and what it found."
@def mutable struct CheckDot <: SemanticUI
  of::Any = nothing
  i::Int = 0                                  # the check that it's for, in the results of `of`
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)   # where it was last drawn, to put its tooltip under it
end

const CHECK_DOT = 10px   # across a dot of a closed `check` block

describe(d::CheckDot) = begin
  rs = d.of.results
  colour = d.i <= length(rs) ? check_colour(rs[d.i]) : colours.faint
  # The room round a dot is a part of it, so the mouse finds it easily
  Box(padding(3px), Box(fixed(CHECK_DOT), height(CHECK_DOT), radius(CHECK_DOT / 2), background(colour)))
end

cursor(::CheckDot) = :hand
draw(ctx, size, ui::ConcreteRect, d::CheckDot) = (d.rect = (ui.left, ui.top, ui.width, ui.height); nothing)

"What the tooltip of a check's dot says: its line, in the colours of its code, and what it found when it didn't pass"
check_tip(r::Checked) = begin
  code = Column(Alignment.Start, tip_code(split(r.code, '\n'))...)
  isempty(r.said) && return Box(padding(10px, 7px), code)
  said = Text(r.said, size=12px, family=codefont(), subfamily=codestyle(), color=TIP_INK, wrap=WrapMode.none)
  Box(padding(10px, 7px), Column(Alignment.Start, child_gap=6px, code, said))
end

onmouse(d::CheckDot, ev::MouseMove) = begin
  rs = d.of.results
  d.i <= length(rs) && show_tooltip!(ev.window, check_tip(rs[d.i]), d.rect..., placement=:bottom, gap=6px)
end

"The top of an open `check` block. A click on it closes the block, so that it shows its dots."
@def mutable struct CheckTop <: SemanticUI
  of::Any = nothing
end

describe(t::CheckTop) = begin
  v = t.of
  rs = v.results
  good = all(r -> r.went == :pass, rs)
  Row(width(grow=grow), height(34px), padding(0px, 6px, 0px, 12px), child_gap=8px, Alignment.Center, background(colours.block),
      Box(fixed(16px), Alignment.Center, justify=Alignment.Center,
          isempty(rs) ? Icon("check2-square", size=14px, color=colours.dim) : Icon(good ? "check-circle-fill" : "x-circle-fill", size=14px, color=good ? CHECK_GOOD : CHECK_BAD)),
      Box(width(grow=grow), Alignment.Start, label(check_words(rs), 13px, weight="Medium")),
      Box(label(ishovered(t) ? "Click to show only the dots" : "", 11px, color=colours.faint)),
      block_button!(v, :again, :again, icon="arrow-clockwise", tip="Run the checks again"))
end

cursor(::CheckTop) = :hand
onkey(t::CheckTop, ev::KeyPress{Keys.mouse_left}) = unmodified(ev) ? (hide_tooltip!(ev.window); open_checks!(t.of, false); handled) : nothing

"Show each check of `v` with what it found, with `open`, or only a dot for each check. Opening runs the checks again."
open_checks!(v::CheckView, open::Bool) = begin
  open && (v.ran = nothing)
  # A check that's being changed is written as the block closes
  open || v.editing == 0 || (settle_check!(v); focus(editor(v)))
  v.open = open
  redraw_in!(editor(v), 0)
  v
end

act!(v::CheckView, action, w) = begin
  action == :again && (v.ran = nothing; redraw_in!(editor(v), 0))
  handled
end

describe(v::CheckView) = begin
  checked!(v)
  rs = v.results
  v.open || return describe_dots(v)
  mark(r) = r.went == :pass ? Icon("check-circle-fill", size=14px, color=CHECK_GOOD) :
            Icon(r.went == :fail ? "x-circle-fill" : "exclamation-triangle-fill", size=14px, color=CHECK_BAD)
  # What a check found is in a box as tall as its lines, so that the words under it don't come up into it
  words(text, size, colour) = Box(width(grow=grow), Alignment.Start, padding(CHECK_INSET, 3px), Text(text, size=size, family=codefont(), subfamily=codestyle(), color=colour, wrap=WrapMode.words))
  row(k, sign) = Row(width(grow=grow), padding(12px, 3px), child_gap=5px, Alignment.Start,
                     Box(fixed(16px), height(25px), Alignment.Center, justify=Alignment.Center, sign),
                     Column(width(grow=grow), Alignment.Start, check_line!(v, k),
                            (k > length(rs) || isempty(rs[k].said) ? () : (words(rs[k].said, 12px, CHECK_BAD),))...))
  # The last row adds a check, unless the page can't be changed
  adds = check_fixed(v) ? () : (row(length(rs) + 1, Icon("plus", size=14px, color=colours.faint)),)
  Column(block_look()..., clip=true, name="Check",
    block_part!(() -> CheckTop(of=v), v, :top),
    (isempty(rs) && isempty(adds) ? () : (Column(width(grow=grow), Alignment.Start, padding(0px, 5px), (row(k, mark(r)) for (k, r) in enumerate(rs))..., adds...),))...)
end

# --- a check that's changed where it is

"True when the page can't be changed, so its checks can't be"
check_fixed(v::CheckView) = (b = editor(v).buf; readonly(b) || b.fixed)

const CHECK_INSET = 4px   # between the left of a check's line and its code, so that a line under the mouse has room round its words

"The font of a check's code, in the open block"
check_face() = Face(codefont(), codestyle(), 13px, colours.ink, false)

"The line of a check in an open `check` block. A click on it puts a field in its place, to change it."
@def mutable struct CheckLine <: SemanticUI
  of::Any = nothing
  k::Int = 0   # the check that it's for, in the order of the block's checks. One more than there are is the line that adds a check.
end

"The line of the check `k` of `v`, kept between frames"
check_line!(v::CheckView, k::Int) = block_part!(() -> CheckLine(of=v, k=k), v, (:line, k))

"""
The field that takes the place of a check's line while you change it. It
shows its text as Julia code, each part in its colour, with no box round it.
"""
check_input(v::CheckView) = block_part!(v, :edit) do
  TextInput(placeholder="A check, like total == 12", font_family=codefont(), font_size=13px, look=julia_look)
end

"""
How a field of one line of Julia looks: no box, and each part of the code in
its colour. The field's own text is under the colours, and can't be seen. It's
the first text in the field, so the caret and the selection go by it.
"""
julia_look(input, text) = begin
  isempty(input.text) && return Row(width(grow=grow), height(grow=grow), clip=true, text)
  size = TextInputs.text_size(input)
  under = Text(input.text, size=size, family=TextInputs.family(input), color=clear, wrap=WrapMode.none)
  parts = value_parts(input.text, Face(TextInputs.family(input), codestyle(), size, TextInputs.ink(input), false))
  Row(width(grow=grow), height(grow=grow), clip=true,
      Row(width(grow=grow), clip_x=true, Stack(Alignment.Start, offset_x=-input.scroll, under, Row(Alignment.Center, parts...))))
end

describe(l::CheckLine) = begin
  v = l.of
  rs = v.results
  v.editing == l.k && return Row(width(grow=grow), height(25px), padding(CHECK_INSET, 0px), Alignment.Center,
                                 Box(width(grow=grow), height(grow=grow), check_input(v)))
  shown = l.k <= length(rs) ? Row(Alignment.Center, value_parts(rs[l.k].code, check_face())...) :
          Text("Add a check", size=13px, family=codefont(), subfamily=codestyle(), color=colours.faint, wrap=WrapMode.none)
  Row(width(grow=grow), height(25px), padding(CHECK_INSET, 0px), radius(5px), Alignment.Center, clip=true,
      background(ishovered(l) && !check_fixed(v) ? colours.hover : clear), shown)
end

cursor(l::CheckLine) = check_fixed(l.of) ? :arrow : :ibeam

# A click puts the caret in the field where it was in the line. A click with a modifier key down is the page's.
onkey(l::CheckLine, ev::KeyPress{Keys.mouse_left}) = begin
  v = l.of
  (unmodified(ev) && !check_fixed(v) && v.editing != l.k) || return nothing
  hide_tooltip!(ev.window)
  r = rect(l)
  col = r === nothing ? 0 : round(Int, num(ev.window.mouse[1] - r.left - CHECK_INSET) / num(measure(check_face(), "0")))
  open_check!(v, l.k, col)
end

"""
Put a field in the place of the check `k` of `v`, with the caret at `col` in
its line. A check that was being changed is written first.
"""
open_check!(v::CheckView, k::Int, col::Int=typemax(Int)) = begin
  was, n = v.editing, length(check_places(v.lines))
  settle_check!(v)
  # A check that was taken away or added before this one moves it
  0 < was < k && (k += length(check_places(v.lines)) - n)
  places = check_places(v.lines)
  input = check_input(v)
  input.font_family = codefont()
  input.text = k <= length(places) ? String(strip(v.lines[places[k]])) : ""
  input.anchor = input.cursor = clamp(col, 0, length(input.text))
  input.scroll = 0px
  v.editing = k
  focus(input)
  handled
end

"""
Write what the field of `v` holds into the line of its check, and take the
field away. An empty field takes the check away, and the field of a new check
adds one at the end of the block.
"""
settle_check!(v::CheckView) = begin
  k, v.editing = v.editing, 0
  (k == 0 || check_fixed(v)) && return v
  text = String(strip(check_input(v).text))
  lines, places = copy(v.lines), check_places(v.lines)
  if k <= length(places)
    i = places[k]
    text == strip(lines[i]) && return v
    # The line keeps the space before it
    isempty(text) ? deleteat!(lines, i) : (lines[i] = match(r"^\s*", lines[i]).match * text)
  else
    isempty(text) && return v
    push!(lines, text)
  end
  write_block!(v, CHECK, lines)
end

# Return writes the check. After a new check, the field stays at the end of the list for another one.
onkey(v::CheckView, ev::KeyPress{Keys.enter}) = begin
  (unmodified(ev) && v.editing != 0 && ev.window.focus === check_input(v)) || return nothing
  adding = v.editing > length(check_places(v.lines)) && !isempty(strip(check_input(v).text))
  settle_check!(v)
  adding ? open_check!(v, length(check_places(v.lines)) + 1) : focus(editor(v))
  handled
end
# Esc leaves the check as it was
onkey(v::CheckView, ev::KeyPress{Keys.escape}) = begin
  (unmodified(ev) && v.editing != 0 && ev.window.focus === check_input(v)) || return nothing
  v.editing = 0
  focus(editor(v))
  handled
end

"A click somewhere else writes what the field of a check holds"
block_tick!(v::CheckView) = begin
  v.editing == 0 && return v
  w = window_of(v)
  (w === nothing || w.focus !== check_input(v)) && settle_check!(v)
  v
end

"""
A closed `check` block: a dot for each check, in rows as wide as the page
leaves them, and after the dots how many pass. With the mouse over it, the
words also say that a click shows each check.
"""
describe_dots(v::CheckView) = begin
  rs = v.results
  dots = [block_part!(() -> CheckDot(of=v, i=i), v, (:dot, i)) for i in eachindex(rs)]
  # The words after the dots need about 280px
  across = max(1, floor(Int, num(editor(v).width - 280px) / num(CHECK_DOT + 6px)))
  rows = [Row(Alignment.Center, dots[i:min(i + across - 1, end)]...) for i in 1:across:length(dots)]
  words = check_words(rs) * (!isempty(rs) && ishovered(v) ? ". Click to see each one." : "")
  Row(width(grow=grow), Alignment.Center, padding(0px, 4px), child_gap=4px, name="Check",
      (isempty(rows) ? () : (Column(Alignment.Start, rows...),))...,
      Box(width(grow=grow), Alignment.Start, padding(0px, 0px, 0px, 6px), label(words, 13px, color=colours.dim)))
end

cursor(::CheckView) = :hand
# A click on the dots opens the block. A click on an open block, out of its top and its lines, does nothing.
# With ⌥ held, the click is the page's, and it shows the block's lines.
onkey(v::CheckView, ev::KeyPress{Keys.mouse_left}) = unmodified(ev) ? (v.open || (hide_tooltip!(ev.window); open_checks!(v, true)); handled) : nothing

# The levels of a `check` block, from the lowest: its lines, each check with what it found, and a dot for each check
const CHECK_LEVELS = ("the checks as lines of Julia", "each check, with what it found", "a dot for each check")

levels(::CheckView) = CHECK_LEVELS

"True while the caret is in the lines of the block of `v`, so that the block shows as its lines"
in_lines(v::CheckView) = begin
  b = editor(v).buf
  span = block_lines(b, CHECK, v.n)
  span !== nothing && span[1] <= b.caret[1] <= span[2] && picked(b) != span
end

level(v::CheckView) = in_lines(v) ? 1 : v.open ? 2 : 3

level!(v::CheckView, i::Int) = begin
  e = editor(v)
  b = e.buf
  span = block_lines(b, CHECK, v.n)
  span === nothing && return v
  s, t = span
  if i == 1
    # The block shows its lines, with the caret at the start of the first, as a click with ⌥ held puts it
    b.caret = b.anchor = (min(s + 1, t), 0)
  else
    i == 2 ? open_checks!(v, true) : open_checks!(v, false)
    # The caret leaves the block's lines and goes onto the block as a whole, so the block shows as what it makes
    s <= b.caret[1] <= t && (b.caret = b.anchor = (s, 0))
  end
  touch!(e)
  v
end

"""
The view of the `check` block that the caret is on as a whole, or in the lines
of, in a page that shows rich text. It's nothing when the caret is elsewhere.
The top bar asks this block for its levels.
"""
check_in_charge(e) = begin
  b = e.buf
  (rich(b) && !caretless(b) && !julia_file(b)) || return nothing
  i = b.caret[1]
  1 <= i <= length(b.lines) || return nothing
  ks = kinds(b)
  ks[i].kind in (Kind.fence, Kind.code) || return nothing
  s, t = codeblock(b, i)
  (t > s && ks[s].kind == Kind.fence && ks[s].level == 0 && ks[s].lang == CHECK && ks[t].kind == Kind.fence && ks[t].level == 1) || return nothing
  s <= b.anchor[1] <= t || return nothing
  block_view(e, CHECK, block_place(b, CHECK, s))
end

check_html(e, v::CheckView) = begin
  checked!(v)
  "<p><strong>$(escape(check_words(v.results)))</strong></p>\n<ul>\n" *
    join(("<li>$(r.went == :pass ? "✓" : "✗") <code>$(escape(r.code))</code>$(isempty(r.said) ? "" : ": " * escape(r.said))</li>" for r in v.results), "\n") * "\n</ul>"
end

BLOCKS[CHECK] = BlockKind("Check", "check2-square", CheckView, check_html)

# --- checks in a file of Julia code ---
#
# A comment like `# check: share("70%") == 0.7` in a file of Julia code is a
# check, as a line of a `check` block is. It runs in the module of the file's
# code, and a dot at the end of its line says how it went: green when it comes
# to true, and red when it doesn't, with the two values that it compared, or
# with why it stopped. The checks run when the window opens the file, when a
# check changes, and each time code runs, as it does with ⌘Return. A name that
# the file's code makes is there once that code ran: in a file that Ladder
# loaded, at once, and in any other file after ⌘Return in its function. The
# top bar says how many pass, and a click there goes to the next that fails.
# The command Add Check writes a check of the call at the caret, with the
# value that it has now.

const FILE_CHECK = r"^\s*#\s*check:\s*(.*\S)\s*$"

"""
The checks of a file of Julia code: the line of each, and its code. `opens[i]`
is the quote of a string in three quotes that's open at the start of line i,
as `string_opens` gives it. A line in such a string, like the middle of a
docstring or of a prompt for an agent, is text and not a check.
"""
file_checks(lines, opens=nothing) = begin
  out = Tuple{Int,String}[]
  for (i, l) in enumerate(lines)
    occursin("check:", l) || continue
    opens === nothing || opens[i] == '\0' || continue
    m = match(FILE_CHECK, l)
    m === nothing || push!(out, (i, String(m[1])))
  end
  out
end

"True for a window that shows a file of Julia code as its text"
julia_file(e) = endswith(e.buf.path, ".jl") && e.buf.view == :code

"""
In each frame: find the checks of a file of Julia code when its text changed,
and run them when a check changed or code ran since they last ran. What they
found is in `e.nodes[:file_checks]`.
"""
file_checks_tick!(e) = begin
  julia_file(e) || return nothing
  b = e.buf
  s = get(e.nodes, :file_checks, nothing)
  if s === nothing || s.version != b.version
    s = (version=b.version, found=file_checks(b.lines, string_opens(b)), ran=s === nothing ? nothing : s.ran,
         results=s === nothing ? Dict{String,Checked}() : s.results)
  end
  key = (unique(last.(s.found)), CODE_RUNS[])
  if !isempty(key[1]) && key != s.ran
    s = (; s..., ran=key, results=Dict(code => check_line(e, code) for code in key[1]))
  end
  e.nodes[:file_checks] = s
  nothing
end

# A function with checks over it runs again by itself, a second after you stop
# typing, in the module that the file's code has: the one that Ladder made
# when it loaded the file, or when ⌘Return ran code of it. Then its checks run
# again. Other code runs only when you run it, as code that does something
# when it runs can do harm. Code that doesn't run yet, like a line that's half
# typed, leaves the checks as they were.

"How long after the last change to its text a function with checks over it runs again, in seconds"
const LIVE_WAIT = 1.0

"""
The expression of `code`, a top part of a file of Julia code, or nothing when
Julia can't read it or it has more than one. Comments after it are read as
nothing, which `Meta.parse` doesn't do.
"""
part_expr(code::AbstractString) = begin
  all = try Meta.parseall(code) catch; return nothing end
  found = [x for x in all.args if !(x isa LineNumberNode)]
  length(found) == 1 && !Meta.isexpr(found[1], (:error, :incomplete)) ? found[1] : nothing
end

"True when `ex`, a top part of a file of Julia code, defines a function, with its documentation or without"
defines_function(ex) = definition_of(ex) !== nothing

"""
In each frame: a second after the text of a file of Julia code last changed,
run each function of it that has checks over it, and that changed since it
last ran. See "checks in a file of Julia code".
"""
live_checks_tick!(e) = begin
  julia_file(e) || return nothing
  b = e.buf
  s = get(e.nodes, :file_checks, nothing)
  (s === nothing || isempty(s.found)) && return nothing
  key = page_key(b.path)
  mod = something(loaded_module(key), Some(get(PAGE_MODULES, key, nothing)))
  mod === nothing && return nothing
  live = get(e.nodes, :live_checks, nothing)
  # The module has each function as the window had it when the module was first seen, or as it last ran since
  if live === nothing || live.mod !== mod
    e.nodes[:live_checks] = (mod=mod, version=b.version, typed=b.version, changed=0.0,
                             start=Set(t for (_, t) in part_texts(b.lines)), ran=Dict{String,String}())
    return nothing
  end
  live.version == b.version && return nothing
  # Each change starts the wait again
  if live.typed != b.version
    e.nodes[:live_checks] = (; live..., typed=b.version, changed=time())
    redraw_in!(e, LIVE_WAIT)
    return nothing
  end
  wait = LIVE_WAIT - (time() - live.changed)
  wait > 0 && (redraw_in!(e, wait); return nothing)
  # The first line of code under each check is a line of the function that it checks
  under = Set(code_start(b.lines, i) for (i, _) in s.found)
  ran = 0
  for (first, code) in part_texts(b.lines)
    any(l -> first <= l <= first + count('\n', code), under) || continue
    def = definition_of(part_expr(code))
    def === nothing && continue
    # The function is known by its first line, like `twice(x)`
    key = string(def_call(def))
    (haskey(live.ran, key) ? live.ran[key] == code : code in live.start) && continue
    try
      # Blank lines before the code give each of its lines the number that it has in the file
      Base.include_string(mod, "\n"^(first - 1) * code, String(b.path))
      live.ran[key] = code
      ran += 1
    catch
      # Code that doesn't run yet leaves the checks as they were
    end
  end
  e.nodes[:live_checks] = (; live..., version=b.version)
  ran > 0 && (CODE_RUNS[] += 1; redraw_windows!())   # the checks run again
  nothing
end

"What a check of a file says after its dot: nothing when it passed, the values that it compared, or why it stopped"
check_note(r::Checked, loaded::Bool) = begin
  r.went == :pass && return ""
  note = r.went == :fail ? (isempty(r.said) ? "It came to false." : r.said) : r.said
  # A name that the file makes isn't there until the file's code runs
  !loaded && r.went == :stop && occursin("UndefVarError", note) && (note = rstrip(note, '.') * ". Press ⌘Return in its function to run it.")
  length(note) > 100 ? first(note, 99) * "…" : note
end

"""
Draw a dot at the end of each line of a file of Julia code that's a check,
green or red, and what a check that failed found. While the mouse or the
caret is on a check's line, buttons follow: Show Steps, and Fix It for one
that fails. The page's text is at `ui`.
"""
mark_checks(ctx, e, ui) = begin
  buttons = get!(() -> Any[], e.nodes, :check_buttons)
  empty!(buttons)
  s = get(e.nodes, :file_checks, nothing)
  (s === nothing || isempty(s.found) || s.version != e.buf.version) && return nothing
  rows = Dict(s.found)
  loaded = loaded_module(page_key(e.buf.path)) !== nothing
  w = window_of(e)
  mouse = w === nothing ? -1.0 : num(w.mouse[2])
  for it in e.layout[e.shown]
    f = it.content
    f isa Flow || continue
    code = get(rows, it.first, nothing)
    code === nothing && continue
    r = get(s.results, code, nothing)
    r === nothing && continue
    k = length(f.lines)
    vl = f.lines[k]
    right = isempty(vl.segs) ? 0px : last(vl.segs).x + last(vl.segs).w
    mid = num(ui.top + it.top + line_top(f, k) + vl.high / 2)
    x = num(ui.left + right) + 10
    round_box(ctx, x, mid - 4, 8, 8, 4; fill=check_colour(r))
    note = check_note(r, loaded)
    face = Face(SANS, "", px(round(num(f.size) * 0.85)), check_colour(r), false)
    isempty(note) || write_ink(ctx, note, x + 14, mid + 4, face)
    # Buttons for the check that the mouse or the caret is on: see "a check that fails"
    top = num(ui.top + it.top)
    (e.buf.caret[1] == it.first || top <= mouse < top + num(it.tall)) || continue
    left = x + 14 + (isempty(note) ? 0 : num(measure(face, note)) + 10)
    small = Face(SANS, "Medium", px(round(num(f.size) * 0.75)), colours.dim, false)
    for (action, words) in ((:steps, "Show Steps"), (:fix, "Fix It"))
      (action == :fix && (r.went == :pass || needs_run(e, r))) && continue
      across = num(measure(small, words)) + 14
      round_box(ctx, left, mid - 9, across, 18, 5; fill=colours.hover)
      write_ink(ctx, words, left + 7, mid + 4, small)
      push!(buttons, (action, (left, mid - 9, across, 18.0), FileCheck(it.first, code, r.went)))
      left += across + 6
    end
  end
  nothing
end

"Draw the window again when the mouse at `pos` moves onto the line of a check of a file of Julia code, or off it, for the buttons beside a check: see `mark_checks`"
hover_check!(e, pos) = begin
  s = get(e.nodes, :file_checks, nothing)
  (julia_file(e) && s !== nothing && !isempty(s.found) && !isempty(e.layout)) || return nothing
  i = locate(e, pos)[1]
  on = any(((l, _),) -> l == i, s.found) ? i : 0
  get(e.nodes, :check_hover, 0) == on && return nothing
  e.nodes[:check_hover] = on
  redraw_in!(e, 0)
  nothing
end

"The checks of the file of `e` that ran, each with its line and how it went, from the top"
file_results(e) = begin
  s = get(e.nodes, :file_checks, nothing)
  s === nothing && return Tuple{Int,Checked}[]
  [(i, s.results[code]) for (i, code) in s.found if haskey(s.results, code)]
end

"The count of the checks in the top bar, for a file of Julia code that has checks"
check_part(e) = julia_file(e) && !isempty(file_results(e)) ? (node!(CheckCount, e, :check_count),) : ()

describe(c::CheckCount) = begin
  e = editor(c)
  results = last.(file_results(e))
  ishovered(c) || (c.quiet = false)
  Box(height(28px), padding(8px, 0px), radius(6px), background(ishovered(c) ? colours.hover : clear),
    label(check_words(results), 12px, color=all(r -> r.went == :pass, results) ? CHECK_GOOD : CHECK_BAD))
end
cursor(::CheckCount) = :hand
tip(c::CheckCount) = all(((_, r),) -> r.went == :pass, file_results(editor(c))) ? "Go to the next check" : "Go to the next check that fails"
onkey(c::CheckCount, ::KeyPress{Keys.mouse_left}) = (next_check!(editor(c)); hush!(c))

"Put the caret on the next check of the file after the caret's line that fails, round to the top again. When none fails, the next check."
next_check!(e) = begin
  found = file_results(e)
  failing = filter(((_, r),) -> r.went != :pass, found)
  lines = first.(isempty(failing) ? found : failing)
  isempty(lines) && return nothing
  i = something(findfirst(>(e.buf.caret[1]), lines), 1)
  note_place!(e)   # ⌘⌥← comes back here
  show_line!(e, lines[i])
  e.nodes[:hold] = (max(lines[i] - 3, 1), 24px - PAGE_TOP)
  nothing
end

"""
The Julia expression at the caret of the window of `e`, for Add Check, with
its line: what's selected, or else the name at the caret with the names that
dots join it to and what's in the brackets after it, like `share("70%")`.
"""
expression_at(e) = begin
  b = e.buf
  lo, hi = selection(b)
  if lo != hi
    lo[1] == hi[1] || error("Select an expression on one line.")
    return (lo[1], String(strip(excerpt(b, lo, hi))))
  end
  found = name_at(b, b.caret)
  found === nothing && error("Put the caret on a call, like share(\"70%\"), or select an expression.")
  i = b.caret[1]
  chars = collect(b.lines[i])
  from = found.col - sum(o -> length(o) + 1, found.owners, init=0)   # where the names before it start
  stop = found.col + length(found.name)                             # its last character
  if stop < length(chars) && chars[stop+1] == '('
    depth = 0
    for k in stop+1:length(chars)
      chars[k] == '(' && (depth += 1)
      chars[k] == ')' && (depth -= 1)
      if depth == 0
        stop = k
        break
      end
    end
    depth == 0 || error("The brackets after $(found.name) don't close on this line.")
  end
  (i, String(chars[from+1:stop]))
end

"`value` as Julia writes it, for a check to compare with. It's an error when that's too long, or isn't Julia that reads back."
check_value(code, value) = begin
  s = Base.invokelatest(repr, value)
  ex = Meta.parse(s; raise=false)
  (length(s) > 80 || Meta.isexpr(ex, (:error, :incomplete))) && error("$code comes to $(value_brief(value)), which is too long to write in a check.")
  s
end

"""
Write a check of the expression at the caret over its function, with the value
that the expression has now, like `# check: share("70%") == 0.7`. Ladder runs
the expression in the module of the file's code. Later, a change that gives
another value turns the check's dot red. See "checks in a file of Julia code".
"""
add_check!(e) = begin
  julia_file(e) || error("A check of this kind goes in a file of Julia code.")
  b = e.buf
  i, code = expression_at(e)
  value = try
    cd(() -> running_code(m -> run_in(m, code, b.path), e), isdir(docdir(e)) ? docdir(e) : pwd())
  catch err
    why = String(first(split(trouble(err), '\n')))
    error("Ladder couldn't work out $code. $why" * (loaded_module(page_key(b.path)) === nothing ? " Press ⌘Return in its function first." : ""))
  end
  check = value === true ? code : value === false ? "!($code)" : "$code == $(check_value(code, value))"
  # The check goes over the function that the caret is in, after its documentation and the checks that it has
  at = min(code_start(b.lines, first(part_lines(b.lines, i))), i)
  indent = match(r"^\s*", b.lines[at]).match
  caret, anchor = b.caret, b.anchor
  edit!(b, (at, 0), (at, 0), "$(indent)# check: $check\n")
  moved(p) = p[1] >= at ? (p[1] + 1, p[2]) : p
  b.caret, b.anchor = moved(caret), moved(anchor)
  nothing
end

works_here(e, ::Val{:add_check}) = julia_file(e)

# --- a save of a table's rows ------------------------------------------------------------------
#
# A code block in the language `save` writes the rows of the table above it
# into a file, or sends them to a server. save.jl says how the block is
# written. The top of the block says which rows it has and where they go, and
# its button does it: Save or Replace for a file, Send for a server. Nothing
# is written or sent until you click.
#
# The line under the top says what a click will do, and then what happened:
# when the rows went, and what the server said. A send runs in a process of its
# own, so the window never waits for the server. When the Keychain has no key
# with the name that the block gives, a button on that line asks for the key
# and keeps it in the Keychain.

const SAVE = Saves.SAVE
push!(BLOCK_ICONS, "save", "cloud-arrow-up", "arrow-right", "key", "check2", "exclamation-circle")

"What a `save` block shows: which rows it has, where they go, and what happened when they last went"
@def mutable struct SaveView <: SemanticUI
  n::Int = 0                               # its place among the page's save blocks
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  spec::Saves.Save = Saves.Save()
  lines::Vector{String} = String[]         # the lines that `spec` was read from
  job::Any = nothing                       # a send that hasn't ended: a function that gives nothing until it has, then how it went
  sending::Any = nothing                   # what that send has: how many rows, where to, and the name of the key
  said::String = ""                        # what happened at the last click, or ""
  failed::Bool = false                     # true when that went wrong
  nokey::Bool = false                      # the Keychain had no key with the name that `key` gives
  choosing::Bool = false                   # the list of folders is open, after a click on Choose
  sourcing::Bool = false                   # the list of files to save the rows of is open, after Choose a file…
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its buttons, kept between frames
end

reread!(v::SaveView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.spec = Saves.query(lines)
  # What happened at the last click was about the block as it was
  v.job === nothing && (v.said = ""; v.failed = false; v.nokey = false)
  v
end

"""
The rows that the save block `v` writes, as a FilterRows: those of the table
that's nearest above it, or of the first one under the heading that `from`
names. A filter's rows are those that it shows. When they came from a JSON
file and the filter hides no column, `things` holds the thing that each one
came from, so a JSON file or a server gets each thing whole.
"""
save_data(v::SaveView) = begin
  e = editor(v)
  tables = page_tables(e)
  from = String(strip(v.spec.from))
  # `from` can name a file of rows
  isfilterable(from) && return filter_file(abspath(docdir(e), expanduser(from)), "")
  k = isempty(from) ? something(findlast(t -> t.last < v.first, tables), 0) : something(named_table(e, tables, from), 0)
  k == 0 && return no_rows(isempty(from) ?
    "Put a table, a filter or a CSV file's table over this block, and the block saves its rows." :
    "This page has no table called “$(from)”, and no file of that name beside it.")
  t = tables[k]
  name = isempty(t.under) ? "the table above" : t.under
  top = kinds(e.buf)[t.first]
  if top.kind == Kind.fence && top.lang in (FILTER, LOAD)
    x = filter_subset(e, e.buf.lines[t.first+1:t.last-1], tables, t.first; load=top.lang == LOAD)
    d, s = x.data, x.subset
    s === nothing && return no_rows(d.problem)
    whole = !isempty(d.things) && s.columns == collect(1:length(d.rows[1]))
    return FilterRows(filter_table(d, s), [get(d.numbers, c, false) for c in s.columns],
                      whole ? Any[d.things[r-1] for r in s.rows] : Any[], isempty(d.path) ? name : d.name, d.path, d.more, "")
  end
  # A line that shows a CSV file: the rows come from that file
  file = t.first == t.last ? table_file(docdir(e), e.buf.lines[t.first]) : nothing
  rows = t.headed ? t.rows : [[["Name", "Value"]]; t.rows]   # a sheet's rows have no names
  wide = maximum(length, rows)
  rows = [[r; fill("", wide - length(r))] for r in rows]
  file === nothing ? FilterRows(rows, Csvs.numbers(rows), Any[], name, "", false, "") :
                     FilterRows(rows, Csvs.numbers(rows), Any[], basename(file[1]), file[1], false, "")
end

"The file that the save block `v` writes, as a whole path, or \"\" when it sends to a server or has no `to`"
save_target(v::SaveView) = (to = String(strip(v.spec.to)); isempty(to) || Saves.isurl(to) ? "" : abspath(docdir(editor(v)), expanduser(to)))

"True when `a` and `b` are one file"
same_file(a, b) = !isempty(a) && !isempty(b) && (a == b || (ispath(a) && ispath(b) && samefile(a, b)))

"Why the save block `v` can't write `d`, its rows, now, or \"\". `path` is the file that it would write."
save_problem(v::SaveView, d; path=save_target(v)) = begin
  isempty(d.problem) || return d.problem
  length(d.rows) < 2 && return "The table above has no rows to save."
  p = Saves.problem(v.spec)
  isempty(p) || return p
  isempty(path) && return ""
  name = basename(path)
  isdir(path) && return "$name is a folder. Name a file in it, like “$name/rows.csv”."
  isdir(dirname(path)) || return "There's no folder called $(basename(dirname(path))) for $name to go in."
  same_file(path, editor(v).buf.path) && return "$name is this page. Name another file."
  same_file(path, d.path) && return "The rows come from $name, so Ladder won't write over it. Name another file."
  isfile(path) && !(lowercase(splitext(path)[2]) in (".csv", ".tsv", ".tab", ".json", ".txt")) &&
    return "Ladder replaces only a CSV, TSV, JSON or text file, and $name is another kind. Name a new file, or one of those."
  ""
end

"A cell of a column of numbers that JSON can hold as a number, like 12 or -3.5, is a number. Any other cell is text."
json_cell_of(cell, number) = number && occursin(Saves.PLAIN_NUMBER, cell) ? JSONNumber(cell) : cell

"""
The text of `d`, the rows of a save block, as CSV, TSV or JSON. JSON is a list
with an object for each row, whose keys are the names of the columns, or the
things that the rows came from when `d` has them.
"""
save_text(d::FilterRows, format) = begin
  format == "json" || return Saves.delimited(d.rows, format == "tsv" ? '\t' : ',')
  isempty(d.things) || return sprint(json_write, d.things) * "\n"
  names = [isempty(name) ? "column $c" : name for (c, name) in enumerate(d.rows[1])]
  things = Any[JSONObject(copy(names), Any[json_cell_of(cell, get(d.numbers, c, false)) for (c, cell) in enumerate(row)]) for row in d.rows[2:end]]
  sprint(json_write, things) * "\n"
end

"What the button of `v` will do, before it's clicked. `to` is where the rows would go."
save_plan(v::SaveView, d; to=String(strip(v.spec.to))) = begin
  rows = "the " * Saves.rows_words(length(d.rows) - 1)
  as = uppercase(Saves.format(Saves.Save(to=to, as=v.spec.as)))
  more = d.more ? " $(d.name) has more rows than Ladder reads, so only these go." : ""
  words = if isempty(to)
    "A click asks where to save $rows, as a file."
  elseif Saves.isurl(to)
    key = String(strip(v.spec.key))
    "A click sends $rows to $to as $as, with $(Saves.method(v.spec))$(isempty(key) ? "" : ", and the key “$(key)” from your Keychain")."
  elseif isfile(abspath(docdir(editor(v)), expanduser(to)))
    "A click replaces $(basename(to)) with $rows, as $as."
  else
    "A click writes $rows into a new file, $(basename(to)), as $as."
  end
  words * more
end

"The name that the Save panel starts with, when the block has no `to` yet"
save_start(d::FilterRows) = begin
  ext = isempty(d.things) ? ".csv" : ".json"
  isempty(d.path) || isload_copy(d.path) || return splitext(basename(d.path))[1] * " (saved)" * ext
  (startswith(d.name, "the table") ? "Rows" : d.name) * ext
end

"What went wrong, in words, for an error that Julia gives"
error_words(err) = err isa SystemError ? Libc.strerror(err.errnum) : String(strip(first(split(sprint(showerror, err), '\n'))))

"Write `d`, the rows of `v`, into the file that `v` names. It's written beside it first, so the file is never half there."
write_rows!(v::SaveView, d) = begin
  path = save_target(v)
  part = path * ".part"
  try
    write(part, save_text(d, Saves.format(v.spec)))
    mv(part, path, force=true)
    v.said, v.failed = "Saved $(Saves.rows_words(length(d.rows) - 1)) to $(basename(path)) at $(Libc.strftime("%H:%M", time())).", false
  catch err
    rm(part, force=true)
    v.said, v.failed = "Ladder couldn't write $(basename(path)): $(error_words(err)).", true
  end
  v
end

# What a send runs: it reads the key from the Keychain, and gives it to curl on curl's input, so the key is never
# in a command's words, where any program could see it. It ends with 90 when the Keychain has no such key.
const SEND_SCRIPT = raw"""
key=""
if [ -n "$1" ]; then key=$(security find-generic-password -s "$1" -w 2>/dev/null) || exit 90; fi
{ if [ -n "$key" ]; then printf 'Authorization: Bearer %s\n' "$key"; fi; } |
  curl --silent --show-error --connect-timeout 15 --max-time 120 --proto =http,https -X "$2" -H "Content-Type: $3" -H "Expect:" -H @- --data-binary @"$4" --output "$5" --write-out '%{http_code}' -- "$6"
"""

"The first `most` bytes of the file at `path`, as text, or \"\" when it isn't there"
file_start(path, most=20_000) = isfile(path) ? String(open(io -> read(io, most), path)) : ""

"""
Send the file `body` to the web address `url`, asking with `method`, and tell
the server that it's `type`. With `key`, the Keychain's password of that name
goes with it, as `Authorization: Bearer`. It runs in a process of its own,
and gives a function that's nothing until that has ended. Then it gives what
happened: `nokey` is true when the Keychain had no such key, `code` is the
server's answer, or 0 when it couldn't be reached, `body` is what the server
said, and `error` is why it couldn't be reached. The file `body` goes then.
"""
send_rows(url, method, type, body, key) = begin
  out, code, err = tempname(), tempname(), tempname()
  job = run(pipeline(`sh -c $SEND_SCRIPT sh $key $method $type $body $out $url`, stdout=code, stderr=err), wait=false)
  () -> process_exited(job) ? begin
    heard = (nokey=job.exitcode == 90, code=something(tryparse(Int, strip(file_start(code))), 0), body=file_start(out), error=file_start(err))
    rm.((out, code, err, body), force=true)
    heard
  end : nothing
end

"What sends a save block's rows to a server. A test puts its own function here, so that it uses no network and no Keychain."
const SAVE_SENDER = Ref{Function}(send_rows)

"Send `d`, the rows of `v`, to the server that `v` names. The window goes on while they go."
send_save!(v::SaveView, d) = begin
  as = Saves.format(v.spec)
  body = tempname()
  write(body, save_text(d, as))
  to, key = String(strip(v.spec.to)), String(strip(v.spec.key))
  v.sending = (n=length(d.rows) - 1, to=to, key=key)
  v.said, v.failed, v.nokey = "Sending $(Saves.rows_words(v.sending.n)) to $(Saves.host(to))…", false, false
  v.job = SAVE_SENDER[](to, Saves.method(v.spec), Saves.content_type(as), body, key)
  v
end

"What a server said with an answer that says no: its message when it sent JSON with one, or else the first line of its text"
server_said(body) = begin
  x = try json_value(Vector{UInt8}(body)) catch; nothing end
  if x isa JSONObject
    for name in ("message", "error_description", "error", "detail", "title")
      k = findfirst(==(name), x.keys)
      k === nothing && continue
      y = x.values[k]
      y isa AbstractString && return Saves.said(y)
      if y isa JSONObject
        j = findfirst(==("message"), y.keys)
        j !== nothing && y.values[j] isa AbstractString && return Saves.said(y.values[j])
      end
    end
  end
  Saves.said(body)
end

"Note what happened to the send of `v`: `heard` is what the function that SAVE_SENDER gave says when the send has ended"
heard!(v::SaveView, heard) = begin
  n, to, key = v.sending
  server = Saves.host(to)
  if heard.nokey
    v.said, v.failed, v.nokey = "Your Keychain has no key called “$(key)”. Add it, and click Send again.", true, true
  elseif heard.code == 0
    words = Saves.curl_words(heard.error)
    v.said, v.failed = "Ladder couldn't reach $server$(isempty(words) ? "." : ": " * words)", true
  elseif 200 <= heard.code < 300
    v.said, v.failed = "Sent $(Saves.rows_words(n)) to $server at $(Libc.strftime("%H:%M", time())). The server said $(Saves.answer(heard.code)).", false
  else
    words = server_said(heard.body)
    v.said, v.failed = "The server at $server said $(Saves.answer(heard.code))$(isempty(words) ? "." : ": " * words)", true
  end
  v
end

"In each frame while rows are on their way, a save block looks to see if they have gone"
block_tick!(v::SaveView) = begin
  sources_tick!(v)
  from_pick_tick!(v)
  v.job === nothing && return v
  heard = v.job()
  heard === nothing && return v
  v.job = nothing
  heard!(v, heard)
end

"""
Keep `key` in the login Keychain as the password called `name`, in place of
one that's there. It goes to `security` on its input, as hex, so it's never
in a command's words. True when the Keychain has it after that.
"""
keep_key(name, key) = begin
  any(c -> c in "\"\\\n", name) && return false
  try
    open(pipeline(`security -i`, stdout=devnull, stderr=devnull), "w") do io
      write(io, "add-generic-password -U -a ladder -s \"$name\" -l \"$name\" -X $(bytes2hex(codeunits(key)))\n")
    end
  catch
    return false
  end
  success(pipeline(`security find-generic-password -s $name`, stdout=devnull, stderr=devnull))
end

"What keeps a key in the Keychain. A test puts its own function here, so that it leaves the Keychain alone."
const KEY_KEEPER = Ref{Function}(keep_key)

"Ask for the key called `name`, in a panel that hides what you type. It gives the key, or nothing if you cancel."
key_panel(name) = with_pool() do
  alert = msg(msg(cls("NSAlert"), "alloc"), "init")
  msg(alert, "setMessageText:", nsstring("The key for $name"))
  msg(alert, "setInformativeText:", nsstring("Ladder keeps it in your Keychain, as the password called “$(name)”. The page holds only the name."))
  msg(alert, "addButtonWithTitle:", nsstring("Keep"))
  msg(alert, "addButtonWithTitle:", nsstring("Cancel"))
  field = ccall((:objc_msgSend, libobjc), Ptr{Cvoid}, (Ptr{Cvoid}, Ptr{Cvoid}, NTuple{4,Float64}),
                msg(cls("NSSecureTextField"), "alloc"), sel("initWithFrame:"), (0.0, 0.0, 280.0, 24.0))
  msg(alert, "setAccessoryView:", field)
  msg(msg(alert, "window"), "setInitialFirstResponder:", field)
  # 1000 is the first button, Keep
  kept = ccall((:objc_msgSend, libobjc), Int, (Ptr{Cvoid}, Ptr{Cvoid}), alert, sel("runModal")) == 1000
  key = kept ? jstring(msg(field, "stringValue")) : nothing
  msg(field, "release")
  msg(alert, "release")
  key
end

"Keep `key` as the key that `v` names, and say how that went"
key_given!(v::SaveView, key) = begin
  name = String(strip(v.spec.key))
  kept = KEY_KEEPER[](name, key)
  v.said, v.failed, v.nokey = kept ? "Ladder put the key “$(name)” in your Keychain. Click Send to send the rows." :
                                     "Ladder couldn't put the key “$(name)” in your Keychain.", !kept, !kept
  v
end

# A save block with no `to` lists the folders beside the page, as a breadcrumb
# that's open, with a field for the name of the file under it. A click on a
# folder goes into it, and a click on a name of the path goes back up. Its
# button saves the rows in that folder, with that name, and makes that file
# the block's `to`. A save block that has a `to` has a Choose button, which
# opens the list in the folder of its file. When a file of that name is there,
# the button says Replace.

"True when the save block `v` shows where to save: it has no `to` yet, or Choose was clicked"
asks_where(v::SaveView) = v.choosing || isempty(strip(v.spec.to))

"The folder that the save block `v` lists first: the folder of its file, or the page's folder"
save_folder(v::SaveView) = begin
  path, dir = save_target(v), docdir(editor(v))
  !isempty(path) && isdir(dirname(path)) ? dirname(path) : isdir(dir) ? dir : homedir()
end

"The breadcrumb that picks the folder of the save block `v`. It lists only folders."
save_picker(v::SaveView) = block_part!(() -> Breadcrumb(at=save_folder(v), open=true, folders=true), v, :picker)

"The field for the name of the file that the save block `v` makes"
save_name_field(v::SaveView) = block_part!(v, :name) do
  TextInput(text=save_start(save_data(v)), placeholder="The name of the file", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"""
The file that the save block `v` would save `d` in, from its list of folders
and its name field. A name that has no end, like .csv, gets the end of the
kind that the rows are written as. It's \"\" when the field is empty.
"""
save_chosen(v::SaveView, d) = begin
  name = String(strip(save_name_field(v).text))
  isempty(name) && return ""
  isempty(splitext(name)[2]) && (name *= isempty(d.things) ? ".csv" : ".json")
  joinpath(save_picker(v).at, name)
end

"What the save block `v` shows while it asks where to save: what to do, the breadcrumb, and the field for the name"
save_picker_section(v::SaveView) = begin
  e = editor(v)
  p, field = save_picker(v), save_name_field(v)
  p.room = e.width - 24px
  w = window_of(v)
  typing = w !== nothing && w.focus === field
  name = Row(width(grow=grow), height(30px), child_gap=8px, Alignment.Center,
    Box(label("Name", 12px, color=colours.dim)),
    Row(width(grow=grow), height(28px), padding(8px, 0px), radius(6px), Alignment.Center,
        background(colours.bg), border(1px, :solid, typing ? colours.accent : colours.line),
        Box(width(grow=grow), height(grow=grow), field)))
  (Column(width(grow=grow), Alignment.Start, padding(10px, 12px, 4px, 12px), child_gap=8px, name="Picker",
     Box(width(grow=grow), Text("Choose a folder, and type the file's name. The end of the name says how the rows are written: .csv, .tsv or .json.",
                                size=12px, family=SANS, color=colours.dim, wrap=WrapMode.words)),
     p, name),)
end

"Open the list of folders of the save block `v` at the folder of its file, with the file's name in the field, or close it"
toggle_save_picker!(v::SaveView) = begin
  v.choosing = !v.choosing
  v.choosing || return v
  p, field = save_picker(v), save_name_field(v)
  p.at, p.open = save_folder(v), true
  to = String(strip(v.spec.to))
  field.text = isempty(to) || Saves.isurl(to) ? save_start(save_data(v)) : basename(to)
  field.cursor = field.anchor = length(field.text)
  v
end

"Save `d`, the rows of `v`, in the file that its list of folders and its name field say, and make that file its `to`"
save_here!(v::SaveView, d) = begin
  path = save_chosen(v, d)
  (isempty(path) || !isempty(save_problem(v, d; path))) && return v
  v.choosing = false
  write_block!(v, SAVE, Saves.with_line(v.lines, :to, tilde(named(editor(v), path))))
  write_rows!(v, d)
end

# Return in the field for the file's name saves, as the button does. Esc closes the list that Choose opened.
onkey(v::SaveView, ev::KeyPress{Keys.enter}) = begin
  unmodified(ev) && ev.window.focus === get(v.parts, :name, nothing) || return nothing
  act!(v, :save, ev.window)
end
onkey(v::SaveView, ev::KeyPress{Keys.escape}) = begin
  unmodified(ev) && ev.window.focus === get(v.parts, :name, nothing) || return nothing
  v.choosing = false
  focus(editor(v))
  handled
end

act!(v::SaveView, action, w) = begin
  # A window that isn't on the screen, like one a test makes, has no panel to ask with
  asks = Sys.isapple() && !isempty(w.glfw)
  if action == :key
    asks && !isempty(strip(v.spec.key)) || return handled
    key = key_panel(String(strip(v.spec.key)))
    # The panel took the keyboard, so the window never heard the keys that opened it come up
    w.keys = Keys(0)
    key === nothing || isempty(key) || key_given!(v, key)
    return handled
  end
  action == :choose && return (toggle_save_picker!(v); handled)
  action == :close_picker && return (v.sourcing = false; handled)
  action == :save && v.job === nothing || return handled
  d = save_data(v)
  # Without a `to`, or after Choose, the rows go where the list of folders and the name field say
  asks_where(v) && return (save_here!(v, d); handled)
  isempty(save_problem(v, d)) || return handled
  Saves.isurl(v.spec.to) ? send_save!(v, d) : write_rows!(v, d)
  handled
end

describe(v::SaveView) = begin
  e = editor(v)
  d = save_data(v)
  asks = asks_where(v)
  # While it asks where to save, the file is the one that the list of folders and the name field say
  chosen = asks ? save_chosen(v, d) : ""
  problem = !asks ? save_problem(v, d) : isempty(chosen) ? "Type a name for the file." : save_problem(v, d; path=chosen)
  to = asks ? chosen : String(strip(v.spec.to))
  url = Saves.isurl(to)
  key = String(strip(v.spec.key))
  v.job === nothing || redraw_in!(v, 0.2)   # so that a frame comes soon to see if the rows have gone
  with_theme(component_theme(e.zoom)) do
    what = isempty(d.problem) ? "$(Saves.rows_words(length(d.rows) - 1)) of" : "Save the rows of"
    path = asks ? chosen : save_target(v)
    go = v.job !== nothing ? "Sending…" : url ? "Send" : !isempty(path) && isfile(path) ? "Replace" : "Save"
    tip = url ? "Send the rows to $(Saves.host(to))" : isempty(to) ? "Type a name for the file first" :
          go == "Replace" ? "Write the rows over $(basename(to))" : "Save the rows in $(basename(to))"
    # A save block that has a `to` has a button that chooses another file. One without asks anyway.
    choose = isempty(strip(v.spec.to)) ? () :
      (block_button!(v, :choose, :choose, icon="folder2-open", words="Choose", tip=v.choosing ? "Close the list of folders" : "Choose another file to save in", on=v.choosing),)
    bar = block_bar(Box(width(6px)), Icon(url ? "cloud-arrow-up" : "save", size=14px, color=colours.dim), Box(width(4px)),
      Box(label(what, 13px, weight="Semibold")), Box(width(6px)), source_button(v),
      (isempty(to) ? () : (Box(width(6px)), Icon("arrow-right", size=12px, color=colours.dim), Box(width(6px)),
                           Box(label(url ? Saves.host(to) : basename(to), 13px))))...,
      (url && !isempty(key) ? (Box(width(10px)), Icon("key", size=12px, color=colours.dim), Box(width(4px)), Box(label(key, 12px, color=colours.dim))) : ())...,
      Box(width(grow=grow)),
      choose...,
      block_button!(v, :go, :save, icon=url ? "cloud-arrow-up" : "save", words=go, tip=tip, off=!isempty(problem) || v.job !== nothing, bold=true),
      Box(width(6px)))
    picker = asks ? save_picker_section(v) : ()
    words, icon, colour = !isempty(problem) ? (problem, "exclamation-circle", colours.accent) :
                          isempty(v.said) || asks ? (save_plan(v, d; to), "", colours.dim) :
                          (v.said, v.failed ? "exclamation-circle" : v.job === nothing ? "check2" : "", v.failed ? colours.accent : colours.dim)
    note = Row(width(grow=grow), padding(9px, 12px, 9px, 12px), Alignment.Center, child_gap=6px, clip=true, name="Said",
      (isempty(icon) ? () : (Icon(icon, size=13px, color=colour),))...,
      Box(width(grow=grow), Text(words, size=12px, family=SANS, color=colour, wrap=WrapMode.words)),
      (v.nokey && Sys.isapple() ? (block_button!(v, :key, :key, icon="key", words="Add Key…", tip="Type the key, and Ladder keeps it in your Keychain"),) : ())...)
    Column(block_look()..., clip=true, name="Save", bar, (v.sourcing ? from_picker_section(v) : ())..., picker..., note)
  end
end

"The save block as HTML: which rows it saves, and where to"
save_html(e, v::SaveView) = begin
  d = save_data(v)
  to = String(strip(v.spec.to))
  what = isempty(d.problem) ? "the $(Saves.rows_words(length(d.rows) - 1)) of $(d.name)" : "the rows of the table above"
  "<p><em>Saves $(escape(what)) $(isempty(to) ? "as a file" : "to " * escape(to)).</em></p>"
end

BLOCKS[SAVE] = BlockKind("Save", "save", SaveView, save_html)

# --- a form that adds a row to a table ---------------------------------------------------------
#
# A code block in the language `form` shows a field for each column of the
# table above it, and a button, Add, that adds a row to the table with what's
# in the fields. forms.jl says how the block is written, and what each field
# takes. A line `to: Jobs` in the block adds to the first table under the
# heading Jobs.
#
# A field is what its column takes:
#
# - A day: a narrow field, and a month that floats under it while it has the
#   keyboard. A click on a day of the month puts that day in the field. ↓ and
#   ↑ go to the next day and the one before, and with ⌥ they go a week. Words
#   like `fri`, `25 nov` and `tomorrow` name a day too, and the words beside
#   the field say which day that is.
# - A time or a number: a narrow field. A number's field shows what the
#   column's numbers have before them and after them, like $ or m.
# - Yes or no: a box to tick, with a click or with Space.
# - A few words that come again and again, like Quote and Booked: a chooser,
#   which is a bar with those words side by side. A click picks a word, and so
#   do ← and →, and the first letter of a word. The first word is picked until
#   you pick another.
#
# Return in a field adds the row too. Tab goes to the next field, ⇧Tab to the
# one before, and Esc closes the month, and then gives the keyboard back to
# the page. After an add, the fields are empty again, the first has the
# keyboard, and the line under them says what was added. One ⌘Z takes the row
# away.
#
# A day, a time or a number goes in the row the way that its column writes it.
# What's typed is changed to that when the keyboard leaves the field. Add
# doesn't add a row while a field holds something that it doesn't take: the
# field gets a red edge, and the line under the fields says what it takes.
#
# What's typed in the fields isn't in the file until it's added. Only a table
# of the page's text takes rows: not a sheet, a spreadsheet or a filter.

const FORM = Forms.FORM
push!(BLOCK_ICONS, "input-cursor-text", "plus-lg", "calendar-event", "chevron-left", "chevron-right", "check", "check2", "exclamation-circle")

const FORM_NARROW = 210px     # how wide the field for a day, a time or a number is
const MONTH_KEY = :form_month
const MONTH_CELL = 30px       # how wide a day of the month that floats is
const MONTH_W = 7 * MONTH_CELL + 18px

"What a `form` block shows: a field for each column of a table, and a button that adds a row"
@def mutable struct FormView <: SemanticUI
  n::Int = 0                               # its place among the page's forms
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  spec::Forms.Form = Forms.Form()
  lines::Vector{String} = String[]         # the lines that `spec` was read from
  said::String = ""                        # what the last add did, or ""
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its fields and its buttons, kept between frames
end

"What a form keeps between frames about its fields"
@def mutable struct FormState <: SemanticUI
  rows::Any = nothing                      # the rows and the lines that `fields` were worked out from
  spec::Any = nothing
  fields::Vector{Forms.Field} = Forms.Field[]
  had::Int = 0                             # the column whose field had the keyboard in the last frame, or 0
  refused::Int = 0                         # the column whose field stopped the last Add, or 0
  month::Int = 0                           # the column whose field the month floats under, or 0
  shut::Int = 0                            # the column whose field has the keyboard after its month was closed, or 0
  shows::Date = Date(1)                    # the first day of the month that floats
  seen::Any = nothing                      # the day that the field named when the month last went to its month
end

"The box to tick of a column of a form that takes yes or no"
@def mutable struct FormTick <: SemanticUI
  of::Any = nothing
  on::Bool = false
  yes::String = "Yes"   # what the row gets when it's ticked, and when it's not
  no::String = "No"
end

"The chooser of a column of a form that takes one of a few words: a RadioGroup, and a ring round it while it has the keyboard"
@def mutable struct FormChoice <: SemanticUI
  of::Any = nothing
  group::Any = nothing
end

"The month that floats under a form's field for a day. A click on one of its days puts the day in the field."
@def mutable struct FormMonth <: SemanticUI
  of::Any = nothing
  side::Symbol = :bottom   # the side of the field that it's on
end
"A day of that month"
@def mutable struct MonthDay <: SemanticUI
  of::Any = nothing
  day::Date = Date(1)
end

reread!(v::FormView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.spec = Forms.query(lines)
  v
end

"""
The table of the page that the form `v` adds rows to, as `page_tables` gives
it: the one under the heading that `to` names, or the one nearest above. It's
words that say why, when there's no table that it can add to.
"""
form_table(v::FormView) = begin
  e = editor(v)
  tables = page_tables(e)
  to = String(strip(v.spec.to))
  k = isempty(to) ? something(findlast(t -> t.last < v.first, tables), 0) : something(named_table(e, tables, to), 0)
  k == 0 && return isempty(to) ? "Put a table over this form, and the form adds rows to it." : "This page has no table called “$(to)”."
  t = tables[k]
  kinds(e.buf)[t.first].kind == Kind.table || return "A form adds rows only to a table of the page's text, and the one $(isempty(to) ? "above" : "called “$(to)”") is a $(table_kind(e, t))."
  t
end

"What the form calls the table `t`: its heading, or “the table above”"
form_target(t) = isempty(t.under) ? "the table above" : t.under

form_state(v::FormView) = block_part!(FormState, v, :state)

"What each field of the form `v` takes, as `Forms.fields` gives it for the table `t`. It's worked out once for each change of the table or of the block."
form_fields(v::FormView, t=form_table(v)) = begin
  t isa String && return Forms.Field[]
  st = form_state(v)
  (st.rows === t.rows && st.spec === v.spec) || (st.rows = t.rows; st.spec = v.spec; st.fields = Forms.fields(t.rows, v.spec))
  st.fields
end

"The text field of the form `v` for column `k`"
form_field(v::FormView, k::Int) = block_part!(v, (:field, k)) do
  TextInput(placeholder="", font_family=SANS, font_size=13px, look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"The box to tick of the form `v` for column `k`"
form_tick(v::FormView, k::Int) = block_part!(() -> FormTick(of=v), v, (:tick, k))

"The chooser of the form `v` for column `k`. A click on one of its words gives it the keyboard."
form_choice(v::FormView, k::Int) = block_part!(v, (:choice, k)) do
  c = FormChoice(of=v)
  c.group = RadioGroup(labels=String[], onchange=_ -> focus(c))
  setfield!(c.group, :parent, c)
  c
end

"What takes the keyboard for the field `f` of column `k`: its box to tick, its chooser, or its text field"
form_part(v::FormView, k::Int, f::Forms.Field) = f.kind == :tick ? form_tick(v, k) : !isempty(f.choices) ? form_choice(v, k) : form_field(v, k)

"The column whose field has the keyboard of the window `w`, or nothing"
form_focused(v::FormView, w) = begin
  for (key, part) in v.parts
    key isa Tuple && key[1] in (:field, :tick, :choice) && part === w.focus && return key[2]
  end
  nothing
end

"How many fields the form `v` has: one for each column of its table"
form_width(v::FormView) = (t = form_table(v); t isa String ? 0 : length(first(t.rows)))

"What the field `f` of column `k` puts in its cell now, or nothing when it holds something that it doesn't take"
form_cell(v::FormView, k::Int, f::Forms.Field) =
  f.kind == :tick ? (form_tick(v, k).on ? f.yes : f.no) :
  !isempty(f.choices) ? f.choices[clamp(form_choice(v, k).group.selected, 1, length(f.choices))] :
  Forms.value(f, form_field(v, k).text; today=calendar_today())

"True while the field `f` of column `k` has nothing in it: no words, and no tick. A chooser always has a word picked, so it doesn't count."
form_empty(v::FormView, k::Int, f::Forms.Field) =
  f.kind == :tick ? !form_tick(v, k).on : !isempty(f.choices) || isempty(strip(form_field(v, k).text))

"Give the keyboard to the field `f` of column `k`, with all its words selected"
form_focus!(v::FormView, k::Int, f::Forms.Field) = begin
  part = form_part(v, k, f)
  part isa TextInput && ((part.anchor, part.cursor) = (0, length(part.text)))
  focus(part)
end

"What the field `f` takes, in words that say why Add added no row"
form_takes(f::Forms.Field) = begin
  today = calendar_today()
  f.kind == :day ? "$(f.name) takes a day, like $(Forms.written(today, f.style)), $(Dates.day(today)) $(Dates.monthabbr(today)) or tomorrow." :
  f.kind == :time ? "$(f.name) takes a time, like $(Forms.written(14, 30, f.style))." :
  "$(f.name) takes a number, like $(Forms.amount(f, "1200"))."
end

"""
Add a row to the table of the form `v`, with what's in its fields, in one edit,
so one ⌘Z takes it away. The caret stays with its text. The fields are emptied
then, and the first gets the keyboard. Nothing happens while every field is
empty. A field that holds something that it doesn't take stops the add, and
gets the keyboard.
"""
add_row!(v::FormView) = begin
  t = form_table(v)
  t isa String && return v
  e = editor(v)
  b = e.buf
  readonly(b) && return v
  fields = form_fields(v, t)
  all(k -> form_empty(v, k, fields[k]), eachindex(fields)) && return v
  st = form_state(v)
  cells = [form_cell(v, k, f) for (k, f) in enumerate(fields)]
  bad = findfirst(isnothing, cells)
  if bad !== nothing
    st.refused, v.said = bad, ""
    # The month would cover the words that say why, so it goes until ↓ or its button shows it again
    st.month == 0 || shut_month!(v)
    fields[bad].kind == :day && (st.shut = bad)
    window_of(v) === nothing || form_focus!(v, bad, fields[bad])
    redraw_in!(v, 0)
    return v
  end
  at = line_end(b, t.last)
  line = Forms.row_line(cells)
  caret, anchor = b.caret, b.anchor
  edit!(b, at, at, "\n" * line)
  stop = (t.last + 1, length(line))
  b.caret, b.anchor = moved(caret, at, at, stop), moved(anchor, at, at, stop)
  for (k, f) in enumerate(fields)
    f.kind == :tick && (form_tick(v, k).on = false)
    isempty(f.choices) || (group = form_choice(v, k).group; group.selected = 1; group.slid = 1.0)
    field = form_field(v, k)
    field.text, field.cursor, field.anchor = "", 0, 0
  end
  st.refused = 0
  name = first(filter(!isempty, strip.(cells)))
  v.said = "Added “$(length(name) > 40 ? first(name, 39) * "…" : name)” to $(form_target(t))."
  window_of(v) === nothing || isempty(fields) || form_focus!(v, 1, fields[1])
  redraw_in!(v, 0)
  v
end

# --- the month under a field for a day ---

"The day that the field of column `k` names now, or nothing"
field_day(v::FormView, k::Int) = Forms.day(form_field(v, k).text; today=calendar_today())

"Put the day `d` in the field of column `k`, written as its column writes days, with all of it selected"
field_day!(v::FormView, k::Int, d::Date) = begin
  fields = form_fields(v)
  k in eachindex(fields) || return handled
  field = form_field(v, k)
  field.text = Forms.written(d, fields[k].style)
  field.anchor, field.cursor = 0, length(field.text)
  handled
end

"Show the month under the field of column `k`, at the month of the day that the field names, or at this month"
show_month!(v::FormView, k::Int, w) = begin
  st = form_state(v)
  st.month, st.shut = k, 0
  st.seen = field_day(v, k)
  st.shows = Dates.firstdayofmonth(something(st.seen, calendar_today()))
  month = FormMonth(of=v)
  v.parts[:month] = month
  # The keys stay with the field, and a click outside the month is the app's, as it is with no month
  popup!(w, month, anchor=form_field(v, k), placement=:bottom, gap=9px, width=MONTH_W, key=MONTH_KEY, modal=false,
         onclose=() -> (st.month = 0; st.shut = k), theme=component_theme(editor(v).zoom))
end

"Take the month away. It stays away while its field keeps the keyboard, until ↓ or its button shows it again."
shut_month!(v::FormView) = begin
  st = form_state(v)
  st.month == 0 || (st.shut = st.month)
  st.month = 0
  w = window_of(v)
  w === nothing || close_popup!(w, MONTH_KEY)
  handled
end

"""
What happens to a form in each frame, before the page is laid out. What's
typed in a field is written as its column writes it when the keyboard leaves
the field. The month shows under a field for a day while that field has the
keyboard, and goes to the month of the day that's typed there.
"""
block_tick!(v::FormView) = begin
  w = window_of(v)
  w === nothing && return v
  st = form_state(v)
  fields = form_fields(v)
  k = something(form_focused(v, w), 0)
  k in eachindex(fields) || (k = 0)
  if st.had != k
    if st.had in eachindex(fields) && form_part(v, st.had, fields[st.had]) isa TextInput
      left = form_field(v, st.had)
      cell = Forms.value(fields[st.had], left.text; today=calendar_today())
      cell === nothing || (cell = Forms.shown(fields[st.had], cell))
      cell === nothing || cell == left.text || (left.text = cell; left.anchor = left.cursor = length(cell))
    end
    st.had = k
  end
  st.refused in eachindex(fields) && form_cell(v, st.refused, fields[st.refused]) !== nothing && (st.refused = 0)
  if k == 0 || fields[k].kind != :day
    st.shut = 0
    st.month == 0 || (shut_month!(v); st.shut = 0)
  elseif st.month != k && st.shut != k
    # The month goes beside where its field was drawn. A field that's new in this frame has it in the next.
    rect(form_field(v, k)) === nothing ? redraw_in!(v, 0) : show_month!(v, k, w)
  end
  if st.month != 0
    d = field_day(v, st.month)
    d == st.seen || (st.seen = d; d === nothing || (st.shows = Dates.firstdayofmonth(d)))
  end
  v
end

describe(d::MonthDay) = begin
  v = d.of
  st = form_state(v)
  c = found_colours()
  on = st.month != 0 && field_day(v, st.month) == d.day
  today = d.day == calendar_today()
  ink = on ? colours.bg : today ? colours.accent : Dates.month(d.day) == Dates.month(st.shows) ? c.ink : RGBA(c.dim, 0.6)
  Row(fixed(MONTH_CELL), height(28px), Alignment.Center, justify=Alignment.Center, name="Day",
    Row(fixed(MONTH_CELL - 2px), height(26px), radius(6px), Alignment.Center, justify=Alignment.Center,
        background(on ? colours.accent : ishovered(d) ? c.pick : clear), border(1px, :solid, today && !on ? colours.accent : clear),
      Box(label(string(Dates.day(d.day)), 12px, color=ink, weight=on || today ? "Semibold" : ""))))
end

cursor(::MonthDay) = :hand
cursor(::FormMonth) = :arrow
onmouse(::MonthDay, ::MouseMove) = handled
# A click on a day puts it in the field, and the month goes
onkey(d::MonthDay, ::KeyPress{Keys.mouse_left}) = begin
  v = d.of
  k = form_state(v).month
  k == 0 && return handled
  field_day!(v, k, d.day)
  field = form_field(v, k)
  field.anchor = field.cursor
  focus(field)
  shut_month!(v)
end
# A click between the days does nothing, and the field keeps the keyboard
onkey(::FormMonth, ::KeyPress{Keys.mouse_left}) = handled

describe(m::FormMonth) = begin
  v = m.of
  st = form_state(v)
  c = found_colours()
  start = Calendars.monday(st.shows)
  head = Row(width(grow=grow), height(28px), Alignment.Center, child_gap=2px,
    Box(width(7px)), Box(label(Calendars.title(st.shows), 13px, color=c.ink, weight="Semibold")), Box(width(grow=grow)),
    block_button!(v, :month_today, (:month, 0), words="Today", tip="Show this month"),
    block_button!(v, :month_back, (:month, -1), icon="chevron-left", tip="The month before"),
    block_button!(v, :month_on, (:month, 1), icon="chevron-right", tip="The month after"))
  names = Row(width(grow=grow), height(22px), Alignment.Center,
    [Row(fixed(MONTH_CELL), Alignment.Center, justify=Alignment.Center, Box(label(name, 11px, color=c.dim))) for name in Calendars.DAYS]...)
  # Six weeks always, so that the box is as tall for every month
  day(n) = (d = block_part!(() -> MonthDay(of=v), v, (:month_day, n)); d.day = start + Day(n); d)
  weeks = [Row(width(grow=grow), Alignment.Center, [day(7week + n) for n in 0:6]...) for week in 0:5]
  Box(width(grow=grow), padding(8px), radius(8px), background(c.frame), border(1px, :solid, c.line),
      shadow(0, 6, 16, RGBA(60 / 255, 45 / 255, 20 / 255, 0.2)), name="Month",
    Column(width(grow=grow), Alignment.Start, head, names, weeks...))
end

placed!(m::FormMonth, side) = (m.side = side; nothing)
draw(ctx, size, ui::ConcreteRect, m::FormMonth) = (k = form_state(m.of).month; k == 0 ? nothing : caret(ctx, ui, m.side, rect(form_field(m.of, k))))

# --- the box to tick ---

describe(t::FormTick) = begin
  w = window_of(t)
  typing = w !== nothing && w.focus === t
  word = t.on ? t.yes : t.no
  # A word like Yes shows beside the box. A mark like ✓ or x doesn't: the box says it.
  words = count(isletter, word) > 1 ? (Box(label(word, 13px, color=t.on ? colours.ink : colours.dim)),) : ()
  Row(height(28px), child_gap=8px, Alignment.Center, name="Tick",
    Box(fixed(16px), height(16px), radius(4px), Alignment.Center, justify=Alignment.Center,
        background(t.on ? colours.accent : colours.bg),
        border(1.5px, :solid, t.on || typing || ishovered(t) ? colours.accent : colours.marker),
        (t.on ? (Icon("check", size=13px, color=colours.bg),) : ())...),
    words...)
end

cursor(::FormTick) = :hand
onkey(t::FormTick, ::KeyPress{Keys.mouse_left}) = (focus(t); t.on = !t.on; handled)
# Return, Tab and Esc are the form's. Any other key alone does nothing here, so that it does nothing to the page's text.
onkey(::Union{FormTick,FormChoice}, ev::KeyPress{K}) where K = K in (Keys.enter, Keys.tab, Keys.escape) || !unmodified(ev) ? nothing : handled

# --- the chooser ---

describe(c::FormChoice) = begin
  w = window_of(c)
  typing = w !== nothing && w.focus === c
  # The chooser's words are 13px, as the words in the fields beside it are, and its bar is in keeping with them
  with_theme(component_theme(13 / 17)) do
    Box(padding(2px), radius(8px), border(1.5px, :solid, typing ? colours.accent : clear), name="Choice", c.group)
  end
end

"Pick word `to` of the chooser `c`. The raised part of its bar slides there."
pick_choice!(c::FormChoice, to::Int) = begin
  g = c.group
  to = clamp(to, 1, max(length(g.labels), 1))
  to == g.selected || ((g.was, g.slid, g.stepped) = (g.selected, 0.0, time()); g.selected = to)
  handled
end

# A click beside the words gives the chooser the keyboard. ← and → pick the word before and the word after, and a
# letter picks the first word that starts with it.
onkey(c::FormChoice, ::KeyPress{Keys.mouse_left}) = (focus(c); handled)
onkey(c::FormChoice, ev::KeyPress{Keys.left}) = unmodified(ev) ? pick_choice!(c, c.group.selected - 1) : nothing
onkey(c::FormChoice, ev::KeyPress{Keys.right}) = unmodified(ev) ? pick_choice!(c, c.group.selected + 1) : nothing
ontype(c::FormChoice, ev::Typed) = begin
  to = findfirst(word -> startswith(lowercase(word), lowercase(ev.char)), c.group.labels)
  to === nothing || pick_choice!(c, to)
  handled
end
# Space ticks the box that has the keyboard, and no other character does anything there
ontype(t::FormTick, ev::Typed) = (ev.char == ' ' && (t.on = !t.on); handled)

act!(v::FormView, action, w) = begin
  if action isa Tuple && action[1] == :month
    # The buttons at the top of the month show the month before, the month after, or this month
    st = form_state(v)
    st.shows = action[2] == 0 ? Dates.firstdayofmonth(calendar_today()) : st.shows + Dates.Month(action[2])
    return handled
  elseif action isa Tuple && action[1] == :pick
    # The button in a field for a day shows the month, or takes it away
    st = form_state(v)
    k = action[2]
    st.month == k && return shut_month!(v)
    st.shut = 0
    focus(form_field(v, k))
    return handled
  end
  action == :add && add_row!(v)
  handled
end

# Return in a field adds the row. Tab and ⇧Tab go from field to field, round to the first or the last. Esc closes the
# month of a field for a day, and then gives the page the keyboard.
onkey(v::FormView, ev::KeyPress{Keys.enter}) = begin
  (unmodified(ev) && form_focused(v, ev.window) !== nothing) || return nothing
  add_row!(v)
  handled
end
onkey(v::FormView, ev::KeyPress{Keys.tab}) = begin
  k = form_focused(v, ev.window)
  (k !== nothing && (unmodified(ev) || only_held(ev, Keys.shft))) || return nothing
  fields = form_fields(v)
  isempty(fields) && return nothing
  # The field that's left keeps no selection, and the next one has all its words selected
  left = ev.window.focus
  left isa TextInput && (left.anchor = left.cursor)
  to = mod1(k + (only_held(ev, Keys.shft) ? -1 : 1), length(fields))
  form_focus!(v, to, fields[to])
  handled
end
onkey(v::FormView, ev::KeyPress{Keys.escape}) = begin
  (unmodified(ev) && form_focused(v, ev.window) !== nothing) || return nothing
  form_state(v).month == 0 || return shut_month!(v)
  focus(editor(v))
  handled
end

"""
↓ or ↑ in a field for a day: go `by` days from the day that the field names,
and put that day in the field. From an empty field, the first press gives
today. While the month is closed, the first press only shows it.
"""
step_day!(v::FormView, ev, by::Int) = begin
  k = form_focused(v, ev.window)
  week = only_held(ev, Keys.opt)
  (k !== nothing && (unmodified(ev) || week)) || return nothing
  fields = form_fields(v)
  (k in eachindex(fields) && fields[k].kind == :day) || return nothing
  st = form_state(v)
  st.month == k || (st.shut = 0; show_month!(v, k, ev.window); return handled)
  d = field_day(v, k)
  field_day!(v, k, d === nothing ? calendar_today() : d + Day(week ? 7by : by))
end
onkey(v::FormView, ev::KeyPress{Keys.down}) = step_day!(v, ev, 1)
onkey(v::FormView, ev::KeyPress{Keys.up}) = step_day!(v, ev, -1)

"The words in a field of the form while it's empty, which say what it takes"
form_hint(f::Forms.Field) = f.kind == :number ? "A number" : f.kind == :day ? "A day, like $(Forms.written(calendar_today(), f.style))" :
                            f.kind == :time ? "A time, like $(Forms.written(14, 30, f.style))" : ""

"The day `d` in words, for beside the field that names it: its day of the week, and how far it is from today"
day_said(d::Date) = begin
  today = calendar_today()
  "$(Dates.dayname(d)) $(Dates.day(d)) $(Dates.monthname(d))$(Dates.year(d) == Dates.year(today) ? "" : " $(Dates.year(d))"), $(Days.away(d, today))"
end

"What a line of the form's block gets wrong, in words: `name` is before its colon, `words` are after it, and `why` is :column or :kind"
stray_words(name, words, why) = why == :column ? "The table has no column called “$(name)”, so the line “$(name): $(words)” does nothing." :
  "“$(words)” is no kind of field. After “$(name):”, write day, time, number, yes/no or words, or the words to choose from with commas between them."

describe(v::FormView) = begin
  e = editor(v)
  t = form_table(v)
  fields = form_fields(v, t)
  with_theme(component_theme(e.zoom)) do
    title = !isempty(v.spec.title) ? v.spec.title : t isa String ? "Form" : "Add a row to $(form_target(t))"
    bar = block_bar(Box(width(10px)), Icon("input-cursor-text", size=14px, color=colours.dim), Box(width(6px)),
                    Box(label(title, 13px, weight="Semibold")), Box(width(grow=grow)))
    t isa String && return Column(block_look()..., clip=true, name="Form", bar, block_note(t))
    w = window_of(v)
    st = form_state(v)
    keys = maximum(f -> measure(Face(SANS, "", 12px, colours.dim, false), f.name), fields, init=0px) + 4px
    # A field that holds something that it doesn't take says so once the keyboard has left it, or once Add was tried
    fault(k, f) = form_cell(v, k, f) === nothing && (st.refused == k || w === nothing || w.focus !== form_field(v, k))
    edge(wide, k, f, parts...; right=8px) = begin
      typing = w !== nothing && w.focus === form_field(v, k)
      Row(wide, height(28px), padding(0px, right, 0px, 8px), radius(6px), Alignment.Center, child_gap=5px, background(colours.bg),
          border(1px, :solid, fault(k, f) ? CHECK_BAD : typing ? colours.accent : colours.line), parts...)
    end
    rows = map(enumerate(fields)) do (k, f)
      name = Box(fixed(keys), Alignment.Start, label(f.name, 12px, color=colours.dim))
      if f.kind == :tick
        tick = form_tick(v, k)
        tick.yes, tick.no = f.yes, f.no
        return Row(width(grow=grow), child_gap=8px, Alignment.Center, name="Field", name, tick, Box(width(grow=grow)))
      end
      if !isempty(f.choices)
        choice = form_choice(v, k)
        # New words start with the first one picked
        choice.group.labels == f.choices || (choice.group.labels = copy(f.choices); choice.group.selected = 1; choice.group.slid = 1.0)
        return Row(width(grow=grow), child_gap=6px, Alignment.Center, name="Field", name, choice, Box(width(grow=grow)))
      end
      field = form_field(v, k)
      field.placeholder = form_hint(f)
      input = Box(width(grow=grow), height(grow=grow), field)
      if f.kind == :day
        d = field_day(v, k)
        open = st.month == k
        pick = block_button!(v, (:pick, k), (:pick, k), icon="calendar-event", on=open, tip=open ? "Close the month" : "Choose a day from a month")
        Row(width(grow=grow), child_gap=8px, Alignment.Center, name="Field", name,
          edge(fixed(FORM_NARROW), k, f, input, pick, right=0px),
          Row(width(grow=grow), height(28px), Alignment.Center, clip=true, Box(label(d === nothing ? "" : day_said(d), 12px, color=colours.dim)), Box(width(grow=grow))))
      elseif f.kind in (:number, :time)
        # A number's field shows what the column's numbers have round them, until a number is typed with its own
        own = f.kind != :number || Forms.marked(field.text)
        mark(words) = own || isempty(strip(words)) ? () : (Box(label(String(strip(words)), 13px, color=colours.dim)),)
        Row(width(grow=grow), child_gap=8px, Alignment.Center, name="Field", name,
          edge(fixed(FORM_NARROW), k, f, mark(f.before)..., input, mark(f.after)...),
          Box(width(grow=grow)))
      else
        Row(width(grow=grow), child_gap=8px, Alignment.Center, name="Field", name, edge(width(grow=grow), k, f, input))
      end
    end
    empty = all(k -> form_empty(v, k, fields[k]), eachindex(fields))
    bad = findfirst(k -> fields[k].kind != :tick && fault(k, fields[k]), eachindex(fields))
    stray = Forms.stray(v.spec, first(t.rows))
    words, icon, colour = bad !== nothing ? (form_takes(fields[bad]), "exclamation-circle", CHECK_BAD) :
                          !isempty(stray) ? (stray_words(stray[1]...), "exclamation-circle", colours.accent) :
                          !isempty(v.said) ? (v.said, "check2", colours.dim) :
                          ("Return or Add puts what's typed in a new row of $(form_target(t)).", "", colours.dim)
    foot = Row(width(grow=grow), child_gap=8px, Alignment.Center,
      (isempty(icon) ? () : (Icon(icon, size=13px, color=colour),))...,
      Box(width(grow=grow), Text(words, size=12px, family=SANS, color=colour, wrap=WrapMode.words)),
      block_button!(v, :add, :add, icon="plus-lg", words="Add", tip=empty ? "Type in a field first" : "Add a row to $(form_target(t))", off=empty, bold=true))
    Column(block_look()..., clip=true, name="Form", bar,
      Column(width(grow=grow), Alignment.Start, padding(12px, 12px, 10px, 12px), child_gap=8px, rows..., Box(height(2px)), foot))
  end
end

"The form block as HTML: which table it adds rows to"
form_html(e, v::FormView) = begin
  t = form_table(v)
  title = isempty(v.spec.title) ? "" : "<strong>$(escape(v.spec.title))</strong>: "
  "<p><em>$(title)A form that adds rows to $(t isa String ? "a table" : escape(form_target(t))).</em></p>"
end

BLOCKS[FORM] = BlockKind("Form", "input-cursor-text", FormView, form_html)

# --- rows loaded from a server or a file --------------------------------------------------------
#
# A code block in the language `load` shows the rows of a file or of a server
# as a table. It's a filter, so it reads the same lines, and its headings
# have the same menus. It shows no field for conditions until it has some.
#
#     ```load
#     from: https://example.com/api/orders
#     key: orders-api
#     at: data.orders
#     ```
#
# `from` is a CSV, TSV or JSON file, as a filter's is, or a web address. A
# file loads again by itself when it changes. A server is asked for its rows
# when the page opens, and again when you click Refresh. When the address
# changes, it's asked once the address has stayed the same for a second.
#
# `key` names a password in the Keychain, as a save block's does. `as` says
# what kind of file the server sends: csv, tsv or json. Without it, the server
# says, or else its first character does: { or [ is JSON.
#
# Ladder keeps a copy of the last rows that each address gave, in the Mac's
# caches. The block shows the copy while it waits, and when the server can't
# be reached. The line under the top of the block says when the rows came,
# or why they didn't.

const LOAD = "load"
push!(BLOCK_ICONS, "cloud-arrow-down", "file-earmark-arrow-down", "arrow-clockwise")

const LOAD_CACHE = Ref("")   # the folder a test keeps the copies in, in place of the one in the Mac's caches
const LOAD_WAIT = 1.0        # seconds that a new address has to stay the same before the server is asked

"The folder that keeps a copy of the rows that each address last gave"
load_dir() = isempty(LOAD_CACHE[]) ? joinpath(homedir(), "Library", "Caches", "Ladder", "loads") : LOAD_CACHE[]

"The start of the path of the copy of what `url` gave. One address always has the same one."
load_stem(url) = joinpath(load_dir(), string(hash(String(strip(url))), base=16))

"The copy of the rows that `url` last gave, or \"\" when there's none. It's a JSON, CSV or TSV file, as the server sent it."
load_copy(url) = begin
  stem = load_stem(url)
  copies = [stem * ext for ext in (".json", ".csv", ".tsv") if isfile(stem * ext)]
  isempty(copies) ? "" : copies[argmax(mtime.(copies))]
end

"True when `path` is a copy of what a server gave, and not a file of yours"
isload_copy(path) = !isempty(path) && startswith(path, load_dir() * "/")

"The web address that the load block `v` asks, or \"\" when it reads a file or a table"
load_url(v::FilterView) = v.lang == LOAD && Saves.isurl(v.spec.from) ? String(strip(v.spec.from)) : ""

"The name of the Keychain's key that the load block `v` sends, or \"\""
load_key(v::FilterView) = String(strip(Saves.query(v.lines).key))

"Why the load block `v` can't ask its server, or \"\""
load_problem(v::FilterView) = begin
  url, key = load_url(v), load_key(v)
  !isempty(key) && !startswith(lowercase(url), "https://") && !Saves.islocal(url) &&
    return "Ladder sends a key only to an address that starts with https://, so that no one on the way can read it."
  as = lowercase(strip(Saves.query(v.lines).as))
  isempty(as) || as in ("csv", "tsv", "json") || return "Ladder reads rows as csv, tsv or json, so “as: $(as)” has to be one of those."
  ""
end

# What a load runs: it reads the key from the Keychain, and gives it to curl on curl's input, so the key is never
# in a command's words. It ends with 90 when the Keychain has no such key. curl writes the server's answer and
# what kind of file it sent.
const LOAD_SCRIPT = raw"""
key=""
if [ -n "$1" ]; then key=$(security find-generic-password -s "$1" -w 2>/dev/null) || exit 90; fi
{ if [ -n "$key" ]; then printf 'Authorization: Bearer %s\n' "$key"; fi; } |
  curl --silent --show-error --location --max-redirs 5 --compressed --connect-timeout 15 --max-time 120 --max-filesize 104857600 --proto =http,https --proto-redir =http,https -H "Accept: application/json, text/csv;q=0.9, */*;q=0.5" -H @- --output "$2" --write-out '%{http_code} %{content_type}' -- "$3"
"""

"""
Ask the server at `url` for its rows, and write what it sends to the file
`out`. With `key`, the Keychain's password of that name goes with the asking,
as `Authorization: Bearer`. It runs in a process of its own, and gives a
function that's nothing until that has ended. Then it gives what happened:
`nokey` is true when the Keychain had no such key, `code` is the server's
answer, or 0 when it couldn't be reached, `type` is what the server said the
file is, `body` is `out`, and `error` is why it couldn't be reached.
"""
get_rows(url, key, out) = begin
  answer, err = tempname(), tempname()
  job = run(pipeline(`sh -c $LOAD_SCRIPT sh $key $out $url`, stdout=answer, stderr=err), wait=false)
  () -> process_exited(job) ? begin
    words = split(strip(file_start(answer)), ' ', limit=2)
    heard = (nokey=job.exitcode == 90, code=something(tryparse(Int, isempty(words) ? "" : words[1]), 0),
             type=length(words) > 1 ? String(words[2]) : "", body=out, error=file_start(err))
    rm.((answer, err), force=true)
    heard
  end : nothing
end

"What asks a server for a load block's rows. A test puts its own function here, so that it uses no network and no Keychain."
const LOAD_GETTER = Ref{Function}(get_rows)

"True when the load block `v` may ask the web: its window is on the screen, or a test stands in for curl"
load_online(v::FilterView) = (e = editor(v); !Eml.isemail(e.buf.path) && (LOAD_GETTER[] !== get_rows || on_screen(e)))

"Ask the server of the load block `v` for its rows. The window goes on while they come."
load_rows!(v::FilterView) = begin
  url = load_url(v)
  (v.job === nothing && !isempty(url) && isempty(load_problem(v))) || return v
  key = load_key(v)
  v.asked = (url, key)
  v.said, v.failed, v.nokey = "Loading the rows from $(Saves.host(url))…", false, false
  v.job = LOAD_GETTER[](url, key, tempname())
  v
end

"A time, as the block says it: 10:41, or 10:41 on 20 Nov when it isn't today"
when_words(t) = Libc.strftime(Libc.strftime("%F", t) == Libc.strftime("%F", time()) ? "%H:%M" : "%H:%M on %-d %b", t)

"What the block says about the copy of what `url` gave, after a load that failed: when those rows came"
kept_words(url) = (c = load_copy(url); isempty(c) ? "" : " These are the rows that came at $(when_words(mtime(c))).")

"The kind of file that a server sent: what the `as` line says, or what the server says, or what its first character looks like"
load_ext(v::FilterView, type, body) = begin
  as = lowercase(strip(Saves.query(v.lines).as))
  isempty(as) || return "." * as
  t = lowercase(type)
  occursin("json", t) && return ".json"
  occursin("tab-separated", t) && return ".tsv"
  occursin("csv", t) && return ".csv"
  start = lstrip(file_start(body, 64))
  startswith(start, '{') || startswith(start, '[') ? ".json" : ".csv"
end

"`words` with a full stop at the end, unless they end with one already, or with ! or ?"
sentence(words) = occursin(r"[.!?…]$", words) ? words : words * "."

"Note what came of the load of `v`. Rows that came take the place of the copy that the block shows."
loaded!(v::FilterView, heard) = begin
  url, key = v.asked
  server = Saves.host(url)
  if heard.nokey
    v.said, v.failed, v.nokey = "Your Keychain has no key called “$(key)”. Add it, and Ladder loads the rows.", true, true
  elseif heard.code == 0
    words = Saves.curl_words(heard.error)
    v.said, v.failed = sentence("Ladder couldn't reach $server$(isempty(words) ? "" : ": " * words)") * kept_words(url), true
  elseif 200 <= heard.code < 300
    ext = load_ext(v, heard.type, heard.body)
    stem = load_stem(url)
    v.said, v.failed = try
      mkpath(load_dir())
      for x in (".json", ".csv", ".tsv")
        x == ext || rm(stem * x, force=true)
      end
      mv(heard.body, stem * ext, force=true)
      # Read it now, so that the block and what uses its rows show them in this frame
      filter_file(stem * ext, v.spec.at; name=server)
      ("Loaded from $server at $(when_words(time())).", false)
    catch err
      ("Ladder couldn't keep the rows from $(server): $(error_words(err)).", true)
    end
  else
    words = server_said(file_start(heard.body))
    v.said, v.failed = sentence("The server at $server said $(Saves.answer(heard.code))$(isempty(words) ? "" : ": " * words)") * kept_words(url), true
  end
  rm(heard.body, force=true)
  v
end

"""
What a load block does in each frame. It looks at the copy of its rows, so a
new copy shows. When rows that it asked for have come, it keeps them. When it
hasn't asked its server since the page opened, it asks. When its address or
its key has changed, it asks once they have stayed the same for LOAD_WAIT.
"""
load_tick!(v::FilterView) = begin
  url = load_url(v)
  isempty(url) && return v
  copy = load_copy(url)
  isempty(copy) || filter_file(copy, v.spec.at; name=Saves.host(url))
  if v.job !== nothing
    heard = v.job()
    heard === nothing || (v.job = nothing; loaded!(v, heard))
    return v
  end
  v.asked == (url, load_key(v)) && return v
  v.asked !== nothing && time() - v.changed < LOAD_WAIT && return v
  load_online(v) && load_rows!(v)
  v
end

"The words of the line under the top of a load block from a server, or \"\""
load_note(v::FilterView) = begin
  url = load_url(v)
  isempty(url) && return ""
  p = load_problem(v)
  isempty(p) || return p
  isempty(v.said) || return v.said
  copy = load_copy(url)
  isempty(copy) ? "" : "Loaded from $(Saves.host(url)) at $(when_words(mtime(copy)))."
end

"The line under the top of a load block: when its rows came, or why they didn't, and a button that asks for a missing key"
load_line(v::FilterView) = begin
  words = load_note(v)
  isempty(words) && return ()
  bad = v.failed || !isempty(load_problem(v))
  icon = bad ? "exclamation-circle" : v.job === nothing ? "check2" : ""
  colour = bad ? colours.accent : colours.dim
  (Row(width(grow=grow), padding(9px, 12px, 9px, 12px), Alignment.Center, child_gap=6px, clip=true, name="Said",
     (isempty(icon) ? () : (Icon(icon, size=13px, color=colour),))...,
     Box(width(grow=grow), Text(words, size=12px, family=SANS, color=colour, wrap=WrapMode.words)),
     (v.nokey && Sys.isapple() ? (block_button!(v, :key, :key, icon="key", words="Add Key…", tip="Type the key, and Ladder keeps it in your Keychain"),) : ())...),)
end

"Ask for the key that the load block `v` names, and keep it in the Keychain"
ask_load_key!(v::FilterView, w) = begin
  name = load_key(v)
  (Sys.isapple() && !isempty(w.glfw) && !isempty(name)) || return v
  key = key_panel(name)
  # The panel took the keyboard, so the window never heard the keys that opened it come up
  w.keys = Keys(0)
  key === nothing || isempty(key) || key_given!(v, key)
  v
end

"Keep `key` as the key that the load block `v` names, and ask its server again"
key_given!(v::FilterView, key) = begin
  name = load_key(v)
  kept = KEY_KEEPER[](name, key)
  v.said, v.failed, v.nokey = kept ? "Ladder put the key “$(name)” in your Keychain." : "Ladder couldn't put the key “$(name)” in your Keychain.", !kept, !kept
  kept && load_rows!(v)
  v
end

# A load block with no `from` shows a breadcrumb of the page's folder, open, as
# a file in a live block does. Its list has folders, and CSV, TSV and JSON
# files. A click on a folder goes into it, and a click on a file makes that
# file the block's `from`. The Choose button at the top of a load block opens
# the picker again, in the folder of the block's file.

"True when the filter or the load block `v` shows its file picker: Choose a file… was clicked, or it's a load block with no `from` yet"
picks_file(v::FilterView) = v.choosing || v.lang == LOAD && isempty(strip(v.spec.from))

"The folder that the picker of the load block `v` starts in: the folder of its file, or the page's folder"
load_start(v::FilterView) = begin
  e = editor(v)
  from = String(strip(v.spec.from))
  path = isempty(from) || Saves.isurl(from) ? "" : abspath(docdir(e), expanduser(from))
  isfile(path) ? dirname(path) : isdir(docdir(e)) ? docdir(e) : homedir()
end

"The breadcrumb that picks the file of the load block `v`"
load_picker(v::FilterView) = block_part!(() -> Breadcrumb(at=load_start(v), open=true, files=isfilterable), v, :picker)

"What the line over the picker of the load block `v` says"
picker_words(v::FilterView) = begin
  from = String(strip(v.spec.from))
  isempty(from) ? "Choose a CSV, TSV or JSON file, or write a web address in a line like “from: https://example.com/orders”." :
                  "Choose a CSV, TSV or JSON file to $(v.lang == LOAD ? "load" : "filter") in place of $(Saves.isurl(from) ? Saves.host(from) : basename(from))."
end

"What a load block shows while it picks a file: a line that says what to do, and the breadcrumb"
picker_section(v::FilterView) = begin
  p = load_picker(v)
  p.room = editor(v).width - 24px
  words = Box(width(grow=grow), Text(picker_words(v), size=12px, family=SANS, color=colours.dim, wrap=WrapMode.words))
  # A block that has a `from` can close the list and keep it
  top = isempty(strip(v.spec.from)) ? words :
        Row(width(grow=grow), Alignment.Center, child_gap=8px, words,
            block_button!(v, :close_picker, :close_picker, icon="x-lg", words="Close", tip="Close the list of files"))
  (Column(width(grow=grow), Alignment.Start, padding(10px, 12px, 10px, 12px), child_gap=8px, name="Picker", top, p),)
end

"Open the picker of the load block `v`, in the folder of its file, or close it"
toggle_picker!(v::FilterView) = begin
  v.choosing = !v.choosing
  v.choosing || return v
  p = load_picker(v)
  p.at, p.open = load_start(v), true
  v
end

"""
What a load block's picker does in each frame: when a file has been clicked in
its list, that file becomes the block's `from`, and the picker closes. The
path goes in as the page's links have it: from the page's folder when the
file is in it.
"""
pick_tick!(v::FilterView) = begin
  picks_file(v) || return v
  p = load_picker(v)
  isfile(p.at) && isfilterable(p.at) || return v
  path = p.at
  # The next time the picker opens, it starts in a folder, not on this file
  p.at = dirname(path)
  v.choosing = false
  f = Filters.query(v.lines)
  f.from = tilde(named(editor(v), path))
  lowercase(splitext(path)[2]) in JSONS || (f.at = "")
  filter_write!(v, f)
  v
end

BLOCKS[LOAD] = BlockKind("Load", "cloud-arrow-down", (; n) -> FilterView(n=n, lang=LOAD), filter_html)

# --- where a block's rows come from --------------------------------------------------------
#
# A filter, a load block, a save block and a chart read rows. The name at the
# top of each is a button that says where its rows come from. A click opens a
# list under it, as the buttons of a `find` block do: the table nearest above,
# each table of the page that it can read, and a last row, Choose a file…. A
# table there is any table, sheet, spreadsheet, filter, load block or time log
# of the page, or a line that shows a CSV file. A click on a row makes it the
# block's `from`. Choose a file… shows a breadcrumb under the top of the block,
# open, that lists folders and the files that the block can read. A click on
# a file makes it the block's `from`, and Close keeps the `from` that it has.
#
# A `from` line calls a table by the heading over it, like `from: Costs`. The
# second table under that heading is `from: Costs 2`. A table with no heading
# over it is called by the name of the page's file.

const SOURCE_MENU = :source_menu   # the key of the list of where a block's rows can come from

"The button at the top of a block that says where its rows come from. A click opens the list of where else they can."
@def mutable struct SourceButton <: SemanticUI
  of::Any = nothing   # the block's view
end

"The list of where a block's rows can come from, while it shows: its rows, the one picked, and the words typed in its field"
@def mutable struct SourceChooser <: SemanticUI
  of::Any = nothing          # the block's view
  asking::Any = nothing      # :source while the list shows
  rows::Vector{Any} = Any[]
  pick::Int = 1
  typed::String = ""
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its field and its rows, kept between frames
end

"What a table with no heading over it is called: the name of the page's file"
headless_name(e) = isempty(e.buf.path) ? "Untitled" : title(e.buf.path)

"What table `n` of `tables`, the tables of the page of `e`, is called in a `from` line: the heading over it, with a number after it for the second table under that heading and the ones after"
table_name(e, tables, n) = begin
  base(t) = isempty(t.under) ? headless_name(e) : t.under
  name = base(tables[n])
  before = count(k -> Charts.same(base(tables[k]), name), 1:n-1)
  before == 0 ? name : "$name $(before + 1)"
end

"""
Which of `tables`, the tables of the page of `e` in their order, the `from`
line `from` calls, or nothing. A heading calls the first table under it, and
a heading with a number after it calls the table of that number under it. The
name of the page's file calls the tables with no heading over them.
"""
named_table(e, tables, from) = begin
  from = String(strip(from))
  isempty(from) && return nothing
  k = findfirst(t -> Charts.same(t.under, from), tables)
  k === nothing || return k
  m = match(r"^(.*\S)\s+(\d+)$", from)
  base, n = m === nothing ? (from, 1) : (String(m[1]), parse(Int, m[2]))
  ks = [k for (k, t) in enumerate(tables) if Charts.same(isempty(t.under) ? headless_name(e) : t.under, base)]
  1 <= n <= length(ks) ? ks[n] : nothing
end

"What a table of the page of `e` is, in a word or two: the kind of block or line that it's in"
table_kind(e, t) = begin
  k = kinds(e.buf)[t.first]
  k.kind == Kind.table && return "table"
  k.kind == Kind.fence || return "CSV file"
  k.lang == SHEET ? "sheet" : k.lang == SPREADSHEET ? "spreadsheet" : k.lang == FILTER ? "filter" :
  k.lang == LOAD ? "load block" : k.lang == TIMELOG ? "time log" : "block"
end

# The language of each kind of block that reads rows, for writing its lines
source_lang(v::FilterView) = v.lang
source_lang(::SaveView) = SAVE
source_lang(::ChartView) = CHART

"The `from` of the block `v`"
source_from(v::Union{FilterView,SaveView,ChartView}) = String(strip(v.spec.from))

"""
The tables that the block `v` can read, by their places among the page's
tables. A filter, a load block and a save block read the tables above them,
so a table never reads itself. A chart can read any.
"""
source_tables(v::Union{FilterView,SaveView}) = (ts = page_tables(editor(v)); [k for k in eachindex(ts) if ts[k].last < v.first])
source_tables(v::ChartView) = (ts = page_tables(editor(v)); [k for k in eachindex(ts) if !(v.first <= ts[k].first <= v.last)])

"True for the name of a file that the block `v` can read. A chart draws a CSV or TSV file. The others read JSON too."
source_files(::ChartView) = istable
source_files(_) = isfilterable

"The tables that the chart `c` of the page of `e` draws, when it draws more than one, or none"
several_sources(e, c::Charts.Chart) = begin
  names = chart_sources(c)
  length(names) > 1 && chart_path(e, c) === nothing && named_table(e, page_tables(e), c.from) === nothing ? names : String[]
end
several_sources(v) = v isa ChartView ? several_sources(editor(v), v.spec) : String[]

"What the button of `v` says: where its rows come from"
source_words(v) = begin
  from = source_from(v)
  isempty(from) && return v isa FilterView && v.lang == LOAD ? "Choose rows" : "The table above"
  n = length(several_sources(v))
  n > 1 && return "$n tables"
  Saves.isurl(from) ? Saves.host(from) : source_files(v)(from) ? basename(from) : from
end

"The button of the block `v` that says where its rows come from"
source_button(v) = block_part!(() -> SourceButton(of=v), v, :source)

describe(b::SourceButton) = begin
  v = b.of
  from = source_from(v)
  c = get(v.parts, :sources, nothing)
  open = c !== nothing && c.asking !== nothing
  icon = Saves.isurl(from) ? "cloud" : !isempty(from) && source_files(v)(from) ? "file-earmark" : "table"
  Row(height(26px), padding(9px, 0px), child_gap=6px, radius(6px), Alignment.Center, name="Source",
      border(1px, :solid, open ? colours.accent : colours.line), background(ishovered(b) ? colours.hover : colours.bg),
    Icon(icon, size=13px, color=colours.dim), Box(label(source_words(v), 12px, weight="Semibold")), Icon("chevron-down", size=9px, color=colours.dim))
end

cursor(::SourceButton) = :hand
onkey(b::SourceButton, ev::KeyPress{Keys.mouse_left}) = open_sources!(b, ev.window)

"""
The rows of the list of where the rows of `v` can come from: the table nearest
above, each table of the page that `v` can read, the file or the server that
it reads now, and a row that chooses a file. A load block's rows come from a
file or a server, so it has no row for the table above.
"""
source_rows(v) = begin
  e = editor(v)
  ts = page_tables(e)
  from = source_from(v)
  rows = Any[]
  v isa FilterView && v.lang == LOAD || push!(rows, (key="", name="The table above", short="", words=["the table above", "nearest"]))
  for k in source_tables(v)
    name, kind = table_name(e, ts, k), table_kind(e, ts[k])
    push!(rows, (key=name, name=name, short=kind, words=[name, kind]))
  end
  several = several_sources(v)
  for name in several   # a chart that draws several tables can draw files too
    istable(name) && !any(r -> r.key isa String && Charts.same(r.key, name), rows) &&
      push!(rows, (key=name, name=basename(name), short="file", words=[name]))
  end
  isempty(from) || !isempty(several) || any(r -> r.key == from, rows) || named_table(e, ts, from) !== nothing ||
    push!(rows, (key=from, name=source_words(v), short=Saves.isurl(from) ? "server" : "file", words=[from]))
  push!(rows, (key=:file, name="Choose a file…", short="", words=["choose a file", "file"]))
  rows
end

"The list of where the rows of the block `v` can come from, kept with the block"
source_chooser(v) = block_part!(() -> SourceChooser(of=v), v, :sources)

"The field at the top of the list of where rows can come from, that searches it. A chart's says how to draw several tables."
choice_input(c::SourceChooser) = block_part!(c, :filter) do
  TextInput(placeholder=c.of isa ChartView ? "Filter, or ⌘-click to add a table" : "Filter…", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"True when the row `r` of the list is where the block's rows come from now, or one of the tables that a chart draws"
chosen(c::SourceChooser, r) = r.key isa String && (r.key == source_from(c.of) || any(n -> Charts.same(n, r.key), several_sources(c.of)))

"""
Add the table of row `k` of the list to the tables that the chart of `c`
draws, or take it away when the chart draws it already. A chart that drew
the table above names that table, so it goes on drawing it too. The list
stays open, for the next table. A row that isn't a table is taken as a click
takes it.
"""
toggle_source!(c::SourceChooser, k::Int) = begin
  v = c.of
  (c.asking !== nothing && k in eachindex(c.rows)) || return stop_choosing!(c)
  key = c.rows[k].key
  (v isa ChartView && key isa String && !isempty(key)) || return choose!(c, k)
  e = editor(v)
  names = several_sources(v)
  if isempty(names)
    from = source_from(v)
    ts = page_tables(e)
    above = something(findlast(t -> t.last < v.first, ts), findfirst(t -> t.first > v.last, ts), 0)
    names = !isempty(from) ? [from] : above == 0 ? String[] : [table_name(e, ts, above)]
  end
  at = findfirst(n -> Charts.same(n, key), names)
  at === nothing ? push!(names, key) : deleteat!(names, at)
  set_source!(v, join(names, ", "))
  handled
end

"Show the list of where the rows of the block of `b` can come from, under `b`, with the keyboard in its field"
open_sources!(b::SourceButton, window) = begin
  v = b.of
  c = source_chooser(v)
  stop_choosing!(c)
  input = choice_input(c)
  input.color = colours.ink
  input.text = ""
  input.anchor = input.cursor = 0
  c.asking, c.typed = :source, ""
  c.rows = source_rows(v)
  c.pick = something(findfirst(r -> chosen(c, r), c.rows), 1)
  focus(input)
  menu = ChoiceMenu(of=c, button=b)
  c.parts[:menu] = menu
  popup!(window, menu, anchor=b, placement=:bottom, gap=9px, width=260px, key=SOURCE_MENU,
         onclose=() -> stop_choosing!(c), theme=component_theme(editor(v).zoom))
  handled
end

"Take the list away. The keyboard goes back to the page."
stop_choosing!(c::SourceChooser) = begin
  c.asking === nothing && return handled
  c.asking = nothing
  c.rows = Any[]
  w = window_of(c)
  w === nothing && return handled
  close_popup!(w, SOURCE_MENU)
  w.focus === choice_input(c) && focus(editor(c))
  handled
end

"""
What happens in each frame to the list: it closes when a click somewhere else
took the keyboard from its field, and it keeps the rows that have the words in
the field. New words pick the row whose name starts with them, or the first.
"""
choosing_tick!(c::SourceChooser) = begin
  c.asking === nothing && return
  w = window_of(c)
  (w === nothing || w.focus !== choice_input(c)) && return stop_choosing!(c)
  typed = String(strip(choice_input(c).text))
  typed == c.typed && return
  c.typed = typed
  c.rows = filter!(r -> choice_matches(r, typed), source_rows(c.of))
  c.pick = something(findfirst(r -> startswith(lowercase(r.name), lowercase(typed)), c.rows), 1)
end

"The list of the block `v`, in each frame"
sources_tick!(v) = (c = get(v.parts, :sources, nothing); c === nothing || choosing_tick!(c); v)

"Take row `k` of the list: its table is where the block's rows come from, or its file picker opens"
choose!(c::SourceChooser, k::Int) = begin
  (c.asking !== nothing && k in eachindex(c.rows)) || return stop_choosing!(c)
  key = c.rows[k].key
  stop_choosing!(c)
  v = c.of
  key == :file ? pick_file!(v) : key == source_from(v) ? close_picker!(v) : set_source!(v, key)
  handled
end

"""
`lines` with `from` as their `from` line, in place of the one there or first.
An empty `from` takes the line away. An `at` line says where the list is in a
JSON file, so it goes when `from` is neither a JSON file nor a web address.
"""
with_from(lines, from) = begin
  out = String.(lines)
  k = findfirst(l -> occursin(r"^\s*from\s*:"i, l), out)
  if isempty(from)
    k === nothing || deleteat!(out, k)
  else
    k === nothing ? pushfirst!(out, "from: $from") : (out[k] = "from: $from")
  end
  lowercase(splitext(from)[2]) in JSONS || Saves.isurl(from) || filter!(l -> !occursin(r"^\s*at\s*:"i, l), out)
  out
end

"Make `from` where the rows of the block `v` come from, and close its file picker"
set_source!(v, from) = (close_picker!(v); write_block!(v, source_lang(v), with_from(v.lines, from)))

# The file picker of each kind of block: a filter's and a load block's is `load_picker`
pick_file!(v::FilterView) = (v.choosing = false; toggle_picker!(v))
close_picker!(v::FilterView) = (v.choosing = false; v)
close_picker!(v::Union{SaveView,ChartView}) = (v.sourcing = false; v)

"The folder that the file picker of `v` starts in: the folder of its file, or the page's folder"
source_folder(v) = begin
  e = editor(v)
  from = source_from(v)
  path = isempty(from) || Saves.isurl(from) ? "" : abspath(docdir(e), expanduser(from))
  isfile(path) ? dirname(path) : isdir(docdir(e)) ? docdir(e) : homedir()
end

"The breadcrumb that picks the file that a save block or a chart reads"
from_picker(v::Union{SaveView,ChartView}) = block_part!(() -> Breadcrumb(at=source_folder(v), open=true, files=source_files(v)), v, :from_picker)

"Open the file picker of a save block or a chart, in the folder of its file or the page's"
pick_file!(v::Union{SaveView,ChartView}) = begin
  v.sourcing = true
  p = from_picker(v)
  p.at, p.open = source_folder(v), true
  v
end

"What a save block or a chart shows while it picks the file that it reads: what to do, a Close button, and the breadcrumb"
from_picker_section(v::Union{SaveView,ChartView}) = begin
  p = from_picker(v)
  p.room = editor(v).width - 24px
  words = v isa ChartView ? "Choose a CSV or TSV file to draw." : "Choose a CSV, TSV or JSON file to save the rows of."
  (Column(width(grow=grow), Alignment.Start, padding(10px, 12px, 10px, 12px), child_gap=8px, name="Picker",
     Row(width(grow=grow), Alignment.Center, child_gap=8px,
       Box(width(grow=grow), Text(words, size=12px, family=SANS, color=colours.dim, wrap=WrapMode.words)),
       block_button!(v, :close_picker, :close_picker, icon="x-lg", words="Close", tip="Close the list of files")),
     p),)
end

"When a file has been clicked in the file picker of `v`, it's where the rows of `v` come from, as a path from the page's folder"
from_pick_tick!(v::Union{SaveView,ChartView}) = begin
  v.sourcing || return v
  p = from_picker(v)
  isfile(p.at) && source_files(v)(p.at) || return v
  path = p.at
  # The next time the picker opens, it starts in a folder, not on this file
  p.at = dirname(path)
  set_source!(v, tilde(named(editor(v), path)))
end

# --- a map of a place ---------------------------------------------------------------------------
#
# A code block in the language `map` shows the map round a place, with a pin
# on the place and the address under it. map.jl says how the block is
# written. A program of its own asks the Mac's maps for two things: where the
# place is, and the picture of the map. The window never waits for that
# program. Until the picture is there, the block shows a grey box. What comes
# back is kept on the Mac, so a page shows its map at once the next time,
# with no network.
#
#   - The − and the + on the map show more and less of what's round the
#     place. The block keeps that as a line like `zoom: 15`.
#   - A drag moves the map. When the mouse lets go, the block keeps the
#     middle of what shows as a line like `centre: -33.86120, 151.21010`.
#     A third button beside the − takes that line away, so the place is in
#     the middle again.
#   - A click moves the place: the pin goes where the click was, and the
#     block's place becomes that point's latitude and longitude.
#   - Open in Maps opens the Mac's Maps app at the place.
#   - The button beside the map's top right corner makes it fill the window,
#     as a picture does, and so does Return with the caret on the map.
#
# The picture has no pin in it. Ladder draws the pin over the picture, on the
# point where the place is. So a click moves the pin in the same frame, and
# the picture stays the one that it was: it depends on the middle, the zoom,
# the size and dark or light, and not on the place. The address under the map
# comes later, when the program has it.
#
# Every picture is drawn where its own middle is on the map that shows now.
# So after a drag or a change of zoom, the picture that showed stays in its
# place until the right one is there, and the map never jumps.
#
# A window that isn't on the screen, like one a test makes, never runs the
# program and never opens the Maps app. A test puts functions of its own in
# `Maps.HELPER`, `Maps.FINDER` and `Maps.OPENER` to see what the block does
# with them.

@use "github.com/jkroso/UI.jl/Interface/image" register_image

const MAP = Maps.MAP
# Seconds that a map keeps one width before Ladder asks for a picture that wide, and that a pin
# keeps its place before Ladder makes the picture that fills the window
const MAP_PAUSE = 0.3
const MAP_ROUND = 7.0   # the radius of the map's top corners, which are just inside the round corners of its block
const MAP_SLACK = 4.0   # px that the mouse can move between a press and a release that are still a click
push!(BLOCK_ICONS, "geo-alt", "plus-lg", "dash-lg", "box-arrow-up-right", "crosshair")

"What a `map` block shows: a picture of the map round a place, a pin on the place, and the address under it"
@def mutable struct MapView <: SemanticUI
  n::Int = 0                               # its place among the page's maps
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Maps.Site = Maps.Site()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  asked::Any = nothing                     # how wide the map is, and when it got that width
  # What's known of a place: the place, what `Maps.found!` last said of it, and the latitude, the longitude and the address that Apple has for it
  place::Any = nothing
  got::Any = nothing                       # what `Maps.picture!` last said of the picture that the map needs now, and whether the program can run
  # The last picture that was there: its file, its zoom, the latitude and the longitude in its middle, and how wide it is.
  # It shows until the next one is there.
  shown::Any = nothing
  # While the mouse button is down on the map: where it went down, the middle of the map then, and whether the mouse has dragged the map
  grab::Any = nothing
  at::Any = nothing                        # the latitude and the longitude in the middle of the map while a drag moves it
  pinned::Any = nothing                    # the picture and the point that the picture with a pin in it was last made from
  due::Any = nothing                       # the picture and the point that it's to be made from next, and since when
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the picture was last drawn in the window
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its buttons and its picture, kept between frames
end

"The part of a map that shows the picture"
@def mutable struct MapArea <: SemanticUI
  of::Any = nothing
end

reread!(v::MapView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Maps.site(lines)
  v
end

"True in a window that's on the screen. A window that a test makes isn't."
on_screen(node) = (w = window_of(node); w !== nothing && !isempty(w.glfw))

"True when `file` holds a picture that Ladder can draw"
whole_picture(file) = try image_aspect(file) > 0 catch; false end

"The place of the block, as two blocks that name one place have it"
map_place(v::MapView) = lowercase(Maps.query(v.data.place))

"How wide the picture of the map is, in px: as wide as the page's text"
map_wide(v::MapView) = round(Int, num(editor(v).width))

"The zoom that the map's picture is made at: the block's, or a higher one on a page that's too wide for it"
map_zoom(v::MapView) = (a = map_around(v); Maps.fit(a === nothing ? v.data.zoom : a.zoom, map_wide(v), Maps.TALL))

"What Apple has for the block's place, or nothing while that isn't known"
map_facts(v::MapView) = (p = v.place; p !== nothing && p.key == map_place(v) ? p.facts : nothing)

"""
Where the pin is: the latitude and the longitude of the block's place. For an
address, that's what Apple has for it. It's nothing until that's known.
"""
map_pin(v::MapView) = begin
  at = Maps.coordinates(v.data.place)
  at !== nothing && return at
  found = map_facts(v)
  found === nothing ? nothing : (found.lat, found.lon)
end

"""
The latitude and the longitude in the middle of the map: where a drag has it
now, what the block's `centre` line says, or the place. It has the five
decimal places that a block keeps, as the middle of a picture has. It's
nothing while the place of an address isn't known.
"""
map_middle(v::MapView) = begin
  v.at === nothing || return v.at
  # A map with no place of its own has the places from the rest of its page round its middle
  a = map_around(v)
  middle = something(v.data.centre, map_pin(v), a === nothing ? nothing : a.centre, Some(nothing))
  middle === nothing ? nothing : Maps.rounded(middle)
end

"""
Where the picture that the map has is on a map `w` px by `h` px that shows
what the block says now: its left, its top, its width and its height, in px
from that map's top left corner. It's nothing when the map has no picture,
or the middle of the map isn't known.
"""
map_spot(v::MapView, w, h) = begin
  shown, middle = v.shown, map_middle(v)
  (shown === nothing || middle === nothing) && return nothing
  zoom = map_zoom(v)
  # A picture that was made at another zoom is drawn as big as the map of this zoom is
  k = 2.0^(zoom - shown.zoom)
  wide, tall = shown.wide * k, Maps.TALL * k
  cx, cy = Maps.point(shown.centre, middle, zoom, w, h)
  (cx - wide / 2, cy - tall / 2, wide, tall)
end

"True when the map has a picture to draw: some of the picture that it has is in the map that shows now"
map_shows(v::MapView) = begin
  w, h = map_wide(v), Maps.TALL
  r = map_spot(v, w, h)
  r !== nothing && r[1] < w && r[1] + r[3] > 0 && r[2] < h && r[2] + r[4] > 0
end

"True when the page can be changed: a page that's read-only takes no drag and no click"
map_changes(v::MapView) = (b = editor(v).buf; !readonly(b) && !b.fixed)

"True when a drag can move the map and a click can move its place: the page can be changed, and the map shows a picture"
map_moves(v::MapView) = map_changes(v) && map_shows(v) && !isempty(v.data.place)

"""
What Apple has for the block's place. The program that finds a place is
started here, when the place isn't kept. A latitude and a longitude need no
finding, and are asked for only to learn their address. What comes back is
read once.
"""
map_find!(v::MapView, runs) = begin
  key = map_place(v)
  p = v.place
  p !== nothing && p.key == key && p.facts !== nothing && return p
  # A map with no place of its own has nothing to find
  isempty(v.data.place) && return v.place = (key=key, found=(state=:none, file="", problem="", wait=Inf), facts=nothing)
  ask(start) = Maps.found!(media_dir(), v.data.place; start)
  found = ask(runs)
  facts = found.state == :there ? Maps.facts(found.file) : nothing
  # A file that holds something else is taken away, and made again later
  found.state == :there && facts === nothing && (Maps.spoiled!(found.file); found = ask(false))
  v.place = (key=key, found=found, facts=facts)
end

"""
The picture that the map needs now: as wide as the page's text, at the block's
zoom, with the middle of the map in its middle, dark on a dark page.
`Maps.picture!` says what it gives. The program that makes the picture is
started here, when the picture isn't kept. While the window changes size, the
map has another width in each frame, so the program is only started once the
width has stayed for a moment. While the place of an address isn't known, the
map has no middle, and no picture is asked for.
"""
map_picture!(v::MapView) = begin
  s = v.data
  wide, dark, zoom = map_wide(v), dark_page(), map_zoom(v)
  (v.asked === nothing || v.asked[1] != wide) && (v.asked = (wide, v.asked === nothing ? 0.0 : time()))
  rest = MAP_PAUSE - (time() - v.asked[2])
  runs = on_screen(v) || Maps.HELPER[] !== Maps.run_program
  place = map_find!(v, runs)
  map_others(v, runs)   # the places from the rest of the page are asked for too
  around = map_around(v)
  # The picture is of what the block says, and not of where a drag has the map now: the block changes when the mouse lets go
  middle = something(s.centre, map_pin(v), around === nothing ? nothing : around.centre, Some(nothing))
  p = nothing
  if middle !== nothing
    middle = Maps.rounded(middle)
    ask(start) = Maps.picture!(media_dir(), middle, zoom, wide, Maps.TALL, dark; start)
    p = ask(runs && rest <= 0)
    # A file that was cut short is no picture. It's taken away, and made again later.
    p.state == :there && !whole_picture(p.file) && (Maps.spoiled!(p.file); p = ask(false))
    p.state == :there && (v.shown = (file=p.file, zoom=zoom, centre=middle, wide=wide))
  end
  v.shown === nothing || isfile(v.shown.file) || (v.shown = nothing)
  # The window looks again when a program may have finished, when the width has stayed, or when it's time to try again
  wait = min(place.found.wait, p === nothing ? Inf : p.wait, runs && rest > 0 ? rest : Inf)
  isfinite(wait) && redraw_in!(v, max(wait, 0.05))
  v.got = (p, runs)
end

"What a map says in place of a picture that isn't there, or \"\" when it has a picture to show"
map_words(v::MapView) = begin
  map_shows(v) && return ""
  p, runs = v.got
  # Without a middle, the map waits for the place. With one, it waits for the picture.
  waits = p === nothing ? v.place.found : p
  waits.state == :lost ? waits.problem : waits.state == :failed ? waits.problem * (runs ? " It tries again in a minute." : "") :
  waits.state == :none && !runs ? Maps.FAILED : "Finding the place…"
end

"""
The words under a map: the address that Apple has for the place, or the place
as the block has it until that's known. An address that Apple's maps don't
have says so here, when the map shows a picture all the same.
"""
map_address(v::MapView) = begin
  found = map_facts(v)
  found === nothing || isempty(found.address) || return found.address
  lost = v.place !== nothing && v.place.key == map_place(v) && v.place.found.state == :lost
  lost && map_shows(v) ? v.data.place * ". " * v.place.found.problem : v.data.place
end

"""
The point of the picture that the map has where the pin is, in px from the
picture's top left corner. It's nothing when the place isn't known, or isn't
in that picture.
"""
map_pin_in(v::MapView) = begin
  shown, pin = v.shown, map_pin(v)
  (shown === nothing || pin === nothing) && return nothing
  at = Maps.point(pin, shown.centre, shown.zoom, shown.wide, Maps.TALL)
  0 <= at[1] <= shown.wide && 0 <= at[2] <= Maps.TALL ? at : nothing
end

"""
The key, for an Image, of the picture that fills the window: the map's
picture with the pin drawn in it, since what fills the window is a picture
and no more. A map whose place isn't in its picture fills the window as it
is.

That picture takes some hundredths of a second to make. So it's made a
moment after the picture or the pin last changed, and not in the frame of
the click that moved the pin. Until the first one is made, the map fills the
window without its pin.
"""
map_full!(v::MapView) = begin
  shown, at = v.shown, map_pin_in(v)
  at === nothing && return shown.file
  key = "the map with its pin $(objectid(v))"
  want = (shown.file, at)
  if v.pinned != want
    (v.due === nothing || v.due[1] != want) && (v.due = (want, time()))
    if v.grab === nothing && time() - v.due[2] >= MAP_PAUSE
      was = has_image(key) ? image_source(key) : nothing
      register_image(key, pinned_png(shown.file, at))
      was === nothing || Skia.sk_image_unref(was.raw)   # the picture that the key had isn't needed
      v.pinned, v.due = want, nothing
    else
      redraw_in!(v, MAP_PAUSE)
    end
  end
  has_image(key) ? key : shown.file
end

describe(v::MapView) = begin
  e = editor(v)
  s = v.data
  with_theme(component_theme(e.zoom)) do
    isempty(s.place) && isempty(page_places(e)) && return Column(block_look()..., clip=true, name="Map",
      block_note("Write an address in this block, or a latitude and a longitude, to see the map of that place. A map with no address shows the addresses of the page's contacts."))
    map_picture!(v)
    others = map_others(v)
    area = block_part!(() -> MapArea(of=v), v, :area)
    least, most = first(Maps.ZOOMS), last(Maps.ZOOMS)
    # On a page that's too wide for the lowest zooms, the − stops at the lowest zoom that a picture is made at
    lowest = s.zoom <= least || Maps.fit(s.zoom - 1, map_wide(v), Maps.TALL) == map_zoom(v)
    buttons = Row(radius(7px), padding(2px), child_gap=1px, background(colours.float), border(1px, :solid, colours.line),
      (s.centre === nothing ? () : (block_button!(v, :home, :home, icon="crosshair", tip="Put the place back in the middle of the map"),))...,
      block_button!(v, :out, (:zoom, -1), icon="dash-lg", tip="Show more of what's round the place", off=lowest),
      block_button!(v, :in, (:zoom, 1), icon="plus-lg", tip="Show the place closer", off=s.zoom >= most))
    # A map with no place of its own is as close as shows every place from the page, and says how many those are
    own = !isempty(s.place)
    under = own ? map_address(v) : isempty(others) ? "Finding the places of this page…" :
            length(others) == 1 ? "1 place from this page: " * others[1].name : "$(length(others)) places from this page: " * join((o.name for o in others), ", ")
    Column(block_look()..., clip=true, name="Map",
      Stack(width(grow=grow), height(px(Maps.TALL)), Alignment.Start,
        map_shows(v) ? fillable(v, (:picture, map_full!(v)), area, wide=:grow) : area,
        (own ? (Row(width(grow=grow), padding(8px), Alignment.Start, justify=Alignment.End, buttons),) : ())...),
      Row(width(grow=grow), padding(own ? 5px : 9px, 6px, own ? 5px : 9px, 12px), child_gap=8px, Alignment.Center,
        Box(Icon("geo-alt", size=14px, color=colours.dim)),
        Box(width(grow=grow), Alignment.Start, clip_x=true, Text(under, size=12.5px, family=SANS, color=colours.dim, wrap=WrapMode.words)),
        (own ? (block_button!(v, :open, :open, words="Open in Maps", icon="box-arrow-up-right", tip="Open the Maps app at this place"),) : ())...))
  end
end

describe(a::MapArea) = begin
  words = map_words(a.of)
  # Only its top corners are round, as the corners of its block are
  Box(width(grow=grow), height(px(Maps.TALL)), Alignment.Center, justify=Alignment.Center, padding(60px, 0px),
      radius(px(MAP_ROUND), px(MAP_ROUND), 0px, 0px), background(colours.block),
      (isempty(words) ? () : (Box(Text(words, size=13px, family=SANS, color=colours.dim, wrap=WrapMode.words)),))...)
end

"The places along the bend from `a` to `d` that `b` and `c` pull towards them, without `a`"
pin_bend(a, b, c, d, steps=12) = [(1 - t)^3 .* a .+ 3t * (1 - t)^2 .* b .+ 3t^2 * (1 - t) .* c .+ t^3 .* d for t in (1:steps) ./ steps]

"""
Draw a pin whose point is at `(x, y)`: a red drop with a white dot in it, as
maps mark a place. It's drawn as a shape, so it's sharp however big the
canvas draws it, on the screen and on paper.
"""
pin_ink(ctx, x, y; fill=RGBA(0.92, 0.26, 0.21, 1.0), line=RGBA(0.70, 0.16, 0.13, 1.0)) = begin
  r, cy = 11.0, y - 26.0   # the radius of the pin's round head, and how high its middle is
  shape = [(x, y); pin_bend((x, y), (x - 2, y - 9), (x - r, cy + 9), (x - r, cy));
           [(x - r * cos(a), cy - r * sin(a)) for a in (1:23) .* (π / 24)];
           (x + r, cy); pin_bend((x + r, cy), (x + r, cy + 9), (x + 2, y - 9), (x, y))]
  # A soft shadow on the ground under the point
  shadow = ink(RGBA(0.0, 0.0, 0.0, 0.25))
  ground = Ref(Skia.sk_rect_t(Float32(x - 5), Float32(y - 2), Float32(x + 5), Float32(y + 2)))
  Skia.sk_canvas_draw_oval(ctx, ground, shadow)
  Skia.sk_paint_delete(shadow)
  trace(ctx, shape, line, 1.0; fill, closed=true)
  disc(ctx, x, cy, 4, RGBA(1.0, 1.0, 1.0, 1.0))
end

"""
The picture in `file` with a pin drawn on the point `at` of it, in px from its
top left corner, as the bytes of a PNG file. The page of HTML and the map
that fills the window show that picture, since each shows a picture and no
more.
"""
pinned_png(file, at) = begin
  image = image_source(file)
  info = Ref(Skia.sk_image_info_t(C_NULL, Skia.SK_COLOR_TYPE_RGBA_8888, Skia.SK_ALPHA_TYPE_OPAQUE, image.width, image.height))
  GC.@preserve info begin
    surface = Skia.sk_surface_make_raster_n32_premul(pointer_from_objref(info), C_NULL)
    surface == C_NULL && return read(file)
    canvas = Skia.sk_surface_get_canvas(surface)
    paint_picture(canvas, image.raw, (0, 0, image.width, image.height), (0, 0, image.width, image.height))
    # The pin is as big on the picture as it is on the page, where the picture has `Maps.SCALE` pixels to the px
    Skia.sk_canvas_scale(canvas, Float32(Maps.SCALE), Float32(Maps.SCALE))
    pin_ink(canvas, at[1], at[2])
    drawn = Skia.sk_surface_make_image_snapshot(surface)
    encoded = Skia.sk_encode_png(C_NULL, drawn, Int32(6))
    bytes = copy(unsafe_wrap(Array, Ptr{UInt8}(Skia.sk_data_get_data(encoded)), Skia.sk_data_get_size(encoded)))
    Skia.sk_data_unref(encoded)
    Skia.sk_image_unref(drawn)
    Skia.sk_surface_unref(surface)
    bytes
  end
end

# The picture is drawn at its own size, with its middle where that latitude and longitude is on the map that
# shows now. So a picture that was made for another width, or for another middle, shows the same streets in
# the same places until the right one is there, and the part with no picture yet is grey. The pin is drawn
# over it, on the place. A place that isn't in the map that shows has no pin, and nothing is drawn outside
# the map's box.
draw(ctx, size, ui::ConcreteRect, a::MapArea) = begin
  v = a.of
  x, y, w, h = v.box = (num(ui.left), num(ui.top), num(ui.width), num(ui.height))
  r = map_spot(v, w, h)
  (r !== nothing && map_shows(v) && whole_picture(v.shown.file)) || return
  # Only the top corners are round: the box that's cut out goes on under the map's foot
  with_clip(ctx, ui.left, ui.top, ui.width, ui.height) do
    with_round_clip(ctx, ui.left, ui.top, ui.width, ui.height + px(2MAP_ROUND), px(MAP_ROUND)) do
      image = image_source(v.shown.file)
      paint_picture(ctx, image.raw, (0, 0, image.width, image.height), (x + r[1], y + r[2], r[3], r[4]))
      # The places from the rest of the page have pins of another colour, under the map's own. The one that the
      # mouse is on, here or on its contact's card, has a ring round its head.
      hot = other_at(v)
      for o in map_others(v)
        at = other_point(v, o)
        at === nothing && continue
        (o === hot || marked(v, o.name)) && disc(ctx, x + at[1], y + at[2] - 26, 15.5, tint(OTHER_PIN[1], 0.35))
        pin_ink(ctx, x + at[1], y + at[2], fill=OTHER_PIN[1], line=OTHER_PIN[2])
      end
      pin = map_pin(v)
      pin === nothing && return
      at = Maps.point(pin, map_middle(v), map_zoom(v), w, h)
      0 <= at[1] <= w && 0 <= at[2] <= h && pin_ink(ctx, x + at[1], y + at[2])
    end
  end
end

cursor(::MapView) = :arrow
# UI.jl has no open hand, so a map that a drag can move has the hand that points
cursor(a::MapArea) = map_moves(a.of) || other_at(a.of) !== nothing ? :hand : :arrow
onpinch(v::MapView, ev::Pinch) = pinch_open(v, ev)

# A press on the map starts a drag that moves the map, or a click that moves the place. The press is the
# map's own, so the page's text takes no caret and no selection from it. With ⌥ held, the press shows the
# block's lines, as it does on any block. A page that can't be changed takes no drag and no click.
onkey(a::MapArea, ev::KeyPress{Keys.mouse_left}) = begin
  v = a.of
  # A click on the pin of a place from the rest of the page goes to the place's line
  o = only_held(v, Keys.opt) ? nothing : other_at(v)
  o === nothing || (hide_tooltip!(ev.window); return show_line!(editor(v), o.line))
  (only_held(v, Keys.opt) || !map_moves(v)) && return nothing
  w = ev.window
  focus(editor(v))
  v.grab = (from=(num(w.mouse[1]), num(w.mouse[2])), middle=map_middle(v), dragged=false)
  handled
end

# While the button is down, the mouse is the map's wherever it goes, so the page doesn't select text behind it
onmouse(a::MapArea, ev::MouseMove) = begin
  v = a.of
  g = v.grab
  if g === nothing
    # The mouse on the pin of a place from the rest of the page says whose place it is
    o = other_at(v)
    o === nothing && return nothing
    at = other_point(v, o)
    show_tooltip!(ev.window, tip_label(o.name * "  ·  " * o.place), px(v.box[1] + at[1] - 11), px(v.box[2] + at[2] - 37), 22px, 37px, placement=:top, gap=4px)
    return nothing
  end
  Keys.mouse_left in ev.window.keys || (map_drop!(v); return handled)
  dx, dy = num(ev.position[1]) - g.from[1], num(ev.position[2]) - g.from[2]
  (g.dragged || hypot(dx, dy) >= MAP_SLACK) || return handled
  g.dragged || (v.grab = merge(g, (dragged=true,)))
  zoom = map_zoom(v)
  v.at = Maps.held(Maps.moved(g.middle, dx, dy, zoom), zoom, Maps.TALL)
  handled
end

onkey(a::MapArea, ::KeyRelease{Keys.mouse_left}) = a.of.grab === nothing ? nothing : (map_drop!(a.of); handled)
# The button can come up while the mouse is off the map, where the map doesn't hear of it
block_tick!(v::MapView) = (v.grab !== nothing && !held(v, Keys.mouse_left) && map_drop!(v); v)

"""
The mouse button came up. After a drag, the middle of what shows is written
as the block's `centre` line. After a click, the block's place becomes the
latitude and the longitude of the point that was clicked, and the middle that
showed is written too, so the map stays where it is, with the picture that it
had, and only the pin moves. ⌘Z takes either back.
"""
map_drop!(v::MapView) = begin
  g, v.grab = v.grab, nothing
  at, v.at = v.at, nothing
  (g === nothing || !map_changes(v)) && return v
  s = v.data
  if g.dragged
    at === nothing && return v
    s.centre = Maps.rounded(at)
  else
    clicked = Maps.latlon((g.from[1] - v.box[1], g.from[2] - v.box[2]), g.middle, map_zoom(v), v.box[3], v.box[4])
    s.centre === nothing && (s.centre = g.middle)
    s.place = Maps.text(clicked)
  end
  write_block!(v, MAP, Maps.written(s))
  v
end

act!(v::MapView, action, w) = begin
  if action == :open
    # Only a window that's on the screen opens another app
    (on_screen(v) || Maps.OPENER[] !== Maps.open_app) && Maps.open_place(v.data.place)
  elseif action == :home
    v.data.centre = nothing
    write_block!(v, MAP, Maps.written(v.data))
  elseif action isa Tuple && action[1] == :zoom
    Maps.zoom!(v.data, action[2]) && write_block!(v, MAP, Maps.written(v.data))
  end
  handled
end

"""
The map as HTML: its picture with the pin drawn in it, when a picture is
kept, and the address under it as a link to Apple Maps. The picture is in the
page itself, so the page needs no other file. A page of HTML is light, so it
gets the light map when that one is kept. Nothing is asked of Apple's maps
for it.
"""
map_html(e, v::MapView) = begin
  s = v.data
  isempty(s.place) && return nothing
  found = Maps.found!(media_dir(), s.place, start=false)
  facts = found.state == :there ? Maps.facts(found.file) : nothing
  pin = something(Maps.coordinates(s.place), facts === nothing ? nothing : (facts.lat, facts.lon), Some(nothing))
  middle = something(s.centre, pin, Some(nothing))
  wide, zoom = map_wide(v), map_zoom(v)
  # The picture that the block asks for, light or else dark, or else the picture that the map shows now
  picture = nothing
  if middle !== nothing
    middle = Maps.rounded(middle)
    kept = [Maps.picture!(media_dir(), middle, zoom, wide, Maps.TALL, dark, start=false) for dark in (false, true)]
    k = findfirst(p -> p.state == :there, kept)
    k === nothing || (picture = (file=kept[k].file, zoom=zoom, centre=middle, wide=wide))
  end
  picture === nothing && v.shown !== nothing && isfile(v.shown.file) && map_shows(v) && (picture = v.shown)
  address = escape(facts === nothing || isempty(facts.address) ? s.place : facts.address)
  shows = ""
  if picture !== nothing && whole_picture(picture.file)
    at = pin === nothing ? nothing : Maps.point(pin, picture.centre, picture.zoom, picture.wide, Maps.TALL)
    inside = at !== nothing && 0 <= at[1] <= picture.wide && 0 <= at[2] <= Maps.TALL
    bytes = inside ? pinned_png(picture.file, at) : read(picture.file)
    shows = "<img src=\"$(Maps.data_uri(bytes))\" alt=\"A map of $address\" width=\"$(picture.wide)\">\n"
  end
  "<div class=\"diagram\">\n$shows<p><a href=\"$(escape(Maps.link(s.place)))\">$address</a></p>\n</div>"
end

BLOCKS[MAP] = BlockKind("Map", "geo-alt", MapView, map_html)

# --- a question with answers to choose ---------------------------------------------------------
#
# A code block in the language `ask` shows a question, the answers to choose
# from, and a field to type in. ask.jl says how the block is written. A click
# on an answer chooses it, and what you type in the field goes under the
# answers. Both are written into the block's lines. So an agent that waits for
# the page reads your answer in the lines that you changed. The block has no
# button that sends them: the bell in the top bar sends the page, and so does
# ⌘Return.

const ASK = Asks.ASK
push!(BLOCK_ICONS, "question-circle", "check")

"What an `ask` block shows: a question, its answers and a field to type in"
@def mutable struct AskView <: SemanticUI
  n::Int = 0                               # its place among the page's questions
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Asks.Question = Asks.Question()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its answers, its field and its button, kept between frames
end

"An answer of a question. A click chooses it."
@def mutable struct AskOption <: SemanticUI
  of::Any = nothing
  i::Int = 0
end

"The text field of a question"
ask_input(v::AskView) = block_part!(v, :input) do
  TextInput(placeholder="", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

reread!(v::AskView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Asks.question(lines)
  # The field shows what the block says was typed, as it does after ⌘Z takes some of it back
  i = ask_input(v)
  i.text == v.data.note || (i.text = v.data.note; i.anchor = i.cursor = length(i.text))
  v
end

"What happens to a question in each frame, before the page is laid out: what was typed in its field is written into its block"
block_tick!(v::AskView) = begin
  text = ask_input(v).text
  text == v.data.note && return v
  v.data.note = text
  write_block!(v, ASK, Asks.written(v.data), typing=true)
end

"""
A text beside a mark that is `tall`, such as an icon or a tick box. The text
starts lower than the mark, so the middle of its capitals is level with the
middle of the mark. A text that wraps keeps its first line there.
"""
beside_mark(tall, t::Text) = Box(width(grow=grow), padding(max(0px, (tall - skia_cap_height(t)) / 2), 0px, 0px, 0px), t)

describe(o::AskOption) = begin
  q = o.of.data
  o.i <= length(q.options) || return Box(height(0px))
  opt = q.options[o.i]
  # The tick is as big as its box. A smaller icon isn't put in the middle of the box.
  mark = opt.many ?
    (opt.chosen ? Box(fixed(16px), height(16px), radius(4px), background(colours.accent), Icon("check", size=16px, color=colours.bg)) :
                  Box(fixed(16px), height(16px), radius(4px), border(1.5px, :solid, colours.marker))) :
    Box(fixed(16px), height(16px), radius(8px), Alignment.Center, justify=Alignment.Center,
        border(1.5px, :solid, opt.chosen ? colours.accent : colours.marker),
        (opt.chosen ? (Box(fixed(8px), height(8px), radius(4px), background(colours.accent)),) : ())...)
  Row(width(grow=grow), padding(8px, 6px), radius(6px), child_gap=10px, Alignment.Start, name="Answer",
      background(opt.chosen ? colours.active : ishovered(o) ? colours.hover : clear),
    Box(mark),
    beside_mark(16px, Text(opt.text, size=13.5px, family=SANS, subfamily=opt.chosen ? "Medium" : "", color=colours.ink, wrap=WrapMode.words)))
end

cursor(::AskOption) = :hand
cursor(::AskView) = :arrow

onkey(o::AskOption, ::KeyPress{Keys.mouse_left}) = begin
  v = o.of
  o.i <= length(v.data.options) || return handled
  Asks.choose!(v.data, o.i)
  write_block!(v, ASK, Asks.written(v.data))
  handled
end

describe(v::AskView) = begin
  e = editor(v)
  q = v.data
  input = ask_input(v)
  input.color = colours.ink
  input.placeholder = isempty(q.options) ? "Type your answer" : "Add a note"
  w = window_of(v)
  typing = w !== nothing && w.focus === input
  with_theme(component_theme(e.zoom)) do
    Column(block_look()..., padding(16px, 14px), child_gap=10px, name="Question",
      Row(width(grow=grow), child_gap=10px, Alignment.Start,
        Box(padding(0px, 1px), Icon("question-circle", size=16px, color=Asks.answered(q) ? colours.string : colours.accent)),
        beside_mark(18px, Text(isempty(q.words) ? "A question with no words yet" : Asks.asked(q), size=15px, family=SANS,
                               subfamily="Semibold", color=isempty(q.words) ? colours.dim : colours.ink, wrap=WrapMode.words))),
      (isempty(q.options) ? () : (Column(width(grow=grow), Alignment.Start, child_gap=2px,
        [block_part!(() -> AskOption(of=v, i=i), v, (:option, i)) for i in eachindex(q.options)]...),))...,
      Box(width(grow=grow), height(30px), padding(9px, 0px), radius(6px), border(1px, :solid, typing ? colours.accent : colours.line),
          background(colours.bg), input))
  end
end

# Return in the field gives the keyboard back to the page
onkey(v::AskView, ev::KeyPress{Keys.enter}) = unmodified(ev) ? (focus(editor(v)); handled) : nothing

"The question as HTML: its words, and each answer with a mark on the ones that are chosen"
ask_html(e, v::AskView) = begin
  q = v.data
  rows = ["<li>$(o.chosen ? "☑" : "☐") $(o.chosen ? "<strong>$(escape(o.text))</strong>" : escape(o.text))</li>" for o in q.options]
  "<p><strong>$(escape(Asks.asked(q)))</strong></p>\n" * (isempty(rows) ? "" : "<ul style=\"list-style: none; padding-left: 0.5em\">\n" * join(rows, "\n") * "\n</ul>\n") *
  (isempty(strip(q.note)) ? "" : "<blockquote>$(escape(q.note))</blockquote>")
end

BLOCKS[ASK] = BlockKind("Question", "question-circle", AskView, ask_html)

# --- changes to accept or reject ----------------------------------------------------------------
#
# A code block in the language `changes` holds a diff, and shows each of its
# changes with the lines that go in red and the lines that come in green.
# changes.jl says how the block is written. Each change has an Accept and a
# Reject button. Your choice is written at the end of the change's @@ line,
# so an agent that waits for the page reads it in the lines that you changed.
#
# Accept makes the change in the file that the diff names. A click on
# Accepted, or on Reject, takes the change out of the file again. A change
# that Ladder can't make, because its file has other lines now, keeps the
# choice that it had, and a line under its row says why.
#
# The lines have the colours of code in the language of their file. Where a
# line that comes is a new version of a line that goes, the words that are
# different have a darker mark. A line that's too long goes on under itself.
# Two buttons at the top choose how the lines show: the new lines under the
# old, or the old lines at the left and the new at the right. That choice is a
# setting, so every block of changes shows the same way.
#
# A click on a line opens a field under it, for what you say about that line.
# Your words are written at the end of the block as you type them, so the
# agent reads them with your choices. Return closes the field, and Esc puts
# back what the comment said before. A comment shows under its line. A click
# on it opens it again, and empty words take it away.

const CHANGES = Diffs.CHANGES
const DIFF_ROW = 19.0        # px: how tall a line of a change is
const DIFF_SIZE = 12px       # how big the text of those lines is
const BESIDE_LEAST = 600.0   # px: the narrowest block that shows the old lines beside the new
const NOTE_ROW = 17.0        # px: how tall a line of a comment is
const NOTE_FIELD = 30.0      # px: how tall the field for a comment is
push!(BLOCK_ICONS, "file-diff", "check-lg", "x-lg", "view-stacked", "layout-split", "exclamation-triangle")

"What a `changes` block shows: each change of a diff, with buttons that accept it and reject it"
@def mutable struct ChangesView <: SemanticUI
  n::Int = 0                               # its place among the page's blocks of changes
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Diffs.Changes = Diffs.Changes(String[], Diffs.Hunk[])
  lines::Vector{String} = String[]         # the lines that `data` was read from
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its buttons and the lines of each change, kept between frames
  laid::Dict{Any,Any} = Dict{Any,Any}()    # the lines of each change as they're drawn, kept until the block is read again
  noting::Union{Nothing,Tuple{Int,Int}} = nothing   # the line that you're writing a comment on: its change, and which of the change's lines
  before::String = ""                      # what that comment said when its field opened, for Esc to put back
  failed::Dict{Int,String} = Dict{Int,String}()   # why Ladder couldn't make a change in its file, or take it out, by the change's number
end

"The lines of one change"
@def mutable struct HunkArea <: SemanticUI
  of::Any = nothing
  k::Int = 0
  over::Int = 0   # the line of the change that the mouse is on, or 0
end

"The field for what you say about a line"
note_input(v::ChangesView) = block_part!(v, :note) do
  TextInput(placeholder="Say something about this line", font_family=SANS, font_size=12.5px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

reread!(v::ChangesView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Diffs.changes(lines)
  empty!(v.laid)
  # What went wrong was about the changes that the block had
  v.failed = Dict{Int,String}()
  v.noting === nothing && return v
  k, j = v.noting
  # The line that the field is under can go, when an agent writes the block again
  (k <= length(v.data.hunks) && j <= length(v.data.hunks[k].rows)) || return (v.noting = nothing; v)
  # The field shows what the block says, as it does after ⌘Z takes some of it back
  i = note_input(v)
  said = get(v.data.notes, (k, j), "")
  i.text == said || (i.text = said; i.anchor = i.cursor = length(said))
  v
end

"What happens to a block of changes in each frame, before the page is laid out: what was typed in its field is written into its block"
block_tick!(v::ChangesView) = begin
  v.noting === nothing && return v
  w = window_of(v)
  # A click somewhere else closes the field
  w !== nothing && w.focus !== note_input(v) && return stop_noting!(v)
  text = note_input(v).text
  text == get(v.data.notes, v.noting, "") && return v
  Diffs.note!(v.data, v.noting..., text)
  write_block!(v, CHANGES, Diffs.written(v.data), typing=true)
end

"Open the field under line `j` of change `k`, with what you said about the line in it"
noting!(v::ChangesView, k, j) = begin
  stop_noting!(v)
  i = note_input(v)
  i.text = get(v.data.notes, (k, j), "")
  i.anchor = i.cursor = length(i.text)
  v.noting, v.before = (k, j), i.text
  empty!(v.laid)
  focus(i)
  v
end

"Close the field. What was typed stays as the comment, without the spaces at its ends. Without `keep`, the comment says what it said before."
stop_noting!(v::ChangesView; keep=true) = begin
  v.noting === nothing && return v
  k, j = v.noting
  i = note_input(v)
  text = keep ? String(strip(i.text)) : v.before
  v.noting = nothing
  empty!(v.laid)
  w = window_of(v)
  w !== nothing && w.focus === i && focus(editor(v))
  text == get(v.data.notes, (k, j), "") && return v
  Diffs.note!(v.data, k, j, text)
  write_block!(v, CHANGES, Diffs.written(v.data), typing=keep)
end

"A line of a change, ready to draw"
struct DiffText
  chars::Vector{Char}
  xs::Vector{Float64}                           # how far across each character starts, and where the last one ends
  parts::Vector{Tuple{UnitRange{Int},Symbol}}   # the characters that have a colour of their own, and which colour
  marks::Vector{UnitRange{Int}}                 # the characters that the other version of the line doesn't have
  indent::Float64                               # how far across its first word starts
end

"""
One line across a change: the row that shows at each side, or 0, and the
characters of that row on each line of text. Or what you said about row
`note`, which shows under that row: `said` has its words, line by line, and
it's empty while the field for them is open.
"""
struct DiffBand
  top::Float64
  tall::Float64
  rows::NTuple{2,Int}
  lines::NTuple{2,Vector{UnitRange{Int}}}
  note::Int
  said::Vector{String}
end

DiffBand(top, tall, rows, lines) = DiffBand(top, tall, rows, lines, 0, String[])

"The lines of a change as they're drawn at one width. With `beside`, the old lines are at the left and the new at the right."
struct DiffLayout
  beside::Bool
  texts::Vector{DiffText}
  bands::Vector{DiffBand}
  digits::Float64   # how wide a column of line numbers is, or 0 when the change has none
  gutter::Float64   # the room for the numbers at the left of a side
  room::Float64     # how wide the text of a side can be
  tall::Float64
end

"The face of a line of a change"
diff_face(colour=colours.ink) = Face(codefont(), codestyle(), DIFF_SIZE, colour, false)

"How far in a line of a row starts when it isn't the row's first: as far as the row's first word, so the code keeps its shape"
hang(t::DiffText, room) = min(t.indent, room / 2)

"The characters of each line of text that the row `t` takes when it has `room` px across. It breaks after a space where it can."
folded(t::DiffText, room) = begin
  n = length(t.chars)
  out = UnitRange{Int}[]
  s = 1
  while s <= n
    space = isempty(out) ? room : room - hang(t, room)
    stop = s   # the last character that fits. A line holds one character at least.
    while stop < n && t.xs[stop+2] - t.xs[s] <= space
      stop += 1
    end
    if stop < n
      k = stop
      while k > s && !isspace(t.chars[k])
        k -= 1
      end
      k > s && !all(isspace, view(t.chars, s:k)) && (stop = k)
    end
    push!(out, s:stop)
    s = stop + 1
  end
  isempty(out) ? [1:0] : out
end

"How wide the lines of a change are in the block of `v`: as wide as the page's text, less the line at each edge of the block. What holds `v` can say otherwise."
diff_wide(v::ChangesView) = diff_wide(getfield(v, :parent), v)
diff_wide(_, v::ChangesView) = num(editor(v).width) - 2

"The face of a comment"
note_face() = Face(SANS, "", 12.5px, colours.ink, false)

"The lines that `words` take in `face` when they have `room` px across"
wrapped(face::Face, words, room) = begin
  out = String[]
  line = ""
  for word in split(words)
    longer = isempty(line) ? String(word) : line * " " * word
    if isempty(line) || num(measure(face, longer)) <= room
      line = longer
    else
      push!(out, line)
      line = String(word)
    end
  end
  push!(out, line)
end

"""
Where the box of a comment is across lines `wide` px wide, and how wide it is.
`sign` is of the row that the comment is on. With the old lines beside the
new, the comment on a line that goes is under the old lines, and any other is
under the new lines.
"""
note_box(beside, gutter, sign, wide) = begin
  half = floor(wide / 2)
  !beside ? (gutter, wide - gutter - 10) : sign == '-' ? (gutter, half - gutter - 10) : (half + gutter, wide - half - gutter - 10)
end

"True when the block of `v` shows the old lines beside the new, with lines `wide` px wide"
beside(v::ChangesView, wide=diff_wide(v)) = editor(v).beside && wide >= BESIDE_LEAST

"The lines of change `k` of `v`, laid out `wide` px wide"
laid(v::ChangesView, k, wide=diff_wide(v)) = get!(v.laid, (k, wide, beside(v, wide), codefont(), codestyle())) do
  h = v.data.hunks[k]
  face = diff_face()
  step = num(measure(face, "0"))
  shown(r) = replace(r.text, '\t' => "  ")
  other, marks = Diffs.matched(h; text=shown)
  lang = lowercase(lstrip(splitext(h.file)[2], '.'))
  texts = map(enumerate(h.rows)) do (j, r)
    chars = collect(shown(r))
    xs = zeros(length(chars) + 1)
    for (i, c) in enumerate(chars)
      xs[i+1] = xs[i] + (isascii(c) ? step : num(measure(face, string(c))))
    end
    parts = [(t.col+1:t.col+length(t.text), t.kind) for t in tokens(String(chars), lang) if !all(isspace, t.text)]
    word = findfirst(!isspace, chars)
    DiffText(chars, xs, parts, marks[j], word === nothing ? 0.0 : xs[word])
  end
  numbered = any(r -> r.old > 0 || r.new > 0, h.rows)
  digits = numbered ? num(measure(Face(face, size=10.5px), string(maximum(r -> max(r.old, r.new), h.rows)))) + 10 : 0.0
  two = beside(v, wide)
  gutter = !numbered ? 12.0 : two ? digits + 10 : 2digits + 10
  room = max((two ? floor(wide / 2) : wide) - gutter - 16 - 8, 12step)
  bands = DiffBand[]
  top = 0.0
  for (l, r) in (two ? Diffs.sides(h, other) : [(j, 0) for j in eachindex(h.rows)])
    lines = (l == 0 ? UnitRange{Int}[] : folded(texts[l], room), r == 0 ? UnitRange{Int}[] : folded(texts[r], room))
    tall = DIFF_ROW * max(length(lines[1]), length(lines[2]), 1)
    push!(bands, DiffBand(top, tall, (l, r), lines))
    top += tall
    # What you said about a row is under it, and so is the field for it
    for j in unique((l, r))
      j == 0 && continue
      said = v.noting == (k, j) ? String[] : haskey(v.data.notes, (k, j)) ?
             wrapped(note_face(), v.data.notes[(k, j)], note_box(two, gutter, h.rows[j].sign, wide)[2] - 20) : continue
      tall = isempty(said) ? NOTE_FIELD + 8 : NOTE_ROW * length(said) + 18
      push!(bands, DiffBand(top, tall, (0, 0), (UnitRange{Int}[], UnitRange{Int}[]), j, said))
      top += tall
    end
  end
  DiffLayout(two, texts, bands, digits, gutter, room, top)
end

"The colour of a line that a change takes away, and of the count of those lines"
removed_colour() = colours.removed
"The colour of a line that a change adds"
added_colour() = colours.added

"How many lines a change adds and takes away, as two small numbers"
tally_words(added, removed) =
  ((added > 0 ? (Box(label("+$(commas(added))", 12px, color=added_colour(), weight="Medium")),) : ())...,
   (removed > 0 ? (Box(label("−$(commas(removed))", 12px, color=removed_colour(), weight="Medium")),) : ())...)

"The end of a file's path that fits in `limit` characters, with … for the folders that it leaves out"
short_path(file, limit=44) = begin
  length(file) <= limit && return file
  parts = split(file, '/')
  k = length(parts)
  while k > 1 && sum(length, parts[k-1:end]) + length(parts) - k + 3 <= limit
    k -= 1
  end
  k == 1 ? file : "…/" * join(parts[k:end], '/')
end

"What the row over a change says: its file, and where the change is in it, like `app.js` and `lines 10 to 13`"
change_words(h) = begin
  place = Diffs.place(h)
  isempty(h.file) ? ("", place) : (short_path(h.file), lowercasefirst(place))
end

describe(v::ChangesView) = begin
  e = editor(v)
  c = v.data
  with_theme(component_theme(e.zoom)) do
    isempty(c.hunks) && return Column(block_look()..., clip=true, name="Changes",
      block_note("This block has no changes yet. Put a diff in it, as git diff writes one: a line that starts with @@, then the lines that go with a - before each, and the lines that come with a +."))
    all = length(c.hunks) > 1 ?
      (rule(), block_button!(v, :accept_all, (:all, :accepted), icon="check-lg", words="Accept all", tip="Make every change in its file"),
       block_button!(v, :reject_all, (:all, :rejected), icon="x-lg", words="Reject all", tip="Reject every change, and take the ones that you accepted out of their files")) : ()
    # The button of the way that the lines show now is lit. A block that's too narrow shows the new lines under the old.
    two = beside(v)
    narrow = diff_wide(v) < BESIDE_LEAST
    ways = (rule(), block_button!(v, :under, (:beside, false), icon="view-stacked", on=!two, tip="Show the new lines under the old lines"),
            block_button!(v, :beside, (:beside, true), icon="layout-split", on=two, off=narrow,
                          tip=narrow ? "The window is too narrow to show the old lines beside the new lines" : "Show the old lines beside the new lines"))
    bar = block_bar(Box(padding(6px, 0px), label(Diffs.summary(c), 12px, color=colours.dim)), Box(width(grow=grow)),
                    Row(child_gap=8px, padding(6px, 0px), tally_words(Diffs.counts(c)...)...), ways..., all...)
    rows = Any[]
    for (k, h) in enumerate(c.hunks)
      state = h.state
      file, place = change_words(h)
      name = isempty(h.file) ? "its file" : basename(h.file)
      push!(rows, Row(width(grow=grow), height(34px), padding(0px, 6px, 0px, 12px), child_gap=8px, Alignment.Center, clip=true,
                      border(1px, :solid, colours.line)[:top], background(colours.stripe),
        Row(child_gap=5px, (isempty(file) ? () : (Box(label(file, 12px, weight="Semibold")),))...,
            (isempty(place) ? () : (Box(label(place, 12px, color=colours.dim)),))...),
        Row(width(grow=grow), clip=true, Alignment.Start,
            Box(Text(h.about, size=11.5px, family=codefont(), subfamily=codestyle(), color=colours.faint, wrap=WrapMode.none))),
        tally_words(Diffs.counts(h)...)...,
        block_button!(v, (:accept, k), (:choose, k, :accepted), icon="check-lg", words=state == :accepted ? "Accepted" : "Accept",
                      on=state == :accepted, tip=state == :accepted ? "Take this change out of $name again" : "Make this change in $name"),
        block_button!(v, (:reject, k), (:choose, k, :rejected), icon="x-lg", words=state == :rejected ? "Rejected" : "Reject",
                      on=state == :rejected, tip=state == :rejected ? "Take your choice away" :
                                                 state == :accepted ? "Reject this change, and take it out of $name" : "Reject this change")))
      # Why Ladder couldn't change the file, under the row
      haskey(v.failed, k) && push!(rows, Row(width(grow=grow), padding(8px, 12px), child_gap=8px, Alignment.Start,
                                             border(1px, :solid, colours.line)[:top], background(RGBA(removed_colour(), 0.08)),
        Icon("exclamation-triangle", size=14px, color=removed_colour()),
        beside_mark(14px, Text(v.failed[k], size=12.5px, family=SANS, color=removed_colour(), wrap=WrapMode.words))))
      push!(rows, block_part!(() -> HunkArea(of=v, k=k), v, (:hunk, k)))
    end
    Column(block_look()..., clip=true, name="Changes", bar, rows...)
  end
end

cursor(::ChangesView) = :arrow
cursor(a::HunkArea) = a.over == 0 ? :arrow : :hand

# Return closes the field for a comment, and Esc puts back what the comment said before
onkey(v::ChangesView, ev::KeyPress{Keys.enter}) = unmodified(ev) ? (v.noting === nothing ? nothing : (stop_noting!(v); handled)) : nothing
onkey(v::ChangesView, ev::KeyPress{Keys.escape}) = unmodified(ev) ? (v.noting === nothing ? nothing : (stop_noting!(v, keep=false); handled)) : nothing

"The line of the change of `a` at the place `x`, `y` of the window: a row of the change or the comment on one. 0 when no line is there."
row_at(a::HunkArea, x, y) = begin
  v, r = a.of, rect(a)
  (r === nothing || a.k > length(v.data.hunks)) && return 0
  l = laid(v, a.k)
  dx, dy = x - num(r.left), y - num(r.top) - 4
  for band in l.bands
    band.top <= dy < band.top + band.tall || continue
    return band.note != 0 ? band.note : band.rows[l.beside && dx >= floor(num(r.width) / 2) ? 2 : 1]
  end
  0
end

onmouse(a::HunkArea, ev::MouseMove) = (a.over = readonly(editor(a.of).buf) ? 0 : row_at(a, num(ev.position[1]), num(ev.position[2])); nothing)

# A click on a line opens the field for what you say about it
onkey(a::HunkArea, ev::KeyPress{Keys.mouse_left}) = begin
  # With ⌥ held, the click is the page's, and it shows the block's lines
  (readonly(editor(a.of).buf) || only_held(a, Keys.opt)) && return nothing
  j = row_at(a, num(ev.window.mouse[1]), num(ev.window.mouse[2]))
  j == 0 ? stop_noting!(a.of) : a.of.noting == (a.k, j) || noting!(a.of, a.k, j)
  handled
end

act!(v::ChangesView, action, w) = begin
  action[1] == :beside && return (beside!(editor(v), action[2]); handled)
  action[1] == :unsay && return (note_input(v).text = ""; stop_noting!(v); handled)
  stop_noting!(v)
  readonly(editor(v).buf) && return handled
  empty!(v.failed)
  if action[1] == :choose
    k, state = action[2], action[3]
    # A click on the choice that a change has takes it away
    decide!(v, k, v.data.hunks[k].state == state ? :open : state)
  else
    foreach(k -> decide!(v, k, action[2]), eachindex(v.data.hunks))
  end
  failed = v.failed
  write_block!(v, CHANGES, Diffs.written(v.data))
  v.failed = failed   # reading the block again forgets them
  handled
end

"""
Give change `k` of `v` the choice `state`, and make its file agree: an
accepted change is in the file, and any other is not. When Ladder can't make
the change in the file, or take it out again, the change keeps the choice
that it had, and `v.failed` says why.
"""
decide!(v::ChangesView, k, state) = begin
  h = v.data.hunks[k]
  h.state == state && return v
  # A choice that's taken away from a rejected change changes no file
  h.state == :rejected && state == :open && return (h.state = state; v)
  back = state != :accepted
  why = change_file!(v, h; back)
  # A change that wasn't accepted is rejected whatever Ladder finds in its file. It's
  # there only when ⌘Z took the choice away after Ladder made it, and then it comes out.
  why === nothing || (back && h.state != :accepted) ? (h.state = state) : (v.failed[k] = why)
  v
end

"Make the change `h` of `v` in its file, or take it out again with `back`. The result is nothing, or words that say why Ladder couldn't."
change_file!(v::ChangesView, h; back=false) = begin
  isempty(h.file) && return "This change doesn't name its file, so Ladder can't make it. A diff names the file in a line that starts with +++, over the change."
  path = Diffs.located(h.file, dirname(abspath(editor(v).buf.path)))
  name = basename(h.file)
  was = isfile(path) ? text(path) : String[]
  done = try
    Diffs.apply!(path, h; back)
  catch err
    return "Ladder couldn't change $path. " * sprint(showerror, err)
  end
  # A file of code that Ladder loaded runs the code that changed, so what it draws is drawn the new way
  if done == :made
    mod = loaded_module(page_key(path))
    mod === nothing || reload_changed!(mod, page_key(path), was)
  end
  done in (:made, :already) ? nothing :
  done == :nofile ? "There's no file at $path, so Ladder didn't make this change." :
  done == :twice ? "The lines that this change takes away are in $name more than once, and the change has no line numbers to say which. Ladder didn't change the file." :
  back ? "The lines that this change put in $name aren't there now, so Ladder didn't change the file." :
         "The lines that this change takes away aren't in $name now, so Ladder didn't change the file."
end

"Show the old lines of every block of changes beside the new lines, or the new lines under the old"
beside!(e, on::Bool) = (e.beside = on; rewrap!(e))   # the line under the mouse stays where it is

describe(a::HunkArea) = begin
  v = a.of
  a.k <= length(v.data.hunks) || return Box(width(grow=grow), height(0px))
  l = laid(v, a.k)
  at = v.noting === nothing || v.noting[1] != a.k ? nothing : findfirst(b -> b.note == v.noting[2], l.bands)
  at === nothing && return Box(width(grow=grow), height(px(l.tall + 8)))
  # The field for a comment is where the comment's box will be. The lines round it are drawn over this.
  band = l.bands[at]
  wide = diff_wide(v)
  x, w = note_box(l.beside, l.gutter, v.data.hunks[a.k].rows[band.note].sign, wide)
  input = note_input(v)
  input.color = colours.ink
  win = window_of(v)
  Column(width(grow=grow), height(px(l.tall + 8)), Alignment.Start,
    Box(height(px(band.top + 8))),
    Row(width(grow=grow), height(px(NOTE_FIELD)), padding(0px, px(wide - x - w), 0px, px(x)), child_gap=4px, Alignment.Center,
      Box(width(grow=grow), height(px(NOTE_FIELD)), padding(9px, 0px), radius(6px), background(colours.bg),
          border(1px, :solid, win !== nothing && win.focus === input ? colours.accent : colours.line), input),
      block_button!(v, :unsay, (:unsay,), icon="trash", tip="Delete this comment")))
end

"Fill a box with slanted lines: the side of a change that has no line. The lines of one box go on in the box under it."
hatch(ctx, x, y, w, h, above) = begin
  shape = Skia.sk_path_new()
  gap = 6.0
  # Each line goes up to the right. `c` is how far across it would cross the top of the change's lines.
  for c in (floor((y - above) / gap) * gap):gap:(w + y + h - above)
    Skia.sk_path_move_to(shape, Float32(x + c - (y + h - above)), Float32(y + h))
    Skia.sk_path_line_to(shape, Float32(x + c - (y - above)), Float32(y))
  end
  paint = ink(RGBA(colours.ink, 0.09), 1.0)
  with_clip(ctx, px(x), px(y), px(w), px(h)) do
    Skia.sk_canvas_draw_path(ctx, shape, paint)
  end
  Skia.sk_paint_delete(paint)
  Skia.sk_path_delete(shape)
end

"""
Draw one side of a line across a change, `wide` px wide with its top left at
`x` and `y`: the row's number, its sign and its text, on the colour of a line
that goes or comes. A change that's rejected is `pale`.
"""
diff_side(ctx, l::DiffLayout, h, band::DiffBand, side, x, y, wide, pale, above) = begin
  j = band.rows[side]
  j == 0 && return hatch(ctx, x, y, wide, band.tall, above)
  r, t = h.rows[j], l.texts[j]
  # A line that stays shows at both sides, with its old number at the left and its new one at the right
  colour = r.sign == '+' ? added_colour() : r.sign == '-' ? removed_colour() : nothing
  colour === nothing || round_box(ctx, x, y, wide, band.tall, 0; fill=RGBA(colour, pale ? 0.05 : 0.13))
  small = Face(diff_face(colour === nothing || pale ? colours.faint : colour), size=10.5px)
  for (i, number) in enumerate(l.beside ? (side == 1 ? r.old : r.new,) : (r.old, r.new))
    number > 0 && write_ink(ctx, string(number), x + 6 + i * l.digits - num(measure(small, string(number))), y + 13.5, small)
  end
  code = diff_face(pale ? colours.faint : colours.ink)
  colour === nothing || write_ink(ctx, r.sign == '-' ? "−" : "+", x + l.gutter, y + 13.5, Face(code, color=pale ? colours.faint : colour))
  for (n, span) in enumerate(band.lines[side])
    isempty(span) && continue
    top = y + (n - 1) * DIFF_ROW
    from = x + l.gutter + 16 + (n > 1 ? hang(t, l.room) : 0.0) - t.xs[first(span)]   # where the row's first character would be
    if colour !== nothing && !pale
      # The words that the other version of the line doesn't have
      for m in t.marks
        lo, hi = max(first(m), first(span)), min(last(m), last(span))
        lo <= hi && round_box(ctx, from + t.xs[lo] - 1, top + 2, t.xs[hi+1] - t.xs[lo] + 2, DIFF_ROW - 4, 3; fill=RGBA(colour, 0.24))
      end
    end
    for (chars, kind) in t.parts
      lo, hi = max(first(chars), first(span)), min(last(chars), last(span))
      lo <= hi || continue
      face = pale || kind == :plain ? code : Face(code, color=getfield(colours, kind), style=kind == :comment ? codeslant() : code.style)
      write_ink(ctx, String(t.chars[lo:hi]), from + t.xs[lo], top + 13.5, face)
    end
  end
end

draw(ctx, size, ui::ConcreteRect, a::HunkArea) = begin
  hunks = a.of.data.hunks
  a.k <= length(hunks) || return
  h = hunks[a.k]
  left, top, wide = num(ui.left), num(ui.top) + 4, num(ui.width)
  l = laid(a.of, a.k, wide)
  half = floor(wide / 2)
  # A change that's rejected is pale
  pale = h.state == :rejected
  over = ishovered(a) ? a.over : 0
  with_clip(ctx, ui.left, ui.top, ui.width, ui.height) do
    for band in l.bands
      y = top + band.top
      if band.note != 0
        # What you said about the row over this, in a box. While its field is open, the field is here.
        isempty(band.said) && continue
        x, w = note_box(l.beside, l.gutter, h.rows[band.note].sign, wide)
        round_box(ctx, left + x, y + 4, w, band.tall - 8, 6; fill=colours.bg, line=over == band.note ? colours.accent : colours.line)
        for (n, words) in enumerate(band.said)
          write_ink(ctx, words, left + x + 10, y + 9 + n * NOTE_ROW - 4.5, Face(note_face(), color=pale ? colours.dim : colours.ink))
        end
        continue
      end
      if over != 0 && over in band.rows && !haskey(a.of.data.notes, (a.k, over)) && a.of.noting != (a.k, over)
        # A mark at the end of the line that the mouse is on says that a click adds a comment
        right = !l.beside || band.rows[2] == over ? left + wide : left + half
        mark = Face(SANS, "Semibold", 13px, colours.bg, false)
        round_box(ctx, right - 24, y + 2, 16, 15, 4; fill=colours.accent)
        write_ink(ctx, "+", right - 16 - num(measure(mark, "+")) / 2, y + 14, mark)
      end
      if l.beside
        diff_side(ctx, l, h, band, 1, left, y, half, pale, top)
        diff_side(ctx, l, h, band, 2, left + half, y, wide - half, pale, top)
      else
        diff_side(ctx, l, h, band, 1, left, y, wide, pale, top)
      end
    end
    l.beside && round_box(ctx, left + half, num(ui.top), 1, num(ui.height), 0; fill=colours.line)
    # A change that's accepted has a green edge
    h.state == :accepted && round_box(ctx, left, num(ui.top), 3, num(ui.height), 0; fill=added_colour())
  end
end

"The changes as HTML: each one with its file, where it is and your choice, its lines, and what you said about them"
changes_html(e, v::ChangesView) = begin
  c = v.data
  isempty(c.hunks) && return nothing
  parts = map(enumerate(c.hunks)) do (k, h)
    about = join(filter(!isempty, [h.file, Diffs.place(h), h.state == :open ? "" : uppercasefirst(string(h.state))]), " · ")
    lines = map(h.rows) do r
      text = escape((r.sign == ' ' ? "  " : r.sign == '-' ? "− " : "+ ") * r.text)
      r.sign == '+' ? "<span style=\"background: #e2f2dc; display: block\">$text</span>" :
      r.sign == '-' ? "<span style=\"background: #f8dfda; display: block\">$text</span>" : "<span style=\"display: block\">$text</span>"
    end
    # What you said about a line is under the change, with the line
    said = join("\n<blockquote><code>$(escape(h.rows[j].sign * h.rows[j].text))</code><br>$(escape(c.notes[(k, j)]))</blockquote>"
                for j in eachindex(h.rows) if haskey(c.notes, (k, j)))
    "<p><strong>$(escape(about))</strong></p>\n<pre><code>" * join(lines) * "</code></pre>" * said
  end
  join(parts, "\n")
end

BLOCKS[CHANGES] = BlockKind("Changes", "file-diff", ChangesView, changes_html)

# --- a calendar of the page's days -------------------------------------------------------------
#
# A code block in the language `calendar` shows one month as a grid of days,
# from Monday to Sunday. calendar.jl says how the block is written. Each day
# shows the things of the page that are on it: the tasks of the page's
# schedule, the to-do items that have a day in their text, and the events
# that the block's own lines hold.
#
#   - The arrows at the top go to the month before and the month after, and
#     Today goes back to the month of today.
#   - Click a thing to select it, and click it twice to go to its line.
#   - Click the box of a to-do item to tick it in the page.
#   - Drag a to-do item or an event to another day. Ladder writes the new day
#     into the item's text or the event's line. A task stays where it is: the
#     schedule says when it's done.
#   - Click a day twice to add an event to it, type its words, and press Return.
#   - A day with more things than it has room for says how many more there
#     are. Click those words to make the week tall enough for all of them.
#
# A block with a line like `in: jobs` is a calendar of a folder: its to-do
# items are those of every page of the folder `jobs` beside the page, as a
# board of a folder has them. A tick and a new day are written into the
# item's own page: see `tick_page!` and `stamp_page!`. Two clicks on such an
# item open its page at its line.

const CALENDAR = Calendars.CALENDAR
push!(BLOCK_ICONS, "calendar3", "chevron-left", "chevron-right")
const DAY_ROWS = 3        # how many lines of things a day has room for
const DAY_HEAD = 26px     # how tall the number of a day is
const THING_H = 20px      # how tall a thing of a day is
const THING_GAP = 2px     # and the space under it
const DAY_TIGHT = 76px    # a day that's narrower than this has less space round its things, and no box or tick before their words

"The day that counts as today, or nothing for the real one. A test names a day here, so that it doesn't depend on the day that it runs."
const calendar_day = Ref{Union{Nothing,Date}}(nothing)
calendar_today() = something(calendar_day[], Dates.today())

"What a `calendar` block shows: a month, with the things of the page on their days"
@def mutable struct CalendarView <: SemanticUI
  n::Int = 0                               # its place among the page's calendars
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Calendars.Calendar = Calendars.Calendar()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  shown::Any = nothing                     # the version of the page and the day, and the things of each day for them
  picked::Any = nothing                    # the thing that's selected, by what `Calendars.id` gives
  grab::Any = nothing                      # the thing that the mouse holds, where the mouse took it, and whether it has moved since
  clicked::NTuple{3,Float64} = (0.0, 0.0, 0.0)   # when and where it was last clicked
  open::Set{Date} = Set{Date}()            # the Monday of each week that shows every thing of its days
  adding::Union{Nothing,Date} = nothing    # the day that a new event is being typed for
  wide::px = 0px                           # how wide a day is
  weeks::Int = 0                           # how many weeks the month that shows is in
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its buttons, days and things, kept between frames
end

"A day of a calendar"
@def mutable struct CalendarDay <: SemanticUI
  of::Any = nothing
  i::Int = 0                 # its place among the days that show
  day::Date = Date(2000)
  tall::px = 0px             # how tall its week is
end
"A thing of a day: a task, a to-do item or an event"
@def mutable struct CalendarThing <: SemanticUI
  of::Any = nothing
  thing::Any = nothing
  box::Any = nothing         # the box of a to-do item
  cut::Bool = false          # its words have no room, and end with …
end
"The box of a to-do item in a calendar. A click ticks the item in the page."
@def mutable struct CalendarTick <: SemanticUI
  of::Any = nothing          # the thing
end
"The words under a day that has more things than room: a click shows them all, or hides them again"
@def mutable struct CalendarMore <: SemanticUI
  of::Any = nothing
  day::Date = Date(2000)
  more::Int = 0              # how many things don't show, or 0 when they all do
end
"The thing that the mouse drags, drawn over the calendar"
@def mutable struct CalendarDrag <: SemanticUI
  of::Any = nothing
end

reread!(v::CalendarView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Calendars.calendar(lines)
  v.shown = nothing
  v
end

"The first day of the month that the calendar shows"
month_shown(v::CalendarView) = Calendars.shown(v.data, today=page_day(editor(v)))

"""
The tasks of the page's first schedule with their days, and whether its work
is done on Saturday and Sunday too. A page with no schedule has no tasks.
"""
calendar_tasks(e) = begin
  b = e.buf
  span = block_lines(b, SCHEDULE, 1)
  span === nothing && return Schedules.Planned[], false
  s = schedule_view(e, 1)
  reread!(s, b.lines[span[1]+1:span[2]-1])
  tasks!(s), s.data.weekends
end

"The things of each day. They're worked out again when the page has changed, and on a new day."
things!(v::CalendarView) = begin
  e = editor(v)
  items = calendar_items(v)
  # The items of a folder are one list until a page of the folder changes
  key = (e.buf.version, v.lines, calendar_today(), objectid(items))
  (v.shown !== nothing && v.shown[1] == key) || (v.shown = (key, Calendars.things(v.data, items, calendar_tasks(e)..., log_things(e))))
  v.shown[2]
end

"The folder whose pages the calendar shows the to-do items of, as a path, or nothing for a calendar of its own page's items"
calendar_folder(v::CalendarView) = begin
  name = Calendars.folder(v.lines)
  name === nothing ? nothing : abspath(joinpath(docdir(editor(v)), expanduser(name)))
end

"The to-do items that the calendar shows on their days: those of its page, or those of every page of its folder, as `folder_todos` gives them"
calendar_items(v::CalendarView) = (folder = calendar_folder(v); folder === nothing ? page_todos(editor(v)) : folder_todos(editor(v), folder).items)

"Where the to-do item called `key` is, for a calendar of a folder: its page, its line and its text. It's nothing for a calendar of its own page."
item_place(v::CalendarView, key) = (folder = calendar_folder(v); folder === nothing ? nothing : get(folder_todos(editor(v), folder).found, key, nothing))

"""
Write the day `to` in place of the day `from` in the text of the to-do item
`m`, in its own page. A page that's open is changed as if you'd typed the day
there. If it isn't the page that shows, and it had nothing to save, it's
saved. A page that isn't open is changed in its file. It gives the item's new
line, or nothing when the item or its day isn't there any more, or its page
can't be written.
"""
stamp_page!(e, m::Searches.Match, from::Date, to::Date) = begin
  b = get(e.buffers, m.path, nothing)
  if b !== nothing && !readonly(b)
    i = Searches.locate(m, b.lines, kinds(b))
    at = i === nothing ? nothing : Calendars.stamp_at(b.lines[i], from)
    at === nothing && return nothing
    clean = !dirty(b)
    caret, anchor = b.caret, b.anchor
    edit!(b, (i, at[1]), (i, at[2]), string(to))
    kept(p) = p[1] == i ? (i, min(p[2], length(b.lines[i]))) : p
    b.caret, b.anchor = kept(caret), kept(anchor)
    b !== e.buf && clean && save!(b)
    i
  else
    isfile(m.path) || return nothing
    lines = text(m.path)
    i = Searches.locate(m, lines)
    at = i === nothing ? nothing : Calendars.stamp_at(lines[i], from)
    at === nothing && return nothing
    lines[i] = first(lines[i], at[1]) * string(to) * join(Iterators.drop(lines[i], at[2]))
    try write(m.path, join(lines, "\n")) catch; return nothing end
    empty!(FOLDER_PAGES)   # the folder is read again, so that the calendar has the file as it is now
    i
  end
end

"""
The things that the page's time logs give its calendars: for each day of a
log, each task with the hours that the log has for it on that day. A click
on one, twice, goes to the first of its rows.
"""
log_things(e) = begin
  b = e.buf
  get!(e.flows, (:log_things, b.path, b.version)) do
    out = Calendars.Thing[]
    ks = kinds(b)
    at = Timelogs.now()
    for (i, k) in enumerate(ks)
      (k.kind == Kind.fence && k.level == 0 && k.lang == TIMELOG) || continue
      t = codeblock(b, i)[2]
      (t > i && ks[t].kind == Kind.fence && ks[t].level == 1) || continue
      lines = b.lines[i+1:t-1]
      rows = [Timelogs.stretch(String(strip(l))) for l in lines]
      for (day, task, minutes) in Timelogs.days(Timelogs.timelog(lines), at)
        minutes > 0 || continue
        r = findfirst(s -> s !== nothing && s.day == day && Timelogs.same(s.task, task), rows)
        push!(out, Calendars.Thing(:log, day, (isempty(task) ? "" : task * "  ") * Timelogs.hours(minutes), false, i + something(r, 0), task))
      end
    end
    out
  end
end

"The things of the day `d`"
day_things(v::CalendarView, d::Date) = get(things!(v), d, Calendars.Thing[])

"The line of the page that the thing `t` is on, or 0 when its block has gone"
thing_line(v::CalendarView, t) = begin
  t.kind == :event || return t.line
  span = block_lines(editor(v).buf, CALENDAR, v.n)
  span === nothing ? 0 : span[1] + t.line
end

"The text field of a calendar, for the words of a new event"
calendar_input(v::CalendarView) = block_part!(v, :input) do
  TextInput(placeholder="New event", font_family=SANS, font_size=12px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"True when the days are narrow, as they are in a narrow window"
tight(v::CalendarView) = v.wide < DAY_TIGHT

"How much room the words of a thing have in a day. `lead` is how wide the box or the tick before them is, with the space after it."
words_room(v::CalendarView, lead=0px) = max(v.wide - (tight(v) ? 13px : 19px) - lead, 1px)

"True while the mouse drags a thing of the calendar"
dragging(v::CalendarView) = v.grab !== nothing && v.grab[4]

"The day that the mouse is over, or nothing when the mouse isn't over a day"
drop_day(v::CalendarView) = begin
  w = window_of(v)
  w === nothing && return nothing
  x, y = w.mouse[1], w.mouse[2]
  for i in 1:7v.weeks
    c = get(v.parts, (:day, i), nothing)
    r = c === nothing ? nothing : rect(c)
    r !== nothing && r.left <= x < r.left + r.width && r.top <= y < r.top + r.height && return c.day
  end
  nothing
end

"Note a click at `(x, y)`. True when it's the second of two clicks in one place."
click_twice!(v::CalendarView, x, y) = begin
  at, cx, cy = v.clicked
  v.clicked = (time(), x, y)
  time() - at < 0.35 && hypot(x - cx, y - cy) < 4
end

"How many lines the day `d` needs when its week shows every thing: its things, the field for a new event, and the words that hide them again"
day_lines(v::CalendarView, d::Date) = (n = length(day_things(v, d)); n + (v.adding == d ? 1 : 0) + (n > DAY_ROWS ? 1 : 0))

"How many lines of things each day of a week has room for. A week that shows every thing has room for the day with the most."
week_rows(v::CalendarView, week) = week[1] in v.open ? max(DAY_ROWS, maximum(d -> day_lines(v, d), week)) : DAY_ROWS

describe(t::CalendarTick) = begin
  thing = t.of.thing
  done = thing !== nothing && thing.done
  side = 13px
  Box(fixed(side), height(side), radius(3.5px), Alignment.Center, justify=Alignment.Center,
      (done ? (background(RGBA(colours.accent, 0.6)),) : (border(1.5px, :solid, ishovered(t) ? colours.accent : colours.marker),))...,
      (done ? (Icon("check", size=11px, color=colours.bg),) : ())...)
end

onkey(t::CalendarTick, ::KeyPress{Keys.mouse_left}) = begin
  c = t.of
  v, thing = c.of, c.thing
  settle!(v)
  e = editor(v)
  (thing === nothing || readonly(e.buf)) && return handled
  place = item_place(v, thing.key)
  # An item of another page is ticked in that page
  place === nothing || return (tick_page!(e, place, !thing.done); v.shown = nothing; handled)
  items = page_todos(e)
  k = findfirst(it -> it.key == thing.key, items)
  k === nothing || tick!(e, items[k].line)
  handled
end

describe(c::CalendarThing) = begin
  v, t = c.of, c.thing
  t === nothing && return Box(height(0px))
  on = v.picked == Calendars.id(t)
  taken = dragging(v) && Calendars.id(v.grab[1]) == Calendars.id(t)
  # A thing is marked while the mouse is on it in another part of the page, or on another of its days here
  lit = !taken && (t.kind == :task || !ishovered(c)) && marked(v, thing_name(t))
  c.box === nothing && (c.box = CalendarTick(of=c); setfield!(c.box, :parent, c))
  if t.kind == :task
    # A task looks like its bar in the schedule
    hue = t.done ? colours.string : colours.accent
    look = (background(RGBA(hue, on || lit ? 0.32 : 0.17)), border(on || lit ? 1.5px : 1px, :solid, RGBA(hue, 0.9)))
    lead = t.done && !tight(v) ? (Icon("check", size=12px, color=hue),) : ()
  elseif t.kind == :log
    # The hours of a time log are quiet: a small clock and grey words, with no box round them
    look = (background(lit ? mark_colour(takeoff_back()) : clear), border(1px, :solid, on || lit ? colours.accent : clear))
    lead = tight(v) ? () : (Icon("stopwatch", size=11px, color=colours.dim),)
  else
    look = (background(taken ? clear : lit ? mark_colour(colours.block) : colours.block),
            border(on && !taken ? 1.5px : 1px, :solid, taken ? colours.faint : on || lit ? colours.accent : ishovered(c) ? colours.marker : colours.line))
    # A narrow day has no room for the box: the words need it
    lead = t.kind == :todo && !tight(v) ? (c.box,) : ()
  end
  words = elide(t.words, 12px, words_room(v, isempty(lead) ? 0px : 18px))
  c.cut = words != t.words
  Row(width(grow=grow), height(THING_H), padding(tight(v) ? 3px : 5px, 0px), radius(5px), child_gap=5px, Alignment.Center, clip=true, name="Thing", look...,
    lead..., Box(label(words, 12px, color=taken ? colours.faint : t.done || t.kind == :log ? colours.dim : colours.ink)), Box(width(grow=grow)))
end

cursor(::Union{CalendarThing,CalendarTick,CalendarMore}) = :hand
cursor(::Union{CalendarView,CalendarDay,CalendarDrag}) = :arrow

onkey(c::CalendarThing, ev::KeyPress{Keys.mouse_left}) = begin
  v, w, t = c.of, ev.window, c.thing
  settle!(v)
  hide_tooltip!(w)
  t === nothing && return handled
  x, y = num(w.mouse[1]), num(w.mouse[2])
  twice = click_twice!(v, x, y)
  again = v.picked == Calendars.id(t)
  v.picked = Calendars.id(t)
  # Two clicks in one place go to the thing's line of the page, or of its own page for an item of a calendar of a folder
  if twice && again
    place = t.kind == :todo ? item_place(v, t.key) : nothing
    return place === nothing ? show_line!(editor(v), thing_line(v, t)) : visit!(editor(v), place.path, place)
  end
  # A task's days are the schedule's, and the hours of a log are the log's, so they stay where they are
  t.kind in (:task, :log) || readonly(editor(v).buf) || (v.grab = (t, x, y, false))
  # The press isn't a click on the page's text, so the text doesn't select when the mouse leaves the calendar with the thing
  e = editor(v)
  e.clicked = (e.clicked[1], e.clicked[2], 0)
  handled
end

# A thing whose words are cut short shows all of them over it
onmouse(c::CalendarThing, ev::MouseMove) = begin
  v, r = c.of, rect(c)
  (c.cut && c.thing !== nothing && v.grab === nothing && r !== nothing) || return nothing
  show_tooltip!(ev.window, tip_label(c.thing.words), r.left, r.top, r.width, r.height, placement=:top, gap=6px)
  nothing
end

describe(m::CalendarMore) = begin
  words = m.more > 0 ? "$(m.more) more" : "Fewer"
  Row(width(grow=grow), height(THING_H), padding(tight(m.of) ? 4px : 6px, 0px), Alignment.Center, clip=true, name="More",
    Box(label(elide(words, 11px, words_room(m.of)), 11px, color=ishovered(m) ? colours.accent : colours.dim)), Box(width(grow=grow)))
end

onkey(m::CalendarMore, ::KeyPress{Keys.mouse_left}) = begin
  v, week = m.of, Calendars.monday(m.day)
  settle!(v)
  week in v.open ? delete!(v.open, week) : push!(v.open, week)
  handled
end

describe(c::CalendarDay) = begin
  v, d = c.of, c.day
  list = day_things(v, d)
  open = Calendars.monday(d) in v.open
  some, more = open ? (list, 0) : Calendars.fit(list, DAY_ROWS)
  inside = Dates.month(d) == Dates.month(month_shown(v))
  weekend = Dates.dayofweek(d) > 5
  number = string(Dates.day(d))
  # The page's day has a circle. When that isn't today, today has a ring.
  head = d == page_day(editor(v)) ?
    Row(fixed(20px), height(20px), radius(10px), Alignment.Center, justify=Alignment.Center, background(colours.accent),
        Box(label(number, 11px, color=colours.bg, weight="Semibold"))) :
    d == calendar_today() ?
    Row(fixed(20px), height(20px), radius(10px), Alignment.Center, justify=Alignment.Center, border(1.5px, :solid, colours.accent),
        Box(label(number, 11px, color=colours.accent, weight="Semibold"))) :
    Row(height(20px), padding(4px, 0px), Alignment.Center,
        Box(label(number, 11px, color=!inside ? colours.faint : weekend ? colours.dim : colours.ink)))
  field = v.adding == d ?
    (Box(width(grow=grow), height(THING_H), padding(tight(v) ? 3px : 5px, 0px), radius(5px), border(1px, :solid, colours.accent), background(colours.bg), calendar_input(v)),) : ()
  under = more > 0 || (open && length(list) > DAY_ROWS) ?
    ((m = block_part!(() -> CalendarMore(of=v), v, (:more, c.i)); m.day = d; m.more = more; m),) : ()
  over = dragging(v) && drop_day(v) == d
  Column(width(grow=grow), height(c.tall), padding(tight(v) ? 2px : 3px, 0px), child_gap=THING_GAP, Alignment.Start, clip=true, name="Day",
         border(1px, :solid, colours.line)[(c.i % 7 == 1 ? (:top,) : (:top, :left))...],
         background(over ? RGBA(colours.accent, 0.14) : weekend ? RGBA(colours.ink, 0.035) : clear),
    Row(width(grow=grow), height(DAY_HEAD - THING_GAP), padding(tight(v) ? 2px : 1px, 0px), Alignment.Center, head, Box(width(grow=grow))),
    [(t = block_part!(() -> CalendarThing(of=v), v, (:thing, c.i, k)); t.thing = thing; t) for (k, thing) in enumerate(some)]...,
    field..., under...)
end

onkey(c::CalendarDay, ev::KeyPress{Keys.mouse_left}) = begin
  v, w = c.of, ev.window
  settle!(v)
  v.picked = nothing
  # Two clicks on a day start a new event there
  click_twice!(v, num(w.mouse[1]), num(w.mouse[2])) && !readonly(editor(v).buf) && return add_event!(v, c.day)
  handled
end

"Show the field for a new event on the day `d`, and give it the keyboard"
add_event!(v::CalendarView, d::Date) = begin
  i = calendar_input(v)
  i.color = colours.ink
  i.text = ""
  i.anchor = i.cursor = 0
  v.adding = d
  v.clicked = (0.0, 0.0, 0.0)          # the next click isn't the second of two
  push!(v.open, Calendars.monday(d))   # the week grows, so that the field has room
  focus(i)
  handled
end

"Take the field for a new event away. With `keep`, the words that were typed are written into the block as an event."
settle!(v::CalendarView; keep=true) = begin
  d = v.adding
  d === nothing && return handled
  v.adding = nothing
  i = calendar_input(v)
  w = window_of(v)
  w !== nothing && w.focus === i && focus(editor(v))
  words = strip(replace(i.text, r"\s+" => " "))
  keep && !isempty(words) && write_block!(v, CALENDAR, Calendars.added(v.lines, d, words))
  handled
end

onkey(v::CalendarView, ev::KeyPress{Keys.enter}) = unmodified(ev) ? (v.adding === nothing ? nothing : settle!(v)) : nothing
onkey(v::CalendarView, ev::KeyPress{Keys.escape}) = unmodified(ev) ? (v.adding === nothing ? nothing : settle!(v, keep=false)) : nothing
# A click beside a button is the block's, and doesn't move the caret
onkey(v::CalendarView, ::KeyPress{Keys.mouse_left}) = (settle!(v); handled)
# A drag is the calendar's, so the page's text doesn't select
onmouse(v::CalendarView, ::MouseMove) = v.grab !== nothing || held(v, Keys.mouse_left) ? handled : nothing

"Do what a button of a calendar does: show the month before, the month after or the month of today"
act!(v::CalendarView, action, w) = begin
  settle!(v)
  empty!(v.open)
  to = action == :today ? nothing : month_shown(v) + Dates.Month(action == :before ? -1 : 1)
  write_block!(v, CALENDAR, Calendars.turned(v.lines, to))
  handled
end

describe(v::CalendarView) = begin
  e = editor(v)
  w = window_of(v)
  g = v.grab
  # A press that moves is a drag, and isn't the first click of two
  if g !== nothing && !g[4] && w !== nothing && hypot(num(w.mouse[1]) - g[2], num(w.mouse[2]) - g[3]) > 4
    v.grab = (g[1], g[2], g[3], true)
    v.clicked = (0.0, 0.0, 0.0)
  end
  calendar_input(v).color = colours.ink
  with_theme(component_theme(e.zoom)) do
    month = month_shown(v)
    weeks = Calendars.weeks(month)
    v.wide = (e.width - 2px) / 7   # each day is as wide as the next
    v.weeks = length(weeks)
    off = readonly(e.buf)
    bar = block_bar(
      block_button!(v, :before, :before, icon="chevron-left", tip="The month before", off=off),
      Row(fixed(max(min(122px, e.width - 150px), 10px)), Alignment.Center, justify=Alignment.Center, clip=true,
          Box(label(Calendars.title(month), 13px, weight="Semibold"))),
      block_button!(v, :after, :after, icon="chevron-right", tip="The month after", off=off),
      Box(width(grow=grow)),
      block_button!(v, :today, :today, words="Today", tip="Show the month of today", off=off || v.data.month === nothing))
    names = Row(width(grow=grow), height(24px), Alignment.Center,
      [Row(fixed(v.wide), padding(8px, 0px), Alignment.Center, clip=true,
           Box(label(name, 11px, color=i > 5 ? colours.faint : colours.dim)), Box(width(grow=grow))) for (i, name) in enumerate(Calendars.DAYS)]...)
    rows = map(enumerate(weeks)) do (k, week)
      tall = DAY_HEAD + week_rows(v, week) * (THING_H + THING_GAP) + 3px
      days = map(enumerate(week)) do (i, d)
        c = block_part!(() -> CalendarDay(of=v), v, (:day, 7(k - 1) + i))
        c.i, c.day, c.tall = 7(k - 1) + i, d, tall
        Box(fixed(v.wide), Alignment.Start, c)
      end
      Row(width(grow=grow), Alignment.Start, days...)
    end
    Stack(block_look()..., clip=true, name="Calendar", Column(width(grow=grow), Alignment.Start, bar, names, rows...),
          (dragging(v) ? (block_part!(() -> CalendarDrag(of=v), v, :drag),) : ())...)
  end
end

describe(::CalendarDrag) = Box(width(grow=grow), height(grow=grow))

draw(ctx, size, ui::ConcreteRect, layer::CalendarDrag) = begin
  v = layer.of
  w = window_of(v)
  (w === nothing || !dragging(v)) && return
  t = v.grab[1]
  # The thing stays under the mouse
  wide = max(num(v.wide) - 6, 40.0)
  x, y = num(w.mouse[1]) - wide / 2, num(w.mouse[2]) - 10
  face = Face(SANS, "", 12px, colours.ink, false)
  round_box(ctx, x + 1, y + 3, wide, 20, 5; fill=RGBA(0, 0, 0, 0.12))
  round_box(ctx, x, y, wide, 20, 5; fill=takeoff_back(), line=colours.accent, wide=1.5)
  write_ink(ctx, elide(t.words, 12px, px(wide - 12)), x + 6, y + 14, face)
end

"A drag ended. Ladder writes the day that the thing was dropped on into the to-do item's text, or into the event's line."
drop!(v::CalendarView) = begin
  g = v.grab
  v.grab = nothing
  (g === nothing || !g[4]) && return v
  t, d = g[1], drop_day(v)
  e = editor(v)
  b = e.buf
  (d === nothing || d == t.day || readonly(b)) && return v
  if t.kind == :event
    write_block!(v, CALENDAR, Calendars.moved(v.lines, t.line, d))
  elseif t.kind == :todo && calendar_folder(v) !== nothing
    # The item's own page gets the new day
    place = item_place(v, t.key)
    line = place === nothing ? nothing : stamp_page!(e, place, t.day, d)
    line === nothing && return v
    # The item's name has the new day in it, and the item stays selected
    found = folder_todos(e, calendar_folder(v)).found
    now = findfirst(m -> m.path == place.path && m.line == line, found)
    v.picked = now === nothing ? nothing : (:todo, now)
  elseif t.kind == :todo
    k = findfirst(it -> it.key == t.key, page_todos(e))
    k === nothing && return v
    line = page_todos(e)[k].line
    at = Calendars.stamp_at(b.lines[line], t.day)
    at === nothing && return v
    caret, anchor = b.caret, b.anchor
    edit!(b, (line, at[1]), (line, at[2]), string(d))
    kept(p) = p[1] == line ? (line, min(p[2], length(b.lines[line]))) : p
    b.caret, b.anchor = kept(caret), kept(anchor)
    # The item's name has the new day in it, and the item stays selected
    k = findfirst(it -> it.line == line, page_todos(e))
    k === nothing || (v.picked = (:todo, page_todos(e)[k].key))
  end
  v.shown = nothing
  v
end

"What happens to a calendar in each frame, before the page is laid out: a drag that ended is written down, and the field that lost the keyboard closes"
block_tick!(v::CalendarView) = begin
  v.grab !== nothing && !held(v, Keys.mouse_left) && drop!(v)
  w = window_of(v)
  # A click somewhere else took the keyboard from the field. The words that were typed are kept.
  v.adding !== nothing && w !== nothing && w.focus !== calendar_input(v) && settle!(v)
  v
end

"A thing of a day as HTML. A thing that's done has a tick, and is grey."
thing_html(t) = t.done ? "<span style=\"color: #8a8176\">✓ $(escape(t.words))</span>" : escape(t.words)

"The calendar as HTML: a table with a row for each week of the month, and the things of each day in the day's cell"
calendar_html(e, v::CalendarView) = begin
  month = month_shown(v)
  days = things!(v)
  cell(d) = begin
    number = Dates.month(d) == Dates.month(month) ? "<b>$(Dates.day(d))</b>" : "<span style=\"color: #a89f91\">$(Dates.day(d))</span>"
    "<td style=\"vertical-align: top\">" * join([number; thing_html.(get(days, d, Calendars.Thing[]))], "<br>") * "</td>"
  end
  heads = join("<th>$name</th>" for name in Calendars.DAYS)
  rows = join(("<tr>" * join(cell.(week)) * "</tr>" for week in Calendars.weeks(month)), "\n")
  "<table style=\"width: 100%; table-layout: fixed\">\n<caption>$(Calendars.title(month))</caption>\n<tr>$heads</tr>\n$rows\n</table>"
end

BLOCKS[CALENDAR] = BlockKind("Calendar", "calendar3", CalendarView, calendar_html)

# --- a board of the page's tasks ---------------------------------------------------------------
#
# A code block in the language `board` shows each to-do item of the page as a
# card, in columns. board.jl says how the block is written. Drag a card to
# another column to move it. The last column holds the items that are ticked:
# a card that's dropped there ticks its item in the page, and a card that's
# dragged out of it takes the tick away. Click a card twice to go to its line
# of the page. The block's lines hold the column of each card that's between
# the first column and the last.
#
# A block with a line like `in: jobs` is a board of a folder: its cards are
# the to-do items of every page of the folder `jobs` beside the page, and of
# the folders in it. `in: .` is the page's own folder. Each card has the name
# of its page under its words. A card that's dropped on the last column ticks
# its item in the item's own page, as a click on a box of a `find` block
# does: see `tick_page!`. Two clicks on a card open its page at its line. The
# schedule of the board's page plans only that page's items, so a board of a
# folder shows today on every day of the page.

const BOARD = Boards.BOARD
push!(BLOCK_ICONS, "kanban")

"What a `board` block shows: the page's to-do items as cards in columns"
@def mutable struct BoardView <: SemanticUI
  n::Int = 0                               # its place among the page's boards
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Boards.Board = Boards.Board()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  shown::Any = nothing                     # the version of the page, and the cards of each column for that page
  grab::Any = nothing                      # the card that the mouse holds: its name, where the mouse took it, and whether it has moved since
  clicked::NTuple{3,Float64} = (0.0, 0.0, 0.0)   # when and where a card was last clicked
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its columns and cards, kept between frames
end

"A column of a board"
@def mutable struct BoardColumn <: SemanticUI
  of::Any = nothing
  c::Int = 0
end
"A card of a board: one to-do item of the page"
@def mutable struct BoardCard <: SemanticUI
  of::Any = nothing
  key::String = ""
end
"The card that the mouse drags, drawn over the board"
@def mutable struct DragLayer <: SemanticUI
  of::Any = nothing
end

reread!(v::BoardView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Boards.board(lines)
  v.shown = nothing
  v
end

"The cards of each column of the board. They're worked out again when the page has changed, and when it shows another day."
columns!(v::BoardView) = begin
  e = editor(v)
  items = board_items(v)
  # The items of a folder are one list until a page of the folder changes
  key = (e.buf.version, v.lines, page_day(e), objectid(items))
  (v.shown !== nothing && v.shown[1] == key) || (v.shown = (key, board_folder(v) === nothing ? cards_on_day(e, v.data) : Boards.arrange(v.data, items)))
  v.shown[2]
end

"The folder whose pages the board shows the items of, as a path, or nothing for a board of its own page's items"
board_folder(v::BoardView) = begin
  name = Boards.folder(v.data)
  name === nothing ? nothing : abspath(joinpath(docdir(editor(v)), expanduser(name)))
end

"""
The to-do items of every page of `folder`, and then of the folders in it, in
the order of the pages' names, for a board or a calendar of a folder.
`items` has each as a to-do item that's called by its page and its text, like
`plans/kitchen: Lay the new pipe`, so two pages can each have an item with
the same words. `found` says where each is, by that name: its page, its line
and its text. They're found again when a page changes in Ladder, and when
the folder is read again. A folder that isn't there has none.
"""
folder_todos(e, folder::AbstractString) = begin
  isdir(folder) || return get!(() -> (key=nothing, items=Schedules.Todo[], found=Dict{String,Searches.Match}()), e.flows, (:no_folder_todos, folder))
  listed = folder_pages(folder)
  key = (hash([b.version for b in values(e.buffers)]), listed.read)
  kept = get(e.flows, (:folder_todos, folder), nothing)
  kept !== nothing && kept.key == key && return kept
  pages = get!(() -> Dict{String,Any}(), e.flows, :folder_todo_pages)   # the items of each page, for every board and calendar of the window
  # A list finds the items that aren't ticked, or the ones that are. These are both, in the order of their lines.
  open, done = Searches.Query(:todo, String[], "", String[]), Searches.Query(:done, String[], "", String[])
  both(path, lines, ks) = sort!([Searches.matches(open, path, lines, ks); Searches.matches(done, path, lines, ks)], by=m -> m.line)
  items, found = Schedules.Todo[], Dict{String,Searches.Match}()
  for (path, at) in listed.pages
    lines, ks, mark = page_text(e, path, at)
    had = get(pages, path, nothing)
    ms = had !== nothing && had[1] == mark ? had[2] : (pages[path] = (mark, both(path, lines, ks)))[2]
    page = splitext(relpath(path, folder))[1]
    seen = Dict{String,Int}()
    for m in ms
      n = seen[m.text] = get(seen, m.text, 0) + 1
      name = "$page: $(m.text)" * (n == 1 ? "" : " #$n")
      push!(items, Schedules.Todo(m.line, m.text, name, 0, m.kind == :done))
      found[name] = m
    end
  end
  e.flows[(:folder_todos, folder)] = (key=key, items=items, found=found)
end

"The to-do items that the board shows: those of its page, or those of every page of its folder, as `folder_todos` gives them"
board_items(v::BoardView) = (folder = board_folder(v); folder === nothing ? page_todos(editor(v)) : folder_todos(editor(v), folder).items)

"Where the item of the card called `key` is, for a board of a folder: its page, its line and its text. It's nothing for a board of its own page, and for a card that the folder has no more."
card_place(v::BoardView, key) = (folder = board_folder(v); folder === nothing ? nothing : get(folder_todos(editor(v), folder).found, key, nothing))

"""
The cards of each column on the page's day. Today, that's what the page's
items and the board's lines say. On another day, a page with a schedule shows
the plan: a task that's finished by that day is in the last column, a task
that runs on that day is in the second column of three or more, and the rest
are in the first.
"""
cards_on_day(e, board::Boards.Board) = begin
  tasks = planned_tasks(e)
  # With no schedule to plan from, a card is where its item was on the page's day, as git has it: see `todos_then`
  isempty(tasks) && return Boards.arrange(board, todos_then(e))
  n = length(board.columns)
  out = [Schedules.Todo[] for _ in 1:n]
  for t in tasks
    s = standing(e, t)
    push!(out[s == :done ? n : s == :doing && n > 2 ? 2 : 1], t.todo)
  end
  out
end

"True when the board shows the schedule's plan for another day than today. Its cards stay where they are then."
planned(v::BoardView) = board_folder(v) === nothing && !isempty(planned_tasks(editor(v)))

"True when the board shows the items as git has them for a day before today: a board of its own page with no schedule to plan from. Its cards stay where they are then, too."
past(v::BoardView) = board_folder(v) === nothing && !planned(v) && page_then(editor(v)) !== nothing

"True when the card of the item `t` shows as done"
card_done(v::BoardView, t) = planned(v) || past(v) ? t in columns!(v)[end] : t.done

"The to-do item of the page that the card called `key` is for, or nothing"
card_todo(v::BoardView, key) = (items = board_items(v); k = findfirst(t -> t.key == key, items); k === nothing ? nothing : items[k])

"True while the mouse drags a card of the board"
dragging(v::BoardView) = v.grab !== nothing && v.grab[4]

"The place of the column that the mouse is over, or nothing when the mouse isn't over the board"
drop_column(v::BoardView) = begin
  w = window_of(v)
  r = rect(v)
  (w === nothing || r === nothing) && return nothing
  x, y = w.mouse[1], w.mouse[2]
  (r.top - 40px <= y <= r.top + r.height + 40px) || return nothing
  for c in eachindex(v.data.columns)
    column = get(v.parts, (:column, c), nothing)
    cr = column === nothing ? nothing : rect(column)
    cr !== nothing && cr.left <= x < cr.left + cr.width && return c
  end
  nothing
end

describe(card::BoardCard) = begin
  v = card.of
  t = card_todo(v, card.key)
  t === nothing && return Box(height(0px))
  taken = dragging(v) && v.grab[1] == card.key
  done = card_done(v, t)
  place = card_place(v, card.key)
  # A card is marked while the mouse is on its item in another part of the page
  lit = !taken && !ishovered(card) && marked(v, card.key)
  Row(width(grow=grow), padding(10px, 8px), radius(6px), child_gap=7px, Alignment.Start, name="Card",
      background(taken ? clear : lit ? mark_colour(takeoff_back()) : takeoff_back()),
      border(1px, :solid, taken ? colours.faint : lit ? colours.accent : ishovered(card) ? colours.marker : colours.line),
    (done ? (Box(padding(0px, 2px), Icon("check", size=14px, color=taken ? colours.faint : colours.string)),) : ())...,
    Column(width(grow=grow), Alignment.Start, child_gap=3px,
      Box(width(grow=grow), Text(t.name, size=13px, family=SANS, color=taken ? colours.faint : done ? colours.dim : colours.ink, wrap=WrapMode.words)),
      # A card of a board of a folder says which page its item is in
      (place === nothing ? () : (Box(width(grow=grow), clip=true, label(card_page(v, place), 11px, color=colours.faint)),))...))
end

"The name of the page of a card's item as the card shows it: where it is in the board's folder, without the end of its file's name"
card_page(v::BoardView, place) = splitext(relpath(place.path, board_folder(v)))[1]

cursor(card::BoardCard) = planned(card.of) || past(card.of) ? :arrow : :hand
cursor(::Union{BoardView,BoardColumn,DragLayer}) = :arrow

onkey(card::BoardCard, ev::KeyPress{Keys.mouse_left}) = begin
  v, w = card.of, ev.window
  x, y = num(w.mouse[1]), num(w.mouse[2])
  at, cx, cy = v.clicked
  v.clicked = (time(), x, y)
  t = card_todo(v, card.key)
  # Two clicks in one place go to the card's line of the page, or of its own page for a board of a folder
  if time() - at < 0.35 && hypot(x - cx, y - cy) < 4 && t !== nothing
    place = card_place(v, card.key)
    return place === nothing ? show_line!(editor(v), t.line) : visit!(editor(v), place.path, place)
  end
  # A board that shows the plan for another day, or the items of a day that's past, has no card to move
  planned(v) || past(v) || (v.grab = (card.key, x, y, false))
  handled
end

describe(col::BoardColumn) = begin
  v = col.of
  cards = col.c <= length(columns!(v)) ? columns!(v)[col.c] : Schedules.Todo[]
  over = dragging(v) && drop_column(v) == col.c
  Column(width(grow=grow), Alignment.Start, radius(8px), padding(8px), child_gap=6px, name="Column",
         background(over ? RGBA(colours.accent, 0.14) : colours.block),
    Row(width(grow=grow), height(22px), padding(3px, 0px), child_gap=7px, Alignment.Center,
        Box(label(get(v.data.columns, col.c, ""), 12px, color=colours.dim, weight="Semibold")),
        Box(label(string(length(cards)), 11px, color=colours.faint)), Box(width(grow=grow))),
    [block_part!(() -> BoardCard(of=v, key=t.key), v, (:card, t.key)) for t in cards]...,
    (isempty(cards) ? (Box(width(grow=grow), height(34px)),) : ())...)
end

describe(v::BoardView) = begin
  e = editor(v)
  w = window_of(v)
  g = v.grab
  # A press that moves is a drag
  if g !== nothing && !g[4] && w !== nothing && hypot(num(w.mouse[1]) - g[2], num(w.mouse[2]) - g[3]) > 4
    v.grab = (g[1], g[2], g[3], true)
  end
  # The cards of items that the page had once are forgotten
  items = board_items(v)
  folder = board_folder(v)
  length(v.parts) > 2length(items) + 40 && filter!(p -> !(p[1] isa Tuple && p[1][1] == :card) || card_todo(v, p[1][2]) !== nothing, v.parts)
  with_theme(component_theme(e.zoom)) do
    isempty(items) && return Column(block_look()..., clip=true, name="Board",
      block_note(folder === nothing ? "This page has no to-do items yet. Start a line with - [ ] to make a card." :
                 isdir(folder) ? "No page of the folder “$(basename(folder))” has a to-do item yet." :
                 "There's no folder called “$(Boards.folder(v.data))” beside this page."))
    n = length(v.data.columns)
    wide = (e.width - 2px - 16px - 8px * (n - 1)) / n   # each column is as wide as the next
    columns = Row(width(grow=grow), padding(8px), child_gap=8px, Alignment.Start,
      [Box(fixed(wide), Alignment.Start, block_part!(() -> BoardColumn(of=v, c=c), v, (:column, c))) for c in 1:n]...)
    # On another day than today, a line over the columns says whose cards these are
    d = page_day(e)
    planned(v) && (columns = Column(width(grow=grow), Alignment.Start,
      Row(width(grow=grow), height(30px), padding(14px, 0px), child_gap=7px, Alignment.Center, clip=true,
          Icon("calendar-day", size=13px, color=colours.accent),
          Box(label("As the schedule plans it for $(Dates.dayname(d)) $(Schedules.long(d))", 12px, color=colours.dim)), Box(width(grow=grow))),
      columns))
    past(v) && (columns = Column(width(grow=grow), Alignment.Start,
      Row(width(grow=grow), height(30px), padding(14px, 0px), child_gap=7px, Alignment.Center, clip=true,
          Icon("calendar-day", size=13px, color=colours.accent),
          Box(label("As git has the page for $(Dates.dayname(d)) $(Schedules.long(d))", 12px, color=colours.dim)), Box(width(grow=grow))),
      columns))
    # A board of a folder says whose items these are
    folder === nothing || (columns = Column(width(grow=grow), Alignment.Start,
      Row(width(grow=grow), height(30px), padding(14px, 0px), child_gap=7px, Alignment.Center, clip=true,
          Icon("folder", size=13px, color=colours.dim),
          Box(label("Every page of $(basename(folder))", 12px, color=colours.dim)), Box(width(grow=grow))),
      columns))
    Stack(block_look()..., clip=true, name="Board", columns,
          (dragging(v) ? (block_part!(() -> DragLayer(of=v), v, :drag),) : ())...)
  end
end

describe(::DragLayer) = Box(width(grow=grow), height(grow=grow))

draw(ctx, size, ui::ConcreteRect, layer::DragLayer) = begin
  v = layer.of
  w = window_of(v)
  (w === nothing || !dragging(v)) && return
  t = card_todo(v, v.grab[1])
  column = get(v.parts, (:column, 1), nothing)
  cr = column === nothing ? nothing : rect(column)
  (t === nothing || cr === nothing) && return
  # The card stays under the mouse where the mouse took hold of it
  wide = num(cr.width) - 16
  x, y = num(w.mouse[1]) - wide / 2, num(w.mouse[2]) - 17
  face = Face(SANS, "", 13px, colours.ink, false)
  round_box(ctx, x + 1, y + 3, wide, 34, 6; fill=RGBA(0, 0, 0, 0.12))
  round_box(ctx, x, y, wide, 34, 6; fill=takeoff_back(), line=colours.accent, wide=1.5)
  write_ink(ctx, elide(t.name, 13px, px(wide - 20)), x + 10, y + 22, face)
end

"A drag ended. The card goes to the column that it was dropped on, and its item is ticked if that's the last one."
drop!(v::BoardView) = begin
  g = v.grab
  v.grab = nothing
  (g === nothing || !g[4]) && return v
  c = drop_column(v)
  e = editor(v)
  b = e.buf
  items = board_items(v)
  t = card_todo(v, g[1])
  (c === nothing || t === nothing || readonly(b) || Boards.column(v.data, t, items) == c) && return v
  place = card_place(v, g[1])
  # The item of another page is ticked there first. If its page can't be written, the card stays where it is.
  if place !== nothing
    last = length(v.data.columns)
    turns = c == last ? !t.done : t.done
    turns && !tick_page!(e, place, c == last) && return v
  end
  Boards.prune!(v.data, items)
  tick = Boards.move!(v.data, t, c, items)
  # The tick and the block's lines change together, so one ⌘Z takes both back
  b.typed = 0.0
  if tick !== nothing && place === nothing
    caret, anchor = b.caret, b.anchor
    col = findfirst('[', b.lines[t.line])
    edit!(b, (t.line, col), (t.line, col + 1), tick ? "x" : " ", typing=true)
    b.caret, b.anchor = caret, anchor
  end
  write_block!(v, BOARD, Boards.written(v.data), typing=true)
  b.typed = 0.0
  v.shown = nothing
  v
end

block_tick!(v::BoardView) = (v.grab !== nothing && !held(v, Keys.mouse_left) && drop!(v); v)
# A drag is the board's, so the page's text doesn't select
onmouse(v::BoardView, ::MouseMove) = v.grab === nothing ? nothing : handled

"The board as HTML: a table with a column for each of the board's columns"
board_html(e, v::BoardView) = begin
  columns = columns!(v)
  all(isempty, columns) && return nothing
  heads = join("<th>$(escape(name))</th>" for name in v.data.columns)
  cells = join("<td style=\"vertical-align: top\">" * join((escape(t.name) for t in cards), "<br>") * "</td>" for cards in columns)
  "<table>\n<tr>$heads</tr>\n<tr>$cells</tr>\n</table>"
end

BLOCKS[BOARD] = BlockKind("Board", "kanban", BoardView, board_html)

# --- blocks of the page side by side -------------------------------------------------------------
#
# A code block in the language `columns` holds a number, and that many of the
# blocks after it show side by side. columns.jl says how the block is written
# and which blocks each column holds. The blocks stay the page's own lines:
# the caret goes into them, and every key does there what it does anywhere else.
#
# The page's layout does the work. `page_columns!` finds the columns before
# the page is laid out. `column_turn!` is called at each line of the layout.
# In a column it makes the page's text as wide as the column, so each line
# wraps there, and each table, picture and component is made for that width.
# A column's lines of text and its tables are placed at the column's left
# edge. So the caret, the selection and a click find them as they find any
# other line. Each column starts level with the first, and the page goes on
# under the tallest. `page_parts` puts the columns side by side in the window.
#
# In a narrow window the blocks show one under another.
#
# The `columns` block itself takes no room in the page, and shows nothing.
# `column_fold` says which lines that is: the block's own, and as many of the
# empty lines after it as there are before it. So the room over the columns is
# the room between two blocks. As rich text the caret steps over those lines,
# as it steps over the ``` lines of a code block. As plain text (⌘E) the caret
# goes through them, and the block shows its lines while the caret is on them.
# A block that doesn't say how many columns keeps a little room, and says how
# to write it.

const COLUMN_BLOCK = Columns.COLUMNS   # the language of the block. `COLUMNS` is the columns of a takeoff's table.
const COLUMN_GAP = 1.6     # the room between two columns, as a part of the size of the page's text
const COLUMN_MARK = 1px    # how tall a `columns` block that says nothing is in the page, without the room above and below it
push!(BLOCK_ICONS, "columns-gap")

"One column of the page, as the layout places it"
struct PageColumn
  first::Int   # the lines of the page that show in it
  last::Int
  left::px     # how far its left edge is from the left edge of the page's text
  wide::px
  group::Int   # the place of its group among the page's groups of columns
end

"The columns that one `columns` block makes"
mutable struct ColumnGroup
  block::Int   # the line that opens the `columns` block
  top::px      # how far down the page the layout put the columns
  tall::px     # they're as tall as the tallest of them
end

"The columns of a page that are side by side, and what the layout does with them"
mutable struct PageColumns
  path::String                      # the page that they're the columns of
  columns::Vector{PageColumn}       # in the order of their lines
  groups::Vector{ColumnGroup}
  folds::Vector{Tuple{Int,Int,Bool}}   # the lines of each `columns` block that takes no room, and whether the caret is in them
  now::Union{Nothing,PageColumn}    # the column that the layout is in. The page's text is as wide as that column then.
  busy::Bool                        # a line of a column is being laid out, so `column_at` doesn't send it round again
  next::Int                         # the place in `columns` of the next column that the layout comes to
  from::Int                         # the first item of the column that the layout is in
  flows::Dict{Any,Any}              # the page's own layouts and its width, to put back after a column
  width::px
end

"The room between two columns of the page"
column_gap(e) = body(e).size * COLUMN_GAP

"Each `columns` block of the page, with the blocks that it puts in columns. They're found again when the page has changed."
column_groups(e) = begin
  b = e.buf
  get!(e.flows, (:column_groups, b.path, b.version)) do
    # A line that holds only a picture or a formula is a block by itself
    Columns.groups(b.lines, kinds(b), alone=i -> pictured(b, i) || maths_line(b, i))
  end
end

"""
The lines of a `columns` block that takes no room in the page, when line `i`
is one of them: the first and the last. Nothing for any other line. A block
that says how many columns takes no room. Nor do the empty lines after it, as
many of them as there are empty lines before it: the room that's left over the
columns is the room between two blocks of the page.
"""
column_fold(b::Buffer, i::Int) = begin
  b.view == :markdown || return nothing
  ks = kinds(b)
  j = i
  if ks[i].kind == Kind.blank
    # An empty line is one of them when the block is the first thing over it
    while j > 1 && ks[j].kind == Kind.blank
      j -= 1
    end
    (ks[j].kind == Kind.fence && ks[j].level == 1) || return nothing
  elseif !(ks[i].kind in (Kind.fence, Kind.code))
    return nothing
  end
  s, t = codeblock(b, j)
  (t > s && Columns.opens(ks[s]) && ks[t].kind == Kind.fence && ks[t].level == 1) || return nothing
  Columns.shares(@view b.lines[s+1:t-1]) === nothing && return nothing
  bare(k) = 1 <= k <= length(ks) && ks[k].kind == Kind.blank
  n = 0
  while bare(s - n - 1) && bare(t + n + 1)
    n += 1
  end
  i <= t + n ? (s, t + n) : nothing
end

"""
Find the columns of the page, before the layout: where each is across the
page, and how wide. A window that's too narrow has none. It also finds the
`columns` blocks that take no room. It's nothing when the page has neither. A
layout that failed in a column left the column's width behind, so the page's
own is put back first.
"""
page_columns!(e) = begin
  old = pop!(e.nodes, :columns, nothing)
  old !== nothing && old.now !== nothing && (e.flows = old.flows; empty!(e.flows))
  b = e.buf
  (b.view == :markdown && lowered(e) === nothing) || return nothing
  found = column_groups(e)
  isempty(found) && return nothing
  gap = column_gap(e)
  s = PageColumns(b.path, PageColumn[], ColumnGroup[], Tuple{Int,Int,Bool}[], nothing, false, 1, 0, e.flows, e.width)
  for g in found
    fold = column_fold(b, g.first)
    # With the caret in them, the lines of the block show
    fold === nothing || push!(s.folds, (fold..., !caretless(b) && all(p -> fold[1] <= p[1] <= fold[2], (b.caret, b.anchor))))
  end
  for g in (Columns.stacked(num(e.width), e.zoom) ? () : found)
    isempty(g.spans) && continue
    push!(s.groups, ColumnGroup(g.first, 0px, 0px))
    left = 0px
    # A group with fewer blocks than its number has room for the columns that it hasn't got
    for (k, wide) in enumerate(Columns.rooms(g.shares, num(e.width), num(gap))[1:length(g.spans)])
      lines = Columns.reach(g, k)
      push!(s.columns, PageColumn(first(lines), last(lines), left, px(wide), length(s.groups)))
      left += px(wide) + gap
    end
  end
  isempty(s.columns) && isempty(s.folds) && return nothing
  e.nodes[:columns] = s
end

"True when `it`, an item that the layout just made, is of a `columns` block that takes no room: the block, or an empty line after it"
folded(s::PageColumns, e, it::Item) = begin
  k = findfirst(f -> f[1] <= it.first <= f[2], s.folds)
  k === nothing && return false
  # With the caret in the block, the block is lines of code, which show
  it.content isa Live && return it.content.node isa ColumnsView
  it.content isa Flow && kinds(e.buf)[it.first].kind == Kind.blank && !s.folds[k][3]
end

"An item that takes no room, in the place of `it`"
flat(e, it::Item) = Item(it.first, it.last, it.top, 0px, Flow([VLine(Seg[], 0px, 0, 0, 0px, 0px)], 0px, body(e).size, 0px, 0px, Kind.blank, false))

"The column that line `i` of the page shows in, or nothing"
column_at(e, i::Int) = begin
  s = get(e.nodes, :columns, nothing)
  # Another page can show before the next layout finds its columns
  (s === nothing || s.busy || s.path != e.buf.path) && return nothing
  for c in s.columns
    c.first > i && break
    i <= c.last && return c
  end
  nothing
end

"How far the left edge of `it` is from the left edge of the page's text, and how wide it is: its column's, or the page's"
item_room(e, it::Item) = (c = column_at(e, it.first); c === nothing ? (0px, e.width) : (c.left, c.wide))

"The layouts of the lines of a column that's as wide as `c`, kept apart from those of the page's own width"
column_cache(s::PageColumns, c::PageColumn) = get!(() -> Dict{Any,Any}(), s.flows, (:column, c.wide))

"Do `f` while the page's text is as wide as the column `c`, so that what `f` lays out and describes fits the column"
in_column(f, e, s::PageColumns, c::PageColumn) = begin
  width, flows = e.width, e.flows
  e.width, e.flows = c.wide, column_cache(s, c)
  try
    f()
  finally
    e.width, e.flows = width, flows
  end
end

"`f` moved `dx` to the right. A line of a column is placed at the column's left edge."
shifted(f::Flow, dx::px) = dx == 0px ? f :
  Flow([VLine([Seg(s.text, s.col, s.n, s.face, s.atomic, s.link, s.x + dx, s.w, s.node) for s in vl.segs], vl.x + dx, vl.from, vl.to, vl.top, vl.high)
        for vl in f.lines], f.lh, f.size, f.above, f.below, f.kind, f.raw)
shifted(g::Grid, dx::px) = dx == 0px ? g : Grid(g.rows, g.widths, g.heights, g.cells, g.flows, g.head, g.left + dx, g.values)
shifted(content, dx::px) = content   # a sheet and a component have no place across the page of their own

"Line `i` of the page, which is in the column `c`, laid out for the column's width and placed at its left edge"
column_flow(e, c::PageColumn, i::Int, raw::Bool) = begin
  s = e.nodes[:columns]
  s.busy = true
  f = try
    # The layout of the page is in the column already. Anything else that asks is at the page's own width.
    s.now === c ? flow(e, i, raw) : in_column(() -> flow(e, i, raw), e, s, c)
  finally
    s.busy = false
  end
  shifted(f, c.left)
end

"""
The layout has come to line `i` of the page, and `top` is how far down the page
it has got. This says how far down the page line `i` goes. After a `columns`
block, line `i` goes where the block was, because the block takes no room. At
the first line of a column, the page's text becomes as wide as the column, and
the line goes level with the top of the group's first column. After the last line of a
column, the page's text gets its own width back. After the last column of a
group, the page goes on under the tallest column.
"""
column_turn!(s::PageColumns, e, items::Vector{Item}, i::Int, top::px) = begin
  # A `columns` block takes no room, so the item that was just made for it goes flat, and line `i` takes its place
  if !isempty(items) && last(items).tall > 0px && folded(s, e, last(items))
    items[end] = flat(e, last(items))
    top = last(items).top
  end
  c = s.now
  if c !== nothing && i > c.last
    g = s.groups[c.group]
    g.tall = max(g.tall, top - g.top)
    e.width, e.flows = s.width, s.flows
    s.now = nothing
    # A table is placed at the column's left edge, as each line of text was when it was laid out
    for k in s.from:length(items)
      it = items[k]
      it.content isa Grid && (items[k] = Item(it.first, it.last, it.top, it.tall, shifted(it.content, c.left)))
    end
    ends = s.next > length(s.columns) || s.columns[s.next].group != c.group
    ends && (top = g.top + g.tall)
  end
  if s.now === nothing && s.next <= length(s.columns) && i >= s.columns[s.next].first
    c = s.columns[s.next]
    g = s.groups[c.group]
    (s.next == 1 || s.columns[s.next-1].group != c.group) && (g.top = top; g.tall = 0px)
    s.next += 1
    s.now, s.from = c, length(items) + 1
    e.width, e.flows = c.wide, column_cache(s, c)
    top = g.top
  end
  top
end

"How far down the page the lowest of `items` ends. In a group of columns, that's the end of the tallest column."
lowest(e, items) = haskey(e.nodes, :columns) ? maximum(it -> it.top + it.tall, items) : last(items).top + last(items).tall

"The first and the last of the items `lo` to `hi` of the page, with the whole of each group of columns that they're part of"
whole_groups(e, items, lo::Int, hi::Int) = begin
  first_of(k) = (c = column_at(e, items[k].first); c === nothing ? nothing : c.group)
  while lo > 1 && first_of(lo) !== nothing && first_of(lo - 1) == first_of(lo)
    lo -= 1
  end
  while hi < length(items) && first_of(hi) !== nothing && first_of(hi + 1) == first_of(hi)
    hi += 1
  end
  (lo, hi)
end

"""
The place in the page's layout of the item under a point that's `dx` across
and `dy` down from the top left corner of the page's text. Beside a group of
columns and between two of them, it's an item of the column that the point is
in or after. Under a column that's shorter than its group, it's the column's
last item.
"""
item_under(e, dx::px, dy::px) = begin
  items = e.layout
  k = something(findlast(it -> it.top <= dy, items), 1)
  s = get(e.nodes, :columns, nothing)
  s === nothing && return k
  g = findfirst(g -> g.top <= dy < g.top + g.tall, s.groups)
  g === nothing && return k
  mine = [c for c in s.columns if c.group == g]
  c = mine[something(findlast(c -> c.left <= dx, mine), 1)]
  lo = findfirst(it -> it.first >= c.first, items)
  hi = findlast(it -> it.first <= c.last, items)
  (lo === nothing || hi === nothing || hi < lo) && return k
  lo - 1 + something(findlast(it -> it.top <= dy, view(items, lo:hi)), 1)
end

"""
The parts of the page that `items` show, as the document holds them: one under
another, with the columns of a group side by side. Each column describes its
blocks while the page's text is as wide as the column.
"""
page_parts(d::Document, e, items) = begin
  parts(run) = Any[x isa Item ? describe(e, x) : x for x in blocks(d, run)]
  s = get(e.nodes, :columns, nothing)
  s === nothing && return parts(items)
  out, run = Any[], Item[]
  k, n = 1, length(items)
  while k <= n
    c = column_at(e, items[k].first)
    if c === nothing
      push!(run, items[k])
      k += 1
      continue
    end
    append!(out, parts(run))
    empty!(run)
    group, columns = c.group, Any[]
    while k <= n && c !== nothing && c.group == group
      mine = Item[]
      while k <= n && items[k].first <= c.last
        it = items[k]
        # Its text is drawn from the column's own left edge
        push!(mine, Item(it.first, it.last, it.top, it.tall, shifted(it.content, -c.left)))
        k += 1
      end
      push!(columns, in_column(() -> Column(fixed(c.wide), Alignment.Start, name="Column", parts(mine)...), e, s, c))
      c = k <= n ? column_at(e, items[k].first) : nothing
    end
    push!(out, Row(width(grow=grow), Alignment.Start, child_gap=column_gap(e), name="Columns", columns...))
  end
  append!(out, parts(run))
  out
end

"""
The place on line `j` that ↑ or ↓ takes the caret to from line `from`, with `x`
as far across the page as the caret tries to stay. It's nothing when `j` isn't
a line of the page. It follows the rules of `line_step`: the caret steps over
a line that doesn't show, and goes onto a part like a picture as a whole.
"""
land(e, j::Int, by::Int, x::px, from::Int) = begin
  b = e.buf
  if rich(b)
    j = step_over(b, j, by, from)
    1 <= j <= length(b.lines) || return nothing
    free(b, j, from) || return (j, 0)
  end
  1 <= j <= length(b.lines) || return nothing
  into = item(e, j)
  into.content isa Sheet && return enter(e, into, into.content, by, x - item_room(e, into)[1])
  # A line of text shows little of its markup as plain text, so it's laid out as it reads
  f = flow(e, j, b.plain && !by_runs(b, j))
  (j, colat(f, by < 0 ? length(f.lines) : 1, x))
end

"""
The place one line up or down the screen from the caret. ↑ and ↓ stay in a
column of the page: they go through its blocks, and leave the group of columns
from the column's first and last line. Into a group, they go to the column
that's under the caret.
"""
vertical(e, by::Int) = begin
  p = line_step(e, by)
  s = get(e.nodes, :columns, nothing)
  s === nothing && return p
  b = e.buf
  i = b.caret[1]
  from, to = column_at(e, i), column_at(e, p[1])
  from == to && return p
  x = something(e.goal, 0px)
  if from !== nothing
    # In a table, the caret keeps its place across its cell. Out of the table it keeps its place across the page,
    # so that it comes back into the column that it left.
    it = item(e, i)
    at = it.content isa Grid ? gridcell(it.content, b.caret) : nothing
    at === nothing || (x = e.goal = cell_origin(it.content, at...)[1] + spot(it.content.flows[at[1]][at[2]], b.caret[2])[2])
    # Out of a column: only the line above the group or the line under it is next, not another column's
    (to === nothing || to.group != from.group) && return p
    mine = [c for c in s.columns if c.group == from.group]
    j = by > 0 ? last(mine).last + 1 : first(mine).first - 1
    return something(land(e, j, by, x, i), b.caret)
  end
  # Into a group: the column that the caret is over
  mine = [c for c in s.columns if c.group == to.group]
  c = mine[something(findlast(c -> c.left <= x, mine), 1)]
  something(land(e, by > 0 ? c.first : c.last, by, x, i), p)
end

"""
The view of a `columns` block. A block that says how many columns shows
nothing, and the layout gives it no room. One that doesn't say shows a faint
line with words that say how to write it.
"""
@def mutable struct ColumnsView <: SemanticUI
  n::Int = 0                                       # its place among the page's `columns` blocks
  first::Int = 0                                   # the lines of its block, when the page was last laid out
  last::Int = 0
  shares::Union{Nothing,Vector{Float64}} = nothing   # the share of each column, or nothing when the block doesn't say
  lines::Vector{String} = String[]                 # the lines that `shares` was read from
  parts::Dict{Any,Any} = Dict{Any,Any}()
end

reread!(v::ColumnsView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.shares = Columns.shares(lines)
  v
end

"What the line of a block that doesn't say how many columns says"
const COLUMN_WORDS = "Columns: write how many in the block, like 3"

# The block is a thin strip of the page. Its line and its words are drawn over the room above and below it.
describe(v::ColumnsView) = Box(width(grow=grow), height(COLUMN_MARK))
cursor(::ColumnsView) = :arrow

draw(ctx, size, ui::ConcreteRect, v::ColumnsView) = begin
  v.shares === nothing || return nothing   # a block that's right shows nothing
  e = editor(v)
  face = Face(SANS, "", body(e).size * 0.62, colours.dim, false)
  x, y = num(ui.left), num(ui.top)
  rectangle(ctx, ui.left, ui.top, ui.width, 1px, background=colours.line, border=0px)
  # The words stand on the line, at its left end, with a picture of two columns before them
  side = num(face.size)
  wide = side * 1.35 + num(measure(face, COLUMN_WORDS)) + 8
  rectangle(ctx, ui.left, ui.top - px(side), px(wide), px(2side), background=colours.bg, border=0px)
  round_box(ctx, x, y - side * 0.42, side * 0.4, side * 0.84, 1.5, line=face.color)
  round_box(ctx, x + side * 0.55, y - side * 0.42, side * 0.4, side * 0.84, 1.5, line=face.color)
  write_ink(ctx, COLUMN_WORDS, x + side * 1.35, y + num(capital(face)) / 2, face)
  nothing
end

"""
The columns of the page for a page of HTML: for each group, the first line, the
last line and the share of each column. A column that the group has no block
for has no lines, and keeps its room.
"""
html_columns(e) = map(filter(g -> !isempty(g.spans), column_groups(e))) do g
  map(eachindex(g.shares)) do k
    k <= length(g.spans) || return (last(g.spans[end]) + 1, last(g.spans[end]), g.shares[k])
    (first(Columns.reach(g, k)), last(Columns.reach(g, k)), g.shares[k])
  end
end

# In a page of HTML the block itself is nothing: its columns are there
columns_html(e, v::ColumnsView) = v.shares === nothing ? nothing : ""

# The language `column` means the same as `columns`
foreach(lang -> BLOCKS[lang] = BlockKind("Columns", "columns-gap", ColumnsView, columns_html), Columns.LANGS)

# --- a list of what was found in the pages of a folder -----------------------------------------
#
# A code block in the language `find` lists the lines that match in every page
# of a folder: every to-do item that isn't ticked, say, or each line that has
# some words. find.jl says how the block is written. The list has the name of
# each page over that page's lines. A click on a line opens its page at that
# line. A click on the box of a to-do item ticks it in its own page. If that
# page isn't open, or is open with nothing to save, Ladder writes the tick to
# the page's file at once. An item that you tick stays in the list, ticked,
# until another page shows.
#
# The top of the list changes what it asks for, so the block's lines needn't
# be seen: a field for the words that a line must have, a button that opens a
# list of the kinds of thing to list, and one that opens a list of the folders
# when the page has folders beside it. Each of the two lists floats under its
# button, as the takeoff's list of units does, with a field at its top that
# searches it. The kinds are those of find.jl: the kinds of line, and each
# kind of block, which is listed by the heading that it's under. Each change
# goes into the block's lines. Under them, a line says
# what the list is of and where it looked. It counts only the lines that
# match, not the items that were ticked here.

const FIND = Searches.FIND
const FIND_MOST = 200     # the most lines that a list shows
const FIND_PAGES = 3000   # the most pages that a list reads
const FIND_EVERY = 3      # seconds between two looks at the folder, while the window is drawn
const FIND_BUDGET = 0.3   # seconds that one look at the folder can take
const FIND_BAR = 440px     # the room that the top of a list needs to show its field and its buttons in one row
const FIND_MENU = :find_choices   # the key of the list that a button at the top opens
const MOST_CHOICES = 8     # the rows that such a list shows before it scrolls
push!(BLOCK_ICONS, "search", "file-earmark-text", "folder", "code-slash")

"What a `find` block shows: the lines of a folder's pages that match"
@def mutable struct SearchView <: SemanticUI
  n::Int = 0                               # its place among the page's lists
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Searches.Query = Searches.Query()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  shown::Any = nothing                     # what the list was last worked out for, and what it found
  kept::Vector{Searches.Match} = Searches.Match[]   # the items whose box was clicked here. They stay in the list.
  pages::Dict{String,Any} = Dict{String,Any}()      # what was found in each page, and the mark of the page's text then
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its rows, kept between frames
  asking::Any = nothing                    # what the list that floats under a button chooses: :kind or :folder, or nothing when none shows
  rows::Vector{Any} = Any[]                # the rows of that list that have the words in its field
  pick::Int = 1                            # the row of them that Return takes
  typed::String = ""                       # the words in its field when the rows were last worked out
  back::Bool = false                       # the field for the words to find had the keyboard when it opened, and gets it back
end

"""
A button at the top of a list that shows what the list asks for now. A click
opens a list of the others. One chooses the kind of thing that the list is
of, and one chooses the folder that it looks in.
"""
@def mutable struct SearchChoice <: SemanticUI
  of::Any = nothing     # the list
  what::Symbol = :kind  # :kind or :folder
end
"The list that floats under such a button, with a field that searches it. It's the takeoff's list of units, with other rows."
@def mutable struct ChoiceMenu <: SemanticUI
  of::Any = nothing        # the list that it changes
  button::Any = nothing    # the button that it's under
  side::Symbol = :bottom   # the side of the button that it's on
  pick::Int = 0            # the row that was picked when it was last drawn. A row that the keys pick is brought in sight.
end
"A row of that list: a kind of thing to list, or a folder"
@def mutable struct ChoiceRow <: SemanticUI
  of::Any = nothing
  k::Int = 0
end

"The name of a page, over the lines of that page in the list"
@def mutable struct SearchPage <: SemanticUI
  of::Any = nothing
  path::String = ""
end
"A line of the list"
@def mutable struct SearchRow <: SemanticUI
  of::Any = nothing
  i::Int = 0
  box::Any = nothing   # its SearchTick
end
"The box of a to-do item in the list. A click ticks the item in its own page."
@def mutable struct SearchTick <: SemanticUI
  of::Any = nothing    # the row
end

"The text field at the top of a list. It holds the words that a line must have."
search_input(v::SearchView) = block_part!(v, :input) do
  TextInput(placeholder="Words to find", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

reread!(v::SearchView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Searches.query(lines)
  v.shown = nothing
  empty!(v.pages)
  # The field shows the words that the block has, as it does after ⌘Z takes some of them back.
  # A space that was just typed after a word stays in the field.
  i = search_input(v)
  split(i.text) == v.data.with || (i.text = join(v.data.with, " "); i.anchor = i.cursor = length(i.text))
  v
end

"Write what the list asks for into the lines of its block, and work the list out again"
ask!(v::SearchView; typing=false) = begin
  v.shown = nothing
  empty!(v.pages)
  write_block!(v, FIND, Searches.written(v.data); typing)
end

"""
What happens to a list in each frame, before the page is laid out: the words
that were typed in its field are written into its block. The words make the
list shorter. They don't change the kind of line that it lists.
"""
block_tick!(v::SearchView) = begin
  choosing_tick!(v)
  words = String.(split(search_input(v).text))
  q = v.data
  words == q.with && return v
  q.what === nothing && (q.what = Searches.kind(q))
  q.with = words
  ask!(v, typing=true)
end

"The folders that the list can look in: the folders beside the page, and the one that the block names now"
search_folders(v::SearchView) = begin
  dir = docdir(editor(v))
  found = isdir(dir) ? sort!([f for f in readdir(dir) if !startswith(f, '.') && f != "node_modules" && isdir(joinpath(dir, f))], by=lowercase) : String[]
  folder = v.data.folder
  isempty(folder) || folder in found || pushfirst!(found, folder)
  found
end

"Look in the folder `name` beside the page, or in the page's own folder when `name` is empty"
look_in!(v::SearchView, name) = (v.data.folder = String(name); ask!(v))

"List things of the kind `kind`, one of the kinds of find.jl, like :todo or :takeoff"
list_kind!(v::SearchView, kind) = (v.data.what = kind; ask!(v))

"What the button `c` says: the kind of thing that its list is of now, or the folder that the list looks in"
choice_words(c::SearchChoice) = begin
  q = c.of.data
  c.what == :folder ? (isempty(q.folder) ? "This folder" : q.folder) : Searches.title(Searches.kind(q))
end

describe(c::SearchChoice) =
  Row(height(26px), padding(9px, 0px), child_gap=6px, radius(6px), Alignment.Center, name="Menu",
      border(1px, :solid, c.of.asking == c.what ? colours.accent : colours.line), background(ishovered(c) ? colours.hover : colours.bg),
    (c.what == :folder ? (Icon("folder", size=13px, color=colours.dim),) : ())...,
    Box(label(choice_words(c), 12px)), Icon("chevron-down", size=9px, color=colours.dim))

cursor(::SearchChoice) = :hand
onkey(c::SearchChoice, ev::KeyPress{Keys.mouse_left}) = open_choices!(c, ev.window)

# --- the list that a button at the top opens -----------------------------------------------
#
# A click on a button shows its list under it: every kind of thing that a
# `find` block can list, or the page's own folder and the folders beside it.
# The keyboard goes to the field at the top of the list, and the list keeps
# the rows that have every word typed there. A kind is found by any of the
# names that a block can give it, so "tasks" finds To-do items. The up and
# down arrows pick a row, and so does the mouse. Return or a click takes it.
# Esc, or a click somewhere else, closes the list and changes nothing.

"The field at the top of the list that a button opens"
choice_input(v::SearchView) = block_part!(v, :filter) do
  TextInput(placeholder="Filter…", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"""
Every row of the list that the button for `what` opens. A row has its `key`,
which is the kind or the folder that goes into the block, the `name` that it
shows, and the `words` that find it.
"""
choice_rows(v::SearchView, what::Symbol) = begin
  what == :kind && return Any[(key=k, name=Searches.title(k), words=[Searches.WHATS[k].names..., Searches.WHATS[k].langs...]) for k in keys(Searches.WHATS)]
  Any[(key="", name="This folder", words=["this folder"]); [(key=f, name=f, words=[f]) for f in search_folders(v)]]
end

"True when the row `r` has every one of the words in `typed`"
choice_matches(r, typed::AbstractString) = all(w -> any(h -> occursin(w, lowercase(h)), r.words), split(lowercase(typed)))

"True when the row `r` is what the list of `v` asks for now"
chosen(v::SearchView, r) = r.key isa Symbol ? r.key == Searches.kind(v.data) : r.key == v.data.folder

"Show the list of the button `c` under it, with the keyboard in its field"
open_choices!(c::SearchChoice, window) = begin
  v = c.of
  stop_choosing!(v)
  input = choice_input(v)
  input.color = colours.ink
  input.text = ""
  input.anchor = input.cursor = 0
  v.back = window.focus === search_input(v)
  v.asking, v.typed = c.what, ""
  v.rows = choice_rows(v, c.what)
  v.pick = something(findfirst(r -> chosen(v, r), v.rows), 1)
  focus(input)
  menu = ChoiceMenu(of=v, button=c)
  v.parts[:menu] = menu
  popup!(window, menu, anchor=c, placement=:bottom, gap=9px, width=230px, key=FIND_MENU,
         onclose=() -> stop_choosing!(v), theme=component_theme(editor(v).zoom))
  handled
end

"Take the list of a button away. The keyboard goes back to the field that had it, or to the page."
stop_choosing!(v::SearchView) = begin
  v.asking === nothing && return handled
  v.asking = nothing
  v.rows = Any[]
  w = window_of(v)
  w === nothing && return handled
  close_popup!(w, FIND_MENU)
  w.focus === choice_input(v) && focus(v.back ? search_input(v) : editor(v))
  handled
end

"Take row `k` of the list that shows: the list of `v` is of that kind, or it looks in that folder"
choose!(v::SearchView, k::Int) = begin
  (v.asking !== nothing && k in eachindex(v.rows)) || return stop_choosing!(v)
  what, key = v.asking, v.rows[k].key
  stop_choosing!(v)
  what == :kind ? list_kind!(v, key) : look_in!(v, key)
  handled
end

"""
What happens in each frame to the list that a button opened: it closes when a
click somewhere else took the keyboard from its field, and it keeps the rows
that have the words in the field. New words pick the row whose name starts
with them, or the first row.
"""
choosing_tick!(v::SearchView) = begin
  v.asking === nothing && return
  w = window_of(v)
  (w === nothing || w.focus !== choice_input(v)) && return stop_choosing!(v)
  typed = String(strip(choice_input(v).text))
  typed == v.typed && return
  v.typed = typed
  v.rows = filter!(r -> choice_matches(r, typed), choice_rows(v, v.asking))
  v.pick = something(findfirst(r -> startswith(lowercase(r.name), lowercase(typed)), v.rows), 1)
end

describe(r::ChoiceRow) = begin
  v = r.of
  r.k <= length(v.rows) || return Box(height(0px))
  row = v.rows[r.k]
  float_row(row.name, get(row, :short, ""), picked=v.pick == r.k, on=chosen(v, row))
end

cursor(::ChoiceRow) = :hand
# ⌘-click on a table in a chart's list adds it to the tables that the chart draws, or takes it away
onkey(r::ChoiceRow, ev::KeyPress{Keys.mouse_left}) = r.of isa SourceChooser && only_held(ev, Keys.cmd) ? toggle_source!(r.of, r.k) : choose!(r.of, r.k)
# The mouse picks the row that it's over, as the arrow keys do
onmouse(r::ChoiceRow, ::MouseMove) = begin
  v = r.of
  v.pick = r.k
  menu = get(v.parts, :menu, nothing)
  menu === nothing || (menu.pick = r.k)   # it's in sight already, so the list doesn't scroll to it
  handled
end

describe(m::ChoiceMenu) = begin
  v = m.of
  n, high = length(v.rows), FLOAT_ROW
  scroll = get!(() -> Scroll(width(grow=grow)), v.parts, :choice_scroll)
  body = if n == 0
    float_none(v.asking == :folder ? "No folder has that name" : "Nothing has that name")
  else
    # Half a row at the bottom says that the list goes on
    scroll.height = height(n <= MOST_CHOICES ? n * high : MOST_CHOICES * high - high / 2)
    m.pick == v.pick || (m.pick = v.pick; scroll_into_view!(scroll, high * (v.pick - 1), high * v.pick))
    reuse!(scroll, Column(width(grow=grow), Alignment.Start, [block_part!(() -> ChoiceRow(of=v, k=k), v, (:choice_row, k)) for k in 1:n]...))
  end
  float_list(choice_input(v), body, name="Choices")
end

placed!(m::ChoiceMenu, side) = (m.side = side; nothing)
draw(ctx, size, ui::ConcreteRect, m::ChoiceMenu) = caret(ctx, ui, m.side, rect(m.button))

# The list sees a key before its field does. The arrows pick a row, Return takes it, and Esc closes the list.
onkey(m::ChoiceMenu, ev::KeyPress{Keys.enter}) = unmodified(ev) ? choose!(m.of, m.of.pick) :
  m.of isa SourceChooser && only_held(ev, Keys.cmd) ? toggle_source!(m.of, m.of.pick) : nothing   # ⌘Return adds the table, as ⌘-click does
onkey(m::ChoiceMenu, ev::KeyPress{Keys.escape}) = unmodified(ev) ? stop_choosing!(m.of) : nothing
onkey(m::ChoiceMenu, ev::KeyPress{Keys.down}) = unmodified(ev) ? (v = m.of; v.pick = min(v.pick + 1, max(1, length(v.rows))); handled) : nothing
onkey(m::ChoiceMenu, ev::KeyPress{Keys.up}) = unmodified(ev) ? (v = m.of; v.pick = max(v.pick - 1, 1); handled) : nothing

# Return in the field gives the keyboard back to the page
onkey(v::SearchView, ev::KeyPress{Keys.enter}) = unmodified(ev) ? (focus(editor(v)); handled) : nothing

"""
The Markdown files in `folder`, then those of each folder in it, in the order
of their names, and whether that's all of them. A folder whose name starts
with a dot is left out. A folder with a great many files in it, like a whole
disk, is read for a part of a second only, so that the window doesn't stop.
"""
pages_under(folder; budget=FIND_BUDGET) = begin
  out, whole, started = String[], true, time()
  for (root, dirs, files) in walkdir(folder, onerror=_ -> nothing)
    filter!(d -> !startswith(d, '.') && d != "node_modules", dirs)
    sort!(dirs, by=lowercase)
    append!(out, (joinpath(root, f) for f in sort(files, by=lowercase) if ismarkdown(f) && !startswith(f, '.')))
    (length(out) > FIND_PAGES || time() - started > budget) && (whole = false; break)
  end
  first(out, FIND_PAGES), whole
end

# What each folder that a list looks in held when it was last read: its pages, with when each file last changed
const FOLDER_PAGES = Dict{String,Any}()

"""
The pages of `folder`, with when the file of each last changed. The folder is
read again after a few seconds, and after longer when reading it takes long.
"""
folder_pages(folder) = begin
  kept = get(FOLDER_PAGES, folder, nothing)
  kept !== nothing && time() < kept.next && return kept
  started = time()
  pages, whole = pages_under(folder)
  found = [(path, mtime(path)) for path in pages]
  FOLDER_PAGES[folder] = (next=time() + max(FIND_EVERY, 20 * (time() - started)), read=started, pages=found, whole=whole)
end

# The text of each page that a list has read, with when the file last changed, so a file is read again only when it changes
const PAGE_TEXTS = Dict{String,Tuple{Float64,Vector{String},Vector{Line}}}()

"""
The lines of the page at `path`, what each line is, and a mark that changes
when the page's text does. A page that's open gives its text as it is now,
with the changes that aren't saved. `at` is when the page's file last changed.
"""
page_text(e, path, at) = begin
  b = get(e.buffers, path, nothing)
  b !== nothing && !readonly(b) && return b.lines, kinds(b), (:open, b.version)
  kept = get(PAGE_TEXTS, path, nothing)
  kept !== nothing && kept[1] == at && return kept[2], kept[3], at
  lines = filesize(path) > 2_000_000 ? String[] : try text(path) catch; String[] end
  length(PAGE_TEXTS) > 2FIND_PAGES && empty!(PAGE_TEXTS)
  PAGE_TEXTS[path] = (at, lines, classify(lines))
  lines, PAGE_TEXTS[path][3], at
end

"The folder that the list looks in"
search_folder(e, q::Searches.Query) = isempty(q.folder) ? docdir(e) : abspath(joinpath(docdir(e), expanduser(q.folder)))

"""
What the list shows: the lines that match, page by page, whether every page of
the folder was read, and why there are no lines when the folder can't be read.
It's worked out again when a page changes in Ladder, and when the folder is
read again. Only the pages that changed are looked through again.
"""
found!(v::SearchView) = begin
  e = editor(v)
  q = v.data
  folder = search_folder(e, q)
  listed = isdir(folder) ? folder_pages(folder) : nothing
  # ⌘Z gives a page the version that it had before, so the version of each open page is looked at, not only the newest one
  key = (v.lines, hash([b.version for b in values(e.buffers)]), listed === nothing ? 0.0 : listed.read, folder, length(v.kept))
  v.shown !== nothing && v.shown[1] == key && return v.shown[2]
  listed === nothing && return (v.shown = (key, (matches=Searches.Match[], whole=true, problem="There's no folder called “$(q.folder)” beside this page.")))[2]
  every, kept = Searches.Match[], Searches.Match[]
  for (path, at) in listed.pages
    lines, ks, mark = page_text(e, path, at)
    had = get(v.pages, path, nothing)
    ms = had !== nothing && had[1] == mark ? had[2] : (v.pages[path] = (mark, Searches.matches(q, path, lines, ks)))[2]
    # An item whose box was clicked here stays in the list, though it no longer matches
    for k in v.kept
      k.path == path || continue
      i = Searches.locate(k, lines, ks)
      i === nothing && continue
      push!(kept, Searches.Match(path, i, k.text, k.kind))
      any(m -> m.line == i, ms) || (ms = sort!([ms; kept[end]], by=m -> m.line))
    end
    append!(every, ms)
  end
  v.kept = kept
  key = (key[1:4]..., length(v.kept))
  (v.shown = (key, (matches=every, whole=listed.whole, problem="")))[2]
end

"The name of the page at `path` as the list shows it: where it is in the list's folder, without the end of its file's name"
page_name(v::SearchView, path) = splitext(relpath(path, search_folder(editor(v), v.data)))[1]

describe(p::SearchPage) =
  Row(width(grow=grow), height(30px), padding(12px, 0px), child_gap=7px, Alignment.Center, name="Page",
    Icon("file-earmark-text", size=13px, color=colours.dim),
    Box(label(page_name(p.of, p.path), 12.5px, color=ishovered(p) ? colours.accent : colours.ink, weight="Semibold")), Box(width(grow=grow)))

describe(t::SearchTick) = begin
  row = t.of
  ms = found!(row.of).matches
  done = row.i <= length(ms) && ms[row.i].kind == :done
  side = 15px
  Box(fixed(side), height(side), radius(4px), Alignment.Center, justify=Alignment.Center,
      (done ? (background(colours.accent),) : (border(1.5px, :solid, ishovered(t) ? colours.accent : colours.marker),))...,
      (done ? (Icon("check", size=13px, color=colours.bg),) : ())...)
end

describe(r::SearchRow) = begin
  ms = found!(r.of).matches
  r.i <= length(ms) || return Box(height(0px))
  m = ms[r.i]
  r.box === nothing && (r.box = SearchTick(of=r); setfield!(r.box, :parent, r))
  boxed = m.kind in (:todo, :done)
  Row(width(grow=grow), padding(4px, 12px, 4px, 31px), child_gap=9px, Alignment.Start, name="Found", background(ishovered(r) ? colours.hover : clear),
    (boxed ? (Box(padding(0px, 1px, 0px, 0px), r.box),) : ())...,
    # A block has the icon of its kind, as it has in the sidebar
    (Searches.isblock(m.kind) ? (Box(padding(0px, 2px, 0px, 0px), Icon(block_icon(m.kind), size=13px, color=colours.dim)),) : ())...,
    Box(width(grow=grow), Text(m.text, size=13.5px, family=SANS, subfamily=m.kind == :heading ? "Semibold" : "",
                               color=m.kind == :done ? colours.dim : colours.ink, wrap=WrapMode.words)))
end

cursor(::Union{SearchPage,SearchRow,SearchTick}) = :hand
cursor(::SearchView) = :arrow

"The icon of the kind of block `kind`, one of the kinds of find.jl. It's the one that the sidebar shows beside such a block."
block_icon(kind::Symbol) = begin
  kind == :code && return "code-slash"
  lang = first(Searches.WHATS[kind].langs)
  lang == TAKEOFF ? "rulers" : lang == SCHEDULE ? "bar-chart-steps" : lang == SHEET ? "calculator" : lang == SPREADSHEET ? "grid-3x3" :
  lang == DIAGRAM ? "diagram-3" : haskey(BLOCKS, lang) ? BLOCKS[lang].icon : "puzzle"
end

"""
Show the page at `path`, with the caret at the end of the line that `m` is on
now. For a block that shows as a component, the caret goes to the line under
it: in the block, it would show the block's lines.
"""
visit!(e, path, m=nothing) = begin
  path == e.buf.path || open!(e, path)
  focus(e)
  m === nothing && return handled
  b = e.buf
  i = Searches.locate(m, b.lines, kinds(b))
  i === nothing && return handled
  Searches.isblock(m.kind) || return show_line!(e, i)
  under = last(Searches.block_span(kinds(b), i)) + 2
  show_line!(e, m.kind == :code ? min(i + 1, length(b.lines)) : min(under, length(b.lines)))
end

onkey(p::SearchPage, ::KeyPress{Keys.mouse_left}) = visit!(editor(p.of), p.path)
onkey(r::SearchRow, ::KeyPress{Keys.mouse_left}) = begin
  ms = found!(r.of).matches
  r.i <= length(ms) ? visit!(editor(r.of), ms[r.i].path, ms[r.i]) : handled
end

"""
Tick the to-do item `m` in its own page when `done` is true, or take its tick
away. A page that's open is changed as if you'd clicked the box there. If it
isn't the page that shows, and it had nothing to save, it's saved. A page
that isn't open is changed in its file. It's false when the item isn't there
any more, or its page can't be written.
"""
tick_page!(e, m::Searches.Match, done::Bool) = begin
  b = get(e.buffers, m.path, nothing)
  if b !== nothing && !readonly(b)
    i = Searches.locate(m, b.lines, kinds(b))
    i === nothing && return false
    clean = !dirty(b)
    tick_item!(b, i, done)
    b !== e.buf && clean && save!(b)
  else
    isfile(m.path) || return false
    lines = text(m.path)
    i = Searches.locate(m, lines)
    i === nothing && return false
    new, z = Repeats.tick(lines, i, done; today=calendar_today())
    splice!(lines, i:z, new)
    # A file that can't be written, like one of the pages that come with the app, stays as it is
    try write(m.path, join(lines, "\n")) catch; return false end
    empty!(FOLDER_PAGES)   # the folder is read again, so that a list has the file as it is now
  end
  true
end

"""
Tick the to-do item `m` of a list in its own page, or take its tick away: see
`tick_page!`. The item stays in the list until another page shows.
"""
tick_found!(v::SearchView, m::Searches.Match) = begin
  e = editor(v)
  done = m.kind != :done
  tick_page!(e, m, done) || return handled
  # The item stays in this list. A second click, which puts it back as it was, lets it go.
  now = Searches.Match(m.path, m.line, m.text, done ? :done : :todo)
  k = findfirst(x -> x.path == m.path && x.text == m.text && x.kind == m.kind, v.kept)
  k === nothing ? push!(v.kept, now) : (v.kept[k] = now)
  Searches.kind(v.data) == now.kind && filter!(x -> !(x.path == now.path && x.text == now.text), v.kept)
  v.shown = nothing
  handled
end

"The lists of the page that shows let go of the items that were ticked in them. `open!` does this when another page takes its place."
forget_ticked!(e) = for (key, v) in e.nodes
  v isa SearchView && key[3] == e.buf.path && !isempty(v.kept) && (empty!(v.kept); v.shown = nothing)
end

onkey(t::SearchTick, ::KeyPress{Keys.mouse_left}) = begin
  row = t.of
  ms = found!(row.of).matches
  row.i <= length(ms) ? tick_found!(row.of, ms[row.i]) : handled
end

"""
What the top of the list says: what it lists, how many lines match and where
it looks. An item that was ticked here stays in the list, but it no longer
matches, so it isn't counted.
"""
search_words(v::SearchView) = begin
  q = v.data
  own = [m for m in found!(v).matches if Searches.counted(q, m)]
  Searches.summary(q, length(own), length(unique(m.path for m in own)))
end

describe(v::SearchView) = begin
  e = editor(v)
  found = found!(v)
  ms = found.matches
  q = v.data
  with_theme(component_theme(e.zoom)) do
    input = search_input(v)
    input.color = colours.ink
    w = window_of(v)
    typing = w !== nothing && w.focus === input
    field = Row(width(grow=grow), height(26px), padding(8px, 0px), child_gap=7px, radius(6px), Alignment.Center, background(colours.bg),
                border(1px, :solid, typing ? colours.accent : colours.line),
                Icon("search", size=12px, color=colours.dim), Box(width(grow=grow), height(grow=grow), input))
    # The button for the folder shows only when there's another folder to choose
    menus = (block_part!(() -> SearchChoice(of=v, what=:kind), v, :kind),
             (isempty(search_folders(v)) ? () : (block_part!(() -> SearchChoice(of=v, what=:folder), v, :folder),))...)
    gap() = Box(width(4px))   # a new one each time: a box can be in the page only once
    bars = editor(v).width < FIND_BAR ?
           (block_bar(field), block_bar(menus[1], gap(), menus[2:end]..., Box(width(grow=grow)))) :
           (block_bar(field, gap(), menus[1], gap(), menus[2:end]...),)
    total = Row(width(grow=grow), padding(9px, 12px, 3px, 12px), Alignment.Start, Box(label(search_words(v), 12px, color=colours.dim)), Box(width(grow=grow)))
    isempty(found.problem) || return Column(block_look()..., clip=true, name="Found", bars..., block_note(found.problem))
    rows = Any[total]
    pages = 0
    for i in 1:min(length(ms), FIND_MOST)
      if i == 1 || ms[i-1].path != ms[i].path
        page = block_part!(() -> SearchPage(of=v), v, (:page, pages += 1))
        page.path = ms[i].path
        push!(rows, page)
      end
      push!(rows, block_part!(() -> SearchRow(of=v, i=i), v, (:row, i)))
    end
    length(ms) > FIND_MOST && push!(rows, block_note("And $(length(ms) - FIND_MOST) more. Add words to the block's with: line to list fewer."))
    found.whole || push!(rows, block_note("This folder has more pages than Ladder reads for a list. Name a folder in it with the block's in: line."))
    Column(block_look()..., clip=true, name="Found", bars..., rows..., Box(height(6px)))
  end
end

"The list as HTML: the name of each page, and its lines under it"
find_html(e, v::SearchView) = begin
  ms = found!(v).matches
  isempty(ms) && return "<p>$(escape(Searches.summary(v.data, 0, 0)))</p>"
  out = String[]
  for (i, m) in enumerate(ms)
    if i == 1 || ms[i-1].path != m.path
      i == 1 || push!(out, "</ul>")
      push!(out, "<p><strong>$(escape(page_name(v, m.path)))</strong></p>\n<ul style=\"list-style: none; padding-left: 0.5em\">")
    end
    push!(out, "<li>$(m.kind == :done ? "☑ " : m.kind == :todo ? "☐ " : "")$(escape(m.text))</li>")
  end
  join(out, "\n") * "\n</ul>"
end

BLOCKS[FIND] = BlockKind("Find", "search", SearchView, find_html)

# --- a gallery of a folder's files ------------------------------------------------------------
#
# A code block in the language `gallery` shows the files and the folders of a
# folder as a grid of small squares. gallery.jl says how the block is written.
# The square of a picture or a video shows the middle of its picture, cut to
# fit. The square of any other file shows the picture that the Finder has for
# it, like the first page of a PDF file, with the file's name under it. A
# folder shows the Finder's icon for it. The top of the block says how many
# files there are and where they are. A button there changes the size of the
# squares, and writes the size into the block.
#
#   - A click on a picture, a PDF file, a video or a 3D model makes it fill
#     the window, as the same file in the text does. There, ← and → go to the
#     file before it and the next one of the gallery that fill the window too,
#     ↑ and ↓ turn the pages of a PDF file, and Esc puts the page back.
#   - A click on a folder or another kind of file opens it, as a link to it
#     does.
#   - While a file fills the window, the bar under it says where it is in the
#     gallery, like "2 of 6", and the name of the file. A button on each side
#     of those words goes to the file before and to the next one. While the
#     mouse is near the left or the right edge of the window, a large arrow
#     shows there that does the same.
#   - The mouse over a square shows the name of its file.
#   - A file or a folder that's dropped on the gallery from the Finder is
#     copied into the gallery's folder. A gallery that only lists its files
#     gets a line for it, and the file stays where it is.
#
# A big folder mustn't stop the window. macOS makes a small picture of each
# file, as it does for the Finder, and Ladder asks for a few of them in each
# frame. Only the rows of the grid that are in the window are built. The
# folder is read again every few seconds while the window is drawn.

const GALLERY = Galleries.GALLERY
const GALLERY_KINDS = (PICTURES..., MAC_PICTURES...)   # the ends of the names of the files that a gallery shows as pictures
const GALLERY_EVERY = 3        # seconds between two looks at the folder, while the window is drawn
const GALLERY_BUDGET = 0.012   # seconds of a frame that making small pictures can take. One is always made.
const GALLERY_TOP = 38px       # how tall the line at the top of a gallery is
const GALLERY_PAD = 12px       # between the edge of a gallery and its pictures
const GALLERY_ROUND = 6px      # how round the corners of a square are
const GALLERY_EDGE = 44px      # how big the arrow is at an edge of the window, while a picture fills the window
const GALLERY_NEAR = 140       # px: the mouse is this near an edge of the window when that edge's arrow shows
const GALLERY_NAME = 200       # px: the most room that the name of a file has in the bar under a picture
const GALLERY_INSET = 6px      # between the edge of a square and the picture and the name in it, where the picture doesn't fill the square
const GALLERY_LABEL = 14px     # how tall the name under such a picture is
"For each size of square: the icon of the button that changes the size, and what the button says"
const GALLERY_SIZES = (small=("grid-3x3-gap", "Small"), medium=("grid", "Medium"), large=("square", "Large"))
push!(BLOCK_ICONS, "images", "image", "grid-3x3-gap", "grid", "square")

"What a `gallery` block shows: the files and the folders of a folder as a grid of squares"
@def mutable struct GalleryView <: SemanticUI
  n::Int = 0                               # its place among the page's galleries
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Galleries.Gallery = Galleries.Gallery()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  shown::Any = nothing                     # what the gallery showed when its folder was last read, and when to read it again
  # The small picture of each file: its key and whether it fills its square. It's nothing for a file that has no picture.
  small::Dict{Any,Any} = Dict{Any,Any}()
  wanted::Vector{Galleries.Item} = Galleries.Item[]   # the files in the window whose small pictures aren't made yet
  side::px = 0px                           # how big each square was when the grid was last laid out
  showing::String = ""                     # the file that fills the window, or that last did
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its squares, its button, and the player of the video that fills the window, kept between frames
end

"A square of a gallery: one file or folder"
@def mutable struct GalleryThumb <: SemanticUI
  of::Any = nothing
  i::Int = 0   # its place among the gallery's files
end

reread!(v::GalleryView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Galleries.gallery(lines)
  v.shown = nothing
  v
end

"True while the page is drawn for paper. `print_pdf` puts the caret on no line then."
on_paper(e) = e.buf.caret[1] == 0

"""
What the gallery shows: its files and folders, the lines that name nothing,
and why there's nothing to show. It leaves out the page that holds it. The
folder is read again after a few seconds, and after longer when reading it
takes long.
"""
found!(v::GalleryView) = begin
  e = editor(v)
  dir = docdir(e)
  key = (v.lines, dir)
  s = v.shown
  s !== nothing && s.key == key && time() < s.next && return s.found
  started = time()
  found = Galleries.items(v.data, dir, pictures=GALLERY_KINDS, skip=(e.buf.path,))
  v.shown = (key=key, next=time() + max(GALLERY_EVERY, 20 * (time() - started)), found=found)
  found
end

"Square `i` of the gallery: a file or a folder, or nothing when it has no such square"
item_at(v::GalleryView, i::Int) = get(found!(v).items, i, nothing)

"What the small picture of `p` is kept under: its file, when the file last changed, and how many pixels the squares need now"
small_mark(v::GalleryView, p) = (p.path, p.at, Galleries.pixels(num(v.side)))

"""
The small picture of `p`: its key, for drawing, and whether it fills the
square. It's nothing for a file that has no picture, and `missing` until it's made.
"""
small(v::GalleryView, p) = get(v.small, small_mark(v, p), missing)

"True when the picture of `p` fills its square: a picture's own, and the picture that macOS makes of a video"
fills_square(p) = p.kind == :picture || p.kind == :file && lowercase(splitext(p.path)[2]) in VIDEOS

"""
Make the small picture of `p`: the one that macOS makes for the Finder, like
the first page of a Pages document. A picture that macOS has none for shows
itself. A folder, and a file that has no picture, show the Finder's icon.
"""
small!(v::GalleryView, p) = begin
  mark = small_mark(v, p)
  key = thumbnail(p.path, mark[3])
  key === nothing && p.kind == :picture && (key = picture_key(p.path))
  fills = key !== nothing && fills_square(p)
  key === nothing && (key = finder_icon(p.path, mark[3]))
  v.small[mark] = key === nothing ? nothing : (key=key, fills=fills)
end

"""
Make the small pictures that the last frame had none for: as many as `budget`
seconds have room for, and one at the least. The next frame asks for the rest.
"""
make_small!(v::GalleryView; budget=GALLERY_BUDGET) = begin
  started = time()
  for p in v.wanted
    ismissing(small(v, p)) || continue
    small!(v, p)
    time() - started > budget && break
  end
  empty!(v.wanted)
  v
end

# In each frame, before the page is laid out, a gallery makes a few small pictures, so the window never waits long
block_tick!(v::GalleryView) = make_small!(v)

"""
The rows of the grid `g` that are in the window, and a few on each side of
them. On paper, every row shows.
"""
rows_in_view(v::GalleryView, g) = begin
  e = editor(v)
  on_paper(e) && return 1:g.rows
  _, h = window_size(e)
  k = findfirst(it -> it.content isa Live && it.content.node === v, e.layout)
  # A gallery that the page hasn't laid out yet is taken to be at the top of the window
  k === nothing && return Galleries.rows_between(0, num(h), g.rows, g.side)
  top = e.layout[k].top + LIVE_GAP + 1px + GALLERY_TOP   # of the grid, from the top of the page's text
  Galleries.rows_between(num(e.scroll.offset - PAGE_TOP - 200px - top), num(e.scroll.offset + h + 200px - top), g.rows, g.side)
end

describe(t::GalleryThumb) = begin
  v = t.of
  p = item_at(v, t.i)
  s = p === nothing ? missing : small(v, p)
  # A picture or a video fills its square, in `draw`
  (p === nothing || (s isa NamedTuple ? s.fills : ismissing(s) && fills_square(p))) &&
    return Box(fixed(v.side), height(v.side), radius(GALLERY_ROUND), name="Picture", background(colours.block))
  # Any other file has the whole of its picture in its square, with its name under it, as the Finder shows it
  wide, high = v.side - 2GALLERY_INSET, v.side - 2GALLERY_INSET - GALLERY_LABEL - 4px
  picture = if s isa NamedTuple
    image = image_source(s.key)
    _, _, w, h = Galleries.fit(image.width, image.height, num(wide), num(high))
    (Image(s.key, fixed(px(w)), height(px(h))),)
  elseif s === nothing
    # A file that has no picture at all has the icon of its kind
    (Icon(p.kind == :folder ? "folder" : file_icon(p.path), size=24px, color=colours.faint),)
  else
    ()   # its picture isn't made yet
  end
  Column(fixed(v.side), height(v.side), radius(GALLERY_ROUND), padding(GALLERY_INSET), child_gap=4px, Alignment.Center, name="Picture",
         background(colours.block),
    Box(fixed(wide), height(high), Alignment.Center, justify=Alignment.Center, picture...),
    Box(height(GALLERY_LABEL), Alignment.Center, label(elide(p.name, 11px, wide), 11px, color=colours.dim)))
end

# The square of a picture or a video shows the middle of its picture, cut to fit, with round corners
draw(ctx, size, ui::ConcreteRect, t::GalleryThumb) = begin
  v = t.of
  p = item_at(v, t.i)
  p === nothing && return
  s = small(v, p)
  left, top, wide, tall = num(ui.left), num(ui.top), num(ui.width), num(ui.height)
  if s isa NamedTuple && s.fills
    image = image_source(s.key)
    with_round_clip(ctx, ui.left, ui.top, ui.width, ui.height, GALLERY_ROUND) do
      paint_picture(ctx, image.raw, Galleries.crop(image.width, image.height), (left, top, wide, tall))
    end
    # A video has a mark that plays in its corner, so that it isn't taken for a picture
    if p.kind == :file
      r = 11.0
      x, y = left + 8 + r, top + tall - 8 - r
      disc(ctx, x, y, r, RGBA(0, 0, 0, 0.55))
      white = RGBA(1, 1, 1, 1)
      trace(ctx, [(x - 3.5, y - 5.5), (x + 5.5, y), (x - 3.5, y + 5.5)], white, 0.5; fill=white, closed=true)
    end
  end
  # The square under the mouse has a line round it
  ishovered(t) && round_box(ctx, left + 1, top + 1, wide - 2, tall - 2, num(GALLERY_ROUND) - 1; line=colours.accent, wide=2.0)
  nothing
end

cursor(::GalleryThumb) = :hand
cursor(::GalleryView) = :arrow

onmouse(t::GalleryThumb, ev::MouseMove) = begin
  p = item_at(t.of, t.i)
  p === nothing || show_tooltip!(ev.window, tip_label(p.name), t, placement=:bottom, gap=6px)
  nothing
end

onkey(t::GalleryThumb, ev::KeyPress{Keys.mouse_left}) = (hide_tooltip!(ev.window); open_item!(t.of, t.i))

"""
True when `p`, a square of the gallery, is of a kind that fills the window on
a click: a picture, a PDF file, a video or a 3D model. A picture whose square
has no picture of its own can't be read, so it doesn't. This reads no file, so
it's quick enough for each frame.
"""
fills_window(v::GalleryView, p) = begin
  ext = lowercase(splitext(p.path)[2])
  p.kind == :picture ? (s = small(v, p); ismissing(s) || s isa NamedTuple && s.fills) :
  p.kind == :file && (ext in MODELS || Sys.isapple() && (ext == ".pdf" || ext in VIDEOS))
end

"""
What fills the window for `p`, a square of the gallery: its picture, the
first page of its PDF file, the player of its video or the viewer of its 3D
model. It's nothing for a folder, a file of another kind, and a file that
can't be read as its kind. The gallery keeps one player and one viewer.
"""
item_fill(v::GalleryView, p) = begin
  if p.kind == :picture
    key = picture_key(p.path)
    return key === nothing ? nothing : (:picture, key)
  end
  fills_window(v, p) || return nothing
  ext = lowercase(splitext(p.path)[2])
  ext == ".pdf" && return pdf_pages(p.path) > 0 ? (:pdf, p.path, 1) : nothing
  if ext in VIDEOS
    old = get(v.parts, :player, nothing)
    old isa VideoPlayer && old.path == p.path && return (:node, old)
    delete!(v.parts, :player)
    return (:node, block_part!(() -> VideoPlayer(path=p.path, height=MODEL_HEIGHT), v, :player))
  end
  old = get(v.parts, :model, nothing)
  (old isa STLViewer && old.path == p.path) || delete!(v.parts, :model)
  m = block_part!(() -> STLViewer(path=p.path, height=MODEL_HEIGHT), v, :model)
  load!(m) isa Mesh ? (:node, m) : nothing
end

"""
Do what a click on square `i` of the gallery does. A picture, a PDF file, a
video or a 3D model fills the window. A folder and any other file open, as a
link to them does.
"""
open_item!(v::GalleryView, i::Int) = begin
  p = item_at(v, i)
  p === nothing && return handled
  what = item_fill(v, p)
  what === nothing || return show_item!(v, p, what)
  show_path!(editor(v), p.path)
  handled
end

"Make `what`, which shows `p` of the gallery, fill the window"
show_item!(v::GalleryView, p, what) = begin
  v.showing = p.path
  zoom_in!(editor(v), what, v)
end

"""
While a file of the gallery fills the window, go `by` files on: to the one
before it, or to the next one. A folder, and a file that doesn't fill the
window, are passed over. At the first file and the last, nothing changes.
"""
step!(v::GalleryView, by::Int) = begin
  items = found!(v).items
  i = something(findfirst(p -> p.path == v.showing, items), 0) + by
  while i in eachindex(items)
    what = item_fill(v, items[i])
    what === nothing || return show_item!(v, items[i], what)
    i += by
  end
  handled
end

"""
Where the file that fills the window is in its gallery: the gallery, the
file's place, how many files and folders the gallery has, and the name of the
file. It's nothing for what isn't from a gallery.
"""
gallery_place(z::ZoomView) = begin
  g = z.from
  (g isa GalleryView && z.what !== nothing) || return nothing
  items = found!(g).items
  i = findfirst(p -> p.path == g.showing, items)
  i === nothing ? nothing : (gallery=g, i=i, n=length(items), name=items[i].name)
end

"What the bar under a file of a gallery says of the file's place, like “2 of 6”"
place_words(at) = "$(at.i) of $(at.n)"

"""
True when the gallery has a file to show `by` files on from square `i`: one
before it, or one after it. A folder and a file that doesn't fill the window
don't count, because `step!` passes over them.
"""
can_step(v::GalleryView, i::Int, by::Int) = begin
  items = found!(v).items
  any(k -> fills_window(v, items[k]), by < 0 ? (1:i-1) : (i+1:length(items)))
end

"""
What the bar under a file of a gallery starts with: a button for the file
before, the file's place, a button for the next file, the file's name and a
line. The bar of anything else has none of them. In a window that's too
narrow for them all, the name goes first, and then the place.
"""
gallery_buttons(z::ZoomView; rest=281) = begin
  at = gallery_place(z)
  at === nothing && return ()
  g = at.gallery
  button(key, by, icon, tip) = begin
    b = part!(() -> PlanButton(of=g), z, (:button, key))
    # The view keeps its buttons, and the gallery can be another one of the page than when they were made
    b.of, b.action, b.icon, b.tip, b.off = g, (:step, by), icon, tip, !can_step(g, at.i, by)
    b
  end
  face = Face(SANS, "", 12px, colours.dim, false)
  # `rest` is how wide the rest of the bar is, with the two buttons here and the room on each side of it
  spare = num(window_size(editor(z))[1]) - rest
  place = place_words(at)
  placed = num(measure(face, place)) + 8
  room = min(spare - placed - 14, GALLERY_NAME)
  words(text) = label(text, 12px, color=colours.dim)
  (button(:before, -1, "chevron-left", "The file before  ←"),
   (spare >= placed ? (Box(Alignment.Center, padding(4px, 0px), words(place)),) : ())...,
   button(:next, 1, "chevron-right", "The next file  →"),
   (room >= 60 ? (Box(Alignment.Center, padding(6px, 0px), words(elide(at.name, 12px, px(room)))),) : ())...,
   rule())
end

"A large arrow at the left or the right edge of the window, while a file of a gallery fills it. A click goes to the file before, or to the next one."
@def mutable struct GalleryEdge <: SemanticUI
  of::Any = nothing   # the gallery
  by::Int = 1         # -1 for the file before, and 1 for the next one
end

describe(a::GalleryEdge) =
  Box(width(GALLERY_EDGE), height(GALLERY_EDGE), radius(GALLERY_EDGE / 2), Alignment.Center, justify=Alignment.Center, name="Button",
      background(ishovered(a) ? colours.hover : RGBA(colours.float, 0.85)), border(1px, :solid, colours.line),
    Icon(a.by < 0 ? "chevron-left" : "chevron-right", size=20px, color=colours.dim))

cursor(::GalleryEdge) = :hand
onkey(a::GalleryEdge, ::KeyPress{Keys.mouse_left}) = step!(a.of, a.by)

"""
The arrows at the left and the right edge of a file of a gallery that fills
the window, in the middle of the window's height. Each one shows while the
mouse is near its edge, and there's a file to go to. Anything else that fills
the window has none.
"""
gallery_edges(z::ZoomView) = begin
  at = gallery_place(z)
  w = window_of(z)
  (at === nothing || w === nothing) && return ()
  wide = num(window_size(editor(z))[1])
  x, y = num(w.mouse[1]), num(w.mouse[2])
  arrow(by) = begin
    near = y > num(TOPBAR_H) && (by < 0 ? x < GALLERY_NEAR : x > wide - GALLERY_NEAR)
    near && can_step(at.gallery, at.i, by) || return Box(width(GALLERY_EDGE))
    a = part!(() -> GalleryEdge(by=by), z, (:edge, by))
    a.of = at.gallery   # the view keeps its arrows, and the gallery can be another one of the page than when they were made
    a
  end
  (Row(width(grow=grow), height(grow=grow), Alignment.Center, padding(0px, 16px, BAR_ROOM, 16px), arrow(-1), Box(width(grow=grow)), arrow(1)),)
end

"""
Do what a button of a gallery does. The one at its top gives its squares the
next size, which goes into the block. The two under a file that fills the
window go to the file before it and to the next one.
"""
act!(v::GalleryView, action, w) = begin
  action isa Tuple && action[1] == :step && return step!(v, action[2])
  action == :size || return handled
  v.data.size = Galleries.next_size(v.data.size)
  # A page that can't be changed still shows the new size
  readonly(editor(v).buf) || write_block!(v, GALLERY, Galleries.written(v.data))
  handled
end

describe(v::GalleryView) = begin
  e = editor(v)
  found = found!(v)
  items = found.items
  paper = on_paper(e)
  with_theme(component_theme(e.zoom)) do
    lost = Galleries.lost_words(found.lost)
    isempty(items) && return Column(block_look()..., clip=true, name="Gallery", block_note(isempty(lost) ? found.problem : lost))
    icon, words = GALLERY_SIZES[v.data.size]
    bigger = lowercase(GALLERY_SIZES[Galleries.next_size(v.data.size)][2])
    top = Row(width(grow=grow), height(GALLERY_TOP), padding(0px, 6px, 0px, GALLERY_PAD), Alignment.Center, clip=true,
              Box(label(Galleries.summary(v.data, found), 12px, color=colours.dim)), Box(width(grow=grow)),
              (paper ? () : (block_button!(v, :size, :size, icon=icon, words=words, tip="Make the squares $bigger"),))...)
    g = Galleries.grid(length(items), num(e.width - 2px - 2GALLERY_PAD), v.data.size)
    v.side = px(g.side)
    rows = rows_in_view(v, g)
    places = [i for r in rows for i in Galleries.row_places(r, g.columns, length(items))]
    # On paper every square shows, so each small picture is made now. In the window, the next frames make them.
    paper && foreach(i -> ismissing(small(v, items[i])) && small!(v, items[i]), places)
    v.wanted = [items[i] for i in places if ismissing(small(v, items[i]))]
    isempty(v.wanted) || redraw_in!(v, 0)
    gap, step = px(Galleries.GAP), g.side + Galleries.GAP
    # The rows that aren't built leave their room empty, so the block is as tall as the whole grid
    above = isempty(rows) ? px(Galleries.tall(g.rows, g.side)) : px((first(rows) - 1) * step) - gap
    below = isempty(rows) ? 0px : px((g.rows - last(rows)) * step) - gap
    grid = Column(width(grow=grow), Alignment.Start, padding(0px, GALLERY_PAD, GALLERY_PAD, GALLERY_PAD), child_gap=gap,
      (above > 0px ? (Box(width(grow=grow), height(above)),) : ())...,
      [Row(height(v.side), child_gap=gap, Alignment.Start,
           [block_part!(() -> GalleryThumb(of=v, i=i), v, (:thumb, i)) for i in Galleries.row_places(r, g.columns, length(items))]...)
       for r in rows]...,
      (below > 0px ? (Box(width(grow=grow), height(below)),) : ())...)
    # A line of the block that names nothing is named under the grid
    note = isempty(lost) ? () : (Row(width(grow=grow), padding(0px, GALLERY_PAD, GALLERY_PAD, GALLERY_PAD), Alignment.Start, clip=true,
                                     Box(width(grow=grow), Text(lost, size=12px, family=SANS, color=colours.dim, wrap=WrapMode.words))),)
    Column(block_look()..., clip=true, name="Gallery", top, grid, note...)
  end
end

"The gallery under the mouse, or nothing. Only a gallery that the page shows now is where it was last drawn."
gallery_at(e, w) = begin
  x, y = w.mouse
  for it in view(e.layout, intersect(e.shown, eachindex(e.layout)))
    node = it.content isa Live ? it.content.node : nothing
    node isa GalleryView || continue
    r = rect(node)
    r !== nothing && r.left <= x < r.left + r.width && r.top <= y < r.top + r.height && return node
  end
  nothing
end

"""
Add the files and the folders at `paths` to the gallery, as a drop on it
does. Each one is copied into the gallery's folder. A gallery that only lists
its files gets a line for each one, and the files stay where they are. It's
true when the gallery took a file or a folder.
"""
add_files!(v::GalleryView, paths) = begin
  e = editor(v)
  dir = docdir(e)
  new = [String(rstrip(String(p), '/')) for p in paths]
  filter!(ispath, new)
  (isempty(new) || readonly(e.buf) || !isdir(dir)) && return false
  to = Galleries.folder(v.data, dir)
  if to === nothing
    append!(v.data.listed, unique(name for name in (named(e, p) for p in new) if !(name in v.data.listed)))
    write_block!(v, GALLERY, Galleries.written(v.data))
  else
    foreach(p -> Galleries.keep(to, p), new)
    list_files!(e)   # the sidebar lists the new files too
  end
  v.shown = nothing
  true
end

"""
The gallery as HTML: a grid of squares, each named as a link in the text names
its file. A picture shows itself. Any other file or folder is a link with its
name in it.
"""
gallery_html(e, v::GalleryView) = begin
  found = found!(v)
  isempty(found.items) && return "<p>$(escape(isempty(found.lost) ? found.problem : Galleries.lost_words(found.lost)))</p>"
  shape = "aspect-ratio: 1; border-radius: $(round(Int, num(GALLERY_ROUND)))px"
  look = "width: 100%; object-fit: cover; $shape"
  box = "display: flex; align-items: flex-end; justify-content: center; box-sizing: border-box; padding: 6px; $shape; " *
        "background: rgba(128, 128, 128, 0.12); color: inherit; text-decoration: none; font-size: 12px; overflow: hidden; overflow-wrap: anywhere"
  square(p) = begin
    src = escape(escaped(named(e, p.path)))
    p.kind == :picture ? "<img src=\"$src\" alt=\"$(escape(splitext(p.name)[1]))\" loading=\"lazy\" style=\"$look\">" :
                         "<a href=\"$src\" style=\"$box\">$(escape(p.name))</a>"
  end
  squares = join((square(p) for p in found.items), "\n")
  "<div class=\"gallery\" style=\"display: grid; grid-template-columns: repeat(auto-fill, minmax($(Galleries.SIDES[v.data.size])px, 1fr)); gap: $(Galleries.GAP)px\">\n$squares\n</div>"
end

BLOCKS[GALLERY] = BlockKind("Gallery", "images", GalleryView, gallery_html)

# --- a sketch ---------------------------------------------------------------------------------
#
# A code block in the language `sketch` is a drawing. sketch.jl says how the
# block is written. You draw in it where it is in the page. Only the button
# that shows beside its top right corner while the mouse is over it makes it
# fill the window, where it has more room. A click or a pinch never does. A
# page that can't change shows only the drawing. The buttons at its top choose
# a tool: the arrow selects a shape, and the others draw by hand, a line, an
# arrow, a box, an oval or words. The dots after them choose the colour of the
# next shape, or of the shape that's selected.
#
#   - Drag in the sketch to draw with the tool. For words, click where they
#     go and type them there. Return, or a click somewhere else, adds them,
#     and Esc leaves them out.
#   - Click words twice with the arrow, or once with the tool for words, to
#     change them where they are. Esc leaves them as they were, and words
#     with nothing left in them are taken away.
#   - With the arrow, click a shape to select it, and drag it to move it.
#     Delete takes the selected shape away.
#   - The shape that's selected glows, and has a circle on each place that
#     changes it: the ends of a line, each place of a line drawn by hand, the
#     corners of a box and the middle of each side of an oval. Drag a circle
#     to move that place.
#   - After the dots come the numbers that say how a shape is drawn: how thick
#     its line is, how round the corners of a box are, and how big words are.
#     The buttons each side of a number change it, for the shape that's
#     selected, or for the shapes that the tool draws next. Click a number
#     to type another, and press Return.
#   - The sketch gets taller when a shape is near its bottom edge. In the
#     page, the wheel scrolls the page past it.
#   - Esc chooses the arrow tool. With that tool, Esc gives the keyboard back
#     to the page's text, or puts a sketch that fills the window back in the
#     page. So does the last button there.
#
# Each shape is a line of the block, so the file holds the whole drawing, and
# ⌘Z takes back the last thing you drew.

const SKETCH = Sketches.SKETCH
"The tools of a sketch: the icon of each one's button, and what the button's tooltip says"
const SKETCH_TOOLS = ((:select, "cursor", "Select a shape, and drag it to move it"), (:pen, "pencil", "Draw by hand"),
                      (:line, "slash-lg", "Draw a line"), (:arrow, "arrow-up-right", "Draw an arrow"), (:box, "square", "Draw a box"),
                      (:oval, "circle", "Draw an oval"), (:text, "type", "Write words: click where they go, and type them there"))
push!(BLOCK_ICONS, "pencil", "slash-lg", "arrow-up-right", "square", "circle", "type", "trash", "cursor",
      "border-width", "fonts", "dash", "plus", "arrows-fullscreen", "fullscreen-exit")
"""
For each part of how a shape is drawn: its icon at the top of a sketch, what
the tooltips of its two buttons say, and how much one click changes it.
"""
const SKETCH_SETTINGS = (width=("border-width", "Make the line thinner", "Make the line thicker", 0.5),
                         radius=("round-corner", "Make the corners less round", "Make the corners rounder", 1.0),
                         size=("fonts", "Make the words smaller", "Make the words bigger", 1.0))
const SKETCH_BAR = 646px   # the room that the top of a sketch needs to show everything in one row
const HANDLE = 4.5         # px: the radius of the circle on a place of the selected shape
const HANDLE_REACH = 8.0   # px: how near the mouse is to a circle to drag it

# UI.jl has no icon for a round corner. This is one, in a square 16 wide: a line that turns a corner.
const ROUND_CORNER = "M1.75 14L1.75 8A6.25 6.25 0 0 1 8 1.75L14 1.75A0.75 0.75 0 0 1 14 3.25L8 3.25A4.75 4.75 0 0 0 3.25 8L3.25 14A0.75 0.75 0 0 1 1.75 14Z"

"The name of an icon at the top of a sketch. The round corner goes among UI.jl's icons the first time that it's asked for."
sketch_icon(name) = begin
  name == "round-corner" || return name
  kept = get(icon_cache, name, nothing)
  (kept === nothing || first(kept.paths).d != ROUND_CORNER) && (icon_cache[name] = (paths=[SVGPath(d=ROUND_CORNER)], viewbox=(0f0, 0f0, 16f0, 16f0)))
  name
end

"What a `sketch` block shows: a drawing, and the tools that draw it"
@def mutable struct SketchView <: SemanticUI
  n::Int = 0                               # its place among the page's sketches
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Sketches.Sketch = Sketches.Sketch()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  tool::Symbol = :pen
  colour::Symbol = :ink                    # the colour of the next shape
  # How the next shape is drawn: how thick its line is, how round the corners of a box are, and how big words are
  next::Dict{Symbol,Float64} = Dict(:width => Sketches.WIDTH, :radius => Sketches.RADIUS, :size => Sketches.TEXT_SIZE)
  draft::Any = nothing                     # the shape that's being drawn, or nothing
  picked::Int = 0                          # the place of the shape that's selected, or 0
  # A drag of the selected shape: where the mouse was last, whether the shape has changed, and the number of
  # the circle that's dragged, or 0 when the whole shape is
  grab::Any = nothing
  asking::Any = nothing                    # the place in the drawing where words are being typed, or nothing
  editing::Int = 0                         # the place among the shapes of the words that are being changed, or 0 when the words are new
  clicked::NTuple{3,Float64} = (0.0, 0.0, 0.0)   # when and where the drawing was last clicked
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the drawing was last drawn in the window
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its buttons and its text field, kept between frames
  typing::Any = nothing                    # the part of how a shape is drawn whose number has the keyboard, like `:width`, or nothing
  full::Bool = false                       # it fills the window, over the page
  tall::px = 0px                           # how tall it was in the page when it was last laid out there
  pinned::px = 0px                         # how far the page was scrolled when it filled the window
end

"The part of a sketch that's drawn in"
@def mutable struct SketchArea <: SemanticUI
  of::Any = nothing
end
"A dot in the top of a sketch that chooses a colour"
@def mutable struct InkDot <: SemanticUI
  of::Any = nothing
  colour::Symbol = :ink
end

reread!(v::SketchView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Sketches.sketch(lines)
  v.picked = min(v.picked, length(v.data.shapes))
  v
end

"The colour that a sketch draws the colour called `name` in"
sketch_colour(name::Symbol) = begin
  cs = series_colours()
  name == :red ? cs[8] : name == :blue ? cs[1] : name == :green ? cs[6] : name == :orange ? cs[2] : colours.ink
end

sketch_area(v::SketchView) = block_part!(() -> SketchArea(of=v), v, :area)

"""
The text field that holds the words that are being typed into the drawing. It
has the keyboard while they're typed, and it isn't shown: the drawing shows
its words where they will be.
"""
sketch_input(v::SketchView) = block_part!(v, :input) do
  TextInput(placeholder="", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"How much room the sketch has from side to side: the page's text, or the window when it fills the window"
sketch_room(v::SketchView) = v.full ? window_size(editor(v))[1] : editor(v).width

"How many px of the window one of the sketch's own measure is"
sketch_scale(v::SketchView) = v.box[3] > 0 ? v.box[3] / Sketches.WIDE : num(sketch_room(v) - (v.full ? 0px : 2px)) / Sketches.WIDE

"The shape that's selected, or nothing"
picked_shape(v::SketchView) = 1 <= v.picked <= length(v.data.shapes) ? v.data.shapes[v.picked] : nothing

"A new shape, in the colour and drawn the way that the top of the sketch says now"
new_shape(v::SketchView, kind, points, text="") = begin
  shape = Sketches.Shape(kind, v.colour, points, text)
  foreach(name -> Sketches.set!(shape, name, v.next[name]), Sketches.settings(kind))
  shape
end

"""
The parts of how a shape is drawn that the top of the sketch shows now: those
of the shape that's selected, or those of the shapes that the tool draws.
"""
shown_settings(v::SketchView) = (s = picked_shape(v); s !== nothing ? Sketches.settings(s) : v.tool == :select ? () : Sketches.settings(v.tool))

"What a part of how a shape is drawn is now: for the shape that's selected, or for the next shape"
setting(v::SketchView, name) = (s = picked_shape(v); s === nothing ? v.next[name] : getfield(s, name))

"The most that a part of how a shape is drawn can be now. The corners of the box that's selected are no rounder than half its shorter side."
most(v::SketchView, name) = begin
  top = Sketches.LIMITS[name][2]
  s = picked_shape(v)
  (name == :radius && s !== nothing) || return top
  l, t, r, b = Sketches.bounds(s)
  min(top, round(min(r - l, b - t) / 2, digits=1))
end

"The number that a click takes `n` to: the next whole step up, or the next one down"
stepped(name, n, up) = begin
  step = SKETCH_SETTINGS[name][4]
  to = up ? (floor(n / step + 1e-9) + 1) * step : (ceil(n / step - 1e-9) - 1) * step
  clamp(to, Sketches.LIMITS[name]...)
end

"The text field that holds the number of one part of how a shape is drawn"
number_input(v::SketchView, name) = block_part!(v, (:number, name)) do
  TextInput(placeholder="", font_family=SANS, font_size=12px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"""
Give a part of how a shape is drawn the number `n`: to the shape that's
selected, and to the shapes that are drawn next. A number that's too small or
too big becomes the nearest that the part can be.
"""
set_setting!(v::SketchView, name, n::Real) = begin
  n = round(clamp(n, Sketches.LIMITS[name][1], most(v, name)), digits=1)
  v.next[name] = n
  s = picked_shape(v)
  (s === nothing || getfield(s, name) == n) || (Sketches.set!(s, name, n); commit!(v))
  v
end

"The number that was typed is taken, and its field lets go of it. Text that isn't a number changes nothing."
settle_number!(v::SketchView) = begin
  name = v.typing
  name === nothing && return v
  v.typing = nothing
  n = tryparse(Float64, strip(number_input(v, name).text))
  (n === nothing || !isfinite(n)) ? v : set_setting!(v, name, n)
end

"""
The number of one part of how a shape is drawn, at the top of a sketch, with
its icon and a button each side that changes it. The number is a text field:
a click in it selects the number, and Return takes what's typed.
"""
stepper(v::SketchView, name) = begin
  icon, less, more, _ = SKETCH_SETTINGS[name]
  n = setting(v, name)
  field = number_input(v, name)
  field.color = colours.ink
  typing = v.typing == name
  # While nobody types in it, the field shows the number as it is now
  typing || (field.text = Sketches.figure(n); field.anchor = field.cursor = 0)
  Row(Alignment.Center, name="Setting",
    Box(fixed(22px), height(26px), Alignment.Center, justify=Alignment.Center, Icon(sketch_icon(icon), size=14px, color=colours.dim)),
    block_button!(v, (:less, name), (:set, name, false), icon="dash", tip=less, off=n <= Sketches.LIMITS[name][1]),
    # The field is as wide as its number, in the middle of its room, so the number is half way between the two buttons
    Box(fixed(34px), height(26px), Alignment.Center, justify=Alignment.Center,
      Box(fixed(px(clamp(sketch_measure(field.text, 12) + 14, 20, 34))), height(22px), padding(5px, 0px), radius(5px),
          border(1px, :solid, typing ? colours.accent : ishovered(field) ? colours.line : clear), background(typing ? colours.bg : clear), field)),
    block_button!(v, (:more, name), (:set, name, true), icon="plus", tip=more, off=n >= most(v, name)))
end

"The place in the sketch that's under the mouse"
sketch_place(v::SketchView, w) = (s = sketch_scale(v); ((num(w.mouse[1]) - v.box[1]) / s, (num(w.mouse[2]) - v.box[2]) / s))

"How wide the words of a text shape are, in the sketch's own measure"
sketch_measure(text, size) = num(measure(Face(SANS, "", px(size), colours.ink, false), text))

"Write the sketch into its block"
commit!(v::SketchView) = write_block!(v, SKETCH, Sketches.written(v.data))

describe(::InkDot) = Box(fixed(22px), height(26px), name="Colour")

# The dot and the ring round it are drawn about the middle of the dot's box, so the ring is never off the dot
draw(ctx, size, ui::ConcreteRect, d::InkDot) = begin
  v = d.of
  on = (v.picked > 0 ? v.data.shapes[v.picked].colour : v.colour) == d.colour
  x, y = Float32(num(ui.left + ui.width / 2)), Float32(num(ui.top + ui.height / 2))
  disc(colour, r, wide=0.0) = (paint = ink(colour, wide); Skia.sk_canvas_draw_circle(ctx, x, y, Float32(r), paint); Skia.sk_paint_delete(paint))
  disc(sketch_colour(d.colour), 5)
  (on || ishovered(d)) && disc(on ? colours.accent : colours.marker, 7.25, 1.5)
end

cursor(::InkDot) = :hand

# A click on a colour gives it to the shape that's selected, and to the shapes that are drawn next
onkey(d::InkDot, ::KeyPress{Keys.mouse_left}) = begin
  v = d.of
  v.colour = d.colour
  v.picked > 0 && (v.data.shapes[v.picked].colour = d.colour; commit!(v))
  v.asking === nothing || focus(sketch_input(v))   # the words that are being typed take the colour, and the keyboard stays with them
  handled
end

"True for a sketch with too little room for all of its top in one row. How a shape is drawn then has a row of its own."
narrow(v::SketchView) = sketch_room(v) < SKETCH_BAR

describe(v::SketchView) = begin
  e = editor(v)
  with_theme(component_theme(e.zoom)) do
    # In the page, a page that can't change shows only the drawing
    v.full || !readonly(e.buf) ||
      return Box(width(grow=grow), Alignment.Start, fillable(v, (:block, v), Column(block_look()..., clip=true, name="Sketch", sketch_area(v)), wide=:grow))
    settings = [stepper(v, name) for name in shown_settings(v)]
    beside = narrow(v) || isempty(settings) ? () : (rule(), settings...)
    # The last button puts a sketch that fills the window back in the page. In the page, the button beside its top
    # right corner makes it fill the window.
    full = v.full ? (block_button!(v, :full, :full, icon="fullscreen-exit", tip="Back to the page  esc"),) : ()
    tools = ([block_button!(v, tool, (:tool, tool), icon=icon, tip=tip, on=v.tool == tool) for (tool, icon, tip) in SKETCH_TOOLS]..., rule(),
             [block_part!(() -> InkDot(of=v, colour=c), v, (:ink, c)) for c in Sketches.COLOURS]..., beside...,
             Box(width(grow=grow)),
             (v.picked > 0 ? (block_button!(v, :delete, :delete, icon="trash", tip="Take the selected shape away  Delete"),) : ())..., full...)
    # The second row is there all the time in a narrow sketch, so that the drawing stays where it is when a shape is selected
    bars = (block_bar(tools...), (narrow(v) ? (block_bar(settings..., Box(width(grow=grow))),) : ())...)
    # In the page its tools are over its drawing, so that you draw where it is
    v.full || return Box(width(grow=grow), Alignment.Start, fillable(v, (:block, v), Column(block_look()..., clip=true, name="Sketch", bars..., sketch_area(v)), wide=:grow))
    # In the window it takes all the room under the top bar. The wheel scrolls through a drawing that's taller than that.
    list = get!(() -> Scroll(width(grow=grow), height(grow=grow)), v.parts, :list)
    Column(width(grow=grow), height(grow=grow), Alignment.Start, background(takeoff_back()), name="Sketch", bars..., reuse!(list, sketch_area(v)))
  end
end

"""
Make the sketch fill the window, or put it back in the page. In the page it
shows only its drawing, so words that were being typed are added, no shape is
selected, and the keyboard goes back to the text.
"""
full!(v::SketchView, on::Bool) = begin
  e = editor(v)
  on && unfill!(e)   # one block at a time fills the window
  on || (settle_number!(v); answer!(v); v.picked = 0; v.draft = v.grab = nothing)
  v.full = on
  v.pinned = e.scroll.offset
  v.box = (0.0, 0.0, 0.0, 0.0)   # it's another size now, so how big it's drawn is worked out afresh
  on ? focus(sketch_area(v)) : focus(e)
  handled
end

# A pinch on a sketch in the page doesn't make it fill the window. Only the button beside its top right corner does.
onpinch(::SketchView, ::Pinch) = nothing

"How tall the drawing is in a sketch that fills the window, when its shapes need less: the window, under the top bar and the sketch's buttons"
full_room(v::SketchView) = num(window_size(editor(v))[2] - TOPBAR_H - (narrow(v) ? 76px : 38px))

act!(v::SketchView, action, w) = begin
  settle_number!(v)
  # A button beside a number changes the words that are being typed, and they stay open. Any other button adds them first.
  (action isa Tuple && action[1] == :set) || answer!(v)
  if action == :delete
    1 <= v.picked <= length(v.data.shapes) || return handled
    deleteat!(v.data.shapes, v.picked)
    v.picked = 0
    commit!(v)
  elseif action == :full
    return full!(v, !v.full)
  elseif action[1] == :tool
    v.tool = action[2]
    v.tool == :select || (v.picked = 0)
  elseif action[1] == :set
    # A button beside a number changes it for the shape that's selected, and for the shapes that are drawn next
    _, name, up = action
    set_setting!(v, name, stepped(name, setting(v, name), up))
  end
  focus(v.asking === nothing ? sketch_area(v) : sketch_input(v))
  handled
end

describe(a::SketchArea) = begin
  v = a.of
  # While a shape is drawn or moved, the sketch keeps its height, and gets taller when the mouse lets go
  tall = Sketches.tall(v.data) * sketch_scale(v)
  # One that fills the window goes down to the window's foot, or further
  Box(width(grow=grow), height(px(v.full ? max(tall, full_room(v)) : tall)))
end

"Draw a line through `points` whose corners are round, as a line drawn by hand has them"
draw_curve(ctx, points, paint) = begin
  length(points) < 2 && return
  shape = Skia.sk_path_new()
  Skia.sk_path_move_to(shape, Float32(points[1][1]), Float32(points[1][2]))
  # The line goes from the middle of each part to the middle of the next, and bends at the place between
  for i in 2:length(points)-1
    mid = (points[i] .+ points[i+1]) ./ 2
    Skia.sk_path_quad_to(shape, Float32(points[i][1]), Float32(points[i][2]), Float32(mid[1]), Float32(mid[2]))
  end
  Skia.sk_path_line_to(shape, Float32(points[end][1]), Float32(points[end][2]))
  Skia.sk_canvas_draw_path(ctx, shape, paint)
  Skia.sk_path_delete(shape)
end

"""
Draw one shape of a sketch whose top left corner is at `(x0, y0)` in the
window. `s` is how many px one of the sketch's measure is. With `glow`, it
draws a soft light in the shape and the colour of the shape, which goes under
the shape that's selected.
"""
draw_shape(ctx, shape, x0, y0, s; glow=false) = begin
  at(p) = (x0 + p[1] * s, y0 + p[2] * s)
  words = shape.kind == :text
  # A line is never so thin in a small sketch that it can't be seen
  wide = max(min(1.2, 0.6shape.width), shape.width * s)
  colour = sketch_colour(shape.colour)
  # The light is the colour of the shape, and fainter
  paint = glow ? ink(RGBA(colour, 0.35), words ? 0.0 : wide + 4) : ink(colour, words ? 0.0 : wide)
  blur = glow ? Skia.sk_maskfilter_new_blur_with_flags(Skia.SK_BLUR_STYLE_NORMAL, 2.5f0, true) : nothing
  glow && Skia.sk_paint_set_maskfilter(paint, blur)
  stroke(ps) = (line = path_through(ps, false); Skia.sk_canvas_draw_path(ctx, line, paint); Skia.sk_path_delete(line))
  if words
    x, y = at(shape.points[1])
    blob = Skia.sk_textblob_make_from_string(shape.text, skia_font(SANS, px(shape.size * s), "").raw, Skia.SK_TEXT_ENCODING_UTF8)
    # The light under words is drawn twice, since words are thin
    for _ in 1:(glow ? 2 : 1)
      Skia.sk_canvas_draw_text_blob(ctx, blob, Float32(x), Float32(y), paint)
    end
    Skia.sk_textblob_unref(blob)
  elseif shape.kind in (:box, :oval)
    l, t, r, b = Sketches.bounds(shape)
    (x1, y1), (x2, y2) = at((l, t)), at((r, b))
    edges = Ref(Skia.sk_rect_t(Float32(x1), Float32(y1), Float32(x2), Float32(y2)))
    if shape.kind == :oval
      Skia.sk_canvas_draw_oval(ctx, edges, paint)
    else
      # The corners of a small box are no rounder than half its shorter side
      bend = Float32(min(shape.radius * s, (x2 - x1) / 2, (y2 - y1) / 2))
      outline = Skia.sk_path_new()
      Skia.sk_path_add_rounded_rect(outline, edges, bend, bend, Skia.SK_PATH_DIRECTION_CW)
      Skia.sk_canvas_draw_path(ctx, outline, paint)
      Skia.sk_path_delete(outline)
    end
  elseif shape.kind == :pen
    draw_curve(ctx, at.(shape.points), paint)
  else
    stroke(at.(shape.points))
    if shape.kind == :arrow
      a, b = Sketches.barbs(shape)
      stroke([at(a), at(shape.points[2]), at(b)])
    end
  end
  glow && Skia.sk_maskfilter_unref(blur)
  Skia.sk_paint_delete(paint)
end

"The number of the circle of the selected shape that's under the mouse, or nothing"
handle_under(v::SketchView, w) = begin
  shape = picked_shape(v)
  (shape === nothing || w === nothing || v.box[3] <= 0) && return nothing
  Sketches.handle(shape, sketch_place(v, w), HANDLE_REACH / sketch_scale(v))
end

"Draw a circle on each place of the selected shape that a drag moves. The one under the mouse, or the one that's dragged, is filled."
draw_handles(ctx, v::SketchView, shape, s) = begin
  hot = v.grab !== nothing ? (v.grab[3] == 0 ? nothing : v.grab[3]) : v.tool == :select ? handle_under(v, window_of(v)) : nothing
  # The places of a line drawn by hand are close together, so their circles are smaller
  r = shape.kind == :pen ? 0.7HANDLE : HANDLE
  for (k, p) in enumerate(Sketches.handles(shape))
    x, y = Float32(v.box[1] + p[1] * s), Float32(v.box[2] + p[2] * s)
    for paint in (ink(k == hot ? colours.accent : takeoff_back()), ink(colours.accent, 1.5))
      Skia.sk_canvas_draw_circle(ctx, x, y, Float32(r), paint)
      Skia.sk_paint_delete(paint)
    end
  end
end

draw(ctx, size, ui::ConcreteRect, a::SketchArea) = begin
  v = a.of
  v.box = (num(ui.left), num(ui.top), num(ui.width), num(ui.height))
  v.box[3] > 0 || return
  s = sketch_scale(v)
  with_clip(ctx, ui.left, ui.top, ui.width, ui.height) do
    isempty(v.data.shapes) && v.draft === nothing && v.asking === nothing &&
      write_ink(ctx, readonly(editor(v).buf) ? "Nothing is drawn here" : "Drag here to draw", v.box[1] + 16, v.box[2] + 28, Face(SANS, "", 13px, colours.faint, false))
    for (k, shape) in enumerate(v.data.shapes)
      k == v.editing && continue   # words that are being changed show as they're typed
      # The shape that's selected glows
      k == v.picked && draw_shape(ctx, shape, v.box[1], v.box[2], s, glow=true)
      draw_shape(ctx, shape, v.box[1], v.box[2], s)
    end
    v.draft === nothing || draw_shape(ctx, v.draft, v.box[1], v.box[2], s)
    # And it has a circle on each place that a drag moves
    chosen = picked_shape(v)
    chosen === nothing || draw_handles(ctx, v, chosen, s)
    v.asking === nothing || draw_typing(ctx, v, s)
  end
end

"The words that are being changed, or nothing when the words that are typed are new"
edited_shape(v::SketchView) = begin
  s = 1 <= v.editing <= length(v.data.shapes) ? v.data.shapes[v.editing] : nothing
  s !== nothing && s.kind == :text ? s : nothing
end

"The words that are being typed, as the shape that they will be"
typed_shape(v::SketchView) = begin
  old, text = edited_shape(v), sketch_input(v).text
  old === nothing ? new_shape(v, :text, [v.asking], text) : Sketches.Shape(:text, old.colour, [v.asking], text, old.width, old.radius, old.size)
end

"""
The place among the characters of the words that are being typed that's
nearest to `p`, a place in the sketch. It's nothing when `p` isn't on the words.
"""
typed_index(v::SketchView, p) = begin
  text, size = sketch_input(v).text, typed_shape(v).size
  x, y = v.asking
  to(n) = x + sketch_measure(first(text, n), size)
  (x - 4 <= p[1] <= to(length(text)) + 4 && y - size <= p[2] <= y + 0.3size) || return nothing
  argmin(n -> abs(to(n) - p[1]), 0:length(text))
end

"Start typing in the drawing: new words at `at`, or with `k` the `k`th shape's words, with the caret where `p` is in them"
type_words!(v::SketchView, at, k=0, p=at) = begin
  field = sketch_input(v)
  v.asking, v.editing = at, k
  field.text = k == 0 ? "" : v.data.shapes[k].text
  field.anchor = field.cursor = something(typed_index(v, p), length(field.text))
  field.last_action = time()
  v.picked = k   # so the colours and the size at the top are those of the words
  v.grab = nothing
  focus(field)
  handled
end

"Note a click at `(x, y)`. True when it's the second of two clicks in one place."
click_twice!(v::SketchView, x, y) = begin
  at, cx, cy = v.clicked
  v.clicked = (time(), x, y)
  time() - at < 0.35 && hypot(x - cx, y - cy) < 4
end

"""
Draw the words that are being typed where they will be in the drawing, in
their colour and at their size, with the caret after the place that the next
character goes in, and the colour of a selection behind the words that are
selected.
"""
draw_typing(ctx, v::SketchView, s) = begin
  field = sketch_input(v)
  shape = typed_shape(v)
  x, y = v.box[1] + v.asking[1] * s, v.box[2] + v.asking[2] * s
  tall = shape.size * s
  face = Face(SANS, "", px(tall), colours.ink, false)
  to(n) = x + num(measure(face, first(field.text, n)))
  lo, hi = minmax(field.anchor, field.cursor)
  lo == hi || round_box(ctx, to(lo), y - 0.95tall, to(hi) - to(lo), 1.25tall, 2.0, fill=colours.select)
  isempty(field.text) || draw_shape(ctx, shape, v.box[1], v.box[2], s)
  # The caret blinks, and it's lit just after a key
  mod(time() - field.last_action, 1.0) < 0.5 && trace(ctx, [(to(field.cursor), y - 0.9tall), (to(field.cursor), y + 0.2tall)], colours.accent, 1.5)
end

cursor(a::SketchArea) = begin
  v = a.of
  readonly(editor(v).buf) && return :arrow
  v.tool == :select || return v.tool == :text ? :ibeam : :crosshair
  v.grab !== nothing || handle_under(v, window_of(a)) !== nothing ? :hand : :arrow
end
cursor(::SketchView) = :arrow

onkey(a::SketchArea, ev::KeyPress{Keys.mouse_left}) = begin
  v, w = a.of, ev.window
  # A click draws in the page too. With ⌥ held, the page shows the block's lines.
  v.full || !only_held(v, Keys.opt) || return nothing
  readonly(editor(v).buf) && return handled
  p = sketch_place(v, w)
  twice = click_twice!(v, num(w.mouse[1]), num(w.mouse[2]))
  # A click on the words that are being typed puts the caret there
  if v.asking !== nothing && (n = typed_index(v, p)) !== nothing
    field = sketch_input(v)
    field.anchor = field.cursor = n
    field.last_action = time()
    return handled
  end
  answer!(v)          # words that were being typed are added where they are
  settle_number!(v)   # a number that was typed goes to the shape that it was typed for
  focus(a)
  k = Sketches.hit(v.data, p, 7.0, sketch_measure)
  words = k !== nothing && v.data.shapes[k].kind == :text
  if v.tool == :select
    # A circle of the shape that's selected is taken before a shape is
    h = handle_under(v, w)
    h === nothing || (k = v.picked)
    # Two clicks on words change them where they are
    h === nothing && words && twice && return type_words!(v, v.data.shapes[k].points[1], k, p)
    v.picked = something(k, 0)
    v.grab = k === nothing ? nothing : (p, false, something(h, 0))
  elseif v.tool == :text
    # A click on words changes them. Anywhere else, new words go where the click was: the middle of their height is at the mouse.
    words ? type_words!(v, v.data.shapes[k].points[1], k, p) : type_words!(v, (p[1], p[2] + 0.35v.next[:size]))
  else
    v.picked = 0
    v.draft = new_shape(v, v.tool, v.tool == :pen ? [p] : [p, p])
  end
  handled
end

onmouse(a::SketchArea, ev::MouseMove) = begin
  v, w = a.of, ev.window
  (v.draft === nothing && v.grab === nothing) && return nothing
  Keys.mouse_left in w.keys || return handled
  p = sketch_place(v, w)
  if v.draft !== nothing
    d = v.draft
    # A line drawn by hand gets a new place when the mouse has moved a little
    d.kind == :pen ? (hypot((p .- d.points[end])...) >= 1.5 && push!(d.points, p)) : (d.points[2] = p)
  elseif (shape = picked_shape(v)) !== nothing
    from, _, h = v.grab
    (p == from) && return handled
    # A circle goes where the mouse is, and takes its place of the shape with it. Without one, the whole shape moves.
    h == 0 ? Sketches.move!(shape, p[1] - from[1], p[2] - from[2]) : Sketches.pull!(shape, h, p)
    v.grab = (p, true, h)
  end
  handled   # the drag is the sketch's, so the page's text doesn't select
end

"The mouse let go. The shape that was drawn joins the sketch, and a shape that moved or changed is written down."
drop!(v::SketchView) = begin
  d, g = v.draft, v.grab
  v.draft = v.grab = nothing
  if d !== nothing
    d.kind == :pen && (d.points = Sketches.simplify(d.points))
    # A click without a drag draws nothing
    (d.kind == :pen ? length(d.points) < 2 : Sketches.slight(d)) && return v
    push!(v.data.shapes, d)
    commit!(v)
  elseif g !== nothing && g[2]
    commit!(v)
  end
  v
end

"""
Take the words that were typed. New words are added as a text shape, at the
place that was clicked. Words that were changed are written down, and taken
away when nothing is left of them.
"""
answer!(v::SketchView) = begin
  v.asking === nothing && return handled
  words = join(split(sketch_input(v).text), " ")
  p, k, old = v.asking, v.editing, edited_shape(v)
  stop_asking!(v)
  if old !== nothing
    isempty(words) ? (deleteat!(v.data.shapes, k); v.picked = 0) : (old.text = words)
    commit!(v)
  elseif k == 0 && !isempty(words)
    push!(v.data.shapes, new_shape(v, :text, [p], words))
    commit!(v)
  end
  handled
end

"Stop typing words into the drawing. New words are left out, and words that were being changed stay as they were. The keyboard goes back to the drawing."
stop_asking!(v::SketchView) = begin
  v.asking = nothing
  v.editing = 0
  v.tool == :select || (v.picked = 0)
  w = window_of(v)
  w !== nothing && w.focus === sketch_input(v) && focus(sketch_area(v))
  handled
end

# Return takes the number that was typed for how a shape is drawn, and Esc leaves the number as it was
onkey(v::SketchView, ev::KeyPress{Keys.enter}) = !unmodified(ev) ? nothing :
  v.typing !== nothing ? (settle_number!(v); focus(sketch_area(v)); handled) : v.asking === nothing ? nothing : answer!(v)
onkey(v::SketchView, ev::KeyPress{Keys.escape}) = !unmodified(ev) ? nothing :
  v.typing !== nothing ? (v.typing = nothing; focus(sketch_area(v)); handled) : v.asking === nothing ? nothing : stop_asking!(v)
onmouse(v::SketchView, ::MouseMove) = v.full || (held(v, Keys.mouse_left) && (v.draft !== nothing || v.grab !== nothing)) ? handled : nothing
# A click beside a button of a sketch that fills the window is the sketch's, and not the page's under it
onkey(v::SketchView, ::KeyPress{Keys.mouse_left}) = v.full ? (focus(sketch_area(v)); handled) : nothing

# The wheel over a sketch that fills the window scrolls a drawing that's taller than the window. It never
# scrolls the page under the sketch, which UI.jl would choose first. In the page, the wheel scrolls the page.
onscroll(a::SketchArea, ev::MouseScroll) = begin
  v = a.of
  v.full || return nothing
  list = get(v.parts, :list, nothing)
  list === nothing || (list.offset = clamp(list.offset - 30ev.delta[2], 0px, max(0px, px(v.box[4] - full_room(v)))))
  handled
end
onscroll(v::SketchView, ::MouseScroll) = v.full ? handled : nothing

block_tick!(v::SketchView) = begin
  (v.draft !== nothing || v.grab !== nothing) && !held(v, Keys.mouse_left) && drop!(v)
  # A click somewhere else took the keyboard from the words that were being typed. They're added.
  w = window_of(v)
  v.asking !== nothing && w !== nothing && w.focus !== sketch_input(v) && answer!(v)
  # The words that were being changed have gone, as after ⌘Z
  v.editing > 0 && edited_shape(v) === nothing && stop_asking!(v)
  v.asking === nothing || redraw_in!(v, 0.25)   # the caret blinks
  # A click in a number gave it the keyboard, and its text is selected so that typing takes its place.
  # A click somewhere else took the keyboard from it, and a number that was typed is kept.
  if w !== nothing
    at = findfirst(name -> w.focus === get(v.parts, (:number, name), nothing), keys(SKETCH_SETTINGS))
    name = at === nothing ? nothing : keys(SKETCH_SETTINGS)[at]
    if name != v.typing
      settle_number!(v)
      v.typing = name
      name === nothing || tabbed!(number_input(v, name))
    end
  end
  v
end

# Esc lets go of the shape that's selected, then chooses the arrow tool, then puts a sketch that fills the window
# back in the page, then gives the keyboard back to the text. In the page the page's text takes that Esc. Delete
# takes the shape away.
onkey(a::SketchArea, ev::KeyPress{Keys.escape}) = begin
  unmodified(ev) || return nothing
  v = a.of
  v.picked > 0 && return (v.picked = 0; handled)
  v.tool == :select || return (v.tool = :select; handled)
  v.full ? full!(v, false) : nothing
end
onkey(a::SketchArea, ::KeyPress{K}) where K = begin
  v = a.of
  K in (Keys.backspace, Keys.delete) && unmodified(window_of(a)) && return v.picked > 0 ? act!(v, :delete, window_of(a)) : handled
  if (command = command_of(editor(v), window_of(a), K)) in (:undo, :redo)
    b = editor(v).buf
    command == :redo ? redo!(b) : undo!(b)
    return handled
  end
  nothing
end

"The sketch as HTML: a picture of it"
sketch_html(e, v::SketchView) = begin
  isempty(v.data.shapes) && return nothing
  cs = css_colour.(SERIES_LIGHT)
  picture = Sketches.svg(v.data, colours=(ink="#2b2622", red=cs[8], blue=cs[1], green=cs[6], orange=cs[2]), family="-apple-system, Helvetica, sans-serif")
  "<div class=\"diagram\">\n$picture\n</div>"
end

BLOCKS[SKETCH] = BlockKind("Sketch", "pencil", SketchView, sketch_html)

# --- a canvas ---------------------------------------------------------------------------------
#
# A code block in the language `canvas` is a board of cards that you put
# anywhere, as in the app Muse. canvas.jl says how the block is written. In
# the page it shows the whole board, small, with its tools over it, and you
# change it there. Only the button beside its top right corner makes it fill
# the window, where it has more room. A click or a pinch never does. A page
# that can't change shows only the board.
#
#   - Two fingers on the trackpad move round the board, and so does a drag
#     on an empty place. A pinch, the mouse wheel, or two fingers with ⌘ held
#     make it bigger or smaller round the mouse. Fit shows the whole board.
#     In the page, the wheel and two fingers scroll the page past the board,
#     and only with ⌘ held do they make it bigger or smaller.
#   - Click twice on an empty place for a new note there, and type its words.
#     Return starts a new line in it. Esc or a click elsewhere ends the
#     typing, and a note with no words is taken away.
#   - Tab makes a new note to the right of the note that's selected or typed
#     in, joined to it by a line, as in a mind map. ⇧Return makes a new note
#     under it, joined to the same card that it's joined from.
#   - Click a card to select it, and drag it to move it. The circle on its
#     bottom right corner makes it wider or narrower. The circle beside its
#     right side draws a line from it: let go on another card to join the
#     two, or on an empty place for a new note that's joined to it. Click a
#     line to select it. Delete takes away what's selected.
#   - Click a note or a text twice to change its words where they are.
#   - The text tool writes words straight on the board, with no card round
#     them. The pen draws by hand. The dots choose the colour of the pen, and
#     of the text or the line drawn by hand that's selected.
#   - ⌘V puts in what the clipboard holds: a picture as a picture, a web
#     address as a card of the web page, a [[wiki link]] as a card of the
#     page, files from the Finder as a drop does, and other text as a note. A
#     picture or a Markdown file that's dropped from the Finder goes where
#     it's dropped. Add Picture asks for a file.
#   - A card of a page shows the page's first lines, or its own board when it
#     has one. Click it twice to open the page, with its board filling the
#     window. Back comes back here. Click a card of a web page twice to open
#     the page in the browser.
#   - Esc lets go of what's selected, then chooses the arrow. Then it gives
#     the keyboard back to the page's text, or puts a board that fills the
#     window back in the page.
#
# Each card is a line of the block, so ⌘Z takes back the last change.

const CANVAS = Canvases.CANVAS
"The tools of a canvas: the icon of each one's button, and what the button's tooltip says"
const CANVAS_TOOLS = ((:select, "cursor", "Select a card and drag it. Click twice to write a note."),
                      (:text, "type", "Write words on the board: click where they go"),
                      (:pen, "pencil", "Draw by hand"))
push!(BLOCK_ICONS, "sticky", "cursor", "type", "pencil", "image", "fullscreen", "fullscreen-exit", "trash", "dash", "plus")
const NOTE_PAD = 12.0            # the room round the words of a note, in the board's own measure
const CARD_ROUND = 6.0           # how round the corners of a card are
const NOTE_LEADING = 1.4         # how far apart the lines of a note are, for each of the size of its words
const TEXT_LEADING = 1.25        # and the lines of a text
const PAGE_HEAD = 34.0           # how tall the top of a card of a page is, where its name is
const PREVIEW_SIZE = 12.5        # how big the first lines of a page are on its card
const CANVAS_MOST = 420.0        # px: the most that a canvas in the page is tall
const CANVAS_LEAST = 160.0       # px: and the least
const CANVAS_ROOM = 32.0         # px: the room round the cards of a board that shows whole
const CANVAS_ZOOMS = (0.1, 4.0)  # the least and the most px of the window for each of the board's own measure
const CARD_KNOB = 5.0            # px: the radius of a circle that a drag changes a card with
const CARD_KNOB_REACH = 9.0      # px: how near the mouse is to a circle to drag it
"The sizes that the buttons for the size of a text's words go through"
const TEXT_SIZES = (10.0, 12.0, 14.0, 16.0, 20.0, 24.0, 28.0, 36.0, 48.0, 64.0, 80.0, 96.0, 128.0, 160.0, 200.0)
const MOST_GLANCE = 2_000_000    # bytes: a page that's bigger shows no lines on its card

"What a `canvas` block shows: a board of cards, and the tools that change it"
@def mutable struct CanvasView <: SemanticUI
  n::Int = 0                               # its place among the page's canvases
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Canvases.Canvas = Canvases.Canvas()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  tool::Symbol = :select
  colour::Symbol = :ink                    # the colour of the pen and of the next text
  size::Float64 = Canvases.TEXT_SIZE       # how big the words of the next text are
  picked::Any = nothing                    # the card, the line between cards or the line drawn by hand that's selected, or nothing
  # A drag: what it does (:move, :width, :join, :draw or :pan), where the mouse was last in the window, and whether it moved
  grab::Any = nothing
  draft::Any = nothing                     # the line that's being drawn by hand, or nothing
  reach::Any = nothing                     # the end of the line that's being drawn from a card, a place on the board, or nothing
  typing::Any = nothing                    # the note or the text whose words are being typed, or nothing
  fresh::Bool = false                      # it's new, so it goes when nothing is typed
  was::String = ""                         # its words before the typing
  clicked::NTuple{3,Float64} = (0.0, 0.0, 0.0)   # when and where the board was last clicked
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the board was last drawn in the window
  at::NTuple{2,Float64} = (0.0, 0.0)       # the place on the board at the top left corner of `box`
  zoom::Float64 = 0.0                      # px of the window for each of the board's own measure. 0 shows the whole board next.
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its buttons and its text field, kept between frames
  full::Bool = false                       # it fills the window, over the page
  tall::px = 0px                           # how tall it was in the page when it was last laid out there
  pinned::px = 0px                         # how far the page was scrolled when it filled the window
end

"The part of a canvas that the board is drawn in"
@def mutable struct CanvasArea <: SemanticUI
  of::Any = nothing
end
"A dot at the top of a canvas that chooses a colour"
@def mutable struct CanvasDot <: SemanticUI
  of::Any = nothing
  colour::Symbol = :ink
end

"What `x`, a card, a line between cards or a line drawn by hand of the canvas `old`, is in `new`: the one in its place there, or nothing"
same_in(old::Canvases.Canvas, new::Canvases.Canvas, x) = begin
  x === nothing && return nothing
  for (a, b) in ((old.cards, new.cards), (old.joins, new.joins), (old.strokes, new.strokes))
    i = findfirst(y -> y === x, a)
    i === nothing || return i <= length(b) ? b[i] : nothing
  end
  nothing
end

reread!(v::CanvasView, lines) = begin
  lines == v.lines && return v
  old = v.data
  v.lines = lines
  v.data = Canvases.canvas(lines)
  # What was selected is found again by its place, as after ⌘Z
  v.picked = same_in(old, v.data, v.picked)
  v.typing = same_in(old, v.data, v.typing)
  v
end

"Write the board into its block. Its lines are the ones that it holds now, so it isn't read again."
commit!(v::CanvasView) = (new = Canvases.written(v.data); v.lines = new; write_block!(v, CANVAS, new))

canvas_area(v::CanvasView) = block_part!(() -> CanvasArea(of=v), v, :area)
keyboard_part(v::CanvasView) = canvas_area(v)

"""
The text field that holds the words that are being typed into a note or a
text. It has the keyboard while they're typed, and it isn't shown: the board
shows its words in the card.
"""
canvas_input(v::CanvasView) = block_part!(v, :input) do
  TextInput(placeholder="", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"The colour of the board behind its cards"
canvas_back() = dark_page() ? colours.bg : colours.block
"The colour of a card"
card_back() = colours.float

# --- the size of a card ---------------------------------------------------------------------

"The face of words `size` big"
canvas_face(size, colour=colours.ink, style="") = Face(SANS, style, px(size), colour, false)

# The lines that each text took, kept, as each card's words are laid out on each frame
const card_wraps = Dict{Tuple{String,Float64,Float64,String},Vector{UnitRange{Int}}}()

"""
The lines that `text` takes when it has `room` across and its words are
`size` big: for each, the characters that it holds, counted from 1. A line
ends where the text has a new line, and where the next word wouldn't fit. A
word that's wider than the room is cut where it reaches the edge. With no
room, a line ends only where the text has a new line. The spaces after the
last word of a line are in that line.
"""
card_wrap(text::AbstractString, room, size, style="") = begin
  length(card_wraps) > 20_000 && empty!(card_wraps)
  get!(card_wraps, (String(text), Float64(room), Float64(size), style)) do
    cs = collect(text)
    face = canvas_face(size, colours.ink, style)
    wide(r) = num(measure(face, String(cs[r])))
    lines = UnitRange{Int}[]
    a = 1
    for b in [findall(==('\n'), cs); length(cs) + 1]   # each line of the text ends before a new line, or at the end
      start = a
      if room > 0
        k, space = start, 0   # the character that's looked at, and the last space of the line so far
        while k <= b - 1
          cs[k] == ' ' && (space = k)
          if cs[k] != ' ' && k > start && wide(start:k) > room
            stop = space >= start ? space : k - 1
            push!(lines, start:stop)
            start, k, space = stop + 1, stop + 1, 0
            continue
          end
          k += 1
        end
      end
      push!(lines, start:b-1)
      a = b + 1
    end
    lines
  end
end

"How wide the words of a note or a text can be, in the board's measure. A text with no width has no edge."
word_room(card) = card.kind == :note ? card.width - 2NOTE_PAD : card.width
"How big the words of a note or a text are"
word_size(card) = card.kind == :note ? Canvases.NOTE_SIZE : card.size
"How far apart the lines of a note or a text are"
word_lead(card) = word_size(card) * (card.kind == :note ? NOTE_LEADING : TEXT_LEADING)
"Where the words of a note or a text start, from its top left corner"
word_inset(card) = card.kind == :note ? (NOTE_PAD, NOTE_PAD) : (0.0, 0.0)

"The lines of the words of a note or a text, as the board shows them"
card_lines(card, text=card.content) = (cs = collect(text); [String(rstrip(String(cs[r]))) for r in card_wrap(text, word_room(card), word_size(card))])

"The file of a picture card: its path from `dir`, the folder of its page, or a whole path"
card_file(card, dir) = (p = expanduser(card.content); isabspath(p) ? p : normpath(joinpath(dir, p)))

"""
How big a card is, in the board's own measure: its width and its height. `dir`
is the folder of the page whose board it's on, where the path of a picture
starts.
"""
card_size(e, card::Canvases.Card, dir=docdir(e)) = begin
  k = card.kind
  if k == :note
    (card.width, 2NOTE_PAD + length(card_lines(card)) * word_lead(card))
  elseif k == :text
    lines = card_lines(card)
    face = canvas_face(card.size)
    (card.width > 0 ? card.width : max(card.size, maximum(l -> num(measure(face, l)), lines, init=0.0)), length(lines) * word_lead(card))
  elseif k == :picture
    key = picture_key(card_file(card, dir))
    (card.width, round(card.width / (key === nothing ? 1.5 : image_aspect(key))))
  elseif k == :page
    (card.width, page_card_tall(e, card))
  else
    (card.width, link_card_tall(e, card))
  end
end
card_size(v::CanvasView, card::Canvases.Card) = card_size(editor(v), card)

# What a card of a page shows, kept under the page's path with when the file last changed
const page_glances = Dict{String,Any}()

"The words of a line of Markdown without its marks: no list mark, no * or _ or `, and a link as its words"
plain_words(s::AbstractString) = begin
  s = replace(s, r"^(?:[-*+]\s+(?:\[[ xX]\]\s+)?|\d+[.)]\s+|>\s*)+" => "")
  s = replace(s, r"!?\[([^\]]*)\]\([^)]*\)" => s"\1")
  s = replace(s, r"\[\[([^\]|]*)(?:\|[^\]]*)?\]\]" => s"\1")
  String(strip(replace(s, r"[*_`]+" => "")))
end

"""
What a card of the page called `name` shows: the page's `path`, its `title`,
its first `lines` of words, its own `board`, which is the first canvas in it,
or nothing, and whether it's `there`. It's kept until the file changes.
"""
page_glance(e, name) = begin
  path = wiki_path(e, name)
  t = isfile(path) ? mtime(path) : -1.0
  kept = get(page_glances, path, nothing)
  kept !== nothing && kept[1] == t && return kept[2]
  text = t < 0 || filesize(path) > MOST_GLANCE ? "" : try read(path, String) catch; "" end
  title, titled, lines, board = splitext(basename(name))[1], false, String[], nothing
  fence, block, top = "", String[], false   # the code block that a line is in, its lines, and whether it's in the front matter
  for (i, line) in enumerate(split(text, '\n'))
    s = strip(line)
    i == 1 && s == "---" && (top = true; continue)
    top && (s == "---" && (top = false); continue)
    if startswith(s, "```") || startswith(s, "~~~")
      if fence == ""
        fence = "~" * lowercase(strip(s[4:end]))   # never "", even for a block with no language
      else
        fence == "~" * CANVAS && board === nothing && (board = Canvases.canvas(block))
        fence = ""
        empty!(block)
      end
      continue
    end
    fence == "" || (push!(block, line); continue)
    isempty(s) && continue
    startswith(s, "# ") && !titled && ((title, titled) = (String(strip(s[3:end])), true); continue)
    startswith(s, "#") && continue
    length(lines) < 3 && push!(lines, plain_words(s))
  end
  g = (path=path, title=title, lines=lines, board=board, there=t >= 0)
  page_glances[path] = (t, g)
  g
end

"How tall a card of a page is: its top, and its board or its first lines under that"
page_card_tall(e, card) = begin
  g = page_glance(e, card.content)
  g.board === nothing || return PAGE_HEAD + round(card.width * 0.6)
  PAGE_HEAD + max(1, length(g.lines)) * PREVIEW_SIZE * NOTE_LEADING + 10
end

"What's known of the web page at `url`: its title, its picture and the name of its site. It asks for the next frame while that's on its way."
link_glance(e, url) = (got = Cards.lookup!(url, cards_dir(), ask=online(e)); got[2] && redraw_in!(e, 0.2); got[1])

"The words at the top of a card of a web page: its title, or the name of its computer"
link_title(c, card) = isempty(c.title) ? Cards.host(card.content) : c.title

"How tall a card of a web page is: its picture, two lines of its title at most, and its site"
link_card_tall(e, card) = begin
  c = link_glance(e, card.content)
  n = min(2, length(card_wrap(link_title(c, card), card.width - 2NOTE_PAD, Canvases.NOTE_SIZE, "Semibold")))
  (isempty(c.image) ? 0.0 : round(card.width / 1.91)) + 2NOTE_PAD + n * Canvases.NOTE_SIZE * NOTE_LEADING + 16
end

# --- where things are -----------------------------------------------------------------------

"The place on the board at the place `(x, y)` in the window"
board_place(v::CanvasView, x, y) = (v.at[1] + (x - v.box[1]) / v.zoom, v.at[2] + (y - v.box[2]) / v.zoom)
"The place in the window of the place `p` on the board"
window_place(v::CanvasView, p) = (v.box[1] + (p[1] - v.at[1]) * v.zoom, v.box[2] + (p[2] - v.at[2]) * v.zoom)
"The place on the board under the mouse"
mouse_place(v::CanvasView, w) = board_place(v, num(w.mouse[1]), num(w.mouse[2]))
"The place on the board in the middle of what shows of it"
board_middle(v::CanvasView) = board_place(v, v.box[1] + v.box[3] / 2, v.box[2] + v.box[4] / 2)

"What the board holds: its left, top, right and bottom. An empty board is a small one."
board_extent(v::CanvasView) = something(Canvases.extent(v.data, c -> card_size(v, c)), (0.0, 0.0, 480.0, 200.0))

"Show the whole board in a box `w` by `h` px: no bigger than its own size, and in the middle"
fit_board!(v::CanvasView, w, h) = begin
  l, t, r, b = board_extent(v)
  m = CANVAS_ROOM
  v.zoom = clamp(min((w - 2m) / max(r - l, 1.0), (h - 2m) / max(b - t, 1.0), 1.0), CANVAS_ZOOMS[1], 1.0)
  v.at = ((l + r) / 2 - w / 2 / v.zoom, (t + b) / 2 - h / 2 / v.zoom)
  v
end

"How tall the board is in the page, in px: as tall as its cards need at the width of the page, between the least and the most"
page_tall(v::CanvasView) = begin
  l, t, r, b = board_extent(v)
  w = num(editor(v).width) - 2
  z = min(1.0, (w - 2CANVAS_ROOM) / max(r - l, 1.0))
  clamp((b - t) * z + 2CANVAS_ROOM, CANVAS_LEAST, CANVAS_MOST)
end

"Make the board `by` times as big. The place on the board at `(x, y)` in the window stays there."
zoom_board!(v::CanvasView, by, x, y) = begin
  v.zoom > 0 || return handled
  p = board_place(v, x, y)
  v.zoom = clamp(v.zoom * by, CANVAS_ZOOMS...)
  v.at = (p[1] - (x - v.box[1]) / v.zoom, p[2] - (y - v.box[2]) / v.zoom)
  handled
end

"Move the board, if it must, so that all of `card` shows"
show_place!(v::CanvasView, card) = begin
  v.zoom > 0 || return v
  x, y = window_place(v, card.at)
  w, h = card_size(v, card) .* v.zoom
  l, t, bw, bh = v.box
  m = 40.0
  shift(lo, hi, from, to) = lo < from + m ? lo - from - m : hi > to - m ? min(hi - to + m, lo - from - m) : 0.0
  dx, dy = shift(x, x + w, l, l + bw), shift(y, y + h, t, t + bh)
  v.at = (v.at[1] + dx / v.zoom, v.at[2] + dy / v.zoom)
  v
end

"The card at the place `p` on the board, or nothing. `reach` is in px of the window."
card_under(v::CanvasView, p; reach=0.0) = v.zoom > 0 ? Canvases.card_at(v.data, p, c -> card_size(v, c); reach=reach / v.zoom) : nothing

"Where the circle that makes a card wider is in the window: on its bottom right corner"
width_knob(v::CanvasView, card) = (wh = card_size(v, card); window_place(v, card.at .+ wh))
"Where the circle that draws a line from a card is in the window: a little right of the middle of its right side"
join_knob(v::CanvasView, card) = (wh = card_size(v, card); q = window_place(v, (card.at[1] + wh[1], card.at[2] + wh[2] / 2)); (q[1] + 12, q[2]))

"""
The circle under the place `(x, y)` in the window: what a drag of it does,
`:width` or `:join`, and its card. The card that's selected has both, and
the card that the mouse is near has the circle that joins. Nothing when no
circle is there.
"""
knob_under(v::CanvasView, x, y) = begin
  (v.zoom > 0 && v.tool == :select) || return nothing
  near(q) = hypot(q[1] - x, q[2] - y) <= CARD_KNOB_REACH
  p = v.picked
  if p isa Canvases.Card && p !== v.typing
    near(width_knob(v, p)) && return (:width, p)
    near(join_knob(v, p)) && return (:join, p)
  end
  card = card_under(v, board_place(v, x, y), reach=2CARD_KNOB_REACH + 12)
  card !== nothing && card !== v.typing && near(join_knob(v, card)) ? (:join, card) : nothing
end

# --- in the page and in the window ----------------------------------------------------------

"The text whose size the buttons at the top change: the one that's typed in or selected, or nothing"
sized_text(v::CanvasView) = begin
  for p in (v.typing, v.picked)
    p isa Canvases.Card && p.kind == :text && return p
  end
  nothing
end

"What a colour that's chosen goes to: the text that's typed in or selected, or the line drawn by hand that's selected, or nothing"
colour_target(v::CanvasView) = begin
  t = sized_text(v)
  t !== nothing ? t : v.picked isa Sketches.Shape ? v.picked : nothing
end

"The buttons that make the words of a text smaller or bigger, while the text tool is chosen or a text is selected"
text_sizes_bar(v::CanvasView) = begin
  card = sized_text(v)
  (v.tool == :text || card !== nothing) || return ()
  n = card === nothing ? v.size : card.size
  (rule(),
   block_button!(v, :smaller, (:size, false), icon="dash", tip="Make the words smaller", off=n <= TEXT_SIZES[1]),
   Box(fixed(30px), height(26px), Alignment.Center, justify=Alignment.Center, label(Sketches.figure(n), 12px, color=colours.dim)),
   block_button!(v, :bigger, (:size, true), icon="plus", tip="Make the words bigger", off=n >= TEXT_SIZES[end]))
end

"The page that a card of a page opened, whose first canvas fills the window when it's laid out"
const canvas_to_fill = Ref("")

describe(v::CanvasView) = begin
  e = editor(v)
  canvas_to_fill[] == e.buf.path && redraw_in!(v, 0.02)   # its first canvas fills the window on the next frame
  with_theme(component_theme(e.zoom)) do
    # In the page, a page that can't change shows only the whole board, small
    v.full || !readonly(e.buf) ||
      return Box(width(grow=grow), Alignment.Start, fillable(v, (:block, v), Column(block_look()..., clip=true, name="Canvas", canvas_area(v)), wide=:grow))
    tools = [block_button!(v, tool, (:tool, tool), icon=icon, tip=tip, on=v.tool == tool) for (tool, icon, tip) in CANVAS_TOOLS]
    dots = [block_part!(() -> CanvasDot(of=v, colour=c), v, (:ink, c)) for c in Canvases.COLOURS]
    picked = v.picked === nothing ? () : (block_button!(v, :delete, :delete, icon="trash", tip="Take away what's selected  Delete"),)
    # The last button puts a board that fills the window back in the page. In the page, the button beside its top
    # right corner makes it fill the window.
    full = v.full ? (block_button!(v, :full, :full, icon="fullscreen-exit", tip="Back to the page  esc"),) : ()
    bar = block_bar(tools..., rule(), dots..., text_sizes_bar(v)..., rule(),
                    block_button!(v, :picture, :picture, icon="image", words="Add Picture…", tip="Put a picture from a file on the board"),
                    block_button!(v, :fit, :fit, icon="fullscreen", words="Fit", tip="Show the whole board"),
                    Box(width(grow=grow)), picked..., full...)
    # In the page its tools are over the board, so that you change it where it is
    v.full || return Box(width(grow=grow), Alignment.Start, fillable(v, (:block, v), Column(block_look()..., clip=true, name="Canvas", bar, canvas_area(v)), wide=:grow))
    Column(width(grow=grow), height(grow=grow), Alignment.Start, background(canvas_back()), name="Canvas", bar, canvas_area(v))
  end
end

# In the page it's as tall as the board needs. In the window it takes all the room under its buttons.
describe(a::CanvasArea) = (v = a.of; Box(width(grow=grow), v.full ? height(grow=grow) : height(px(page_tall(v)))))

"""
Make the canvas fill the window, or put it back in the page. In the page it
shows the whole board, so words that were being typed are kept, nothing is
selected, and the keyboard goes back to the text.
"""
full!(v::CanvasView, on::Bool) = begin
  e = editor(v)
  # One block at a time fills the window. A canvas of the page that a card of a page came from still fills it
  # when Back goes there.
  on && for (key, node) in e.nodes
    filling(node) && key isa Tuple && (key[1] == :block ? key[3] : key[2]) == e.buf.path && (node.full = false)
  end
  on || (finish_typing!(v); v.picked = v.grab = v.draft = v.reach = nothing)
  v.full = on
  v.pinned = e.scroll.offset
  v.zoom = 0.0   # it's another size now, so it shows the whole board
  v.box = (0.0, 0.0, 0.0, 0.0)
  on ? focus(canvas_area(v)) : focus(e)
  handled
end

# A pinch on a canvas in the page makes its board bigger or smaller there: see `onpinch(::CanvasArea, ...)`. It doesn't make
# it fill the window. Only the button beside its top right corner does.
onpinch(::CanvasView, ::Pinch) = nothing

act!(v::CanvasView, action, w) = begin
  # A button for the size of the words changes the words that are being typed, and they stay open. Any other button keeps them.
  (action isa Tuple && action[1] == :size) || finish_typing!(v)
  if action == :delete
    delete_picked!(v)
  elseif action == :full
    return full!(v, !v.full)
  elseif action == :fit
    v.zoom = 0.0
  elseif action == :picture
    return choose_pictures!(v, w)
  elseif action[1] == :tool
    v.tool = action[2]
    v.tool == :select || (v.picked = nothing)
  elseif action[1] == :size
    resize_text!(v, action[2])
  end
  focus(v.typing === nothing ? canvas_area(v) : canvas_input(v))
  handled
end

"Make the words of the text that's typed in or selected, and of the next text, the next size up or down"
resize_text!(v::CanvasView, up) = begin
  card = sized_text(v)
  n = card === nothing ? v.size : card.size
  i = up ? findfirst(s -> s > n + 0.01, TEXT_SIZES) : findlast(s -> s < n - 0.01, TEXT_SIZES)
  i === nothing && return v
  v.size = TEXT_SIZES[i]
  card === nothing && return v
  card.size = v.size
  card === v.typing || commit!(v)   # words that are being typed are written when the typing ends
  v
end

describe(::CanvasDot) = Box(fixed(22px), height(26px), name="Colour")

# The dot and the ring round it are drawn about the middle of the dot's box, as a sketch draws them
draw(ctx, size, ui::ConcreteRect, d::CanvasDot) = begin
  v = d.of
  t = colour_target(v)
  on = (t === nothing ? v.colour : t.colour) == d.colour
  x, y = Float32(num(ui.left + ui.width / 2)), Float32(num(ui.top + ui.height / 2))
  disc(colour, r, wide=0.0) = (paint = ink(colour, wide); Skia.sk_canvas_draw_circle(ctx, x, y, Float32(r), paint); Skia.sk_paint_delete(paint))
  disc(sketch_colour(d.colour), 5)
  (on || ishovered(d)) && disc(on ? colours.accent : colours.marker, 7.25, 1.5)
end

cursor(::CanvasDot) = :hand

# A click on a colour gives it to the pen, to the next text, and to the text or the line drawn by hand that's selected
onkey(d::CanvasDot, ::KeyPress{Keys.mouse_left}) = begin
  v = d.of
  v.colour = d.colour
  t = colour_target(v)
  t === nothing || (t.colour = d.colour; t === v.typing || commit!(v))
  focus(v.typing === nothing ? canvas_area(v) : canvas_input(v))   # words that are being typed keep the keyboard
  handled
end

# --- drawing ----------------------------------------------------------------------------------

"Draw the soft shadow under a card at `(x, y)` in the window that's `w` by `h`, with corners `r` round. `z` is how big the board shows."
card_shadow(ctx, x, y, w, h, r, z) = begin
  paint = ink(RGBA(0, 0, 0, dark_page() ? 0.4 : 0.11))
  blur = Skia.sk_maskfilter_new_blur_with_flags(Skia.SK_BLUR_STYLE_NORMAL, Float32(1 + 3min(z, 1.0)), true)
  Skia.sk_paint_set_maskfilter(paint, blur)
  shape = Skia.sk_path_new()
  rect = Ref(Skia.sk_rect_t(Float32(x), Float32(y + 1.5min(z, 1.0)), Float32(x + w), Float32(y + h + 1.5min(z, 1.0))))
  Skia.sk_path_add_rounded_rect(shape, rect, Float32(r), Float32(r), Skia.SK_PATH_DIRECTION_CW)
  Skia.sk_canvas_draw_path(ctx, shape, paint)
  Skia.sk_path_delete(shape)
  Skia.sk_maskfilter_unref(blur)
  Skia.sk_paint_delete(paint)
end

"Draw a card's paper: its shadow, its colour and a thin line round it"
card_paper(ctx, x, y, w, h, z) = begin
  r = CARD_ROUND * z
  card_shadow(ctx, x, y, w, h, r, z)
  round_box(ctx, x, y, w, h, r, fill=card_back(), line=colours.line, wide=0.75)
end

"How far down from the top of its line the words of a line stand, when they're `size` big and the lines are `lead` apart"
line_foot(size, lead) = (lead - size) / 2 + 0.84size

"""
Draw `lines` of words from `(x, y)` in the window, `size` px big and `lead` px
apart. Words too small to read are a faint bar each, as long as the words.
`room` is how big the words are in the board's own measure, for that.
"""
draw_words(ctx, lines, x, y, size, lead, colour; style="", room=size) = begin
  if size < 3.5
    face = canvas_face(room, colour, style)
    k = size / room
    for (i, line) in enumerate(lines)
      isempty(line) && continue
      round_box(ctx, x, y + (i - 1) * lead + 0.3lead, num(measure(face, line)) * k, 0.4lead, 0.2lead, fill=RGBA(colour, 0.25))
    end
    return
  end
  face = canvas_face(size, colour, style)
  for (i, line) in enumerate(lines)
    isempty(line) || write_ink(ctx, line, x, y + (i - 1) * lead + line_foot(size, lead), face)
  end
end

"`text`, cut short with … to be no wider than `room` in `face`"
cut_to(face, text, room) = begin
  num(measure(face, text)) <= room && return String(text)
  cs = collect(text)
  lo, hi = 0, length(cs)
  while lo < hi   # the most characters that fit before the …
    mid = (lo + hi + 1) ÷ 2
    num(measure(face, String(cs[1:mid]) * "…")) <= room ? (lo = mid) : (hi = mid - 1)
  end
  String(cs[1:lo]) * "…"
end

"Draw the line between two cards through the four places of a curve, which are in the window"
draw_join(ctx, (a, b, c, d), colour, wide) = begin
  paint = ink(colour, wide)
  path = Skia.sk_path_new()
  Skia.sk_path_move_to(path, Float32(a[1]), Float32(a[2]))
  Skia.sk_path_cubic_to(path, Float32(b[1]), Float32(b[2]), Float32(c[1]), Float32(c[2]), Float32(d[1]), Float32(d[2]))
  Skia.sk_canvas_draw_path(ctx, path, paint)
  Skia.sk_path_delete(path)
  Skia.sk_paint_delete(paint)
end

"""
Draw a card of a board whose place 0,0 is at `(x0, y0)` in the window, `z`
px for each of the board's measure. `dir` is the folder of the board's page.
`depth` is how many boards it's inside: a card of a page shows its own board
only on the board that fills the window or shows in the page.
"""
draw_card(ctx, e, card, x0, y0, z, dir; depth=0) = begin
  w, h = card_size(e, card, dir)
  x, y, W, H = x0 + card.at[1] * z, y0 + card.at[2] * z, w * z, h * z
  k = card.kind
  if k == :text
    draw_words(ctx, card_lines(card), x, y, card.size * z, word_lead(card) * z, sketch_colour(card.colour), room=card.size)
  elseif k == :note
    card_paper(ctx, x, y, W, H, z)
    draw_words(ctx, card_lines(card), x + NOTE_PAD * z, y + NOTE_PAD * z, Canvases.NOTE_SIZE * z, word_lead(card) * z, colours.ink, room=Canvases.NOTE_SIZE)
  elseif k == :picture
    key = picture_key(card_file(card, dir))
    if key === nothing
      card_paper(ctx, x, y, W, H, z)
      face = canvas_face(PREVIEW_SIZE)
      words = ["No picture at", cut_to(face, card.content, w - 2NOTE_PAD)]
      draw_words(ctx, words, x + NOTE_PAD * z, y + NOTE_PAD * z, PREVIEW_SIZE * z, PREVIEW_SIZE * NOTE_LEADING * z, colours.dim, room=PREVIEW_SIZE)
    else
      card_shadow(ctx, x, y, W, H, 3z, z)
      image = image_source(key)
      with_round_clip(() -> paint_picture(ctx, image.raw, (0, 0, image.width, image.height), (x, y, W, H)), ctx, px(x), px(y), px(W), px(H), px(3z))
    end
  elseif k == :page
    draw_page_card(ctx, e, card, w, x, y, z, H, depth)
  else
    draw_link_card(ctx, e, card, w, x, y, z, H)
  end
end

"Draw a card of a page, `w` wide in the board's measure, at `(x, y)` in the window, and `H` px tall"
draw_page_card(ctx, e, card, w, x, y, z, H, depth) = begin
  g = page_glance(e, card.content)
  W = w * z
  card_paper(ctx, x, y, W, H, z)
  pad = NOTE_PAD * z
  # A small sheet of paper before its title
  round_box(ctx, x + pad, y + (PAGE_HEAD - 13) / 2 * z, 10z, 13z, 1.5z, line=colours.dim, wide=max(0.5, 1.2z))
  size = 13.5
  title = cut_to(canvas_face(size, colours.ink, "Semibold"), g.title, w - 2NOTE_PAD - 16)
  draw_words(ctx, [title], x + pad + 16z, y + (PAGE_HEAD - size * 1.3) / 2 * z, size * z, size * 1.3z, g.there ? colours.ink : colours.dim, style="Semibold", room=size)
  top = y + PAGE_HEAD * z
  if g.board !== nothing
    inner = (x + 6z, top, W - 12z, H - PAGE_HEAD * z - 6z)
    round_box(ctx, inner..., 4z, fill=canvas_back())
    depth == 0 && with_round_clip(() -> draw_inner_board(ctx, e, g.board, dirname(g.path), inner), ctx, px.(inner)..., px(4z))
  else
    trace(ctx, [(x, top), (x + W, top)], colours.line, max(0.5, 0.75z))
    face = canvas_face(PREVIEW_SIZE)
    lines = !g.there ? ["No page yet. Click twice to make it."] : isempty(g.lines) ? ["No words yet"] : g.lines
    draw_words(ctx, [cut_to(face, l, w - 2NOTE_PAD) for l in lines], x + pad, top + 5z, PREVIEW_SIZE * z, PREVIEW_SIZE * NOTE_LEADING * z, colours.dim, room=PREVIEW_SIZE)
  end
end

"Draw a card of a web page: its picture at the top, its title and its site under that"
draw_link_card(ctx, e, card, w, x, y, z, H) = begin
  c = link_glance(e, card.content)
  W = w * z
  card_paper(ctx, x, y, W, H, z)
  top = y
  key = isempty(c.image) ? "" : card_picture(e, c.image)
  if !isempty(c.image)
    tall = round(w / 1.91) * z
    if !isempty(key)
      image = image_source(key)
      # The picture covers its room, and what doesn't fit is cut off
      s = max(W / image.width, tall / image.height)
      from = ((image.width - W / s) / 2, (image.height - tall / s) / 2, W / s, tall / s)
      with_round_clip(() -> paint_picture(ctx, image.raw, from, (x, y, W, tall)), ctx, px(x), px(y), px(W), px(tall + CARD_ROUND * z), px(CARD_ROUND * z))
    end
    top += tall
  end
  pad = NOTE_PAD * z
  size = Canvases.NOTE_SIZE
  rows = card_lines_of(link_title(c, card), w - 2NOTE_PAD, size, "Semibold")
  length(rows) > 2 && (rows = [rows[1], cut_to(canvas_face(size, colours.ink, "Semibold"), rows[2] * " " * join(rows[3:end], " "), w - 2NOTE_PAD)])
  draw_words(ctx, rows, x + pad, top + pad, size * z, size * NOTE_LEADING * z, colours.ink, style="Semibold", room=size)
  # A page with no title shows the name of its computer at the top, and its whole address under that
  site = isempty(c.title) ? replace(card.content, r"^https?://(www\.)?"i => "") : isempty(c.site) ? Cards.host(card.content) : c.site
  draw_words(ctx, [cut_to(canvas_face(12.0), site, w - 2NOTE_PAD)], x + pad, top + pad + length(rows) * size * NOTE_LEADING * z + 2z, 12z, 14z, colours.dim, room=12.0)
end

"The lines that `text` takes `room` across, with words `size` big in the style `style`"
card_lines_of(text, room, size, style="") = (cs = collect(text); [String(rstrip(String(cs[r]))) for r in card_wrap(text, room, size, style)])

"Draw the board of another page small, to fit `(x, y, w, h)` in the window"
draw_inner_board(ctx, e, board, dir, (x, y, w, h)) = begin
  size(c) = card_size(e, c, dir)
  ext = Canvases.extent(board, size)
  ext === nothing && return
  l, t, r, b = ext
  m = 8.0
  z = min((w - 2m) / max(r - l, 1.0), (h - 2m) / max(b - t, 1.0), 1.0)
  draw_board_ink(ctx, e, board, dir, x + w / 2 - (l + r) / 2 * z, y + h / 2 - (t + b) / 2 * z, z, depth=1)
end

"""
Draw what a board holds: the lines between cards under the cards, then the
cards, then the lines drawn by hand over them. The board's place 0,0 is at
`(x0, y0)` in the window, and `z` px are one of its measure. What's `picked`
is in the colour of a selection.
"""
draw_board_ink(ctx, e, data, dir, x0, y0, z; depth=0, picked=nothing) = begin
  size(c) = card_size(e, c, dir)
  at(p) = (x0 + p[1] * z, y0 + p[2] * z)
  wide = clamp(1.4z, 0.6, 2.2)
  for j in data.joins
    curve = Canvases.join_curve(Canvases.edges(j[1], size(j[1])), Canvases.edges(j[2], size(j[2])))
    draw_join(ctx, at.(curve), j === picked ? colours.accent : colours.dim, j === picked ? wide + 1 : wide)
  end
  foreach(card -> draw_card(ctx, e, card, x0, y0, z, dir; depth), data.cards)
  for s in data.strokes
    s === picked && draw_shape(ctx, s, x0, y0, z, glow=true)
    draw_shape(ctx, s, x0, y0, z)
  end
end

"Draw a circle that a drag changes a card with, at `(x, y)` in the window. The one under the mouse is filled."
draw_knob(ctx, (x, y), hot) = for paint in (ink(hot ? colours.accent : card_back()), ink(colours.accent, 1.5))
  Skia.sk_canvas_draw_circle(ctx, Float32(x), Float32(y), Float32(CARD_KNOB), paint)
  Skia.sk_paint_delete(paint)
end

"""
Draw what shows only while the board fills the window: the line round the
card that's selected, its circles, the circle that joins the card that the
mouse is near, the line that's being drawn from a card, and the words that are
being typed with their caret.
"""
draw_canvas_marks(ctx, v::CanvasView) = begin
  w = window_of(v)
  mx, my = w === nothing ? (-1e9, -1e9) : (num(w.mouse[1]), num(w.mouse[2]))
  hot = v.grab === nothing ? knob_under(v, mx, my) : v.grab[1] in (:width, :join) ? (v.grab[1], v.picked) : nothing
  p = v.picked
  if p isa Canvases.Card
    x, y = window_place(v, p.at)
    W, H = card_size(v, p) .* v.zoom
    round_box(ctx, x - 2, y - 2, W + 4, H + 4, CARD_ROUND * v.zoom + 2, line=colours.accent, wide=2.0)
    if p !== v.typing && v.tool == :select
      draw_knob(ctx, width_knob(v, p), hot == (:width, p))
      draw_knob(ctx, join_knob(v, p), hot == (:join, p))
    end
  end
  # The card that the mouse is near shows the circle that draws a line from it
  hot !== nothing && hot[2] !== p && draw_knob(ctx, join_knob(v, hot[2]), true)
  if v.reach !== nothing && p isa Canvases.Card
    target = card_under(v, v.reach)
    to = target === nothing || target === p ? (v.reach..., v.reach...) : Canvases.edges(target, card_size(v, target))
    draw_join(ctx, map(q -> window_place(v, q), Canvases.join_curve(Canvases.edges(p, card_size(v, p)), to)), colours.accent, 2.0)
    if target !== nothing && target !== p
      x, y = window_place(v, target.at)
      W, H = card_size(v, target) .* v.zoom
      round_box(ctx, x - 2, y - 2, W + 4, H + 4, CARD_ROUND * v.zoom + 2, line=RGBA(colours.accent, 0.5), wide=2.0)
    end
  end
  v.typing === nothing || draw_caret(ctx, v)
end

"Draw the selection and the caret of the words that are being typed, where they are in their card"
draw_caret(ctx, v::CanvasView) = begin
  card, field, z = v.typing, canvas_input(v), v.zoom
  cs = collect(field.text)
  lines = card_wrap(field.text, word_room(card), word_size(card))
  x, y = window_place(v, card.at .+ word_inset(card))
  lead = word_lead(card) * z
  face = canvas_face(word_size(card))
  wide(r) = num(measure(face, String(cs[r]))) * z
  lo, hi = minmax(field.anchor, field.cursor)
  for (i, r) in enumerate(lines)
    a, b = max(first(r) - 1, lo), min(last(r), hi)
    a < b && round_box(ctx, x + wide(first(r):a), y + (i - 1) * lead, wide(a+1:b), lead, 2.0, fill=RGBA(colours.select, 0.6))
  end
  # The caret blinks, and it's lit just after a key
  mod(time() - field.last_action, 1.0) < 0.5 || return
  i = caret_line(lines, field.cursor)
  cx, top = x + wide(first(lines[i]):field.cursor), y + (i - 1) * lead
  trace(ctx, [(cx, top + 0.12lead), (cx, top + 0.88lead)], colours.accent, 1.5)
end

draw(ctx, size, ui::ConcreteRect, a::CanvasArea) = begin
  v = a.of
  e = editor(v)
  was = v.box
  v.box = (num(ui.left), num(ui.top), num(ui.width), num(ui.height))
  (v.box[3] > 0 && v.box[4] > 0) || return
  sync_typing!(v)
  # It shows the whole board when it first shows, and after Fit. In the page it shows it whole again when the page
  # gets wider or narrower. Otherwise it stays as big as a pinch or the wheel made it, so a card that's dragged
  # stays under the mouse.
  (v.zoom <= 0 || (!v.full && was[3] != v.box[3])) && fit_board!(v, v.box[3], v.box[4])
  with_clip(ctx, ui.left, ui.top, ui.width, ui.height) do
    round_box(ctx, v.box..., 0, fill=canvas_back())
    isempty(v.data.cards) && isempty(v.data.strokes) && v.draft === nothing &&
      write_ink(ctx, readonly(e.buf) ? "Nothing is on this board" : "Click twice to write a note, or paste a picture, a link or a page",
                v.box[1] + 16, v.box[2] + 28, Face(SANS, "", 13px, colours.faint, false))
    x0, y0 = v.box[1] - v.at[1] * v.zoom, v.box[2] - v.at[2] * v.zoom
    draw_board_ink(ctx, e, v.data, docdir(e), x0, y0, v.zoom; picked=v.picked)
    v.draft === nothing || draw_shape(ctx, v.draft, x0, y0, v.zoom)
    draw_canvas_marks(ctx, v)
  end
end

# --- typing -------------------------------------------------------------------------------------

"The number of the line among `lines`, which `card_wrap` gives, that the caret after `n` characters is on"
caret_line(lines, n) = something(findlast(r -> first(r) - 1 <= n <= last(r), lines), length(lines))

"""
The place among the characters of `text`, as the note or the text `card`
shows it, that's nearest to `p`, a place on the board.
"""
index_near(card, text, p) = begin
  cs = collect(text)
  lines = card_wrap(text, word_room(card), word_size(card))
  dx, dy = word_inset(card)
  i = clamp(floor(Int, (p[2] - card.at[2] - dy) / word_lead(card)) + 1, 1, length(lines))
  r = lines[i]
  face = canvas_face(word_size(card))
  # The space at the end of a line that wraps belongs to it, but the caret goes before it
  soft = i < length(lines) && last(r) + 1 == first(lines[i+1])
  ns = first(r)-1:max(first(r) - 1, soft ? last(r) - 1 : last(r))
  argmin(n -> abs(num(measure(face, String(cs[first(r):n]))) - (p[1] - card.at[1] - dx)), ns)
end

"The place among the characters that are being typed that's nearest to `p`, a place on the board, or nothing when `p` is off their card"
typed_place(v::CanvasView, p) = begin
  card = v.typing
  card === nothing && return nothing
  Canvases.inside(p, Canvases.edges(card, card_size(v, card)), 4 / v.zoom) || return nothing
  index_near(card, canvas_input(v).text, p)
end

"While words are typed, the card holds them, so that it's as big as they need"
sync_typing!(v::CanvasView) = (v.typing === nothing || (v.typing.content = canvas_input(v).text); v)

"Start typing in the note or the text `card`, with the caret nearest `p`, a place on the board, or at the end of its words"
start_typing!(v::CanvasView, card, p=nothing; fresh=false) = begin
  field = canvas_input(v)
  v.typing, v.fresh, v.was = card, fresh, card.content
  v.picked = card
  v.grab = nothing
  field.text = card.content
  field.anchor = field.cursor = p === nothing ? length(field.text) : index_near(card, field.text, p)
  field.last_action = time()
  focus(field)
  handled
end

"""
Stop typing. With `keep`, the words that were typed are written down, and a
note that holds only a web address or a wiki link becomes a card of that
page. Without it, the words go back to what they were. A card with no words
left is taken away. The keyboard goes back to the board.
"""
finish_typing!(v::CanvasView; keep=true) = begin
  card = v.typing
  card === nothing && return nothing
  field = canvas_input(v)
  v.typing = nothing
  w = window_of(v)
  w !== nothing && w.focus === field && focus(canvas_area(v))
  text = keep ? replace(rstrip(field.text), r"^(?:[ \t]*\n)+" => "") : v.was
  fresh, v.fresh = v.fresh, false
  if isempty(strip(text))
    Canvases.remove!(v.data, card)
    v.picked === card && (v.picked = nothing)
    fresh || commit!(v)   # a new card that was never written goes as it came
    return nothing
  end
  card.content = text
  if card.kind == :note && !occursin('\n', text)
    if Cards.isaddress(text)
      card.kind, card.width = :link, Canvases.WIDTHS.link
    elseif occursin(r"^\[\[[^\]]+\]\]$", text)
      card.kind, card.width, card.content = :page, Canvases.WIDTHS.page, Canvases.page_name(text)
    end
  end
  commit!(v)
  v.tool == :select || (v.picked = nothing)   # with another tool, the next click makes more
  card
end

"Put a new line in the words that are being typed, where the caret is, in place of what's selected"
type_newline!(v::CanvasView) = begin
  field = canvas_input(v)
  cs = collect(field.text)
  lo, hi = minmax(field.anchor, field.cursor)
  field.text = String([cs[1:lo]; '\n'; cs[hi+1:end]])
  field.anchor = field.cursor = lo + 1
  field.last_action = time()
  handled
end

"Move the caret of the words that are being typed a line up or down, as near as it can be to where it is across. ⇧ selects."
caret_up_down!(v::CanvasView, down, shift) = begin
  card, field = v.typing, canvas_input(v)
  cs = collect(field.text)
  lines = card_wrap(field.text, word_room(card), word_size(card))
  i = caret_line(lines, field.cursor)
  j = i + (down ? 1 : -1)
  n = if j < 1
    0
  elseif j > length(lines)
    length(cs)
  else
    dx, dy = word_inset(card)
    across = num(measure(canvas_face(word_size(card)), String(cs[first(lines[i]):field.cursor])))
    index_near(card, field.text, (card.at[1] + dx + across, card.at[2] + dy + (j - 0.5) * word_lead(card)))
  end
  field.cursor = n
  shift || (field.anchor = n)
  field.last_action = time()
  handled
end

"Note a click at `(x, y)` in the window. True when it's the second of two clicks in one place."
click_twice!(v::CanvasView, x, y) = begin
  at, cx, cy = v.clicked
  v.clicked = (time(), x, y)
  time() - at < 0.35 && hypot(x - cx, y - cy) < 4
end

# --- changing the board -----------------------------------------------------------------------

"""
A new note joined to `card` by a line, and the keyboard in it: to the right
of `card` as the next card that it joins to (`:child`), or under it as the
next card joined from the card that it's joined from (`:sibling`).
"""
add_joined!(v::CanvasView, card, how) = begin
  readonly(editor(v).buf) && return handled
  size(c) = card_size(v, c)
  new = Canvases.Card(:note, (0.0, 0.0))
  wh = (new.width, 2NOTE_PAD + word_lead(new))
  if how == :child
    new.at, from = Canvases.child_place(v.data, card, wh, size), card
  else
    new.at, from = Canvases.sibling_place(v.data, card, wh, size), Canvases.parent_of(v.data, card)
  end
  push!(v.data.cards, new)
  from === nothing || Canvases.join!(v.data, from, new)
  show_place!(v, new)
  start_typing!(v, new; fresh=true)
end

"Stop typing, and add a note joined to the card that was typed in or is selected, as `add_joined!` does"
add_after!(v::CanvasView, how) = begin
  card = v.typing !== nothing ? v.typing : v.picked
  card isa Canvases.Card || return handled
  finish_typing!(v)
  any(c -> c === card, v.data.cards) || return handled   # it had no words, and went
  add_joined!(v, card, how)
end

"Take away the card, the line between cards or the line drawn by hand that's selected"
delete_picked!(v::CanvasView) = begin
  p, d = v.picked, v.data
  p === nothing && return handled
  v.picked = nothing
  p isa Canvases.Card ? Canvases.remove!(d, p) : p isa Pair ? filter!(j -> j !== p, d.joins) : filter!(s -> s !== p, d.strokes)
  commit!(v)
  handled
end

"Take back the last change of the page, or do it again"
undo_canvas!(v::CanvasView, command) = begin
  b = editor(v).buf
  command == :redo ? redo!(b) : undo!(b)
  v.picked = nothing
  handled
end

"Put `card` on the board with the middle of its top at `at`, where no card covers it, select it and write the board down"
add_card!(v::CanvasView, card, at) = begin
  wh = card_size(v, card)
  card.at = Canvases.free_place(v.data, (at[1] - wh[1] / 2, at[2] - 20), wh, c -> card_size(v, c))
  push!(v.data.cards, card)
  v.picked = card
  commit!(v)
  show_place!(v, card)
  handled
end

"The card that text which is put on the board makes: a card of a web page for its address, a card of a page for a wiki link, and a note for any other"
text_card(text) = Cards.isaddress(text) ? Canvases.Card(:link, (0, 0), text) :
                  occursin(r"^\[\[[^\]\n]+\]\]$", text) ? Canvases.Card(:page, (0, 0), Canvases.page_name(text)) :
                  Canvases.Card(:note, (0, 0), text)

"The name that a card of the page at `path` has: what a wiki link from this page would call it"
page_name_for(e, path) = (name = splitext(basename(path))[1]; wiki_path(e, name) == path ? name : splitext(named(e, path))[1])

"""
Put the files at `paths` on the board, near the place `at`: a picture as a
picture, and a Markdown file as a card of the page. Other files are left out.
A file in a folder for temporary files is copied to the media folder first,
as a paste in the page does.
"""
put_on_board!(v::CanvasView, paths, at) = begin
  e = editor(v)
  readonly(e.buf) && return handled
  added = 0
  for path in paths
    path = rstrip(String(path), '/')
    isfile(path) || continue
    passing(e, path) && (path = something(keep_copy(e, path), path))
    card = ispicture(path) ? Canvases.Card(:picture, (0, 0), named(e, path)) :
           ismarkdown(path) ? Canvases.Card(:page, (0, 0), page_name_for(e, path)) : nothing
    card === nothing && continue
    wh = card_size(v, card)
    card.at = Canvases.free_place(v.data, (at[1] - wh[1] / 2, at[2] - wh[2] / 2), wh, c -> card_size(v, c))
    push!(v.data.cards, card)
    v.picked = card
    added += 1
  end
  added > 0 && (commit!(v); show_place!(v, v.picked))
  handled
end

"The place on the board where what's pasted goes: under the mouse when it's on the board, or the middle of what shows"
drop_place(v::CanvasView, w) = begin
  x, y = num(w.mouse[1]), num(w.mouse[2])
  Canvases.inside((x, y), (v.box[1], v.box[2], v.box[1] + v.box[3], v.box[2] + v.box[4])) ? board_place(v, x, y) : board_middle(v)
end

"""
Put what the clipboard holds on the board, as a paste in the page does:
files that were copied in the Finder, a picture that was copied as itself, a
web address as a card of its page, a wiki link as a card of the page, and any
other text as a note.
"""
paste_canvas!(v::CanvasView, w) = begin
  e = editor(v)
  at = drop_place(v, w)
  paths = Pasteboard.files()
  isempty(paths) || return put_on_board!(v, paths, at)
  text = String(strip(replace(Sys.isapple() ? Pasteboard.text() : clipboard(), "\r\n" => "\n", '\r' => '\n')))
  # A picture that's copied from a web page comes with its address as text, and the picture is what's wanted
  found = isempty(text) || occursin(r"^\w+://\S+$", text) ? Pasteboard.media() : nothing
  path = found === nothing ? nothing : keep_pasted(e, found...)
  path === nothing || return put_on_board!(v, [path], at)
  isempty(text) ? handled : add_card!(v, text_card(text), at)
end

"Ask which pictures go on the board, with macOS's own panel"
choose_pictures!(v::CanvasView, w) = begin
  # A window that isn't on the screen, like one a test makes, has no panel to ask with
  (Sys.isapple() && !isempty(w.glfw)) || return handled
  path = with_pool() do
    panel = msg(cls("NSOpenPanel"), "openPanel")
    msg(panel, "setDirectoryURL:", msg(cls("NSURL"), "fileURLWithPath:", nsstring(docdir(editor(v)))))
    # 1 is the panel's Open button
    ccall((:objc_msgSend, libobjc), Int, (Ptr{Cvoid}, Ptr{Cvoid}), panel, sel("runModal")) == 1 || return nothing
    jstring(msg(msg(panel, "URL"), "path"))
  end
  # The panel took the mouse, so the window never heard its button come up
  Keys.mouse_left in w.keys && (w.keys ⊻= Keys.mouse_left)
  path === nothing || put_on_board!(v, [path], board_middle(v))
  handled
end

"""
Open what a card shows: a web page in the browser, or one of your pages in
the window. When that page has a canvas, its first one fills the window.
"""
open_card!(v::CanvasView, card) = begin
  e = editor(v)
  if card.kind == :link
    BROWSER[](card.content)
  elseif card.kind == :page
    # From a board that fills the window, the page's own board fills the window too. From a board in the page, the page shows.
    g = page_glance(e, card.content)
    v.full && g.board !== nothing && (canvas_to_fill[] = g.path)
    follow_wiki!(e, card.content)
    redraw_in!(e, 0.05)
  end
  handled
end

"The canvas of the page that's under the mouse, in the page or filling the window, or nothing"
canvas_at(e, w) = begin
  x, y = w.mouse
  full = full_block(e)
  for (key, node) in e.nodes
    node isa CanvasView && key isa Tuple && length(key) == 4 && key[3] == e.buf.path || continue
    (full === nothing || full === node) || continue
    r = rect(canvas_area(node))
    r !== nothing && r.left <= x < r.left + r.width && r.top <= y < r.top + r.height && return node
  end
  nothing
end

# --- the mouse and the keys -------------------------------------------------------------------

cursor(a::CanvasArea) = begin
  v = a.of
  w = window_of(a)
  (w === nothing || v.zoom <= 0) && return :arrow
  v.tool == :pen && return :crosshair
  v.tool == :text && return :ibeam
  v.grab !== nothing && return v.grab[1] == :pan ? :hand : :arrow
  x, y = num(w.mouse[1]), num(w.mouse[2])
  knob_under(v, x, y) === nothing || return :hand
  typed_place(v, board_place(v, x, y)) === nothing ? :arrow : :ibeam
end
cursor(::CanvasView) = :arrow

onkey(a::CanvasArea, ev::KeyPress{Keys.mouse_left}) = begin
  v, w = a.of, ev.window
  # A click changes the board in the page too. With ⌥ held, the page shows the block's lines.
  v.full || !only_held(v, Keys.opt) || return nothing
  v.zoom > 0 || return handled
  x, y = num(w.mouse[1]), num(w.mouse[2])
  p = board_place(v, x, y)
  twice = click_twice!(v, x, y)
  # A click on the words that are being typed puts the caret there
  if v.typing !== nothing && (n = typed_place(v, p)) !== nothing
    field = canvas_input(v)
    field.cursor = n
    only_held(w, Keys.shft) || (field.anchor = n)
    field.last_action = time()
    return handled
  end
  finish_typing!(v)
  focus(a)
  # A page that can't change can still be moved round
  readonly(editor(v).buf) && (v.grab = (:pan, (x, y), false); return handled)
  if v.tool == :pen
    v.picked = nothing
    v.draft = Sketches.Shape(:pen, v.colour, [p])
    v.grab = (:draw, (x, y), false)
    return handled
  elseif v.tool == :text
    card = card_under(v, p)
    card !== nothing && card.kind == :text && return start_typing!(v, card, p)
    # The middle of the first line of the new words is at the mouse
    new = Canvases.Card(:text, (p[1], p[2] - v.size * TEXT_LEADING / 2); colour=v.colour, size=v.size)
    push!(v.data.cards, new)
    return start_typing!(v, new; fresh=true)
  end
  knob = knob_under(v, x, y)
  if knob !== nothing
    v.picked = knob[2]
    v.grab = (knob[1], (x, y), false)
    knob[1] == :join && (v.reach = p)
    return handled
  end
  card = card_under(v, p)
  if card !== nothing
    # Two clicks on a note or a text change its words, and two on a card of a page or a web page open it
    if twice && card === v.picked
      Canvases.wordy(card) && return start_typing!(v, card, p)
      card.kind in (:page, :link) && return open_card!(v, card)
    end
    v.picked = card
    v.grab = (:move, (x, y), false)
    return handled
  end
  line = Canvases.stroke_at(v.data, p; reach=6 / v.zoom)
  line === nothing && (line = Canvases.join_at(v.data, p, c -> card_size(v, c); reach=6 / v.zoom))
  line === nothing || return (v.picked = line; handled)
  # Two clicks on an empty place make a note there, and a drag moves round the board
  if twice
    new = Canvases.Card(:note, (p[1] - 2NOTE_PAD, p[2] - NOTE_PAD - word_lead(Canvases.Card(:note, (0, 0))) / 2))
    push!(v.data.cards, new)
    return start_typing!(v, new; fresh=true)
  end
  v.picked = nothing
  v.grab = (:pan, (x, y), false)
  handled
end

onmouse(a::CanvasArea, ev::MouseMove) = begin
  v, w = a.of, ev.window
  v.grab === nothing && return nothing
  Keys.mouse_left in w.keys || return handled
  what, from, _ = v.grab
  x, y = num(w.mouse[1]), num(w.mouse[2])
  (x, y) == from && return handled
  dx, dy = (x - from[1]) / v.zoom, (y - from[2]) / v.zoom
  p = v.picked
  if what == :pan
    v.at = (v.at[1] - dx, v.at[2] - dy)
  elseif what == :move && p isa Canvases.Card
    Canvases.move!(p, dx, dy)
  elseif what == :width && p isa Canvases.Card
    p.kind == :text && p.width == 0 && (p.width = card_size(v, p)[1])   # a text with no width gets the width of its words
    Canvases.set!(p, :width, p.width + dx)
  elseif what == :join
    v.reach = board_place(v, x, y)
  elseif what == :draw && v.draft !== nothing
    q = board_place(v, x, y)
    # A line drawn by hand gets a new place when the mouse has moved a little
    hypot((q .- v.draft.points[end])...) >= 1.5 / v.zoom && push!(v.draft.points, q)
    return handled
  end
  v.grab = (what, (x, y), true)
  handled   # the drag is the board's, so the page's text doesn't select
end

"The mouse let go. A line that was drawn joins the board, a line from a card joins it to the card it ends on, and a card that moved is written down."
canvas_drop!(v::CanvasView) = begin
  g, d, at = v.grab, v.draft, v.reach
  v.grab = v.draft = v.reach = nothing
  g === nothing && return v
  what, _, moved = g
  p = v.picked
  if what == :draw && d !== nothing
    d.points = Sketches.simplify(d.points, 0.8 / v.zoom)
    length(d.points) >= 2 || return v   # a click without a drag draws nothing
    push!(v.data.strokes, d)
    commit!(v)
  elseif what == :join && moved && p isa Canvases.Card && at !== nothing
    target = card_under(v, at)
    if target === nothing
      # On an empty place, a new note joined to the card, with the keyboard
      new = Canvases.Card(:note, (at[1], at[2] - NOTE_PAD - word_lead(p) / 2))
      push!(v.data.cards, new)
      Canvases.join!(v.data, p, new)
      start_typing!(v, new; fresh=true)
    elseif target !== p
      Canvases.join!(v.data, p, target) && commit!(v)
    end
  elseif what in (:move, :width) && moved && p isa Canvases.Card
    # A card that's moved goes over the others
    what == :move && (filter!(c -> c !== p, v.data.cards); push!(v.data.cards, p))
    commit!(v)
  end
  v
end

# Two fingers on the trackpad move round the board. A pinch, the mouse wheel, or two fingers with ⌘ held make it
# bigger or smaller round the mouse. In the page the wheel and two fingers scroll the page, which goes past the
# board. With ⌘ held they make it bigger or smaller there too, as a pinch does.
onscroll(a::CanvasArea, ev::MouseScroll) = begin
  v, w = a.of, ev.window
  (v.full || only_held(w, Keys.cmd)) || return nothing
  v.zoom > 0 || return handled
  (only_held(w, Keys.cmd) || ev.wheel) && return zoom_board!(v, exp(num(ev.delta[2]) / 10), num(w.mouse[1]), num(w.mouse[2]))
  v.at = (v.at[1] - 30num(ev.delta[1]) / v.zoom, v.at[2] - 30num(ev.delta[2]) / v.zoom)
  handled
end
onscroll(v::CanvasView, ::MouseScroll) = v.full ? handled : nothing
onpinch(a::CanvasArea, ev::Pinch) = zoom_board!(a.of, ev.scale, num(ev.window.mouse[1]), num(ev.window.mouse[2]))

# Esc lets go of what's selected, then chooses the arrow, then puts a board that fills the window back in the page.
# In the page the page's text takes that Esc, and gets the keyboard back. Delete takes away what's selected. Tab
# and ⇧Return add a note joined to the card that's selected. Return types in the note or the text that's selected,
# or opens a card of a page.
onkey(a::CanvasArea, ev::KeyPress{K}) where K = begin
  v, w = a.of, ev.window
  ro = readonly(editor(v).buf)
  p = v.picked
  if K == Keys.escape && unmodified(ev)
    p === nothing || return (v.picked = nothing; handled)
    v.tool == :select || return (v.tool = :select; handled)
    return v.full ? full!(v, false) : nothing
  elseif K in (Keys.backspace, Keys.delete) && unmodified(ev)
    return ro ? handled : delete_picked!(v)
  elseif K == Keys.tab && unmodified(ev)
    return p isa Canvases.Card && !ro ? add_after!(v, :child) : handled
  elseif K == Keys.enter && only_held(ev, Keys.shft)
    return p isa Canvases.Card && !ro ? add_after!(v, :sibling) : handled
  elseif K == Keys.enter && unmodified(ev)
    p isa Canvases.Card || return handled
    Canvases.wordy(p) && !ro && return start_typing!(v, p)
    return p.kind in (:page, :link) ? open_card!(v, p) : handled
  elseif K == Keys.v && only_held(ev, Keys.cmd)
    return ro ? handled : paste_canvas!(v, w)
  elseif (command = command_of(editor(v), w, K)) in (:undo, :redo)
    return undo_canvas!(v, command)
  end
  nothing
end

# While words are typed, the text field takes the keys that it knows. The rest come here. Return starts a new
# line, and Esc ends the typing. Tab and ⇧Return add a note joined to the one that's typed in. Up and Down move
# the caret a line. ⌘Z ends the typing and takes back the last change.
onkey(v::CanvasView, ev::KeyPress{K}) where K = begin
  v.typing === nothing && return nothing
  if K == Keys.enter
    unmodified(ev) && return type_newline!(v)
    only_held(ev, Keys.shft) && return add_after!(v, :sibling)
  elseif K == Keys.tab && unmodified(ev)
    return add_after!(v, :child)
  elseif K == Keys.escape && unmodified(ev)
    finish_typing!(v)
    return handled
  elseif K in (Keys.up, Keys.down) && (unmodified(ev) || only_held(ev, Keys.shft))
    return caret_up_down!(v, K == Keys.down, only_held(ev, Keys.shft))
  elseif (command = command_of(editor(v), ev.window, K)) in (:undo, :redo)
    finish_typing!(v)
    return undo_canvas!(v, command)
  end
  nothing
end
onmouse(v::CanvasView, ::MouseMove) = v.full || (held(v, Keys.mouse_left) && v.grab !== nothing) ? handled : nothing
# A click beside a button of a canvas that fills the window is the canvas's, and not the page's under it
onkey(v::CanvasView, ::KeyPress{Keys.mouse_left}) = v.full ? (focus(canvas_area(v)); handled) : nothing

block_tick!(v::CanvasView) = begin
  v.grab !== nothing && !held(v, Keys.mouse_left) && canvas_drop!(v)
  w = window_of(v)
  # A click somewhere else took the keyboard from the words that were being typed. They're kept.
  v.typing !== nothing && w !== nothing && w.focus !== canvas_input(v) && finish_typing!(v)
  # The card that was typed in has gone, as after ⌘Z
  v.typing !== nothing && !any(c -> c === v.typing, v.data.cards) && (v.typing = nothing)
  v.typing === nothing || (sync_typing!(v); redraw_in!(v, 0.25))   # the caret blinks
  # The page took the keyboard, as when Back came to this page, but its text doesn't show
  v.full && w !== nothing && w.focus === editor(v) && focus(canvas_area(v))
  # A card of a page opened this page, and its first canvas fills the window
  if canvas_to_fill[] == editor(v).buf.path && v.n == 1
    canvas_to_fill[] = ""
    v.full || full!(v, true)
  end
  v
end

"The canvas as HTML: a picture of it"
canvas_html(e, v::CanvasView) = begin
  d = v.data
  isempty(d.cards) && isempty(d.strokes) && return nothing
  cs = css_colour.(SERIES_LIGHT)
  dir = docdir(e)
  source(card) = (p = card_file(card, dir); isfile(p) ? escaped(named(e, p)) : nothing)
  picture = Canvases.svg(d; size=c -> card_size(e, c, dir), lines=card_lines, source,
                         colours=(ink="#2b2622", red=cs[8], blue=cs[1], green=cs[6], orange=cs[2], card="#ffffff", edge="#dddddd", join="#9a9a9a", dim="#777777"),
                         family="-apple-system, Helvetica, sans-serif")
  "<div class=\"diagram\">\n$picture\n</div>"
end

BLOCKS[CANVAS] = BlockKind("Canvas", "sticky", CanvasView, canvas_html)

# --- a log of the hours on each task -----------------------------------------------------------
#
# A code block in the language `timelog` keeps the hours that someone works
# on each task. timelog.jl says how the block is written, and adds the hours
# up. The block shows a row for each stretch of work, and the totals under
# the rows. At its top, a field takes a task, and the button beside it starts
# the clock on that task: a new line for now, with no stop time. While a line
# runs, its row counts up, and the button is lit and reads Stop. A click on it
# then writes the time now into the line. A task that's typed in the field
# while a line runs makes the button read Start again: a click stops that
# line and starts the new task. The field offers the tasks that the log
# already has, in a list like the one under a button of a `find` block. A
# click on a time or a task of a row lets you change it where it is, with no
# box round it, and Return writes what's typed there into the line. A `chart` block under a log draws
# the hours of each task.

const TIMELOG = Timelogs.TIMELOG
const TASKS_KEY = :timelog_tasks   # the key of the list of tasks under the field
const MOST_TASKS = 6               # the rows that the list shows before it scrolls
const LOG_ROW = 28px               # how tall a row of the log is
const LOG_DAY, LOG_TIME, LOG_HOURS = 104px, 58px, 124px   # how wide the columns before the task are
const LOG_NARROW = 470px           # a log that's narrower than this has each day on a line of its own, and no column for the day
const LOG_SLIM = (52px, 112px)     # how wide the columns of a time and of the hours are in such a log
const LOG_WRONG = colorant"rgb(214,69,65)"   # the line under a time that's being changed and can't be read
push!(BLOCK_ICONS, "stopwatch", "play-fill", "stop-fill")

"What a `timelog` block shows: a row for each stretch of work, the totals, and a field and a button that start the clock"
@def mutable struct TimelogView <: SemanticUI
  n::Int = 0                               # its place among the page's time logs
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Timelogs.Log = Timelogs.Log()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its fields, its button and its cells, kept between frames
  editing::Any = nothing                   # the cell that's being changed where it is: its row, and :from, :to or :task
  wrong::Bool = false                      # what's typed there isn't a time
  offers::Vector{String} = String[]        # the tasks that the list under the field offers
  pick::Int = 0                            # the one of them that Return takes, or 0 for none
  typed::Any = nothing                     # what the field held when the offers were last worked out, or nothing while it has no keyboard
  minute::Int = -1                         # the minute that the page's charts last drew a running log for
end

"A time or a task of a row. A click lets you change it where it is."
@def mutable struct LogCell <: SemanticUI
  of::Any = nothing
  i::Int = 0
  part::Symbol = :task
end
"The list of tasks that floats under the field of a log"
@def mutable struct TaskOffers <: SemanticUI
  of::Any = nothing
  side::Symbol = :bottom   # the side of the field that it's on
  pick::Int = 0            # the row that was picked when it was last drawn. A row that the keys pick is brought in sight.
end
"A row of that list: a task that the log has"
@def mutable struct TaskOffer <: SemanticUI
  of::Any = nothing
  k::Int = 0
end

"The field at the top of a log. It holds the task that Start starts."
task_input(v::TimelogView) = block_part!(v, :input) do
  TextInput(placeholder="What are you working on?", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"The field that takes the place of a time or a task while you change it"
cell_input(v::TimelogView) = block_part!(v, :edit) do
  TextInput(placeholder="", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

reread!(v::TimelogView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Timelogs.timelog(lines)
  # The row of the cell that's being changed can go, as when ⌘Z takes its line back
  v.editing === nothing || Timelogs.stretch(v.data, v.editing[1]) !== nothing || (v.editing = nothing)
  v
end

"True when the page can't be changed, so the log can't be"
log_fixed(v::TimelogView) = (b = editor(v).buf; readonly(b) || b.fixed)

"Write the log into the lines of its block"
write_log!(v::TimelogView) = write_block!(v, TIMELOG, Timelogs.written(v.data))

"True when the button starts the clock: no line runs, or the field holds a task to change to"
starts(v::TimelogView) = Timelogs.running(v.data) === nothing || !isempty(strip(task_input(v).text))

"What the button does: it starts the clock on the task in the field, or it stops the line that runs"
clock!(v::TimelogView) = begin
  log_fixed(v) && return handled
  input = task_input(v)
  at = Timelogs.now()
  starts(v) ? Timelogs.start!(v.data, input.text, at) : Timelogs.stop!(v.data, at)
  input.text = ""
  input.anchor = input.cursor = 0
  shut_offers!(v)
  write_log!(v)
  handled
end

# A click on the button gives the keyboard back to the page, if the field had it
act!(v::TimelogView, action, w) = (action == :clock && clock!(v); w.focus === task_input(v) && focus(editor(v)); handled)

"The words of a part of the stretch `s`: a time as its line has it, or its task"
cell_words(s::Timelogs.Stretch, part::Symbol) =
  part == :task ? s.task : part == :from ? Timelogs.hhmm(s.from) : s.to === nothing ? "" : Timelogs.hhmm(s.to)

"""
Write what the field in a row holds into its line, and take the field away.
It gives false, and the field stays, when a time can't be read.
"""
settle_cell!(v::TimelogView) = begin
  v.editing === nothing && return true
  i, part = v.editing
  s = Timelogs.stretch(v.data, i)
  text = cell_input(v).text
  if s !== nothing && !log_fixed(v) && strip(text) != cell_words(s, part)
    Timelogs.set!(v.data, i, part, text) || (v.wrong = true; return false)
    write_log!(v)
  end
  v.editing, v.wrong = nothing, false
  true
end

"Put a field in the place of the cell `c`, with the cell's words in it and selected"
open_cell!(c::LogCell) = begin
  v = c.of
  log_fixed(v) && return handled
  settle_cell!(v) || (v.editing = nothing)   # another cell that was being changed is written first
  s = Timelogs.stretch(v.data, c.i)
  s === nothing && return handled
  input = cell_input(v)
  input.color = colours.ink
  input.text = cell_words(s, c.part)
  input.anchor, input.cursor = 0, length(input.text)
  v.editing, v.wrong = (c.i, c.part), false
  focus(input)
  handled
end

"Show the list of the tasks to offer under the field"
show_offers!(v::TimelogView, w) = begin
  list = TaskOffers(of=v)
  v.parts[:offers] = list
  r = rect(task_input(v))
  # The keys stay with the field, and a click outside the list is the app's, as it is with no list
  popup!(w, list, anchor=task_input(v), placement=:bottom, gap=9px, width=max(220px, r === nothing ? 0px : r.width + 16px), key=TASKS_KEY, modal=false,
         onclose=() -> (v.offers = String[]; v.pick = 0), theme=component_theme(editor(v).zoom))
end

"Take the list of tasks away. It comes back when what's in the field changes."
shut_offers!(v::TimelogView) = begin
  v.offers, v.pick = String[], 0
  w = window_of(v)
  w === nothing || close_popup!(w, TASKS_KEY)
  handled
end

"Put the task at row `k` of the list in the field, with the caret after it. Start, or Return, then starts it."
take_offer!(v::TimelogView, k::Int) = begin
  input = task_input(v)
  k in eachindex(v.offers) && (input.text = v.offers[k]; input.anchor = input.cursor = length(input.text))
  v.typed = input.text
  focus(input)
  shut_offers!(v)
end

"""
What happens to a log in each frame, before the page is laid out. A click
somewhere else writes what the field in a row holds. The list under the top
field gets the tasks that have what's typed there, and goes when the field
loses the keyboard. A chart of a log that runs is drawn again each minute.
"""
block_tick!(v::TimelogView) = begin
  w = window_of(v)
  v.editing !== nothing && (w === nothing || w.focus !== cell_input(v)) && (settle_cell!(v) || (v.editing = nothing))
  input = task_input(v)
  if w === nothing || w.focus !== input
    v.typed === nothing || (v.typed = nothing; shut_offers!(v))
  elseif input.text != v.typed
    v.typed = input.text
    v.offers, v.pick = Timelogs.offered(v.data, input.text), 0
    isempty(v.offers) ? close_popup!(w, TASKS_KEY) : show_offers!(v, w)
  end
  if Timelogs.running(v.data) !== nothing && (minute = Dates.minute(Timelogs.now())) != v.minute
    v.minute = minute
    e = editor(v)
    delete!(e.flows, (:tables, e.buf.path, e.buf.version, table_reads[], sums_run[], page_day(e)))
    foreach(node -> node isa ChartView && (node.shown = nothing), values(e.nodes))
  end
  v
end

describe(o::TaskOffer) = begin
  v = o.of
  o.k <= length(v.offers) ? float_row(v.offers[o.k], picked=v.pick == o.k) : Box(height(0px))
end

cursor(::TaskOffer) = :hand
onkey(o::TaskOffer, ::KeyPress{Keys.mouse_left}) = take_offer!(o.of, o.k)
# The mouse picks the task that it's over, as the arrow keys do
onmouse(o::TaskOffer, ::MouseMove) = begin
  v = o.of
  v.pick = o.k
  list = get(v.parts, :offers, nothing)
  list === nothing || (list.pick = o.k)   # it's in sight already, so the list doesn't scroll to it
  handled
end

describe(l::TaskOffers) = begin
  v = l.of
  c = found_colours()
  n, high = length(v.offers), FLOAT_ROW
  scroll = get!(() -> Scroll(width(grow=grow)), v.parts, :offer_scroll)
  # Half a row at the bottom says that the list goes on
  scroll.height = height(n <= MOST_TASKS ? n * high : MOST_TASKS * high - high / 2)
  l.pick == v.pick || (l.pick = v.pick; v.pick > 0 && scroll_into_view!(scroll, high * (v.pick - 1), high * v.pick))
  Box(width(grow=grow), padding(6px), radius(8px), background(c.frame), border(1px, :solid, c.line),
      shadow(0, 6, 16, RGBA(60 / 255, 45 / 255, 20 / 255, 0.2)), name="Tasks",
    reuse!(scroll, Column(width(grow=grow), Alignment.Start, [block_part!(() -> TaskOffer(of=v, k=k), v, (:offer, k)) for k in 1:n]...)))
end

placed!(l::TaskOffers, side) = (l.side = side; nothing)
draw(ctx, size, ui::ConcreteRect, l::TaskOffers) = caret(ctx, ui, l.side, rect(task_input(l.of)))

# The keys that a field of the log has no use for come here. Return in the field of a row writes what's typed
# there. In the top field, it takes the task that's picked in the list, or does what the button does.
onkey(v::TimelogView, ev::KeyPress{Keys.enter}) = begin
  unmodified(ev) || return nothing
  w = ev.window
  if w.focus === cell_input(v)
    settle_cell!(v) && focus(editor(v))
  elseif w.focus === task_input(v)
    v.pick > 0 && return take_offer!(v, v.pick)
    starts(v) && clock!(v)
    focus(editor(v))
  else
    return nothing
  end
  handled
end
# Esc leaves a row as it was. In the top field, it closes the list, and then gives the keyboard back to the page.
onkey(v::TimelogView, ev::KeyPress{Keys.escape}) = begin
  unmodified(ev) || return nothing
  w = ev.window
  if w.focus === cell_input(v)
    v.editing, v.wrong = nothing, false
    focus(editor(v))
  elseif w.focus === task_input(v)
    isempty(v.offers) ? focus(editor(v)) : shut_offers!(v)
  else
    return nothing
  end
  handled
end
onkey(v::TimelogView, ev::KeyPress{Keys.down}) = unmodified(ev) ? (isempty(v.offers) ? nothing : (v.pick = min(v.pick + 1, length(v.offers)); handled)) : nothing
onkey(v::TimelogView, ev::KeyPress{Keys.up}) = unmodified(ev) ? (isempty(v.offers) ? nothing : (v.pick = max(v.pick - 1, 0); handled)) : nothing

"True when the log is too narrow for a column of days. Each day is then on a line of its own, over its rows."
log_narrow(v::TimelogView) = editor(v).width < LOG_NARROW

"Words in a column of a log. `wide` says how wide the column is."
log_column(wide, words; size=13px, color=colours.ink, weight="") =
  Row(wide, height(24px), padding(6px, 0px), Alignment.Center, clip=true, Box(label(words, size, color=color, weight=weight)))

describe(c::LogCell) = begin
  v = c.of
  s = Timelogs.stretch(v.data, c.i)
  s === nothing && return Box(width(0px))
  wide = c.part == :task ? width(grow=grow) : fixed(log_narrow(v) ? LOG_SLIM[1] : LOG_TIME)
  if v.editing == (c.i, c.part)
    # The words are changed where they are, with no box round them. A time that can't be read has a red line under it.
    field = Row(wide, height(24px), padding(6px, 0px), Alignment.Center, Box(width(grow=grow), height(grow=grow), cell_input(v)))
    v.wrong && (field.border = border(1px, :solid, LOG_WRONG)[:bottom])
    return field
  end
  words = cell_words(s, c.part)
  # A row with no stop time says "now" while it runs. A row with no task says so.
  shown = !isempty(words) ? words : c.part == :task ? "No task" : Timelogs.running(v.data) == c.i ? "now" : "–"
  Row(wide, height(24px), padding(6px, 0px), radius(5px), Alignment.Center, clip=true, background(ishovered(c) && !log_fixed(v) ? colours.hover : clear),
      Box(label(shown, 13px, color=isempty(words) ? colours.faint : colours.ink)))
end

cursor(c::LogCell) = log_fixed(c.of) ? :arrow : :ibeam
cursor(::TimelogView) = :arrow
onkey(c::LogCell, ::KeyPress{Keys.mouse_left}) = c.of.editing == (c.i, c.part) ? nothing : open_cell!(c)

"What the button's tooltip says after \"Start the clock\": the task, if there is one"
on_task(task) = isempty(task) ? "" : " on " * task

describe(v::TimelogView) = begin
  e = editor(v)
  log = v.data
  at = Timelogs.now()
  run = Timelogs.running(log)
  # The row that runs counts up, so the window draws again when the next second starts
  run === nothing || redraw_in!(v, 1.02 - Dates.millisecond(at) / 1000)
  with_theme(component_theme(e.zoom)) do
    input = task_input(v)
    input.color = colours.ink
    w = window_of(v)
    typing = w !== nothing && w.focus === input
    field = Row(width(grow=grow), height(26px), padding(8px, 0px), child_gap=7px, radius(6px), Alignment.Center, background(colours.bg),
                border(1px, :solid, typing ? colours.accent : colours.line),
                Icon("stopwatch", size=12px, color=run === nothing ? colours.dim : colours.accent), Box(width(grow=grow), height(grow=grow), input))
    # The button reads what a click does. It's lit while a line runs, and its tooltip says which task the click is for.
    typed = Timelogs.tidy(input.text)
    next = on_task(isempty(typed) ? Timelogs.last_task(log) : typed)
    button = !starts(v) ? block_button!(v, :clock, :clock, icon="stop-fill", words="Stop", on=true, tip="Stop the clock" * on_task(log.rows[run].task)) :
             block_button!(v, :clock, :clock, icon="play-fill", words="Start", bold=true, off=log_fixed(v),
                           tip=run === nothing ? "Start the clock" * next : "Stop the clock" * on_task(log.rows[run].task) * ", and start it" * next)
    bar = block_bar(field, Box(width(4px)), button)
    isempty(log.rows) && return Column(block_look()..., clip=true, name="Time log", bar,
      block_note("This log has no hours yet. Type a task in the field and click Start."))
    narrow = log_narrow(v)
    time_wide, hours_wide = narrow ? LOG_SLIM : (LOG_TIME, LOG_HOURS)
    head = Row(width(grow=grow), height(24px), padding(6px, 0px), Alignment.Center,
      (narrow ? () : (log_column(fixed(LOG_DAY), "Day", size=11px, color=colours.dim),))...,
      log_column(fixed(time_wide), "From", size=11px, color=colours.dim), log_column(fixed(time_wide), "To", size=11px, color=colours.dim),
      log_column(fixed(hours_wide), "Hours", size=11px, color=colours.dim), log_column(width(grow=grow), "Task", size=11px, color=colours.dim))
    rows, day, hot = Any[], nothing, hot_stretch(v)
    for (i, r) in enumerate(log.rows)
      if r isa String
        # A line that can't be read shows as it's written
        push!(rows, Row(width(grow=grow), height(LOG_ROW), padding(12px, 0px), Alignment.Center, clip=true, Box(label(r, 13px, color=colours.faint)), Box(width(grow=grow))))
        continue
      end
      # The day shows once, for the first of its rows
      fresh = r.day != day
      day = r.day
      narrow && fresh && push!(rows, Row(width(grow=grow), height(24px), padding(12px, 0px), Alignment.Center,
                                         Box(label(Timelogs.day(r.day), 12px, color=colours.dim, weight="Semibold")), Box(width(grow=grow))))
      runs = i == run
      hours = runs ? Timelogs.elapsed(Timelogs.seconds(log, i, at)) : r.to === nothing ? "–" : Timelogs.hours(Timelogs.counted(log, i, at))
      # A row is marked while the mouse is on its task: in another row, or in another part of the page
      lit = !isempty(r.task) && i != hot && marked(v, r.task)
      push!(rows, Row(width(grow=grow), height(LOG_ROW), padding(6px, 0px), Alignment.Center, background(lit ? tint(colours.accent, MARK_FILL) : runs ? RGBA(colours.accent, 0.09) : clear),
        (narrow ? () : (log_column(fixed(LOG_DAY), fresh ? Timelogs.day(r.day) : "", color=colours.dim),))...,
        block_part!(() -> LogCell(of=v, i=i, part=:from), v, (:cell, i, :from)), block_part!(() -> LogCell(of=v, i=i, part=:to), v, (:cell, i, :to)),
        log_column(fixed(hours_wide), hours, color=runs ? colours.accent : r.to === nothing || r.day > page_day(e) ? colours.faint : colours.ink, weight=runs ? "Semibold" : ""),
        block_part!(() -> LogCell(of=v, i=i, part=:task), v, (:cell, i, :task))))
    end
    # Under the rows: the total, and the hours of each task when the log has more than one
    sums = Any[]
    if any(r -> r isa Timelogs.Stretch, log.rows)
      lead = (narrow ? 0px : LOG_DAY) + 2time_wide
      sum_row(name, minutes, weight) = Row(width(grow=grow), height(LOG_ROW), padding(6px, 0px), Alignment.Center,
        background(isempty(weight) && marked(v, name) ? tint(colours.accent, MARK_FILL) : clear),
        log_column(fixed(lead), elide(name, 13px, lead - 12px), color=isempty(weight) ? colours.dim : colours.ink, weight=weight),
        log_column(fixed(hours_wide), Timelogs.hours(minutes), weight=weight),
        log_column(width(grow=grow), something(Timelogs.money(log, minutes), ""), weight=weight))
      # A page that shows a day that's past adds up the hours to that day
      counted = log_to_day(e, log)
      tasks = Timelogs.tasks(counted, at)
      push!(sums, Box(width(grow=grow), padding(12px, 4px), Box(width(grow=grow), height(1px), background(colours.line))),
            sum_row(counted === log ? "Total" : "To " * Schedules.short(page_day(e)), Timelogs.total(counted, at), "Semibold"))
      length(tasks) > 1 && append!(sums, (sum_row(isempty(name) ? "No task" : name, minutes, "") for (name, minutes) in tasks))
    end
    Column(block_look()..., clip=true, name="Time log", bar, head, rows..., sums..., Box(height(6px)))
  end
end

"The log as HTML: a table with a row for each stretch of work, and the totals at its foot"
timelog_html(e, v::TimelogView) = begin
  log = v.data
  isempty(log.rows) && return nothing
  at = Timelogs.now()
  run = Timelogs.running(log)
  rows, day = String[], nothing
  for (i, r) in enumerate(log.rows)
    if r isa String
      push!(rows, "<tr><td colspan=\"5\" style=\"color: #a39a8a\">$(escape(r))</td></tr>")
      continue
    end
    shown = r.day == day ? "" : Timelogs.day(r.day)
    day = r.day
    to = r.to !== nothing ? Timelogs.hhmm(r.to) : i == run ? "now" : ""
    hours = r.to === nothing && i != run ? "" : Timelogs.hours(Timelogs.counted(log, i, at))
    push!(rows, "<tr><td>$shown</td><td>$(Timelogs.hhmm(r.from))</td><td>$to</td><td>$hours</td><td>$(escape(r.task))</td></tr>")
  end
  sum_row(name, minutes, cell) =
    "<tr><$cell colspan=\"3\">$(escape(name))</$cell><$cell>$(Timelogs.hours(minutes))</$cell><$cell>$(something(Timelogs.money(log, minutes), ""))</$cell></tr>"
  sums = String[]
  if any(r -> r isa Timelogs.Stretch, log.rows)
    tasks = Timelogs.tasks(log, at)
    push!(sums, sum_row("Total", Timelogs.total(log, at), "th"))
    length(tasks) > 1 && append!(sums, (sum_row(isempty(name) ? "No task" : name, minutes, "td") for (name, minutes) in tasks))
  end
  "<table>\n<thead><tr><th>Day</th><th>From</th><th>To</th><th>Hours</th><th>Task</th></tr></thead>\n<tbody>\n" * join(rows, "\n") *
  "\n</tbody>\n<tfoot>\n" * join(sums, "\n") * "\n</tfoot>\n</table>"
end

BLOCKS[TIMELOG] = BlockKind("Time log", "stopwatch", TimelogView, timelog_html)

# --- contacts ----------------------------------------------------------------------------------
#
# A code block in the language `contact` holds contacts: people and
# companies. contact.jl says how the block is written. Each contact shows as
# a card: a round picture, the name, the role and the company under it, and a
# row for each other detail. A block with nothing in it shows a card with a
# place for a name.
#
#   - A click on a row uses it. An email address starts a new email, a phone
#     number a call, an address shows in the Maps app, and a web address
#     opens in the browser. Each one goes through `BROWSER`, as the address
#     of a link card does, so a test opens nothing.
#   - While the mouse is over a row, a button at its right end copies its value.
#   - Two clicks on the name, the role, the company or the value of a row
#     change those words where they are, with no box round them. Return keeps
#     the change, esc leaves it, and a click somewhere else keeps it. An
#     emptied value takes its line out of the block. So a click on a row
#     waits a moment for a second click before it opens anything.
#   - While the mouse is over a card, two buttons show at its top right. The
#     + opens a menu of the details to add. The other one writes the contact
#     as a vCard file and opens the file, so the Contacts app asks to add it.
#   - While the mouse is over the block, a button under the last card adds a contact.
#   - A vCard file that's dropped on the page becomes a block of its
#     contacts, and one that's dropped on a block joins it. ⌘V does the same
#     with a contact that was copied in the Contacts app.
#   - A page that can't be changed, like an email, takes no changes. Its
#     rows still open and copy.

const CONTACT = Contacts.CONTACT
push!(BLOCK_ICONS, "person-vcard", "person", "building", "envelope", "telephone", "geo-alt", "globe", "card-text", "tag",
      "plus", "plus-circle", "person-plus", "copy", "check")
const CONTACT_WIDE = 420px   # how wide a card is at the usual size of the text, in a page with room for it
const CONTACT_FACE = 44px    # how wide the round picture is
const CONTACT_PAD = 12px     # the room inside a card's edge, and between the picture and the words
const CONTACT_NAME = 22px    # how tall the line of the name is
const CONTACT_LINE = 20px    # and each other line of a card
const CONTACT_WAIT = 0.35    # how many seconds a click on a row waits for a second click
const CONTACT_COPIED = 1.2   # how many seconds the button of a row shows that it copied
"The details that the + of a card adds: what the menu calls each, and its kind"
const CONTACT_MENU = [("Email", :email), ("Phone", :phone), ("Address", :address), ("Website", :web), ("Note", :note)]
"The icon of a row of each kind. A row of any other kind has a tag."
const CONTACT_ICONS = Dict(:email => "envelope", :phone => "telephone", :address => "geo-alt", :web => "globe", :note => "card-text", :company => "building")
"What the button of a row of each kind copies, as its tooltip says it"
const CONTACT_COPIES = Dict(:email => "the email address", :phone => "the phone number", :address => "the address", :web => "the web address", :note => "the note")

"What a `contact` block shows: a card for each contact of the block"
@def mutable struct ContactView <: SemanticUI
  n::Int = 0                               # its place among the page's blocks of contacts
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Vector{Contacts.Contact} = Contacts.Contact[]
  lines::Vector{String} = String[]         # the lines that `data` was read from
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its cards, their rows and buttons, and the field, kept between frames
  # What's being changed where it is, or nothing: the contact's place in the block, then the line of the
  # contact, or `:name` for its name, or the kind of a new detail, like `:email`
  editing::Any = nothing
  waiting::Any = nothing                   # a click on a row that opens something: when it was, the contact and the line
  clicked::Any = (0.0, nothing, 0.0, 0.0)  # when the last click was, what it was on and where
  copied::Any = (0.0, 0, 0)                # when a value was last copied, and its contact and its line
  menu::Int = 0                            # the card whose menu of details is open, or 0
end

"The card of one contact"
@def mutable struct ContactCard <: SemanticUI
  of::Any = nothing
  k::Int = 0
end
"The round picture of a card: the photo, the initials, or a building for a company"
@def mutable struct ContactFace <: SemanticUI
  of::Any = nothing
  k::Int = 0
  key::String = ""   # of the photo, for drawing, or "" when the card has none to show
end
"Words of a card that two clicks change where they are: the name, the role or the company"
@def mutable struct ContactWords <: SemanticUI
  of::Any = nothing
  k::Int = 0
  i::Any = :name       # the line of the contact, or `:name`
  room::px = 0px       # how wide the words can be
  tight::Bool = false  # other words follow them on their line, so the field is as wide as what's typed
end
"A row of a card: one detail, with its icon"
@def mutable struct ContactRow <: SemanticUI
  of::Any = nothing
  k::Int = 0
  i::Any = 0           # the line of the contact, or the kind of a new detail that's being typed
  room::px = 0px       # how wide the row is
end
"A small button of a card, with only an icon. A click does `contact_act!(view, action, window)`."
@def mutable struct ContactButton <: SemanticUI
  of::Any = nothing
  action::Any = (:none,)
  icon::String = ""
  tip::String = ""
  quiet::Bool = false   # clicked, so no tooltip until the mouse leaves it
end

"The field that takes the place of words of a card while you change them"
contact_input(v::ContactView) = block_part!(v, :edit) do
  TextInput(placeholder="", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

"""
That field in a box with no border and no background, set to draw its text
`size` tall. `sizing` says how wide and how tall the box is.
"""
contact_field(v::ContactView, size, sizing...) = begin
  input = contact_input(v)
  input.color = colours.ink
  theme = component_theme(editor(v).zoom)
  # A size in points is a part of the theme's size
  input.font_size = (12 * num(size) / num(theme.size))pt
  with_theme(() -> Box(sizing..., input), theme)
end

"""
A part of a block of contacts that's kept between frames. `parent` is the part
that it's drawn in. So the mouse over a button of a row is over the row too,
and over the row's card.
"""
contact_part!(make, v::ContactView, key, parent) = begin
  node = get!(make, v.parts, key)
  node.parent === nothing && setfield!(node, :parent, parent)
  node
end

contact_card!(v::ContactView, k) = contact_part!(() -> ContactCard(of=v, k=k), v, (:card, k), v)
contact_words!(v::ContactView, k, i) = contact_part!(() -> ContactWords(of=v, k=k, i=i), v, (:words, k, i), contact_card!(v, k))
contact_row!(v::ContactView, k, i) = contact_part!(() -> ContactRow(of=v, k=k, i=i), v, (:row, k, i), contact_card!(v, k))
"The button of the block that's kept for `action`, with what it shows now"
contact_button!(v::ContactView, action, icon, tip, parent) = begin
  b = contact_part!(() -> ContactButton(of=v), v, (:button, action), parent)
  b.action, b.icon, b.tip = action, icon, tip
  b
end

reread!(v::ContactView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Contacts.contacts(lines)
  # The line that was being changed can go, as when ⌘Z takes it back
  v.editing = v.waiting = nothing
  v
end

"True for contacts in a page that can't be changed, like an email. They take no changes."
locked(v::ContactView) = (b = editor(v).buf; readonly(b) || b.fixed)

"The contact at `k` of the block. A place after the last one has a contact with nothing in it: the one that a new name starts."
contact_of(v::ContactView, k::Int) = k in eachindex(v.data) ? v.data[k] : Contacts.Contact()

"How many cards the block shows: one for each contact, one for a block with none, and one more while a new contact gets its name"
contact_cards(v::ContactView) = max(1, length(v.data), v.editing === nothing ? 0 : v.editing[1])

"How wide a card is in the page: 420 px at the usual size of the text, and no wider than the page's text"
contact_wide(v::ContactView) = (e = editor(v); min(CONTACT_WIDE * e.zoom, e.width))

"""
Keep what the field holds: write it into the line that was being changed, as
the name, or as a new detail. A contact that's left with no lines goes out of
the block. It's true when that changed the block.
"""
settle!(v::ContactView) = begin
  v.editing === nothing && return false
  k, what = v.editing
  text = contact_input(v).text
  v.editing = nothing
  locked(v) && return false
  list = Contacts.contacts(v.lines)
  fresh = k > length(list)
  c = fresh ? Contacts.Contact() : list[k]
  changed = what === :name ? Contacts.rename!(c, text) : what isa Symbol ? Contacts.add!(c, what, text) : Contacts.set!(c, what, text)
  changed || return false
  fresh && Contacts.add!(list, c)
  isempty(c.lines) && Contacts.remove!(list, k)
  write_block!(v, CONTACT, Contacts.written(list))
  true
end

"""
Put the field in the place of words of contact `k`, with the words in it and
selected. `what` is the line of the contact, or `:name`, or the kind of a new
detail, which starts with nothing in it.
"""
change!(v::ContactView, k::Int, what) = begin
  locked(v) && return handled
  c = contact_of(v, k)
  words = what === :name ? Contacts.title(c) : what isa Symbol ? "" : what in eachindex(c.lines) ? c.lines[what].value : nothing
  words === nothing && return handled
  input = contact_input(v)
  input.text = words
  input.anchor, input.cursor, input.scroll = 0, length(words), 0px
  input.placeholder = what === :name ? "Name" : what isa Symbol ? first(CONTACT_MENU[findfirst(m -> last(m) == what, CONTACT_MENU)]) : ""
  v.editing, v.waiting = (k, what), nothing
  v.clicked = (0.0, nothing, 0.0, 0.0)
  # The press isn't a click on the page's text, so the text doesn't select when the mouse moves
  e = editor(v)
  e.clicked = (e.clicked[1], e.clicked[2], 0)
  focus(input)
  handled
end

"Note a click on `what`. True when it's the second of two clicks in one place."
contact_twice!(v::ContactView, what, w) = begin
  at, on, x, y = v.clicked
  mx, my = num(w.mouse[1]), num(w.mouse[2])
  v.clicked = (time(), what, mx, my)
  time() - at < CONTACT_WAIT && on == what && hypot(mx - x, my - y) < 4
end

"True when the block can open something now. A window that isn't on the screen opens nothing, unless a test put its own function in place of the browser."
contact_opens(v::ContactView) = on_screen(v) || BROWSER[] !== open_url

"Open what line `i` of contact `k` names: a new email, a call, the Maps app or the browser"
use_row!(v::ContactView, k, i) = begin
  c = contact_of(v, k)
  i in eachindex(c.lines) || return nothing
  to = Contacts.link(c.lines[i])
  to === nothing || !contact_opens(v) || BROWSER[](to)
  nothing
end

"Write contact `k` as a vCard file in a folder for temporary files, and open the file, so the Contacts app asks to add it"
keep_contact!(v::ContactView, k) = begin
  c = contact_of(v, k)
  (Contacts.isblank(c) || !contact_opens(v)) && return nothing
  path = joinpath(mktempdir(), Contacts.filename(c))
  write(path, Contacts.vcard(c))
  BROWSER[](path)
  nothing
end

"Do what a button of a card does"
contact_act!(v::ContactView, action, w) = begin
  kind = action[1]
  # What was being changed is kept first. A line that went with it leaves the others in new places.
  n = length(v.lines)
  settle!(v)
  length(v.lines) == n || kind == :new || return handled
  if kind == :copy
    c = contact_of(v, action[2])
    if action[3] in eachindex(c.lines)
      clipboard!(w, c.lines[action[3]].value)
      v.copied = (time(), action[2], action[3])
      redraw_in!(v, CONTACT_COPIED + 0.05)   # so that the button shows its own icon again
    end
  elseif kind == :more
    # The menu hangs under the button, which stays while the menu is open
    k = action[2]
    v.menu = k
    show_menu!(w, [first(m) for m in CONTACT_MENU], w.mouse[1], w.mouse[2], 150px, theme=menu_theme(), item_height=28px, lift=3.0,
               under=v.parts[(:button, action)], gap=4px,
               onselect=j -> (v.menu = 0; j in eachindex(CONTACT_MENU) && change!(v, k, last(CONTACT_MENU[j])); nothing))
  elseif kind == :keep
    keep_contact!(v, action[2])
  elseif kind == :new
    change!(v, length(v.data) + 1, :name)
  end
  handled
end

"""
What happens to a block of contacts in each frame, before the page is laid
out. A click somewhere else keeps what the field holds. A click on a row
that no second click followed opens what the row names.
"""
block_tick!(v::ContactView) = begin
  w = window_of(v)
  typing = w !== nothing && w.focus === contact_input(v)
  v.editing === nothing || typing || settle!(v)
  # The field went, as when ⌘Z took its line back, so the page has the keyboard again
  v.editing === nothing && typing && focus(editor(v))
  if v.waiting !== nothing && time() - v.waiting[1] >= CONTACT_WAIT
    _, k, i = v.waiting
    v.waiting = nothing
    use_row!(v, k, i)
  end
  v
end

# The keys that the field has no use for come here. Return keeps what's typed, and esc leaves the words as they were.
onkey(v::ContactView, ev::KeyPress{Keys.enter}) = unmodified(ev) ? (ev.window.focus === contact_input(v) ? (settle!(v); focus(editor(v)); handled) : nothing) : nothing
onkey(v::ContactView, ev::KeyPress{Keys.escape}) = unmodified(ev) ? (ev.window.focus === contact_input(v) ? (v.editing = nothing; focus(editor(v)); handled) : nothing) : nothing

# Return, while the caret is on the block as a whole, starts on the name of its first contact
keyboard_part(v::ContactView) = locked(v) ? nothing : (v.editing === nothing && change!(v, 1, :name); contact_input(v))

describe(b::ContactButton) = begin
  ishovered(b) || (b.quiet = false)
  z = editor(b.of).zoom
  Box(fixed(20px * z), height(20px * z), radius(5px * z), Alignment.Center, name="Button", background(ishovered(b) ? colours.active : clear),
      Row(Alignment.Center, Icon(b.icon, size=13px * z, color=colours.dim)))
end

cursor(::ContactButton) = :hand
onmouse(b::ContactButton, ev::MouseMove) = begin
  (b.quiet || isempty(b.tip)) && return
  show_tooltip!(ev.window, tip_label(b.tip), b, placement=:bottom, gap=6px)
end
onkey(b::ContactButton, ev::KeyPress{Keys.mouse_left}) = begin
  b.quiet = true
  hide_tooltip!(ev.window)
  contact_act!(b.of, b.action, ev.window)
end

"""
The key, for drawing, of the picture that a contact names, or "" while there's
none to show. A file is named from the page's folder, as a picture line names
one. A picture from the web is fetched in the background and kept, as the
picture of a link card is. An email asks a web site for nothing.
"""
contact_photo(e, src::AbstractString) = begin
  isempty(src) && return ""
  occursin(r"^https?://"i, src) && return Eml.isemail(e.buf.path) ? "" : card_picture(e, src)
  something(picture_key(abspath(docdir(e), expanduser(unescaped(src)))), "")
end

describe(f::ContactFace) = begin
  v = f.of
  e = editor(v)
  z = e.zoom
  c = contact_of(v, f.k)
  side = CONTACT_FACE * z
  f.key = contact_photo(e, Contacts.photo(c))
  # With no photo: a building for a company, the initials of a person, and a head for a contact with no name yet
  letters = Contacts.initials(Contacts.title(c))
  mark = !isempty(f.key) ? () : Contacts.iscompany(c) ? (Icon("building", size=20px * z, color=colours.accent),) :
         isempty(letters) ? (Icon("person", size=22px * z, color=colours.faint),) :
         (label(letters, 16px * z, color=colours.accent, weight="Semibold"),)
  Box(fixed(side), height(side), radius(side / 2), Alignment.Center, name="Picture",
      background(isempty(letters) && !Contacts.iscompany(c) ? colours.hover : tint(colours.accent, 0.13)), Row(Alignment.Center, mark...))
end

# The photo fills the circle. What doesn't fit in a square is cut off at its sides, or at its top and bottom.
draw(ctx, size, ui::ConcreteRect, f::ContactFace) = begin
  isempty(f.key) && return
  source = try image_source(f.key) catch; return end
  w, h = Float64(source.width), Float64(source.height)
  side = min(w, h)
  side > 0 || return
  with_round_clip(ctx, ui.left, ui.top, ui.width, ui.height, ui.width / 2) do
    paint_picture(ctx, source.raw, ((w - side) / 2, (h - side) / 2, side, side), (num(ui.left), num(ui.top), num(ui.width), num(ui.height)))
  end
end

describe(t::ContactWords) = begin
  v = t.of
  z = editor(v).zoom
  c = contact_of(v, t.k)
  name = t.i === :name
  size, tall = name ? (15px * z, CONTACT_NAME * z) : (13px * z, CONTACT_LINE * z)
  if v.editing == (t.k, t.i)
    # The words are changed where they are, with no box round them. A field with words after it is as wide as what's typed.
    field = contact_input(v)
    typed = measure(Face(SANS, "", size, colours.ink, false), isempty(field.text) ? field.placeholder : field.text) + 4px * z
    wide = t.tight ? fixed(clamp(typed, 24px * z, max(24px * z, t.room))) : width(grow=grow)
    return contact_field(v, size, wide, height(tall))
  end
  words = name ? Contacts.title(c) : t.i in eachindex(c.lines) ? c.lines[t.i].value : ""
  face = Face(SANS, name ? "Semibold" : "", size, name ? colours.ink : colours.dim, false)
  # A contact with no name says where its name goes
  shown, colour = isempty(words) && name ? (on_paper(editor(v)) || locked(v) ? "" : "Name", colours.faint) : (shortened(face, words, t.room), face.color)
  Row(height(tall), Box(label(shown, size, color=colour, weight=face.style)))
end

cursor(t::ContactWords) = :arrow
# Two clicks change the words. A contact with no name takes its name at the first click. Any other click goes on to the page.
onkey(t::ContactWords, ev::KeyPress{Keys.mouse_left}) = begin
  v = t.of
  (only_held(v, Keys.opt) || locked(v) || v.editing == (t.k, t.i)) && return nothing
  twice = contact_twice!(v, (t.k, t.i), ev.window)
  settle!(v) && return nothing   # the click kept what was being changed, and the lines aren't where they were
  nameless = t.i === :name && isempty(Contacts.title(contact_of(v, t.k)))
  twice || nameless ? change!(v, t.k, t.i) : nothing
end

"The lines that the value of the detail `d` takes in a row with `room` for it. An address and a note wrap. Anything else is one line."
contact_lines(d::Contacts.Detail, face::Face, room) =
  d.kind in (:email, :web, :phone) || isempty(d.value) ? [d.value] : wrapped(face, d.value, num(room))

describe(r::ContactRow) = begin
  v, k = r.of, r.k
  e = editor(v)
  z = e.zoom
  c = contact_of(v, k)
  # A new detail that's being typed has no line yet
  d = r.i isa Symbol ? Contacts.Detail(r.i, "", "") : r.i in eachindex(c.lines) ? c.lines[r.i] : nothing
  d === nothing && return Box(height(0px))
  size, line, gap = 13px * z, CONTACT_LINE * z, 7px * z
  editing = v.editing == (k, r.i)
  to = Contacts.link(d)
  face = Face(SANS, "", size, to === nothing ? colours.ink : colours.accent, false)
  grey = Face(SANS, "", size, colours.dim, false)
  # The label of a row that has one is cut short before it takes more than a third of the row
  caption = shortened(grey, Contacts.caption(d), r.room / 3)
  room = r.room - 15px * z - gap - (isempty(caption) ? 0px : measure(grey, caption) + gap) - 20px * z - gap
  lines = contact_lines(d, face, room)
  cell(words, colour) = Row(height(line), Box(label(words, size, color=colour)))
  value = if editing
    # The words are changed where they are, with no box round them. The row stays as tall as it was.
    Column(width(grow=grow), Alignment.Start, contact_field(v, size, width(grow=grow), height(line)),
           (length(lines) > 1 ? (Box(height(line * (length(lines) - 1))),) : ())...)
  else
    Column(width(grow=grow), Alignment.Start, (cell(shortened(face, words, room), face.color) for words in lines)...)
  end
  over = ishovered(r) && !editing && !isempty(d.value) && !on_paper(e)
  done = v.copied[2:3] == (k, r.i) && time() - v.copied[1] < CONTACT_COPIED
  button = over || done ? (contact_button!(v, (:copy, k, r.i), done ? "check" : "copy", "Copy " * get(CONTACT_COPIES, d.kind, "this"), r),) : ()
  Row(width(grow=grow), Alignment.Start, child_gap=gap, name="Detail",
    Box(fixed(15px * z), height(line), Alignment.Center, Row(Alignment.Center, Icon(get(CONTACT_ICONS, d.kind, "tag"), size=13px * z, color=colours.dim))),
    (isempty(caption) ? () : (cell(caption, colours.dim),))...,
    value,
    Box(fixed(20px * z), height(line), Alignment.Center, button...))
end

cursor(r::ContactRow) = begin
  c = contact_of(r.of, r.k)
  r.i in eachindex(c.lines) && Contacts.link(c.lines[r.i]) !== nothing ? :hand : :arrow
end

# A click on a row opens what the row names, once it's known that no second click comes. Two clicks change
# the row's value. The click goes on to the page, which takes the keyboard back from the field.
onkey(r::ContactRow, ev::KeyPress{Keys.mouse_left}) = begin
  v = r.of
  (only_held(v, Keys.opt) || v.editing == (r.k, r.i)) && return nothing
  twice = contact_twice!(v, (r.k, r.i), ev.window)
  settle!(v) && return nothing   # the click kept what was being changed, and the lines aren't where they were
  c = contact_of(v, r.k)
  r.i in eachindex(c.lines) || return nothing
  # A page that can't be changed has no second click to wait for
  locked(v) && return use_row!(v, r.k, r.i)
  twice && return change!(v, r.k, r.i)
  if Contacts.link(c.lines[r.i]) !== nothing
    v.waiting = (time(), r.k, r.i)
    redraw_in!(v, CONTACT_WAIT + 0.02)
  end
  nothing
end

describe(card::ContactCard) = begin
  v, k = card.of, card.k
  e = editor(v)
  z = e.zoom
  c = contact_of(v, k)
  pad = CONTACT_PAD * z
  inner = contact_wide(v) - 2pad - 2px - CONTACT_FACE * z - pad   # how wide the column beside the picture is
  over = !on_paper(e) && (ishovered(card) || v.menu == k)
  # The buttons have their room at the top right, so the name isn't cut shorter when they show
  buttons = 44px * z
  name = contact_words!(v, k, :name)
  name.room, name.tight = inner - buttons - 4px * z, false
  filler(node) = v.editing == (k, node.i) && !node.tight ? () : (Box(width(grow=grow)),)
  head = Row(width(grow=grow), height(CONTACT_NAME * z), justify=Alignment.Start, name, filler(name)...,
    Row(fixed(buttons), height(20px * z), child_gap=2px * z, justify=Alignment.End,
      (over && !locked(v) ? (contact_button!(v, (:more, k), "plus", "Add a detail", card),) : ())...,
      (over && !Contacts.isblank(c) ? (contact_button!(v, (:keep, k), "person-plus", "Add to Contacts", card),) : ())...))
  # Under the name of a person: the role, a comma, the company
  role, firm = Contacts.under(c)
  grey = Face(SANS, "", 13px * z, colours.dim, false)
  both = role !== nothing && firm !== nothing
  comma = both ? measure(grey, ",") + 4px * z : 0px
  under = Any[]
  taken = 0px
  if role !== nothing
    t = contact_words!(v, k, role)
    # The company keeps half of the line at the least
    t.tight, t.room = both, both ? max(inner / 2, inner - comma - measure(grey, c.lines[firm].value)) : inner
    taken = min(measure(grey, c.lines[role].value), t.room)
    push!(under, t)
    both && push!(under, Row(height(CONTACT_LINE * z), Box(label(",", 13px * z, color=colours.dim))), Box(width(4px * z)))
  end
  if firm !== nothing
    t = contact_words!(v, k, firm)
    t.tight, t.room = false, inner - taken - comma
    push!(under, t)
  end
  tag = isempty(under) ? () : (Row(width(grow=grow), height(CONTACT_LINE * z), justify=Alignment.Start, under..., filler(under[end])...),)
  rows = Any[contact_row!(v, k, i) for i in Contacts.rows(c)]
  # A new detail that's being typed is a row at the end
  v.editing !== nothing && v.editing[1] == k && v.editing[2] isa Symbol && v.editing[2] !== :name && push!(rows, contact_row!(v, k, v.editing[2]))
  foreach(r -> r.room = inner, rows)
  # Under the details: the to-do items that name the contact, with a line over them
  work = contact_work(v, k)
  jobs = isempty(work) ? () :
    (Box(height(6px * z)), Box(fixed(inner), height(1px), background(colours.line)), Box(height(4px * z)),
     [(r = contact_part!(() -> ContactWork(of=v, k=k, i=i), v, (:work_row, k, i), card); r.room = inner; r) for i in 1:min(length(work), WORK_ROWS)]...,
     (length(work) > WORK_ROWS ? (Row(fixed(inner), height(CONTACT_LINE * z), padding(0px, 0px, 0px, 25px * z), Alignment.Center,
                                    Box(label("and $(length(work) - WORK_ROWS) more", 11.5px * z, color=colours.faint)), Box(width(grow=grow))),) : ())...)
  # A card with only a name, or a name and the line under it, has them level with the middle of the picture
  # A card is marked while the mouse is on its contact in another part of the page, like its pin on a map
  lit = !ishovered(card) && !isempty(Contacts.title(c)) && marked(v, Contacts.title(c))
  Row(fixed(contact_wide(v)), isempty(rows) && isempty(jobs) ? Alignment.Center : Alignment.Start, padding(pad), child_gap=pad, radius(8px), border(1px, :solid, lit ? colours.accent : colours.line),
      background(lit ? mark_colour(colours.block) : colours.block), clip=true, name="Contact",
    contact_part!(() -> ContactFace(of=v, k=k), v, (:face, k), card),
    Column(width(grow=grow), Alignment.Start, head, tag..., (isempty(rows) ? () : (Box(height(5px * z)),))..., rows..., jobs...))
end

cursor(::ContactCard) = :arrow
cursor(::ContactView) = :arrow

describe(v::ContactView) = begin
  e = editor(v)
  z = e.zoom
  wide = contact_wide(v)
  cards = [contact_card!(v, k) for k in 1:contact_cards(v)]
  # The button that adds a contact has its room under the last card, so the page doesn't move when it shows.
  # It's there while the mouse is over the block, and not while a new contact gets its name.
  adds = !locked(v) && !on_paper(e)
  starting = v.editing !== nothing && v.editing[1] > length(v.data)
  more = !adds ? () : (Row(fixed(wide), height(22px * z), justify=Alignment.Start,
    (ishovered(v) && !starting && !isempty(v.data) ? (contact_button!(v, (:new,), "plus-circle", "Add a contact", v),) : ())...),)
  Box(width(grow=grow), Alignment.Start,
    Column(fixed(wide), Alignment.Start, name="Contacts",
      Column(fixed(wide), Alignment.Start, child_gap=8px * z, cards...), more...))
end

"The contacts of the block as HTML: a card for each one, with the class names of the h-card microformat"
contact_html(e, v::ContactView) = Contacts.markup(v.data)

BLOCKS[CONTACT] = BlockKind("Contact", "person-vcard", ContactView, contact_html)

# --- contacts from a vCard ---------------------------------------------------------------------
#
# The Contacts app writes a contact as a vCard: a .vcf file, or text that
# starts with BEGIN:VCARD. contact.jl reads one. A vCard file that's dropped
# on the page, or pasted, goes in as a block of its contacts.

"The contacts that the file at `path` holds, when it's a vCard file. Any other file has none, and so has one that can't be read."
file_contacts(path::AbstractString) = begin
  (isfile(path) && lowercase(splitext(path)[2]) in (".vcf", ".vcard")) || return Contacts.Contact[]
  try Contacts.from_vcard(read(path, String)) catch; Contacts.Contact[] end
end

"The contacts of the vCard files among `paths`, and the paths that are left"
split_contacts(paths) = begin
  list = Contacts.Contact[]
  rest = filter(paths) do p
    found = file_contacts(p)
    foreach(c -> Contacts.add!(list, c), found)
    isempty(found)
  end
  (list, rest)
end

"The block of contacts under the mouse, or nothing. Only a block that the page shows now is where it was last drawn."
contacts_at(e, w) = begin
  x, y = w.mouse
  for it in view(e.layout, intersect(e.shown, eachindex(e.layout)))
    node = it.content isa Live ? it.content.node : nothing
    node isa ContactView || continue
    r = rect(node)
    r !== nothing && r.left <= x < r.left + r.width && r.top <= y < r.top + r.height && return node
  end
  nothing
end

"Add `list` to the contacts of the block, each one after an empty line. It's true when the block took them."
add_contacts!(v::ContactView, list) = begin
  (isempty(list) || locked(v)) && return false
  settle!(v)
  all = Contacts.contacts(v.lines)
  foreach(c -> Contacts.add!(all, c), list)
  write_block!(v, CONTACT, Contacts.written(all))
  true
end

"""
Put the contacts of `list` into the text at `at`, and give the place for the
caret. In a block of contacts, they join the block. Anywhere else, they go in
as a new block under the block that `at` is in, as a picture that's dropped
does, and the caret goes to an empty line under it.
"""
put_contacts!(e, list, at::Pos) = begin
  b = e.buf
  (isempty(list) || readonly(b) || b.fixed) && return at
  ks = kinds(b)
  if ks[at[1]].kind in (Kind.fence, Kind.code)
    s, t = codeblock(b, at[1])
    if ks[s].lang == CONTACT && t > s && ks[t].kind == Kind.fence && ks[t].level == 1
      all = Contacts.contacts(b.lines[s+1:t-1])
      foreach(c -> Contacts.add!(all, c), list)
      edit!(b, line_end(b, s), line_end(b, t - 1), "\n" * join(Contacts.written(all), "\n"))
      return (s, 0)
    end
  end
  under = block_end(b, at[1])
  empty = isempty(strip(b.lines[under]))
  block = ["```$CONTACT"; Contacts.written(collect(Contacts.Contact, list)); "```"]
  # An empty line goes under the block, for the caret, unless the page has one there
  spare = under < length(b.lines) && isempty(strip(b.lines[under+1]))
  edit!(b, empty ? (under, 0) : line_end(b, under), line_end(b, under), (empty ? "" : "\n\n") * join(block, "\n") * (spare ? "" : "\n"))
  (under + (empty ? 0 : 2) + length(block), 0)
end

"Put the contacts of `list` in the page at the caret, in place of what's selected, as ⌘V does with a contact that was copied"
paste_contacts!(e, list) = begin
  b = e.buf
  selecting(b) && type!(e, "")
  b.caret = b.anchor = put_contacts!(e, list, settle(b, b.caret))
  focus(e)
  touch!(e)
end

"""
The contacts that ⌘V pastes, or none: the clipboard holds the text of a
vCard, or a contact that was copied in the Contacts app. In a code block of
another language, a vCard is pasted as its text.
"""
copied_contacts(e, text::AbstractString) = begin
  b = e.buf
  b.view == :markdown || return Contacts.Contact[]   # a file of code has no blocks
  k = kinds(b)[b.caret[1]]
  k.kind == Kind.code && kinds(b)[codeblock(b, b.caret[1])[1]].lang != CONTACT && return Contacts.Contact[]
  card = Contacts.isvcard(text) ? text : Sys.isapple() ? Pasteboard.vcard() : ""
  try Contacts.from_vcard(card) catch; Contacts.Contact[] end
end

# --- a signature -------------------------------------------------------------------------------
#
# A code block in the language `signature` is a place where a person signs
# the page with the mouse or the trackpad. signature.jl says how the block is
# written. The block shows a box with a line to sign on, and under it the
# name of who signs. A block with no name has a field there to type it in.
#
#   - Press in the box and drag to draw. Each stroke is a line of the block,
#     so the file holds the signature, and ⌘Z takes back the last stroke.
#   - The first stroke writes the day and the time. From then on the block
#     says who signed and on which day.
#   - A stroke that leaves the box goes on when the mouse comes back. The
#     page's text doesn't select meanwhile, and the page doesn't scroll.
#   - While the mouse is over a signed block, a Clear button shows. It takes
#     the strokes and the day away, and ⌘Z brings them back.
#   - A page that can't be changed, like an email, takes no strokes.

const SIGNATURE = Signatures.SIGNATURE
push!(BLOCK_ICONS, "pen")
const SIGN_STEP = 1.0   # how far the mouse moves, in the box's own measure, before a stroke gets a new place
"The clock that says when a block is signed. A test puts its own clock here."
const sign_clock = Ref{Function}(Dates.now)

"What a `signature` block shows: a box to sign in, and the name of who signs"
@def mutable struct SignatureView <: SemanticUI
  n::Int = 0                               # its place among the page's signatures
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  data::Signatures.Signature = Signatures.Signature()
  lines::Vector{String} = String[]         # the lines that `data` was read from
  draft::Any = nothing                     # the places of the stroke that's being drawn, or nothing
  asked::Bool = false                      # the block had no name once, so its field takes the name
  stay::px = 0px                           # how far the page was scrolled when the stroke started
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the box was last drawn in the window
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its box, its field and its button, kept between frames
end

"The box of a signature that's drawn in"
@def mutable struct SignArea <: SemanticUI
  of::Any = nothing
end

sign_area(v::SignatureView) = block_part!(() -> SignArea(of=v), v, :area)

"The text field that takes the name of who signs"
signer_input(v::SignatureView) = block_part!(v, :input) do
  TextInput(placeholder="Type your name", font_family=SANS, font_size=13px,
            look=(_, text) -> Row(width(grow=grow), height(grow=grow), clip=true, text))
end

reread!(v::SignatureView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.data = Signatures.signature(lines)
  # The field shows the name that the block has, as it does after ⌘Z takes some of it back
  i = signer_input(v)
  strip(i.text) == v.data.name || (i.text = v.data.name; i.anchor = i.cursor = length(i.text))
  v
end

"True for a signature in a page that can't be changed, like an email. It takes no strokes."
locked(v::SignatureView) = (b = editor(v).buf; readonly(b) || b.fixed)

"True while the page is drawn for paper. Printing puts the caret on no line."
on_paper(v::SignatureView) = editor(v).buf.caret[1] == 0

"""
True when a field under the box takes the name: the block has no name, or it
had none and the name was typed in the field. A signed block has no field.
"""
asks(v::SignatureView) = begin
  isempty(v.data.name) && (v.asked = true)
  v.asked && !Signatures.issigned(v.data) && !locked(v) && !on_paper(v)
end

"How wide the box is in the page: 420 px at the usual size of the text, and no wider than the page's text"
sign_wide(v::SignatureView) = (e = editor(v); min(px(Signatures.WIDE * e.zoom), e.width))

"How many px of the window one of the box's own measure is"
sign_scale(v::SignatureView) = v.box[3] > 0 ? v.box[3] / Signatures.WIDE : num(sign_wide(v)) / Signatures.WIDE

"The place in the box that's at `pos` in the window. A place outside the box has numbers that are outside it."
sign_place(v::SignatureView, pos) = (s = sign_scale(v); ((num(pos[1]) - v.box[1]) / s, (num(pos[2]) - v.box[2]) / s))

describe(a::SignArea) = begin
  wide = sign_wide(a.of)
  Box(fixed(wide), height(wide * (Signatures.TALL / Signatures.WIDE)), radius(8px), border(1px, :solid, colours.line),
      background(takeoff_back()), name="Box to sign in")
end

draw(ctx, size, ui::ConcreteRect, a::SignArea) = begin
  v = a.of
  v.box = (num(ui.left), num(ui.top), num(ui.width), num(ui.height))
  v.box[3] > 0 || return
  s = sign_scale(v)
  at(p) = (v.box[1] + p[1] * s, v.box[2] + p[2] * s)
  with_round_clip(ctx, ui.left, ui.top, ui.width, ui.height, 8px) do
    # The line to sign on, and the ✕ at its left end, as paper forms have
    trace(ctx, [at((Signatures.EDGE, Signatures.LINE)), at((Signatures.WIDE - Signatures.EDGE, Signatures.LINE))], colours.marker, 1.0)
    foreach(((from, to),) -> trace(ctx, [at(from), at(to)], colours.dim, max(1.0, 1.5s)), Signatures.CROSS)
    # The words go with the first stroke. A page that takes no strokes doesn't ask for one.
    if !Signatures.issigned(v.data) && v.draft === nothing && !locked(v)
      face = Face(SANS, "", 13px * editor(v).zoom, colours.faint, false)
      write_ink(ctx, "Sign here", v.box[1] + (v.box[3] - num(measure(face, "Sign here"))) / 2, at((0.0, Signatures.LINE - 12))[2], face)
    end
    # The ink is the colour of the page's text, with round ends
    paint = ink(colours.ink, max(1.2, Signatures.INK * s))
    foreach(points -> draw_curve(ctx, at.(points), paint), v.data.strokes)
    v.draft === nothing || draw_curve(ctx, at.(v.draft), paint)
    Skia.sk_paint_delete(paint)
  end
end

cursor(a::SignArea) = locked(a.of) ? :arrow : :crosshair
cursor(::SignatureView) = :arrow

# A press in the box starts a stroke. The click goes on to the page, which takes the keyboard back from the
# name's field. With ⌥ held the page shows the block's lines, and a page that can't be changed takes no strokes.
onkey(a::SignArea, ev::KeyPress{Keys.mouse_left}) = begin
  v = a.of
  (only_held(v, Keys.opt) || locked(v) || v.box[3] <= 0) && return nothing
  v.draft === nothing || drop!(v)   # a stroke that no frame has taken yet
  v.draft = Signatures.Place[sign_place(v, ev.window.mouse)]
  v.stay = editor(v).scroll.offset
  nothing
end

# UI.jl gives the box each move of the mouse while its button is down, in the box or out of it
onmouse(a::SignArea, ev::MouseMove) = begin
  v = a.of
  v.draft === nothing && return nothing
  Keys.mouse_left in ev.window.keys || return handled
  p = sign_place(v, ev.position)
  hypot((p .- v.draft[end])...) >= SIGN_STEP && push!(v.draft, p)
  handled   # the drag is the signature's, so the page's text doesn't select
end

# The wheel doesn't scroll the page under a stroke that's being drawn
onscroll(a::SignArea, ::MouseScroll) = a.of.draft === nothing ? nothing : handled

"The mouse let go. The stroke that was drawn joins the signature, and the first stroke writes the day and the time."
drop!(v::SignatureView) = begin
  points = v.draft
  v.draft = nothing
  points === nothing && return v
  Signatures.sign!(v.data, points, sign_clock[]()) && write_block!(v, SIGNATURE, Signatures.written(v.data))
  v
end

block_tick!(v::SignatureView) = begin
  if v.draft !== nothing
    # The page stays where it was while a stroke is drawn, whatever scrolls it
    held(v, Keys.mouse_left) ? (editor(v).scroll.offset = v.stay) : drop!(v)
  end
  # What was typed in the field is written into the block as the name
  name = String(strip(signer_input(v).text))
  name == v.data.name && return v
  v.data.name = name
  write_block!(v, SIGNATURE, Signatures.written(v.data), typing=true)
end

describe(v::SignatureView) = begin
  e = editor(v)
  s = v.data
  signed = Signatures.issigned(s)
  input = signer_input(v)
  input.color = colours.ink
  w = window_of(v)
  typing = w !== nothing && w.focus === input
  with_theme(component_theme(e.zoom)) do
    # Under the box: who signed and when, or the field that takes the name, or the name. The words are
    # bigger in a page whose text is bigger, as the box is.
    size = 13px * e.zoom
    under = signed ? (Box(width(grow=grow), Text(Signatures.caption(s), size=size, family=SANS, color=colours.dim, wrap=WrapMode.words)),) :
            asks(v) ? (Box(fixed(min(sign_wide(v), 240px * e.zoom)), height(28px * e.zoom), padding(9px, 0px), radius(6px), background(colours.bg),
                           border(1px, :solid, typing ? colours.accent : colours.line), input), Box(width(grow=grow))) :
            (Box(width(grow=grow), Text(s.name, size=size, family=SANS, subfamily="Medium", color=colours.ink, wrap=WrapMode.words)),)
    # The Clear button shows while the mouse is over a signed block, and never on paper
    clear = signed && ishovered(v) && v.draft === nothing && !locked(v) && !on_paper(v) ?
      (block_button!(v, :clear, :clear, words="Clear", tip="Take the signature away"),) : ()
    Box(width(grow=grow), Alignment.Start,
      Column(fixed(sign_wide(v)), Alignment.Start, child_gap=6px, name="Signature",
        sign_area(v),
        Row(width(grow=grow), height(min=26px), child_gap=8px, Alignment.Center, under..., clear...)))
  end
end

# Clear takes the strokes and the day away in one change, so one ⌘Z brings them back
act!(v::SignatureView, action, w) = begin
  action == :clear || return handled
  Signatures.clear!(v.data)
  write_block!(v, SIGNATURE, Signatures.written(v.data))
  handled
end

# Return in the name's field gives the keyboard back to the page
onkey(v::SignatureView, ev::KeyPress{Keys.enter}) = unmodified(ev) ? (focus(editor(v)); handled) : nothing

"The signature as HTML: a picture of the box and its strokes, with who signed and when under it"
signature_html(e, v::SignatureView) = begin
  s = v.data
  picture = Signatures.svg(s, ink="#2b2622", line="#d8d0bd", mark="#6b6259")
  under = Signatures.issigned(s) ? Signatures.caption(s) : s.name
  "<div class=\"diagram\">\n$picture\n</div>" *
  (isempty(under) ? "" : "\n<p style=\"margin-top: -0.5em; font-size: 0.88em; color: #6b6259\">$(escape(under))</p>")
end

BLOCKS[SIGNATURE] = BlockKind("Signature", "pen", SignatureView, signature_html)
# --- a link card -------------------------------------------------------------------------------
#
# A line that holds only the address of a web page, written as a picture's
# is, like ![Julia](https://julialang.org), shows a card: the page's title,
# two lines of its description, its picture, and the name of its site beside
# the site's icon. The line's own text shows again while the caret is on it,
# as a picture's does. A click on the card with ⌘ held opens its address in
# the browser. In a page that's never changed, a click opens it with no key
# held. Any other click puts the caret on the line.
#
# What's at the address decides what the line shows. An address whose name
# ends as a picture's, a video's, a sound's or a table's does, like .png, shows
# that, and Ladder asks for no card. For any other address, Ladder gets the
# start of what's there, in the background. A web page shows as a card.
# Anything else, like a picture whose address doesn't end in .png, shows as a
# picture. Until Ladder knows, the line shows a card with the address.
#
# Ladder reads what the page says of itself. See linkcard.jl. It keeps that,
# and the picture, in a folder of the Mac's caches, so the card shows at once
# the next time, and with no network. When the page can't be had, the card
# shows the address. Ladder asks the web for nothing in a window that isn't
# on the screen. An email shows no cards: each such line in it is a picture.

push!(BLOCK_ICONS, "globe")

"What opens the address of a card: the browser. A test puts its own function here."
const BROWSER = Ref{Function}(open_url)

"The folder that keeps what the cards read from the web, and their pictures"
cards_dir() = isempty(MEDIA_CACHE[]) ? joinpath(homedir(), "Library", "Caches", "Ladder", "cards") : joinpath(MEDIA_CACHE[], "cards")

"A card that a line of the page shows: what the web page at the line's address says of itself"
@def mutable struct LinkCard <: SemanticUI
  line::Int = 0
  words::String = ""     # the line's words for the card, between its [ and ], which show while the page has no title
  card::Cards.Card = Cards.Card("")
  picture::String = ""   # the key of the page's picture, for an Image, or "" while there's none
  icon::String = ""      # and the key of the site's icon
end

# The sizes of a card's title, of its description and of the name of its site, as parts of the size of the page's text
const CARD_TITLE, CARD_WORDS, CARD_SOURCE = 0.92, 0.8, 0.74
const CARD_LINE = 1.36   # how tall a line of a card is, as a part of the size of its text
const CARD_PAD = 0.65    # the room inside a card's edge, as a part of the size of the page's text

"How tall a card is in a page whose text is `s` tall. Every card is as tall as the next, so the page's text doesn't move when a card fills in."
card_tall(s) = s * (2CARD_PAD + CARD_LINE * (CARD_TITLE + 2CARD_WORDS + CARD_SOURCE) + 0.45)

"`words` cut short with … so that they're no wider than `room` in `face`"
shortened(face::Face, words::AbstractString, room) = begin
  (room <= 0px || measure(face, words) <= room) && return String(words)
  cs = collect(words)
  lo, hi = 0, length(cs)
  while lo < hi
    mid = (lo + hi + 1) ÷ 2
    measure(face, rstrip(String(cs[1:mid])) * "…") <= room ? (lo = mid) : (hi = mid - 1)
  end
  rstrip(String(cs[1:lo])) * "…"
end

"The picture with the key `key` in a box `wide` by `tall`. The picture fills the box, and the box cuts off what doesn't fit."
covered(key, wide, tall) = begin
  aspect = image_aspect(key)
  w, h = aspect > wide / tall ? (tall * aspect, tall) : (wide, wide / aspect)
  Box(fixed(wide), height(tall), radius(6px), clip=true, Image(key, fixed(w), height(h)))
end

"""
True when Ladder can ask the web for what a card shows: the page isn't an
email, and its window is on the screen. A window that a test makes isn't, so a
test asks the web for nothing, unless it put its own function in place of `curl`.
"""
online(e) = !Eml.isemail(e.buf.path) && (Cards.getter[] !== Cards.curl || (w = window_of(e); w !== nothing && !isempty(w.glfw)))

"The key, for an Image, of the picture at the web address `url`, or \"\" while Ladder has none. It asks for the next frame while the picture is on its way."
card_picture(e, url) = begin
  file, coming = Cards.picture!(url, cards_dir(), ask=online(e))
  coming && redraw_in!(e, 0.2)   # look again soon
  file === nothing ? "" : something(picture_key(file), "")
end

# The ends of the names of the files that a line shows as what they are, and never as a card
const NOT_CARDS = (PICTURES..., MAC_PICTURES..., VIDEOS..., SOUNDS..., TABLES..., ".pdf")

"""
True when a line of `e` that holds only `src`, written as a picture is, can
show a card: `src` is a web address, its name doesn't end as a picture's, a
video's, a sound's or a table's does, and the page isn't an email.
"""
card_address(e, src) = Cards.isaddress(src) && !Eml.isemail(e.buf.path) && !(lowercase(splitext(Cards.path(src))[2]) in NOT_CARDS)

"""
What line `i` shows when it holds only the address `src` of a web page,
written as a picture is: a card. `words` are the line's words for the card.
It's nothing when the address can't show a card, and when what's there turned
out not to be a page. That line shows what's there as a picture.
"""
card_item(e, i, src, words) = begin
  card_address(e, src) || return nothing
  card, coming = Cards.lookup!(src, cards_dir(), ask=online(e))
  coming && redraw_in!(e, 0.2)   # look again soon
  card.page || return nothing
  c = node!(LinkCard, e, (:link_card, i))
  # A picture that the card has already isn't looked for again on each frame
  same = c.card == card
  c.line, c.words, c.card = i, words, card
  same && !isempty(c.picture) || (c.picture = card_picture(e, card.image))
  same && !isempty(c.icon) || (c.icon = card_picture(e, card.icon))
  own!(node!(Document, e, :document), c)
  Live(c, card_tall(body(e).size) + 2LIVE_GAP)
end

describe(c::LinkCard) = begin
  e = editor(c)
  s, wide, card = body(e).size, e.width, c.card
  pad = s * CARD_PAD
  inside = card_tall(s) - 2pad - 2px
  # The picture is at the right, and takes no more than a third of the card
  across = isempty(c.picture) ? 0px : min(inside * 1.75, wide * 0.3)
  room = wide - 2pad - 2px - (across > 0px ? across + pad : 0px)
  # An address that stands in for the title isn't bold
  heading = Cards.heading(card, c.words)
  title = Face(SANS, heading == card.url ? "" : "Semibold", s * CARD_TITLE, colours.ink, false)
  words = Face(SANS, "", s * CARD_WORDS, colours.dim, false)
  source = Face(SANS, "", s * CARD_SOURCE, colours.faint, false)
  line(face, text, room) = Box(width(grow=grow), height(face.size * CARD_LINE), Alignment.Start, justify=Alignment.Center,
                               label(shortened(face, text, room), face.size, color=face.color, weight=face.style))
  # The description has two lines at most, and the second ends in … when there's more
  under = Cards.blurb(card, c.words)
  told = isempty(under) ? String[] : wrapped(words, under, num(room))
  length(told) > 2 && (told = [told[1], join(told[2:end], " ")])
  mark = source.size * 1.15
  # Many sites have a dark icon with nothing behind it, which a dark page would hide. There it has a light square behind it.
  page = convert(RGBA{Float64}, colours.bg)
  behind = page.r + page.g + page.b < 1.5 ? (background(RGBA(1, 1, 1, 0.85)),) : ()
  Row(width(grow=grow), height(card_tall(s)), padding(pad), child_gap=pad, radius(8px), border(1px, :solid, colours.line),
      background(ishovered(c) && opening(c) ? colours.hover : colours.block), name="Link card",
    Column(width(grow=grow), height(inside), Alignment.Start,
      line(title, heading, room),
      (line(words, text, room) for text in told)...,
      Box(width(grow=grow), height(grow=grow)),
      Row(width(grow=grow), height(source.size * CARD_LINE), justify=Alignment.Start, child_gap=s * 0.35,
        isempty(c.icon) ? Icon("globe", size=mark, color=colours.faint) : Image(c.icon, fixed(mark), height(mark), radius(3px), behind...),
        Box(label(shortened(source, Cards.source(card), room - mark - s * 0.35), source.size, color=source.color)))),
    (across > 0px ? (covered(c.picture, across, inside),) : ())...)
end

"True when a click on the card now opens its address: ⌘ alone is held, or the page is one that's never changed and no key is held"
opening(c::LinkCard) = only_held(c, Keys.cmd) || (editor(c).buf.fixed && unmodified(c))

cursor(c::LinkCard) = opening(c) ? :hand : :arrow
# A click with ⌘ held opens the address. Any other click goes to the page, which puts the caret on the card as a whole.
onkey(c::LinkCard, ev::KeyPress{Keys.mouse_left}) = opening(c) ? (BROWSER[](c.card.url); handled) : click_page!(c, ev)

"""
The HTML of the line `text` when it shows a card: the card as a link in a box.
It's nothing for any other line. The rules that give a card its look come with
the first card of the page. `styled` is true once they're in.
"""
card_html(e, text, styled::Ref{Bool}) = begin
  occursin("![", text) || return nothing
  m = match(PICTURE_LINE, text)
  m === nothing && return nothing
  src = unescaped(String(m[2]))
  card_address(e, src) || return nothing
  card = first(Cards.lookup!(src, cards_dir(), ask=online(e)))
  card.page || return nothing
  rules = styled[] ? "" : "<style>\n" * Cards.STYLE * "</style>\n"
  styled[] = true
  rules * Cards.markup(card, unescaped(String(m[1])))
end

# --- a page of the web ------------------------------------------------------------------------
#
# A `view` block shows a page of the web, or the page of an HTML file, with
# Ladder's own engine: see web/browser.jl and "a view of another file". Its
# line is the page's address, like https://julialang.org, or the name of an
# HTML file beside the document. A block whose first line starts with a tag,
# like `<h1>`, holds the HTML of the page itself.
#
# The page's scripts run, and the page is yours to use where it is, as a
# model in the page is:
#
#   - A click follows a link or presses a button, and a drag goes to the
#     page's scripts, as a drag turns a model that a script draws. After a
#     click the page has the keyboard, so you type in its fields. Esc gives
#     the keyboard back to the document.
#   - The wheel scrolls the document, so the page doesn't stop it as it goes
#     past. With ⌘ held the wheel is the page's, and so is a pinch: a script
#     hears it as a browser sends it, as the wheel with Ctrl held.
#   - A click with ⌘ held goes to the page, as the button beside the block's
#     top right corner does. With ⌥ held the document shows the block's line.
#
# The block's line always says the page that shows. When a link goes to
# another page, the line becomes that page's address, and ⌘Z in the document
# takes it back, and the page with it. A page that the block held goes back
# into the block as its HTML.
#
# A block in the language `web` is a `view` block too: `web` is the name that
# it had before.
#
# A page of an email asks the web for nothing, so a `view` block there shows
# no page of the web. A window that isn't on the screen asks for nothing
# either, unless a test put its own function in `WEB_GETTER`.

"The name that a `view` block of a page of the web had before, which still works"
const WEBVIEW = "web"
const WEB_HIGH = 420px     # how tall the page is in the document at the most, before the zoom
const WEB_LEAST = 60px     # and at the least
push!(BLOCK_ICONS, "globe", "arrow-left", "arrow-right", "arrow-clockwise", "box-arrow-up-right", "fullscreen-exit")

"What gets a file from the web for the page of a `view` block. A test puts its own function here, so that it uses no network."
const WEB_GETTER = Ref{Function}(Webfiles.curl)

"True when a `view` block of `e` may ask the web for its page: the document isn't an email, and its window is on the screen or a test stands in for `curl`"
web_online(e) = !Eml.isemail(e.buf.path) && (WEB_GETTER[] !== Webfiles.curl || on_screen(e))

"""
What the lines of a `view` block of a page ask for: its address, or the HTML
of one with the address that the addresses in it are from. The name of a
file beside the document is that file.
"""
web_source(e, lines) = begin
  i = findfirst(l -> !isempty(strip(l)), lines)
  i === nothing && return (address="", html="", base="")
  dir = docdir(e)
  first = String(strip(lines[i]))
  # A block that starts with a tag holds the page itself. Its addresses are from the document's folder.
  startswith(first, '<') && return (address="", html=join(lines, "\n"), base="file://" * joinpath(abspath(dir), "page.html"))
  if !occursin(r"^[a-z][a-z0-9+.-]*:"i, first)
    file = startswith(first, '~') ? expanduser(first) : joinpath(dir, first)
    isfile(file) && return (address=abspath(file), html="", base="")
  end
  (address=first, html="", base="")
end

"The lines of a `view` block that say `page`: its address, or the HTML of a page that was written in the block. A file in the document's folder is said by its name there."
web_lines(e, page) = begin
  page isa Browsers.Written && return String.(split(page.html, '\n'))
  file = Webfiles.path(page)
  dir = joinpath(abspath(docdir(e)), "")
  file !== nothing && startswith(file, dir) && isfile(file) && return [relpath(file, dir)]
  [String(page)]
end

"True when `lines`, the lines of a `view` block, say `page`"
web_says(e, lines, page) = begin
  src = web_source(e, lines)
  page isa Browsers.Written && return src.html == page.html && src.base == page.base
  isempty(src.html) || return false
  said = Browsers.whole(src.address)
  # A file can be said by its path or by a file:// address
  file = Webfiles.path(said)
  file === nothing ? said == page : file == Webfiles.path(page)
end

# The scripts of the page in a `view` block can read the sums of the document. `ladder.sums` has the value of each sum
# in a line of text that gives a name, like !`span = 70m`, and `ladder.shown` has the text that the document shows for
# it. The page hears the event `sums` when it's given them, and again each time they change, as while a number is
# dragged. A page whose scripts wait for a module can find them already there, so it reads them at its start too.

"The units that a page's script gets amounts in: SI units, with the kilogram for mass"
const SI_UNITS = ((Units.Length, Units.m), (Units.Mass, Units.kg), (Units.Time, Units.s), (Units.Current, Units.A),
                  (Units.Temperature, Units.K))

"""
What a script of a web page gets for the value `x` of a sum: a number, true
or false, or words. An amount is a number in SI units: 70m is 70, 150kW is
150000, 500g is 0.5 and 98% is 0.98. Money is a number of its currency, so
25USD/W is 25. A value that is none of these is nothing.
"""
script_value(x::Bool) = x
script_value(x::AbstractString) = String(x)
script_value(x::Real) = Float64(x)
script_value(x::Units.Unit) = try
  # Units.jl has no rates between currencies, so the currency comes out first
  bits, _ = Units.flatten_units(typeof(x))
  i = findfirst(u -> Units.unwrap(u) <: Cash.Money, bits)
  i === nothing || (x = x / Units.unwrap(bits[i])(1))
  x isa Units.Unit || return Float64(x)
  # Units.jl's own base for mass is the gram, so the amount is converted to SI units by name
  si = nothing
  for d in Units.dimensions(typeof(x))
    D = Units.unwrap(d)
    D <: Units.NullDimension && continue
    j = findfirst(((kind, _),) -> D <: kind, SI_UNITS)
    j === nothing && return nothing
    u = SI_UNITS[j][2]^Units.power(d)
    si = si === nothing ? u : si * u
  end
  si === nothing ? convert(Float64, x) : Float64(convert(si, x).value)
catch
  nothing
end
script_value(x) = nothing

"""
The sums of the document of `e` that give a name, for the scripts of a web
page: what each name came to as `script_value` gives it, and the text that
the document shows for it. A sum that went wrong, or that hasn't run, is
left out. When two sums give one name, the lower one counts.
"""
script_sums(e) = begin
  b = e.buf
  sums, shown = Dict{String,Any}(), Dict{String,Any}()
  values = get(e.nodes, (:sum_values, b.path), nothing)
  values === nothing && return sums, shown
  for (_, code, n) in given_and_sums(e, typemax(Int), true)[2]
    haskey(values, (code, n)) || continue
    out = get(e.nodes, (:inline, b.path, code, n), nothing)
    (out isa Tuple && !out[2]) || continue
    x = script_value(values[(code, n)])
    x === nothing && continue
    name = String(sum_name(code))
    sums[name], shown[name] = x, out[1]
  end
  sums, shown
end

"""
Give the scripts of the page of the `view` block `v` the sums of the document,
if they've changed since it was last given them, and tell the page with the
event `sums`.
"""
send_sums!(v) = begin
  b = web_browser(v)
  l = Browsers.live(b)
  # The page starts as the browser draws, which doesn't lay the block out again. So the block looks again soon.
  (l === nothing || Browsers.loading(b)) && (isempty(b.address) && isempty(b.html) || redraw_in!(v, 0.25))
  l === nothing && return v
  e = editor(v)
  # The sums run as their lines are laid out, so `sums_run` says when they may have changed
  (v.sent !== nothing && v.sent[1] === l && v.sent[2] == sums_run[]) && return v
  sums, shown = script_sums(e)
  if v.sent === nothing || v.sent[1] !== l || v.sent[3] != sums || v.sent[4] != shown
    l.scripts.js["ladder"] = Dict{String,Any}("sums" => sums, "shown" => shown)
    # A script that draws runs as the page's scripts do, so the window gets its own drawing back after it
    Browsers.Live.fire!(l, "sums")
    # The sums under the block run after it's laid out, so another frame gives the page those too
    redraw_in!(v, 0)
  end
  v.sent = (l, sums_run[], sums, shown)
  v
end

# --- an HTML file as its page ---------------------------------------------------------------------
#
# An HTML file has four levels. Over its bits, its bytes in hexadecimal and its
# text is the page that its HTML makes, which Ladder's own engine lays out and
# draws, as a `view` block does. That's its highest level, the ladder, so an
# HTML file opens as its page, and ⌘E shows its text.
#
# The page covers the page's whole space in the window, as it would a
# browser's window, and it's yours to use: the wheel scrolls it, a click
# follows a link or presses a button, its scripts run, and you type in its
# fields. After a click it has the keyboard, so the arrows and Space scroll
# it. When the file changes on the disk, the page shows it afresh.

const HTMLS = (".html", ".htm")

"""
True when the page shows an HTML file at one of its levels: as its page, its
text, its bytes in hexadecimal or its bits. A page of HTML from a web server
counts too: see "a page from a web server".
"""
html_page(b::Buffer) = b.view in FILE_VIEWS && (served_html(b) || lowercase(splitext(b.path)[2]) in HTMLS && isfile(b.path) && text_file(b.path))

"True when the page shows an HTML file as the page that its HTML makes"
html_shown(e) = e.buf.view == :file && html_page(e.buf)

"What shows an HTML file as the page that its HTML makes"
@def mutable struct HTMLPage <: SemanticUI
  path::String = ""
  read::Float64 = 0.0      # when the file had last changed, as the page last read it
  browser::Any = nothing   # the Browser that lays the page out and shows it
end

"The HTMLPage of the HTML file that the page shows. A file that another file takes the window from loses its page, and its scripts end."
html_part(e) = node!(() -> HTMLPage(path=e.buf.path), e, (:html, e.buf.path))

"""
The Browser of `v`, which gets the file and the files that it names, and shows
the page. A page from a web server came already: the Browser gets the files
that it names, and a link of the page goes where Ladder goes, so ⌘⌥← comes back.
"""
html_browser(v::HTMLPage) = begin
  v.browser === nothing || return v.browser
  e = editor(v)
  files = Webfiles.Files(getter=(a...) -> WEB_GETTER[](a...), online=() -> web_online(e))
  isremote(v.path) && return v.browser = own!(v, Browsers.Browser(html=get(SERVED_HTML, v.path, ""), base=v.path, files=files,
                                                                  open=url -> BROWSER[](url), leads=url -> follow_remote!(e, url)))
  v.read = mtime(v.path)
  v.browser = own!(v, Browsers.Browser(address=v.path, files=files, open=url -> BROWSER[](url)))
end

describe(v::HTMLPage) = begin
  e = editor(v)
  b = html_browser(v)
  # A file that changed on the disk shows afresh, as after a browser's reload
  at = isremote(v.path) ? v.read : mtime(v.path)
  at == v.read || (v.read = at; Browsers.reload!(b))
  carry_sums!(v, b)
  b.zoom = round(Float64(e.zoom), digits=2)
  b.wide, b.high = page_room(e)
  Box(width(grow=grow), height(grow=grow), Alignment.Start, name="Web page", b)
end

keyboard_part(v::HTMLPage) = html_browser(v)

# --- a view of another file -------------------------------------------------------------------
#
# A code block in the language `view` shows another file in the document, as
# the file is. Its line names the file:
#
#     ```view
#     plan.pdf
#     ```
#
# The name can be of a file or a folder beside the document, a path like
# ~/Desktop/plan.pdf, or the address of a page of the web. What shows depends
# on the kind of file:
#
#   - An HTML file and a page of the web show the page that their HTML makes,
#     and so does a block whose first line starts with a tag, like `<h1>`,
#     which holds the HTML itself. The page is yours to use where it is: see
#     "a page of the web". Its scripts read the document's sums.
#   - A Markdown page shows as it reads, a little smaller than the document.
#   - A picture, a model, a sound, a video, a PDF file, a CSV file, a zip, a
#     Word file, a font and a file of text show as they do under a path.
#   - A SolidCraft design shows alone, with none of its editor: you turn it,
#     and nothing changes it. The button that goes to the file shows the editor.
#   - A Julia file with a function called `view` shows what that function
#     makes from the document's sums: see "a view of what code makes".
#   - A folder shows the files and the folders in it. A click on one goes to it.
#
# While the mouse is over the block, two buttons show beside its top right
# corner. The first makes what the block shows fill the window, over the
# document: a page, a model, a video, a picture or a PDF file. The window goes
# to no other file, and Esc puts the document back. A view that would show no
# more that way, like a table, has only the second button. That one goes to the
# file: the window shows it, as a click on a link to it does, and ⌘⌥← comes
# back. A click on the block with ⌘ held does the same, and one with ⌥ held
# shows the block's line. An HTML file that you go to keeps the sums that
# the block gave its page, so the page there looks as it did in the document.
#
# A line like `aspect: 16:9` under the name sets the shape of a page, a model
# or a video: its width to its height. The view is as wide as the document's
# text, so it keeps that shape at any width of the window. `aspect: 2` is the
# same as `aspect: 2:1`. With no such line, a page is as tall as what it shows
# and a model is 260 pixels tall.

const VIEW_BLOCK = "view"
push!(BLOCK_ICONS, "eye", "arrow-up-right")

"What a `view` block shows: another file, a folder, or a page of the web"
@def mutable struct ViewBlock <: SemanticUI
  n::Int = 0                               # its place among the page's `view` blocks
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  lines::Any = nothing                     # the lines that it was last read from
  source::Vector{String} = String[]        # those lines without its settings: the name of what it shows, or its HTML
  settings::Vector{String} = String[]      # its lines of settings, like `aspect: 16:9`, as they're written
  aspect::Float64 = 0.0                    # its width over its height, from its line `aspect:`, or 0 when it has none
  lang::String = VIEW_BLOCK                # the language of its block: `view`, or `web` as it was called before
  target::String = ""                      # the path or the address that its line names, as `view_target` gives it
  held::Bool = false                       # its lines hold the HTML of a page, which starts with a tag
  browser::Any = nothing                   # the Browser that shows an HTML file or a page of the web
  crumb::Any = nothing                     # the Breadcrumb that keeps what shows any other file: its model, its player, its text
  parts::Dict{Any,Any} = Dict{Any,Any}()
  sent::Any = nothing                      # the page that was last given the sums, and what it was given: see `send_sums!`
  made::Any = nothing                      # what the function `view` of a Julia file made for it: a Made
end

"A line of settings of a `view` block, like `aspect: 16:9`, or nothing for any other line"
view_setting(line) = match(r"^\s*(aspect)\s*:\s*(.*?)\s*$"i, line)

"""
The lines of a `view` block, `lines`, in two parts: those that name what it
shows, or hold its HTML, and its lines of settings. A line of HTML is no
setting, so the settings of a page that the block holds are above its first tag.
"""
view_parts(lines) = begin
  html = findfirst(l -> startswith(strip(l), '<'), lines)
  upto = html === nothing ? length(lines) : html - 1
  set = [i for i in 1:upto if view_setting(lines[i]) !== nothing]
  (source=String.(lines[setdiff(eachindex(lines), set)]), settings=String.(lines[set]))
end

"""
The width over the height that `text` says, like 16:9, 16/9, 2 or 1.5, or 0
when it says none.
"""
aspect_of(text) = begin
  m = match(r"^(\d+(?:\.\d+)?)\s*(?:[:/x×]\s*(\d+(?:\.\d+)?))?$", strip(text))
  m === nothing && return 0.0
  wide = parse(Float64, m[1])
  high = m[2] === nothing ? 1.0 : parse(Float64, m[2])
  wide > 0 && high > 0 ? wide / high : 0.0
end

"How tall a model or a video of the `view` block `v` is in the document `e`: as its line `aspect:` says, or `MODEL_HEIGHT`"
view_high(v::ViewBlock, e) = v.aspect > 0 ? px(round(num(e.width) / v.aspect)) : MODEL_HEIGHT

"True when `name` is the address of a page of the web, or of anything with a scheme, and not a path on the Mac"
has_scheme(name::AbstractString) = occursin(r"^[a-z][a-z0-9+.-]*:"i, name)

"""
What the lines of a `view` block name: the whole path of a file or a folder,
or the address of a page of the web. A name with no / at its start is beside
the document, and one with ~ at its start is in the home folder. It's "" when
the block names nothing.
"""
view_target(e, lines) = begin
  i = findfirst(l -> !isempty(strip(l)), lines)
  i === nothing && return ""
  name = String(strip(lines[i]))
  has_scheme(name) && return name
  path = abspath(docdir(e), expanduser(name))
  length(path) > 1 ? String(rstrip(path, '/')) : path
end

"What a tooltip calls the file or the page at `target`: its name, or the address of a page of the web"
view_name(target) = has_scheme(target) ? target : basename(target)

"True when the `view` block `v` shows a page that its HTML makes: of an HTML file, of the web, or that its lines hold"
view_web(v::ViewBlock) = v.held || !isempty(v.target) && (has_scheme(v.target) || lowercase(splitext(v.target)[2]) in HTMLS && isfile(v.target))

"""
True when the page of the `view` block `v` gets `ev`, a click, a turn of the
wheel or a pinch. A click with ⌘ or ⌥ held is the block's, and the wheel
scrolls the document unless ⌘ is held, as over a model. A page that fills
the window gets them all.
"""
page_takes(v::ViewBlock, ev) = zoomed_node(editor(v), v.browser) ? true :
                               ev isa MouseScroll ? only_held(ev, Keys.cmd) :
                               ev isa KeyPress ? !(only_held(ev, Keys.cmd) || only_held(ev, Keys.opt)) : true

"The Browser of the `view` block `v`, for an HTML file or a page of the web"
web_browser(v::ViewBlock) = begin
  v.browser === nothing || return v.browser
  e = editor(v)
  files = Webfiles.Files(getter=(a...) -> WEB_GETTER[](a...), online=() -> web_online(e))
  v.browser = own!(v, Browsers.Browser(files=files, open=url -> BROWSER[](url), takes=ev -> page_takes(v, ev)))
end

"The Breadcrumb that keeps what shows the file of `v` when it's no page of HTML: its model, its player, its text"
view_crumb(v::ViewBlock) = v.crumb === nothing ? (v.crumb = own!(v, Breadcrumb())) : v.crumb

reread!(v::ViewBlock, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  e = editor(v)
  v.source, v.settings = view_parts(lines)
  said = filter(!isnothing, view_setting.(v.settings))
  v.aspect = isempty(said) ? 0.0 : aspect_of(last(said)[2])
  src = web_source(e, v.source)
  v.held = !isempty(src.html)
  v.target = v.held ? "" : view_target(e, v.source)
  if view_web(v)
    b = web_browser(v)
    b.address, b.html, b.base = src
  elseif v.browser !== nothing
    # It showed a page before, and its scripts end with it
    v.browser = nothing
    v.sent = nothing
  end
  v
end

describe(v::ViewBlock) = begin
  e = editor(v)
  isempty(v.target) && !v.held &&
    return Column(block_look()..., name="View", block_note("Write the name of a file in this block, like plan.pdf, or the address of a page of the web"))
  v.held || has_scheme(v.target) || ispath(v.target) ||
    return Column(block_look()..., name="View", block_note("$(basename(v.target)) isn't there"))
  with_theme(component_theme(e.zoom)) do
    content = view_content(v, e)
    fills = view_fills(v, e)
    # A page that the block holds is in no file, so it has no button that goes to one: its one button makes it fill the window
    f = v.held ? fillable(v, fills, content, wide=:grow) : fillable(v, (:go, v.target), content, wide=:grow)
    v.held || (f.also = fills)
    Box(width(grow=grow), Alignment.Start, f)
  end
end

"""
What fills the window when you click the first button beside the `view` block
`v`: its page of the web, its model, its video, its picture or its PDF file.
The window shows it over the document, and goes to no other file, so Esc puts
the document back as it was. It's nothing for a view that would show no more
with the window to itself, like a table, a page of Markdown or a folder: the
button that goes to the file shows the whole of those.
"""
view_fills(v::ViewBlock, e) = begin
  view_web(v) && return (:node, web_browser(v))
  if view_made(v)
    m = v.made
    return m isa Made && isempty(m.fault) && m.ready && m.node isa SemanticUI ? fill_what(m.node) : nothing
  end
  l = v.crumb
  l === nothing && return nothing
  # What the file shows under a path has a Fillable of its own, with no button while it's in a view
  for owner in (l, l.viewer)
    f = owner === nothing ? nothing : get(fills(e), objectid(owner), nothing)
    f === nothing || f.what === nothing || return f.what
  end
  nothing
end

"`node`, or the empty room that the page keeps for it while it fills the window"
in_page(e, node) = node isa SemanticUI && zoomed_node(e, node) ? held_room(e) : node

"What shows in the `view` block `v`: the page that an HTML file makes, the list of a folder, or what any other file shows under a path"
view_content(v::ViewBlock, e) = begin
  if view_web(v)
    b = web_browser(v)
    send_sums!(v)
    # While the page fills the window, the window says how big it is
    zoomed_node(e, b) && return held_room(e)
    b.zoom = round(Float64(e.zoom), digits=2)
    b.wide = e.width - 2px
    p = b.view.page
    # Until a page has come, the block is as tall as it's likely to be with one
    b.high = v.aspect > 0 ? px(round(num(b.wide) / v.aspect)) :
             p === nothing || isempty(b.view.html) ? WEB_HIGH * e.zoom : clamp(px(p.tall), WEB_LEAST * e.zoom, WEB_HIGH * e.zoom)
    return Column(block_look()..., clip=true, name="Web page", b)
  end
  view_made(v) && return made_content(v, e)
  l = view_crumb(v)
  path = v.target
  if isdir(path)
    l.at = path
    names = listing(path)
    folders = count(n -> isdir(joinpath(path, n)), names)
    held = filter(!isempty, [how_many(length(names) - folders, "file"), how_many(folders, "folder")])
    about = isempty(held) ? basename(path) : basename(path) * "  ·  " * join(held, " and ")
    return Column(block_look()..., padding(6px), child_gap=1px, name="View", contents(l)...,
                  Box(padding(10px, 6px, 0px, 10px), label(about, 12px, color=colours.dim)))
  end
  # A player that was made for another file stops when the block names another
  l.viewer !== nothing && l.viewer.path != path && (hush!(l); l.viewer = nothing)
  l.at = path
  # What could fill the window is found again in each frame, so that a file of another kind leaves none behind: see `view_fills`
  for owner in (l, l.viewer)
    inner = owner === nothing ? nothing : get(fills(e), objectid(owner), nothing)
    inner === nothing || (inner.what = nothing)
  end
  about = basename(path) * "  ·  Changed " * Libc.strftime("%-d %b %Y, %H:%M", mtime(path))
  content = try
    peek(l, path, lowercase(splitext(path)[2]), words -> (about *= "  ·  " * words))
  catch
    nothing
  end
  content === nothing && (content = label("This file has no preview", 12px, color=colours.dim))
  # A model or a video is as tall as the block's line `aspect:` says, except while it fills the window
  (l.viewer isa STLViewer || l.viewer isa VideoPlayer || l.viewer isa Designs.DesignView) && !zoomed_node(e, l.viewer) && (l.viewer.height = view_high(v, e))
  # A model in a view has no line under it, as it has under a path: the model is all that shows
  l.viewer isa STLViewer && (l.viewer.foot = false; return bare_view(content))
  # A SolidCraft design is the same: the design is all that shows
  l.viewer isa Designs.DesignView && return bare_view(content)
  Column(block_look()..., padding(6px), child_gap=8px, name="View", content, Box(padding(4px, 0px), label(about, 12px, color=colours.dim)))
end

"""
A `view` block that shows only `content`, the viewer of a model. The viewer
has a frame of its own, so the block adds none round it. It names no file
either: the model is all that shows.
"""
bare_view(content) = Column(width(grow=grow), Alignment.Start, name="View", content)

"`n` things of a kind, like 3 files or 1 folder, or nothing when there are none"
how_many(n, thing) = n == 0 ? "" : "$n $thing$(n == 1 ? "" : "s")"

own_button(::ViewBlock) = true

"""
Show the file of the `view` block `v` in the window, as a click on a link to
it does. ⌘⌥← comes back. An HTML file there keeps the sums that the block gave
its page: see `carry_sums!`.
"""
go_view!(v::ViewBlock) = begin
  e = top_editor(editor(v))
  to = v.target
  isempty(to) && return handled
  # A page of Markdown or of HTML on a web server shows in the window, and anything else in your browser
  has_scheme(to) && return (Remote.isaddress(to) && page_online(e) ? get_page!(e, to, else_browser=true) : BROWSER[](to); handled)
  ispath(to) || return handled
  sent = v.sent
  show_path!(e, to)
  if sent !== nothing && e.buf.path == to && html_shown(e)
    e.nodes[(:carried_sums, to)] = (sums=sent[3], shown=sent[4], page=html_part(e), given=nothing)
  end
  handled
end

"""
Give the page of the HTML file of `v` the sums that a `view` block gave it, when
the window went to the file from that block. A page of the file that opens
another way gets none.
"""
carry_sums!(v::HTMLPage, b) = begin
  e = editor(v)
  key = (:carried_sums, v.path)
  c = get(e.nodes, key, nothing)
  c === nothing && return v
  c.page === v || (delete!(e.nodes, key); return v)
  l = Browsers.live(b)
  # The page starts as the browser draws, which doesn't lay the page out again. So it looks again soon.
  (l === nothing || Browsers.loading(b)) && (redraw_in!(v, 0.25); return v)
  c.given === l && return v
  l.scripts.js["ladder"] = Dict{String,Any}("sums" => c.sums, "shown" => c.shown)
  Browsers.Live.fire!(l, "sums")
  e.nodes[key] = merge(c, (given=l,))
  v
end

# When a link goes to another page, the block's line changes to say it. It changes once the view has read the line:
# until then, the line is what the view goes by.
block_tick!(v::ViewBlock) = begin
  b = v.browser
  (b === nothing || v.lines === nothing || !view_web(v)) && return v
  page = Browsers.page_now(b)
  (page === nothing || b.asked != (b.address, b.html, b.base)) && return v
  e = editor(v)
  (readonly(e.buf) || e.buf.fixed || web_says(e, v.source, page)) && return v
  # The block's settings stay. Those of a page that the block holds stay above its HTML.
  said = web_lines(e, page)
  write_block!(v, v.lang, page isa Browsers.Written ? vcat(v.settings, said) : vcat(said, v.settings))
  # The view is at that page already, so it doesn't get it again
  view_web(v) && v.browser === b && Browsers.asked!(b)
  v
end

cursor(v::ViewBlock) = :arrow

# A click with ⌘ held goes to the file. The rest are the page's or the viewer's, or go on to the document, which picks
# the block, or shows its line with ⌥ held.
onkey(v::ViewBlock, ::KeyPress{Keys.mouse_left}) = only_held(v, Keys.cmd) ? go_view!(v) : nothing

# Esc gives the keyboard back to the document, once no field of the page has it. A page that fills the window goes
# back into the document.
onkey(v::ViewBlock, ev::KeyPress{Keys.escape}) = begin
  unmodified(ev) || return nothing
  (v.browser !== nothing && ev.window.focus === v.browser) || return nothing
  e = editor(v)
  zoomed_node(e, v.browser) && return zoom_out!(zooming(e))
  focus(e)
  handled
end

keyboard_part(v::ViewBlock) = view_web(v) ? web_browser(v) : v.crumb !== nothing && v.crumb.viewer isa Pages ? v.crumb.viewer : nothing

"The `view` block as HTML: the page that it holds, in a frame, the picture that it shows, or a link to its file or its page"
view_html(e, v::ViewBlock) = begin
  if v.held
    held = replace(join(v.source, "\n"), '&' => "&amp;", '"' => "&quot;")
    shape = v.aspect > 0 ? "aspect-ratio:$(v.aspect)" : "height:$(round(Int, num(WEB_HIGH)))px"
    return "<iframe srcdoc=\"$held\" style=\"width:100%;$shape;border:1px solid #d8d2c8;border-radius:8px\"></iframe>"
  end
  isempty(v.target) && return nothing
  name = has_scheme(v.target) ? Browsers.whole(v.target) : String(strip(v.source[findfirst(l -> !isempty(strip(l)), v.source)]))
  shown = replace(name, '&' => "&amp;", '<' => "&lt;", '>' => "&gt;", '"' => "&quot;")
  ispicture(v.target) && return "<p><img src=\"$shown\" style=\"max-width:100%\"></p>"
  "<p><a href=\"$shown\">$shown</a></p>"
end

BLOCKS[VIEW_BLOCK] = BlockKind("View", "eye", ViewBlock, view_html)
# A block in the language `web` is a view by the name that it had before. It writes its line back in its own language.
BLOCKS[WEBVIEW] = BlockKind("View", "eye", (; n) -> ViewBlock(n=n, lang=WEBVIEW), view_html)

# --- a view of what code makes ------------------------------------------------------------------
#
# A `view` block can name a Julia file that makes what the block shows:
#
#     ```view
#     satellite.jl
#     ```
#
# The file has a function called `view` that takes one thing: the sums of the
# block's document, as the scripts of a page of the web get them in
# `ladder.sums`. Each sum that gives a name is there under that name, as a
# number in SI units: see `script_value`. Ladder calls the function and shows
# what it makes:
#
#   - The bytes of a .glb file show as a model, in the model viewer.
#   - A node draws itself, and any other value shows as text, as in a `ui` block.
#
# Ladder calls the function again when the sums change, as while a number is
# dragged, and when the file is saved. A model stays turned as it was, and as
# big. The function runs in a thread of its own, as the code of a page does, so
# the window goes on drawing while a slow one runs. What it made last shows
# until it comes back.
#
# A Julia file with no such function shows its code, as any file of text does.

"What the function `view` of a Julia file made for a `view` block, and the run that makes it again"
@def mutable struct Made
  file::String = ""          # the file, by its real path
  saved::Float64 = 0.0       # when the file had last been saved, as the last run found it
  seen::Int = -1             # `sums_run` when the document's sums were last read
  now::Any = nothing         # the sums as they were then
  sums::Any = nothing        # the sums that the function was last called with
  task::Any = nothing        # the run of the function that hasn't come back yet
  ready::Bool = false        # a run has come back
  value::Any = nothing       # what the function made last
  node::Any = nothing        # the node that shows it, like the viewer of a model, or nothing for a value that shows as text
  fault::String = ""         # what went wrong in the last run, or ""
end

"How many seconds a `view` block waits for its file's function, before the window goes on drawing with what the function made last"
const MADE_WAIT = 0.03

"True when the `view` block `v` names a Julia file whose function `view` makes what the block shows"
view_made(v::ViewBlock) = !v.held && endswith(v.target, ".jl") && isfile(v.target) && !foreign(editor(v).buf.path) && defines(v.target, VIEW_BLOCK)

"""
Call the function `view` of the Julia file `file` with `sums`. The file's
code is loaded first, and with `again` it's loaded once more, since the file
was saved. This gives true and what the function made, or false and what went
wrong. It runs in a thread of its own: see `made!`.
"""
made_run(file, sums, again) = try
  m = get(Kip.modules, file, nothing)
  # The file's new code goes into the module that it has
  m === nothing ? (m = Base.invokelatest(Kip.require, file)) : again && Base.include(m, file)
  f = named(m, Symbol(VIEW_BLOCK))
  # Every module has Base's `view`, which is no function of the file
  (f === nothing || f === Base.view) && error("$(basename(file)) has no function called $VIEW_BLOCK")
  (true, Base.invokelatest(f, sums))
catch err
  (false, trouble(err))
end

"Take what the run of `m` made, if the run has come back: a model goes to the viewer of the `view` block `v`, which keeps how it's turned"
finish!(v::ViewBlock, m::Made) = begin
  t = m.task
  (t === nothing || !istaskdone(t)) && return m
  m.task = nothing
  ok, value = try fetch(t) catch err; (false, trouble(err)) end
  m.ready = true
  m.fault = ok ? "" : String(value)
  ok || return m
  m.value = value
  if value isa Vector{UInt8}
    m.node isa STLViewer || (m.node = own!(v, STLViewer(path=m.file, height=MODEL_HEIGHT, foot=false)))
    show!(m.node, value)
  else
    node = Base.invokelatest(present, value)
    m.node = node isa SemanticUI ? own!(v, node) : node
  end
  m
end

"""
What the function `view` of the file of the `view` block `v` made last. The
function runs again when the sums of the document `e` have changed since its
last run, or the file was saved since. It runs in a thread of its own, after
any code of a page that runs now. The window waits `MADE_WAIT` seconds for it,
so a quick function shows what it made in the same frame, and a number that
you drag doesn't run ahead of the model.
"""
made!(v::ViewBlock, e) = begin
  file = realpath(v.target)
  m = v.made isa Made && v.made.file == file ? v.made : (v.made = Made(file=file))
  finish!(v, m)
  # The sums run as their lines are laid out, so `sums_run` says when they may have changed
  m.seen == sums_run[] || (m.seen = sums_run[]; m.now = script_sums(e)[1])
  saved = mtime(file)
  if m.task === nothing && (m.now != m.sums || saved != m.saved)
    again = get(LOADED, file, saved) != saved
    LOADED[file] = saved
    sums, before = m.now, LAST_RUN[]
    m.sums, m.saved = sums, saved
    m.task = LAST_RUN[] = Threads.@spawn begin
      before === nothing || try wait(before) catch end
      made_run(file, sums, again)
    end
    # A test waits for every run, as it does for the code of a page
    until = time() + (isfinite(RUN_WAIT[]) ? MADE_WAIT : Inf)
    while !istaskdone(m.task) && time() < until
      sleep(0.001)
    end
    finish!(v, m)
    # The sums under the block run after it's laid out, so another frame reads those too
    redraw_in!(v, 0)
  end
  m.task === nothing || redraw_in!(v, 0.05)
  m
end

"What the `view` block `v` shows of a Julia file that has a function `view`: what the function made, or what went wrong"
made_content(v::ViewBlock, e) = begin
  m = made!(v, e)
  if isempty(m.fault) && m.ready && m.node isa STLViewer
    zoomed_node(e, m.node) || (m.node.height = view_high(v, e))
    return bare_view(in_page(e, m.node))
  end
  name = basename(v.target)
  about = name * "  ·  Changed " * Libc.strftime("%-d %b %Y, %H:%M", mtime(v.target))
  content = !isempty(m.fault) ? note(m.fault, colours.accent) :
            !m.ready ? Box(padding(4px, 6px), label("Running $name…", 12px, color=colours.dim)) :
            m.node !== nothing ? in_page(e, m.node) :
            note(m.value isa AbstractString ? m.value : Base.invokelatest(repr, "text/plain", m.value), colours.ink)
  Column(block_look()..., padding(6px), child_gap=8px, name="View", content, Box(padding(4px, 0px), label(about, 12px, color=colours.dim)))
end

# --- one thing in many parts of the page -------------------------------------------------------
#
# One thing can show in many parts of a page. A to-do item is a line of the
# text, a card of a board, a bar of a schedule, a thing of a calendar's day
# and the rows of a time log. A row of a table is a bar of a chart. While the
# mouse is on a thing in one part, each other part marks the same thing, so
# you see where it is in all of them.
#
# A thing is known by its name: the words of a to-do item, the task of a row
# of a log, the first cell of a row of a table. No part sends another a
# message. `pointed(part)` is the name of what the mouse is on in a part, and
# `marked(part, name)` is true while the mouse is on a thing of that name
# anywhere in the page. A kind of block joins in with a method of `pointed`,
# and a call of `marked` where it draws a thing.

const MARK_FILL = 0.13   # how strong the accent colour is behind a thing that's marked

"A name as two parts of the page compare it. Capital letters, and the space round it, make no other name."
plain_name(name::AbstractString) = lowercase(strip(name))

"The colour `back` with the accent colour over it, as strong as a mark is: what's behind a thing that's marked"
mark_colour(back) = begin
  a, b = convert(RGBA{Float64}, back), convert(RGBA{Float64}, colours.accent)
  RGBA(a.r + (b.r - a.r) * MARK_FILL, a.g + (b.g - a.g) * MARK_FILL, a.b + (b.b - a.b) * MARK_FILL, 1.0)
end

"The name of the thing that the mouse is on in `part`, or nothing. A kind of block that shows things by name has a method."
pointed(part) = nothing

"What tells a thing of a calendar from the others for the rest of the page: the name of its task or its to-do item, or the words of an event"
thing_name(t::Calendars.Thing) = t.kind == :event ? t.words : t.key

pointed(v::BoardView) = begin
  v.grab === nothing || return nothing
  for card in values(v.parts)
    card isa BoardCard && ishovered(card) && return card.key
  end
  nothing
end

pointed(v::CalendarView) = begin
  v.grab === nothing || return nothing
  for c in values(v.parts)
    c isa CalendarThing && c.thing !== nothing && ishovered(c) && return thing_name(c.thing)
  end
  nothing
end

pointed(v::ScheduleView) = (i = v.grab === nothing ? hot_row(v) : 0; i == 0 ? nothing : v.tasks[i].todo.key)

"The place of the row of a log that the mouse is on, or 0"
hot_stretch(v::TimelogView) = begin
  w = window_of(v)
  (w === nothing || !ishovered(v)) && return 0
  y = w.mouse[2]
  for i in eachindex(v.data.rows)
    c = get(v.parts, (:cell, i, :task), nothing)
    r = c === nothing ? nothing : rect(c)
    r !== nothing && r.top - 2px <= y < r.top + r.height + 2px && return i
  end
  0
end

pointed(v::TimelogView) = begin
  s = Timelogs.stretch(v.data, hot_stretch(v))
  s === nothing || isempty(s.task) ? nothing : s.task
end

pointed(v::ChartView) = begin
  a = get(v.parts, :area, nothing)
  (a === nothing || !ishovered(a) || v.shown === nothing) && return nothing
  m, labels = chart_hit(v), v.shown[2].labels
  m !== nothing && 1 <= m.label <= length(labels) ? labels[m.label] : nothing
end

"Each part of the page that shows: the children of the document, in the order of their lines"
shown_parts(e) = begin
  out = Any[]
  child = getfield(node!(Document, e, :document), :firstchild)
  while child !== nothing
    push!(out, child)
    child = getfield(child, :nextsibling)
  end
  out
end

"The table of the page that the item `it` shows, as `page_tables` gives it, or nothing"
item_table(e, it::Item) = (ts = page_tables(e); k = findfirst(t -> t.first == it.first, ts); k === nothing ? nothing : ts[k])

"The name of row `r` of a table of the page: its first cell that holds something. The row of the columns' names has none."
row_name(table, r::Int) = begin
  (1 <= r <= length(table.rows) && !(r == 1 && table.headed)) || return nothing
  k = findfirst(!isempty, table.rows[r])
  k === nothing ? nothing : table.rows[r][k]
end

"""
The rows of the table or the sheet that the item `it` shows, each with its
name, how far its top is from the top of the item, and how tall it is. A row
with no name is left out.
"""
named_rows(e, it::Item) = begin
  out = Tuple{String,px,px}[]
  g = it.content
  g isa Union{Grid,Sheet} || return out
  table = item_table(e, it)
  (table === nothing || table.ranged) && return out   # the rows of a sheet over a range are its values, and not its own rows
  y = g isa Grid ? TABLE_GAP + g.head : 0px
  for r in eachindex(g.rows)
    top, high = g isa Grid ? (y, g.heights[r] + 1px) : (row_top(g, r), g.heights[r])
    y += high
    name = row_name(table, r)
    name === nothing || push!(out, (name, top, high))
  end
  out
end

"""
The line of the page's text that the mouse is on, and the name of the thing
on it: a to-do item, or a row of a table, of a spreadsheet or of a sheet. It's
nothing when the mouse is on no such line.
"""
pointed_line(e) = begin
  (zooming(e) === nothing && full_block(e) === nothing && e.popup == :none) || return nothing
  win = window_of(e)
  (win === nothing || isempty(e.layout) || held(e, Keys.mouse_left) || !ishovered(node!(Document, e, :document))) && return nothing
  x, y = num(win.mouse[1]), num(win.mouse[2])
  line = todo_line(e, x, y)
  if line !== nothing
    k = findfirst(t -> t.line == line, page_todos(e))
    return k === nothing ? nothing : (line, page_todos(e)[k].key)
  end
  dx, dy = px(x) - e.origin[1], px(y) - e.origin[2]
  (0px <= dx < e.width && y >= num(TOPBAR_H) && dy >= 0px) || return nothing
  it = e.layout[item_under(e, dx, dy)]
  for (r, (name, top, high)) in enumerate(named_rows(e, it))
    it.top + top <= dy < it.top + top + high && return (it.first + r, name)
  end
  nothing
end

"""
Find the thing that the mouse is on, before the page is laid out: in the
page's text, or else in the first part of the page that says so. `pointed(e)`
gives its name until the next frame.
"""
point_tick!(e) = begin
  found = pointed_line(e)
  if found === nothing
    for part in shown_parts(e)
      name = pointed(part)
      name === nothing || (found = (0, name); break)
    end
  end
  e.nodes[:pointed] = found === nothing ? nothing : (found[1], plain_name(found[2]))
  e
end

"The name of the thing that the mouse is on, in any part of the page that shows, or nothing"
pointed(e::Editor) = (p = get(e.nodes, :pointed, nothing); p === nothing ? nothing : p[2])

"True while the mouse is on a thing called `name`, in any part of the page"
marked(e::Editor, name::AbstractString) = (p = pointed(e); p !== nothing && p == plain_name(name))
marked(part, name::AbstractString) = marked(editor(part), name)

"""
Mark the thing that the mouse is on where the page's text has it too: a soft
box behind each to-do item and each row of a table that has its name. The line
that the mouse is on has none. The page's text is at `ui`.
"""
mark_pointed(ctx, e, ui) = begin
  p = get(e.nodes, :pointed, nothing)
  p === nothing && return
  from, name = p
  fill = tint(colours.accent, MARK_FILL)
  todos = nothing
  for it in e.layout[e.shown]
    across, wide = item_room(e, it)
    left, top = num(ui.left + across), num(ui.top + it.top)
    f = it.content
    if shows_box(f) && it.first != from
      todos === nothing && (todos = page_todos(e))
      k = findfirst(t -> t.line == it.first, todos)
      k !== nothing && plain_name(todos[k].key) == name && round_box(ctx, left - 6, top, num(wide) + 12, num(it.tall), 5; fill)
    elseif f isa Union{Grid,Sheet}
      long = f isa Grid ? num(f.left + sum(f.widths, init=0px) + 1px * (length(f.widths) + 1)) : num(wide)
      for (r, (row, y, high)) in enumerate(named_rows(e, it))
        plain_name(row) == name && it.first + r != from && round_box(ctx, left, top + num(y), long, num(high), 0; fill)
      end
    end
  end
end

# --- the day that the page shows ---------------------------------------------------------------
#
# A page shows itself as it stands on one day: today, until the page has a
# code block in the language `day`. day.jl says how that block is written. It
# shows a line of days with a slider on it. Drag the slider, click a day, or
# press ← and →, and the page's day changes while the mouse moves. When the
# mouse lets go, the day goes into the block's line. Today takes the line
# away, so the page follows the real day again.
#
# No part of the page is told. Each part that would ask for today asks
# `page_day(e)`:
#
#   - A schedule draws its line of today on that day. A task that the plan
#     finishes before that day shows as done.
#   - The box of each to-do item that the schedule has a task for shows the
#     same: a tick when the plan has the task finished by then. A past day
#     that git keeps the page for has git's ticks instead.
#   - A board puts each card where the schedule's plan has its task on that
#     day: to do, doing or done. Its cards stay where they are while it does.
#   - A calendar shows the month of that day, with a circle round the day.
#   - A time log adds up the hours to that day, when the day is past. A chart
#     of the log draws those hours.
#   - The text shows what git has of the page for that day, when the day is
#     past and git keeps the page: see "the page's text on its day".
#
# The slider goes from the first to the last day of the things of the page.
# `page_days` finds those: it asks the schedule for its tasks, and reads the
# days of the to-do items, the events and the rows of the logs.

const DAY_BLOCK = Days.DAY
const DAY_TRACK = 50px    # how tall the line of days is
const DAY_PAD = 20.0      # px from each end of that line to the edge of the block
const DAY_KNOB = 7.0      # the radius of the slider
push!(BLOCK_ICONS, "calendar-day")

"What a `day` block shows: a line of days with a slider on it, which sets the day that the page shows"
@def mutable struct DayView <: SemanticUI
  n::Int = 0                               # its place among the page's blocks of this kind
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  day::Union{Nothing,Date} = nothing       # the day that its lines say, or nothing for today
  lines::Vector{String} = String[]         # the lines that `day` was read from
  at::Union{Nothing,Date} = nothing        # the day that the slider is on while the mouse drags it
  grab::Bool = false                       # the mouse holds the slider
  days::Vector{Date} = Date[]              # the days that the line shows
  box::NTuple{4,Float64} = (0.0, 0.0, 0.0, 0.0)   # where the line of days was last drawn in the window
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its buttons and its line of days, kept between frames
end

"The line of days of a `day` block, with the slider on it"
@def mutable struct DayTrack <: SemanticUI
  of::Any = nothing
end

reread!(v::DayView, lines) = begin
  lines == v.lines && return v
  v.lines = lines
  v.day = Days.day(lines)
  v
end

"The lines that open and close the page's first `day` block, or nothing. They're found again when the page has changed."
day_block(e) = (b = e.buf; get!(() -> block_lines(b, DAY_BLOCK, 1), e.flows, (:day_block, b.path, b.version)))

"""
The day that the page shows itself on: today, unless the page has a `day`
block that says another. Each part of the page that shows what's done, what's
running or what's to come asks for this day.
"""
page_day(e) = begin
  today = calendar_today()
  span = day_block(e)
  span === nothing && return today
  v = block_view(e, DAY_BLOCK, 1)
  reread!(v, e.buf.lines[span[1]+1:span[2]-1])
  something(v.at, v.day, today)
end

"True when the page shows a day that isn't today"
another_day(e) = page_day(e) != calendar_today()

"""
How the task `t` of a schedule stands on the page's day: `:done`, `:doing` or
`:todo`. On another day than today, a task that repeats isn't done while its
next run is still to come: it's `:doing` on the days of a run. One with a limit,
like `every day for 3 days`, is done after the last day of its last run.
"""
standing(e, t::Schedules.Planned) = begin
  d, today = page_day(e), calendar_today()
  if d != today && Schedules.repeats(t.todo) !== nothing
    weekends = calendar_tasks(e)[2]
    z = Schedules.last_day(t, weekends)
    z !== nothing && d > z && return Days.stands(t.start, z, t.todo.done, d, today)
    return Schedules.running(t, d, weekends) ? :doing : :todo
  end
  Days.stands(t.start, t.finish, t.todo.done, d, today)
end

"True when the task `t` shows as done: it's ticked, or on another day than today, the plan has it finished by then"
finished(e, t::Schedules.Planned) = another_day(e) ? standing(e, t) == :done : t.todo.done

"The tasks of the page's schedule, when the page shows another day than today. On the real day, and with no schedule, there are none: the page shows what's ticked."
planned_tasks(e) = another_day(e) ? calendar_tasks(e)[1] : Schedules.Planned[]

"A log with only the hours to the page's day, when that day is past. If not, the log itself."
log_to_day(e, log::Timelogs.Log) = (d = page_day(e); d < calendar_today() ? Timelogs.upto(log, d) : log)

"""
The days of the things of the page: the days of its schedule's tasks, of its
to-do items that have a day, of its calendars' events and of the rows of its
time logs. They're found again when the page has changed.
"""
page_days(e) = begin
  b = e.buf
  get!(e.flows, (:page_days, b.path, b.version, calendar_today())) do
    out = Date[]
    foreach(t -> push!(out, t.start, t.finish), calendar_tasks(e)[1])
    for t in page_todos(e)
      d = Calendars.stamp(t.name)
      d === nothing || push!(out, d)
    end
    for (i, k) in enumerate(kinds(b))
      (k.kind == Kind.code && k.lang in (CALENDAR, TIMELOG)) || continue
      d = Days.day((b.lines[i],))
      d === nothing || push!(out, d)
    end
    # The slider goes back to the page's first commit, when git keeps the page: see "the page's text on its day"
    h = !isempty(b.path) && isfile(b.path) ? page_history(page_key(b.path)) : nothing
    h === nothing || push!(out, h.commits[end][2])
    out
  end
end

"Make `d` the page's day, and write it into the block's line. Today takes the line away."
set_day!(v::DayView, d::Date) = begin
  v.at = nothing
  write_block!(v, DAY_BLOCK, Days.written(v.lines, d == calendar_today() ? nothing : d))
  handled
end

act!(v::DayView, action, w) = begin
  e = editor(v)
  action == :today ? set_day!(v, calendar_today()) : set_day!(v, page_day(e) + Day(action == :back ? -1 : 1))
end

"How far across the window the middle of the day at place `i` of the line is"
day_spot(v::DayView, i::Real) = v.box[1] + DAY_PAD + (i - 0.5) * (v.box[3] - 2DAY_PAD) / max(length(v.days), 1)

"The day of the line that's nearest to `x` across the window"
day_near(v::DayView, x::Real) = begin
  n = length(v.days)
  n == 0 && return calendar_today()
  v.days[clamp(floor(Int, (x - v.box[1] - DAY_PAD) / max((v.box[3] - 2DAY_PAD) / n, 1e-6)) + 1, 1, n)]
end

"What happens to a `day` block in each frame, before the page is laid out: the slider follows the mouse that holds it, and its day is written down when the mouse lets go"
block_tick!(v::DayView) = begin
  v.grab || return v
  w = window_of(v)
  w === nothing && return (v.grab = false; v)
  if held(v, Keys.mouse_left)
    v.at = day_near(v, num(w.mouse[1]))
  else
    v.grab = false
    v.at === nothing || set_day!(v, v.at)
  end
  v
end

describe(v::DayView) = begin
  e = editor(v)
  today, d = calendar_today(), page_day(e)
  v.days = collect(Days.span(page_days(e), today, d))
  with_theme(component_theme(e.zoom)) do
    off = readonly(e.buf)
    bar = block_bar(
      block_button!(v, :back, :back, icon="chevron-left", tip="The day before", off=off),
      block_button!(v, :on, :on, icon="chevron-right", tip="The day after", off=off),
      Box(width(6px)),
      Box(label("$(Dates.dayname(d)) $(Schedules.long(d))", 13px, weight="Semibold")),
      Box(width(8px)),
      # The row is as tall as the bar, so that it doesn't cut the tails of its letters off
      Row(width(grow=grow), height(grow=grow), clip=true, Alignment.Center,
          Box(label(d == today ? "Today" : uppercasefirst(Days.away(d, today)) * (isempty(then_words(e)) ? "" : ", and " * then_words(e)), 12px, color=colours.dim)), Box(width(grow=grow))),
      block_button!(v, :today, :today, words="Today", tip="Show the page as it is today", off=off || (d == today && v.day === nothing)))
    Column(block_look()..., clip=true, name="Day", bar, block_part!(() -> DayTrack(of=v), v, :track))
  end
end

describe(::DayTrack) = Box(width(grow=grow), height(DAY_TRACK))

draw(ctx, size, ui::ConcreteRect, t::DayTrack) = begin
  v = t.of
  v.box = (num(ui.left), num(ui.top), num(ui.width), num(ui.height))
  n = length(v.days)
  (v.box[3] > 2DAY_PAD && n > 0) || return
  e = editor(v)
  left, top = v.box[1], v.box[2]
  today, d = calendar_today(), page_day(e)
  step = (v.box[3] - 2DAY_PAD) / n
  line = top + 30
  small = Face(SANS, "", 11px, colours.dim, false)
  with_clip(ctx, ui.left, ui.top, ui.width, ui.height) do
    round_box(ctx, left + DAY_PAD, line - 2, v.box[3] - 2DAY_PAD, 4, 2; fill=RGBA(colours.ink, 0.1))
    # The names of the days go over the line: each Monday, or the first day of each month when the days are narrow
    weekly = 7step >= 50
    for (i, day) in enumerate(v.days)
      x = day_spot(v, i)
      monday, first = Dates.dayofweek(day) == 1, Dates.day(day) == 1
      step >= 7 && trace(ctx, [(x, line - 6), (x, line - 3)], RGBA(colours.ink, monday ? 0.35 : 0.15), 1.0)
      (weekly ? monday : first) || continue
      words = weekly ? "$(Dates.day(day)) $(Dates.monthabbr(day))" : Dates.monthabbr(day)
      write_ink(ctx, words, x - num(measure(small, words)) / 2, top + 16, small)
    end
    # The line is coloured from today to the page's day, and today has its name under it
    a, b = findfirst(==(today), v.days), findfirst(==(d), v.days)
    if a !== nothing
      x = day_spot(v, a)
      b === nothing || a == b || round_box(ctx, min(x, day_spot(v, b)), line - 2, abs(day_spot(v, b) - x), 4, 2; fill=RGBA(colours.accent, 0.45))
      disc(ctx, x, line, 3.5, colours.ink)
      words = "Today"
      write_ink(ctx, words, clamp(x - num(measure(small, words)) / 2, left + 4, left + v.box[3] - num(measure(small, words)) - 4), line + 16, small)
    end
    if b !== nothing
      x = day_spot(v, b)
      disc(ctx, x, line, DAY_KNOB + 2, takeoff_back())
      disc(ctx, x, line, DAY_KNOB, colours.accent)
    end
  end
end

cursor(::DayTrack) = :hand
cursor(::DayView) = :arrow

onkey(t::DayTrack, ev::KeyPress{Keys.mouse_left}) = begin
  v = t.of
  readonly(editor(v).buf) && return handled
  focus(t)
  v.grab = true
  v.at = day_near(v, num(ev.window.mouse[1]))
  handled
end
onkey(t::DayTrack, ev::KeyPress{Keys.left}) = unmodified(ev) ? act!(t.of, :back, nothing) : nothing
onkey(t::DayTrack, ev::KeyPress{Keys.right}) = unmodified(ev) ? act!(t.of, :on, nothing) : nothing
onkey(t::DayTrack, ev::KeyPress{Keys.escape}) = unmodified(ev) ? (focus(editor(t.of)); handled) : nothing
# A click beside a button is the block's, and doesn't move the caret
onkey(::DayView, ::KeyPress{Keys.mouse_left}) = handled
# A drag is the slider's, so the page's text doesn't select
onmouse(v::DayView, ::MouseMove) = v.grab ? handled : nothing

"The block as HTML: the day that the page shows"
day_html(e, v::DayView) = (d = something(v.day, calendar_today()); "<p><strong>$(Dates.dayname(d)) $(Schedules.long(d))</strong></p>")

BLOCKS[DAY_BLOCK] = BlockKind("Day", "calendar-day", DayView, day_html)

# --- the page's text on its day ------------------------------------------------------------------
#
# A page in a folder that git keeps has its past. On a day before today, the
# text shows that past too: Ladder asks git for the page as its last commit
# of that day had it, and compares it with the page as it is now.
#
#   - The box of a to-do item shows a tick only if the item was ticked then.
#     A click on a box does nothing until the page shows today again.
#   - A line that wasn't on the page then, or that read another way, is
#     fainter, with a grey bar beside it. A tick alone is no other way to read.
#   - A board with no schedule to plan from puts each card where its item
#     was then.
#
# The slider of a `day` block goes back to the day of the page's first
# commit. A page that git doesn't keep, and a day with nothing to compare,
# shows as it is.

"How many seconds the commits of a page stay good, before git is asked for them again"
const HISTORY_FRESH = 30.0
"The commits of each page that was asked for, by the page's real path: when git was asked, the top folder of the page's repository, the page's place in it, and the commits, newest first, each as its hash and its day"
const PAGE_HISTORY = Dict{String,Any}()
"The lines of a page in a commit, by the repository's folder, the commit's hash and the page's place. A commit never changes, so they're kept."
const COMMIT_LINES = Dict{Tuple{String,String,String},Vector{String}}()

"The day of the time `t`, in seconds, on this Mac's clock"
day_of(t::Real) = Date(Libc.strftime("%Y-%m-%d", t))

"""
What git has of the page at `path`: the top folder of its repository, its
place in that folder, and its commits, the newest first, each as its hash and
its day. It's nothing for a page that no repository holds, or that has no
commit yet.
"""
page_history(path::AbstractString) = begin
  kept = get(PAGE_HISTORY, path, nothing)
  kept !== nothing && time() - kept.at < HISTORY_FRESH && return kept.found
  found = try
    root = Git.top(path)
    if isempty(root)
      nothing
    else
      rel = relpath(path, realpath(root))
      commits = [(hash, day_of(at)) for (hash, at) in Git.history(root, rel)]
      isempty(commits) ? nothing : (root=root, rel=rel, commits=commits)
    end
  catch
    nothing   # no git on this Mac, or a folder that macOS doesn't let Ladder read
  end
  length(PAGE_HISTORY) > 500 && empty!(PAGE_HISTORY)
  PAGE_HISTORY[path] = (at=time(), found=found)
  found
end

"The lines of the page at `rel` in the commit `hash` of the repository at `root`, or none when the commit hasn't got the page"
commit_lines(root, hash, rel) = begin
  length(COMMIT_LINES) > 200 && empty!(COMMIT_LINES)
  get!(COMMIT_LINES, (root, hash, rel)) do
    text = Git.at_commit(root, hash, rel)
    text === nothing ? String[] : String.(split(chomp(text), '\n'))
  end
end

"The line `text` with the box of a to-do item empty, so that a tick alone doesn't make two lines differ"
unticked(text::AbstractString) = replace(text, r"^(\s*[-*+] \[)[xX](\])" => s"\1 \2")

"""
The page as git has it for the page's day, when that day is before today:

  - `lines`: its lines in the last commit of that day or before it. There
    are none when its first commit came later.
  - `later`: for each line of the page as it is now, true when the line
    wasn't there then, or read another way.
  - `ticks`: for the line of each to-do item of the page now, true when the
    item was ticked then.

It's nothing when the page shows today, and for a page that git doesn't keep.
"""
page_then(e) = begin
  b = e.buf
  (b.view == :markdown && !isempty(b.path)) || return nothing
  d = page_day(e)
  d < calendar_today() || return nothing
  # Each to-do item of the page asks in each frame, so what was found is good for a second without a look at the disk
  kept = get(e.flows, (:page_then_at, b.path, b.version, d), nothing)
  kept !== nothing && time() - kept[1] < 1 && return kept[2]
  found = page_then(e, d)
  e.flows[(:page_then_at, b.path, b.version, d)] = (time(), found)
  found
end

"The page as git has it for the day `d`, as `page_then(e)` gives it for the page's day. It looks at the disk, for whether the page's file is there."
page_then(e, d::Date) = begin
  b = e.buf
  h = isfile(b.path) ? page_history(page_key(b.path)) : nothing
  h === nothing && return nothing
  k = findfirst(c -> c[2] <= d, h.commits)
  hash = k === nothing ? "" : h.commits[k][1]
  get!(e.flows, (:page_then, b.path, b.version, hash)) do
    lines = k === nothing ? String[] : commit_lines(h.root, hash, h.rel)
    later = falses(length(b.lines))
    for (_, new) in changes(unticked.(lines), unticked.(b.lines)), i in new
      later[i] = true
    end
    was = Dict(t.key => t.done for t in Schedules.todos(lines))
    ticks = Dict{Int,Bool}(t.line => get(was, t.key, false) for t in page_todos(e))
    (lines=lines, later=later, ticks=ticks)
  end
end

"""
True or false when the box of the to-do item on line `i` shows how the item
stands on the page's day, ticked or not. On a day before today that git has
the page for, it's git's tick of that day. On any other day than today, it's
the schedule's plan: a task that the plan has finished by then has a tick.
It's nothing when the page shows today, and for an item that neither says
anything about, and so the box shows the line's own tick.
"""
ticked_then(e, i::Int) = begin
  i > 0 || return nothing
  then = page_then(e)
  then === nothing || return get(then.ticks, i, nothing)
  get(planned_ticks(e), i, nothing)
end

"For the line of each to-do item that the page's schedule has a task for, true when the plan has that task finished by the page's day. There are none on the real day, and on a page with no schedule."
planned_ticks(e) = begin
  another_day(e) || return Dict{Int,Bool}()
  b = e.buf
  get!(e.flows, (:planned_ticks, b.path, b.version, page_day(e), calendar_today())) do
    Dict{Int,Bool}(t.todo.line => finished(e, t) for t in planned_tasks(e))
  end
end

"The to-do items of the page as they stand on the page's day: each is done if git has it ticked then. On the real day, and for a page that git doesn't keep, they're the page's own."
todos_then(e) = begin
  then = page_then(e)
  then === nothing && return page_todos(e)
  b = e.buf
  get!(e.flows, (:todos_then, b.path, b.version, objectid(then))) do
    [Schedules.Todo(t.line, t.name, t.key, t.level, get(then.ticks, t.line, false)) for t in page_todos(e)]
  end
end

"How strongly the page's own colour covers a line that wasn't on the page on its day"
const LATER_VEIL = 0.62

"Make each line of text that wasn't on the page on its day fainter, and draw a grey bar in the margin beside it. The text is drawn already."
veil_later(ctx, e, ui) = begin
  then = page_then(e)
  (then === nothing || slideshow(e) !== nothing) && return
  left = ui.left + sideways(e)
  n = length(then.later)
  for it in e.layout[e.shown]
    (it.content isa Flow && it.first <= n && all(i -> then.later[i], it.first:min(it.last, n))) || continue
    isempty(strip(e.buf.lines[it.first])) && it.first == it.last && continue   # an empty line has nothing to make fainter
    rectangle(ctx, ui.left, ui.top + it.top, ui.width, it.tall, background=RGBA(colours.bg, LATER_VEIL), border=0px)
    rectangle(ctx, left - 16px, ui.top + it.top, 3px, it.tall, background=RGBA(colours.ink, 0.22), border=0px)
  end
end

"What a `day` block says of the page's text on a day before today: that it shows as git has it, or that git has none so early. It's \"\" when the text shows as it is."
then_words(e) = begin
  then = page_then(e)
  then === nothing && return ""
  isempty(then.lines) && return "before this page's first commit"
  n = count(i -> then.later[i] && !isempty(strip(e.buf.lines[i])), eachindex(then.later))   # an empty line is no line to read
  n == 0 ? "the text is as it was" : "$n line$(n == 1 ? "" : "s") came later"
end

# --- a number that a drag changes ---------------------------------------------------------------
#
# A sum in a line of text that is one number, like !`l = 16m`, shows what it
# comes to: 16m. So does a row of a sheet that is one number. A drag on that
# value, to the right or to the left, makes the number bigger or smaller. Each
# step of the drag writes the new number into the page's text, so every other
# part that reads it follows while the mouse moves: the rows of the sheet
# under that row, a chart of the sheet, and the sums in a line that use the
# sum's name. ⇧ makes each step ten times as big. A click that doesn't move
# puts the caret where a click puts it anywhere else.
#
# A sum in a line of text keeps what it made, so that it runs once. When a
# sum of the page changes, `inline_tick!` forgets what the sums after it made,
# and they run again from the top down.

const SCRUB_STEP = 5.0         # px that the mouse moves for one step of a number, near where the drag started
const SCRUB_SPEEDUP = 200.0    # px: each this much further from there, the steps come e times as fast

"""
How many steps of a number a drag of `dx` px from where it started makes. Near
the start it's one step for each `SCRUB_STEP` px, so a small change is easy to
make. Further away, the steps come faster and faster: 100px makes 26 steps, and
1000px makes 5,897, which is more than 200 times as many.
"""
scrub_steps(dx) = (k = SCRUB_SPEEDUP / SCRUB_STEP; round(Int, sign(dx) * k * expm1(abs(dx) / SCRUB_SPEEDUP)))

"""
The number at the place `pos` of the window that a drag can change: its line,
and the columns that it runs from and to. It's the number of a sum in a line
of text, under what the sum shows, or the number of a row of a sheet, under
what the row comes to. Nothing when the place has no such number.
"""
scrub_at(e, pos) = begin
  b = e.buf
  (isempty(e.layout) || readonly(b) || b.fixed || b.view != :markdown) && return nothing
  dx, dy = pos[1] - e.origin[1], pos[2] - e.origin[2]
  (dy >= 0px && pos[2] >= TOPBAR_H) || return nothing
  it = e.layout[item_under(e, dx, dy)]
  # Until the next frame, the layout is of the page that showed before, which can have more lines than this one
  it.last <= length(b.lines) || return nothing
  y = dy - it.top
  c = it.content
  if c isa Flow
    (!c.raw && 0px <= y < tall(c)) || return nothing
    chars = collect(b.lines[it.first])
    for seg in c.lines[line_at(c, y)].segs
      (seg.atomic && seg.node === nothing && seg.x <= dx < seg.x + seg.w) || continue
      # The piece stands for the code of !`code`
      (seg.col >= 2 && seg.col + seg.n <= length(chars) && chars[seg.col-1] == '!' && chars[seg.col] == '`') || continue
      at = number_at(String(chars[seg.col+1:seg.col+seg.n]))
      return at === nothing ? nothing : (it.first, seg.col + at[1], seg.col + at[2])
    end
  elseif c isa Sheet
    across, wide = item_room(e, it)
    r = rowunder(c, y)
    res = c.results[r]
    (res.failed || isempty(res.text) || !(row_top(c, r) <= y < row_top(c, r) + c.heights[r])) && return nothing
    # What the row comes to is at the right end of the row
    w = chip_w(Face(SHEET_FONT, SHEET_WEIGHT, c.size, colours.ink, false), res)
    (wide - SHEET_X - w <= dx - across < wide - SHEET_X) || return nothing
    cell = c.cells[r][end]
    at = number_at(rest(head(b.lines[c.rows[r]], cell.hi), cell.lo))
    return at === nothing ? nothing : (c.rows[r], cell.lo + at[1], cell.lo + at[2])
  end
  nothing
end

"""
Draw a line of dashes under each sum in a line of text that a drag can change,
so that it reads as a number to take hold of. The page's text is at `ui`.
"""
underline_scrubs(ctx, e, ui) = begin
  b = e.buf
  (readonly(b) || b.fixed || b.view != :markdown) && return
  for it in e.layout[e.shown]
    f = it.content
    (f isa Flow && !f.raw && occursin(INLINE, b.lines[it.first])) || continue
    chars = collect(b.lines[it.first])
    for vl in f.lines, seg in vl.segs
      (seg.atomic && seg.node === nothing && seg.col >= 2 && seg.col + seg.n <= length(chars) && chars[seg.col-1] == '!' && chars[seg.col] == '`') || continue
      number_at(String(chars[seg.col+1:seg.col+seg.n])) === nothing && continue
      y = num(ui.top + it.top + f.above + vl.top + vl.high / 2) + num(f.size) * 0.62
      trace(ctx, [(num(ui.left + seg.x), y), (num(ui.left + seg.x + seg.w), y)], tint(colours.accent, 0.75), 1.0, dashed=true)
    end
  end
end

"""
The words that a click with ⌘ at the point `pos` acts on, as the line and the
columns where they start and end: a link, or a name of Julia code that has a
place where it's defined. It's nothing where a click with ⌘ does neither.
`cursor(::Document)` and `press!` find the same.
"""
cmd_words(e, pos) = begin
  line, col = locate(e, pos)
  it = item(e, line)
  it.content isa Flow || return nothing
  segs = [seg for vl in it.content.lines for seg in vl.segs]
  k = findfirst(s -> s.col <= col < s.col + s.n && !isempty(s.link), segs)
  if k !== nothing
    # A link's words can be in several runs of text, as where part of them is bold
    a = z = k
    while a > 1 && segs[a-1].link == segs[k].link; a -= 1 end
    while z < length(segs) && segs[z+1].link == segs[k].link; z += 1 end
    return (line, segs[a].col, segs[z].col + segs[z].n)
  end
  found = name_at(e.buf, (line, col))
  (found === nothing || Base.invokelatest(definition, e, (line, col)) === nothing) && return nothing
  (line, found.col, found.col + length(found.name))
end

"""
While ⌘ is held by itself, mark the words under the mouse that a click would
act on: a soft box behind them and a line under them, as the mouse is a hand
there. The page's text is at `ui`.
"""
mark_clickable(ctx, e, ui) = begin
  w = window_of(e)
  if !(w !== nothing && only_held(w, Keys.cmd) && e.popup == :none && e.buf.view != :file && slideshow(e) === nothing)
    # The card of a name goes when ⌘ comes up
    w === nothing || pop!(e.nodes, :peek, nothing) === nothing || hide_tooltip!(w)
    delete!(e.nodes, :cmd_mouse)
    return
  end
  redraw_in!(e, 1/30)   # the mark follows the mouse, and goes when ⌘ comes up
  found = cmd_words(e, w.mouse)
  peek!(e, w, found)
  found === nothing && return
  line, lo, hi = found
  it = item(e, line)
  f = it.content::Flow
  k1, x1 = spot(f, lo)
  k2, x2 = spot(f, hi)
  # Words that wrap onto a second line are marked on each line that they're on
  for k in k1:k2
    vl = f.lines[k]
    isempty(vl.segs) && continue
    left = k == k1 ? x1 : first(vl.segs).x
    right = k == k2 ? x2 : last(vl.segs).x + last(vl.segs).w
    right > left || continue
    top = ui.top + it.top + line_top(f, k)
    round_box(ctx, num(ui.left + left) - 1, num(top), num(right - left) + 2, num(vl.high), 3; fill=tint(colours.accent, MARK_FILL))
    y = num(top + vl.high / 2) + num(f.size) * 0.62
    trace(ctx, [(num(ui.left + left), y), (num(ui.left + right), y)], colours.accent, 1.0)
  end
end

# --- a card of what a name is ---
#
# While ⌘ is held, a name that has a place where it's defined is marked. When
# the mouse rests on it for a moment, a card under it shows that place: the
# name's documentation and the first lines of its code, from the page or from
# another file. A link's card has where it goes. The card goes when the mouse
# moves, and comes again when the mouse rests.
#
# No card shows until the mouse moves after ⌘ goes down. ⌘ is often pressed
# for a key like ⌘S, and what is under a mouse that didn't move is chance.

const PEEK_WAIT = 0.6   # seconds that the mouse rests on a name before its card shows
const PEEK_LINES = 8    # the most lines of code that a card shows

"""
The lines of `lines` that a card shows for the definition on line `at`: its
documentation above it, and the lines of its code, as many as `most`, up to
the line `last`.
"""
peek_lines(lines, at::Int, last::Int, most=PEEK_LINES) = begin
  from = peek_from(lines, at)
  stop = min(last, at + most - 1)
  while stop > at && isempty(strip(lines[stop])); stop -= 1 end
  [length(l) > 100 ? first(l, 99) * "…" : l for l in lines[from:stop]]
end

"The first line that a card shows for the definition on line `at` of `lines`: the first of the documentation above it that shows"
peek_from(lines, at::Int) = begin
  from = at
  above = at > 1 ? strip(lines[at-1]) : ""
  if startswith(above, '"') && endswith(above, '"')
    # One line of documentation, like "Words" or """Words"""
    from = at - 1
    # Documentation of several lines ends with three quotes, and starts on the line that starts with three quotes
    if endswith(above, "\"\"\"") && !(startswith(above, "\"\"\"") && length(above) >= 6)
      from = something(findprev(l -> startswith(strip(l), "\"\"\""), lines, at - 2), at - 1)
    end
  elseif endswith(above, "\"\"\"")
    from = something(findprev(l -> startswith(strip(l), "\"\"\""), lines, at - 2), at)
  end
  max(from, at - 6)   # long documentation shows its last lines, next to the code
end

"""
What the card of the words `found`, which `cmd_words` gave, shows: where a
link goes, or where a name is defined, with the lines there. It's nothing
when there's nothing to show.
"""
peek_card(e, found) = begin
  line, lo, hi = found
  b = e.buf
  it = item(e, line)
  segs = it.content isa Flow ? [s for vl in it.content.lines for s in vl.segs] : []
  k = findfirst(s -> s.col <= lo < s.col + s.n && !isempty(s.link), segs)
  # Each line has a set height: a Text alone in a box can be less tall than its line, and the lines then overlap
  said(text; family=SANS, color=TIP_INK) = Box(height(17px), Text(text, size=12px, family=family, color=color, wrap=WrapMode.none))
  faint = RGBA(TIP_INK.r, TIP_INK.g, TIP_INK.b, 0.65)
  if k !== nothing
    # A link to a page shows the start of the page, unless the setting is off. Any other link says where it goes.
    page = e.peeks ? linked_page(e, segs[k].link) : nothing
    card = page === nothing ? nothing : page_peek(e, page...)
    return something(card, Box(padding(10px, 7px), said(segs[k].link)))
  end
  place = Base.invokelatest(definition, e, (line, lo))
  place === nothing && return nothing
  # `open` says if the first line that shows is inside a docstring, when long documentation shows only its last lines
  head, lines, lang, open = if place isa Method
    spot = code_place(place)
    spot === nothing && return nothing
    file, at = spot
    _, all, starts = file_parts(file)
    at = settled_line(place, all, at)
    j = max(1, searchsortedlast(starts, at))
    last = j == length(starts) ? length(all) : starts[j+1] - 1
    open = foldl((q, l) -> left_open(l, "julia", q), view(all, 1:peek_from(all, at)-1), init='\0')
    ("$(basename(file)):$at", peek_lines(all, at, last), "julia", open)
  else
    at = place[1]
    # A name of a function, like a variable in it, is one line. A name of the whole page shows its code.
    local_name = any(m -> m.at == place && m.span !== nothing, page_bounds(e))
    j = local_name ? nothing : findfirst(c -> c.first <= at <= c.last, code_blocks(e))
    last = local_name ? at : j === nothing ? at + PEEK_LINES - 1 : code_blocks(e)[j].last
    l = kinds(b)[at]
    ("line $at", peek_lines(b.lines, at, min(last, length(b.lines))), l.kind == Kind.code ? shared_lang(l.lang) : "julia",
     string_opens(b)[peek_from(b.lines, at)])
  end
  # The code has the colours that it has in the page
  Box(padding(10px, 8px), Column(Alignment.Start, child_gap=1px, said(head, color=faint), tip_code(lines, lang; open)...))
end

"""
Show the card of the words `found` when the mouse has rested on them for a
moment while ⌘ is held, and take it away when the mouse is on other words.
The mouse must move after ⌘ goes down before a card shows.
"""
peek!(e, w, found) = begin
  # Where the mouse was when ⌘ went down, or :moved once it has moved from there
  still = get!(e.nodes, :cmd_mouse, w.mouse)
  still === :moved || w.mouse == still || (e.nodes[:cmd_mouse] = still = :moved)
  was = get(e.nodes, :peek, nothing)
  if found === nothing || was === nothing || was.words != found
    was === nothing || !was.shown || hide_tooltip!(w)
    found === nothing ? delete!(e.nodes, :peek) : (e.nodes[:peek] = (words=found, since=time(), shown=false))
    return
  end
  # A mouse move took the card away. It comes again when the mouse rests.
  if was.shown
    any(p -> p.key == :tooltip, popups(w)) || (e.nodes[:peek] = (words=found, since=time(), shown=false))
    return
  end
  # The moment of rest starts when the mouse first moves
  still === :moved || (e.nodes[:peek] = (words=found, since=time(), shown=false); return)
  time() - was.since < PEEK_WAIT && return
  card = peek_card(e, found)
  e.nodes[:peek] = (words=found, since=was.since, shown=true)
  card === nothing && return
  line, lo, hi = found
  it = item(e, line)
  f = it.content::Flow
  k, x = spot(f, lo)
  _, x2 = spot(f, hi)
  top = e.origin[2] + it.top + line_top(f, k)
  # The start of a page is a card of the page's own colours, and not a dark box. It goes as a tooltip does, when the mouse moves.
  card isa PagePeek && return popup!(w, card.layout, anchor=(e.origin[1] + x, top, max(x2 - x, 4px), f.lines[k].high),
                                     placement=:below, gap=4px, key=:tooltip, input=false)
  show_tooltip!(w, card, e.origin[1] + x, top, max(x2 - x, 4px), f.lines[k].high; placement=:bottom, gap=4px)
end

# --- the start of a page in a link's card ---
#
# While ⌘ is held, the card of a link to a page shows the start of that page,
# as the page reads, so you can read it without leaving your own page. A link
# to a heading, like [[Ideas#Plans]], shows the page from that heading to the
# next heading that's as big. A page that's open shows as it is now, with what
# isn't saved yet. The setting "Show a page when I hold ⌘ over its link" turns
# this off, and the card then says where the link goes, as for any other link.

const PEEK_PAGE_W = 440px      # how wide the card of a page is
const PEEK_PAGE_HIGH = 280px   # the most of the page that shows. A longer page is cut there.

"The start of a page, for the card of a link to it: what shows, kept apart from other cards so that it isn't put in a dark box"
struct PagePeek
  layout::Any
  flows::Vector{Flow}   # the lines of the page that it shows, laid out
end

"""
The page that the link `url` goes to, and the heading of the page that it
names, or "" for none. It's nothing for a link that doesn't go to a Markdown
page that's there: a web address, a footnote, a file of another kind, or a
wiki link to a page that isn't made yet.
"""
linked_page(e, url::AbstractString) = begin
  startswith(url, '^') && return nothing   # a footnote
  isremote(e.buf.path) && return nothing   # a page from a web server links to no page of the Mac
  target = wikitarget(url)
  name, heading = if target !== nothing
    occursin('#', target) ? String.(split(target, '#', limit=2)) : (String(target), "")
  else
    # An address with a scheme, like https: or mailto:, isn't a file
    occursin(r"^[a-z][a-z0-9+.-]+:"i, url) && return nothing
    file, mark = occursin('#', url) ? String.(split(url, '#', limit=2)) : (String(url), "")
    (unescaped(file), unescaped(mark))
  end
  name = String(strip(name))
  path = isempty(name) ? e.buf.path : target !== nothing ? wiki_path(e, name) : abspath(docdir(e), expanduser(name))
  (ismarkdown(path) && (isfile(path) || path == e.buf.path && !isempty(e.buf.lines))) || return nothing
  (path, String(strip(heading)))
end

"""
The lines of the page at `path`, their kinds, and the lines of them that the
card of a link shows: from the heading `heading` to the next heading that's as
big, or from the top, after the page's front matter. A page that's open gives
its lines as they are now. It's nothing when the file can't be read as text.
"""
peek_page_lines(e, path, heading) = begin
  b = path == e.buf.path ? e.buf : get(e.buffers, path, nothing)
  lines = if b !== nothing
    b.lines
  else
    found = reading(path, tidy=false)
    found === nothing && return nothing
    found[1]
  end
  isempty(lines) && return nothing
  ks = classify(lines)
  from, to = front_matter(lines) + 1, length(lines)
  if !isempty(heading)
    slug = heading_slug(heading)
    i = findfirst(i -> ks[i].kind == Kind.heading && heading_slug(rest(lines[i], ks[i].prefix)) == slug, eachindex(ks))
    if i !== nothing
      from = i
      next = findnext(j -> ks[j].kind == Kind.heading && ks[j].level <= ks[i].level, eachindex(ks), i + 1)
      next === nothing || (to = next - 1)
    end
  end
  while from < to && isempty(strip(lines[from])); from += 1 end
  while to > from && isempty(strip(lines[to])); to -= 1 end
  (lines, ks, from:to)
end

"""
The card of a link to the page at `path`: the page's name, with the heading
`heading` after it, over the start of the page as it reads, a little smaller
than the page's own text. Only as many lines are laid out as the card shows.
It's nothing when the page has nothing to show.
"""
page_peek(e, path, heading) = begin
  found = peek_page_lines(e, path, heading)
  found === nothing && return nothing
  lines, ks, shown = found
  wide = PEEK_PAGE_W - 2 * 6px - 2 * 14px   # the card has 6px of room on each side, and the page 14px inside that
  zoom = e.zoom
  e.zoom = zoom * PAGE_ZOOM
  flows = Flow[]
  # -1 says that the line isn't one of the document's, so its inline code isn't run
  try
    total = 0px
    for i in shown
      push!(flows, laid(e, lines[i], ks[i], false, -1, wide))
      total += tall(flows[end])
      total > PEEK_PAGE_HIGH && break
    end
  finally
    e.zoom = zoom
  end
  isempty(flows) && return nothing
  total = sum(tall, flows)
  name = splitext(basename(path))[1]
  title = isempty(heading) ? name : "$name  ›  $heading"
  PagePeek(Column(fixed(PEEK_PAGE_W), Alignment.Start, padding(6px), radius(8px), background(colours.block),
                  border(1px, :solid, colours.line), lifted, child_gap=4px,
    Row(width(grow=grow), height(22px), padding(8px, 0px), child_gap=6px, clip=true,
      Icon("file-earmark-text", size=12px, color=colours.dim), label(title, 12px, color=colours.dim)),
    Box(width(grow=grow), height(min(total, PEEK_PAGE_HIGH) + 2TEXT_PAD), padding(14px, 0px), radius(5px), background(colours.bg), clip=true,
      Column(width(grow=grow), Alignment.Start, spacer(TEXT_PAD),
        [describe(e, Item(0, 0, 0px, tall(f), f), f) for f in flows]...))), flows)
end

"Turn on or off whether the card of a link to a page shows the start of the page, while ⌘ is held"
peeks!(e, on::Bool) = (e.peeks = on; save_settings!(e); rerun!(e, :peeks); e)

"Make the agent called `name` the one that Ladder starts for a change or a question: see \"the agents that Ladder can start\""
preferred_agent!(e, name::String) = begin
  any(k -> k.name == name, AGENT_KINDS) || error("Ladder can't start an agent called $name.")
  e.ai = name
  save_settings!(e)
  rerun!(e, :ai)
  redraw_windows!()   # the logo on the line round a thing shows the new agent
  e
end

"Take hold of the number at `found`, which `scrub_at` gave, with the mouse at `pos`"
scrub!(e, found, pos) = begin
  i, lo, hi = found
  b = e.buf
  e.nodes[:scrub] = (line=i, lo=lo, hi=hi, x=num(pos[1]), text=rest(head(b.lines[i], hi), lo), steps=0, moved=false)
  b.typed = 0.0   # the drag is taken back by itself, and not with what was typed before it
  e.popup = :none
  e.clicked = (time(), (i, 0), 0)
  took(e) || focus(e)
  e
end

"Give the number that the mouse holds the value for where the mouse is now, and write it into its line. The caret stays with its text."
scrub_to!(e, pos) = begin
  s = e.nodes[:scrub]
  b = e.buf
  steps = scrub_steps(num(pos[1]) - s.x) * (only_held(e, Keys.shft) ? 10 : 1)
  (steps == s.steps || !(1 <= s.line <= length(b.lines))) && return e
  new = nudged(s.text, steps)
  caret, anchor = b.caret, b.anchor
  edit!(b, (s.line, s.lo), (s.line, s.hi), new, typing=true)
  by = length(new) - (s.hi - s.lo)
  kept(p) = p[1] == s.line && p[2] >= s.hi ? (p[1], p[2] + by) : p
  b.caret, b.anchor = kept(caret), kept(anchor)
  e.nodes[:scrub] = (; s..., hi=s.lo + length(new), steps, moved=true)
  e
end

"What happens in each frame to a number that the mouse holds: when the mouse lets go, the drag ends. A press that never moved was a click, and puts the caret there."
scrub_tick!(e) = begin
  s = get(e.nodes, :scrub, nothing)
  (s === nothing || held(e, Keys.mouse_left)) && return e
  delete!(e.nodes, :scrub)
  b = e.buf
  b.typed = 0.0
  w = window_of(e)
  if !s.moved && w !== nothing
    b.caret = b.anchor = settle(b, locate(e, w.mouse))
    touch!(e)
  end
  e
end

"The code of each sum in a line of text of the page, in the order of the page"
inline_codes(e, b::Buffer) = get!(e.flows, (:inline_codes, b.path, b.version)) do
  String[m[1] for i in inline_lines(e, b) for m in eachmatch(r"!`([^`]+)`", b.lines[i])]
end

"""
Run again the sums in a line of text that come after a sum that changed, so
that a sum which uses a name follows the sum that gives the name its value.
What a sum made is forgotten, and the sum runs when its line is next laid
out. A sum that made a node, like a switch, keeps its node, so the switch
stays on. A node made from names that the page's sums and sheets give, like
!`ProgressBar(value=done / jobs)`, is made again, so it follows the numbers.
`also` is what else the sums read, as `inline_given!` gives it: when that
changes, every sum runs again.
"""
inline_tick!(e) = begin
  b = e.buf
  b.view == :markdown || return e
  key = (:inline_seen, b.path)
  seen = get(e.nodes, key, nothing)
  seen !== nothing && seen[1] == b.version && return e
  codes = inline_codes(e, b)
  also = inline_given!(e)
  e.nodes[key] = (b.version, codes, also)
  seen === nothing && return e
  also == seen[3] || (CODE_RUNS[] += 1)   # a row of a sheet has a new value, so the page's `check` blocks run again
  (codes == seen[2] && also == seen[3]) && return e
  from = also == seen[3] ? something(findfirst(i -> i > length(seen[2]) || seen[2][i] != codes[i], eachindex(codes)), length(codes) + 1) : 1
  counts = Dict{String,Int}()
  # The names that the page's sums and sheets give
  names = Set{Symbol}(Iterators.flatten((filter(!isnothing, sum_name.(codes)), (Symbol(ident(name)) for (name, _) in page_given(e)))))
  for (i, code) in enumerate(codes)
    n = counts[code] = get(counts, code, 0) + 1
    i >= from || continue
    was = get(e.nodes, (:inline, b.path, code, n), nothing)
    (was isa Tuple || (was isa Shown && follows(code, names))) && delete!(e.nodes, (:inline, b.path, code, n))
  end
  # A sum that the page no longer has is forgotten too, so that it runs if it comes back
  for k in collect(keys(e.nodes))
    (k isa Tuple && length(k) == 4 && k[1] == :inline && k[2] == b.path && e.nodes[k] isa Tuple) || continue
    get(counts, k[3], 0) < k[4] && delete!(e.nodes, k)
  end
  e
end

# --- the places that a map has from the rest of its page ------------------------------------------
#
# A map shows more than its own place. Each address of a contact of the
# page has a pin on the map too, in another colour, and so has the address
# in the page's front matter. The mouse over such a pin says whose it is, and
# a click goes to its line of the page. A map with no place of its own shows
# all of those places, and is as close as shows them all.
#
# The map asks: `block_places(lang, lines)` says which places a block of one
# kind gives, and `page_places` gathers them. A kind of block that has a place
# joins in with a line there. While the mouse is on a contact's card, its pin
# is marked, and the other way round: see "one thing in many parts of the page".

const OTHER_PIN = (colorant"#2a78d6", colorant"#1d5fb0")   # what fills the pin of a place from the page, and the line round it
const PIN_REACH = 14.0   # px from the middle of a pin's head that the mouse is still on the pin

"""
The places that a block in the language `lang` gives the maps of its page:
each with the name of whose place it is, the place as the block has it, and
the line of the block that it's on. `lines` are the lines of the block. A
block of contacts gives the address of each contact that has one.
"""
block_places(lang, lines) = begin
  out = @NamedTuple{name::String, place::String, line::Int}[]
  lang == CONTACT || return out
  at = 0
  for c in Contacts.contacts(lines)
    at += c.before
    k = Contacts.place(c, :address)
    k === nothing || push!(out, (name=Contacts.title(c), place=c.lines[k].value, line=at + k))
    at += length(c.lines)
  end
  out
end

"""
Every place that the page gives its maps, with the line of the page that
each is on: the address in the page's front matter, and what each block
gives. They're found again when the page has changed.
"""
page_places(e) = begin
  b = e.buf
  get!(e.flows, (:places, b.path, b.version)) do
    out = @NamedTuple{name::String, place::String, line::Int}[]
    matter = 2:front_matter(b.lines)-1
    # The place is called what the front matter calls the page, or else what the page's file is called
    title = something((match(r"^title\s*:\s*(\S.*?)\s*$"i, b.lines[i]) for i in matter)..., Some(nothing))
    called = title === nothing ? splitext(basename(b.path))[1] : String(strip(title[1], ['"', '\'']))
    for i in matter
      m = match(r"^(?:address|place|site)\s*:\s*(\S.*?)\s*$"i, b.lines[i])
      m === nothing || push!(out, (name=called, place=String(strip(m[1], ['"', '\''])), line=i))
    end
    ks = kinds(b)
    for (i, k) in enumerate(ks)
      (k.kind == Kind.fence && k.level == 0 && k.lang == CONTACT) || continue
      t = codeblock(b, i)[2]
      (t > i && ks[t].kind == Kind.fence && ks[t].level == 1) || continue
      append!(out, ((name=p.name, place=p.place, line=i + p.line) for p in block_places(k.lang, b.lines[i+1:t-1])))
    end
    out
  end
end

"""
The places from the rest of the page that the map `v` can show: each with its
name, its line of the page, and its latitude and longitude. A place is one of
them once Apple's maps have said where it is. With `runs`, the program that
asks them starts for a place that isn't kept yet. The map's own place isn't
one of them.
"""
map_others(v::MapView, runs::Bool=false) = begin
  e = editor(v)
  kept = get(e.flows, (:map_others, objectid(v)), nothing)
  kept !== nothing && kept[1] == (e.buf.version, map_place(v)) && kept[2] && return kept[3]
  out = @NamedTuple{name::String, place::String, line::Int, at::Maps.LatLon}[]
  whole = true
  for p in page_places(e)
    lowercase(Maps.query(p.place)) == map_place(v) && continue
    at = Maps.coordinates(p.place)
    if at === nothing
      found = Maps.found!(media_dir(), p.place; start=runs)
      facts = found.state == :there ? Maps.facts(found.file) : nothing
      if facts === nothing
        # The window looks again when the program may have finished
        found.state in (:coming, :none) && (whole = false; isfinite(found.wait) && redraw_in!(v, max(found.wait, 0.05)))
        continue
      end
      at = (facts.lat, facts.lon)
    end
    push!(out, (name=p.name, place=p.place, line=p.line, at=at))
  end
  e.flows[(:map_others, objectid(v))] = ((e.buf.version, map_place(v)), whole, out)
  out
end

"The middle and the zoom of a map with no place of its own, which shows the places from the rest of its page. It's nothing when the map has a place, or the page gives none that's known."
map_around(v::MapView) = begin
  isempty(v.data.place) || return nothing
  ats = [o.at for o in map_others(v)]
  isempty(ats) ? nothing : Maps.around(ats, v.data.zoom, map_wide(v), Maps.TALL)
end

"The point of the map that shows now where the place `o` from the page is, in px from the map's top left corner, or nothing when it isn't in the map"
other_point(v::MapView, o) = begin
  middle = map_middle(v)
  middle === nothing && return nothing
  _, _, w, h = v.box
  at = Maps.point(o.at, middle, map_zoom(v), w, h)
  0 <= at[1] <= w && 0 <= at[2] <= h ? at : nothing
end

"The place from the page whose pin the mouse is on, or nothing"
other_at(v::MapView) = begin
  w = window_of(v)
  a = get(v.parts, :area, nothing)
  (w === nothing || a === nothing || !ishovered(a) || v.grab !== nothing || !map_shows(v)) && return nothing
  x, y = num(w.mouse[1]) - v.box[1], num(w.mouse[2]) - v.box[2]
  for o in map_others(v)
    at = other_point(v, o)
    # The head of a pin is over its point
    at !== nothing && hypot(x - at[1], y - (at[2] - 26)) <= PIN_REACH && return o
  end
  nothing
end

pointed(v::MapView) = (o = other_at(v); o === nothing ? nothing : o.name)

pointed(v::ContactView) = begin
  # A to-do item under a contact's details is the item, and not the contact
  for r in values(v.parts)
    r isa ContactWork && ishovered(r) || continue
    m = work_of(r)
    return m === nothing ? nothing : m.text
  end
  for card in values(v.parts)
    card isa ContactCard && ishovered(card) || continue
    c = contact_of(v, card.k)
    return c === nothing || isempty(Contacts.title(c)) ? nothing : Contacts.title(c)
  end
  nothing
end

# --- the work that names a contact --------------------------------------------------------------
#
# Under the details of a contact, its card lists the to-do items that name
# the contact and aren't ticked yet: the items of this page, and of every
# page of this page's folder and of the folders in it. A person is named by
# the whole name, or by the first name alone. A click on an item goes to its
# line, in its own page. The mouse on an item marks it in the other parts of
# the page that show it: see "one thing in many parts of the page".
#
# The card reads the pages as a `find` block does, with `folder_pages` and
# `page_text`, so a page is read again only when it changes. A page that
# can't be changed, like an email, lists none.

const WORK_ROWS = 4   # the most items that a card lists. Under them, a line says how many more there are.
push!(BLOCK_ICONS, "square")

"A row under the details of a contact: a to-do item that names the contact"
@def mutable struct ContactWork <: SemanticUI
  of::Any = nothing
  k::Int = 0        # the contact
  i::Int = 0        # the item's place among the contact's items
  room::px = 0px    # how wide the row is
end

"The words that name the contact `c` in a line of text: its whole name, and for a person the first name too, when it has three letters or more"
contact_names(c::Contacts.Contact) = begin
  title = String(strip(Contacts.title(c)))
  isempty(title) && return String[]
  first_name = String(first(split(title)))
  !Contacts.iscompany(c) && first_name != title && length(first_name) >= 3 ? [title, first_name] : [title]
end

"True when `text` has one of `names` in it as whole words. Capital letters make no difference."
names_one(text::AbstractString, names) = begin
  low = lowercase(text)
  any(names) do name
    n = lowercase(name)
    at = findfirst(n, low)
    while at !== nothing
      before = first(at) == firstindex(low) ? ' ' : low[prevind(low, first(at))]
      after = last(at) == lastindex(low) ? ' ' : low[nextind(low, last(at))]
      (isletter(before) || isdigit(before) || isletter(after) || isdigit(after)) || return true
      at = findnext(n, low, nextind(low, first(at)))
    end
    false
  end
end

"""
The to-do items that name contact `k` of the block and aren't ticked, in
every page of this page's folder and of the folders in it. They're found
again when a page changes in Ladder, and when the folder is read again.
"""
contact_work(v::ContactView, k::Int) = begin
  e = editor(v)
  names = contact_names(contact_of(v, k))
  folder = docdir(e)
  (isempty(names) || locked(v) || !isdir(folder)) && return Searches.Match[]
  listed = folder_pages(folder)
  key = (names, hash([b.version for b in values(e.buffers)]), listed.read)
  kept = get(e.flows, (:contact_work, objectid(v), k), nothing)
  kept !== nothing && kept[1] == key && return kept[2]
  pages = get!(() -> Dict{String,Any}(), e.flows, :contact_todos)   # the open items of each page, for every card of the window
  every = Searches.Query(:todo, String[], "", String[])
  out = Searches.Match[]
  for (path, at) in listed.pages
    lines, ks, mark = page_text(e, path, at)
    had = get(pages, path, nothing)
    items = had !== nothing && had[1] == mark ? had[2] : (pages[path] = (mark, Searches.matches(every, path, lines, ks)))[2]
    append!(out, (m for m in items if m.kind == :todo && names_one(m.text, names)))
  end
  e.flows[(:contact_work, objectid(v), k)] = (key, out)
  out
end

"The to-do item that the row `r` shows, or nothing when the contact has it no more"
work_of(r::ContactWork) = (found = contact_work(r.of, r.k); r.i in eachindex(found) ? found[r.i] : nothing)

describe(r::ContactWork) = begin
  v = r.of
  e = editor(v)
  z = e.zoom
  m = work_of(r)
  m === nothing && return Box(height(0px))
  # An item of another page says which page it's in
  page = m.path == e.buf.path ? "" : splitext(relpath(m.path, docdir(e)))[1]
  grey = Face(SANS, "", 11.5px * z, colours.faint, false)
  tail = isempty(page) ? 0px : min(measure(grey, page), r.room * 0.4) + 8px * z
  Row(fixed(r.room), height(CONTACT_LINE * z), child_gap=7px * z, Alignment.Center, radius(4px), clip=true, name="Item",
      background(ishovered(r) ? colours.hover : clear),
    Box(fixed(18px * z), Alignment.Center, Icon("square", size=12px * z, color=colours.dim)),
    Box(label(elide(m.text, 13px * z, r.room - 25px * z - tail), 13px * z, color=colours.ink)), Box(width(grow=grow)),
    (isempty(page) ? () : (Box(label(elide(page, 11.5px * z, tail - 8px * z), 11.5px * z, color=colours.faint)),))...)
end

cursor(::ContactWork) = :hand
onkey(r::ContactWork, ::KeyPress{Keys.mouse_left}) = (m = work_of(r); m === nothing ? handled : visit!(editor(r.of), m.path, m))

# --- the clock of a to-do item -----------------------------------------------------------------
#
# On a page with a time log, the mouse over a to-do item shows a small
# button at the end of the item's line, with the hours that the log has for
# the item. A click starts the log's clock on the item: the log gets a new
# line for now, with the item's words as its task. While the clock runs on
# the item, the button stops it. A tick in the item's box stops it too.
#
# The item and the log send each other nothing. The button calls the log's
# own `Timelogs.start!` and `Timelogs.stop!` on the log's view, and writes
# the log's block. The schedule asks `worked` for the hours of each task, and
# shows them beside the task's name.

push!(BLOCK_ICONS, "play-fill", "stop-fill")

"The button beside a to-do item that starts and stops the clock of the page's time log on the item"
@def mutable struct ItemClock <: SemanticUI
  key::String = ""                              # the to-do item, by what a schedule calls it
  rect::NTuple{4,px} = (0px, 0px, 0px, 0px)     # where it was last drawn, to put its tooltip over it
end

"The view of the page's first time log, read again from the lines of its block, or nothing when the page has none or can't be changed"
page_log(e) = begin
  b = e.buf
  (readonly(b) || b.fixed) && return nothing
  span = get!(() -> block_lines(b, TIMELOG, 1), e.flows, (:log_block, b.path, b.version))
  span === nothing && return nothing
  v = block_view(e, TIMELOG, 1)
  v.first, v.last = span
  reread!(v, b.lines[span[1]+1:span[2]-1])
end

"""
The minutes that the page's time logs have for each task, by the task's name
as `plain_name` gives it. A row that runs counts up to now, so they're worked
out again each minute, and when the page has changed.
"""
page_minutes(e) = begin
  b = e.buf
  at = Timelogs.now()
  get!(e.flows, (:minutes, b.path, b.version, Dates.format(at, "yyyymmddHHMM"))) do
    out = Dict{String,Int}()
    ks = kinds(b)
    for (i, k) in enumerate(ks)
      (k.kind == Kind.fence && k.level == 0 && k.lang == TIMELOG) || continue
      t = codeblock(b, i)[2]
      (t > i && ks[t].kind == Kind.fence && ks[t].level == 1) || continue
      for (task, minutes) in Timelogs.tasks(Timelogs.timelog(b.lines[i+1:t-1]), at)
        out[plain_name(task)] = get(out, plain_name(task), 0) + minutes
      end
    end
    out
  end
end

"The minutes that the page's time logs have for the task called `name`"
worked(e, name::AbstractString) = get(page_minutes(e), plain_name(name), 0)

"The to-do item of the page that a schedule calls `key`, or nothing"
todo_called(e, key) = (items = page_todos(e); k = findfirst(t -> t.key == key, items); k === nothing ? nothing : items[k])

"True when the clock of the log `log` runs on the task called `name`"
clocked(log::TimelogView, name::AbstractString) = begin
  run = Timelogs.running(log.data)
  run !== nothing && plain_name(log.data.rows[run].task) == plain_name(name)
end

describe(c::ItemClock) = begin
  e = editor(c)
  log, t = page_log(e), todo_called(e, c.key)
  (log === nothing || t === nothing) && return Box(width(0px), height(18px))
  on = clocked(log, t.name)
  on && redraw_in!(c, 1.0)   # the hours count up
  minutes = worked(e, t.name)
  words = on ? Timelogs.elapsed(Timelogs.seconds(log.data, Timelogs.running(log.data), Timelogs.now())) : minutes > 0 ? Timelogs.hours(minutes) : ""
  Row(height(18px), child_gap=4px, Alignment.Center, name="Clock",
    Box(width(18px), height(18px), radius(4px), Alignment.Center, justify=Alignment.Center,
        background(on ? colours.active : ishovered(c) ? colours.hover : clear),
      Icon(on ? "stop-fill" : "play-fill", size=12px, color=on ? colours.accent : colours.dim)),
    (isempty(words) ? () : (Box(label(words, 12px, color=on ? colours.accent : colours.dim)),))...)
end

cursor(::ItemClock) = :hand
draw(ctx, size, ui::ConcreteRect, c::ItemClock) = (c.rect = (ui.left, ui.top, ui.width, ui.height); nothing)

onmouse(c::ItemClock, ev::MouseMove) = begin
  e = editor(c)
  log, t = page_log(e), todo_called(e, c.key)
  (log === nothing || t === nothing) && return handled
  show_tooltip!(ev.window, tip_label(clocked(log, t.name) ? "Stop the clock" : "Start the clock on this item"), c.rect..., placement=:top, gap=6px)
  handled
end

onkey(c::ItemClock, ev::KeyPress{Keys.mouse_left}) = begin
  e = editor(c)
  log, t = page_log(e), todo_called(e, c.key)
  hide_tooltip!(ev.window)
  (log === nothing || t === nothing) && return handled
  at = Timelogs.now()
  clocked(log, t.name) ? Timelogs.stop!(log.data, at) : Timelogs.start!(log.data, t.name, at)
  write_log!(log)
  handled
end

"""
Stop the clock of the page's time log, when it runs on the to-do item of line
`i` and the item has just been ticked. The stop is taken back with the tick.
"""
stop_clock!(e, i::Int) = begin
  b = e.buf
  (1 <= i <= length(b.lines) && isdone(b.lines[i])) || return e
  log = page_log(e)
  log === nothing && return e
  k = findfirst(t -> t.line == i, page_todos(e))
  (k !== nothing && clocked(log, page_todos(e)[k].name)) || return e
  Timelogs.stop!(log.data, Timelogs.now())
  b.typed = time()   # the tick and the log's line change together, so one ⌘Z takes both back
  write_block!(log, TIMELOG, Timelogs.written(log.data), typing=true)
  b.typed = 0.0
  e
end

# --- names that one part of the page has from another -------------------------------------------
#
# A row of a sheet can use a name from a part of the page over it, the way
# it uses the name of a row above it: a measure of a takeoff, a task of a
# time log, and a row of another sheet. So "Tiles = kitchen floor tiles /
# 0.36m^2" follows the outline that's drawn on the plan. A sum in a line of
# text can use the same names, and the names of every sheet of the page, as
# Julia knows them: !`wall_length` for the row "Wall length". The code of the
# page's `julia` blocks can use them too.
#
# No part sends its values anywhere. `block_names(lang, lines)` says what the
# block of one kind gives: each name with an expression for its value, as a
# row of a sheet has. A sheet asks for the names of the blocks over it with
# `page_given`, and works them out as rows over its first row.

"""
What a block in the language `lang` gives the rest of its page: names, each
with an expression for its value, as a row of a sheet has. `lines` are the
lines of the block. A sheet gives its rows, a takeoff gives each measure with
its amount, and a time log gives each task with its hours.
"""
block_names(lang, lines) = begin
  out = Tuple{String,String}[]
  if lang == SHEET
    append!(out, (row for row in parts.(lines) if !isempty(ident(row[1]))))
  elseif lang == TAKEOFF
    t = Plans.takeoff(lines)
    for m in t.measures
      a = isempty(strip(m.name)) ? nothing : Plans.amount(t, m)
      a === nothing && continue
      x = string(round(a, digits=4))
      push!(out, (m.name, m.kind == :count ? x : m.kind == :length ? x * "m" : x * "m^2"))
    end
  elseif lang == TIMELOG
    for (task, minutes) in Timelogs.tasks(Timelogs.timelog(lines), Timelogs.now())
      isempty(strip(task)) || push!(out, (task, string(round(minutes / 60, digits=4)) * "hr"))
    end
  end
  out
end

"""
The names that the sums in a line of text give, each with the code of its
value: !`farm = 2GW` gives ("farm", "2GW"). A sum that gives no name, like
!`farm * 2`, gives nothing. A `_` of a name is a space, so a row of a sheet
can use !`farm_cost = …` as "farm cost", the way a sum uses the row "Farm
cost" as `farm_cost`.
"""
sum_names(text::AbstractString) = [(name, expr) for (name, expr, _, _) in named_sums(text)]

"What `sum_names` gives, with the code of each sum and the column where its code starts in `text`"
named_sums(text::AbstractString) = begin
  out = Tuple{String,String,String,Int}[]
  occursin(INLINE, text) || return out
  for m in eachmatch(r"!`([^`]+)`", text)
    code = String(m[1])
    name = sum_name(code)
    name === nothing && continue
    # The name has no =, so the first = is the one after it
    push!(out, (replace(String(name), '_' => ' '), String(strip(code[nextind(code, findfirst('=', code)):end])), code, length(text, 1, m.offset) + 1))
  end
  out
end

"The name that the code of a sum gives, like `:farm` for `farm = 2GW`, or nothing"
sum_name(code::AbstractString) = begin
  ex = try Meta.parse(code, raise=false) catch; nothing end
  ex isa Expr && ex.head == :(=) && length(ex.args) == 2 && ex.args[1] isa Symbol ? ex.args[1] : nothing
end

"""
True when the code of a sum uses one of `names` for its value. The name that
the sum gives doesn't count, nor does the name of a keyword: in
`p = ProgressBar(value=x)` only `x` counts.
"""
follows(code::AbstractString, names) = begin
  ex = try Meta.parse(code, raise=false) catch; return false end
  sum_name(code) === nothing || (ex = ex.args[2])
  found = false
  look(x) = if x isa Symbol
    x in names && (found = true)
  elseif x isa Expr
    foreach(look, x.head in (:kw, :(=)) && x.args[1] isa Symbol ? x.args[2:end] : x.args)
  end
  look(ex)
  found
end

"""
The names that the parts of the page over line `upto` give, each with an
expression for its value. With no line, it's the names of the whole page.
With `sums`, the sums in the lines of text give their names too, so a sheet
can use !`farm = 2GW` as `farm`. They're found again when the page has changed.
"""
page_given(e, upto::Int=typemax(Int); sums::Bool=false) = given_and_sums(e, upto, sums)[1]

"""
`page_given`, and where each name that a sum gives is: its place in that
list, and the code and the ordinal that `made` keeps the sum by.
"""
given_and_sums(e, upto::Int, sums::Bool) = begin
  b = e.buf
  get!(e.flows, (:given_sums, b.path, b.version, upto, sums)) do
    out = Tuple{String,String}[]
    spots = Tuple{Int,String,Int}[]
    ks = kinds(b)
    i = 1
    while i <= length(ks) && i < upto
      k = ks[i]
      if k.kind == Kind.fence && k.level == 0
        t = codeblock(b, i)[2]
        if t > i && ks[t].kind == Kind.fence && ks[t].level == 1
          t < upto && k.lang in (SHEET, TAKEOFF, TIMELOG) &&
            append!(out, get!(() -> block_names(k.lang, b.lines[i+1:t-1]), e.flows, (:block_names, k.lang, b.lines[i+1:t-1])))
          i = t
        end
      elseif sums && !(k.kind in (Kind.fence, Kind.code))
        for (name, expr, code, col) in get!(() -> named_sums(b.lines[i]), e.flows, (:named_sums, b.lines[i]))
          push!(out, (name, expr))
          push!(spots, (length(out), code, ordinal(e, i, col, code)))
        end
      end
      i += 1
    end
    (out, spots)
  end
end

"""
What the sheet whose block opens on line `upto` has from the parts of the
page over it: what `page_given` gives with `sums`, but a sum that didn't go
wrong gives what it came to, as a `Given`, in place of its code. The sheet
takes that value as it is. So a sum that takes long, like one that adds up
thousands of numbers, runs once for its line, and not again for each sheet
under it.

A sum over the sheet that hasn't run since the page changed runs here, as it
would when its line is laid out, from the top down. A chart near the top of
the page asks for every table of the page before the sums under it are laid
out, and the sheet then has the same values for it as for the rest of the frame.
"""
sheet_given(e, upto::Int) = begin
  b = e.buf
  given, spots = given_and_sums(e, upto, true)
  foreach(((_, code, n),) -> made(e, code, n), spots)
  get!(e.flows, (:sheet_given, b.path, b.version, upto, sums_run[])) do
    values = get(e.nodes, (:sum_values, b.path), nothing)
    out = Tuple{String,Any}[given...]
    values === nothing && return out
    for (k, code, n) in spots
      made = get(e.nodes, (:inline, b.path, code, n), nothing)
      (made isa Tuple && !made[2] && haskey(values, (code, n))) || continue
      out[k] = (given[k][1], Given(values[(code, n)]))
    end
    out
  end
end

"""
Keep what the `n`th sum `code` of the page came to, when it gives a name and
didn't go wrong, so that `sheet_given` can give it to the sheets under it.
"""
keep_value!(e, code::String, n::Int, failed::Bool) = begin
  values = get!(() -> Dict{Tuple{String,Int},Any}(), e.nodes, (:sum_values, e.buf.path))
  delete!(values, (code, n))
  name = sum_name(code)
  (failed || name === nothing) && return
  # A drag makes a new sum on each step, so the values of sums that the page no longer has are forgotten
  length(values) > 400 && filter!(((k, _),) -> haskey(e.nodes, (:inline, e.buf.path, k...)), values)
  try
    values[(code, n)] = Base.invokelatest(getglobal, workspace(e), name)
  catch
  end
end

"""
Give the page's code the names of the page's sheets, takeoffs and time logs,
with their values, and say what they came to. A sum in a line of text, and
the code of a `julia` block, can then use a row called "Wall length" as
`wall_length`. A name that the page's code already has, like `sum`, stays as
it is. `inline_tick!` runs the page's sums again when what this gives changes.
"""
inline_given!(e) = begin
  given = page_given(e)
  isempty(given) && return nothing
  values = get!(() -> name_values(given), e.flows, (:name_values, given))
  m = workspace(e)
  ours = get!(() -> Set{Symbol}(), e.nodes, (:given_names, e.buf.path))
  for (id, value) in values
    name = Symbol(id)
    (name in ours || !Base.invokelatest(isdefined, m, name)) || continue
    try
      Core.eval(m, Expr(:(=), name, QuoteNode(value)))
      push!(ours, name)
    catch
    end
  end
  hash(given)
end

# --- blocks that a file defines --------------------------------------------------------------
#
# A page can have kinds of block that Ladder doesn't know. A code block in a
# language that isn't one of Ladder's own, like `progress`, is such a block
# when a file defines the language. The file is `progress.jl` in the page's
# folder, or the file or the GitHub repository that the line that opens the
# block names after the language:
#
#     ```progress                             progress.jl, beside the page
#     ```progress ./widgets.jl                a file that has another name
#     ```progress github.com/sam/blocks       a repository on GitHub
#     ```progress github.com/sam/blocks@v2    one branch of it
#
# The file can be a Markdown page too: `progress.md` beside the page, when
# there's no `progress.jl`, or a path that ends in `.md`. Ladder runs the code
# of the page's `julia` blocks, from the top, in one module, and that module
# defines the kind of block as a Julia file's module does. So the page can say
# in words what its code does, and can hold a block of its own kind to try.
#
# A file beside the page only counts if its text defines a function with the
# language's name that takes one thing. So a page in a folder of Julia code
# doesn't run `json.jl` because it has a block of JSON.
#
# The file has a function with the language's name. Ladder gives it the lines
# of the block, and shows what it makes, as a `ui` block shows what its code
# makes: a node draws itself, and any other value shows as text. If the file
# also has a function called `written`, it gives the lines of what was made,
# and Ladder writes them into the block. So what you do to the block is in
# the page's file.
#
#     progress(lines)          makes a Progress from the lines of the block
#     describe(p::Progress)    draws it
#     written(p::Progress)     the lines of its block now
#
# There are three times that Ladder writes a block's lines:
#
#   - Before something reads the page's text: ⌘S, the caret going into the
#     block, a copy, a page of HTML, another page taking the window. The file
#     does nothing for this.
#   - When the component asks, with UI.jl's `changed!(p)`. Ladder writes in
#     the next frame that the mouse isn't held in. Changes that come one soon
#     after another are one step for ⌘Z.
#   - At once, when the component says `changed!(p, now=true)`.
#
# A change that's written only by the first of these doesn't mark the page as
# edited until then, and ⌘Z can't take it back. So a component asks for a
# write after each change that you'd want to take back.
#
# What was made is kept until the block's lines change some other way: you
# type in them, or ⌘Z puts back older ones. Then the function makes it again.
#
# Ladder asks you before it runs the code of a GitHub repository for the
# first time, and keeps the repositories that you allow in a file.
#
# A file on this Mac is loaded again when it's saved, so a kind of block
# changes as you write it. Each block that the file defines is then made again.

"The file or the repository that follows the language on the line that opens a code block"
const SOURCE = r"^\s*(?:`{3,}|~{3,})\s*[^\s`]+[ \t]+((?:\.{1,2}/|~?/|github\.com/)\S+)\s*$"

"True when Ladder itself says what a code block in the language `lang` shows"
known_lang(lang) = lang in (LIVE, SHEET, SPREADSHEET, DIAGRAM, MATH, TAKEOFF, SCHEDULE, MATTER, TOML_MATTER, HEX, BITS, COMMENT, "julia") || haskey(BLOCKS, lang)

"What was found in each file that could define a kind of block: when the file was saved, and whether its text defines the function"
const DEFINES = Dict{Tuple{String,String},Tuple{Float64,Bool}}()

"""
True when the text of `file` defines a function called `name` that takes one
thing, like `progress(lines) = ...` or `function progress(lines)`. The file
is read again only when it's saved.
"""
defines(file::AbstractString, name::AbstractString) = begin
  at = mtime(file)
  at == 0 && return false
  kept = get(DEFINES, (file, name), nothing)
  kept !== nothing && kept[1] == at && return kept[2]
  code = ismarkdown(file) ? join(last.(page_code(file)), "\n") : read(file, String)
  found = occursin(Regex("^(?:function[ \\t]+)?\\Q$name\\E\\([^,;)]+[;)]", "m"), code)
  DEFINES[(file, name)] = (at, found)
  found
end

"""
Where the function of a block in the language `lang` comes from, as Kip names
it: a file or a GitHub repository. `text` is the line that opens the block, and
`folder` is the folder of its page. It's nothing when no file defines the language.
"""
block_source(text::AbstractString, lang::AbstractString, folder::AbstractString) = begin
  (Base.isidentifier(lang) && !known_lang(lang)) || return nothing
  m = match(SOURCE, text)
  m === nothing || return String(m[1])
  isempty(folder) && return nothing
  # A Julia file comes before a Markdown page with the same name
  k = findfirst(ext -> defines(joinpath(folder, lang * ext), lang), (".jl", ".md"))
  k === nothing ? nothing : "./$lang$((".jl", ".md")[k])"
end

"""
The module of each Markdown page's `julia` code, by the real path of the
page's file. There's one for each file, as Kip has one for each Julia file.
The page's live blocks, the code that you run on it in any window, and the
kinds of block that it defines are all in the same module. See `page_module`.
"""
const PAGE_MODULES = Dict{String,Module}()

"The window whose code ran last in the module of each page, by the page's path. A name of the module that acts on a window, like `page_theme!`, acts on that one."
const PAGE_WINDOWS = Dict{String,Any}()

"The pages whose code has all run in their module, by path, as the kinds of block that a page defines need"
const PAGES_RUN = Set{String}()

"The path that the module of the page at `path` is kept by: the file's real path, as Kip keeps a module by, or the address of a page on the web"
page_key(path::AbstractString) = isremote(path) ? String(path) : isfile(path) ? realpath(path) : abspath(path)

"The name of the module of the page at `path`: its path, with ~ for your home folder, and a ⭒ in front, as Kip's modules have"
page_module_name(path::AbstractString) = Symbol("⭒", Base.Filesystem.contractuser(page_key(path)))

"The code of each `julia` block of the Markdown page at `path`, with the line of the page that it starts on. `lines` are the page's lines."
page_code(path::AbstractString, lines=text(path)) = begin
  ks = classify(lines)
  out = Tuple{Int,String}[]
  for (i, k) in enumerate(ks)
    (k.kind == Kind.fence && k.level == 0 && k.lang == "julia") || continue
    t = something(findnext(c -> c.kind == Kind.fence, ks, i + 1), length(lines) + 1)
    push!(out, (i + 1, join(lines[i+1:t-1], "\n")))
  end
  out
end

"""
Run the code of the Markdown page at `path` in the module `m`: each of its
`julia` blocks, from the top. An error names the line of the page that it's on.
"""
run_page!(m::Module, path::AbstractString) = (page_value(m, path); m)

"""
Run the code of the Markdown page at `path` in the module `m`, as `run_page!`
does. It gives the value of the last `julia` block, or nothing when the page
has none. `lines` are the page's lines, as a page from a web server gives them.
"""
page_value(m::Module, path::AbstractString, lines=text(path)) = begin
  value = nothing
  for (line, code) in page_code(path, lines)
    try
      # Empty lines before the code give each line of it the number that it has in the page
      value = run_in(m, "\n"^(line - 1) * code, path)
    catch err
      error("Line $(err isa LoadError ? err.line : line) of $(basename(path)): $(trouble(err))")
    end
  end
  value
end

"""
Run the code `code` of the page at `path` in the page's module `m`, as
`include_string` does, and give the value that it comes to. A function that
the code defines with the name of a unit, like `bar(p) = …`, is a new function
of the page. Julia gives a unit that new method instead: a unit is a type, and
a page has the units with `using`, so Julia takes the code as a new way to make
the unit. A name that the page loads or makes itself is as Julia has it.
"""
run_in(m::Module, code::AbstractString, path::AbstractString) = include_string(ex -> own_units(m, ex), m, code, path)

# --- a sum that makes a function --------------------------------------------------------------
#
# Julia compiles code that makes a function each time the code runs, like
# the generator of !`years = sum(exp(-fade * t) for t in 0:0.05:2000)` or the
# `t -> …` of a findfirst. That takes far longer than the sum itself, and a
# drag on a number that the sum reads runs it again on each step. So such a
# sum is made into a function with no arguments the first time, and that
# function runs each time after. It reads the page's names as it runs, so it
# follows them, and Julia compiles it only once.
#
# Only code that means the same in a function does this: code that gives no
# name a value, except inside a `let`, a function or a generator, where the
# name is the code's own. Any other sum runs as the code of a file does.

"""
Run the code of a sum in a line of text in the module `m`, as `run_in` does.
A sum that makes a function runs as a function that's made once: see "a sum
that makes a function".
"""
run_sum(m::Module, code::AbstractString, path::AbstractString) = begin
  f = sum_function(m, code)
  f === nothing && return run_in(m, code, path)
  value = Base.invokelatest(f)
  name = sum_name(code)
  name === nothing || Core.eval(m, Expr(:(=), name, QuoteNode(value)))
  value
end

const SUM_FUNCTIONS = Dict{Tuple{Module,String},Any}()   # by the module and the code of a sum

"The function that the code of a sum in the module `m` runs as, or nothing when the code runs as code"
sum_function(m::Module, code::AbstractString) = begin
  key = (m, String(code))
  haskey(SUM_FUNCTIONS, key) && return SUM_FUNCTIONS[key]
  ex = try Meta.parse(code, raise=false) catch; nothing end
  sum_name(code) === nothing || (ex = ex.args[2])
  f = makes_function(ex) && in_function(ex, true) ? Core.eval(m, Expr(:->, Expr(:tuple), Expr(:block, ex))) : nothing
  # Typing makes a new sum with each key, so the functions of old sums are forgotten now and then
  length(SUM_FUNCTIONS) >= 500 && empty!(SUM_FUNCTIONS)
  SUM_FUNCTIONS[key] = f
end

"True when the code `ex` makes a function as it runs, or has a loop, which Julia compiles too"
makes_function(ex) = ex isa Expr && (ex.head in (:generator, :comprehension, :typed_comprehension, :->, :do, :function, :for, :while) || any(makes_function, ex.args))

"""
True when the code `ex` means the same in a function as it does on its own.
`top` is true outside a `let`, a function or a generator: there, code that gives
a name a value would give the page's name a value, and in a function it
wouldn't. Code that declares or loads anything, or has a macro, doesn't either.
"""
in_function(ex, top::Bool) = begin
  ex isa Expr || return true
  h = ex.head
  h in (:global, :const, :local, :using, :import, :export, :module, :struct, :abstract, :primitive, :toplevel, :macrocall, :quote) && return false
  # The names in a let, a function or a generator are their own
  h in (:let, :->, :do, :generator, :comprehension, :typed_comprehension) && return all(x -> in_function(x, false), ex.args)
  if h == :function
    # A function with a name gives that name a value
    sig = ex.args[1]
    top && !(sig isa Expr && sig.head == :tuple) && return false
    return all(x -> in_function(x, false), ex.args)
  end
  # The names of a named tuple, and of the keywords of a call, aren't names that get a value
  h in (:tuple, :parameters) && return all(x -> Meta.isexpr(x, :(=)) ? in_function(x.args[2], top) : in_function(x, top), ex.args)
  h == :kw && return in_function(ex.args[2], top)
  top && (h == :(=) || (endswith(string(h), "=") && !(h in (:(==), :(!=), :(<=), :(>=), :(===), :(!==))))) && return false
  all(x -> in_function(x, top), ex.args)
end

"The expression `ex` of a page's code, with `function bar end` before it for each unit, like `bar`, that it defines a function of. See `run_in`."
own_units(m::Module, ex) = begin
  found = filter(n -> unit_of(m, n), defined_names!(Symbol[], ex))
  isempty(found) ? ex : Expr(:toplevel, (Expr(:function, n) for n in unique(found))..., ex)
end

"The names of the functions that the expression `ex` defines, like `f` for `f(x) = x`, added to `out`. A definition can be inside a `begin` block, and have documentation or a macro before it."
defined_names!(out::Vector{Symbol}, ex) = begin
  if Meta.isexpr(ex, (:block, :toplevel))
    foreach(x -> defined_names!(out, x), ex.args)
  elseif Meta.isexpr(ex, :macrocall) && length(ex.args) > 2
    defined_names!(out, last(ex.args))
  elseif is_definition(ex)
    lhs = ex.args[1]
    while Meta.isexpr(lhs, (:where, :(::))) && !isempty(lhs.args)
      lhs = lhs.args[1]
    end
    Meta.isexpr(lhs, :call) && lhs.args[1] isa Symbol && push!(out, lhs.args[1])
  end
  out
end

"True when the name `n` in the module `m` is a unit of a sheet that `m` has with `using`, and not a name of its own or one that it loaded"
unit_of(m::Module, n::Symbol) = begin
  sheet = units()
  Base.invokelatest(isdefined, sheet, n) && Base.invokelatest(isdefined, m, n) || return false
  # The names that `m` has made, and the ones that it loaded by name, like `@use "…/Units.jl" bar`
  n in Base.invokelatest(names, m; all=true, imported=true) && return false
  Base.invokelatest(getglobal, m, n) === Base.invokelatest(getglobal, sheet, n)
end

"""
The module of the page at `path`, which the window `e` asks for. A file of
code that Ladder loaded has the module that Kip made from it, so code that
runs in its window changes what's loaded: see "the code of a thing". The
module of any other page is made the first time, and kept by the page's real
path. It has what a Julia file that Kip loads has, like `@use`, and more
names by the kind of page:

  - The startup page and a folder's page have `Ladder`, as they have when
    Ladder runs their code. Each time Ladder runs one, the page has a new
    module: see `code_module!`.
  - Any other page has the names that its window gives a page's code, like
    UI.jl's components, and each unit of a sheet: see `usual_module`.

The module's name is the page's path. So a page called `stars` can define a
function called `stars`, and two pages with the same name have two modules.
"""
page_module(e, path::AbstractString) = begin
  key = page_key(path)
  # A file of code that Ladder loaded has the module that the file made, so code that runs there changes what's loaded
  loaded = loaded_module(key)
  loaded === nothing || return loaded
  get!(PAGE_WINDOWS, key, e)
  m = get!(() -> ladder_runs(key) ? code_module(key) : usual_module(e, page_module_name(key), key), PAGE_MODULES, key)
  # A window that's newer than the module can give a page's code more names. It gives them once.
  get!(() -> Base.invokelatest(isdefined, m, :Usual) && window_names!(m, e, key), e.nodes, (:page_names, key))
  m
end

"The module of the page at `path`, as `page_module` gives it, with all of the page's code run in it, as a kind of block that the page defines needs"
page_run(e, path::AbstractString) = begin
  m = page_module(e, path)
  key = page_key(path)
  key in PAGES_RUN || (run_page!(m, path); push!(PAGES_RUN, key))
  m
end

"""
Give the file that the window `e` shows a new, empty module for its code, in
place of the one it had. The names, the methods and the files that its code
made or loaded are gone. The new module is made when code next runs on the
file, as it is the first time: see `page_module`. Each window that shows the
file runs its live blocks and its inline code again, in the new module. What
⌘Return showed under the code stays as it was.
"""
reset_module!(e) = begin
  path = e.buf.path
  isempty(path) && delete!(e.nodes, :workspace)
  key = isempty(path) ? "" : page_key(path)
  isempty(key) || (delete!(PAGE_MODULES, key); delete!(PAGES_RUN, key))
  for w in unique!(Any[e; editors])
    w === e || (!isempty(w.buf.path) && page_key(w.buf.path) == key) || continue
    delete!(w.nodes, (:page_names, key))
    # What the page's code made goes, so that it runs again in the new module
    p = w.buf.path
    gone(k) = k isa Tuple && length(k) >= 2 &&
              ((k[1] in (:live, :inline, :given_names, :inline_seen) && k[2] == p) ||
               (k[1] == :replaced && k[2] isa Tuple && k[2][1] == :live && k[2][2] == p))
    foreach(k -> delete!(w.nodes, k), filter(gone, collect(keys(w.nodes))))
    empty!(w.flows)
  end
  nothing
end

"""
The file on this Mac that the source `source` names inside a repository, like
`github.com/sam/blocks/progress.md`. Kip gets the repository if it isn't here.
"""
repository_file(source::AbstractString) = begin
  user, repo, tag, inside = match(Kip.gh_shorthand, source).captures
  folder = Base.invokelatest(Kip.checkout, Base.invokelatest(Kip.getrepo, user, repo), user, repo, tag)
  joinpath(folder, something(inside, ""))
end

"Where the function of the block that opens on line `s` of `b` comes from, or nothing when no file defines its language"
block_source(b::Buffer, s::Int) = foreign(b.path) ? nothing : block_source(b.lines[s], kinds(b)[s].lang, isempty(b.path) ? "" : dirname(b.path))

"The `user/repo` of a source that's a GitHub repository, or nothing for a file on this Mac"
repository(source::AbstractString) = (m = match(r"^github\.com/([\w\-.]+)/([\w\-.]+)", source); m === nothing ? nothing : "$(m[1])/$(m[2])")

"The GitHub repositories whose code you let a block run, since Ladder opened"
const ALLOWED = Set{String}()

"The file that keeps the repositories you allowed, one on each line"
allowed_file() = joinpath(dirname(settings_file()), "repositories")

"True when you have let a block run the code of the GitHub repository `repo`"
allowed(e, repo::AbstractString) = repo in ALLOWED || (e.remember && isfile(allowed_file()) && repo in eachline(allowed_file()))

"Let a block run the code of the GitHub repository `repo`, now and when Ladder next opens"
allow!(e, repo::AbstractString) = begin
  allowed(e, repo) && return
  push!(ALLOWED, repo)
  e.remember || return
  try
    mkpath(dirname(allowed_file()))
    open(io -> println(io, repo), allowed_file(), "a")
  catch
    # A file that can't be written only means Ladder asks again the next time it opens
  end
  nothing
end

"A block that a file defines: what the file's function made of the lines of the block"
@def mutable struct FileBlock <: SemanticUI
  n::Int = 0                               # its place among the page's blocks in its language
  first::Int = 0                           # the lines of its block, when the page was last laid out
  last::Int = 0
  lang::String = ""
  source::String = ""                      # where its function comes from, as the page names it
  lines::Vector{String} = String[]         # the lines that `value` was made from, or that it wrote last
  state::Symbol = :new                     # :new, :ask (you haven't allowed its repository), :wait and :get (its repository comes), :made or :fault
  from::Any = nothing                      # the module of the file
  file::String = ""                        # the file on this Mac that the module comes from, or "" for a repository or a folder
  read::Float64 = 0.0                      # when that file was last saved, as this block last knew it
  value::Any = nothing                     # what the function made
  shown::Any = nothing                     # the Shown that draws it
  said::Any = nothing                      # the lines that `written` last gave for it, or nothing
  wants::Bool = false                      # what was made asked for its lines to be written
  inside::Bool = false                     # the caret was in the block's lines in the last frame
  fault::String = ""                       # what went wrong
  parts::Dict{Any,Any} = Dict{Any,Any}()   # its button, kept between frames
end

cursor(::FileBlock) = :arrow

"The view of the `n`th block of the page in the language `lang`, which the file or the repository `source` defines"
file_block(e, lang, source, n) = begin
  v = get!(() -> FileBlock(n=n, lang=lang), e.nodes, (:block, lang, e.buf.path, n))
  own!(node!(Document, e, :document), v)
  v.source == source || (v.source = source; v.from = nothing; v.file = ""; v.state = :new)
  v
end

"What the block in the language `lang` from line `i` to line `t` shows. A file or a repository, `source`, defines the language."
file_block_item(e, lang, source, i, t, n) = begin
  v = file_block(e, lang, source, n)
  v.first, v.last = i, t
  reread!(v, e.buf.lines[i+1:t-1])
  # Lay it out once to learn how tall it is
  concrete = describe(Column(fixed(e.width), Alignment.Start, geometry(v)), (e.width, 9999px))
  Live(v, concrete.height + 2LIVE_GAP)
end

reread!(v::FileBlock, lines) = begin
  (lines == v.lines && v.state != :new) && return v
  v.lines = lines
  make!(v)
end

"True when Kip has the GitHub repository `repo` on this Mac, so that nothing has to come from GitHub"
here(repo::AbstractString) = isdir(joinpath(Kip.repos, repo))

"The module of the file or the repository `source`. A path like `./progress.jl` starts from the folder of the page."
source_module(e, source::AbstractString) = begin
  folder = isdir(docdir(e)) ? docdir(e) : pwd()
  # A Markdown page isn't Julia code, so Kip doesn't load it: the page's `julia` blocks make its module
  if ismarkdown(source)
    file = repository(source) === nothing ? source_file(e, source) : repository_file(source)
    isfile(file) || error("Ladder can't find the page $source.")
    return cd(() -> Base.invokelatest(page_run, e, realpath(file)), folder)
  end
  cd(() -> Base.invokelatest(Kip.require, source, folder), folder)
end

"True when `source` names a file or a folder that's on this Mac, as Kip looks for it: the path as it is, or with `.jl` after it"
source_found(e, source::AbstractString) = begin
  path = startswith(source, "~/") ? homedir() * source[2:end] : normpath(joinpath(docdir(e), source))
  ispath(path) || isfile(path * ".jl")
end

"The file on this Mac that `source` names, or \"\" when it names a folder, or a file that isn't there"
source_file(e, source::AbstractString) = begin
  path = startswith(source, "~/") ? homedir() * source[2:end] : normpath(joinpath(docdir(e), source))
  isfile(path) || (path *= ".jl")
  isfile(path) ? realpath(path) : ""
end

"When each file that defines a kind of block was last loaded: the time that the disk gave for it then"
const LOADED = Dict{String,Float64}()

"The files that define a kind of block and didn't load, with what went wrong"
const BROKEN = Dict{String,String}()

"What went wrong, as a block shows it"
trouble(err) = sprint(showerror, err isa LoadError ? err.error : err)

"""
Load the file of the block of `v` again if it was saved since it was loaded,
so that a kind of block changes as you write it. Each block that the file
defines is then made again from its lines.
"""
reload!(v::FileBlock) = begin
  isempty(v.file) && return v
  at = mtime(v.file)
  at == 0 && return v   # the file is gone, so the block stays as it is
  if at != get(LOADED, v.file, at)
    write_blocks!(editor(v))   # what the blocks hold goes into their lines first, since they're made again from those
    LOADED[v.file] = at
    delete!(BROKEN, v.file)
    m = get(Kip.modules, v.file, get(PAGE_MODULES, page_key(v.file), nothing))
    try
      # The file's new code goes into the module that it has. A file that didn't load the first time has none yet.
      m === nothing || (ismarkdown(v.file) ? Base.invokelatest(run_page!, m, v.file) : Base.include(m, v.file))
    catch err
      BROKEN[v.file] = trouble(err)
    end
  end
  v.read == get(LOADED, v.file, v.read) || (v.state = :new)
  v
end

"The function called `name` of the module `from`, or nothing if the module has none"
named(from, name::Symbol) = Base.invokelatest(isdefined, from, name) ? Base.invokelatest(getglobal, from, name) : nothing

"""
The lines of the block of `v` as what the block made writes them now. It's
nothing when the file has no function `written` for what was made.
"""
lines_now(v::FileBlock) = begin
  w = named(v.from, :written)
  (w === nothing || !Base.invokelatest(applicable, w, v.value)) && return nothing
  out = Base.invokelatest(w, v.value)
  String[String(l) for l in (out isa AbstractString ? split(out, '\n') : out)]
end

"""
The Shown that draws what the block of `v` made: its node, or its words when
it has no node. Words show as they are, and any other value as Julia prints it.
"""
shown(v::FileBlock) = begin
  node = Base.invokelatest(present, v.value)
  words = node !== nothing ? "" : v.value isa AbstractString ? v.value : Base.invokelatest(repr, "text/plain", v.value)
  s = own!(v, Shown(value=node === nothing ? note(words, colours.ink) : node))
  s.value isa SemanticUI && own!(s, s.value)
  s
end

"Note that the block of `v` can't show, and why"
fault!(v::FileBlock, why) = begin
  v.state, v.fault = :fault, String(why)
  push!(problems, v.fault)
  v
end

"""
Make what the block of `v` shows from its lines: load its file, and give the
lines to the function that has the language's name. A repository that you
haven't allowed isn't loaded: the block asks first. With `now`, a repository
that has to come from GitHub comes now. Without it, the block first says that
it's coming, because the window stops while it comes.
"""
make!(v::FileBlock; now=false) = begin
  e = editor(v)
  old = v.shown
  v.value = v.shown = v.said = nothing
  repo = repository(v.source)
  if v.from === nothing && repo !== nothing
    allowed(e, repo) || (v.state = :ask; return v)
    (now || here(repo)) || (v.state = :wait; return v)
  end
  v.from === nothing && repo === nothing && !source_found(e, v.source) &&
    return fault!(v, "Ladder can't find the file $(v.source). The line that opens this block names it.")
  repo === nothing && isempty(v.file) && (v.file = source_file(e, v.source))
  if !isempty(v.file)
    v.read = get!(() -> mtime(v.file), LOADED, v.file)
    haskey(BROKEN, v.file) && return fault!(v, BROKEN[v.file])
  end
  try
    v.from === nothing && (v.from = source_module(e, v.source))
    f = named(v.from, Symbol(v.lang))
    f === nothing && return fault!(v, "$(v.source) has no function called $(v.lang). A block in the language $(v.lang) shows what that function makes of the block's lines.")
    v.value = Base.invokelatest(f, copy(v.lines))
    v.shown = shown(v)
    # What a new value shows can carry on from what the last one showed, like a bar that slides to its new length
    old isa Shown && v.shown.value isa SemanticUI && typeof(old.value) === typeof(v.shown.value) && Base.invokelatest(carry!, v.shown.value, old.value)
    v.said = lines_now(v)
    v.state = :made
  catch err
    # A file that didn't load is tried again when it's saved
    v.from === nothing && !isempty(v.file) && (BROKEN[v.file] = trouble(err))
    fault!(v, trouble(err))
  end
  v
end

"""
Write the lines of what the block of `v` made into the block, if they aren't
the lines that it has. With `typing`, writes that come one soon after another
are one step for ⌘Z. Nothing is written when the block's lines in the page
aren't the ones that this was made from: then it's made again from those.
"""
write!(v::FileBlock; typing=false) = begin
  v.wants = false
  (v.state == :made && v.said !== nothing) || return v
  b = editor(v).buf
  span = block_lines(b, v.lang, v.n)
  (span !== nothing && b.lines[span[1]+1:span[2]-1] == v.lines) || return v
  now = try
    lines_now(v)
  catch err
    return fault!(v, trouble(err))
  end
  (now === nothing || now == v.said) && return v
  v.said = v.lines = now
  # A value that shows as words has new words now
  Base.invokelatest(present, v.value) === nothing && (v.shown = shown(v))
  write_block!(v, v.lang, now; typing)
end

"The views of the blocks of the page of `e` that a file defines"
file_blocks(e) = FileBlock[node for (key, node) in e.nodes if node isa FileBlock && key[3] == e.buf.path]

"""
Write the lines of every block of the page that a file defines. Whatever
reads the page's text calls this first: a save, a copy, a page of HTML,
another page that takes the window.
"""
write_blocks!(e) = (foreach(write!, file_blocks(e)); e)

# What was made asks for its lines to be written, with UI.jl's `changed!`
onchanged(v::FileBlock, ev::Changed) = begin
  ev.now ? write!(v) : (v.wants = true; redraw_in!(v, 0))
  handled
end

block_tick!(v::FileBlock) = begin
  v.state == :get && return make!(v, now=true)
  # A repository that another block of the page asked about, and that you allowed there
  v.state == :ask && repository(v.source) in ALLOWED && return make!(v)
  reload!(v)
  v.state == :made || return v
  # The page shows the block's lines while the caret is in them, so they're written as the caret goes in
  b = editor(v).buf
  span = block_lines(b, v.lang, v.n)
  inside = span !== nothing && incode(b, span[1])
  inside && !v.inside && write!(v)
  v.inside = inside
  # A write that was asked for waits until the mouse lets go, so that ⌘Z takes back a whole drag
  v.wants && !held(v, Keys.mouse_left) && write!(v, typing=true)
  v
end

act!(v::FileBlock, action, w) = begin
  allow!(editor(v), repository(v.source))
  v.state = :wait
  make!(v)
  handled
end

describe(v::FileBlock) = begin
  v.state == :made && return Column(width(grow=grow), Alignment.Start, v.shown)
  repo = something(repository(v.source), v.source)
  if v.state == :ask
    return Column(block_look()...,
      Row(width(grow=grow), padding(12px, 16px), child_gap=12px, Alignment.Center,
        Box(width(grow=grow), Alignment.Start,
          Text("This block runs code from github.com/$repo. Run it only if you trust who wrote it.", size=13px, family=SANS, color=colours.dim, wrap=WrapMode.words)),
        block_button!(v, :allow, :allow, words="Run the code", bold=true)))
  end
  if v.state in (:wait, :get)
    # The words are drawn in one frame, and the repository comes in the next
    v.state = :get
    redraw_in!(v, 0)
    return Column(block_look()..., block_note("Getting github.com/$repo…"))
  end
  note(v.fault, colours.accent)
end

# --- front matter as a card ---------------------------------------------------------
#
# While the caret isn't in it, front matter shows as a card: a small FRONTMATTER
# heading, then each key with what it's set to. A click on the card puts the
# caret in the line that was clicked, and the lines show as they're written.

"Front matter, shown as a card"
@def mutable struct MatterCard <: SemanticUI
  rows::Vector{Tuple{Int,String,String}} = Tuple{Int,String,String}[]   # the line, the key and what it's set to
  size::px = 13px                                                       # of the text
end

"""
The top of an email, in place of the card of its front matter. It's a part of
the page with levels of its own. See "the top of an email".
"""
@def mutable struct EmailHead <: SemanticUI
  rows::Vector{Tuple{Int,String,String}} = Tuple{Int,String,String}[]   # the keys of the front matter: the line, the key and what it's set to
  size::px = 13px      # of the text
  wide::px = 0px       # how wide the page's text is
  path::String = ""    # the page's file. The top goes back to its highest level when another file shows.
  full::Bool = false   # it shows every field of the email's header
  fields::Vector{Pair{String,String}} = Pair{String,String}[]   # those fields, as the email's file has them
  read_for::Tuple{String,Float64} = ("", 0.0)                   # the file that they were read from, and when it was last changed
  folded::Any = nothing   # the fields cut into lines for the width they were cut for, and that width
end

"A key of front matter and what it's set to, in its card"
@def mutable struct MatterRow <: SemanticUI
  line::Int = 0
  key::String = ""
  value::String = ""
  keys::px = 0px    # how wide the widest key is, so that what each is set to starts in one place
  size::px = 13px
end

"""
The keys of the front matter that ends at line `t`, each with the line it's on and
what it's set to. A line that goes on from the one above, like an item of a list,
joins what that key is set to. A comment isn't shown.
"""
matter_rows(lines, t) = begin
  toml = rstrip(lines[1]) == "+++"
  key = toml ? r"^\s*((?:\"[^\"]*\"|'[^']*'|[\w.-])+)\s*=\s*(.*)$" : r"^([^:#\s-][^:#]*):(?:\s+(.*)|$)"
  rows = Tuple{Int,String,String}[]
  for i in 2:t-1
    text = rstrip(lines[i])
    (isempty(strip(text)) || startswith(lstrip(text), '#')) && continue
    m = match(key, text)
    if m !== nothing
      push!(rows, (i, String(m[1]), something(m[2], "")))
    elseif toml && startswith(lstrip(text), '[') && !isempty(rows) && !endswith(last(rows)[3], ',') && !endswith(last(rows)[3], '[')
      push!(rows, (i, String(strip(text)), ""))   # a [table] that starts a group of keys
    elseif isempty(rows)
      push!(rows, (i, "", String(strip(text))))
    else
      # An item of a list, or the next part of a value that goes over several lines
      at, k, v = pop!(rows)
      part = strip(replace(strip(text), r"^-\s+" => ""))
      push!(rows, (at, k, isempty(v) ? String(part) : endswith(v, '[') ? v * part : v * (startswith(text, r"\s*-\s") ? ", " : " ") * part))
    end
  end
  rows
end

# --- a cover picture ---------------------------------------------------------------------------
#
# A key `cover` in the front matter names a picture, as a picture's line does:
# a file, named from the page's folder, or an address on the web.
#
#     ---
#     title: Kitchen
#     cover: photos/kitchen.jpg
#     ---
#
# The picture goes across the top of the page. It's as wide as the page's text,
# a third as tall as that, and no taller than `COVER_MOST`. It fills that room:
# its middle shows, and what's over the edges of the room is cut off. The card
# of the front matter is under it, without the `cover` key. Front matter that
# has only a cover shows only the picture. A click on the picture selects the
# front matter, and ⌥-click shows its lines, where you change the cover. A
# cover that isn't a picture, or isn't there, shows nothing, and the card shows
# the key as it's written. A page as HTML has the picture at its top too.

const COVER_MOST = 260px   # how tall a cover can be
const COVER_GAP = 16px     # between the cover and the card under it

"The cover picture across the top of the page, with the card of the front matter under it, or with no card"
@def mutable struct CoverPicture <: SemanticUI
  key::String = ""    # of the picture, for an Image
  wide::px = 0px
  tall::px = 0px
  card::Any = nothing
end

"The key of the picture that the `cover` of the front matter names, or nothing. `rows` are the keys of the front matter."
cover_key(e, rows) = begin
  k = findfirst(r -> lowercase(r[2]) == "cover", rows)
  k === nothing && return nothing
  src = String(strip(rows[k][3], ['"', '\'', ' ']))
  isempty(src) && return nothing
  isremote(e.buf.path) && (src = something(remote_src(e, src), ""); isempty(src) && return nothing)
  path = startswith(src, r"https?://") ? fetched(e, src) : abspath(docdir(e), expanduser(src))
  path === nothing ? nothing : picture_key(path)
end

# The room at the top is empty, and `draw` paints the picture into it, as a gallery's square does
describe(c::CoverPicture) = begin
  picture = Box(fixed(c.wide), height(c.tall), radius(8px), background(colours.block), name="Cover")
  Column(width(grow=grow), Alignment.Start, child_gap=COVER_GAP, picture, (c.card === nothing ? () : (geometry(c.card),))...)
end

"The part of a picture `w` by `h` pixels that fills a room `wide` by `tall`: its middle, as wide or as tall as it is, whichever fills the room"
cover_part(w, h, wide, tall) = w / h > wide / tall ?
  ((w - h * wide / tall) / 2, 0.0, h * wide / tall, Float64(h)) :
  (0.0, (h - w * tall / wide) / 2, Float64(w), w * tall / wide)

draw(ctx, size, ui::ConcreteRect, c::CoverPicture) = begin
  image = try image_source(c.key) catch; nothing end
  image === nothing && return
  wide, tall = num(c.wide), num(c.tall)
  with_round_clip(ctx, ui.left, ui.top, px(wide), px(tall), 8px) do
    paint_picture(ctx, image.raw, cover_part(image.width, image.height, wide, tall), (num(ui.left), num(ui.top), wide, tall))
  end
end

cursor(::CoverPicture) = :arrow
onkey(c::CoverPicture, ev::KeyPress{Keys.mouse_left}) = click_page!(c, ev)

"The front matter that ends at line `t`, as a card, as the top of an email, or as what code from the startup page shows there. A `cover` key puts a picture over it."
matter_card(e, t) = begin
  rows = matter_rows(e.buf.lines, t)
  cover = cover_key(e, rows)
  cover === nothing || (rows = filter(r -> lowercase(r[2]) != "cover", rows))
  card = first_answer(MATTER_CARDS, e, rows)
  # A kind of folder can show the front matter of a page that it holds its own way, as a blog shows a book review's
  o = card === nothing ? text_object(e) : nothing
  o === nothing || (card = matter_view(e, o.parent, o, rows))
  if card === nothing
    # An email that came or went shows the top of an email in place of its keys. That top has levels of its own.
    card = email_shows(e, Dict(lowercase(k) => v for (_, k, v) in rows)) ? email_head!(e) : node!(MatterCard, e, :matter)
    card.rows = rows
    card.size = body(e).size * 0.76
  end
  if cover !== nothing
    c = node!(CoverPicture, e, :cover_picture)
    c.key, c.wide, c.tall = cover, e.width, min(e.width / 3, COVER_MOST)
    # Front matter with only a cover shows only the picture
    c.card = card isa MatterCard && isempty(rows) ? nothing : own!(node!(Document, e, :document), card)
    card = c
  end
  own!(node!(Document, e, :document), card)
  # Lay it out once to learn how tall it is
  concrete = describe(Column(fixed(e.width), Alignment.Start, geometry(card)), (e.width, 9999px))
  Live(card, concrete.height + 2LIVE_GAP)
end

describe(c::MatterCard) = begin
  s = c.size
  e = editor(c)
  # Code from the startup page can give the card another name, as a draft of an email has
  title = something(first_answer(MATTER_TITLES, e), "FRONTMATTER")
  keyface = Face(SANS, "Semibold", s, colours.dim, false)
  keys = maximum(r -> measure(keyface, r[2]), c.rows, init=0px)
  Column(width(grow=grow), Alignment.Start, padding(s, s * 0.7), child_gap=s * 0.4, radius(6px),
         border(1px, :solid, colours.line), background(colours.block), name="Front matter",
    # The heading has a little more room under it than the rows have between them
    Box(padding(0px, 0px, s * 0.2, 0px), label(title, s * 0.72, color=colours.dim, weight="Bold")),
    [MatterRow(line=at, key=k, value=v, keys=keys, size=s) for (at, k, v) in c.rows]...)
end

describe(r::MatterRow) = begin
  s, keys = r.size, r.keys
  Row(width(grow=grow), Alignment.Start, padding(0px, s * 0.15), child_gap=(keys > 0px ? s * 0.9 : 0px),
    (keys > 0px ? (Box(fixed(keys), label(r.key, s, color=colours.dim, weight="Semibold")),) : ())...,
    Box(width(grow=grow), Alignment.Start, Text(r.value, size=s, family=SANS, color=colours.ink, wrap=WrapMode.words)))
end

"""
The top of an email at its highest level: the subject as a title, then who
sent it with the date at the right, then who it's to. `said` is what the front
matter sets each key to.
"""
email_head(c::EmailHead, said) = begin
  s = c.size
  # Each person's name, or the address of one with no name
  people(key) = join((isempty(name) ? address : name for (name, address) in Mime.addresses(get(said, key, ""))), ", ")
  from = Mime.addresses(get(said, "from", ""))
  name, address = isempty(from) ? (get(said, "from", ""), "") : (first(from)[1], first(from)[2])
  isempty(name) && ((name, address) = (address, ""))
  subject = get(said, "subject", "")
  line(words) = Box(width(grow=grow), Alignment.Start, Text(words, size=s, family=SANS, color=colours.dim, wrap=WrapMode.words))
  high = s * 1.5   # a line of one size of text, with room for the tails of its letters
  Column(width(grow=grow), Alignment.Start, padding(0px, s * 0.2, s * 1.1, 0px), child_gap=s * 0.55, name="Email head",
         border(1px, :solid, colours.line)[:bottom],
    Box(width(grow=grow), Alignment.Start, padding(0px, 0px, s * 0.5, 0px),
      Text(isempty(subject) ? "No subject" : subject, size=s * 1.6, family=SANS, subfamily="Semibold", color=colours.ink, wrap=WrapMode.words)),
    # A line of text is as tall as its capitals, with the foot of its letters at its bottom. So the
    # inner Row, which puts each part at its bottom, puts the name, the address and the date on one line.
    # The address is cut at its sides only, so the tops of its tall letters show.
    Row(width(grow=grow), height(high),
      Row(width(grow=grow), Alignment.End, child_gap=s * 0.6,
        Box(label(name, s * 1.05, weight="Semibold")),
        Box(width(grow=grow), Alignment.Start, clip_x=true, label(address, s, color=colours.dim)),
        Box(label(get(said, "date", ""), s, color=colours.dim)))),
    (haskey(said, "to") ? (line("To " * people("to")),) : ())...,
    (haskey(said, "cc") ? (line("Cc " * people("cc")),) : ())...)
end

cursor(::Union{MatterCard,MatterRow}) = :arrow
onkey(c::Union{MatterCard,MatterRow}, ev::KeyPress{Keys.mouse_left}) = click_page!(c, ev)

"Put the caret at the end of line `i` of the front matter, so it shows as it's written"
edit_matter!(node, i) = begin
  e = editor(node)
  b = e.buf
  b.caret = b.anchor = (i, length(b.lines[i]))
  focus(e)
  touch!(e)
  handled
end


# --- the top of an email -----------------------------------------------------------
#
# An email that came or went shows the top of an email in place of the card of
# its front matter: its subject, who sent it and when, and who it's to. That
# top is a part of the page with two levels of its own. A level down, it shows
# every field of the email's header, like Received, Message-ID and
# DKIM-Signature, each with its value. A page that's an email but not an .eml
# file shows the keys of its front matter there.
#
# A click on the top gives it the keyboard, and a line goes round it. On a page
# that can change, the caret can also go onto it as a whole. The ladder in the
# top bar is then the top's: ⌘E, the ladder and the slider go between its two
# levels, and it keeps the keyboard. Esc, a click on the page, or a key that
# scrolls the page gives the keyboard back to the page. The top stays at its
# level until another file shows. On a page that can change, Return shows the
# front matter as it's written.

const HEAD_LEVELS = ("every field of the email's header", "the email's subject, sender and date")   # from the lower

"The top of the email that the page shows. It goes back to its highest level when another file shows."
email_head!(e) = begin
  h = node!(EmailHead, e, :email_head)
  h.path == e.buf.path || (h.path = e.buf.path; h.full = false)
  h.wide = e.width
  h
end

describe(h::EmailHead) = h.full ? whole_header(h) : email_head(h, Dict(lowercase(k) => v for (_, k, v) in h.rows))

"""
The fields of the email's header: those of its file, read again only when the
file changes. A page that's an email but not an .eml file has the keys of its
front matter, and so has a file whose header can't be read.
"""
header_fields!(h::EmailHead) = begin
  keys = [k => v for (_, k, v) in h.rows if !isempty(k)]
  Eml.isemail(h.path) || return keys
  now = (h.path, mtime(h.path))
  h.read_for == now || (h.fields = Eml.header_fields(h.path); h.read_for = now)
  isempty(h.fields) ? keys : h.fields
end

"""
`s` in lines no wider than `room` in `face`, joined with line breaks, for a
Text that breaks only there. Lines break at spaces. A word that's too wide for
a line of its own, like a DKIM signature, goes on from the line that it starts
on, when a quarter of that line or more is free. It breaks after its last
hyphen that fits, or between two characters when no hyphen fits. A line is as
wide as its characters added up.
"""
fold(s::AbstractString, face::Face, room) = begin
  wide(c::Char) = measure(face, string(c))
  space = wide(' ')
  # How many characters at the start of `word` fit in `free`: up to its last hyphen that fits, when one does
  fitting(word, free) = begin
    fits, hyphen, sofar = 0, 0, 0px
    for c in word
      sofar += wide(c)
      sofar > free && break
      fits += 1
      c == '-' && (hyphen = fits)
    end
    hyphen > 0 ? hyphen : fits
  end
  lines = String[]
  line, x, started = IOBuffer(), 0px, false
  for word in split(s)
    w = sum(wide, word, init=0px)
    if started && x + space + w <= room
      print(line, ' ', word)
      x += space + w
      continue
    end
    more = String(word)
    if started && w > room && room - x - space >= room / 4
      cut = fitting(more, room - x - space)
      cut > 0 && print(line, ' ', first(more, cut))
      more = String(chop(more, head=cut, tail=0))
      w = sum(wide, more, init=0px)
    end
    started && push!(lines, String(take!(line)))
    while w > room
      cut = max(fitting(more, room), 1)
      push!(lines, first(more, cut))
      more = String(chop(more, head=cut, tail=0))
      w = sum(wide, more, init=0px)
    end
    print(line, more)
    x, started = w, true
  end
  started && push!(lines, String(take!(line)))
  join(lines, '\n')
end

"""
The top of an email a level down: every field of the email's header, each
with its value, in a card like the card of front matter. The names of the
fields take no more than a third of the card, and a name or a value that's
too wide breaks onto more lines.
"""
whole_header(h::EmailHead) = begin
  s = h.size
  keyface = Face(SANS, "Semibold", s, colours.dim, false)
  face = Face(SANS, "", s, colours.ink, false)
  gap = s * 0.9
  inner = h.wide - 2s - 2px   # inside the card's line and the room at its sides
  folded = something(h.folded, ((), nothing))
  fields = header_fields!(h)
  if folded[2] != (h.wide, s, fields)
    keys = min(maximum(f -> measure(keyface, f[1]), fields, init=0px), inner / 3)
    room = max(inner - keys - gap, 40px) * 0.98   # a little room for the letters' widths that `fold` adds up
    rows = [(fold(k, keyface, keys), fold(v, face, room)) for (k, v) in fields]
    folded = h.folded = ((keys, rows), (h.wide, s, fields))
  end
  keys, rows = folded[1]
  lines(words, sub, colour) = Text(words, size=s, family=SANS, subfamily=sub, color=colour, wrap=WrapMode.newlines)
  Column(width(grow=grow), Alignment.Start, padding(s, s * 0.7), child_gap=s * 0.4, radius(6px),
         border(1px, :solid, colours.line), background(colours.block), name="Email header",
    # The heading has a little more room under it than the rows have between them
    Box(padding(0px, 0px, s * 0.2, 0px), label("HEADER", s * 0.72, color=colours.dim, weight="Bold")),
    (Row(width(grow=grow), Alignment.Start, padding(0px, s * 0.15), child_gap=gap,
       Box(fixed(keys), Alignment.Start, lines(k, "Semibold", colours.dim)),
       Box(width(grow=grow), Alignment.Start, lines(v, "", colours.ink)))
     for (k, v) in rows)...)
end

levels(::EmailHead) = HEAD_LEVELS
level(h::EmailHead) = h.full ? 1 : 2
level!(h::EmailHead, i::Int) = (h.full = i == 1; h)

"""
What shows the page's front matter, like the top of an email, while the top
bar asks it for its levels: while it or a part of it has the keyboard, or
while the caret is on it as a whole. Otherwise it's nothing. One with no
levels of its own, like the card of front matter, is never in charge: the
page answers for it, as it does for any part with none. So code from the
startup page can show front matter as a part with levels of its own: see
`MATTER_CARDS`.
"""
head_in_charge(e) = begin
  w = window_of(e)
  (w === nothing || isempty(e.layout)) && return nothing
  it = e.layout[1]
  (it.content isa Live && it.first == 1 && it.last == front_matter(e.buf.lines)) || return nothing
  h = it.content.node
  # A part with none passes the question up to the window. If the window asked that part again, the two would ask each other without end.
  own_levels(h) || return nothing
  (part_of(w.focus, h) || ((w.focus === e || w.focus === input(e)) && picked(e.buf) == (it.first, it.last))) ? h : nothing
end

"True when `node` has levels of its own: its type has a method of `levels`, and not only the one that passes the question on to the part that it's in"
own_levels(node) = which(levels, Tuple{typeof(node)}) !== which(levels, Tuple{SemanticUI})

"True when `node` is `part`, or is in it"
part_of(node, part) = begin
  while node isa SemanticUI
    node === part && return true
    node = node.parent
  end
  false
end

cursor(::EmailHead) = :arrow
onkey(h::EmailHead, ::KeyPress{Keys.mouse_left}) = (focus(h); handled)
# On a page that can change, Return shows the front matter as it's written, as it does for any front matter
onkey(h::EmailHead, ev::KeyPress{Keys.enter}) = unmodified(ev) ? (caretless(editor(h).buf) ? nothing : edit_matter!(h, isempty(h.rows) ? 1 : first(h.rows)[1])) : nothing
# A key that isn't held with ⌘ or ⌃, like Space or ↓, gives the keyboard back to the page, and the page takes the key.
# So the keys that scroll an email still scroll it. A shortcut like ⌘E goes on to the window with the top keeping the keyboard.
onkey(h::EmailHead, ev::KeyPress{K}) where K = begin
  w = ev.window
  (K in (Keys.cmd, Keys.ctrl, Keys.opt, Keys.shft, Keys.fn, Keys.capslock, Keys.escape) || Keys.cmd in w.keys || Keys.ctrl in w.keys) && return nothing
  focus(editor(h))
  nothing
end

# The code of a live block can load methods that are newer than the frame that
# ran it, so the node is described with the newest methods there are
geometry(node::SemanticUI) = Base.invokelatest(convert, GeometricUI, node)
geometry(node::GeometricUI) = detach!(node)

"True when the page shows a CSV file as a table"
sheet_page(b::Buffer) = b.view == :file && lowercase(splitext(b.path)[2]) in TABLES

"How far under the top bar the page starts. A CSV file's table and a JSON file's tree start nearer than the text of a page does."
page_top(e) = sheet_page(e.buf) || (e.buf.view == :file && json_page(e.buf)) ? SHEET_ABOVE : PAGE_TOP

"How wide the page's text is in the window"
text_width(e) = begin
  w, _ = window_size(e)
  # While the sidebar slides, the text keeps the width it has beside the
  # sidebar, so it doesn't wrap again on each frame
  # The numbers of a file's lines have room on the left of the text
  # The lines of a block that fill the window have no sidebar beside them
  alone = lowered(e) !== nothing
  room = w - ((e.panel || sliding(e)) && !alone ? panel_w(e) : 0px) - 2PAGE_X - gutter(e)
  # A file of code or of text takes all the room that the window has, and so do a CSV file's table and
  # the lines of a block that fill the window. A page is no wider than the settings say. A page of a blog is
  # as wide as its site's text, for as many words to a line. A page with comments leaves room for them at its right.
  numbered(e.buf) || alone || json_page(e.buf) || bytes_page(e.buf) || sheet_page(e.buf) || own_page(e) ? max(room, 240px) :
    clamp(room - comment_room(e), 240px, e.look == :site ? SITE_MEASURE * TEXT_SIZE * e.zoom : e.widest * e.zoom)
end

"""
How far the left edge of the page's text is from the left edge of the window.
A page's text is in the middle of the space beside the file panel. A file with
numbered lines starts at the left of that space, after its numbers, unless it's
scrolled to the right.
"""
text_left(e) = begin
  w, _ = window_size(e)
  side = lowered(e) === nothing ? panel_w(e) * opened(e) : 0px
  # The lines of a file's bytes start at the left too, and scroll to the right as numbered lines do
  numbered(e.buf) || bytes_page(e.buf) ? side + PAGE_X + gutter(e) - sideways(e) : side + text_inset(e, w - side)
end

"""
How far the left edge of a page's text is from the left edge of `space`, the
room beside the file panel. The text is in the middle of it. When the page's
comments at its right don't fit in the margin there, the text and the comments
are in the middle together, so the text is to the left of the middle.
"""
text_inset(e, space) = begin
  extra = comment_room(e)
  extra == 0px && return max(PAGE_X, (space - e.width) / 2)
  before = comment_balance(e, space)
  max(PAGE_X, (space - e.width - extra - before) / 2) + before
end

# A page of Markdown is laid out again in each frame, since what a block shows
# can change with no change to the text. A line of plain text is different: it
# only changes when its text does. So each such line is kept by its number,
# with what it was laid out from, and the next frame takes it as it is when
# the line still has that text and is still the same kind of line. A long
# page then costs little more in a frame than a short one. The lines are kept
# with the other layouts, in `e.flows`, so what empties those empties them too.

"A line of plain text as a frame laid it out: its text, what kind of line it was, whether its markup showed, and its layout with its height"
struct PlainLine
  text::String
  line::Line
  raw::Bool
  flow::Flow
  tall::px
end

"The kinds of line that are laid out from their own text alone. A to-do item is left out: on a day before today its box shows that day's tick."
const PLAIN_KINDS = (Kind.blank, Kind.paragraph, Kind.heading, Kind.bullet, Kind.ordered, Kind.blockquote, Kind.code, Kind.rule)

"Keep line `i` as it was laid out in this frame, for the next frame, when its layout came from its text alone"
keep_plain!(kept::Vector{Union{Nothing,PlainLine}}, b::Buffer, i::Int, line::Line, flow::Flow, tall::px) = begin
  text = b.lines[i]
  # A picture, what inline code made, and a footnote's number each come from more than the line's text
  # ... and a line with a comment can take no room, which isn't a layout of its own
  # ... and a line that shows the markup of one of its runs goes with where the caret is in it
  plain = line.kind in PLAIN_KINDS && !occursin("![", text) && !occursin(INLINE, text) && !occursin("[^", text) && !occursin("%%", text) &&
          raw_part(b, i) === nothing
  kept[i] = plain ? PlainLine(text, line, flow.raw, flow, tall) : nothing
end

"Work out what the page shows and how tall each part is, for text that's `width` wide"
layout!(e, width=text_width(e)) = begin
  b = e.buf
  unlist!(node!(Document, e, :document))   # the document's children are the parts that this layout gives it
  # The page is written as rich text or as plain text, as the switch in the top bar says. After a
  # change, the caret's place is looked at afresh.
  shows = e.plain && b.view == :markdown
  b.plain == shows || (b.plain = shows; b.stood = nothing)
  stand!(b)
  ks = kinds(b)
  width == e.width || (e.width = width; empty!(e.flows))
  columns = page_columns!(e)   # the blocks that show side by side after a `columns` block, or nothing when the page has none
  # A file that's only shown is one viewer, or lines of text that are laid out once and kept
  b.view == :file && return e.layout = [file_item(e, b)]
  readonly(b) && return e.layout = file_lines(e, b)
  # A file of code is lines of text too, which a key can change
  b.view == :code && columns === nothing && lowered(e) === nothing && return e.layout = slide_items(e, file_lines(e, b))
  items = Item[]
  # These three have their types written out. What a block or a table gives has no type that Julia knows before it
  # runs, and without these the loop below would look up the type of each of them for every line of the page.
  top::px = 0px
  i::Int = 1
  n::Int = length(b.lines)
  # The lines of a block that went down a level from the window it filled show by themselves, and so do
  # the lines of a part of this page that another page shows
  span = hosted(e) === nothing ? lowered(e) : e.nodes[:span]
  span === nothing || ((i, n) = span)
  # The email as it was sent, with the lines that it stands for, or nothing when the page shows its lines
  sent = span === nothing ? sent_email(e) : nothing
  sent === nothing || (lines = sent_lines(e); sent = lines === nothing ? nothing : (sent, lines))
  plans = 0   # how many takeoff blocks there have been so far
  schedules = 0   # and how many schedules
  parts = 0   # and how many lines that show a part of another page
  seen = Dict{String,Int}()   # and how many blocks in each of the languages of `BLOCKS`
  # The lines of plain text as the frame before laid them out: see `PlainLine`. A page in columns, an email as it
  # was sent, and a page of emails have lines that are laid out another way.
  kept = columns === nothing && sent === nothing && !Eml.isemail(b.path) ?
    get!(() -> Union{Nothing,PlainLine}[], e.flows, (:plain, b.path))::Vector{Union{Nothing,PlainLine}} : nothing
  # A page that has more lines than it had has nothing kept for the new ones
  kept === nothing || length(kept) == length(b.lines) || (had = length(kept); resize!(kept, length(b.lines)); fill!(view(kept, had+1:length(kept)), nothing))
  while i <= n
    # In a column, the page's text is as wide as the column, and each column starts level with the first
    columns === nothing || (top = column_turn!(columns, e, items, i, top))
    if kept !== nothing
      was = kept[i]
      if was !== nothing && pointer(was.text) == pointer(b.lines[i]) && was.line === ks[i] && was.raw == israw(b, i) && raw_part(b, i) === nothing
        push!(items, Item(i, i, top, was.tall, was.flow))
        top += was.tall
        i += 1
        continue
      end
    end
    j = i
    if ks[i].kind == Kind.table
      while j < n && ks[j+1].kind == Kind.table
        j += 1
      end
    end
    # Front matter shows as a card, unless the caret is in it
    if i == 1 && ks[1].kind == Kind.fence && ks[1].lang in (MATTER, TOML_MATTER) && !incode(b, 1)
      t = front_matter(b.lines)
      if t > 1
        content = matter_card(e, t)
        push!(items, Item(1, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A comment on lines of its own takes no room, unless the caret is in it. Nor do the empty lines after it that
    # `comment_fold` counts, unless the caret is on one of them, which then shows.
    if ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang == COMMENT && !incode(b, i)
      t = codeblock(b, i)[2]
      fold = comment_fold(b, i)[2]
      (caretless(b) || !(t < b.caret[1] <= fold || t < b.anchor[1] <= fold)) && (t = fold)
      push!(items, flat(e, Item(i, t, top, 0px, nothing)))
      i = t + 1
      continue
    end
    # An email shows as it was sent, in place of the lines that were made of it, once its pictures are there
    if sent !== nothing && i == sent[2][1]
      content = sent_item(e, sent[1])
      push!(items, Item(i, sent[2][2], top, content.tall, content))
      top += content.tall
      i = sent[2][2] + 1
      continue
    end
    # A `takeoff` code block shows its plan and its measures, unless the caret is in it
    if ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang == TAKEOFF
      plans += 1   # each takeoff keeps its view by its place among the page's takeoffs
      t = codeblock(b, i)[2]
      if !incode(b, i) && t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        content = takeoff_item(e, i, t, plans)
        push!(items, Item(i, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A `schedule` code block shows the page's tasks on a line of days, unless the caret is in it
    if ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang == SCHEDULE
      schedules += 1
      t = codeblock(b, i)[2]
      if !incode(b, i) && t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        content = schedule_item(e, i, t, schedules)
        push!(items, Item(i, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A block in one of the languages of `BLOCKS` shows as its component, unless the caret is in it
    if ks[i].kind == Kind.fence && ks[i].level == 0 && haskey(BLOCKS, ks[i].lang)
      lang = ks[i].lang
      seen[lang] = get(seen, lang, 0) + 1   # each one keeps its view by its place among the page's blocks in its language
      t = codeblock(b, i)[2]
      if !incode(b, i) && t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        content = block_item(e, lang, i, t, seen[lang])
        push!(items, Item(i, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A block in a language that a file defines shows what the file's function makes of it, unless the caret is in it
    if ks[i].kind == Kind.fence && ks[i].level == 0 && !isempty(ks[i].lang) && !known_lang(ks[i].lang)
      lang = ks[i].lang
      seen[lang] = get(seen, lang, 0) + 1   # every block in the language counts, as `block_lines` counts them
      source = block_source(b, i)
      t = codeblock(b, i)[2]
      if source !== nothing && !incode(b, i) && t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        content = file_block_item(e, lang, source, i, t, seen[lang])
        push!(items, Item(i, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A `ui` code block shows what its code makes, unless the caret is in it
    if ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang == LIVE && !incode(b, i)
      t = codeblock(b, i)[2]
      if t > i && ks[t].kind == Kind.fence && ks[t].level == 1
        content = live(e, join(b.lines[i+1:t-1], "\n"))
        push!(items, Item(i, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A `mermaid` code block shows its diagram, unless the caret is in it. Code that can't be drawn as a diagram shows as code.
    if ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang == DIAGRAM && !incode(b, i)
      t = codeblock(b, i)[2]
      content = t > i && ks[t].kind == Kind.fence && ks[t].level == 1 ? diagram(e, join(b.lines[i+1:t-1], "\n")) : nothing
      if content !== nothing
        push!(items, Item(i, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A formula between two lines of $$, or in a `math` code block, shows as it's set, unless the caret is in it
    if ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang == MATH && !incode(b, i)
      t = codeblock(b, i)[2]
      content = t > i && ks[t].kind == Kind.fence && ks[t].level == 1 ? equation_item(e, join(b.lines[i+1:t-1], "\n")) : nothing
      if content !== nothing
        push!(items, Item(i, t, top, content.tall, content))
        top += content.tall
        i = t + 1
        continue
      end
    end
    # A line that holds only a formula between $$ and $$ shows the formula, unless the caret is in the line
    if ks[i].kind == Kind.paragraph && !israw(b, i) && maths_line(b, i)
      content = equation_item(e, maths_text(b.lines[i]))
      if content !== nothing
        push!(items, Item(i, i, top, content.tall, content))
        top += content.tall
        i += 1
        continue
      end
    end
    # A `sheet` code block is drawn as a sheet, and a `spreadsheet` one as a spreadsheet, unless the caret is on its first or last line
    if ks[i].kind == Kind.fence && ks[i].level == 0 && ks[i].lang in (SHEET, SPREADSHEET)
      run = drawn(b, i, ks[i].lang)
      if run !== nothing
        content = ks[i].lang == SHEET ? sheetgrid(e, run...) : spreadgrid(e, run...)
        push!(items, Item(i, run[2], top, tall(content), content))
        top += tall(content)
        i = run[2] + 1
        continue
      end
    end
    # The links at the end of an email to the files that came with it show as file icons, at both of its levels
    if ks[i].kind == Kind.paragraph && !israw(b, i) && Eml.isemail(b.path)
      content = attached_item(e, i)
      if content !== nothing
        push!(items, Item(i, content.node.to, top, content.tall, content))
        top += content.tall
        i = content.node.to + 1
        continue
      end
    end
    # A line that holds only a link like ![[Ideas#Plans]] shows that part of the other page, unless the caret is in the line
    if ks[i].kind == Kind.paragraph && !israw(b, i) && transcludes(b, i)
      parts += 1   # each one keeps its view by its place among the page's lines like it
      content = transclusion_item(e, i, parts)
      push!(items, Item(i, i, top, content.tall, content))
      top += content.tall
      i += 1
      continue
    end
    # A line that holds only a comment takes no room either, unless the caret is on it
    if ks[i].kind == Kind.paragraph && !alone(b, i) && comment_only(b.lines[i])
      t = something(comment_fold(b, i), (i, i))[2]
      (caretless(b) || !(i < b.caret[1] <= t || i < b.anchor[1] <= t)) || (t = i)
      push!(items, flat(e, Item(i, t, top, 0px, nothing)))
      i = t + 1
      continue
    end
    # A line that holds only a picture shows the picture, unless the caret is on the line
    if ks[i].kind == Kind.paragraph && !israw(b, i) && occursin("![", b.lines[i])
      content = picture_item(e, i)
      if content !== nothing
        push!(items, Item(i, i, top, content.tall, content))
        top += content.tall
        i += 1
        continue
      end
    end
    # A table needs its line of dashes. It shows as plain lines while the caret is on that line.
    if j > i && isdivider(b.lines[i+1]) && !israw(b, i + 1)
      content = grid(e, i, j)
      push!(items, Item(i, j, top, tall(content), content))
      top += tall(content)
      i = j + 1
    else
      content = flow(e, i)::Flow
      high = tall(content)
      push!(items, Item(i, i, top, high, content))
      kept === nothing || keep_plain!(kept, b, i, ks[i], content, high)
      top += high
      i += 1
    end
  end
  columns === nothing || column_turn!(columns, e, items, n + 1, top)   # the page ends in a column
  e.layout = slide_items(e, items)   # while the page shows as slides, only the items of one slide
end

"The item that shows line `i`"
item(e, i::Int) = e.layout[something(findfirst(it -> it.first <= i <= it.last, e.layout), length(e.layout))]

"Scroll so the caret is on screen"
reveal!(e) = begin
  e.buf.view == :file && return   # a viewer has no caret
  it = item(e, e.buf.caret[1])
  top, bottom = it.top, it.top + it.tall
  if it.content isa Flow
    k, x = spot(it.content, e.buf.caret[2])
    top = it.top + line_top(it.content, k)
    bottom = top + it.content.lines[k].high
    # A long line that doesn't wrap scrolls sideways to show the caret, with a little of the line on each side of it
    if !wraps(e)
      b = e.buf
      x < b.across + SIDE_ROOM && (b.across = x - SIDE_ROOM)
      x > b.across + e.width - SIDE_ROOM && (b.across = x - e.width + SIDE_ROOM)
      scroll_sideways!(e, 0px)
    end
  elseif it.content isa Sheet
    r = clamp(e.buf.caret[1] - it.first, 1, length(it.content.rows))
    top = it.top + row_top(it.content, r)
    bottom = top + it.content.heights[r]
  end
  scroll_into_view!(e.scroll, PAGE_TOP + top - 30px, PAGE_TOP + bottom + 40px)
end

# --- drawing the text -----------------------------------------------------------------

"The box of a to-do item: empty, or filled and ticked when the item is done"
todo_box(seg::Seg) = begin
  side = px(round(num(seg.face.size) * 0.82))
  box = seg.text == TODO_DONE ?
    Box(fixed(side), height(side), radius(side * 0.22), Alignment.Center, justify=Alignment.Center, background(colours.accent),
        Icon("check", size=side * 0.9, color=colours.bg)) :
    Box(fixed(side), height(side), radius(side * 0.22), border(1.5px, :solid, colours.marker))
  Box(fixed(seg.w), Alignment.Start, box)
end

describe(seg::Seg) = begin
  # What inline code made is drawn in place of the code
  seg.node === nothing || return Box(fixed(seg.w), Alignment.Start, geometry(seg.node.node))
  isbox(seg) && return todo_box(seg)
  f = seg.face
  # A character that the font lacks, like the raised minus of yr⁻¹ in Charter, is in a font that has it
  t = hasall(f, seg.text) ? Text(seg.text, size=f.size, family=f.family, subfamily=f.style, color=f.color, wrap=WrapMode.none) :
                            Row(Alignment.Start, spared(seg.text, f)...)
  # The number of a footnote is at the top of a box as tall as the text beside it, so it sits high in the line
  seg.atomic && startswith(seg.link, '^') && !endswith(seg.text, ' ') && return Box(fixed(seg.w), height(f.size * 1.9), Alignment.Start, t)
  # ==Words== have a highlighter's colour behind them
  f.highlit && !f.chip && return Box(fixed(seg.w), Alignment.Start, radius(2px), background(highlighter()), t)
  # A Text on its own would take a share of the spare room in its row
  f.chip || return Box(fixed(seg.w), Alignment.Start, t)
  isempty(f.lang) || (t = Row(Alignment.Start, [part for tok in tokens(seg.text, f.lang) for part in coloured(tok, f)]...))
  Box(fixed(seg.w), height(f.size * 1.5), padding(CHIP_X, 0px), radius(4px), background(colours.chip), border(1px, :solid, colours.chip_line), t)
end

"""
One part of a line of code in a chip, in the colour of its kind, as the parts
of a row. Each is as wide as its text measures, so the caret lines up with it.
"""
coloured(tok, f::Face) =
  spared(tok.text, Face(f, color=tok.kind == :plain ? f.color : getfield(colours, tok.kind), style=tok.kind == :comment ? codeslant() : f.style))

"The lines of a Flow, as rows of text. `edge` is the width of a border on its left."
rows(f::Flow, edge=0px) =
  [Row(width(grow=grow), height(vl.high), padding(0px, 0px, 0px, vl.x - edge), clip=true, map(describe, vl.segs)...) for vl in f.lines]

describe(e::Editor, it::Item) = gone_under(e, it, describe(e, it, it.content))

describe(e::Editor, it::Item, f::Flow) = begin
  f = in_colour(e, it, f)   # a line of a file gets the colours of its code here
  k = f.kind
  if k == Kind.rule && !f.raw
    return Box(width(grow=grow), height(tall(f)), Box(width(grow=grow), height(1px), background(colours.line)))
  end
  edge = k == Kind.blockquote ? 3px : 0px
  col = Column(width(grow=grow), Alignment.Start, padding(f.above, 0px, f.below, 0px), rows(f, edge)...)
  if (k == Kind.code || k == Kind.fence) && !(1 <= it.first <= length(e.buf.lines) && kinds(e.buf)[it.first].lang == COMMENT)
    col.background = background(colours.block)
  elseif k == Kind.blockquote
    # A callout has its kind's colour down its left, and a little of that colour behind it
    kind = 1 <= it.first <= length(e.buf.lines) ? callout(kinds(e.buf)[it.first]) : ""
    col.border = border(edge, :solid, isempty(kind) ? colours.line : callout_colour(kind))[:left]
    isempty(kind) || (col.background = background(callout_tint(kind)))
  end
  col
end

describe(e::Editor, it::Item, g::Grid) = begin
  isspread(g) && return spreadsheet(e, it, g)
  line = border(1px, :solid, colours.line; between=true)
  table = Column(width(grow=grow), Alignment.Start, line, name="Table",
    [Row(width(grow=grow), height(g.heights[r]), Alignment.Start, line[:between],
         background(r == 1 ? colours.head : iseven(r) ? colours.bg : colours.stripe),
       [Column(fixed(g.widths[c]), height(grow=grow), Alignment.Start, justify=Alignment.Center, rows(g.flows[r][c])...)
        for c in eachindex(g.widths)]...)
     for r in eachindex(g.rows)]...)
  Box(width(grow=grow), padding(0px, TABLE_GAP), table)
end

describe(e::Editor, it::Item, l::Live) = begin
  # In a part of this page that another page shows, a live block is only shown: a cover over it takes its clicks
  inner = hosted(e) === nothing || l.node isa Transclusion ? geometry(l.node) :
    Stack(width(grow=grow), Alignment.Start, geometry(l.node), live_cover(e, it))
  Box(width(grow=grow), height(l.tall), Alignment.Start, padding(0px, LIVE_GAP), inner)
end

"The kind of block that an item is part of, or nothing for a blank line"
blocktype(it::Item) = begin
  c = it.content
  c isa Grid && return Table
  c isa Sheet && return SheetBlock
  c isa Live ? LiveBlock : blocktype(c.kind)
end

blocktype(k::Kind) =
  k == Kind.paragraph ? Paragraph : k == Kind.heading ? Heading : k in (Kind.bullet, Kind.ordered, Kind.todo) ? List :
  k == Kind.blockquote ? Quote : k in (Kind.code, Kind.fence) ? CodeBlock : k == Kind.table ? Table :
  k == Kind.rule ? Rule : nothing

"The kind of block that line `i` is in. The keys that edit the text do different things in different blocks."
block(b::Buffer, i::Int) = blocktype(kinds(b)[i].kind)

"The items as the nodes of the document: one for each paragraph, list, table and so on"
blocks(d::Document, items) = begin
  ks = kinds(editor(d).buf)
  out, group, T = Any[], Item[], nothing
  close() = begin
    isempty(group) && return
    T === nothing ? append!(out, group) : push!(out, own!(d, T(first=group[1].first, last=group[end].last, items=copy(group))))
    empty!(group)
  end
  for it in items
    U = blocktype(it)
    # A heading, a rule, a table and a live block each stand alone, and a ``` line that opens a block starts a new one
    alone = U in (Heading, Rule, LiveBlock, SheetBlock) || it.content isa Grid || (U === CodeBlock && ks[it.first].kind == Kind.fence && ks[it.first].level == 0)
    (U !== T || alone) && close()
    T = U
    push!(group, it)
  end
  close()
  out
end

describe(b::Block) = Column(width(grow=grow), Alignment.Start, [describe(editor(b), it) for it in b.items]...)

describe(d::Document) = begin
  e = editor(d)
  items = e.layout
  total = isempty(items) ? 0px : lowest(e, items)
  _, h = window_size(e)
  # Only the lines on screen, and a few either side, are built
  from, to = e.scroll.offset - PAGE_TOP - 200px, e.scroll.offset + h + 200px
  lo = something(findfirst(it -> it.top + it.tall >= from, items), length(items))
  hi = something(findlast(it -> it.top <= to, items), lo)
  # A part of this page that another page shows is built whole. That page's own scroll says what's on screen.
  hosted(e) === nothing || ((lo, hi) = (1, length(items)))
  lo, hi = whole_groups(e, items, lo, hi)   # a group of columns is built whole
  e.shown = lo:hi
  # Each row of text cuts off what's past its end, so long lines that don't wrap need a page as wide as the longest
  Column(fixed(wraps(e) ? e.width : max(e.width, e.reach + SIDE_ROOM)), Alignment.Start, name="Document",
    gone_over(e, items, lo)...,
    page_parts(d, e, items[lo:hi])...,
    spacer(total - lowest(e, view(items, lo:hi))))
end

# With ⌘ and no other key held, a click on a link opens it, so the mouse shows a hand there. In a page
# that's never changed, a click on a link opens it with no key held.
cursor(d::Document) = begin
  e = editor(d)
  e.buf.view == :file && return :arrow   # a viewer has no text to select
  slideshow(e) === nothing || return slide_cursor(e)   # nor has a slide
  w = window_of(e)
  w === nothing && return :ibeam
  # A click on a to-do item's box ticks it
  todo_at(e, w.mouse) === nothing || return :hand
  # A drag on what a number comes to changes the number
  (haskey(e.nodes, :scrub) || scrub_at(e, w.mouse) !== nothing) && return :resize_x
  # With ⌘ held, a click on a name of Julia code goes to where the name is defined. Julia compiles definition only when ⌘ is first held.
  # ⌘ with another key held, like ⇧ or ⌃, does neither, so the mouse isn't a hand.
  cmd = only_held(w, Keys.cmd)
  cmd && link_at(e, w.mouse) === nothing && Base.invokelatest(definition, e, locate(e, w.mouse)) !== nothing && return :hand
  (cmd && link_at(e, w.mouse) !== nothing) || (e.buf.fixed && unmodified(w) && link_on(e, w.mouse) !== nothing) ? :hand : :ibeam
end

"""
The room under the last line of the page. A code file scrolls on until its last
lines are at the top of the window, so a box that opens under them has room to
show.
"""
page_bottom(e) = numbered(e.buf) ? max(PAGE_BOTTOM, e.scroll.viewport - CODE_END) : PAGE_BOTTOM

describe(p::Page) = begin
  e = editor(p)
  nofile(e) && return nofile_view(e)
  # A kind of folder or of file can cover the page's whole space, as a desktop does with its wallpaper
  cover = page_cover(e)
  cover === nothing || return cover
  # An HTML file at its highest level covers it with the page that its HTML makes, as a browser's window would show it
  html_shown(e) && return Box(width(grow=grow), height(grow=grow), Alignment.Start, html_part(e))
  # A model's file covers it with the model, which is a component, so it gets a live block's colours and text size
  model = model_part(e)
  model === nothing || return with_theme(() -> Box(width(grow=grow), height(grow=grow), Alignment.Start, model), component_theme(e.zoom))
  # A picture and a PDF file fit it, and can be made bigger and moved
  shown = file_zoom(e)
  shown === nothing || return Box(width(grow=grow), height(grow=grow), Alignment.Start, shown)
  # A video has all of it, with black round its picture and its controls over the foot of the picture, as when it fills a
  # screen. While it does fill the screen, it's there and not here.
  video = video_part(e)
  if video !== nothing
    zoomed_node(e, video) && return Box(width(grow=grow), height(grow=grow), background(RGBA(0, 0, 0, 1)))
    video.screen, video.height = true, page_room(e)[2]
    return with_theme(() -> Box(width(grow=grow), height(grow=grow), Alignment.Start, background(RGBA(0, 0, 0, 1)), video), component_theme(e.zoom))
  end
  # Long lines that don't wrap go on to the right edge of the window. The text moves left as the page
  # scrolls sideways. None of it shows past the edges of the page, and the numbers of the lines go over it.
  # A kind of folder can show something under the text of each page that it holds
  foot = page_foot(e)
  page = wraps(e) ?
    Row(width(grow=grow), Alignment.Start, justify=numbered(e.buf) ? Alignment.Start : Alignment.Center,
        padding(page_top(e), PAGE_X, page_bottom(e), PAGE_X + gutter(e)),
      with_comments(e, foot === nothing ? node!(Document, e, :document) : Column(Alignment.Start, node!(Document, e, :document), foot))) :
    Row(width(grow=grow), Alignment.Start, padding(page_top(e), 0px, page_bottom(e), PAGE_X + gutter(e)), clip_x=true,
      Box(Alignment.Start, offset_x=-sideways(e), node!(Document, e, :document)))
  reuse!(e.scroll, guide_under(e, page))
end

"What the page shows in a window with no file: the keys that open a file and that close the window"
nofile_view(e) = begin
  open_keys, close_keys = strip(hint(e, :open)), strip(hint(e, :close))
  Box(width(grow=grow), height(grow=grow),
    Column(child_gap=8px,
      Box(label("No file is open", 15px, color=colours.dim)),
      (isempty(open_keys) ? () : (Box(label("$open_keys finds a file", 13px, color=colours.faint)),))...,
      (isempty(close_keys) ? () : (Box(label("$close_keys closes the window", 13px, color=colours.faint)),))...))
end

"""
Put a faint line down a file of code, under the text of `page`, after the
number of characters that the settings page chooses. It moves with the text
when the page scrolls sideways.
"""
guide_under(e, page) = begin
  (e.guide > 0 && numbered(e.buf)) || return page
  x = PAGE_X + gutter(e) + measure(face(e, Line(Kind.code, 0, 0, "")), "0") * e.guide - sideways(e)
  Stack(width(grow=grow), Alignment.Start,
    Box(fixed(1px), height(grow=grow), background(colours.line), offset_x=x),
    page)
end

"The part of line `i` that's selected, as columns, and whether the selection goes on past it"
selected(b::Buffer, i::Int) = begin
  lo, hi = selection(b)
  (lo[1] <= i <= hi[1] && lo != hi) || return nothing
  (i == lo[1] ? lo[2] : 0, i == hi[1] ? hi[2] : length(b.lines[i]), i < hi[1])
end

const Rect = NTuple{4,Float64}   # left, top, right and bottom, in px

"""
The boxes that cover the selected part of each line of `f`, whose top left
corner is at (x, y). The first and last boxes take in the space above and below
the lines, so the boxes of one line of the document meet those of the next.
With `margin`, a box that starts at the start of its line also takes in the
space to the left of the text, like the inset of a code block. That's for a
line that the selection came into from the line above: it keeps the left edge
of the selection straight from one kind of line to the next. The line that the
selection starts in has no `margin`, so its box starts where its text does. A
selection that's all in one code block has no `margin` on any line. See `within_code`.
"""
marks(f::Flow, x, y, (from, to, more); margin=true, edge=0px) = begin
  out = Rect[]
  n = length(f.lines)
  for (k, vl) in enumerate(f.lines)
    (from <= vl.to && to >= vl.from) || continue
    # `edge` is the left edge of the line's column of the page, where the space to the left of its text starts
    # A selection from the end of inline code starts after its last words, which can start the line
    starts = from > vl.from || (from == vl.from && !isempty(vl.segs) && later_word(first(vl.segs)))
    x1 = starts ? xcol(vl, from) : margin ? edge : vl.x
    x2 = xcol(vl, min(to, vl.to))
    # A little extra shows that the end of the line is selected too
    (to > vl.to || (more && k == n)) && (x2 += 7px)
    # A line with none of its text selected has no box, not even over its margin
    x2 > max(x1, vl.x) || continue
    top = k == 1 ? 0px : line_top(f, k)
    bottom = line_top(f, k) + vl.high + (k == n ? f.below : 0px)
    push!(out, (num(x + x1), num(y + top), num(x + x2), num(y + bottom)))
  end
  out
end

const SELECTION_RADIUS = 4.0

"""
Fill the selection. Boxes that sit on top of each other are joined into one
shape, and every corner of that shape is rounded, the ones that point in as
well as the ones that point out.
"""
fill_selection(ctx, rects::Vector{Rect}) = begin
  isempty(rects) && return
  paint = Skia.sk_paint_new()
  Skia.sk_paint_set_antialias(paint, true)
  Skia.sk_paint_set_color(paint, sk_color(colours.select))
  from = 1
  for i in 2:length(rects)+1
    # A box joins the one above it when they touch and share some width
    joined = i <= length(rects) && abs(rects[i][2] - rects[i-1][4]) < 1 &&
             rects[i][1] < rects[i-1][3] && rects[i][3] > rects[i-1][1]
    joined && continue
    outline = rounded(corners(rects[from:i-1]), SELECTION_RADIUS)
    Skia.sk_canvas_draw_path(ctx, outline, paint)
    Skia.sk_path_delete(outline)
    from = i
  end
  Skia.sk_paint_delete(paint)
end

"The corners of the shape made by a stack of boxes: down its right side, then back up its left"
corners(rects) = begin
  points = NTuple{2,Float64}[]
  add(p) = (isempty(points) || points[end] != p) && push!(points, p)
  top = rects[1][2]
  for (l, t, r, b) in rects
    add((r, top)); add((r, b))
    top = b
  end
  for (i, (l, t, r, b)) in Iterators.reverse(enumerate(rects))
    add((l, b)); add((l, i == 1 ? t : rects[i-1][4]))
  end
  points
end

"A Skia path around `points`, with each corner rounded by up to `radius`"
rounded(points, radius) = begin
  path = Skia.sk_path_new()
  n = length(points)
  for i in 1:n
    before, corner, after = points[mod1(i - 1, n)], points[i], points[mod1(i + 1, n)]
    d1, d2 = hypot((before .- corner)...), hypot((after .- corner)...)
    # A short edge has room for less of a curve at each end
    r = min(radius, d1 / 2, d2 / 2)
    a = corner .+ (before .- corner) .* (r / max(d1, 1e-6))
    b = corner .+ (after .- corner) .* (r / max(d2, 1e-6))
    i == 1 ? Skia.sk_path_move_to(path, Float32(a[1]), Float32(a[2])) : Skia.sk_path_line_to(path, Float32(a[1]), Float32(a[2]))
    # A conic with this weight is a quarter of a circle
    Skia.sk_path_conic_to(path, Float32(corner[1]), Float32(corner[2]), Float32(b[1]), Float32(b[2]), Float32(sqrt(0.5)))
  end
  Skia.sk_path_close(path)
  path
end

# --- the caret's glide ------------------------------------------------------------------
#
# When you type, or press a key that takes the caret a step, the caret doesn't
# jump to its new place. It moves there in a short time, fast at first and then
# slower, and its height changes on the way. A caret that's sent somewhere else
# before it arrives goes on from where it is. A step is a character, a word or
# a line: what the arrow keys do, with ⌥ or without.
#
# Anything else that moves the caret puts it at its new place at once: a click,
# a drag, a key that goes to the end of the line or of the page, a link to a
# heading. So does a page that's laid out again, because the window changed
# its width, say, and a page that has just opened. The settings page turns the
# glide off.

const GLIDE_TIME = 0.07   # seconds the caret takes to get to a new place

"Where a caret is at the time `now`: its left, its top and its height"
glided(g::Glide, now) = begin
  t = clamp((now - g.left_at) / GLIDE_TIME, 0.0, 1.0)
  g.from .+ (g.to .- g.from) .* (1 - (1 - t)^3)   # fast at first, then slower
end

"True while a caret of the page is on its way to a new place"
gliding(e, now=time()) = any(g -> g.from != g.to && now - g.left_at < GLIDE_TIME, values(e.glides))

"""
Where to draw the caret numbered `slot` at the time `now`, when its place in
the text is at `to` on the page. A caret that a step or a change to the text
gave a new place sets off for it from where it's drawn now.
"""
glide_to!(e, slot, to, now=time()) = begin
  b = e.buf
  key = (b.caret, b.version)
  g = get(e.glides, slot, nothing)
  if g !== nothing && e.glide && g.buf == objectid(b)
    if g.key == key
      # The same place in the text, at the same place on the page: it goes on with its move
      maximum(abs, g.to .- to) < 0.01 && return glided(g, now)
    elseif e.by_step || g.key[2] != b.version
      g.from, g.to, g.left_at, g.key = glided(g, now), to, now, key
      return g.from
    end
  end
  e.glides[slot] = Glide(to, to, now, objectid(b), key)
  to
end

"Turn the caret's glide on or off"
glide!(e, on::Bool) = (e.glide = on; save_settings!(e); rerun!(e, :glide); e)

"Draw the caret at column `col` of `f`, whose top left corner is at (x, y)"
caret(ctx, e, f::Flow, x, y, col) = begin
  w = window_of(e)
  (w !== nothing && w.focus === e) || return
  k, cx = spot(f, col)
  high = f.size * 1.25
  left, top = e.origin
  at = glide_to!(e, e.gliding, (num(x + cx - left), num(y + line_top(f, k) + (f.lines[k].high - high)/2 - top), num(high)))
  g = e.glides[e.gliding]
  moving = g.from != g.to && time() - g.left_at < GLIDE_TIME
  # The window draws each frame as soon as it can until the caret arrives
  moving && (w.animating = true)
  # A caret that's moving doesn't blink
  since = time() - e.blink
  (moving || since < 0.5 || mod(since - 0.5, 1.0) >= 0.5) || return
  rectangle(ctx, left + px(at[1]) - 0.75px, top + px(at[2]), 1.5px, px(at[3]), background=colours.ink, border=0px)
end

# The caret and the selection are drawn over the text, once it has been placed
draw(ctx, size, ui::ConcreteRect, d::Document) = begin
  e = editor(d)
  b = e.buf
  e.origin = (ui.left, ui.top)
  tint_new(ctx, e, ui)
  fill_selection(ctx, selection_boxes(ctx, e, ui))
  with_others(() -> fill_selection(ctx, selection_boxes(ctx, e, ui)), b)
  outline_same_word(ctx, e, ui)
  mark_pointed(ctx, e, ui)
  underline_scrubs(ctx, e, ui)
  mark_clickable(ctx, e, ui)
  note_peek!(e)   # the card of a footnote whose number the mouse is on
  mark_checks(ctx, e, ui)
  mark_steps(ctx, e, ui)
  ring_part(ctx, e, ui)
  annotate(ctx, e, ui)
  mark_commented(ctx, e, ui)
  glow_bracket_pair(ctx, e, ui)
  # A file that's only shown has a selection and no caret. So has a page that's never changed.
  if !(caretless(b) || readonly(b))
    # Each caret has a number, so that it moves from its own last place. When there are more carets or fewer, the others start again.
    n = 1 + length(others(b))
    n == e.carets || (filter!(kv -> kv.first == 1, e.glides); e.carets = n)
    e.gliding = 1
    carets(ctx, e, ui)
    with_others(() -> (e.gliding += 1; carets(ctx, e, ui)), b)
    e.gliding = 1
  end
  e.by_step = false   # the step has been drawn. What moves the caret next may be a click.
  veil_later(ctx, e, ui)
  margin(ctx, e, ui)
end

"""
True when the selection is all in one code block, or in a file of code. The
space to the left of the code is the block's padding. There's no line outside
the block for the selection to line up with, so that space gets no colour.
"""
within_code(b::Buffer) = begin
  lo, hi = selection(b)
  kinds(b)[lo[1]].kind in (Kind.code, Kind.fence) && hi[1] <= codeblock(b, lo[1])[2]
end

"""
The boxes that cover the selection on the page, whose text is at `ui`. The
part of it that's in the cells of a table is filled here, a cell at a time.
"""
selection_boxes(ctx, e, ui) = begin
  b = e.buf
  # A line takes in the space left of its text only when the selection came into it from the line above
  margins = !within_code(b)
  # The selection goes under the caret, as one shape for each run of lines that touch
  rects = Rect[]
  for it in e.layout[e.shown]
    top = ui.top + it.top
    across, wide = item_room(e, it)   # an item in a column of the page starts at the column's left edge, and is as wide as the column
    left = ui.left + across
    if it.content isa Grid
      g = it.content
      if b.caret[1] != b.anchor[1]
        # A selection that covers several lines takes each row whole
        lo, hi = selection(b)
        y = top + TABLE_GAP
        lo[1] < it.first && hi[1] >= it.first && push!(rects, (num(left), num(top), num(left + 7px), num(y)))
        y += g.head   # a spreadsheet's row of letters isn't part of the text, so it's never selected
        for (r, i) in enumerate(g.rows)
          h = g.heights[r] + (r == length(g.rows) ? 2px : 1px)
          lo[1] <= i <= hi[1] && push!(rects, (num(left), num(y), num(left + wide), num(y + h)))
          y += h
        end
        lo[1] <= it.last && hi[1] > it.last && push!(rects, (num(left), num(y), num(left + 7px), num(y + TABLE_GAP)))
        continue
      end
      for (r, i) in enumerate(g.rows), (c, cell) in enumerate(g.cells[r])
        sel = selected(b, i)
        (sel !== nothing && sel[1] < cell.limit && sel[2] > cell.lo) || continue
        x, y = cell_origin(g, r, c)
        fill_selection(ctx, marks(g.flows[r][c], ui.left + x, top + y, (max(sel[1], cell.lo), min(sel[2], cell.limit), false), margin=false))
      end
    elseif it.content isa Sheet
      append!(rects, marks(e, it, it.content, left, top))
    elseif it.content isa Live
      # A live block is selected whole
      lo, hi = selection(b)
      selecting(b) && lo[1] <= it.first && hi[1] >= it.last &&
        push!(rects, (num(left), num(top), num(left + wide), num(top + it.tall)))
    else
      sel = selected(b, it.first)
      sel === nothing || append!(rects, marks(it.content, ui.left, top, sel, margin=margins && selection(b)[1][1] < it.first, edge=across))
    end
  end
  rects
end

"""
Draw the numbers of the lines, and the bars beside the lines that just changed,
in the room on the left of the text. The text of a page that's scrolled to the
right goes under that room, so the room is filled with the page's colour first.
"""
margin(ctx, e, ui) = begin
  across = sideways(e)
  left = ui.left + across   # where the text starts when it isn't scrolled
  room = PAGE_X + gutter(e)
  across > 0px && rectangle(ctx, left - room, ui.top, room, ui.height, background=colours.bg, border=0px)
  shade_line(ctx, e, left - room, ui.top)
  draw_numbers(ctx, e, left, ui.top)
  draw_fresh(ctx, e, left, ui.top)
  draw_diff_bars(ctx, e, left, ui.top)
end

const SHADE = 0.05   # how much of the colour of the text the shade of the caret's line has

"""
Shade the line that the caret is on, from `x` to the right edge of the window,
in a file of code whose settings ask for it. The shade is faint, so the text
shows through it. There's none while text is selected.
"""
shade_line(ctx, e, x, top) = begin
  b = e.buf
  (e.shade && numbered(b) && !caretless(b) && !readonly(b) && !selecting(b) && !isempty(e.layout)) || return
  it = item(e, b.caret[1])
  w, _ = window_size(e)
  rectangle(ctx, x, top + it.top, w - x, it.tall, background=RGBA(colours.ink, SHADE), border=0px)
end

"Draw the caret on the page, whose text is at `ui`"
carets(ctx, e, ui) = begin
  b = e.buf
  picked(b) === nothing || return   # a line round the part shows where the caret is
  for it in e.layout[e.shown]
    top = ui.top + it.top
    if it.content isa Grid
      g = it.content
      at = gridcell(g, b.caret)
      isspread(g) && at !== nothing && b.caret[1] == b.anchor[1] && ring(ctx, g, at, ui.left, top)
      for (r, i) in enumerate(g.rows), (c, cell) in enumerate(g.cells[r])
        x, y = cell_origin(g, r, c)
        at == (r, c) && caret(ctx, e, g.flows[r][c], ui.left + x, top + y, b.caret[2])
      end
      continue
    end
    it.content isa Sheet && caret(ctx, e, it.content, ui.left + item_room(e, it)[1], top)
    it.first == b.caret[1] && it.content isa Flow && caret(ctx, e, it.content, ui.left, top, b.caret[2])
  end
end

# --- the mouse on the page --------------------------------------------------------------

"The place in the document under a point in the window"
locate(e, (x, y)) = begin
  # On a page that's scrolled sideways, a point on the numbers of the lines is on the first part of the line that shows
  dx, dy = max(x - e.origin[1], sideways(e)), y - e.origin[2]
  items = e.layout
  isempty(items) && return e.buf.caret
  it = items[item_under(e, dx, dy)]
  # Until the next frame, the layout can be of the page that showed before, as when a click opened another
  # file and the mouse moved with its button still down. That page can have more lines than this one.
  it.last <= length(e.buf.lines) || return e.buf.caret
  if it.content isa Grid
    g = it.content
    # The row and the column under the point
    r = something(findfirst(r -> dy < it.top + cell_origin(g, r, 1)[2] + g.heights[r], eachindex(g.rows)), length(g.rows))
    c = something(findlast(c -> dx >= cell_origin(g, r, c)[1], eachindex(g.widths)), 1)
    cells = g.cells[r]
    isempty(cells) && return line_end(e.buf, g.rows[r])
    # A row can have fewer cells than the table has columns
    c = min(c, length(cells))
    f = g.flows[r][c]
    x, y = cell_origin(g, r, c)
    k = line_at(f, dy - it.top - y)
    return (g.rows[r], cellcol(f, k, dx - x, cells[c]))
  end
  it.content isa Sheet && return locate(e, it, it.content, dx - item_room(e, it)[1], dy - it.top)
  if it.content isa Live
    # A point on a live block counts as the end of the line above it or the start of the line below
    above = dy < it.top + it.tall/2 ? it.first > 1 : it.last == length(e.buf.lines)
    return above && it.first > 1 ? line_end(e.buf, it.first - 1) : it.last < length(e.buf.lines) ? (it.last + 1, 0) : (it.first, 0)
  end
  f = it.content::Flow
  # A line of the page before can be longer than this page's line of the same number
  (it.first, min(colat(f, line_at(f, dy - it.top), dx), length(e.buf.lines[it.first])))
end

"The link under a point in the window, or nothing. A link in a cell of a table counts too."
link_at(e, pos) = begin
  line, col = locate(e, pos)
  it = item(e, line)
  c = it.content
  # Each cell of a table has its own lines of text. Their columns are the columns of the row's line.
  r = c isa Grid ? findfirst(==(line), c.rows) : nothing
  flows = c isa Flow ? [c] : r === nothing ? Flow[] : c.flows[r]
  for f in flows, vl in f.lines, seg in vl.segs
    seg.col <= col < seg.col + seg.n && !isempty(seg.link) && return seg.link
  end
  nothing
end

"""
The link that's drawn under a point in the window, or nothing. `link_at` gives
the link nearest to a point, which is right for a click with ⌘ held. A point
beside a line, or between two lines, is on no link here, so a click with no
key held opens a link only when the click is on its words. A link in a cell
of a table counts too.
"""
link_on(e, (x, y)) = begin
  dx, dy = x - e.origin[1], y - e.origin[2]
  (dy >= 0px && !isempty(e.layout)) || return nothing
  it = e.layout[item_under(e, dx, dy)]
  c = it.content
  c isa Flow && return link_on(c, dx, dy - it.top)
  c isa Grid || return nothing
  # Each cell of a table has its own lines of text, from the top left of the cell
  for r in eachindex(c.rows), col in eachindex(c.flows[r])
    cx, cy = cell_origin(c, r, col)
    found = link_on(c.flows[r][col], dx - cx, dy - it.top - cy)
    found === nothing || return found
  end
  nothing
end

"The link that's drawn at `dx` across and `dy` down from the top left of `f`, or nothing"
link_on(f::Flow, dx::px, dy::px) = begin
  for vl in f.lines
    top = f.above + vl.top
    top <= dy < top + vl.high || continue
    for seg in vl.segs
      !isempty(seg.link) && seg.x <= dx < seg.x + seg.w && return seg.link
    end
  end
  nothing
end

isword(c::Char) = isletter(c) || isdigit(c) || c == '_' || c == '\''

"The columns of the word around column `col` of `line`"
word_at(line::String, col::Int) = begin
  chars = collect(line)
  lo = hi = clamp(col, 0, length(chars))
  while lo > 0 && isword(chars[lo]); lo -= 1 end
  while hi < length(chars) && isword(chars[hi+1]); hi += 1 end
  (lo, hi)
end

held(node, key) = (w = window_of(node); w !== nothing && key in w.keys)

"The keys of ⌃, ⌘, ⌥ and ⇧ that are down in the window `w`"
held_keys(w::Window) = w.keys & HELD

"""
True when the keys of ⌃, ⌘, ⌥ and ⇧ that are down are `keys` and no others,
like `Keys.cmd` for ⌘ alone. It takes a window, the event of a key, a click or
the wheel, or a part of a window. Each key and click that does something else
with ⌃, ⌘, ⌥ or ⇧ held asks this, so each does it only with the keys that it's
for. A key that holds all four, like a hyper key, does none of those things.
"""
only_held(w::Window, keys::Keys) = held_keys(w) == keys
only_held(ev::Union{KeyPress,KeyRelease,MouseScroll,Typed}, keys::Keys) = only_held(ev.window, keys)
only_held(node, keys::Keys) = (w = window_of(node); w === nothing ? keys == Keys(0) : only_held(w, keys))

"True when no key of ⌃, ⌘, ⌥ and ⇧ is down: in a window, with a key's event, or in the window of a part"
unmodified(x) = only_held(x, Keys(0))

"The caret moved or the text changed, so show the caret"
touch!(e; keep_goal=false) = begin
  e.buf.reading = false
  e.blink = time()
  e.reveal = true
  keep_goal || (e.goal = nothing)
  confine!(e)
end

"The line of the to-do item whose box is under a point in the window, or nothing"
todo_at(e, (x, y)) = begin
  isempty(e.layout) && return nothing
  dx, dy = x - e.origin[1], y - e.origin[2]
  it = e.layout[item_under(e, dx, dy)]
  f = it.content
  shows_box(f) || return nothing
  # The box is on the item's first line
  it.top + f.above <= dy < it.top + f.above + first(f.lines).high || return nothing
  for seg in first(f.lines).segs
    isbox(seg) && return seg.x <= dx < seg.x + seg.w ? it.first : nothing
  end
  nothing
end

"What inline code made that's under a point in the window: its Inline, or nothing"
inline_at(e, (x, y)) = begin
  isempty(e.layout) && return nothing
  dx, dy = x - e.origin[1], y - e.origin[2]
  it = e.layout[item_under(e, dx, dy)]
  c = it.content
  if c isa Grid
    for r in eachindex(c.rows), col in eachindex(c.flows[r])
      cx, cy = cell_origin(c, r, col)
      found = inline_at(c.flows[r][col], dx - cx, dy - it.top - cy)
      found === nothing || return found
    end
    return nothing
  end
  c isa Flow ? inline_at(c, dx, dy - it.top) : nothing
end

inline_at(f::Flow, dx::px, dy::px) = begin
  (0px <= dy < tall(f)) || return nothing
  for seg in f.lines[line_at(f, dy)].segs
    seg.node !== nothing && seg.x <= dx < seg.x + seg.w && return seg.node
  end
  nothing
end

"""
Tick the box of the to-do item on line `i`, or take its tick away. The caret
stays where it is. A tick of an item that repeats, like one that ends with
"every week", adds the next one under it: see repeats.jl.
"""
tick!(e, i::Int) = begin
  # On another day than today, the box shows how the item stands then, which a click can't change
  ticked_then(e, i) === nothing || return e
  tick_item!(e.buf, i, !isdone(e.buf.lines[i]))
  stop_clock!(e, i)   # a tick stops the clock of a time log that runs on the item
  e
end

"""
Tick the to-do item on line `i` of `b` when `done`, or take its tick away, in
one edit, so one ⌘Z takes it back. The item that a tick of a repeating item
adds goes in the same edit. The caret and the other end of the selection stay
with their text.
"""
tick_item!(b::Buffer, i::Int, done::Bool) = begin
  new, z = Repeats.tick(b.lines, i, done; today=calendar_today())
  caret, anchor = b.caret, b.anchor
  edit!(b, (i, 0), line_end(b, z), join(new, "\n"))
  grow = length(new) - (z - i + 1)
  # A line after the item moves down or up with the line that went in or out. One that went takes it to the item's last line.
  keep((l, c)) = l > z ? (l + grow, c) : l < i + length(new) ? (l, min(c, length(b.lines[l]))) : line_end(b, i + length(new) - 1)
  b.caret, b.anchor = keep(caret), keep(anchor)
  b
end

press!(e, pos) = begin
  slideshow(e) === nothing || return slide_press!(e, pos)   # a click on a slide goes to the next one, or back
  # ⌥-click on a part of another page shows the link that names the part, as ⌥-click on any part shows its lines
  (hosted(e) !== nothing && only_held(e, Keys.opt)) && return press!(hosted(e), pos)
  empty!(e.glides)   # a click puts the caret at its new place at once, even a click that changes the text
  b = e.buf
  # A click on the number of a line asks git when the line last changed. The click puts the caret on the line too.
  # Julia compiles line_history! and definition! when they're first used, not with this function, so a first click doesn't wait for them.
  numbered = number_at(e, pos)
  numbered === nothing || Base.invokelatest(line_history!, e, numbered)
  box = only_held(e, Keys.opt) ? nothing : todo_at(e, pos)
  if box !== nothing
    # A click on a to-do item's box ticks it, and doesn't move the caret
    focus(e)
    e.popup = :none
    e.clicked = (time(), (box, 0), 0)
    return tick!(e, box)
  end
  # A press on what a number comes to takes hold of the number: a drag then changes it
  found = unmodified(e) ? scrub_at(e, pos) : nothing
  found === nothing || return scrub!(e, found, pos)
  it = e.layout[item_under(e, pos[1] - e.origin[1], pos[2] - e.origin[2])]
  made = only_held(e, Keys.opt) ? nothing : inline_at(e, pos)
  # A click on a formula in a line of text puts the caret beside it, as a click on a word does
  if made !== nothing && !(made.node isa Equation)
    # What inline code made takes its own clicks, as a live block does. A click with ⌥ held shows the code.
    e.popup = :none
    e.clicked = (time(), (it.first, 0), 0)
    took(e) || focus(e)
    return
  end
  if it.content isa Live && !only_held(e, Keys.opt)
    # A live block takes its own clicks. A part of it that took the keyboard, like a text field, keeps it.
    e.popup = :none
    e.clicked = (time(), (it.first, 0), 0)
    took(e) || focus(e)
    pick_clicked!(e, it)
    return
  end
  focus(e)
  e.popup = :none
  # ⌘ with another key held, like ⇧ or ⌃, opens no link
  if only_held(e, Keys.cmd)
    url = link_at(e, pos)
    url === nothing || return follow!(e, url)
    # In Julia code, a click on a name goes to where the name is defined
    it.content isa Flow && Base.invokelatest(definition!, e, locate(e, pos)) === true && return
  elseif b.fixed && only_held(e, Keys(0))
    # A page that's never changed has no caret for a click to place, so a click with no key held on a link opens it
    url = link_on(e, pos)
    url === nothing || return follow!(e, url)
  end
  if it.content isa Live
    # A click with ⌥ held shows the block's code. A part of one line, like a picture, shows its line, with the caret at the end.
    e.clicked = (time(), (it.first, 0), 0)
    b.caret = b.anchor = it.last > it.first ? (it.first + 1, 0) : line_end(b, it.first)
    return touch!(e)
  end
  it.content isa Sheet && press!(e, it, it.content, pos) && return touch!(e)
  if it.content isa Grid && isspread(it.content) && only_held(e, Keys.opt)
    # A click on a spreadsheet with ⌥ held shows it as lines of code
    b.caret = b.anchor = line_end(b, it.first)
    return touch!(e)
  end
  at = settle(b, locate(e, pos))
  t, before, count = e.clicked
  count = time() - t < 0.4 && before == at ? count % 3 + 1 : 1
  e.clicked = (time(), at, count)
  if count == 2
    lo, hi = word_at(b.lines[at[1]], at[2])
    b.anchor, b.caret = (at[1], lo), (at[1], hi)
  elseif count == 3
    # Three clicks select the line, or in a table the cell
    cell = cellat(b, at)
    lo, hi = cell === nothing ? (0, length(b.lines[at[1]])) : (cell.lo, cell.hi)
    b.anchor, b.caret = (at[1], lo), (at[1], hi)
  else
    b.caret = at
    only_held(e, Keys.shft) || (b.anchor = at)
  end
  touch!(e)
end

"""
After a click on the live block that `it` shows, put the caret on the block as a
whole, as ↑ and ↓ do, so that it has the line round it. A click that a part of
the block takes for itself, like a click on a button, never comes here. A click
that a part uses and lets go on to the page, like a stroke of a pen or a click
in a field, puts the caret on the block too, unless the part moved the caret.
A click with a key like ⌘ or ⇧ held leaves the caret where it is. The page
doesn't scroll, because the block is under the mouse.
"""
pick_clicked!(e, it::Item) = begin
  b = e.buf
  (unmodified(e) && rich(b) && !b.fixed && b.caret == b.stood) || return
  # A part of the block that changed its lines leaves the caret where it is
  part(b, it.first) == (it.first, it.last) || return
  b.caret = b.anchor = (it.first, 0)
  touch!(e)
  e.reveal = false
end

"""
Give a click on `node` to the page, as a click on its text is given. A part of
the page like a picture, a table from a CSV file or the front matter has no use
for a click of its own, so the page puts the caret on the part as a whole, or
with ⌥ held shows its lines as they're written. Such a part's node hangs from
the editor, not from the page's text, so the click doesn't get there by itself.
"""
click_page!(node, ev) = (press!(editor(node), ev.window.mouse); handled)

"""
How far a key scrolls the page while it's read, or nothing for a key that doesn't
scroll it. `command` is the command that the key runs while the page isn't read.
The keys that move the caret up and down scroll a little. The keys that move it
a screen, and Space, scroll a screen less a little, so a line or two stays in
sight. Home, End and the keys that move the caret to the top or the bottom of
the page scroll that far.
"""
read_step(e, K, command, down) = begin
  screen = e.scroll.viewport - 40px
  # Home, End and Space with no command scroll only by themselves, with no key of ⌃, ⌘, ⌥ and ⇧ held. Space with ⇧ goes back.
  plain = down == Keys(0)
  command == :up ? -50px :
  command == :down ? 50px :
  command == :page_up ? -screen :
  command == :page_down ? screen :
  command == :doc_start || (K == Keys.home && (command == :line_start || (command === nothing && plain))) ? px(-Inf) :
  command == :doc_end || (K == Keys._end && (command == :line_end || (command === nothing && plain))) ? px(Inf) :
  command === nothing && K == Keys.space && (plain || down == Keys.shft) ? (plain ? screen : -screen) : nothing
end

"Scroll the page by `by`, as far as it goes"
scroll_page!(e, by) = begin
  s = e.scroll
  s.offset = clamp(s.offset + by, 0px, max(0px, s.content_height - s.viewport))
  e
end

"True when `a` is `b` or holds it"
holds(a, b) = begin
  while b !== nothing
    b === a && return true
    b = b.parent
  end
  false
end

"""
True when the node that has the keyboard is something other than the text, and
the click that is happening now is on that node, or on a part of it, or on a
node that holds it. A click on a list in a live block gives the list the
keyboard, and the click goes on to the page after the list has taken it.
"""
took(e) = begin
  w = window_of(e)
  w === nothing && return false
  f, under = w.focus, hittest(w)
  (f === nothing || f === e || f === input(e) || under === nothing) && return false
  holds(f, under) || holds(under, f)
end

"A heading as a link names it: its letters and digits in lower case, with a - where anything else is. `Live blocks` is `live-blocks`."
heading_slug(words) = String(strip(replace(lowercase(plain_cell(words)), r"[^\p{L}\p{N}]+" => "-"), '-'))

"""
Follow a link that names a heading of a page: `welcome.md#tables`, or `#tables`
for a heading of the page that shows. The page opens, and the heading goes to
the top of the window. It's true when the link names a page. It's false for any
other link with a # in it, like the address of a web page.
"""
follow_heading!(e, url) = begin
  file, name = String.(split(url, '#', limit=2))
  path = isempty(file) ? e.buf.path : abspath(docdir(e), unescaped(file))
  (ismarkdown(path) && isfile(path)) || return false
  go_heading!(e, path, unescaped(name))
end

"Show the page at `path` with its heading `name` near the top of the window. A page with no such heading shows from where it was. It's true."
go_heading!(e, path, name) = begin
  hosted(e) === nothing || return go_heading!(top_editor(e), path, name)   # a link in a part of another page goes there in the window
  path == e.buf.path || open!(e, path)
  b = e.buf
  ks = kinds(b)
  slug = heading_slug(name)
  i = findfirst(i -> ks[i].kind == Kind.heading && heading_slug(rest(b.lines[i], ks[i].prefix)) == slug, eachindex(ks))
  i === nothing && return true
  show_line!(e, i)
  # Its line goes near the top of the window. The next frame does it, once it has laid out the page.
  e.nodes[:hold] = (i, 24px - PAGE_TOP)
  true
end

# --- wiki links ---------------------------------------------------------------------------
#
# A wiki link, like [[Ideas]], names a page and not its file, as in Obsidian. The
# page can be anywhere in the project, so a link stays good when a page moves to
# another folder. See markdown.jl for how one is written.

"The folder names that mark the top folder of a project"
const PROJECT_MARKS = (".git", ".obsidian")

"""
The top folder of the project that the folder `dir` is in: the nearest folder,
from `dir` up, that has a `.git` or an `.obsidian` folder in it. It's `dir`
when there's none below the home folder.
"""
project_root(dir) = begin
  d = dir
  while d != homedir() && d != dirname(d)
    any(m -> ispath(joinpath(d, m)), PROJECT_MARKS) && return d
    d = dirname(d)
  end
  dir
end

"""
The file under `root` whose path ends with one of `names`, like `Ideas.md` or
`notes/Ideas.md`, in any case, or nothing. A file in a folder near the top
comes before one in a folder deeper down. Hidden folders and `node_modules` are
left out, and the look stops after a part of a second, as the `find` block's does.
"""
find_named(root, names; budget=FIND_BUDGET) = begin
  ends = ["/" * lowercase(n) for n in names]
  started = time()
  level = [root]
  while !isempty(level) && time() - started < budget
    deeper = String[]
    for dir in level
      found = try sort!(readdir(dir), by=lowercase) catch; String[] end
      for name in found
        startswith(name, '.') && continue
        path = joinpath(dir, name)
        if isdir(path)
          name == "node_modules" || push!(deeper, path)
        elseif any(t -> endswith(lowercase(path), t), ends)
          return path
        end
      end
    end
    level = deeper
  end
  nothing
end

"The file that the wiki link to `name`, in a page in the folder `dir`, names, as `wiki_path` finds it, or nothing when no file has the name"
wiki_file(dir, name) = begin
  names = ismarkdown(name) ? [name] : [name * ".md", name]
  root = project_root(dir)
  for top in unique([dir, root]), n in names
    path = abspath(top, expanduser(n))
    isfile(path) && return path
  end
  find_named(root, names)
end

"""
The file that the wiki link to `name` names. `name` is a page's name, like
`Ideas`, and its file is `Ideas.md`. A name with a file's extension, like
`plan.pdf`, can be that file too. A name can have folders in it, like
`notes/Ideas`. Ladder looks in the page's own folder, then from the top of its
project (see `project_root`), then through the whole project. When no file
has the name, it's the path of a new page in the page's own folder.
"""
wiki_path(e, name) = begin
  dir = docdir(e)
  found = wiki_file(dir, name)
  found === nothing || return found
  names = ismarkdown(name) ? [name] : [name * ".md", name]
  new = abspath(dir, names[1])
  # A name with folders that aren't there yet makes its page in the page's own folder
  isdir(dirname(new)) ? new : joinpath(dir, basename(new))
end

"""
Follow a wiki link to `target`: show the page that it names. `Ideas#Plans` goes
to the heading Plans of the page Ideas, and `#Plans` to a heading of the page
that shows. A page that isn't anywhere opens as a new page with no text, in the
page's own folder. Its file is made when you write in it.
"""
follow_wiki!(e, target) = begin
  name, heading = occursin('#', target) ? String.(split(target, '#', limit=2)) : (target, "")
  name = String(strip(name))
  isempty(name) && return (go_heading!(e, e.buf.path, heading); e)
  path = wiki_path(e, name)
  if !isempty(heading) && ismarkdown(path) && isfile(path)
    go_heading!(e, path, heading)
    return e
  end
  isfile(path) ? show_path!(e, path) : open!(e, path)
end

# While you type the name in a wiki link, the list of names under the caret
# shows the pages of the project whose names fit what's typed. Right after the
# [[, it shows them all, the pages beside this one first. Each page's folder,
# from the top of the project, is at the right of its row. Return or Tab types
# the rest of the name and the ]] that ends the link. Two pages with the same
# name are each written with their folders, like notes/Ideas.

"""
The pages that the name being typed in a wiki link could be: the line, the
column where the name starts, and the names. Nothing when the caret isn't in
the name of a wiki link just after a character was typed, or no page fits.
"""
wiki_offered(e) = begin
  b = e.buf
  i, col = b.caret
  key = (b.path, b.version, b.caret)
  get(e.nodes, :typed_at, nothing) == key || return nothing
  kept = get(e.nodes, :wiki_offered, nothing)
  kept !== nothing && kept[1] == key && return kept[2]
  found = wiki_names(e, i, col)
  e.nodes[:wiki_offered] = (key, found)
  found
end

"The name being typed in a wiki link at column `col` of line `i`, and the pages that fit it, as `wiki_offered` gives them"
wiki_names(e, i, col) = begin
  b = e.buf
  kinds(b)[i].kind in (Kind.code, Kind.fence, Kind.table) && return nothing
  chars = collect(b.lines[i])
  # The name starts after the [[ before the caret. A | or a # ends it, and a bracket isn't part of one.
  start = col
  while start > 0 && !(chars[start] in ('[', ']', '|', '#')); start -= 1 end
  (start >= 2 && chars[start] == '[' && chars[start-1] == '[') || return nothing
  col - start <= 80 || return nothing
  typed = lowercase(String(chars[start+1:col]))
  dir = docdir(e)
  root = project_root(dir)
  pages = [p for (p, _) in folder_pages(root).pages if p != b.path]
  name(p) = splitext(basename(p))[1]
  many = Dict{String,Int}()
  foreach(p -> many[lowercase(name(p))] = get(many, lowercase(name(p)), 0) + 1, pages)
  notes = Dict{String,String}()
  found = Tuple{Int,Bool,Int,String,String}[]   # how well it fits, whether it's in another folder, how deep it is, its name in lower case, and its name
  for p in pages
    folder = relpath(dirname(p), root)
    folder == "." && (folder = "")
    # Two pages with the same name are told apart by their folders
    shown = many[lowercase(name(p))] > 1 && !isempty(folder) ? joinpath(folder, name(p)) : name(p)
    low = lowercase(shown)
    fit = low == typed ? 0 : startswith(low, typed) ? 1 : any(w -> startswith(w, typed), split(low, r"[\s_/-]+", keepempty=false)) ? 2 : occursin(typed, low) ? 3 : 4
    fit < 4 || continue
    shown == name(p) && (notes[shown] = folder)
    push!(found, (fit, dirname(p) != dir, count(==('/'), folder), low, shown))
  end
  isempty(found) && return nothing
  e.nodes[:wiki_notes] = notes
  (i, start, unique([n for (_, _, _, _, n) in first(sort!(found), NAMES_SHOWN)]))
end

"""
Type `name` in place of the text from column `start` of line `i` to the caret,
as the list of names does. In a wiki link, the ]] that ends the link comes too,
unless the link has its end already. The caret goes past a ]] that's just after the name.
"""
complete!(e, i, start, name) = begin
  b = e.buf
  edit!(b, (i, start), b.caret, name)
  kinds(b)[i].kind == Kind.code && return
  after = rest(b.lines[i], b.caret[2])
  ends, opens = findfirst("]]", after), findfirst("[[", after)
  if ends === nothing || (opens !== nothing && first(opens) < first(ends))
    edit!(b, b.caret, b.caret, "]]")
  elseif startswith(after, "]]")
    b.caret = b.anchor = (i, b.caret[2] + 2)
  end
end

# --- a part of another page ----------------------------------------------------------------
#
# A line that holds only a link like ![[Ideas#Plans]] shows that part of the
# page Ideas in this page. Ted Nelson called that a transclusion, and Notion
# calls it a synced block. The part isn't a copy. It's the other page's own
# lines: type in it here and the other page changes, and a change there shows
# here at once. ⌘S saves both pages. What comes after the # names the part:
#
#   - ![[Ideas]] is the whole page, without its front matter.
#   - ![[Ideas#Plans]] is the heading Plans and the lines under it, up to the
#     next heading that's as big as it or bigger.
#   - ![[Ideas#^prices]] is the block that has the name prices, as Obsidian
#     names one: see `block_id` in markdown.jl. The command Copy Link To Block
#     names the block at the caret, and copies the link that shows it.
#   - ![[Ideas#table 2]] is the second table of the page. A kind is one of
#     paragraph, heading, list, quote, table, code and picture, or the
#     language of a code block, like board, canvas or julia. Without a number,
#     it's the first one. Code counts the code blocks that show as code.
#
# A heading with the name comes first, so a heading called "Table 2" wins over
# the second table. The page is found as a wiki link finds it: see `wiki_path`.
#
# An editor of its own shows the part. It edits the other page's lines, and
# shows only the lines of the part. Ladder's keys work in it as they do in any
# page. A click in its text puts its caret there, and Return gives it the
# keyboard while the caret is on the part as a whole. ↑ on its first line, ↓
# on its last line and esc go back to this page. A key for the window, like
# ⌘W, is this page's. A live block of the other page, like a board or a chart,
# shows there what it shows in its own page, but a click on it does nothing.

"A line that holds only a link to a part of another page. The name of the part is after the [[."
const TRANSCLUSION = r"^\s*!\[\[([^\]|]+)(?:\|[^\]]*)?\]\]\s*$"

"True when line `i` holds only a link that shows a part of another page"
transcludes(b::Buffer, i::Int) = (line = b.lines[i]; occursin("![[", line) && occursin(TRANSCLUSION, line) && !isremote(b.path))

"How many parts of other pages can show inside each other: a part of a page that shows a part of a page that…"
const DEEPEST_PART = 3

"How tall the line is that shows in place of a part that isn't there"
const PART_NOTE_H = 28px

"""
The room over the text of a part of another page. The button that opens the
other page sits there, on the line round the part. A click goes only to what's
inside its parent's box, so the button can't be over the line above the part.
"""
const PART_TAB = 15px

"A part of another page, as a line of this page shows it"
@def mutable struct Transclusion <: SemanticUI
  line::Int = 0            # the line of this page that names the part
  target::String = ""      # what the line names, like "Ideas#Plans"
  path::String = ""        # the other page's file
  sub::Any = nothing       # the editor of the other page's lines
  note::String = ""        # what shows in place of a part that isn't there
  tall::px = 0px
end

"What covers a live block in a part of another page, so that a click on the block does nothing"
@def mutable struct LiveCover <: SemanticUI
  tall::px = 0px
end

"The button over a part of another page that opens that page"
@def mutable struct PartSource <: SemanticUI
  of::Any = nothing   # the Transclusion
end

"The editor of the page that shows the part of a page that `e` edits, or nothing when `e` is the window's own"
hosted(e) = get(e.nodes, :host, nothing)

"The editor of the window that `e` is in: `e`, or the editor of the page that shows the part that `e` edits, and so on up"
top_editor(e) = (h = hosted(e); h === nothing ? e : top_editor(h))

"The files of `e`'s page, of the page that shows a part of it, and so on up to the window's page"
host_paths(e) = (h = hosted(e); h === nothing ? [e.buf.path] : [e.buf.path; host_paths(h)])

"The views of the parts of other pages that `e`'s page shows"
transclusions(e) = [v for (k, v) in e.nodes if v isa Transclusion && k[2] == e.buf.path]

"The pages whose lines the parts on `e`'s page edit, with the pages that parts of those edit, and so on"
shown_buffers(e) = begin
  out = Buffer[]
  for v in transclusions(e)
    v.sub === nothing && continue
    any(b -> b === v.sub.buf, out) || push!(out, v.sub.buf)
    foreach(b -> any(c -> c === b, out) || push!(out, b), shown_buffers(v.sub))
  end
  out
end

"""
The blocks of the page that `b` holds, in order, as the kind of each, the
language of a code block, and its first and last line. The front matter and a
line that only names the block above it aren't blocks.
"""
transclusion_blocks(b::Buffer) = begin
  ks, lines = kinds(b), b.lines
  n = length(lines)
  out = Tuple{String,String,Int,Int}[]
  i = front_matter(lines) + 1
  lists = (Kind.bullet, Kind.ordered, Kind.todo)
  # The lines after `i` that go on in the block of line `i`
  run(more) = (t = i; while t < n && more(t + 1); t += 1 end; t)
  while i <= n
    k = ks[i]
    if k.kind == Kind.blank || only_id(lines[i])
      i += 1
      continue
    end
    kind, lang, t = if k.kind in (Kind.fence, Kind.code)
      s, t = codeblock(b, i)
      # A block that shows as what it makes, like a board, isn't code
      (solid(b, i) == (s, t) ? "block" : "code", k.lang, t)
    elseif k.kind == Kind.heading
      ("heading", "", i)
    elseif k.kind == Kind.rule
      ("rule", "", i)
    elseif k.kind == Kind.table
      ("table", "", run(j -> ks[j].kind == Kind.table))
    elseif k.kind in lists
      # A list goes on through the lines that are indented under its items
      ("list", "", run(j -> ks[j].kind in lists || (ks[j].kind == Kind.paragraph && ks[j].level > 0)))
    elseif k.kind == Kind.blockquote
      ("quote", "", run(j -> ks[j].kind == Kind.blockquote))
    elseif pictured(b, i) || transcludes(b, i)
      ("picture", "", i)
    else
      ("paragraph", "", run(j -> ks[j].kind == Kind.paragraph && !only_id(lines[j]) && !pictured(b, j) && !transcludes(b, j)))
    end
    push!(out, (kind, lang, i, t))
    i = t + 1
  end
  out
end

"""
The first and last line of the part of the page in `b` that `part` names, as
what comes after the # of a link like ![[Ideas#Plans]] names one, or nothing
when the page has no such part. "" names the whole page.
"""
transclusion_lines(b::Buffer, part::AbstractString) = begin
  lines, ks = b.lines, kinds(b)
  n = length(lines)
  part = String(strip(part))
  trimmed((s, t)) = (while t > s && isempty(strip(lines[t])); t -= 1 end; s <= t ? (s, t) : nothing)
  isempty(part) && return trimmed((min(front_matter(lines) + 1, n), n))
  found = transclusion_blocks(b)
  if startswith(part, '^')
    # The block whose last line ends with the name, or the block over a line that holds only the name
    name = part[2:end]
    i = findfirst(l -> block_id(l) == name, lines)
    i === nothing && return nothing
    if only_id(lines[i])
      above = findlast(x -> x[4] < i, found)
      return above === nothing ? nothing : found[above][3:4]
    end
    at = findfirst(x -> x[3] <= i <= x[4], found)
    at === nothing && return nothing
    kind, _, s, t = found[at]
    kind == "heading" && return heading_lines(b, i)
    # In a list, the name is on one item, and the part is that item with the lines indented under it
    if kind == "list"
      last = t
      t = i
      while t < last && ks[t+1].level > ks[i].level; t += 1 end
      return (i, t)
    end
    return (s, t)
  end
  # A heading with the name
  slug = heading_slug(part)
  i = findfirst(j -> ks[j].kind == Kind.heading && heading_slug(heading_words(b, j)) == slug, 1:n)
  i === nothing || return heading_lines(b, i)
  # A kind and a number, like table 2
  m = match(r"^(\p{L}[\p{L}\p{N}_+-]*)\s*(\d*)$", part)
  m === nothing && return nothing
  want, nth = lowercase(m[1]), isempty(m[2]) ? 1 : parse(Int, m[2])
  want = get(Dict("paragraphs" => "paragraph", "headings" => "heading", "lists" => "list", "quotes" => "quote",
                  "tables" => "table", "pictures" => "picture", "image" => "picture"), want, want)
  fits = [(s, t) for (kind, lang, s, t) in found if kind == want || (kind in ("code", "block") && lowercase(lang) == want)]
  1 <= nth <= length(fits) ? fits[nth] : nothing
end

"The words of the heading on line `i`, without its #s and without the name of its block"
heading_words(b::Buffer, i::Int) = begin
  text = rest(b.lines[i], kinds(b)[i].prefix)
  block_id(text) === nothing ? text : rstrip(text[1:prevind(text, findlast(==('^'), text))])
end

"The heading on line `i` and the lines under it, up to the next heading that's as big or bigger, without the empty lines at the end"
heading_lines(b::Buffer, i::Int) = begin
  ks, n = kinds(b), length(b.lines)
  t = i
  while t < n && !(ks[t+1].kind == Kind.heading && ks[t+1].level <= ks[i].level); t += 1 end
  while t > i && isempty(strip(b.lines[t])); t -= 1 end
  (i, t)
end

"What line `i` shows when it holds a link to a part of another page. It's the `n`th such line of the page."
transclusion_item(e, i, n) = begin
  v = get!(Transclusion, e.nodes, (:part, e.buf.path, n))
  own!(node!(Document, e, :document), v)
  v.line = i
  show_part!(v, e, String(strip(match(TRANSCLUSION, e.buf.lines[i])[1])))
  Live(v, part_tall(v) + 2LIVE_GAP)
end

"How tall a part of another page is on the page that shows it, with the room over it for its button"
part_tall(v::Transclusion) = isempty(v.note) ? PART_TAB + v.tall : v.tall

"""
Find the part that `target`, like "Ideas#Plans", names, and lay out its lines
for the page of `e`. While the part's editor has the keyboard, the part keeps
the lines that it has, with the lines that typing adds, so a heading that's
being renamed doesn't make it go.
"""
show_part!(v::Transclusion, e, target::String) = begin
  v.target = target
  name, part = occursin('#', target) ? String.(split(target, '#', limit=2)) : (target, "")
  name = String(strip(name))
  path = isempty(name) ? e.buf.path : wiki_path(e, name)
  shown = isempty(name) ? title(path) : name
  note(words) = (v.note = words; v.tall = PART_NOTE_H; v)
  isfile(path) || return note("There's no page called $shown")
  ismarkdown(path) || return note("Only a page of Markdown can show a part of itself here")
  path in host_paths(e) && return note("A page can't show a part of itself")
  length(host_paths(e)) >= DEEPEST_PART && return note("Parts of pages show inside each other too deeply to show $shown here")
  if v.sub === nothing || v.path != path
    v.sub = part_editor(e, path)
    setfield!(v.sub, :parent, v)
  end
  v.path = path
  sub = v.sub
  b = sub.buf
  refresh!(b)   # a change that something else made to the other page's file shows here too
  w = window_of(e)
  typing = w !== nothing && w.focus === sub
  kept = get(sub.nodes, :kept, nothing)
  span = if typing && kept !== nothing
    # Every change while it types is in the part, so its last line moves down as lines are added
    (s, t), had = kept
    s <= length(b.lines) ? (s, clamp(t + length(b.lines) - had, s, length(b.lines))) : nothing
  else
    transclusion_lines(b, part)
  end
  span === nothing && return note("$shown has no $(isempty(part) ? "lines" : part)")
  v.note = ""
  sub.nodes[:span] = span
  sub.nodes[:kept] = (span, length(b.lines))
  # While no part of this page has the other page's caret, every line of the part shows as it reads
  (w !== nothing && w.focus isa Editor && w.focus.buf === b) || (b.reading = true; sub.plain = false)
  follow_host!(sub, e)
  layout!(sub, e.width)
  v.tall = isempty(sub.layout) ? 0px : lowest(sub, sub.layout)
  typing && sub.reveal && keep_shown!(v, e)
  v
end

"An editor of the page at `path`, for a part of it that the page of `e` shows. It edits the lines that the window has open for that page."
part_editor(e, path) = begin
  sub = Editor()
  sub.buffers = e.buffers
  sub.buf = get!(() -> load(path), e.buffers, path)
  sub.nodes[:input] = own!(sub, TextInput())
  sub.nodes[:host] = e
  sub
end

"Give the editor of a part the choices of the editor of the page that shows it: its colours, font, text size and keys"
follow_host!(sub, e) = begin
  for f in (:theme, :look, :font, :weight, :zoom, :code_scale, :code_font, :code_weight, :indent, :wrap, :spelling,
            :glide, :bundle, :rebound, :widest, :size, :autosave)
    setfield!(sub, f, getfield(e, f))
  end
  # Text that was laid out in another font or at another size is laid out again
  key = (e.theme, e.look, e.font, e.weight, e.zoom, e.code_scale, e.code_font, e.code_weight)
  get(sub.nodes, :style, nothing) == key || (sub.nodes[:style] = key; empty!(sub.flows))
  sub
end

"Scroll the page of `e` so that the caret of the part that `v` shows is in the window"
keep_shown!(v::Transclusion, e) = begin
  sub = v.sub
  sub.reveal = false
  b = sub.buf
  it = item(sub, b.caret[1])
  top, high = it.top, it.tall
  if it.content isa Flow
    k, _ = spot(it.content, b.caret[2])
    top, high = it.top + line_top(it.content, k), it.content.lines[k].high
  end
  # The page's own layout isn't done, so the place of the part on it is found after it is
  e.nodes[:show_part] = (v.line, top, high)
end

"Scroll the window's page to the caret of a part of another page that it shows, once the page is laid out"
reveal_part!(e) = begin
  kept = pop!(e.nodes, :show_part, nothing)
  (kept === nothing || isempty(e.layout)) && return
  line, top, high = kept
  at = item(e, line).top + LIVE_GAP + PART_TAB + top
  scroll_into_view!(e.scroll, PAGE_TOP + at - 30px, PAGE_TOP + at + high + 40px)
end

describe(v::Transclusion) = begin
  isempty(v.note) || return Row(width(grow=grow), height(v.tall), Alignment.Center, child_gap=6px,
    Icon("link-45deg", size=14px, color=colours.faint), Box(label(v.note, 13px, color=colours.dim)))
  doc = node!(Document, v.sub, :document)
  w = window_of(v)
  page = Box(width(grow=grow), height(part_tall(v)), Alignment.Start, padding(PART_TAB, 0px, 0px, 0px), doc)
  # The name of the page that the part comes from shows at its top right while the mouse is over it or it has the keyboard
  on = ishovered(v) || (w !== nothing && w.focus === v.sub)
  on || return page
  source = node!(() -> PartSource(of=v), v.sub, :source)
  Stack(width(grow=grow), height(part_tall(v)), Alignment.Start, page,
    Row(width(grow=grow), Alignment.Start, justify=Alignment.End, padding(0px, 6px, 0px, 0px), source))
end

"Draw a line round a part of another page while the mouse is over it or it has the keyboard"
draw(ctx, size, ui::ConcreteRect, v::Transclusion) = begin
  isempty(v.note) || return
  w = window_of(v)
  on = w !== nothing && w.focus === v.sub
  (on || ishovered(v)) || return
  top, high = num(ui.top) + num(PART_TAB), num(ui.height) - num(PART_TAB)
  round_box(ctx, num(ui.left) - RING_OUT, top - num(LIVE_GAP) + 2, num(ui.width) + 2RING_OUT, high + 2num(LIVE_GAP) - 4, 8.0,
            line=on ? tint(colours.accent, 0.75) : colours.line, wide=on ? 1.5 : 1.0)
  # The button that opens the other page sits on the line, so it's drawn again over the line
  for row in ui.children
    row isa ConcreteRect || continue
    for chip in row.children
      chip isa ConcreteRect && chip.from.from isa PartSource && draw(ctx, chip.size, chip)
    end
  end
end

# A click in the part's text is for its editor, which puts the caret there. A click that the part's editor didn't take,
# like one on the room round its text, puts this page's caret on the part as a whole.
onkey(v::Transclusion, ev::KeyPress{Keys.mouse_left}) =
  (w = ev.window; v.sub !== nothing && (w.focus === v.sub || only_held(w, Keys.opt)) ? handled : click_page!(v, ev))
# A key that the part's editor had is done with: it isn't for this page too
onkey(::Transclusion, ::KeyPress) = handled
onmouse(::Transclusion, ::MouseMove) = handled

describe(c::LiveCover) = Box(width(grow=grow), height(c.tall))
onkey(::LiveCover, ::KeyPress{Keys.mouse_left}) = handled
onmouse(::LiveCover, ::MouseMove) = handled
cursor(::LiveCover) = :arrow

"What covers the live block that `it` shows in the part of another page that `e` edits"
live_cover(e, it::Item) = (c = node!(LiveCover, e, (:cover, it.first)); c.tall = it.content.tall - 2LIVE_GAP; c)

describe(s::PartSource) = begin
  v = s.of
  Row(height(18px), padding(7px, 0px), child_gap=4px, radius(9px), Alignment.Center,
      background(ishovered(s) ? colours.active : colours.bg), border(1px, :solid, colours.line),
    Box(label(splitext(basename(v.path))[1], 11px, color=colours.dim)), Icon("box-arrow-up-right", size=10px, color=colours.dim))
end
cursor(::PartSource) = :hand
onkey(s::PartSource, ::KeyPress{Keys.mouse_left}) = (open_part!(s.of); handled)
onmouse(::PartSource, ::MouseMove) = handled

"Show the page that `v` shows a part of, with the part's first line near the top of the window"
open_part!(v::Transclusion) = begin
  top = top_editor(editor(v))
  s = v.sub === nothing ? 1 : get(v.sub.nodes, :span, (1, 1))[1]
  open!(top, v.path)
  show_line!(top, s)
  top.nodes[:hold] = (s, 24px - PAGE_TOP)
  top
end

"""
Give the keyboard to the part that `v` shows, with its caret at the start of
the part's first line, or at `at` in the other page's lines.
"""
enter_shown!(v::Transclusion, at=nothing) = begin
  sub = v.sub
  (sub === nothing || !isempty(v.note)) && return nothing
  b = sub.buf
  s, t = sub.nodes[:span]
  b.reading = false
  b.caret = b.anchor = settle(b, something(at, (s, 0)), 1)
  confine!(sub)
  focus(sub)
  touch!(sub)
  sub
end

"""
Give the keyboard back to the page that shows the part that `e` edits. Its
caret goes onto the part as a whole, or with `by` of -1 or 1 on to the line
over the part or under it.
"""
leave_part!(e, by::Int=0) = begin
  host = hosted(e)
  v = getfield(e, :parent)
  e.buf.reading = true
  e.plain = false
  hb = host.buf
  hb.caret = hb.anchor = (v.line, 0)
  focus(host)
  touch!(host)
  w = window_of(host)
  by == 0 || w === nothing || run!(host, w, by < 0 ? :up : :down)
  host
end

"Commands for the window that leave the keyboard in the part of another page that has it"
const KEEP_PART = (:save, :bigger, :smaller, :usual_size, :inspector, :sidebar, :hidden_files, :settings, :commands)

"""
What a key does in a part of another page before the part's editor does what
it does with a key. True when the key is done with. A command for the window
runs in the window's own page. ⌘E shows the part's lines as they're written.
"""
part_key!(e, w, K, command, select) = begin
  b = e.buf
  s, t = e.nodes[:span]
  kind = command === nothing ? :none : COMMANDS[command].kind
  K == Keys.escape && unmodified(w) && return (leave_part!(e); true)
  if command == :plain
    e.plain = !e.plain
    return true
  end
  if kind == :window || command in (:find, :find_next, :find_last)
    if !(command in KEEP_PART)
      f = e
      while hosted(f) !== nothing; f = leave_part!(f) end
    end
    run!(top_editor(e), w, command, select)
    return true
  end
  # ↑ on the first line and ↓ on the last go on to the page that shows the part
  if command in (:up, :down) && !select && isempty(others(b))
    by = command == :up ? -1 : 1
    p = vertical(e, by)
    (p[1] < s || p[1] > t || p == b.caret) && return (leave_part!(e, by); true)
  end
  # A key that would join the part's first line to the line over it, or its last line to the line under it, does nothing
  if !selecting(b) && ((command in (:erase_back, :erase_word_back, :erase_line_start) && b.caret == (s, 0)) ||
                       (command in (:erase, :erase_word) && b.caret == line_end(b, t)))
    return true
  end
  # A live block in the part is only shown: the caret can be on it as a whole, and nothing changes it
  picked(b) !== nothing && (K == Keys.enter || kind in (:edit, :type))
end

"""
Copy a link that shows the block at the caret in another page, like
![[Ideas#^prices]]. A block without a name gets one from its first words: at
the end of its last line, or on a line under a list, a table or a code block.
"""
copy_link_to_block!(e) = begin
  link = block_link!(e)
  link === nothing && return nothing
  clipboard(link)
  e.nodes[:result] = ("Copied $link", time())
  redraw_in!(e, 0)
  link
end
works_here(e, ::Val{:copy_link_to_block}) = e.buf.view == :markdown && !readonly(e.buf)

"The link that shows the block at the caret in another page, as `copy_link_to_block!` makes it, or nothing. The block gets a name if it has none."
block_link!(e) = begin
  b = e.buf
  (b.view == :markdown && !readonly(b) && !b.fixed && isfile(b.path)) || return nothing
  i = b.caret[1]
  found = transclusion_blocks(b)
  at = findfirst(x -> x[3] <= i <= x[4], found)
  at === nothing && return nothing
  _, _, s, t = found[at]
  # A heading's link shows the lines under it too
  kinds(b)[s].kind == Kind.heading && ((s, t) = heading_lines(b, s))
  name = node_name!(b, s, t)
  touch!(e)
  "![[$(title(b.path))#^$name]]"
end

"""
The block of `b` that lines `s` to `t` are the whole of, or nothing: a block
of the page, a heading with the lines under it, or an item of a list with the
lines indented under it. The front matter isn't one, and nor is a line that
already shows a part of another page.
"""
whole_node(b::Buffer, s::Int, t::Int) = begin
  (b.view == :markdown && front_matter(b.lines) < s <= t <= length(b.lines)) || return nothing
  ks = kinds(b)
  ks[s].kind == Kind.heading && return heading_lines(b, s) == (s, t) ? (s, t) : nothing
  found = transclusion_blocks(b)
  at = findfirst(x -> x[3] <= s <= x[4], found)
  at === nothing && return nothing
  kind, _, from, to = found[at]
  (kind == "picture" && transcludes(b, s)) && return nothing
  from == s && to == t && return (s, t)
  kind == "list" || return nothing
  last = s
  while last < to && ks[last+1].level > ks[s].level; last += 1 end
  last == t ? (s, t) : nothing
end

"""
The name of the block of `b` from line `s` to line `t`, which a link from
another page uses, like `prices` in ![[costs#^prices]]. A block without one
gets one from the first words of its first line: at the end of the line of a heading or an item
of a list, at the end of a paragraph's last line, or on a line under anything
else. The caret stays where it was in the text.
"""
node_name!(b::Buffer, s::Int, t::Int) = begin
  ks = kinds(b)
  found = transclusion_blocks(b)
  at = findfirst(x -> x[3] == s, found)
  kind, lang = at === nothing ? ("item", "") : found[at][1:2]
  ks[s].kind == Kind.heading && (kind = "heading")
  kind == "list" && found[at][4] != t && (kind = "item")
  ends = kind in ("heading", "item") ? s : kind == "paragraph" ? t : 0
  name = ends > 0 ? block_id(b.lines[ends]) : nothing
  # A name on a line under the block names it too, but not a heading's lines or an item's: that's the name of their last block
  under = kind in ("heading", "item") || t == length(b.lines) || !only_id(b.lines[t+1]) ? nothing : block_id(b.lines[t+1])
  name = something(name, under, Some(nothing))
  name === nothing || return name
  words = kind in ("code", "block") ? [isempty(lang) ? "code" : lang] :
          kind in ("table", "picture") ? [kind] :
          first(split(lowercase(replace(b.lines[s], r"[^\p{L}\p{N}\s]" => " "))), 4)
  words = first(filter(w -> !isempty(w) && w != "x", String.(words)), 3)
  base = isempty(words) ? kind : join(words, '-')
  taken = Set(something(block_id(l), "") for l in b.lines)
  name, k = base, 1
  while name in taken; k += 1; name = "$base-$k" end
  caret, anchor = b.caret, b.anchor
  if ends > 0
    edit!(b, line_end(b, ends), line_end(b, ends), " ^" * name)
    b.caret, b.anchor = caret, anchor
  else
    edit!(b, line_end(b, t), line_end(b, t), "\n^" * name)
    moved(p) = p[1] > t ? (p[1] + 1, p[2]) : p
    b.caret, b.anchor = moved(caret), moved(anchor)
  end
  name
end

# --- a block that's copied pastes as a part of its page --------------------------------------
#
# Copy a whole block of a page and paste it into another page, and the other
# page gets a line like ![[costs#^prices]]: a part of the first page, which
# you type in, and not a copy of its lines. The block gets a name if it has
# none. A block is copied whole while the caret is on it as a whole, after a
# click with ⌘ and ⌥ down chose it, or when the selection runs from its start
# to its end. A heading with the lines under it is one block, and so is an
# item of a list with the lines indented under it. ⌘⇧V pastes the lines
# instead. A paste in the page that the block came from pastes its lines too,
# and so does a block that's cut, since a cut block leaves its page.

"The block that Ladder last copied whole: the text that it put on the clipboard, the lines of the page that the block is in, the block's lines and its first and last line"
const COPIED_BLOCK = Ref{Any}(nothing)

"Put `text` on the clipboard. A window that isn't on the screen keeps it to itself, so a test leaves the Mac's clipboard alone."
copy_text!(e, text) = (w = window_of(e); w === nothing ? clipboard(text) : clipboard!(w, text); text)

"Note what was just copied: `text`, from the selection `span` of the page of `e`. A whole block is kept, for a paste in another page."
copied!(e, span, text) = begin
  COPIED_BLOCK[] = nothing
  b = e.buf
  (span === nothing || b.view != :markdown || !isfile(b.path) || Eml.isemail(b.path)) && return nothing
  lo, hi = span
  s, t = lo[1], hi[1]
  hi[2] == 0 && t > s && (t -= 1)   # a selection that ends at the start of the next line
  # It starts no later than the first line's words start, and goes to the end of its last line
  (lo[2] <= kinds(b)[s].prefix && (hi[1] > t || hi[2] >= length(b.lines[t]))) || return nothing
  whole_node(b, s, t) === nothing && return nothing
  COPIED_BLOCK[] = (text=String(text), buf=b, lines=b.lines[s:t], first=s, last=t)
end

"""
The line that shows the block that Ladder last copied whole, when `text` is
what it copied and the page of `e` is another page, or nothing. The block
gets a name in its own page if it has none. Its page is saved then if it had
no other changes, so that a window that reads the page from its file finds the name.
"""
pasted_part(e, text) = begin
  c = COPIED_BLOCK[]
  (c !== nothing && c.text == text) || return nothing
  b, src = e.buf, c.buf
  (b.view == :markdown && !readonly(b) && !b.fixed && b.path != src.path && isfile(src.path)) || return nothing
  # The block is on the lines that it was copied from, or it's found again in its page
  s, t = c.first, c.last
  n = t - s
  if !(t <= length(src.lines) && src.lines[s:t] == c.lines)
    k = findfirst(i -> i + n <= length(src.lines) && src.lines[i:i+n] == c.lines, eachindex(src.lines))
    k === nothing && return nothing
    s, t = k, k + n
  end
  whole_node(src, s, t) === nothing && return nothing
  clean = !dirty(src)
  name = node_name!(src, s, t)
  clean && dirty(src) && save!(src)
  "![[$(page_name_for(e, src.path))#^$name]]"
end

"Put `link`, a line that shows a part of another page, on a line of its own: on the empty line that the caret is on, or under the block that it's in. The caret goes onto the part as a whole."
paste_part!(e, link) = begin
  b = e.buf
  selecting(b) && type!(e, "")
  i = b.caret[1]
  if isempty(strip(b.lines[i]))
    edit!(b, (i, 0), line_end(b, i), link)
  else
    under = block_end(b, i)
    after = under < length(b.lines) && !isempty(strip(b.lines[under+1])) ? "\n" : ""
    edit!(b, line_end(b, under), line_end(b, under), "\n\n" * link * after)
    i = under + 2
  end
  b.caret = b.anchor = (i, 0)
  focus(e)
  touch!(e)
end

"Paste what the clipboard holds as text: a block that was copied whole from another page goes in as a copy of its lines, not as a part of that page"
paste_copy!(e) = begin
  copied = COPIED_BLOCK[]
  COPIED_BLOCK[] = nothing
  try paste!(e) finally COPIED_BLOCK[] = copied end
end


"True when the Finder shows the folder at `path` as one file, as it shows an app"
ispackage(path) = with_pool() do
  ccall((:objc_msgSend, libobjc), Bool, (Ptr{Cvoid}, Ptr{Cvoid}, Ptr{Cvoid}),
        msg(cls("NSWorkspace"), "sharedWorkspace"), sel("isFilePackageAtPath:"), nsstring(path))
end

"""
Open a link. A file on the Mac shows in this editor, like a page, or a file
that came with an email. A folder on the Mac shows in the page, and the
sidebar lists it. Anything else opens in the app that the Mac uses for it. A path can start at the home folder, like `~/Mail`.
"""
follow!(e, url) = begin
  startswith(url, '^') && return follow_note!(e, url[2:end])
  isremote(e.buf.path) && return follow_remote!(e, url)   # a link of a page from a web server is from the page's address
  target = wikitarget(url)
  target === nothing || return follow_wiki!(e, target)   # a wiki link, like [[Ideas]]
  occursin('#', url) && follow_heading!(e, url) && return e   # a heading of a page, like welcome.md#tables
  path = abspath(docdir(e), expanduser(unescaped(url)))
  ispath(path) && return show_path!(e, path)
  # The address of a page of Markdown on a web server shows in the window: see "a page from a web server"
  reads_here(e, url) ? get_page!(e, url, else_browser=true) : open_url(url)
end

"""
Show the file or the folder at `path` in the window, as a link to it does.
The sidebar lists the folder, and it stays as it was: open or closed. Only
you open it. A folder that the Finder shows as one file, like an app, opens as
that file does.
"""
show_path!(e, path) = begin
  hosted(e) === nothing || return show_path!(top_editor(e), path)   # a link in a part of another page shows in the window
  isfile(path) && return open!(e, path)
  (isdir(path) && !ispackage(path)) || return open_url(path)
  path = String(rstrip(path, '/'))
  # The folder's own page says its kind, and loads the code of the kind. It runs now if it hasn't, and
  # the rest goes on with that code.
  folder_pages!(path)
  Base.invokelatest(follow_folder!, e, path)
  e
end

"""
Do what a click on the folder at `path` does in the sidebar. A kind of folder
can show a page of its own, like a blog's Readme. When the click only lists the
folder in the sidebar, the page shows the folder too, so you see it with the
sidebar closed.
"""
follow_folder!(e, path) = begin
  folder_pages_tick!(e)   # the sidebar can have listed the folder before its page ran
  was = e.buf.path
  o = try object(e, path) catch; nothing end
  o isa AbstractDirectory ? open!(e, o) : go_folder!(e, path)
  e.buf.path == was && show_beside!(e, path)
  e
end

drag!(e, pos) = begin
  haskey(e.nodes, :scrub) && held(e, Keys.mouse_left) && return scrub_to!(e, pos)
  held(e, Keys.mouse_left) && e.clicked[3] == 1 || return
  at = settle(e.buf, locate(e, pos))
  at == e.buf.caret && return
  e.buf.caret = at
  touch!(e)
end

onkey(d::Document, ev::KeyPress{Keys.mouse_left}) = press!(editor(d), ev.window.mouse)
onkey(p::Page, ev::KeyPress{Keys.mouse_left}) = press!(editor(p), ev.window.mouse)
onmouse(d::Document, ev::MouseMove) = begin
  e = editor(d)
  Base.invokelatest(hover_check!, e, ev.position)
  # The window draws again as the mouse goes on to a footnote's number or off it, for its card: see `note_peek!`
  (haskey(e.nodes, :note_peek) || Base.invokelatest(note_at, e, ev.position) !== nothing) && redraw_in!(e, 0)
  drag!(e, ev.position)
end
onmouse(p::Page, ev::MouseMove) = drag!(editor(p), ev.position)

# --- editing -----------------------------------------------------------------------------

"Put `new` where the selection is, or at the caret"
type!(e, new; typing=false) = begin
  b = e.buf
  run = picked(b)
  if run !== nothing
    isempty(new) && return e
    # What's pasted or inserted while the caret is on a part as a whole goes on a line of its own under the part
    b.caret = b.anchor = line_end(b, run[2])
    new = "\n" * new
  end
  cell = cellat(b, b.caret)
  if cell !== nothing && b.caret[1] == b.anchor[1]
    # In a row of a table, typing only ever changes the cell the caret is in
    lo, hi = selection(b)
    (within(cell, lo[2]) && within(cell, hi[2])) || (b.anchor = b.caret)
    new = replace(new, '\n' => ' ')
  end
  lo, hi = selection(b)
  # A third ` that opens a code block. Inside a block it would close that block instead.
  fence = new == "`" && lo == hi && kinds(b)[lo[1]].kind != Kind.code && strip(b.lines[lo[1]]) == "``" && lo[2] == length(b.lines[lo[1]])
  if rich(b) && lo != hi
    # As rich text, the markup of text that's only partly selected stays, after what's typed
    from, to, kept = richcut(b, lo, hi, typed=!isempty(new))
    edit!(b, from, to, new * kept; typing)
    parts = split(new, '\n')
    b.caret = b.anchor = (from[1] + length(parts) - 1, length(parts) == 1 ? from[2] + length(new) : length(last(parts)))
  else
    edit!(b, lo, hi, new; typing)
  end
  if fence
    # The line that closes the block is typed too. Without it, the block would
    # take the line that opens the next block as its end, and turn every block
    # after it inside out.
    at = b.caret
    edit!(b, at, at, "\n```")
    b.caret = b.anchor = at
  end
  touch!(e)
end

line_end(b, i) = (i, length(b.lines[i]))

"The place one character of the file before or after `p`"
neighbour(b::Buffer, (i, col)::Pos, by::Int) =
  by < 0 ? (col > 0 ? (i, col - 1) : i > 1 ? line_end(b, i - 1) : (i, col)) :
           (col < length(b.lines[i]) ? (i, col + 1) : i < length(b.lines) ? (i + 1, 0) : (i, col))

"""
The place one character before or after `p`. As rich text that's one
character that shows: the place is past any markup that's in the way, and past
the whole of something that shows as one thing, like the number of a footnote.
"""
beside(b::Buffer, p::Pos, by::Int) = begin
  rich(b) || return neighbour(b, p, by)
  run = p == b.caret ? picked(b) : nothing
  # From a part that the caret is on as a whole, it's the end of the line before the part or the start of the line after it
  run === nothing || return by < 0 ? (run[1] > 1 ? line_end(b, run[1] - 1) : p) : (run[2] < length(b.lines) ? (run[2] + 1, 0) : p)
  i, col = p
  hidden, whole = unseen(b, i), wholes(b, i)
  if by < 0
    for (a, z) in hidden
      a < col <= z && (col = a)
    end
    col <= 0 && return neighbour(b, (i, 0), by)
    k = findfirst(r -> r[2] == col, whole)
    (i, k === nothing ? col - 1 : whole[k][1])
  else
    for (a, z) in hidden
      a <= col < z && (col = z)
    end
    col >= length(b.lines[i]) && return neighbour(b, line_end(b, i), by)
    k = findfirst(r -> r[1] == col, whole)
    (i, k === nothing ? col + 1 : whole[k][2])
  end
end

"The place one word before or after `p`"
word_step(b::Buffer, p::Pos, by::Int) = begin
  i, col = p
  chars = collect(b.lines[i])
  # As rich text, a line's text can start after characters that don't show, like the # of a heading
  (by < 0 ? col <= first_stop(b, i) : col == length(chars)) && return beside(b, p, by)
  if by < 0
    while col > 0 && !isword(chars[col]); col -= 1 end
    while col > 0 && isword(chars[col]); col -= 1 end
  else
    while col < length(chars) && !isword(chars[col+1]); col += 1 end
    while col < length(chars) && isword(chars[col+1]); col += 1 end
  end
  (i, col)
end

"The place one line up or down the screen from the caret, in the order of the page's lines. `vertical` keeps it in a column of the page."
line_step(e, by::Int) = begin
  b = e.buf
  i, col = b.caret
  run = picked(b)
  if run !== nothing
    # From a part that the caret is on as a whole, ↑ goes to the line before the part and ↓ to the line after it
    j = by > 0 ? run[2] + 1 : run[1] - 1
    j < 1 && return b.caret
    if j > length(b.lines)
      # ↓ on a part at the end of the document starts a line below it, as it does under a table
      edit!(b, line_end(b, length(b.lines)), line_end(b, length(b.lines)), "\n")
      return (length(b.lines), 0)
    end
    x = e.goal = something(e.goal, 0px)
    free(b, j, 0) || return by > 0 ? (j, 0) : line_end(b, j)
    into = item(e, j)
    into.content isa Sheet && return enter(e, into, into.content, by, x)
    f = flow(e, j, false)
    return (j, colat(f, by < 0 ? length(f.lines) : 1, x))
  end
  it = item(e, i)
  at = it.content isa Grid ? gridcell(it.content, b.caret) : nothing
  at === nothing || return vertical(e, it, at, by)
  it.content isa Sheet && return vertical(e, it, it.content, by)
  f = flow(e, i)
  k, x = spot(f, col)
  x = e.goal = something(e.goal, x)
  1 <= k + by <= length(f.lines) && return (i, colat(f, k + by, x))
  j = i + by
  if rich(b)
    # As rich text, the caret steps over a line that doesn't show, like the ``` of a code block
    j = step_over(b, j, by, i)
    if j > length(b.lines) && i < length(b.lines)
      # ↓ over such a line at the end of the document starts a line below it, as it does under a table
      edit!(b, line_end(b, length(b.lines)), line_end(b, length(b.lines)), "\n")
      return (length(b.lines), 0)
    end
    # It goes onto a part that shows as one thing, like a diagram, as a whole
    1 <= j <= length(b.lines) && !free(b, j, i) && return (j, 0)
  end
  j < 1 && return (1, 0)
  j > length(b.lines) && return line_end(b, i)
  # Into a sheet, the caret goes to the cell that's under it or over it
  into = item(e, j)
  into.content isa Sheet && return enter(e, into, into.content, by, x)
  # The line is laid out as it will show with the caret on it. A line of text shows little of its markup as plain text, so it's laid out as it reads.
  f = flow(e, j, b.plain && !by_runs(b, j))
  (j, colat(f, by < 0 ? length(f.lines) : 1, x))
end

"The place one line up or down from the caret, which is in row `r`, column `c` of a table"
vertical(e, it::Item, (r, c), by::Int) = begin
  b = e.buf
  g = it.content::Grid
  f = g.flows[r][c]
  k, x = spot(f, b.caret[2])
  x = e.goal = something(e.goal, x)
  1 <= k + by <= length(f.lines) && return (b.caret[1], cellcol(f, k + by, x, g.cells[r][c]))
  r += by
  if r < 1
    return it.first > 1 ? line_end(b, it.first - 1) : b.caret
  elseif r > length(g.rows)
    # ↓ on the last row of a table at the end of the document starts a line below it
    it.last == length(b.lines) && edit!(b, line_end(b, it.last), line_end(b, it.last), "\n")
    return (it.last + 1, 0)
  end
  isempty(g.cells[r]) && return (g.rows[r], 0)
  c = min(c, length(g.cells[r]))
  f = g.flows[r][c]
  (g.rows[r], cellcol(f, by < 0 ? length(f.lines) : 1, x, g.cells[r][c]))
end

"The start or end of the line of the screen that the caret is on"
screen_edge(e, by::Int) = begin
  cell = cellat(e.buf, e.buf.caret)
  cell === nothing || return (e.buf.caret[1], by < 0 ? cell.lo : cell.hi)
  i, col = e.buf.caret
  f = flow(e, i)
  k, _ = spot(f, col)
  vl = f.lines[k]
  by < 0 ? (i, vl.from) : (i, k < length(f.lines) ? max(vl.from, vl.to - 1) : vl.to)
end

"""
Where a selection that grows to `p` ends. It steps over the ``` lines of a code
block that the selection didn't start in, and over the whole of a block that
shows as one thing, like a diagram or a contact, because those lines don't show.
"""
pass(b::Buffer, p::Pos, by::Int) = begin
  ks = kinds(b)
  i = p[1]
  ks[i].kind in (Kind.fence, Kind.code) || return p
  s, t = codeblock(b, i)
  s <= b.anchor[1] <= t && return p
  whole = solid(b, i)
  if whole !== nothing && whole[1] < whole[2]
    # Under a block that ends the document there's no line to go to, so the selection ends where the block does
    by > 0 && whole[2] == length(b.lines) && return line_end(b, whole[2])
    i = by < 0 ? whole[1] - 1 : whole[2] + 1
  elseif ks[i].kind == Kind.fence
    i += by
  else
    return p
  end
  1 <= i <= length(b.lines) || return p
  by < 0 ? line_end(b, i) : (i, 0)
end

"Move the caret to `p`, which was reached by going in the direction `by`. With `extend`, the selection grows to it."
move!(e, p::Pos, extend::Bool; keep_goal=false, by=0) = begin
  p = settle(e.buf, p, by)
  extend && by != 0 && (p = pass(e.buf, p, by))
  e.buf.caret = p
  extend || (e.buf.anchor = p)
  touch!(e; keep_goal)
end

erase!(e, to::Pos) = begin
  b = e.buf
  picked(b) === nothing || return delete_lines!(e)   # the part that the caret is on as a whole goes
  insheet(b, b.caret[1]) && !selecting(b) && erase_row!(e, to) && return
  cell = cellat(b, b.caret)
  # In a table, a cell's edges can't be deleted
  cell === nothing || selecting(b) || (to[1] == b.caret[1] && within(cell, to[2])) || return
  selecting(b) || (b.anchor = to)
  type!(e, "")
end

"Return starts a new line. What else it does depends on the block the caret is in."
newline!(e) = begin
  b = e.buf
  picked(b) === nothing || return enter_part!(e)   # Return gives the keyboard to the part that the caret is on
  insheet(b, b.caret[1]) && b.caret[1] == b.anchor[1] && return next_row!(e)
  isempty(rowcells(b, b.caret)) || return next_cell!(e, false, down=true)
  selecting(b) ? type!(e, "\n") : newline!(e, block(b, b.caret[1]))
end

newline!(e, block) = begin
  b = e.buf
  i, col = b.caret
  if rich(b) && kinds(b)[i].kind == Kind.heading && col <= first_stop(b, i) < length(b.lines[i])
    # As rich text, Return at the start of a heading's text moves the heading down a line
    edit!(b, (i, 0), (i, 0), "\n")
    b.caret = b.anchor = (i + 1, col)
    return touch!(e)
  end
  shut, opened = halves!(b)
  type!(e, shut * "\n" * opened)
end

# In a list or a quote, the new line carries it on
newline!(e, ::Type{<:Union{List,Quote,Paragraph}}) = begin
  b = e.buf
  i, col = b.caret
  text, line = b.lines[i], kinds(b)[i]
  k = line.kind
  col < line.prefix && return type!(e, "\n")
  lead = head(text, line.prefix)
  # The line after the one that names a callout is a line of the callout: it starts with the > and no more
  if opens_callout(line)
    shut, opened = halves!(b)
    return type!(e, shut * "\n> " * opened)
  end
  # Return on an empty list item ends the list
  # What starts the item goes as it's written. As rich text, a selection that's
  # deleted keeps what starts its line, so `type!` would leave the item there.
  if length(text) == line.prefix && k != Kind.paragraph
    edit!(b, (i, 0), (i, line.prefix), "")
    return touch!(e)
  end
  # As rich text, bold text that the new line cuts in two is bold on both lines
  shut, opened = halves!(b)
  type!(e, shut * "\n" * carry(lead, k) * opened)
end

"What starts the line after a list item or a quote that starts with `lead`: the next number, or a to-do box with no tick"
carry(lead, k::Kind) = begin
  k == Kind.todo && return replace(lead, r"\[[xX]\]" => "[ ]")
  m = k == Kind.ordered ? match(r"^(\s*)(\d+)(.*)$", lead) : nothing
  m === nothing ? lead : string(m[1], parse(Int, m[2]) + 1, m[3])
end

# In code, the new line starts under the text of the line before. It starts
# one step further in after a line that opens a block.
newline!(e, ::Type{CodeBlock}) = begin
  b = e.buf
  i, col = b.caret
  line = kinds(b)[i]
  if line.kind == Kind.fence && line.level == 0 && line.lang == SHEET && col == length(b.lines[i])
    # The line that opens a sheet. Its first row starts with a place for a name.
    type!(e, "\n = ")
    b.caret = b.anchor = (i + 1, 0)
    return touch!(e)
  end
  if line.kind == Kind.fence && line.level == 0 && line.lang == SPREADSHEET && col == length(b.lines[i])
    # The line that opens a spreadsheet. Its first row starts with three cells, and the caret goes to the first.
    type!(e, "\n|  |  |  |")
    b.caret = b.anchor = (i + 1, 2)
    return touch!(e)
  end
  line.kind == Kind.fence && return type!(e, "\n")
  before = head(b.lines[i], col)
  type!(e, "\n" * match(r"^ *", before).match * (opens(before, line.lang) ? indentation(e, CodeBlock) : ""))
end

const STEP = "  "   # one step of indentation
const OPENERS = r"^\s*(function|if|elseif|else|for|while|let|try|catch|finally|struct|mutable struct|module|macro|quote)\b"

"True when a line of code that ends with `text` opens a block, so the next line goes further in"
opens(text::AbstractString, lang::AbstractString) = begin
  s = rstrip(text)
  isempty(s) && return false
  last(s) in "([{" && return true
  lowercase(lang) in ("python", "py") && return last(s) == ':'
  lowercase(lang) in ("julia", "jl", LIVE) || return false
  occursin(r"\b(begin|do( [\w, ]+)?)$", s) || (occursin(OPENERS, s) && !occursin(r"\bend$", s))
end

"Where backspace deletes back to from the caret: one character, or one step of `n` of the spaces that start a line"
backstep(b::Buffer, block, n=length(STEP)) = begin
  i, col = b.caret
  indented = col > 0 && !selecting(b) && all(==(' '), head(b.lines[i], col))
  indented ? (i, col - (col - 1) % n - 1) : beside(b, b.caret, -1)
end

# In a table the spaces belong to a cell
backstep(b::Buffer, ::Type{Table}, n=0) = beside(b, b.caret, -1)

# In code, a bracket that you type comes with the bracket that closes it, and
# the caret stays between the two. A quote comes with the quote that ends the
# string. This is so in a file of code and in a code block of a page.
#
#   - The closing one only comes where it can't join a word: at the end of the
#     line, or before a space, a comma or another closing bracket.
#   - A closing bracket or a quote that you type where the same one already is
#     goes over that one. So `f(x)` typed one key after another is `f(x)`.
#   - With text selected, a bracket or a quote goes round the text, and the
#     text stays selected.
#   - A quote that's typed in a string ends the string, and comes alone. A ' after
#     a name is Julia's transpose, or the ' of a word like "don't", and comes alone too.
#   - A third quote after two makes the six quotes of a string of several lines.
#   - ⌫ between the two of a pair that has nothing in it takes both away.

const PAIRS = Dict('(' => ')', '[' => ']', '{' => '}', '"' => '"', '\'' => '\'')
const CLOSING = Set(values(PAIRS))

"True when line `i` is code that's typed as text. A row of a sheet or a spreadsheet is typed as a cell."
typed_code(b::Buffer, i::Int) = kinds(b)[i].kind == Kind.code && !insheet(b, i) && !inspread(b, i)

"How many quotes in `text` start or end a string. One after a \\ is a character of its string."
quotes(text::AbstractString) = count(r"(?<!\\)\"", text)

"True when line `i` up to `before` is inside a string of several lines: an odd number of \"\"\" come before it in its code"
in_long_string(b::Buffer, i::Int, before::AbstractString) = begin
  top = b.view == :code ? 1 : codeblock(b, i)[1] + 1
  isodd(sum(l -> count("\"\"\"", l), @view(b.lines[top:i-1]), init=0) + count("\"\"\"", before))
end

"""
Type the character `c` at the caret, as code does: a bracket or a quote comes
with the one that closes it. It returns false, and types nothing, where `c` is
typed as any other character is.
"""
pair!(e, c::Char) = begin
  b = e.buf
  picked(b) === nothing || return false
  lo, hi = minmax(b.caret, b.anchor)
  all(i -> typed_code(b, i), lo[1]:hi[1]) || return false
  close = get(PAIRS, c, nothing)
  if lo != hi
    # A bracket or a quote goes round the text that's selected, and the text stays selected
    close === nothing && return false
    back = b.caret < b.anchor
    edit!(b, lo, hi, c * excerpt(b, lo, hi) * close)
    from, to = (lo[1], lo[2] + 1), (hi[1], hi[2] + (lo[1] == hi[1]))
    b.anchor, b.caret = back ? (to, from) : (from, to)
    touch!(e)
    return true
  end
  i, col = lo
  before, after = head(b.lines[i], col), rest(b.lines[i], col)
  next = isempty(after) ? nothing : first(after)
  if next == c && c in CLOSING
    # The one that closes is already here, so the caret goes over it
    b.caret = b.anchor = (i, col + 1)
    touch!(e)
    return true
  end
  close === nothing && return false
  # Before a word, the one that closes would have to be moved to the word's end by hand
  roomy = next === nothing || isspace(next) || next in ")]},;:" || (c in "([{" && next == '"')
  roomy || return false
  if c == '"' && endswith(before, "\"\"") && !endswith(before, "\"\"\"")
    # The third quote of three. It starts a string of several lines, or it ends the one that the caret is in.
    in_long_string(b, i, chop(before, tail=2)) && return false
    close = "\"\"\""
  elseif c == '"'
    isodd(quotes(before)) && return false   # this quote ends a string
  elseif c == '\'' && !isempty(before)
    prev = last(before)
    (isnamechar(prev) || prev in ")]}'") && return false
  end
  edit!(b, lo, lo, c * close, typing=true)
  b.caret = b.anchor = (i, col + 1)
  touch!(e)
  true
end

"True when the caret is in code between a bracket or a quote and the one that closes it, with nothing between them"
in_empty_pair(b::Buffer) = begin
  i, col = b.caret
  line = b.lines[i]
  (!selecting(b) && 0 < col < length(line) && typed_code(b, i)) || return false
  at = nextind(line, 0, col)
  get(PAIRS, line[at], nothing) == line[nextind(line, at)]
end

# In code, the two brackets that the caret is between glow: the nearest ( [
# or { before the caret that's still open there, and the bracket that closes
# it. The two can be on different lines. Each has a soft light in its own
# shape, in the colour of a link, and two that touch have one light.
#
#   - A bracket in a string or a comment isn't one of the code's brackets. With
#     the caret in a string or a comment, the brackets are the ones in the
#     strings or the comments of the caret's line.
#   - A bracket that's closed by another kind of bracket doesn't glow.
#   - Nothing glows while text is selected.

const PAIR_REACH = 2000   # lines. A bracket that's further from the caret than this isn't looked for.
const OPENING, ENDING = "([{", ")]}"

"What each character of line `i` is a part of: :code, :string or :comment"
parts_of(b::Buffer, i::Int) = begin
  out = Symbol[]
  for t in tokens(b.lines[i], shared_lang(kinds(b)[i].lang))
    append!(out, fill(t.kind in (:string, :comment) ? t.kind : :code, length(t.text)))
  end
  out
end

"""
The places of the two brackets that the caret is between, in code: the one that
opens and the one that closes. Nothing when the caret isn't between two.
"""
bracket_pair(b::Buffer) = begin
  i, col = b.caret
  (!selecting(b) && picked(b) === nothing && typed_code(b, i)) || return nothing
  here = parts_of(b, i)
  col = min(col, length(here))   # a caret that a change left past the end of its line is at the end
  before = col > 0 ? here[col] : :code
  after = col < length(here) ? here[col+1] : before == :comment ? :comment : :code
  # At the edge of a string, the caret is in the code
  part = before == after ? before : :code
  top, bottom = b.view == :code ? (1, length(b.lines)) : codeblock(b, i) .+ (1, -1)
  top, bottom = part == :code ? (max(top, i - PAIR_REACH), min(bottom, i + PAIR_REACH)) : (i, i)
  # The characters of line `l` that are brackets of the caret's part, or nothing when it has none
  brackets(l) = begin
    any(in("()[]{}"), b.lines[l]) || return nothing
    parts = l == i ? here : parts_of(b, l)
    [(k, c) for (k, c) in enumerate(b.lines[l]) if (c in OPENING || c in ENDING) && parts[k] == part]
  end
  open = nothing
  closed = Char[]   # the brackets between the caret and here that close one before here
  for l in i:-1:top
    found = brackets(l)
    found === nothing && continue
    for (k, c) in Iterators.reverse(found)
      l == i && k > col && continue
      if c in ENDING
        push!(closed, c)
      elseif isempty(closed)
        open = (l, k - 1, c)
        break
      elseif closed[end] == PAIRS[c]
        pop!(closed)
      end
    end
    open === nothing || break
  end
  open === nothing && return nothing
  opened = Char[]   # what closes the brackets that open between the caret and here
  for l in i:bottom
    found = brackets(l)
    found === nothing && continue
    for (k, c) in found
      l == i && k <= col && continue
      if c in OPENING
        push!(opened, PAIRS[c])
      elseif isempty(opened)
        return c == PAIRS[open[3]] ? ((open[1], open[2]), (l, k - 1)) : nothing
      elseif opened[end] == c
        pop!(opened)
      end
    end
  end
  nothing
end

"The two brackets that the caret is between. They're looked for once for each place of the caret in each version of the text."
caret_pair(e) = begin
  b = e.buf
  key = (b.path, b.version, b.caret, b.anchor)
  kept = get(e.nodes, :bracket_pair, nothing)
  kept !== nothing && kept[1] == key && return kept[2]
  found = bracket_pair(b)
  e.nodes[:bracket_pair] = (key, found)
  found
end

"""
The runs of text that glow for the two brackets at `found`: the line of each,
and its columns. Two brackets with nothing between them are one run, so they
have one light.
"""
bracket_runs((open, close)) =
  open[1] == close[1] && close[2] == open[2] + 1 ? [(open[1], open[2], open[2] + 2)] : [(i, col, col + 1) for (i, col) in (open, close)]

"""
Make the two brackets that the caret is between glow: a soft light in the shape
of each bracket, and the bracket over it in the light's colour. The page's text
is at `ui`.
"""
glow_bracket_pair(ctx, e, ui) = begin
  b = e.buf
  (caretless(b) || readonly(b)) && return
  w = window_of(e)
  (w !== nothing && w.focus === e) || return   # as the caret does, the light shows while the page has the keyboard
  found = caret_pair(e)
  found === nothing && return
  light, lit = ink(tint(colours.accent, 0.65)), ink(colours.accent)
  blur = Skia.sk_maskfilter_new_blur_with_flags(Skia.SK_BLUR_STYLE_NORMAL, 3f0, true)
  Skia.sk_paint_set_maskfilter(light, blur)
  for it in e.layout[e.shown], (i, from, to) in bracket_runs(found)
    f = it.content
    (f isa Flow && it.first == i) || continue
    for (k, vl) in enumerate(f.lines), seg in vl.segs
      lo, hi = max(from, seg.col), min(to, seg.col + seg.n)
      (hi > lo && seg.node === nothing && !seg.atomic) || continue
      words = String(collect(seg.text)[lo-seg.col+1:hi-seg.col])
      x = num(ui.left + seg.x + inset(seg, lo - seg.col))
      # The brackets stand on the line that the text stands on
      y = num(ui.top + it.top + line_top(f, k) + (vl.high + capital(seg.face)) / 2)
      blob = Skia.sk_textblob_make_from_string(words, skia_font(seg.face.family, seg.face.size, seg.face.style).raw, Skia.SK_TEXT_ENCODING_UTF8)
      # The light is drawn twice, since a bracket is thin
      for paint in (light, light, lit)
        Skia.sk_canvas_draw_text_blob(ctx, blob, Float32(x), Float32(y), paint)
      end
      Skia.sk_textblob_unref(blob)
    end
  end
  Skia.sk_maskfilter_unref(blur)
  Skia.sk_paint_delete(light)
  Skia.sk_paint_delete(lit)
end

"Tab moves text in, and shift-Tab moves it back out. What they move depends on the block the caret is in."
indent!(e, out::Bool) = begin
  b = e.buf
  insheet(b, b.caret[1]) && return sheet_tab!(e, out)
  isempty(rowcells(b, b.caret)) || return next_cell!(e, out)
  indent!(e, out, block(b, b.caret[1]))
end

indent!(e, out::Bool, block) = out ? nothing : type!(e, STEP)

# In code, Tab goes to the next step. With a selection, or with shift, it moves every line the selection touches.
indent!(e, out::Bool, ::Type{CodeBlock}) = begin
  b = e.buf
  tab = indentation(e, CodeBlock)   # as many spaces as the settings page says
  out || selecting(b) || return type!(e, " " ^ (length(tab) - b.caret[2] % length(tab)))
  ends = Dict(:caret => b.caret, :anchor => b.anchor)
  lo, hi = minmax(b.caret, b.anchor)
  for i in lo[1]:hi[1]
    kinds(b)[i].kind == Kind.code || continue
    n = out ? min(length(tab), length(match(r"^ *", b.lines[i]).match)) : length(tab)
    isempty(b.lines[i]) && continue
    edit!(b, (i, 0), (i, out ? n : 0), out ? "" : tab)
    for (name, (l, col)) in ends
      l == i && (ends[name] = (i, max(0, col + (out ? -n : n))))
    end
  end
  b.caret, b.anchor = ends[:caret], ends[:anchor]
  touch!(e)
end

# In a list, Tab moves the item in and shift-Tab moves it back out
indent!(e, out::Bool, ::Type{List}) = begin
  b = e.buf
  i, col = b.caret
  selecting(b) && return out ? nothing : type!(e, STEP)
  n = out ? min(2, kinds(b)[i].level) : 2
  edit!(b, (i, 0), (i, out ? n : 0), out ? "" : "  ")
  b.caret = b.anchor = (i, max(0, col + (out ? -n : n)))
  touch!(e)
end

"""
Go to the next cell of a table and select what's in it, or with `back` the one
before. With `down`, go to the same cell of the next row. Going on from the end
of the table adds a row.
"""
next_cell!(e, back::Bool; down=false) = begin
  b = e.buf
  i, col = b.caret
  rows = gridrows(b, i)
  r = findfirst(==(i), rows)
  cs = rowcells(b, b.caret)
  c = nearest(cs, col)
  if down
    r += 1
  elseif back
    c -= 1
    c < 1 && (r -= 1; c = 0)
  else
    c += 1
    c > length(cs) && (r += 1; c = 1)
  end
  r < 1 && return
  if r > length(rows)
    t = last(rows)
    edit!(b, line_end(b, t), line_end(b, t), "\n|" * repeat("  |", maximum(i -> length(rowcells(b, (i, 0))), rows)))
    push!(rows, t + 1)
  end
  cs = rowcells(b, (rows[r], 0))
  isempty(cs) && return move!(e, (rows[r], 0), false)
  cell = cs[c == 0 ? length(cs) : min(c, length(cs))]
  b.anchor, b.caret = (rows[r], cell.lo), (rows[r], cell.hi)
  touch!(e)
end

"Put `mark` around the selection, or take it away if it's there already"
surround!(e, mark::String) = begin
  b = e.buf
  picked(b) === nothing || return
  lo, hi = selection(b)
  lo[1] == hi[1] || return
  if rich(b)
    # As rich text, each end of a selection can be on either side of markup that doesn't show. A selection
    # of all the text that `mark` marks is that text, whichever side its ends are on.
    _, ss = richspans(b, lo[1])
    hidden = unseen(b, lo[1])
    for (o, c) in markpairs(ss)
      ss[o].text == mark || continue
      from, to = ss[o].col + length(mark), ss[c].col
      opens = findfirst(r -> r[1] <= ss[o].col && from <= r[2], hidden)
      closes = findfirst(r -> r[1] <= to && to + length(mark) <= r[2], hidden)
      (opens === nothing || closes === nothing) && continue
      hidden[opens][1] <= lo[2] <= hidden[opens][2] && hidden[closes][1] <= hi[2] <= hidden[closes][2] || continue
      lo, hi = (lo[1], from), (hi[1], to)
      break
    end
  end
  i, n = lo[1], length(mark)
  line = b.lines[i]
  inner = rest(head(line, hi[2]), lo[2])
  if lo[2] >= n && rest(head(line, lo[2]), lo[2] - n) == mark && head(rest(line, hi[2]), n) == mark
    edit!(b, (i, lo[2] - n), (i, hi[2] + n), inner)
    b.anchor, b.caret = (i, lo[2] - n), (i, hi[2] - n)
  else
    edit!(b, lo, hi, mark * inner * mark)
    b.anchor, b.caret = (i, lo[2] + n), (i, hi[2] + n)
  end
  touch!(e)
end

"""
Copy what's selected. With several selections, each one's text goes on a line
of its own, in the order of the page. With none, the part that the caret is on
as a whole, like a board or a picture, is copied as its lines. A whole block
pastes in another page as a part of this one: see "a block that's copied
pastes as a part of its page".
"""
copy_selection!(e) = begin
  b = e.buf
  run = picked(b)
  (selecting(b) || run !== nothing) && write_blocks!(e)   # a block that a file defines is copied as what it holds now
  spans = selecting(b) ? [selection(b)] : Tuple{Pos,Pos}[]
  with_others(() -> selecting(b) && push!(spans, selection(b)), b)
  isempty(spans) && run !== nothing && push!(spans, ((run[1], 0), line_end(b, run[2])))
  isempty(spans) && return false
  text = join((excerpt(b, s...) for s in sort(spans)), "\n")
  copied!(e, length(spans) == 1 ? only(spans) : nothing, text)
  copy_text!(e, text)
end

"""
Put what the clipboard holds into the text at the caret. Files that were
copied in the Finder go in the way a dropped file does: a picture shows as a
picture, and a video, a sound, a PDF or any other file as a path that shows
what's in the file. A picture that was copied as itself, like a screenshot, is
written to a file in the media folder beside the document first. So is a PDF,
a sound or a video that was copied as itself. Anything else is pasted as text.

A file in a folder for temporary files is copied to that media folder,
and the copy is what goes in. An app that takes screenshots puts its picture
on the clipboard as a file like that, and macOS removes the file later.
"""
paste!(e) = begin
  b = e.buf
  paths = Pasteboard.files()
  if isempty(paths)
    text = Sys.isapple() ? Pasteboard.text() : clipboard()
    # A whole block that was copied from another page goes in as a part of that page
    link = pasted_part(e, text)
    link === nothing || return paste_part!(e, link)
    # A contact that was copied in the Contacts app goes in as a block of contacts
    list = copied_contacts(e, text)
    isempty(list) || return paste_contacts!(e, list)
    # A picture that's copied from a web page comes with its address as text, and the picture is what's wanted
    found = isempty(strip(text)) || occursin(r"^\s*\w+://\S+\s*$", text) ? Pasteboard.media() : nothing
    path = found === nothing ? nothing : keep_pasted(e, found...)
    path === nothing && return each_selection!(() -> type!(e, replace(text, "\r\n" => "\n", '\r' => '\n', '\t' => "  ")), e)
    paths = [path]
  end
  paths = [passing(e, p) ? something(keep_copy(e, p), p) : p for p in paths]
  selecting(b) && type!(e, "")
  put_files!(e, paths, settle(b, b.caret))
end

# A file that a page makes goes in a folder called .media beside the page: a
# picture that's pasted, a recording, a copy of a temporary file. Only the page
# that made it has a use for it, so it stays out of the list of the page's
# folder. The Finder and the sidebar leave out a name that starts with a dot
# until you ask for the hidden files.
const PAGE_MEDIA = ".media"

"The folder for the files that the pages of the folder `dir` make. It's made if it isn't there."
page_media(dir) = begin
  media = joinpath(dir, PAGE_MEDIA)
  # A folder that can't be made leaves the file's own write to say what went wrong
  try mkpath(media) catch end
  media
end

"""
Write `bytes` that were pasted to a new file in the media folder of the
document's folder, and return its path. `ext` is the end of the file's name,
like "png". Nothing if the document has no folder yet.
"""
keep_pasted(e, ext, bytes) = begin
  dir = docdir(e)
  isdir(dir) || return nothing
  path = unused(page_media(dir), "pasted-" * Libc.strftime("%Y%m%d-%H%M%S", time()), ".$ext")
  write(path, bytes)
  list_files!(e)   # a sidebar that shows hidden files lists the media folder, or the new file in it
  path
end

"A path in `dir` that no file has yet: `stem` and `ext`, with a number after the stem if that name is taken"
unused(dir, stem, ext) = begin
  path = joinpath(dir, stem * ext)
  n = 1
  while ispath(path)
    path = joinpath(dir, "$stem-$(n += 1)$ext")
  end
  path
end

# The folders that macOS keeps temporary files in, and empties by itself
const PASSING = ("/private/var/folders/", "/var/folders/", "/private/tmp/", "/tmp/")

"True when the file at `path` is a temporary one, which macOS removes later. A file in the document's own folder is never one."
passing(e, path) = isfile(path) && dirname(path) != docdir(e) && any(p -> startswith(path, p), PASSING)

"""
Copy the file at `path` to the media folder of the document's folder, under
its own name, and return the copy's path. Nothing if the document has no
folder yet.
"""
keep_copy(e, path) = begin
  dir = docdir(e)
  isdir(dir) || return nothing
  copy = unused(page_media(dir), splitext(basename(path))...)
  cp(path, copy)
  list_files!(e)
  copy
end

zoom!(e, z) = (e.zoom = clamp(z, 0.6, 2.5); save_settings!(e); rerun!(e, :zoom); restyle!(e))

"The size of the page's text, to the nearest pixel"
text_size(e) = round(Int, TEXT_SIZE.value * e.zoom)
# The page's text is a whole number of pixels tall, so the settings page can show its size as a number
"The zoom that makes the page's text `size` pixels tall. Sizes are whole numbers from 11 to 42."
zoom_for(size) = clamp(round(Int, size), 11, 42) / TEXT_SIZE.value

"The one after `x` in `list`, going back to the start after the last"
after(list, x) = list[mod1(findfirst(==(x), list) + 1, length(list))]

const THEME_ORDER = (:sepia, :paper, :night)

const SLIDE_TIME = 0.25   # seconds for the sidebar to slide in or out

"Show the sidebar if it's hidden, or hide it. It slides from where it is now."
toggle_panel!(e) = (e.slid_from = opened(e); e.slid = time(); e.panel = !e.panel)

sliding(e) = time() - e.slid < SLIDE_TIME

"How far a slide from `from` to `to` that started at the time `at` has gone. It takes `SLIDE_TIME`."
eased(from, to, at) = begin
  t = (time() - at) / SLIDE_TIME
  t < 1 || return to
  t = t < 0.5 ? 4t^3 : 1 - (2 - 2t)^3 / 2   # slow at the start and the end
  from + (to - from) * t
end

"How far the sidebar is open, from 0 to 1"
opened(e) = eased(e.slid_from, e.panel ? 1.0 : 0.0, e.slid)

# --- the panel at the right ---------------------------------------------------------------
#
# A page of a kind that has one shows a panel at the right of the window, as
# the page of a repository shows what git says beside the repository's files:
# see `page_side`. The button at the right end of the top bar hides the panel,
# and shows it again. It slides as the sidebar does. Whether it shows is a
# setting: each window shows it or none does, and so does the next window.

const RIGHT_W = 340px   # how wide the panel at the right is, in a window that has room for it

"When the panel at the right last started to slide in or out, and how far open it was then, from 0 to 1"
right_slid(e) = get(e.nodes, :right_slid, (1.0, 0.0))

"How far the panel at the right is open, from 0 to 1"
right_opened(e) = ((from, at) = right_slid(e); eased(from, e.right ? 1.0 : 0.0, at))

right_sliding(e) = time() - right_slid(e)[2] < SLIDE_TIME

"Show or hide the panel at the right of the page, like git's panel beside a repository's files. Each window does the same."
toggle_right!(e) = (e.nodes[:right_slid] = (right_opened(e), time()); e.right = !e.right; save_settings!(e); e)

"How wide the panel at the right is when it's open. A narrow window makes it narrower, so the page keeps room beside it."
right_w(e) = begin
  w, _ = window_size(e)
  left = lowered(e) === nothing ? panel_w(e) * opened(e) : 0px
  px(round(num(clamp((w - left) * 0.4, 200px, RIGHT_W))))
end

"What the panel at the right shows for the page, or nothing when the page has no panel: see `page_side`"
right_view(e) = begin
  (filled(e) || as_app(e) || nofile(e)) && return nothing
  o = page_object(e)
  o === nothing ? nothing : page_side(e, o)
end

"""
The panel at the right of the window, while the page has one. It keeps its
width as it slides in and out from the right edge, so only its left part
shows while it's partly out.
"""
right_panel(e) = begin
  shows = right_opened(e)
  shows > 0 || return ()
  own = right_view(e)
  own === nothing && return ()
  right_sliding(e) && redraw_in!(e, 0)
  wide = right_w(e)
  (Row(fixed(wide * shows), height(grow=grow), Alignment.Start, clip=true,
     Column(fixed(wide), height(grow=grow), Alignment.Start, background(colours.panel), name="Side",
            border(1px, :solid, colours.line)[:left],
       Box(width(grow=grow), height(TOPBAR_H)),   # under the top bar
       own)),)
end

"What the button that hides the panel at the right calls the panel of `o`"
side_name(e, o) = "the panel"

"The button at the right end of the top bar that hides the panel at the right and shows it, while the page has a panel"
right_part(e) = right_view(e) === nothing ? () : (button(e, :right_panel, "layout-sidebar-reverse"),)

"""
Notice when the window starts or stops filling a screen of its own, as the
green button makes it do. macOS hides the close, minimise and zoom buttons
then, so the buttons of the top bar slide left into their room. They slide
back when the window leaves full screen.
"""
screen_tick!(e) = begin
  w = window_of(e)
  # A window that isn't on the screen can't fill one. Its setting stays as it is, so a test can set it.
  (w === nothing || isempty(w.glfw)) && return
  on = fills_screen(w)
  on == e.full_screen && return
  e.screened_from = cleared(e)
  e.screened = time()
  e.full_screen = on
end

clearing(e) = time() - e.screened < SLIDE_TIME

"How far the buttons of the top bar have slid into the room of the close, minimise and zoom buttons, from 0 to 1"
cleared(e) = eased(e.screened_from, e.full_screen ? 1.0 : 0.0, e.screened)

const MAC_BUTTONS_W = 84px   # the room at the left of the top bar for the close, minimise and zoom buttons

"""
The room that the top bar leaves at its left for the close, minimise and zoom
buttons. In full screen they're hidden, and it leaves 8px, as it does after
the arrows at the right.
"""
mac_buttons_room(e) = MAC_BUTTONS_W - (MAC_BUTTONS_W - 8px) * cleared(e)

"The most of the window's width that the sidebar can have, so the page keeps room beside it"
widest_panel(e) = max(PANEL_MIN, min(PANEL_MAX, px(floor(num(window_size(e)[1]) / 2))))

"How wide the sidebar is when it's open. A narrow window makes it narrower than you dragged it."
panel_w(e) = min(e.side, widest_panel(e))

"Make the sidebar `w` pixels wide, or as near to that as it can be, and keep the width in the settings"
side!(e, w) = begin
  w = px(round(num(clamp(w, PANEL_MIN, widest_panel(e)))))
  w == e.side && return e
  e.side = w
  save_settings!(e)
  e
end

ismouse(k) = k in (Keys.mouse_left, Keys.mouse_right, Keys.mouse_middle, Keys.mouse_back, Keys.mouse_forward)

# --- key bindings ------------------------------------------------------------------------
#
# Each thing that a key does is a command with a name, like `:save`. A shortcut
# is the keys that run a command: one key with the keys that are held with it,
# like ⌘S, or two of those pressed one after the other, like ⌃X ⌃S. A bundle
# gives every command its shortcuts. Ladder starts with the bundle called
# "Ladder". Each other bundle has the keys of another editor. The key bindings
# page of the settings chooses the bundle, and gives any one command another
# shortcut. The bundle and those changes are settings: every window has the
# same keys, and the settings file keeps them.
#
# A command's kind says where it works:
#   :window  whatever has the keyboard, and on a file that's only shown
#   :look    while the text has the keyboard, and on a file that's only shown as text
#   :edit    while the text has the keyboard. It changes the text.
#   :move    it moves the caret. With ⇧ held too, it grows the selection.
#   :type    it changes the text at the caret, like ⌫. While the page is read it does nothing.
#
# Return, esc and Space have no command. What each does depends on where the caret is.

"A key, and the keys of ⌃, ⌘, ⌥ and ⇧ that are held with it"
struct Stroke
  held::Keys
  key::Keys
end

"The keys that run a command: one stroke, or two that are pressed one after the other"
const Shortcut = Tuple{Vararg{Stroke}}

# The keys that are held with another key: the name that the settings file has for each, and the Mac's sign for it
const HOLDS = ((Keys.ctrl, "ctrl", "⌃"), (Keys.cmd, "cmd", "⌘"), (Keys.opt, "opt", "⌥"), (Keys.shft, "shift", "⇧"))
const HELD = Keys.ctrl | Keys.cmd | Keys.opt | Keys.shft

"Each key that a shortcut can have, by the name that the settings file has for it, like \"z\", \"f5\" or \"pageup\""
const KEY_NAMES = Dict{String,Keys}(lstrip(string(name), '_') => getproperty(Keys, name) for name in keys(instances(Keys))
                                    if !(name in (:shft, :cmd, :opt, :ctrl, :capslock, :fn, :mouse_left, :mouse_right, :mouse_middle, :mouse_back, :mouse_forward)))
const KEY_OF = Dict{Keys,String}(key => name for (name, key) in KEY_NAMES)

"What the key bindings page shows for a key that isn't a letter, a number or an F key"
const KEY_SIGNS = Dict{Keys,String}(
  Keys.enter => "Return", Keys.tab => "Tab", Keys.space => "Space", Keys.backspace => "⌫", Keys.delete => "⌦", Keys.escape => "esc",
  Keys.left => "←", Keys.right => "→", Keys.up => "↑", Keys.down => "↓",
  Keys.home => "Home", Keys._end => "End", Keys.pageup => "Page Up", Keys.pagedown => "Page Down",
  Keys.tilde => "`", Keys.minus => "-", Keys.equal => "=", Keys.left_bracket => "[", Keys.right_bracket => "]", Keys.semicolon => ";",
  Keys.apostrophe => "'", Keys.comma => ",", Keys.period => ".", Keys.slash => "/", Keys.backslash => "\\", Keys.plus => "+", Keys.times => "*")

const TYPING_KEYS = ("tilde", "minus", "equal", "left_bracket", "right_bracket", "semicolon", "apostrophe", "comma", "period", "slash",
                     "backslash", "times", "plus", "space")

"True when the key `K` types a character: a letter, a number or a sign. A shortcut with it needs ⌘, ⌃ or ⌥ too."
typing_key(K) = (name = get(KEY_OF, K, ""); length(name) == 1 || startswith(name, "num") || name in TYPING_KEYS)

"The stroke that `text` writes, like \"cmd+shift+z\", or nothing when it writes none"
read_stroke(text::AbstractString) = begin
  parts = split(text, '+')
  key = get(KEY_NAMES, last(parts), nothing)
  key === nothing && return nothing
  held = Keys(0)
  for part in parts[1:end-1]
    i = findfirst(h -> h[2] == part, HOLDS)
    i === nothing && return nothing
    held |= HOLDS[i][1]
  end
  Stroke(held, key)
end

"The shortcuts that `text` writes, with a comma between them, like \"cmd+z, ctrl+x u\". One that can't be read is left out."
read_shortcuts(text::AbstractString) = begin
  out = Shortcut[]
  for part in split(text, ','; keepempty=false)
    strokes = map(read_stroke, split(part))
    (isempty(strokes) || length(strokes) > 2 || any(isnothing, strokes)) && continue
    push!(out, Tuple(strokes))
  end
  out
end

"How the settings file writes a stroke, a shortcut or a command's shortcuts. `read_shortcuts` reads it back."
written(s::Stroke) = join([[name for (key, name, _) in HOLDS if key in s.held]; KEY_OF[s.key]], '+')
written(s::Shortcut) = join(map(written, s), ' ')
written(list::Vector{Shortcut}) = join(map(written, list), ", ")

"How a stroke or a shortcut reads, like ⌘⇧Z or ⌃X ⌃S"
caps(s::Stroke) = join([sign for (key, _, sign) in HOLDS if key in s.held]) * get(() -> uppercase(KEY_OF[s.key]), KEY_SIGNS, s.key)
caps(s::Shortcut) = join(map(caps, s), ' ')

"""
Something that a key does. `keys` are its shortcuts in the bundle called
Ladder. `run` gets the editor, its window, and true when ⇧ is held to grow
the selection. `call` is the function that the command palette calls, after
it asks for each thing that the function takes. It's nothing for a command
that takes nothing. See "the command palette".
"""
struct Command
  name::Symbol
  title::String   # what the key bindings page calls it
  kind::Symbol
  keys::String
  run::Function
  call::Any
end
Command(name, title, kind, keys, run) = Command(name, title, kind, keys, run, nothing)

"Move the caret one character left or right. With a selection and no ⇧, it goes to that end of the selection."
caret_step!(e, by::Int, select::Bool) = begin
  b = e.buf
  lo, hi = selection(b)
  move!(e, selecting(b) && !select ? (by < 0 ? lo : hi) : beside(b, b.caret, by), select; by)
end

"Move the caret most of a screen up or down"
caret_page!(e, by::Int, select::Bool) = foreach(_ -> move!(e, vertical(e, by), select; keep_goal=true, by), 1:20)

"What ⌫ does: it takes away a row of a table that has nothing in it, or what's before the caret"
erase_back!(e) = begin
  b = e.buf
  picked(b) === nothing || return delete_lines!(e)   # the part that the caret is on as a whole goes
  emptyrow(b) && return backrow!(e)
  erase_start!(e) && return
  if in_empty_pair(b)
    # The bracket that closes goes with the bracket that it came with
    i, col = b.caret
    b.anchor, b.caret = (i, col - 1), (i, col + 1)
    return type!(e, "")
  end
  blk = block(b, b.caret[1])
  erase!(e, backstep(b, blk, length(indentation(e, blk))))
end

"""
What ⌫ does in rich text when the caret is at the start of a line's text. It
returns true when it did it, and false when the caret is somewhere else.

- In a heading, a list item or a quote, it makes the line a paragraph. An item
  of a list inside a list goes out a step first.
- After a part that shows as one thing, like a diagram or a picture, it takes
  away a line with nothing on it. A line with text stays. Either way the caret
  goes onto the part, and ⌫ again takes the part away.
"""
erase_start!(e) = begin
  b = e.buf
  (rich(b) && !selecting(b)) || return false
  i, col = b.caret
  line = kinds(b)[i]
  hidden = unseen(b, i)
  if !isempty(hidden) && first(hidden)[1] < 0 && col <= first(hidden)[2]
    n = line.kind in (Kind.bullet, Kind.ordered, Kind.todo) && line.level >= 2 ? 2 : richspans(b, i)[1]
    edit!(b, (i, 0), (i, n), "")
    b.caret = b.anchor = (i, max(0, col - n))
    touch!(e)
    return true
  end
  at = something(findfirst(r -> r[1] < col <= r[2], hidden), 0)
  (at == 0 ? col : hidden[at][1]) == 0 && i > 1 && !free(b, i - 1, i) || return false
  if isempty(b.lines[i]) && line.kind != Kind.code
    edit!(b, line_end(b, i - 1), (i, 0), "")
    b.caret = b.anchor = settle(b, line_end(b, i - 1), -1, from=(0, 0))
  else
    return (move!(e, line_end(b, i - 1), false, by=-1); true)
  end
  touch!(e)
  true
end

"""
What ⌦ does: it takes away what's after the caret. As rich text, at the end of
a line it joins the next line's text to it, without what starts that line.
"""
erase_next!(e) = begin
  b = e.buf
  picked(b) === nothing || return delete_lines!(e)   # the part that the caret is on as a whole goes
  to = beside(b, b.caret, 1)
  if rich(b) && !selecting(b) && to[1] > b.caret[1]
    j = to[1]
    # The caret goes onto a part that comes next, and ⌦ again takes that part away. It stays before a ``` line.
    free(b, j, b.caret[1]) || return part(b, j) === nothing ? nothing : move!(e, to, false, by=1)
    to = (j, first_stop(b, j))
  end
  erase!(e, to)
end

"Take away the rest of the caret's line. At the end of a line, it joins the next line to it."
erase_line_end!(e) = (b = e.buf; at = line_end(b, b.caret[1]); at == b.caret ? erase_next!(e) : erase!(e, at))

# --- commands for whole lines ---

"The first and last line that the selection touches. A selection that ends at the start of a line doesn't touch that line."
touched(b::Buffer) = begin
  run = picked(b)
  run === nothing || return run   # all the lines of the part that the caret is on as a whole
  lo, hi = minmax(b.caret, b.anchor)
  (lo[1], hi[2] == 0 && hi[1] > lo[1] ? hi[1] - 1 : hi[1])
end

"Put the caret at `caret` and the other end of the selection at `anchor`, each `by` lines further down, after their lines moved"
follow_lines!(e, caret::Pos, anchor::Pos, by::Int) = begin
  b = e.buf
  place((i, col)) = i + by > length(b.lines) ? line_end(b, length(b.lines)) : (max(1, i + by), min(col, length(b.lines[max(1, i + by)])))
  b.caret, b.anchor = place(caret), place(anchor)
  touch!(e)
end

"Take away each line that the selection touches"
delete_lines!(e) = begin
  b = e.buf
  s, t = touched(b)
  col = b.caret[2]
  if t < length(b.lines)
    edit!(b, (s, 0), (t + 1, 0), "")
  elseif s > 1
    edit!(b, line_end(b, s - 1), line_end(b, t), "")
  else
    edit!(b, (1, 0), line_end(b, t), "")
  end
  i = min(s, length(b.lines))
  # The caret comes to the line afresh, so in rich text it isn't left on a line that doesn't show
  b.caret = b.anchor = settle(b, (i, min(col, length(b.lines[i]))), 1, from=(0, 0))
  touch!(e)
end

"Put a copy of the lines that the selection touches under them. The caret goes to the copy."
duplicate_lines!(e) = begin
  b = e.buf
  s, t = touched(b)
  caret, anchor = b.caret, b.anchor
  edit!(b, line_end(b, t), line_end(b, t), "\n" * join(b.lines[s:t], "\n"))
  follow_lines!(e, caret, anchor, t - s + 1)
end

"Move the lines that the selection touches one line up or down"
move_lines!(e, by::Int) = begin
  b = e.buf
  s, t = touched(b)
  caret, anchor = b.caret, b.anchor
  if by < 0
    s > 1 || return
    edit!(b, (s - 1, 0), line_end(b, t), join([b.lines[s:t]; b.lines[s-1]], "\n"))
  else
    t < length(b.lines) || return
    edit!(b, (s, 0), line_end(b, t + 1), join([b.lines[t+1]; b.lines[s:t]], "\n"))
  end
  follow_lines!(e, caret, anchor, by)
end

"Select the whole of the caret's line. With a selection, it grows to the end of its last line. Again, it takes the next line too."
select_lines!(e) = begin
  b = e.buf
  lo, hi = minmax(b.caret, b.anchor)
  b.anchor = (lo[1], 0)
  move!(e, hi[1] < length(b.lines) ? (hi[1] + 1, 0) : line_end(b, hi[1]), true; by=1)
end

"""
Do `f` at each selection: at the main one, then at each of the others with it
in the main one's place. An edit that one of them makes moves the ones after
it, and one ⌘Z takes back what they all did.
"""
each_selection!(f, e) = begin
  b = e.buf
  n = length(others(b))
  (n == 0 || b.many) && return f()
  undos = length(b.undo)
  b.many = true
  try
    for _ in 0:n
      f()
      # The main selection goes to the back of the queue, and the next one takes its place
      push!(b.others, (b.anchor, b.caret))
      b.anchor, b.caret = popfirst!(b.others)
    end
  finally
    b.many = false
  end
  length(b.undo) > undos + 1 && resize!(b.undo, undos + 1)
  # Two selections that came to the same place are one
  kept = Tuple{Pos,Pos}[]
  for s in b.others
    clash(s, (b.anchor, b.caret)) || any(k -> clash(s, k), kept) || push!(kept, s)
  end
  b.others = kept
  keep_others!(b)
  nothing
end

"Do `f` with each of the other selections in the main one's place, then put the main one back. It's for drawing them."
with_others(f, b::Buffer) = begin
  list = copy(others(b))
  isempty(list) && return
  main, many = (b.anchor, b.caret), b.many
  b.many = true
  try
    for s in list
      b.anchor, b.caret = s
      f()
    end
  finally
    b.anchor, b.caret = main
    b.many = many
  end
end

"The columns of each place in `line` that has `text`. With `whole`, only where it's a word by itself."
places(line::AbstractString, text::AbstractString, whole::Bool) = begin
  out = Tuple{Int,Int}[]
  at = firstindex(line)
  while (r = findnext(text, line, at)) !== nothing
    before, after = prevind(line, first(r)), nextind(line, last(r))
    if whole && ((before >= 1 && isword(line[before])) || (after <= ncodeunits(line) && isword(line[after])))
      at = nextind(line, first(r))
      continue
    end
    lo = length(line, 1, before)
    push!(out, (lo, lo + length(text)))
    at = after
  end
  out
end

"""
Select the next place that has the text of the selection as well, and go to
it. After the end of the page it looks from the top. Text that is one word is
found only where it's a word by itself. A live block's own text isn't looked at.
"""
select_next!(e) = begin
  b = e.buf
  lo, hi = selection(b)
  (lo != hi && lo[1] == hi[1]) || return
  text = excerpt(b, lo, hi)
  whole = all(isword, text)
  taken = [(b.anchor, b.caret); others(b)]
  found = [((i, from), (i, to)) for i in eachindex(b.lines) for (from, to) in places(b.lines[i], text, whole)]
  for s in [filter(s -> s[1] >= hi, found); filter(s -> s[1] < lo, found)]
    (any(t -> clash(s, t), taken) || item(e, s[1][1]).content isa Live) && continue
    push!(b.others, (b.anchor, b.caret))
    b.anchor, b.caret = s
    keep_others!(b)
    return
  end
end

"""
Select the word that the caret is in or beside. With a selection, each end of
it goes out to the edge of the word that it's in. With whole words selected
already, the next place that has the same text is selected as well, so what's
typed next goes in at each of them. With no word at the caret, nothing changes.

The selection that was there first stays first in `others`, so Escape can go
back to it.
"""
select_word!(e) = begin
  b = e.buf
  grew = Ref(false)
  each_selection!(e) do
    lo, hi = selection(b)
    from = (lo[1], word_at(b.lines[lo[1]], lo[2])[1])
    to = (hi[1], word_at(b.lines[hi[1]], hi[2])[2])
    (from, to) == (lo, hi) && return
    b.anchor, b.caret = from, to
    grew[] = true
  end
  grew[] || select_next!(e)
  touch!(e)
end

"What starts a comment in each language of code, by the language's name or the end of its file's name"
const COMMENT_MARKS = Dict{String,String}(
  (lang => "#" for lang in ("jl", "julia", "ui", "py", "python", "rb", "ruby", "sh", "bash", "zsh", "fish", "toml", "yaml", "yml", "r", "perl", "pl", "make", "dockerfile"))...,
  (lang => "//" for lang in ("js", "javascript", "jsx", "ts", "typescript", "tsx", "c", "h", "cpp", "hpp", "cc", "java", "swift", "rs", "rust", "go", "kt", "kotlin",
                             "scala", "cs", "php", "dart", "zig"))...,
  (lang => "--" for lang in ("lua", "sql", "hs", "haskell", "elm"))...,
  (lang => ";" for lang in ("lisp", "el", "clj", "clojure", "scm", "scheme"))...,
  (lang => "%" for lang in ("tex", "latex", MATH, "erl", "erlang"))..., "mermaid" => "%%")

"""
Make a comment of each line of code that the selection touches, or make code
of them again if each is a comment already. A line with nothing on it stays
as it is. Outside code, where a comment has no mark, nothing changes.
"""
toggle_comment!(e) = begin
  b = e.buf
  picked(b) === nothing || return
  s, t = touched(b)
  ks = kinds(b)
  lines = [i for i in s:t if ks[i].kind == Kind.code && !isempty(strip(b.lines[i]))]
  isempty(lines) && return
  mark = get(COMMENT_MARKS, lowercase(ks[first(lines)].lang), nothing)
  mark === nothing && return
  indent(i) = length(b.lines[i]) - length(lstrip(b.lines[i]))
  on = all(i -> startswith(lstrip(b.lines[i]), mark), lines)
  at = minimum(indent, lines)   # every mark goes at the indent of the line that's furthest out
  ends = Dict(:caret => b.caret, :anchor => b.anchor)
  new = b.lines[s:t]
  for i in lines
    line = b.lines[i]
    from = on ? indent(i) : at
    # A comment's mark has a space after it, which goes with the mark
    n = !on ? length(mark) + 1 : length(mark) + (startswith(rest(line, from + length(mark)), " ") ? 1 : 0)
    new[i-s+1] = on ? head(line, from) * rest(line, from + n) : head(line, from) * mark * " " * rest(line, from)
    for (name, (l, col)) in ends
      l == i && (ends[name] = (i, on ? (col > from ? max(from, col - n) : col) : (col >= from ? col + n : col)))
    end
  end
  # One change, so one ⌘Z puts every line back
  edit!(b, (s, 0), line_end(b, t), join(new, "\n"))
  b.caret, b.anchor = ends[:caret], ends[:anchor]
  touch!(e)
end

# ⌃↑ and ⌃↓ change the value at the caret a step. A number goes a step bigger or smaller, as a drag on a
# sum does: a step is one of its last digit. Unlike a drag, ⌃↓ takes a number under 0. true and false swap,
# with either key. Any other word goes up from small letters, to a capital at its front, to all capitals,
# and ⌃↓ takes it back down. The value can be anywhere in the text: in a sum, in a sheet, in code, in a
# date or a time. Presses one after another are taken back by one ⌘Z.

"""
Where the number is that the column `col` of `line` is in, or at either end
of: the columns that it runs from and to. Nothing when no digit touches the
column. A number has digits, and can have a dot and more digits after them,
like 2.40. Digits with a dot on each side, like the parts of 1.2.3, are each a
number of their own. A - just before the digits is the number's sign, unless a
letter, a digit or a bracket comes before it, like the - of x-1 or of 2026-11-21.
"""
caret_number(line::AbstractString, col::Int) = begin
  c = collect(line)
  n = length(c)
  digit(i) = 1 <= i <= n && isdigit(c[i])
  at = digit(col + 1) ? col + 1 : digit(col) ? col : col < n && c[col+1] == '-' && digit(col + 2) ? col + 2 : 0
  at == 0 && return nothing
  lo = hi = at                      # the first and the last of the number's characters, from 1
  while digit(lo - 1) lo -= 1 end
  while digit(hi + 1) hi += 1 end
  run = (lo, hi)
  # Digits, a dot and digits are one number
  if lo > 2 && c[lo-1] == '.' && digit(lo - 2)
    lo -= 2
    while digit(lo - 1) lo -= 1 end
  elseif hi < n - 1 && c[hi+1] == '.' && digit(hi + 2)
    hi += 2
    while digit(hi + 1) hi += 1 end
  end
  # With a dot more at either end, it's a list of numbers, like 1.2.3 or 192.168.0.1, and the caret's is one of them
  dotted(i, j) = (i >= 2 && c[i-1] == '.' && digit(i - 2)) || (j < n && c[j+1] == '.' && digit(j + 2))
  (lo, hi) != run && dotted(lo, hi) && ((lo, hi) = run)
  lo >= 2 && c[lo-1] == '-' && !(lo >= 3 && (isletter(c[lo-2]) || isdigit(c[lo-2]) || c[lo-2] in ")]}_")) && (lo -= 1)
  # The caret was before a - that isn't a sign, like the one of x|-1
  lo - 1 <= col || return nothing
  (lo - 1, hi)
end

"""
The number that `text` writes, `steps` steps on. A step is one of its last
digit: 16 goes to 17, 2.40 to 2.41, and 0 to -1 after a step back. It has as
many digits after its dot as before, and a number with a 0 at its front keeps
its width, so 09 goes to 10 and 007 to 008.
"""
number_plus(text::AbstractString, steps::Int) = begin
  neg = startswith(text, '-')
  body = neg ? text[2:end] : text
  dot = findfirst('.', body)
  places = dot === nothing ? 0 : length(body) - dot
  whole = dot === nothing ? body : body[1:dot-1]
  digits = replace(body, "." => "")
  # In whole numbers, so that 2.4 and a step of 0.01 don't make 2.4099999
  v = parse(BigInt, digits) * (neg ? -1 : 1) + steps
  wide = length(whole) > 1 && startswith(whole, '0') ? length(digits) : places + 1
  s = lpad(string(abs(v)), wide, '0')
  places > 0 && (s = s[1:end-places] * "." * s[end-places+1:end])
  v < 0 ? "-" * s : s
end

"""
Where the word is that the column `col` of `line` is in, or at either end of:
the columns that it runs from and to. A word has letters, digits and _, and an
apostrophe between two letters, like don't. Nothing when no word touches the column.
"""
caret_word(line::AbstractString, col::Int) = begin
  c = collect(line)
  n = length(c)
  inword(i) = 1 <= i <= n && (isletter(c[i]) || isdigit(c[i]) || c[i] == '_' ||
                              (c[i] in "'’" && 1 < i < n && isletter(c[i-1]) && isletter(c[i+1])))
  lo = hi = col
  while inword(lo) lo -= 1 end
  while inword(hi + 1) hi += 1 end
  lo == hi ? nothing : (lo, hi)
end

"""
The word `w` a step up, or a step down when `up` is false. It's `w` itself
when it can't go further. true and false swap, and so do True and False, and
TRUE and FALSE. Any other word goes up from small letters, to a capital at its
front, to all capitals: word, Word, WORD. A step down goes back: WORD, Word, word.
"""
word_step(w::AbstractString, up::Bool) = begin
  low = lowercase(w)
  if low in ("true", "false")
    other = low == "true" ? "false" : "true"
    return w == uppercase(w) ? uppercase(other) : isuppercase(first(w)) ? uppercasefirst(other) : other
  end
  c = collect(w)
  letters = findall(isletter, c)
  isempty(letters) && return w
  f = first(letters)
  caps = all(i -> isuppercase(c[i]), letters)
  if up
    !isuppercase(c[f]) ? (c[f] = uppercase(c[f])) : caps || (c = collect(uppercase(w)))
  else
    caps && length(letters) > 1 ? (c = collect(lowercase(w)); c[f] = uppercase(c[f])) : isuppercase(c[f]) && (c[f] = lowercase(c[f]))
  end
  String(c)
end

"""
The value at the column `col` of `line`, `steps` steps on: the columns that it
runs from and to, and its new text. It's the number that the column is in or at,
or else the word. A word with digits, like 16m or h1, is its number, so the
caret can be after the unit of 16m. Nothing when there's no value there, or
when it can't go further.
"""
caret_value(line::AbstractString, col::Int, steps::Int) = begin
  at = caret_number(line, col)
  w = caret_word(line, col)
  if at === nothing && w !== nothing
    # The digit in the word that's nearest the caret, before it or else after it
    c = collect(line)
    lo, hi = w
    before = findlast(isdigit, c[lo+1:col])
    after = findfirst(isdigit, c[col+1:hi])
    at = before !== nothing ? caret_number(line, lo + before) : after !== nothing ? caret_number(line, col + after - 1) : nothing
  end
  at === nothing || return (at..., number_plus(rest(head(line, at[2]), at[1]), steps))
  w === nothing && return nothing
  word = rest(head(line, w[2]), w[1])
  new = word_step(word, steps > 0)
  new == word ? nothing : (w..., new)
end

"Make the value at the caret `steps` steps bigger, or smaller for steps under 0. See `caret_value`. The caret and the selection stay with their text."
step_value!(e, steps::Int) = begin
  b = e.buf
  (readonly(b) || b.fixed) && return
  i, col = b.caret
  found = caret_value(b.lines[i], col, steps)
  found === nothing && return
  lo, hi, new = found
  caret, anchor = b.caret, b.anchor
  # A press right after a press, with no other change between them, is taken back with it
  b.typed = get(e.nodes, :value_stepped, -1) == b.version ? time() : 0.0
  edit!(b, (i, lo), (i, hi), new, typing=true)
  b.typed = 0.0   # and what's typed after it is taken back by itself
  e.nodes[:value_stepped] = b.version
  # A place in the number stays as far from its end as it was, so the caret at the end of 9 is at the end of 10
  by = length(new) - (hi - lo)
  kept(p) = p[1] != i || p[2] <= lo ? p : (i, max(lo, p[2] + by))
  b.caret, b.anchor = kept(caret), kept(anchor)
  touch!(e)
end

"""
Each command that `add_commands!` added, with the name of its group, in the
order that they came. A hot reload makes `COMMAND_GROUPS` again when a name
in it changes, and doesn't call `add_command!` again further down the file.
So the list takes these back in: see `with_added`.
"""
const ADDED_COMMANDS = Pair{String,Command}[]

"""
Put each of `commands` in the group of `groups` called `group`, at the end,
or in the place of the one that has its name. A group that isn't there yet
comes last.
"""
put_commands!(groups, group::AbstractString, commands) = begin
  i = findfirst(g -> first(g) == group, groups)
  i === nothing && (push!(groups, String(group) => Command[]); i = length(groups))
  list = last(groups[i])
  for c in commands
    k = findfirst(o -> o.name == c.name, list)
    k === nothing ? push!(list, c) : (list[k] = c)
  end
  groups
end

"`groups` with each command that `add_commands!` added put back in its group"
with_added(groups) = (foreach(((group, c),) -> put_commands!(groups, group, (c,)), ADDED_COMMANDS); groups)

"""
The commands, in the groups and the order that the key bindings page shows
them. Each has its shortcuts in the bundle called Ladder.
"""
const COMMAND_GROUPS = with_added([
  "Files and windows" => [
    Command(:save, "Save the file", :window, "cmd+s", (e, w, _) -> save_page!(e)),
    Command(:new_window, "Open a new window on the folder that you're in", :window, "cmd+n", (e, w, _) -> new_window!(e)),
    Command(:open, "Find a file by name", :window, "cmd+o", (e, w, _) -> open_finder!(e)),
    Command(:open_project, "Find a project by name and open it", :window, "cmd+p", (e, w, _) -> open_projects!(e)),
    Command(:home, "Open your home folder in the page", :window, "cmd+shift+h", (e, w, _) -> go_home!(e)),
    Command(:commands, "Show the command palette, to run a command by its name", :window, "cmd+shift+p", (e, w, _) -> toggle_palette!(e)),
    Command(:back, "Go back to the line or the file that showed before", :window, "cmd+opt+left", (e, w, _) -> go_back!(e)),
    Command(:forward, "Go forward again, to the line or the file that you went back from", :window, "cmd+opt+right", (e, w, _) -> go_forward!(e)),
    Command(:print, "Print the page", :window, "cmd+opt+p", (e, w, _) -> print!(e, w)),
    Command(:export, "Export the page as HTML", :window, "cmd+shift+e", (e, w, _) -> export_html!(e, w)),
    Command(:slides, "Show the page as slides, or as a page again", :window, "ctrl+cmd+shift+p", (e, w, _) -> slides!(e)),
    Command(:close, "Close the file, or the window when it shows no file", :window, "cmd+w", (e, w, _) -> close_file_or_window!(e, w)),
    Command(:settings, "Show or hide the settings", :window, "cmd+comma", (e, w, _) -> toggle_settings!(e)),
    Command(:sidebar, "Show or hide the sidebar", :window, "cmd+backslash", (e, w, _) -> toggle_panel!(e)),
    Command(:sidebar_keys, "Give the sidebar the keyboard", :window, "cmd+shift+backslash", (e, w, _) -> focus_panel!(e)),
    Command(:plain, "Go down a level in the part that the caret is in, or up again", :window, "cmd+e", (e, w, _) -> level!(e)),
    Command(:hidden_files, "Show or hide the hidden files in the sidebar", :window, "cmd+shift+period", (e, w, _) -> hidden!(e, !e.hidden)),
    Command(:bigger, "Make the text bigger", :window, "cmd+equal", (e, w, _) -> zoom!(e, zoom_for(text_size(e) + 1))),
    Command(:smaller, "Make the text smaller", :window, "cmd+minus", (e, w, _) -> zoom!(e, zoom_for(text_size(e) - 1))),
    Command(:usual_size, "Put the text back to its usual size", :window, "cmd+0", (e, w, _) -> zoom!(e, 1.0)),
    # The app that's built has no layout inspector
    (BUILDING_APP ? () : (Command(:inspector, "Show or hide the layout inspector", :window, "cmd+opt+i", (e, w, _) -> toggle_inspector!(w)),))...],
  "The text" => [
    Command(:undo, "Undo", :edit, "cmd+z", (e, w, _) -> (undo!(e.buf); touch!(e))),
    Command(:redo, "Redo", :edit, "cmd+shift+z", (e, w, _) -> (redo!(e.buf); touch!(e))),
    Command(:cut, "Cut", :edit, "cmd+x", (e, w, _) -> cut!(e)),
    Command(:copy, "Copy", :look, "cmd+c", (e, w, _) -> copy_selection!(e)),
    Command(:paste, "Paste", :edit, "cmd+v", (e, w, _) -> paste!(e)),
    Command(:select_all, "Select all", :look, "cmd+a", (e, w, _) -> select_all!(e)),
    Command(:select_word, "Select the word at the caret", :look, "cmd+d", (e, w, _) -> select_word!(e)),
    Command(:find, "Find in the page", :look, "cmd+f", (e, w, _) -> open_find!(e)),
    Command(:find_next, "Go to the next place that's found", :look, "cmd+g", (e, w, _) -> find_step!(e, 1)),
    Command(:find_last, "Go to the place that's found before", :look, "cmd+shift+g", (e, w, _) -> find_step!(e, -1)),
    Command(:bold, "Make the selection bold", :edit, "cmd+b", (e, w, _) -> e.buf.view == :markdown && surround!(e, "**")),
    Command(:italic, "Make the selection italic", :edit, "cmd+i", (e, w, _) -> e.buf.view == :markdown && surround!(e, "*")),
    Command(:value_up, "Make the number or the word at the caret a step bigger", :edit, "ctrl+up", (e, w, _) -> step_value!(e, 1)),
    Command(:value_down, "Make the number or the word at the caret a step smaller", :edit, "ctrl+down", (e, w, _) -> step_value!(e, -1)),
    # In a `julia` code block these run the code that the caret is in. Anywhere else, the first sends the page
    # to the agent that waits for it, and with no agent, each starts a new line as Return does.
    Command(:run, "Run the code at the caret, or nudge the agent", :edit, "cmd+enter",
            (e, w, _) -> run_here!(e) || (isempty(agents(e)) ? newline!(e) : send!(e))),
    Command(:run_step, "Run the code at the caret and go to the next line", :type, "shift+enter",
            (e, w, _) -> run_here!(e, step=true) || newline!(e))],
  "Lines" => [
    Command(:select_line, "Select the line", :look, "cmd+shift+l", (e, w, _) -> select_lines!(e)),
    Command(:line_up, "Move the line up", :edit, "cmd+opt+left_bracket", (e, w, _) -> move_lines!(e, -1)),
    Command(:line_down, "Move the line down", :edit, "cmd+opt+right_bracket", (e, w, _) -> move_lines!(e, 1)),
    Command(:duplicate_line, "Copy the line to the line under it", :edit, "cmd+shift+d", (e, w, _) -> duplicate_lines!(e)),
    Command(:delete_line, "Delete the line", :edit, "cmd+shift+k", (e, w, _) -> delete_lines!(e)),
    Command(:comment, "Make a line of code a comment, or code again", :edit, "cmd+slash", (e, w, _) -> toggle_comment!(e)),
    Command(:indent, "Indent, or go to the next cell of a table", :type, "tab", (e, w, _) -> indent!(e, false)),
    Command(:outdent, "Take an indent away, or go back a cell", :type, "shift+tab", (e, w, _) -> indent!(e, true))],
  "The caret" => [
    Command(:left, "Left", :move, "left", (e, w, select) -> (e.by_step = true; caret_step!(e, -1, select))),
    Command(:right, "Right", :move, "right", (e, w, select) -> (e.by_step = true; caret_step!(e, 1, select))),
    Command(:up, "Up", :move, "up", (e, w, select) -> (e.by_step = true; move!(e, vertical(e, -1), select; keep_goal=true, by=-1))),
    Command(:down, "Down", :move, "down", (e, w, select) -> (e.by_step = true; move!(e, vertical(e, 1), select; keep_goal=true, by=1))),
    Command(:word_left, "To the word before", :move, "opt+left", (e, w, select) -> (e.by_step = true; move!(e, word_step(e.buf, e.buf.caret, -1), select; by=-1))),
    Command(:word_right, "To the next word", :move, "opt+right", (e, w, select) -> (e.by_step = true; move!(e, word_step(e.buf, e.buf.caret, 1), select; by=1))),
    Command(:line_start, "To the start of the line", :move, "cmd+left, home", (e, w, select) -> move!(e, screen_edge(e, -1), select; by=-1)),
    Command(:line_end, "To the end of the line", :move, "cmd+right, end", (e, w, select) -> move!(e, screen_edge(e, 1), select; by=1)),
    Command(:doc_start, "To the top of the page", :move, "cmd+up", (e, w, select) -> move!(e, (1, 0), select; by=-1)),
    Command(:doc_end, "To the bottom of the page", :move, "cmd+down", (e, w, select) -> move!(e, line_end(e.buf, length(e.buf.lines)), select; by=1)),
    Command(:page_up, "Up a screen", :move, "pageup", (e, w, select) -> caret_page!(e, -1, select)),
    Command(:page_down, "Down a screen", :move, "pagedown", (e, w, select) -> caret_page!(e, 1, select))],
  "Deleting" => [
    Command(:erase_back, "Delete what's before the caret", :type, "backspace", (e, w, _) -> erase_back!(e)),
    Command(:erase, "Delete what's after the caret", :type, "delete", (e, w, _) -> erase_next!(e)),
    Command(:erase_word_back, "Delete to the start of the word", :type, "opt+backspace", (e, w, _) -> erase!(e, word_step(e.buf, e.buf.caret, -1))),
    Command(:erase_word, "Delete to the end of the word", :type, "opt+delete", (e, w, _) -> erase!(e, word_step(e.buf, e.buf.caret, 1))),
    Command(:erase_line_start, "Delete to the start of the line", :type, "cmd+backspace", (e, w, _) -> erase!(e, (e.buf.caret[1], 0))),
    Command(:erase_line_end, "Delete to the end of the line", :type, "ctrl+k", (e, w, _) -> erase_line_end!(e))]])

"Each command, by its name"
const COMMANDS = Dict{Symbol,Command}(c.name => c for (_, cs) in COMMAND_GROUPS for c in cs)

"""
The bundles of key bindings, in the order that the key bindings page offers
them. Each lists only the commands whose shortcuts are different from the
ones in the bundle called Ladder, with the shortcuts it gives them.
"""
const BUNDLES = [
  "Ladder" => Pair{Symbol,String}[],
  # ⌘P finds a project in every bundle, so printing has another key. The slides' key, ⌃⌘⇧P, is free in every bundle.
  "VS Code" => [
    :back => "ctrl+minus", :forward => "ctrl+shift+minus",
    :line_up => "opt+up", :line_down => "opt+down", :duplicate_line => "opt+shift+down, opt+shift+up"],
  "Sublime Text" => [
    :back => "ctrl+minus", :forward => "ctrl+shift+minus",
    :sidebar => "cmd+k cmd+b, cmd+backslash", :redo => "cmd+shift+z, cmd+y",
    :line_up => "ctrl+cmd+up", :line_down => "ctrl+cmd+down", :delete_line => "ctrl+shift+k",
    :erase_line_start => "cmd+backspace, cmd+k cmd+backspace", :erase_line_end => "ctrl+k, cmd+k cmd+k"],
  # Emacs's own keys come first, and the Mac's keys still work where Emacs has no other use for them
  "Emacs" => [
    :save => "ctrl+x ctrl+s, cmd+s", :open => "ctrl+x ctrl+f, cmd+o", :close => "ctrl+x ctrl+c, cmd+w",
    :undo => "ctrl+slash, ctrl+x u, cmd+z", :cut => "ctrl+w, cmd+x", :copy => "opt+w, cmd+c", :paste => "ctrl+y, cmd+v",
    :commands => "opt+x, cmd+shift+p", :select_all => "ctrl+x h, cmd+a", :select_word => "opt+shift+2, cmd+d", :find => "ctrl+s, cmd+f", :find_last => "ctrl+r, cmd+shift+g", :comment => "opt+semicolon, cmd+slash",
    :left => "ctrl+b, left", :right => "ctrl+f, right", :up => "ctrl+p, up", :down => "ctrl+n, down",
    :word_left => "opt+b, opt+left", :word_right => "opt+f, opt+right",
    :line_start => "ctrl+a, cmd+left, home", :line_end => "ctrl+e, cmd+right, end",
    :doc_start => "opt+shift+comma, cmd+up", :doc_end => "opt+shift+period, cmd+down",
    :page_up => "opt+v, pageup", :page_down => "ctrl+v, pagedown",
    :erase => "ctrl+d, delete", :erase_word => "opt+d, opt+delete"]]

"The shortcuts that the bundle called `name` gives each command"
bundle_keys(name::AbstractString) = begin
  theirs = Dict(last(BUNDLES[something(findfirst(b -> first(b) == name, BUNDLES), 1)]))
  Dict{Symbol,Vector{Shortcut}}(c.name => read_shortcuts(get(theirs, c.name, c.keys)) for c in values(COMMANDS))
end

"""
The key bindings as they are now. `of` has the shortcuts of each command: the
bundle's, with the ones that the key bindings page changed. `commands` has the
command of each shortcut, and `starts` each stroke that starts a shortcut of two.
"""
keys_now(e) = begin
  made = get(e.nodes, :keys, nothing)
  # Code from the startup page can add commands, so the bindings are made again when there are more
  made !== nothing && made.bundle == e.bundle && made.rebound === e.rebound && made.count == length(COMMANDS) && return made
  of = bundle_keys(e.bundle)
  for (name, text) in e.rebound
    haskey(of, name) && (of[name] = read_shortcuts(text))
  end
  commands = Dict{Shortcut,Symbol}()
  # A shortcut that two commands have runs the one that the page lists first
  for (_, cs) in COMMAND_GROUPS, c in cs, s in of[c.name]
    get!(commands, s, c.name)
  end
  starts = Set{Stroke}(first(s) for s in keys(commands) if length(s) == 2)
  e.nodes[:keys] = (bundle=e.bundle, rebound=e.rebound, of=of, commands=commands, starts=starts, count=length(COMMANDS))
end

"The command that the key `K` runs by itself in window `w`, with the keys that are held there, or nothing"
command_of(e, w, K) = get(keys_now(e).commands, (Stroke(w.keys & HELD, K),), nothing)

"""
The command that the key `K` runs in window `w`, with the keys that are held
there, and true when ⇧ is held to grow the selection. The command is `:wait`
for a key that does nothing by itself: the first key of a shortcut of two, or
a second key that ends no shortcut. It's nothing for a key with no command.
"""
command!(e, w, K) = begin
  (ismouse(K) || K in HELD || K == Keys.capslock || K == Keys.fn) && return (nothing, false)
  ks = keys_now(e)
  s = Stroke(w.keys & HELD, K)
  before = pop!(e.nodes, :stroke, nothing)
  name, select = if before !== nothing
    (get(ks.commands, (before, s), :wait), false)
  elseif haskey(ks.commands, (s,))
    (ks.commands[(s,)], false)
  elseif s in ks.starts
    e.nodes[:stroke] = s
    (:wait, false)
  else
    # ⇧ with the keys of a command that moves the caret grows the selection. With a key like ⌫, it changes nothing.
    found = Keys.shft in s.held ? get(ks.commands, (Stroke(setdiff(s.held, Keys.shft), K),), nothing) : nothing
    kind = found === nothing ? :none : COMMANDS[found].kind
    kind == :move ? (found, true) : kind == :type ? (found, false) : (nothing, false)
  end
  # A key that types a character types nothing when it's the key of a command, like ⌥F in the Emacs bundle
  name !== nothing && typing_key(K) && !(Keys.cmd in s.held) && !(Keys.ctrl in s.held) && (e.nodes[:mute] = time())
  (name, select)
end

"The commands that are done at each selection when there are several: the ones that go along a line, and the ones that delete"
const AT_EACH = Set([:left, :right, :word_left, :word_right, :line_start, :line_end, :bold, :italic, :value_up, :value_down,
                     :erase_back, :erase, :erase_word_back, :erase_word, :erase_line_start, :erase_line_end])

"Run the command called `name` in the window `w` of `e`"
run!(e, w, name::Symbol, select::Bool=false) =
  name in AT_EACH ? each_selection!(() -> COMMANDS[name].run(e, w, select), e) : COMMANDS[name].run(e, w, select)

"The first shortcut of the command `name` with two spaces before it, to end a tooltip with, or nothing when the command has no keys"
hint(e, name::Symbol) = (list = keys_now(e).of[name]; isempty(list) ? "" : "  " * caps(first(list)))

"True when one of the shortcuts `a` and `b` starts with the other, so the keys of one would run the other"
clashes(a::Shortcut, b::Shortcut) = (n = min(length(a), length(b)); a[1:n] == b[1:n])

"""
Use the bundle called `bundle`, with the shortcuts in `rebound` for the commands
that have other keys than the bundle's. Every window gets them, and they're kept.
"""
keys!(e, bundle::String, rebound::Dict{Symbol,String}) = begin
  usual = bundle_keys(bundle)
  # A command that has the bundle's own shortcuts again isn't changed any more
  e.bundle, e.rebound = bundle, filter(((name, text),) -> haskey(usual, name) && read_shortcuts(text) != usual[name], rebound)
  delete!(e.nodes, :stroke)
  save_settings!(e)
  rerun!(e, :bundle)
  rerun!(e, :rebound)
  e
end

"Use the bundle of key bindings called `name`. Every command gets the bundle's keys, so the keys that were changed go back too."
bundle!(e, name::String) = begin
  any(b -> first(b) == name, BUNDLES) || error("The bundles of key bindings are $(join(first.(BUNDLES), ", ", " and ")). $name isn't one of them.")
  keys!(e, name, Dict{Symbol,String}())
end

"""
Give the command `name` the shortcut `s`, and no other. A command that had
those keys, or keys that start the same way, loses them. Returns the names
of the commands that lost a shortcut.
"""
rebind!(e, name::Symbol, s::Shortcut) = begin
  new = copy(e.rebound)
  lost = Symbol[]
  for (other, list) in keys_now(e).of
    other == name && continue
    kept = filter(o -> !clashes(o, s), list)
    length(kept) == length(list) && continue
    new[other] = written(kept)
    push!(lost, other)
  end
  new[name] = written(Shortcut[s])
  keys!(e, e.bundle, new)
  lost
end

"Give the command `name` the bundle's shortcuts again. A command that has one of them now loses it."
put_back!(e, name::Symbol) = begin
  new = copy(e.rebound)
  delete!(new, name)
  lost = Symbol[]
  for s in bundle_keys(e.bundle)[name], (other, list) in keys_now(e).of
    other == name && continue
    kept = filter(o -> !clashes(o, s), read_shortcuts(get(new, other, written(list))))
    length(kept) == length(list) && continue
    new[other] = written(kept)
    other in lost || push!(lost, other)
  end
  keys!(e, e.bundle, new)
  lost
end

# The key bindings page shows the commands in a list. Each row has the command's shortcuts at its right.
# A click on a row waits for the keys of its new shortcut.

"The list of the commands on the key bindings page"
@def mutable struct KeyList <: SemanticUI end
"A command's row in that list. A click on it waits for the command's new keys."
@def mutable struct KeyRow <: SemanticUI
  name::Symbol = :save
end
"The words in a row that give its command the bundle's keys again"
@def mutable struct KeyReset <: SemanticUI
  name::Symbol = :save
end

const KEY_ROW_H = 34px

"A shortcut as the list shows it: its keys in a box"
keycap(s::Shortcut) = Box(height(22px), padding(7px, 0px), radius(5px), background(colours.float), border(1px, :solid, colours.line),
                          label(caps(s), 12px, color=colours.ink))

"The command whose row waits for new keys, or nothing"
key_asking(e) = get(e.nodes, :key_asking, nothing)

"Stop waiting for a command's new keys, and give the keyboard back to the text"
stop_asking_keys!(e) = (delete!(e.nodes, :key_asking); focus(e); handled)

"What the list says under the row of `name`, after its new keys took the keys of the commands in `lost`"
lost_note!(e, name::Symbol, lost) = begin
  isempty(lost) && return delete!(e.nodes, :key_note)
  titles = [COMMANDS[other].title for other in lost]
  none = [other for other in lost if isempty(keys_now(e).of[other])]
  e.nodes[:key_note] = (name, "\"$(join(titles, "\", \"", "\" and \""))\" had $(length(lost) == 1 ? "this key" : "these keys") before." *
                              (isempty(none) ? "" : length(lost) == 1 ? " It has no key now." : " $(length(none)) of them have no key now."))
end

describe(l::KeyList) = begin
  e = editor(l)
  row(name) = node!(() -> KeyRow(name=name), e, (:key_row, name))
  Column(width(grow=grow), Alignment.Start, name="Key bindings",
    Iterators.flatten(((Box(width(grow=grow), height(40px), padding(10px, 0px, 6px, 10px), Alignment.End,
                            Row(width(grow=grow), label(group, 12px, color=colours.dim, weight="Semibold"))),
                        map(c -> row(c.name), cs)...) for (group, cs) in COMMAND_GROUPS))...)
end

describe(r::KeyRow) = begin
  e = editor(r)
  w = window_of(e)
  waits = key_asking(e) == r.name
  # A click somewhere else gives the keyboard to something else, and the row stops waiting
  waits && (w === nothing || w.focus !== r) && (delete!(e.nodes, :key_asking); waits = false)
  list = keys_now(e).of[r.name]
  under = get(e.nodes, :key_note, (:none, ""))
  # Words by themselves would take half of the row, so each is in a box that's as wide as the words
  right = waits ? (Box(label(get(e.nodes, :key_refused, "Press the new keys, or esc to keep these"), 12px, color=colours.accent)),) :
          isempty(list) ? (Box(label("No keys", 12px, color=colours.faint)),) : map(keycap, list)
  row = Row(width(grow=grow), height(KEY_ROW_H), padding(10px, 0px), radius(6px), child_gap=6px, name="Command",
            background(waits ? colours.active : ishovered(r) ? colours.hover : clear),
    Box(width(grow=grow), Alignment.Start, label(COMMANDS[r.name].title, 14px)),
    (haskey(e.rebound, r.name) && !waits ? (node!(() -> KeyReset(name=r.name), e, (:key_reset, r.name)),) : ())...,
    right...)
  under[1] == r.name || return row
  Column(width(grow=grow), Alignment.Start, row,
    Box(width(grow=grow), padding(10px, 0px, 8px, 10px), Alignment.Start, label(under[2], 12px, color=colours.dim)))
end

cursor(::KeyRow) = :hand

onkey(r::KeyRow, ::KeyPress{Keys.mouse_left}) = begin
  e = editor(r)
  e.nodes[:key_asking] = r.name
  delete!(e.nodes, :key_refused)
  delete!(e.nodes, :key_note)
  focus(r)
  handled
end

# While a row waits, the next key with the keys held with it is the command's new shortcut. esc leaves the command as it was.
onkey(r::KeyRow, ev::KeyPress{K}) where K = begin
  e = editor(r)
  key_asking(e) == r.name || return nothing
  ismouse(K) && return nothing
  (K in HELD || K == Keys.capslock || K == Keys.fn) && return handled
  K == Keys.escape && return stop_asking_keys!(e)
  s = Stroke(ev.window.keys & HELD, K)
  # The text gets the keyboard back before the key types its character, like the π of ⌥P, so the character is dropped
  typing_key(K) && !(Keys.cmd in s.held) && !(Keys.ctrl in s.held) && (e.nodes[:mute] = time())
  if typing_key(K) && !(Keys.cmd in s.held) && !(Keys.ctrl in s.held) && !(Keys.opt in s.held)
    e.nodes[:key_refused] = "$(caps(s)) types a character. Hold ⌘, ⌃ or ⌥ with it."
    return handled
  elseif K == Keys.enter && s.held == Keys(0)
    e.nodes[:key_refused] = "Return starts a new line. Hold ⌘, ⌃, ⌥ or ⇧ with it."
    return handled
  end
  lost_note!(e, r.name, rebind!(e, r.name, (s,)))
  stop_asking_keys!(e)
end
ontype(r::KeyRow, ::Typed) = key_asking(editor(r)) == r.name ? handled : nothing

describe(b::KeyReset) = Box(height(22px), padding(7px, 0px), radius(5px), background(ishovered(b) ? colours.active : clear),
                            label("Put back", 12px, color=colours.dim))
cursor(::KeyReset) = :hand
onkey(b::KeyReset, ::KeyPress{Keys.mouse_left}) = begin
  e = editor(b)
  lost_note!(e, b.name, put_back!(e, b.name))
  handled
end

# A mouse can have two buttons at its side, which go back and forward in a web browser. Here they do what
# ⌘⌥← and ⌘⌥→ do. A press of one isn't for the place that the mouse is over. It comes to the part of the
# window that has the keyboard, and from there to here.
onkey(e::Editor, ev::KeyPress{Keys.mouse_back}) = side_button!(e, ev.window, :back)
onkey(e::Editor, ev::KeyPress{Keys.mouse_forward}) = side_button!(e, ev.window, :forward)

"Run the `command` of a button at the side of the mouse: `:back` or `:forward`"
side_button!(e, w, command) = begin
  e = top_editor(e)   # in a part of another page, they go back and forward in the window's page
  # While a picture fills the window, or the file finder is open, the page under it stays, as it does for the keys
  (zooming(e) === nothing && e.popup == :none) || return nothing
  run!(e, w, command)
  nothing
end

# A press of a mouse button that nothing under the mouse took comes here. It has a method of its own, so the
# first click in a window doesn't wait for the code of the key bindings to be made ready.
onkey(e::Editor, ev::Union{KeyPress{Keys.mouse_left},KeyPress{Keys.mouse_right},KeyPress{Keys.mouse_middle}}) = begin
  pop!(e.nodes, :chose, false) && return
  # While a picture or a model fills the window, a right-click has no menu
  zooming(e) === nothing || e.popup != :none || return
  slideshow(e) === nothing || return   # nor has a right-click on a slide
  ev isa KeyPress{Keys.mouse_right} && return context_menu!(e, ev.window)
  nothing
end

"""
What a key does. The key bindings say which command it runs. Return, esc and
Space have no command: what they do depends on where the caret is.
"""
onkey(e::Editor, ev::KeyPress{K}) where K = begin
  # A key that the sidebar's tree took, like Return on a heading, comes here next. It isn't for the text.
  pop!(e.nodes, :chose, false) && return
  w = ev.window
  # The first key of a shortcut of two, like ⌃X, does nothing but wait for the second
  command, select = command!(e, w, K)
  command == :wait && return
  # In a part of another page, a key for the window is the window's page's, and esc goes back to that page
  hosted(e) === nothing || !part_key!(e, w, K, command, select) || return handled
  # In the text of a request in place, Return gives the request to the agent and esc takes the field away
  ask_box_of(e) === nothing || !ask_key!(e, w, K, command) || return handled
  # In a field of a SolidCraft design, Return, Esc, Tab and the window's keys are the design's and the window's
  field = design_field_of(e)
  field === nothing || (done = design_key!(field, e, w, K, command); done === :text || return done)
  # While the command palette shows, every key is its own, whatever part of it has the keyboard
  e.popup == :commands && return (palette_key!(e, w, K, command); K == Keys.tab ? handled : nothing)
  kind = command === nothing ? :none : COMMANDS[command].kind
  # The commands that close the window and show the settings work whatever has the keyboard. A slider
  # on the settings page takes the keyboard when it's dragged, and ⌘, still closes that window.
  command in (:close, :settings) && return (run!(e, w, command); nothing)
  # While a picture or a model fills the window, the keys are its own. Esc puts the page back.
  zoomed = zooming(e)
  zoomed === nothing || e.popup != :none || zoom_key!(zoomed, K, w, command) !== handled || return
  # The picture, the PDF file or the video that covers a file's own page takes the keys that are its own
  zoomed === nothing && e.popup == :none && file_key!(e, K, w, command) === handled && return
  # While the page shows as slides, the keys go from one slide to another. Esc shows the page again.
  slideshow(e) === nothing || slide_key!(e, K, w, command) !== handled || return
  shift = only_held(w, Keys.shft)
  b = e.buf
  # While a part of a live block has the keyboard, the keys are its own and don't change the text.
  # Escape gives the keyboard back to the text. A command for the window, like the one that saves, still runs.
  if w.focus !== e && w.focus !== input(e)
    if w.focus === find_input(e)
      find_key!(e, w, K, command)
    elseif w.focus === renamer(e)
      rename_key!(e, K)
    elseif K == Keys.escape && unmodified(w)
      hide_menu!(w)
      focus(e)
    elseif command in (:sidebar, :sidebar_keys) && w.focus === file_tree(e)
      # While the sidebar has the keyboard, its two commands give the keyboard back to the text, and the first hides it too
      command == :sidebar && toggle_panel!(e)
      focus(e)
    elseif any(f -> f(e, w, K), values(FIELD_KEYS))
      # Code from the startup page took the key, like Return in a field of a form that it shows
    elseif kind == :window
      run!(e, w, command)
    end
    # Tab goes from one field of a live block to the next. In the field that finds text, and the one
    # that renames a file, it stays where it is.
    return K == Keys.tab && (w.focus === find_input(e) || w.focus === renamer(e)) ? handled : nothing
  end
  e.popup in (:finder, :projects) && return (finder_key!(e, K); K == Keys.tab ? handled : nothing)
  # The list of names under a sheet's expression takes ↑, ↓, Return, Tab and esc
  unmodified(w) && suggest_key!(e, K) && return nothing
  # Esc hides the box that lists what a function takes
  unmodified(w) && call_key!(e, K) && return nothing
  # While the page is read, there's no caret to move, so the keys that would move it scroll the
  # page. A key that would change the text at the caret does nothing. Any other command still
  # works, and one that moves the caret, like undo, puts it back.
  if caretless(b) || readonly(b)
    step = read_step(e, K, command, held_keys(w))
    step === nothing || return (scroll_page!(e, step); nothing)
    K == Keys.escape || kind in (:window, :look, :edit) || return nothing
  end
  # A file that's only shown takes the commands that don't change it. Its text can be selected, copied and searched.
  if readonly(b) && K != Keys.escape
    kind == :window || (kind == :look && b.view != :file) || return nothing
  end
  if K == Keys.escape && finding(e) && unmodified(w)
    close_find!(e)
  elseif K == Keys.escape && unmodified(w)
    # Escape closes a popup. With none open, it takes away what the page's code came to. With
    # none of that either, it hides the caret, and so every line shows as it reads.
    if e.popup != :none
      e.popup = :none
    elseif !isempty(others(b))
      # With several selections, Escape leaves the one that was there first, and the page goes back to it
      b.anchor, b.caret = first(b.others)
      empty!(b.others)
      touch!(e)
    elseif lowered(e) !== nothing
      # The lines of a block that fill the window go back among the lines of the page
      widen!(e)
    elseif !forget_outcomes!(e)
      b.anchor = b.caret
      b.reading = true
    end
  elseif command !== nothing
    run!(e, w, command, select)
  elseif K == Keys.enter && (unmodified(w) || shift)
    each_selection!(() -> newline!(e), e)
  end
  nothing
end

# What a key types comes as a character, so each keyboard types its own letters:
# ß on a German keyboard, é from ⌥E and then E, and an emoji from the Mac's
# emoji list. A key that's held with ⌘ types nothing.
ontype(e::Editor, ev::Typed) = begin
  # The key that types this just ran a command, like ⌥F in the Emacs bundle, so it types nothing
  time() - pop!(e.nodes, :mute, 0.0) < 0.5 && return handled
  # A character that a part of a live block didn't take comes here next. It isn't for the text.
  ev.window.focus === e || return nothing
  zooming(e) === nothing || return handled   # the page under a picture that fills the window doesn't change
  c = ev.char
  # macOS has characters of its own for keys like the arrows, which aren't text
  (iscntrl(c) || '\uf700' <= c <= '\uf8ff') && return nothing
  # While the page is read, a key that would change the text does nothing. A file that's only shown is never changed.
  (caretless(e.buf) || readonly(e.buf)) && return nothing
  # Nor does a character change a part that the caret is on as a whole, like a diagram
  picked(e.buf) === nothing || return nothing
  # In code, a bracket or a quote comes with the one that closes it
  each_selection!(() -> pair!(e, c) || type!(e, string(c), typing=true), e)
  # A code block offers names only just after a character is typed
  e.nodes[:typed_at] = (e.buf.path, e.buf.version, e.buf.caret)
  # The ( of a call opens the box of what the function takes, and so does a , or a ; in a call
  c in ('(', ',', ';') && call_typed!(e, c)
  handled
end

# --- files dropped on the page -----------------------------------------------------------
#
# A file that's dropped on the page from the Finder goes into the text. A
# picture goes on a line of its own under the line it's dropped on, written as
# ![name](path), so the page shows it. A CSV file goes in the same way, and
# the page shows it as a table. A Markdown file goes in where it's
# dropped as a link to it. Any other file, and a folder, goes in there as a
# path that shows as a breadcrumb: !`fs"path"`.

"`path` as the text names it: from the folder of the document when it's in that folder, and whole when it isn't"
named(e, path) = (dir = docdir(e); startswith(path, dir * "/") ? relpath(path, dir) : path)

"`path` as a link writes it. A space or a bracket would end the link early, so each is written as its code."
escaped(path) = replace(path, ' ' => "%20", '(' => "%28", ')' => "%29")
"The path that a link wrote with `escaped`"
unescaped(path) = replace(path, "%20" => ' ', "%28" => '(', "%29" => ')')

ispicture(path) = (ext = lowercase(splitext(path)[2]); ext in PICTURES || ext in MAC_PICTURES)

"The Markdown that shows the file or the folder at `path`"
markdown_for(e, path) = begin
  name, at = splitext(basename(path))[1], named(e, path)
  ispicture(path) || istable(path) ? "![$name]($(escaped(at)))" : ismarkdown(path) ? "[$name]($(escaped(at)))" : "!`fs\"$(replace(at, '"' => "\\\""))\"`"
end

onfiledrop(e::Editor, w::Window, paths) = begin
  e.buf.view == :markdown || return nothing   # a file goes into a page as Markdown
  slideshow(e) === nothing || return nothing   # the text doesn't change while the page shows as slides
  # A PDF file or a picture that's dropped on a takeoff is its plan
  v = takeoff_at(e, w)
  plan = v === nothing ? nothing : findfirst(p -> isfile(p) && (ispdf(p) || ispicture(p)), paths)
  plan === nothing || return plan!(v, rstrip(String(paths[plan]), '/'))
  # A picture or a page that's dropped on a canvas goes on the board where it's dropped
  board = canvas_at(e, w)
  board === nothing || board.zoom <= 0 || return (put_on_board!(board, paths, board_place(board, num(w.mouse[1]), num(w.mouse[2]))); nothing)
  # A file or a folder that's dropped on a gallery goes into the gallery
  g = gallery_at(e, w)
  g !== nothing && add_files!(g, paths) && return nothing
  # A vCard file that's dropped on a block of contacts joins the block
  c = contacts_at(e, w)
  if c !== nothing
    list, paths = split_contacts(paths)
    add_contacts!(c, list)
    isempty(paths) && return nothing
  end
  put_files!(e, paths, settle(e.buf, locate(e, w.mouse)))
end

"Put the files and folders at `paths` into the text at `at`, the way a drop there does. ⌘V does this with files that were copied."
put_files!(e, paths, at::Pos) = begin
  paths = [rstrip(String(p), '/') for p in paths if ispath(p)]
  isempty(paths) && return
  b = e.buf
  b.view == :markdown || return   # only a page has text for the path to go into, as Markdown
  # A vCard file goes in as a block of its contacts
  list, paths = split_contacts(paths)
  at = put_contacts!(e, list, at)
  # A CSV file goes on a line of its own as a picture does, so the page shows it as a table
  pictures = [markdown_for(e, p) for p in paths if isfile(p) && (ispicture(p) || istable(p))]
  others = [markdown_for(e, p) for p in paths if !(isfile(p) && (ispicture(p) || istable(p)))]
  if !isempty(others)
    line = b.lines[at[1]]
    # What's dropped on a word goes after the word, not into it
    at = (at[1], word_at(line, at[2])[2])
    # A space goes between what's dropped and the words on each side of it, but not before a full stop or a comma
    before = at[2] > 0 && !isspace(line[nextind(line, 0, at[2])]) ? " " : ""
    next = at[2] < length(line) ? line[nextind(line, 0, at[2] + 1)] : ' '
    after = isspace(next) || next in ".,;:!?)]}" ? "" : " "
    new = before * join(others, " ") * after
    edit!(b, at, at, new)
    at = (at[1], at[2] + length(new))
  end
  if !isempty(pictures)
    # Under the block that it's dropped on, so that a picture doesn't go into the middle of a table
    under = block_end(b, at[1])
    empty = isempty(strip(b.lines[under]))
    edit!(b, empty ? (under, 0) : line_end(b, under), line_end(b, under), (empty ? "" : "\n\n") * join(pictures, "\n\n"))
    under += (empty ? 0 : 2) + 2(length(pictures) - 1)
    at = line_end(b, under)
  end
  b.caret = b.anchor = at
  focus(e)
  touch!(e)
end

# --- the bar over a table ----------------------------------------------------------------
#
# While the caret is in a table, a small bar floats over the table's top left
# corner. Its buttons add and remove a row or a column at the caret, and put the
# text of the caret's column on the left, in the centre or on the right.

const TABLE_ACTIONS = (:addrow => "+Row", :delrow => "−Row", :addcol => "+Col", :delcol => "−Col",
                       :left => "L", :center => "C", :right => "R")
const DASHES = (left=":---", center=":---:", right="---:")
const ALIGN_ICONS = (left="text-left", center="text-center", right="text-right")
const BAR_H = 26px

"Change the table the caret is in, then put the caret back in a cell"
tableop!(e, action::Symbol) = begin
  b = e.buf
  inspread(b, b.caret[1]) && return spreadop!(e, action)
  run = table(b, b.caret[1])
  run === nothing && return
  s, t = run
  i = b.caret[1] == s + 1 ? s : b.caret[1]
  cs = tablecells(b.lines[i])
  c = isempty(cs) ? 1 : nearest(cs, b.caret[2])
  rows = map(celltexts, b.lines[s:t])
  n = maximum(length, rows)
  rows = [[r; fill(k == 2 ? "---" : "", n - length(r))] for (k, r) in enumerate(rows)]
  k = i - s + 1   # the caret's row in `rows`, where row 2 is the line of dashes
  if action == :addrow
    k = max(k, 2) + 1
    insert!(rows, k, fill("", n))
  elseif action == :delrow
    k == 1 && return   # the heading row stays
    deleteat!(rows, k)
    k = k > length(rows) ? (length(rows) > 2 ? length(rows) : 1) : k
  elseif action == :addcol
    c += 1
    foreach((j, r) -> insert!(r, c, j == 2 ? "---" : ""), eachindex(rows), rows)
  elseif action == :delcol
    n == 1 && return
    foreach(r -> deleteat!(r, c), rows)
    c = min(c, n - 1)
  else
    rows[2][c] = getproperty(DASHES, action)
  end
  edit!(b, (s, 0), line_end(b, t), join(map(tableline, rows), "\n"))
  line = s + k - 1
  cell = tablecells(b.lines[line])[c]
  b.caret = b.anchor = (line, cell.hi)
  touch!(e)
end

# The three buttons that move a column's text show the usual picture of lines of text on that side
"True when the caret is in a row of a table, under the heading row, that has no text in any cell"
emptyrow(b::Buffer) = begin
  inspread(b, b.caret[1]) && return !selecting(b) && all(isempty, spreadtexts(b.lines[b.caret[1]]))
  run = table(b, b.caret[1])
  run !== nothing && !selecting(b) && b.caret[1] > run[1] + 1 && all(isempty, celltexts(b.lines[b.caret[1]]))
end

"Backspace in an empty row removes the row and puts the caret at the end of the row above"
backrow!(e) = begin
  b = e.buf
  inspread(b, b.caret[1]) && return droprow!(e)
  s, _ = table(b, b.caret[1])
  i = b.caret[1]
  tableop!(e, :delrow)
  above = i - 1 == s + 1 ? s : i - 1
  cs = tablecells(b.lines[above])
  isempty(cs) || (b.caret = b.anchor = (above, cs[end].hi))
  touch!(e)
end

describe(t::TableButton) =
  Box(height(BAR_H - 6px), padding(7px, 0px), radius(4px), background(ishovered(t) ? colours.hover : clear),
    haskey(ALIGN_ICONS, t.action) ? Icon(getproperty(ALIGN_ICONS, t.action), size=13px, color=colours.dim) :
                                    label(t.label, 11px, color=colours.dim))

cursor(::TableButton) = :hand
onkey(t::TableButton, ::KeyPress{Keys.mouse_left}) = (e = editor(t); tableop!(e, t.action); focus(e))

"The bar over the table the caret is in, placed in the window. Nothing when the caret isn't in a table."
tablebar(e) = begin
  b = e.buf
  (!caretless(b) && b.caret[1] == b.anchor[1] && !isempty(e.layout)) || return ()
  it = item(e, b.caret[1])
  it.content isa Grid || return ()
  top = TOPBAR_H + PAGE_TOP + it.top + TABLE_GAP - e.scroll.offset - BAR_H - 3px
  top >= TOPBAR_H || return ()
  bar = Row(height(BAR_H), padding(3px, 0px), radius(6px), background(colours.float), border(1px, :solid, colours.line), lifted,
    # A spreadsheet has no buttons that move a column's text: a number goes on the right and text on the left
    [node!(() -> TableButton(action=a, label=l), e, (:table, a)) for (a, l) in TABLE_ACTIONS[1:(isspread(it.content) ? 4 : end)]]...)
  # The page's text is in the middle of the space beside the file panel
  w, _ = window_size(e)
  side = panel_w(e) * opened(e)
  left = side + max(PAGE_X, (w - side - e.width) / 2) + item_room(e, it)[1]
  (Row(width(grow=grow), height(grow=grow), Alignment.Start, padding(top, 0px, 0px, left), bar),)
end

# --- the top bar ------------------------------------------------------------------------

describe(b::ToolButton) = begin
  e = editor(b)
  ishovered(b) || (b.quiet = false)
  on = (b.action == :panel && e.panel) || (b.action == :marks && marking(e)) || (b.action == :hidden && e.hidden) ||
       (haskey(BUTTONS, b.action) && get(BUTTONS[b.action], :on, _ -> false)(e))
  # A button whose work takes a while, like a commit while the agent writes its message, spins until it's done
  busy = haskey(BUTTONS, b.action) && get(BUTTONS[b.action], :busy, _ -> false)(e)
  # A half button, like each chevron beside the diff button, is half as tall as the others, with one over the other, and narrow
  half = haskey(BUTTONS, b.action) && get(BUTTONS[b.action], :half, false) !== false
  box = Box(width(half ? 18px : 30px), height(half ? 14px : 28px), radius(half ? 4px : 6px), Alignment.Center, name="Button",
            background(on ? colours.active : ishovered(b) && !off(b) ? colours.hover : clear),
          busy ? Spinner(size=15px) :
          Icon(b.icon, size=half ? 9px : 15px, color=off(b) ? colours.faint : haskey(BUTTONS, b.action) && BUTTONS[b.action].strong ? colours.accent : colours.dim))
  # While the sidebar is closed, a dot beside its button says that an agent waits for a page that isn't showing
  (b.action == :panel && waiting_dot(e)) || return box
  Row(Alignment.Center, child_gap=DOT_GAP, box, Box(width(DOT_W), height(DOT_W), radius(DOT_W / 2), background(colours.accent)))
end

const DOT_W = 7px     # how wide the dot beside the sidebar's button is
const DOT_GAP = 4px   # the room between the button and its dot

"True when the sidebar's button has a dot beside it: the sidebar is closed, and an agent waits for a page that isn't showing"
waiting_dot(e) = !e.panel && !isempty(elsewhere(e))

cursor(b::ToolButton) = off(b) ? :arrow : :hand

onkey(b::ToolButton, ::KeyPress{Keys.mouse_left}) = begin
  e = editor(b)
  b.action == :panel && toggle_panel!(e)
  b.action == :outside && open_outside!(e)
  b.action == :marks && toggle_marks!(e)
  b.action == :hidden && hidden!(e, !e.hidden)
  b.action == :back && go_back!(e)
  b.action == :forward && go_forward!(e)
  b.action == :job && make_job!(e)
  b.action in BLOG_ACTIONS && blog_act!(e, b.action)
  haskey(BUTTONS, b.action) && BUTTONS[b.action].run(e)
  hush!(b)
  # A button that opened the palette, like Commit's, leaves the keyboard in it
  e.popup == :commands || focus(e)
end

# Each button in the top bar says what it does while the mouse is over it. A
# click hides what it says until the mouse leaves the button.

const Tipped = Union{ToolButton,SendButton,Mode,CheckCount,ReadOnly}
const TIP_INK = colorant"rgb(240,240,240)"   # on the dark grey that every tooltip has

"What a tooltip shows: `words`, with room around them"
tip_label(words) = Box(padding(10px, 7px), label(words, 12px, color=TIP_INK))

# The colours of code in a tooltip. A tooltip is dark grey in each theme, so
# they're the night theme's, with comments lighter so that they can be read.
const TIP_CODE = (comment=colorant"rgb(150,150,156)", string=NIGHT.string, number=NIGHT.number,
                  keyword=NIGHT.keyword, call=NIGHT.call, type=NIGHT.type, added=NIGHT.added, removed=NIGHT.removed)

"""
Lines of code in a tooltip, each a row `high` tall, with the colours that code
has in the page. `lang` is the code's language, like julia: text that isn't
code is all `TIP_INK`. The lines inside three quotes, like the middle of a
docstring, are all the colour of a string. `open` is the quote of one that's
open at the first line, as `string_opens` gives it, or '\\0'.
"""
tip_code(lines, lang="julia"; high=17px, open='\0') = begin
  face(kind) = Face(codefont(), kind == :comment ? codeslant() : codestyle(), 12px,
                    kind == :plain ? TIP_INK : getfield(TIP_CODE, kind), false)
  rows = Any[]
  for line in lines
    parts = tokens(line, lang, open)
    open = left_open(line, lang, open)
    push!(rows, Box(height(high), Row(Alignment.Start, [p for t in parts if !isempty(t.text) for p in spared(t.text, face(t.kind))]...)))
  end
  rows
end

"What the tooltip of a button in the top bar says"
tip(b::ToolButton) = begin
  e = editor(b)
  if b.action == :panel
    e.panel && return "Hide sidebar" * hint(e, :sidebar)
    ws = elsewhere(e)
    # The dot beside the button is for the first of these
    isempty(ws) && return "Show sidebar" * hint(e, :sidebar)
    return "$(uppercasefirst(first(ws).name)) waits for $(basename(first(ws).page))  ·  Show sidebar" * hint(e, :sidebar)
  end
  b.action == :marks && return marking(e) ? "Hide $(whose(e)) changes" : "Show $(whose(e)) changes"
  b.action == :hidden && return (e.hidden ? "Leave out hidden files" : "Show hidden files") * hint(e, :hidden_files)
  if b.action == :back
    to = step_words(e)
    return to === nothing ? "No file to go back to" : "Back to $to" * hint(e, :back)
  elseif b.action == :forward
    to = step_words(e, e.ahead)
    return to === nothing ? "No file to go forward to" : "Forward to $to" * hint(e, :forward)
  end
  b.action == :job && return job_tip(e)
  b.action in BLOG_ACTIONS && return blog_tip(e, b.action)
  haskey(BUTTONS, b.action) && return BUTTONS[b.action].tip(e)
  b.action == :outside || return ""
  "Open in $(app_name(opener(e.buf.path)))"
end
tip(s::SendButton) = begin
  e = editor(s)
  ws = agents(e)
  isempty(ws) ? "Nudged $(get(e.nodes, :agent, "the agent"))" : "Nudge $(first(ws).name) with what you changed" * hint(e, :run)
end

tip(::ReadOnly) = "Read only"

const LOCK_W = 26px   # how wide the lock is in the top bar

describe(::ReadOnly) = Box(width(LOCK_W), height(28px), Alignment.Center, Icon("lock", size=14px, color=colours.dim))

"The lock in the top bar of `e`"
lock_part(e) = node!(() -> ReadOnly(), e, :read_only)

draw(ctx, size, ui::ConcreteRect, b::Tipped) = (b.rect = (ui.left, ui.top, ui.width, ui.height); nothing)

onmouse(b::Tipped, ev::MouseMove) = begin
  b.quiet && return
  show_tooltip!(ev.window, tip_label(tip(b)), tip_rect(b)...,
                placement=:bottom, gap=6px)
end

"What a button's tooltip points at: the button itself, or the upper half button and the one under it, so the tooltip doesn't cover the lower one"
tip_rect(b::Tipped) = b.rect
tip_rect(b::ToolButton) = haskey(BUTTONS, b.action) && get(BUTTONS[b.action], :half, false) == :top ?
                          (b.rect[1], b.rect[2], b.rect[3], 2b.rect[4]) : b.rect

hush!(b::Tipped) = (b.quiet = true; hide_tooltip!(window_of(b)))

commas(n::Int) = replace(string(n), r"(?<=\d)(?=(\d{3})+$)" => ",")

button(e, action, icon) = node!(() -> ToolButton(icon=icon, action=action), e, action)

# --- a page that an agent waits for -------------------------------------------------------
#
# An agent like Claude Code writes a page, shows it here and waits (see
# agent.jl). While it waits, the top bar has a button with a bell that sends the page: it
# saves the file and tells the agent which lines you changed. ⌘Return does the
# same. The agent can change the file while you type, and the page keeps both.

"Every agent that waits, for any page. The folder that lists them is read twice a second."
waiters(e) = begin
  at, found = get(e.nodes, :agents, (0.0, Agent.Waiter[]))::Tuple{Float64,Vector{Agent.Waiter}}
  time() - at < 0.5 && return found
  Agent.announce()
  found = Agent.waiters()
  e.nodes[:agents] = (time(), found)
  found
end

# An agent names its page by the path that has no links in it. Each file's path of that kind is found once.
const TRUE_PATHS = Dict{String,String}()
truepath(path) = get!(() -> ispath(path) ? realpath(path) : abspath(path), TRUE_PATHS, path)

"The agents that wait for the file at `path`"
agents(e, path) = begin
  ws = waiters(e)
  (isempty(ws) || isempty(path)) && return ws[1:0]
  at = truepath(path)
  filter(w -> w.page == at, ws)
end

"The agents that wait for the page that's showing"
agents(e) = readonly(e.buf) ? Agent.Waiter[] : agents(e, e.buf.path)

"The agents that wait for a page that isn't the one that's showing"
elsewhere(e) = begin
  ws = waiters(e)
  isempty(ws) && return ws
  at = isempty(e.buf.path) ? "" : truepath(e.buf.path)
  filter(w -> w.page != at, ws)
end

"Save the page and tell each agent that waits for it what you changed. Nothing happens if no agent waits."
send!(e) = begin
  b = e.buf
  delete!(e.nodes, :agents)
  ws = agents(e)
  isempty(ws) && return
  save!(b)
  lo, hi = selection(b)
  hand_over!(e, ws, Agent.report(b.path, b.told, b.lines, lo[1], selecting(b) ? excerpt(b, lo, hi) : ""))
end

"Give the agents `ws`, which wait for the page of `e`, the text `text`, which tells them of the page as it is now"
hand_over!(e, ws, text) = begin
  b = e.buf
  foreach(w -> Agent.send(w, text), ws)
  # The agent knows the page as it is now, and none of the lines are its changes any more
  b.sent = b.told = copy(b.lines)
  delete!(e.nodes, :marking)
  e.nodes[:sent] = (b.path, b.version, first(ws).name)
  delete!(e.nodes, :agents)
  nothing
end

"""
What the top bar shows of the agent: a button while one waits, and a few
words after you sent the page. The button that shows the agent's changes is
beside the diff button (see `diff_part`).
"""
agent_part(e) = begin
  b = e.buf
  ws = agents(e)
  sent = get(e.nodes, :sent, nothing)
  if !isempty(ws)
    delete!(e.nodes, :sent)
    e.nodes[:agent] = first(ws).name
    (node!(SendButton, e, :send),)
  elseif sent !== nothing && sent[1] == b.path && sent[2] == b.version
    # The button shows that the page was sent, until the agent waits again or the text changes
    (node!(SendButton, e, :send),)
  else
    ()
  end
end

"""
The runs of lines of the page that were changed from outside, by an agent,
since you last sent the page, or since it was opened. Lines that were removed
leave nothing to show.
"""
theirs(e) = begin
  b = e.buf
  none = UnitRange{Int}[]
  (readonly(b) || b.sent === b.told) && return none
  # They're worked out again when the text changes, or what the agent knows
  key = (objectid(b.sent), objectid(b.told), b.version)
  kept = get(e.nodes, :theirs, nothing)
  kept !== nothing && kept[1] == key && return kept[2]::Vector{UnitRange{Int}}
  mine = changes(b.told, b.lines)   # your own changes since, which move the agent's lines down or up
  runs = UnitRange{Int}[]
  for (_, new) in changes(b.sent, b.told)
    isempty(new) && continue
    lo, hi = follow(mine, first(new)), follow(mine, last(new))
    push!(runs, min(lo, hi):max(lo, hi))
  end
  e.nodes[:theirs] = (key, runs)
  runs
end

"True while the bars beside the agent's changes stay on the page that's showing"
marking(e) = get(e.nodes, :marking, "") == e.buf.path

"Show the bars beside the agent's changes until this is called again. The page goes to the first change if none is on screen."
toggle_marks!(e) = begin
  marking(e) && return delete!(e.nodes, :marking)
  e.nodes[:marking] = e.buf.path
  runs = theirs(e)
  (isempty(runs) || isempty(e.layout)) && return
  touches(it) = any(r -> first(r) <= it.last && last(r) >= it.first, runs)
  _, h = window_size(e)
  seen = filter(it -> it.top + it.tall > e.scroll.offset && it.top < e.scroll.offset + h - TOPBAR_H - PAGE_TOP, e.layout)
  any(touches, seen) && return
  i = findfirst(touches, e.layout)
  i === nothing || (e.scroll.offset = max(0px, e.layout[i].top - 80px))
  nothing
end

"The name of the agent that works on the page, as the owner of something: \"Claude's\""
whose(e) = get(e.nodes, :agent, "the agent")::String * "'s"

# The logos of the agents that Ladder knows. Each is one shape in a square 24
# wide, from Simple Icons (Claude, OpenAI, Gemini) and Lobe Icons (Grok).
